local P = LoreForeverPacks.Begin("LoreForever_Lang_ukUA")
P.entries["quest:883"] = {n="Лакота'мані",s="«Лакота'мані» — мисливський обряд, що починається зі здобуття копита Лакота'мані, величезного мандрівного кодо з Пусток. Принесений Джорнові Скайсіру в Табір Тауражо, цей трофей вшановує дух могутнього звіра й визнає мисливця рівним його громовій силі.",h="«Лакота'мані» — мисливський обряд, що починається зі здобуття копита Лакота'мані, величезного мандрівного...",kw={"лакота'мані","землетряс","кодо","джорн скайсір","табір тауражо","мисливець"},ang={["class:Hunter"]="Вистежити легендарного самотнього кодо на неосяжній савані — найвище випробування мисливського хисту, витривалості й польового бою в серці Калімдору.",["faction:Horde"]="Табір Тауражо — важливий мисливський осередок Орди, і здобич із рівнин допомагає вам здобути славу серед племен.",["race:Tauren"]="Для тауренських мисливців перемога над Лакота'мані виконує давні мисливські традиції й приносить вам духовну шану й горде звання Землетряса від старійшин."},sec={{t="Землетряс",b="Мовою таур-ахе Лакота'мані означає «Землетряс». Серед стад, що мандрують випаленими сонцем рівнинами Пусток, він вирізняється — кодо неймовірного розміру й витривалості, чиї кроки відлунюють, наче громовиця, що збирається. Для тауренських мисливців вистежити й здолати таку істоту — не безглузде вбивство, а священне єднання з первісною силою дикої природи Калімдору."},{t="Полювання, вшановане в Таборі Тауражо",b="Копито полеглого звіра, принесене Джорнові Скайсіру в Табір Тауражо, дає полюванню духовне завершення. Джорн одразу помічає зміну: кожен мисливець, що повертається з цієї зустрічі, має нову силу й ходу. Вручаючи трофей, мисливець отримує благословення Джорна — визнання того, що незламна мужність і первісний дух Лакота'мані тепер крокують поруч із ним."}},faq={{q="Що означає ім'я Лакота'мані?",a="За словами Джорна Скайсіра, мовою тауренів Лакота'мані означає «Землетряс». Ім'я відбиває величезний зріст звіра й кроки, що гуркочуть рівнинами, наче грім, що збирається.",al={"значення лакота'мані","переклад лакота'мані","що означає лакотамані"}},{q="Хто такий Джорн Скайсір?",a="Джорн Скайсір — духовний провідник і старійшина-таурен із Табору Тауражо на півдні Пусток. Він тлумачить знаки, наставляє молодих мисливців і шанує великих звірів, уполюваних на рівнинах.",al={"хто такий джорн","роль джорна скайсіра","де джорн скайсір"}},{q="Чому таурени збирають копита великих звірів?",a="Для тауренів копито, зняте зі звіра на кшталт Лакота'мані, — відчутний знак неймовірної сили істоти. Коли його показують старійшині, дух і стійкість полеглого звіра урочисто визнають і прив'язують до духу мисливця.",al={"чому брати копито","значення копита лакота'мані","трофей копита кодо"}},{q="Де блукає звір Лакота'мані?",a="Лакота'мані блукає відкритою саваною в центрі й на півдні Пусток серед менших стад кодо, доки його не вистежить уважний мисливець.",al={"де лакотамані","місце лакота'мані","як знайти лакотамані"}},{q="Чому Джорн називає мисливця «Землетрясом»?",a="Джорн Скайсір вірить, що перемога над Лакота'мані назавжди зливає дух і відвагу звіра з духом мисливця. Здолавши Землетряса, мисливець успадковує його ім'я й крокує з тією самою громовою рішучістю.",al={"чому мене називають землетрясом","переказ про звання землетряса"}},{q="Чи має це полювання духовне значення поза Табором Тауражо?",a="Так. Воно відбиває головне вірування тауренів у Земну Матір і природну рівновагу. Мисливець доводить свою силу не пануванням над природою, а тим, що випробовує себе на її найвеличніших утіленнях і несе їхню духовну силу в майбутні бої.",al={"духовне значення лакотамані","чи це обряд тауренів"}}},fp="11,271,15.390.0,30.384.0,36.200.0,20.196.0,49.259.0,38.152.0,44.223.0,63.261.0"}
P.entries["quest:884"] = {n="Оватанка",s="Оватанка — легендарний громоящер, якого таурени звуть Синьою Блискавкою; він бродить південними рівнинами Пусток. Убивши цього прудкого наелектризованого звіра, мисливець здобуває тріскучий хвостовий шпичак, що несе ув'язнену в ньому блискавку старійшинам табору. Доставка цього трофея Джорнові Скайсіру в Табір Тауражо вшановує традицію вчитися в первісних звірів Калімдору.",h="Оватанка — легендарний громоящер, якого таурени звуть Синьою Блискавкою; він бродить південними рівнинами...",kw={"оватанка","синя блискавка","громоящер","хвостовий шпичак оватанки","джорн скайсір","мисливець"},ang={["class:Hunter"]="Перемога над Оватанкою — найкраща перевірка скрадання й швидкості: вона доводить, що мисливець може випередити й здолати найпрудкіших велетнів природи.",["class:Shaman"]="Залишкова блискавка, ув'язнена в хвостовому шпичаку Оватанки, показує, як стихійні сили неба можуть назавжди змінити живих істот Калімдору.",["faction:Horde"]="Знищення такого непередбачуваного, зарядженого блискавкою верховного хижака захищає вразливі стежки постачання поблизу Табору Тауражо.",["race:Tauren"]="Полювання на Синю Блискавку вшановує давні тауренські традиції шани до диких духів і здобуття життєвої сили найвитриваліших звірів Пусток."},sec={{t="Звір на ім'я Синя Блискавка",b="Посушливими просторами південних Пусток бродить Оватанка — рідкісний громоящер, про якого тауренські мисливці говорять із побожною шаною. Більшість його родичів — величезні й неповороткі, а Оватанка має раптову, сліпучу швидкість. Таурени звуть його Синьою Блискавкою, бо він — істота, яку буря змінила до самої суті."},{t="Живлений гнівом неба",b="За переказами, які зберігає Джорн Скайсір, колись в Оватанку влучила блискавка. Громоящер не загинув, а ввібрав небесний удар, і той живить у ньому невичерпне джерело шаленої люті. Навіть після смерті його хвостовий шпичак, коли його беруть у руки, люто тріщить іскрами — відчутний слід сили бурі."},{t="Трофей Тауражо",b="Принести Хвостовий Шпичак Оватанки до Табору Тауражо — обряд, що доводить вправність і силу духу. Джорн Скайсір одразу впізнає слід цієї сутички в очах кожного мисливця, якому вдалося переважити швидкість звіра. Вручаючи трофей, мисливець символічно переймає незгасну прудкість Синьої Блискавки."}},faq={{q="Що таке Оватанка?",a="Оватанка — легендарний громоящер із Пусток. Місцеві таурени звуть його «Синя Блискавка»: він славиться надзвичайною швидкістю й енергією блискавиць, що тріщить довкола нього.",al={"хто така оватанка","який звір оватанка","переказ про оватанку"}},{q="Чому з Оватанки сиплються іскри блискавиць?",a="За легендою тауренів, колись давно в Оватанку вдарила блискавка. Вона не вбила його, а сповнила нескінченною енергією й люттю, що живиться просто від неба.",al={"чому оватанка електрична","переказ про синього грому","чому летять іскри"}},{q="Хто такий Джорн Скайсір?",a="Джорн Скайсір — старійшина й духовний провідник тауренів у Таборі Тауражо на півдні Пусток. Він знає приховану силу великих звірів краю й приймає трофеї на кшталт хвостового шпичака Оватанки.",al={"де здати оватанку","хто джорн","видавець табору тауражо"}},{q="Де блукає Оватанка?",a="Оватанка блукає посушливими рівнинами півдня Пусток, зазвичай серед чагарників і ґрунтових стежок на південь від Табору Тауражо.",al={"місце оватанки","де оватанка","де знайти синього грому"}},{q="Що буде, коли принести Хвостовий Шпичак Оватанки?",a="Джорн Скайсір хвалить вас за перемогу над прудким громоящером і зауважує, що той, хто встигав за такою істотою, назавжди зберігає в собі іскру її енергії й сили.",al={"здати оватанку","що каже джорн","нагорода оватанки"}},{q="Чи Оватанка небезпечніший за звичайних громоящерів?",a="Так. Окрім звичайної для громоящерів витривалості, Оватанка має оманливу прудкість і вроджену електричну силу від тієї легендарної блискавки.",al={"чи оватанка важка","небезпека синього грому","бій з оватанкою"}}},fp="8,366,25.320.0,21.344.0,17.316.0,17.177.0,39.189.0,20.208.0,27.137.0,51.171.0,57.167.0"}
P.entries["quest:8846"] = {n="П'ять печаток за військові припаси",s="Фельдмаршал Сноуфолл в Айронфорджі збирає провіант і спорядження для воєнних зусиль Великого Альянсу. Поборники, що поповнюють запаси, можуть обміняти свої похвальні печатки просто на польові пайки, бинти й необхідні бойові припаси. Так ті, хто невтомно працює в тилу, залишаються спорядженими до прийдешніх битв.",h="Фельдмаршал Сноуфолл в Айронфорджі збирає провіант і спорядження для воєнних зусиль Великого Альянсу.",kw={"фельдмаршал сноуфолл","похвальні печатки","припаси","пайки","бинти","айронфордж"},ang={["faction:Alliance"]="Це постачання — справжній рятівний канал для поборників Альянсу, що готуються до великих походів по всьому Азероту: війська матимуть бинти й пайки.",["race:Dwarf"]="Гамірне місто-кузня стало розподільчим вузлом Альянсу, і дворфійські захисники пишаються тим, що їхні зали озброюють усі союзні народи."},sec={{t="Постачання фронту",b="Щоб зібрати величезні армії, мало самої відваги: потрібен безперервний потік постачання. Фельдмаршал Сноуфолл — один із головних інтендантів Альянсу в Айронфорджі: він спрямовує матеріали на діючі фронти. Коли гінці й герої приносять похвальні печатки, здобуті службою громаді, Сноуфолл навзамін пропонує пайки для виживання й бойове спорядження."},{t="Практичний обмін",b="Похвальні печатки здебільшого здають королівським герольдам заради публічних почестей і доброго імені, але Сноуфолл пропонує скромнішу альтернативу. Обмін п'яти печаток на пакунок польового спорядження не принесе ні пишноти, ні слави, ні офіційного визнання. Натомість він дає відчутні речі, що рятують життя: вояки й добровольці, вирушаючи у ворожі землі, залишаться живими."}},faq={{q="Хто такий Фельдмаршал Сноуфолл?",a="Фельдмаршал Сноуфолл — високий військовий чин Альянсу в столиці дворфів, Айронфорджі. Йому доручено збирати сировину й роздавати припаси солдатам і шукачам пригод, що допомагають воєнним зусиллям.",al={"снігопад айронфордж","польовий маршал сноуфолл","хто такий сноуфолл"}},{q="Що таке Похвальні печатки Альянсу?",a="Похвальні печатки Альянсу — офіційні знаки, якими нагороджують городян і шукачів пригод, що жертвують важливі товари, бинти, трави й руду на підтримку загальної мобілізації Альянсу.",al={"похвальні печатки","печатки альянсу","що таке печатки"}},{q="Чому міняти печатки на припаси, а не на престиж?",a="Обмін печаток на ящики з припасами оминає громадське визнання заради негайних, практичних ресурсів. Бійцям передової, яким просто зараз потрібні витратні речі, пайки й польові бинти, практичне спорядження часто важить більше за урочисте становище.",al={"чому міняти печатки на припаси","чи варто здавати печатки","торгівля сноуфолла припасами"}},{q="Де відбувається цей обмін?",a="Обмін відбувається в Айронфорджі, де Фельдмаршал Сноуфолл стоїть біля збірних пунктів і складів припасів, координуючи поставки по всьому Каз Модану й далі.",al={"де сноуфолл","місце завдання","місце сноуфолла в айронфорджі"}},{q="Чи можна повторювати цей обмін?",a="Так. Фельдмаршал Сноуфолл готовий видавати нові пакунки з припасами знову й знову, якщо щоразу ви приноситимете потрібні п'ять похвальних печаток.",al={"чи повторюване","чи можна ще раз","здати ще печатки"}},{q="Чи дає ця здача репутацію?",a="Ні. Фельдмаршал Сноуфолл прямо попереджає: обмін печаток на особисті припаси не дає ні громадського визнання, ні престижу у фракціях Альянсу, бо їхню вартість повертають речами.",al={"чи це дає репутацію","репутація айронфорджа за печатки","визнання за печатки"}}},fp="29,372,19.422.0,17.374.0,30.225.0,39.195.0,52.243.0,36.175.0,27.165.0,35.207.0"}
P.entries["quest:885"] = {n="Вашт Павн",s="Це завдання починається зі здобуття пера Вашт Павна — рідкісного й шанованого громояструба, що ширяє в небі над південними Пустками. Його пір'я пече неприродним жалом, і мисливці несуть цю реліквію Джорнові Скайсіру в Табір Тауражо. Для тауренів убити цього легендарного птаха — не просто полювання за трофеєм, а глибоке духовне випробування болем і каяттям.",h="Це завдання починається зі здобуття пера Вашт Павна — рідкісного й шанованого громояструба, що ширяє в небі...",kw={"вашт павн","жало духу","громояструб","джорн скайсір","каяття","мисливець"},ang={["class:Hunter"]="Сутичка з Вашт Павном ставить під сумнів мотиви мисливця й показує, що відібране життя звіра важить набагато більше, ніж простий трофей.",["class:Shaman"]="Примарне жало, що лишається на пері громояструба, відкриває сирий духовний відгук дикої природи — відлуння, зрозуміле кожному, хто вивчає злагоду стихій.",["faction:Horde"]="Табір Тауражо — важливе духовне й мисливське роздоріжжя Орди, що веде молодих воїнів крізь випробування не лише бойового хисту, а й сумління.",["race:Tauren"]="Для шу'гало відібрати життя Жала Духу — священний урок шани до рівноваги природи, що вчить мисливців перековувати каяття на внутрішню мудрість."},sec={{t="Жало Духу",b="Громояструби — невловимі створіння Пусток, яких мандрівні кочові племена шанують із забобонним трепетом. Серед них Вашт Павн — мовою таур-ахе «Жало Духу» — посідає особливе, доленосне місце. На відміну від звичайної здобичі, його смерть не сприймають легковажно: шамани шепочуть, що вбивство такої істоти несе знамення, які небезпечно хитаються між тріумфом і нещастям."},{t="Урок каяття",b="Ті, хто вб'є Вашт Павна, швидко виявляють, що його перо від дотику пече пронизливим, тривалим болем. Коли перо приносять Джорнові Скайсіру в Табір Тауражо, провидець пояснює, що цей біль — не отрута, а духовне жало каяття. Відібране величне життя — важкий тягар, і випробування з'ясовує, чи мисливець піддасться мукам сумління, чи перекує свою скорботу на тривку мудрість."}},faq={{q="Що означає Вашт Павн?",a="Мовою таурахе, якою говорять таурени, Вашт Павн означає «Кусач Духів». Так звуть величного рідкісного громояструба, що ширяє над південними рівнинами Пусток.",al={"значення вашт павн","що таке вашт павн","значення духокуса"}},{q="Чому перо Вашт Павна завдає болю?",a="За словами Джорна Скайсіра, пекучий біль, коли береш перо до рук, — це гострий укол жалю. Він уособлює емоційну й духовну ціну того, що обірвав життя величної істоти.",al={"чому перо завдає болю","жало пера вашт павна"}},{q="Кому віднести Перо Вашті Поне?",a="Перо треба віднести Джорнові Скайсіру, старійшині-таурену з Табору Тауражо на півдні Пусток.",al={"кому віднести перо","здати перо вашті поне"}},{q="Яке знамення несе вбивство громояструба?",a="За традицією тауренів, смерть громояструба може віщувати або велике щастя, або страшну біду. Але Джорн пояснює, що Вашт Павн особливий: його загибель сама собою не несе жодної з цих доль, і мисливцеві лишається виплекати мудрість із власного каяття.",al={"знамення громояструба","чи погано вбивати громояструбів"}},{q="Де знайти Вашт Павна?",a="Вашт Павн ширяє в небі над півднем Пусток, і його часто бачать, як він кружляє над саваною біля Табору Тауражо.",al={"місце вашт павна","де з'являється духокус"}},{q="Що Джорн Скайсір думає про вас, коли його вбито?",a="Джорн вас не засуджує. Навпаки, він зауважує: якщо ви витерпіли біль від пера, значить, опанували свій жаль, перетворивши духовну скорботу на силу й глибоке розуміння.",al={"реакція джорна скайсіра","чи джорн розсердиться"}}},fp="12,378,16.412.0,18.429.0,28.193.0,43.203.0,41.118.0,43.260.0,28.119.0,53.183.0"}
P.entries["quest:8851"] = {n="П'ять печаток за воєнні припаси",s="«П'ять печаток за воєнні припаси» — обмін, яким опікується Воєначальник Ґорчук в Оргріммарі. Здаючи похвальні печатки, зароблені під час масштабної воєнної мобілізації Орди, чемпіони отримують особисті припаси, щоб бути добре спорядженими до прийдешньої битви.",h="«П'ять печаток за воєнні припаси» — обмін, яким опікується Воєначальник Ґорчук в Оргріммарі.",kw={"воєначальник ґорчук","похвальні печатки","воєнні припаси","мобілізація","оргріммар","орда"},ang={["class:Warrior"]="Бійці передової, які цінують практичне виживання більше за церемоніальні почесті, вважатимуть ящики Ґорчука вартими всіх зібраних печаток.",["faction:Horde"]="Кожен ящик і кожен клунок, зібраний в Оргріммарі, гарантує, що Орда зустріне згубні загрози, які маячать на обрії, у всеозброєнні."},sec={{t="Зусилля цілого континенту",b="По всьому Калімдору Орда збирає величезні запаси сировини, бойового спорядження й провіанту для великого походу. Поки звичайні збирачі й ремісники тягнуть до міських осередків ящики з бинтами, металами й травами, військові наглядачі видають похвальні печатки на знак їхньої служби. Ці знаки засвідчують особистий внесок у великий запас, що росте на центральних вулицях Оргріммара."},{t="Спорядження для передової",b="Воєначальник Ґорчук розуміє: збирати припаси для спільної справи вкрай важливо, але кожному воїнові теж потрібне спорядження й харчі, щоб вижити в битві. Завдяки цьому обміну бійці можуть відмовитися від особистого визнання й повернути свої похвальні печатки у воєнну машину, отримавши натомість готові до бою припаси й надлишкове спорядження."}},faq={{q="Навіщо здавати п'ять печаток?",a="Це дає змогу воякам, що допомагають воєнній мобілізації Орди, обміняти зароблені похвальні знаки просто на особисте спорядження для виживання й польові припаси, а не берегти їх заради політичного визнання.",al={"навіщо здавати п'ять печаток","мета здачі печаток","що отримаю за п'ять печаток"}},{q="Хто такий Воєначальник Ґорчук?",a="Воєначальник Ґорчук — військовий координатор Орди в Оргріммарі, що відає припасами й дає дозволи на видачу спорядження воїнам, які готуються до неминучої війни.",al={"особа ґорчука","хто такий ґорчук"}},{q="Як здобути Похвальні печатки Орди?",a="Печатки видають інтенданти й офіцери постачання по всій Орді, коли шукачі пригод жертвують на воєнні потреби фракції сировину, їжу, бинти й ремісничі матеріали.",al={"отримати печатки","звідки печатки","джерело похвальних печаток"}},{q="Чи можна повторювати цю видачу?",a="Так. Воєначальник Ґорчук готовий знову й знову дозволяти обмін, доки ви приноситимете потрібні партії печаток на підтримку війська.",al={"чи повторюване","чи можна ще раз"}},{q="Чому Ґорчук каже, що я не отримаю визнання за цей обмін?",a="Коли ви витрачаєте похвальні печатки просто на особисті припаси, їх беруть зі складів інтенданта, а не заносять ваші подвиги до літопису, тож ви міняєте офіційні почесті на негайне, практичне польове спорядження.",al={"що значить без визнання","чому без репутації"}},{q="Де відбувається цей обмін?",a="Видача відбувається просто в Оргріммарі, де зосереджені запаси й координатори постачання, що готують Орду до війни.",al={"де це завдання","місце здачі"}}},fp="29,274,23.405.0,27.380.0,47.206.0,23.181.0,45.188.0,33.153.0,67.225.0,36.141.0"}
P.entries["quest:8852"] = {n="Десять печаток за воєнні припаси",s="«Десять печаток за воєнні припаси» — обмін, яким опікується Воєначальник Ґорчук в Оргріммарі. Чемпіони Орди можуть обміняти зайві похвальні печатки на практичне бойове спорядження й припаси. Такий обмін означає відмову від офіційної слави й визнання, зате безпосередньо озброює солдатів передової до прийдешніх сутичок.",h="«Десять печаток за воєнні припаси» — обмін, яким опікується Воєначальник Ґорчук в Оргріммарі.",kw={"воєначальник ґорчук","похвальні печатки","воєнні припаси","спорядження","оргріммар","долина духів"},ang={["class:Warrior"]="Бійці передової знають, що холодна сталь і вдосталь харчів виграють затяжні війни не гірше за бойову відвагу.",["faction:Horde"]="Кожен ящик припасів, зібраний в Оргріммарі, безпосередньо готує Орду до жорстоких битв, що вже маячать на обрії."},sec={{t="Спорядження для фронту",b="Коли Орда збирає свої легіони на війну, заготівля припасів важить не менше, ніж збирання воїнів. Воєначальник Ґорчук опікується постачанням у Долині Духів, стежачи, щоб ящики зі зброєю, пайками й обладунками безперервно надходили на передову. Ті, хто довів свою відданість, можуть здати похвальні печатки й отримати корисне спорядження з армійських запасів."},{t="Виживання понад славу",b="Похвальні печатки Орди зазвичай здають як доказ служби, і вони приносять солдатові шану й славу серед провідників. Обмінюючи їх безпосередньо на спорядження, боєць оминає це офіційне визнання заради простого виживання. Ґорчук розуміє, що зайва сумка з припасами чи міцна зброя можуть вирішити, жити чи загинути, щойно зіткнуться армії."}},faq={{q="Що таке Похвальні печатки Орди?",a="Похвальні печатки Орди — офіційні знаки, якими нагороджують поборників, що збирають важливу сировину й ресурси для воєнної мобілізації Орди.",al={"похвальна печатка","печатки орди","воєнні печатки"}},{q="Хто такий Воєначальник Ґорчук?",a="Воєначальник Ґорчук — офіцер постачання Орди в Оргріммарі, що відповідає за збір воєнних ресурсів і роздачу бойового провіанту мобілізованим загонам.",al={"ґорчук","місце воєначальника ґорчука","хто такий ґорчук"}},{q="Чому здавати печатки за припаси, а не за репутацію у фракції?",a="Обмін печаток на припаси жертвує політичним становищем і офіційним визнанням заради практичних речей, бинтів і спорядження, що допомагають вижити на передовій просто зараз.",al={"печатки проти припасів","чому припаси","нагороди за печатки"}},{q="Чи можна повторювати цей обмін?",a="Так. Воєначальник Ґорчук і далі видаватиме польові припаси, доки ви матимете потрібні партії похвальних печаток.",al={"чи повторюване","повторити печатки","здати ще раз"}},{q="Де відбувається цей обмін?",a="Обмін відбувається в столиці, Оргріммарі, де зосереджені воєнні приготування й запаси Орди.",al={"де здати печатки","місце здачі печаток","місце ґорчука"}},{q="До якої війни готується Орда?",a="Орда збирає величезні запаси металу, тканини, трав і пайків, щоб озброїти експедиційне військо, здатне протистояти неминучій, нищівній загрозі.",al={"яка війна","чому збирають припаси","воєнні зусилля"}}},fp="28,340,22.370.0,29.379.0,36.149.0,23.170.0,63.181.0,30.133.0,36.122.0,44.158.0"}
P.entries["quest:886"] = {n="Оази Пусток",s="Високо на Узвишші Старійшин у Тандер Блафі Верховний Друїд Гамуул Рунтотем відчуває тривожний приплив сили, що ллється в посушливі ґрунти Пусток. Щоб дізнатися правду, він посилає здібних мандрівників на схід, за ворота Малгора, — на зустріч зі своїм родичем Тонгою Рунтотемом на Перехресті. Так починається розслідування таємничих вод, що б'ють із-під землі на випалених сонцем рівнинах.",h="Високо на Узвишші Старійшин у Тандер Блафі Верховний Друїд Гамуул Рунтотем відчуває тривожний приплив сили...",kw={"оази пусток","гамуул рунотем","тонга рунтотем","коло кенарія","перехрестя","друїд","узвишшя старійшин"},ang={["class:Druid"]="Ви — серед перших учнів Гамуула Рунтотема, і ваш Верховний Друїд довіряє вам прислухатися до шепоту землі й загоювати рани в крихкій рівновазі природи.",["faction:Horde"]="Перехрестя — життєва артерія, що поєднує західні володіння Орди з узбережжям, тож будь-яке магічне збурення поблизу стає справою глибокої стратегічної й духовної ваги.",["race:Tauren"]="Для тауренів, які вперше виходять за межі священних лук Малгора, це завдання стає обрядом посвяти — початком ширшого обов'язку берегти рівновагу Калімдору."},sec={{t="Неспокій серед посухи",b="Поки рівнини Малгора квітнуть під пильним поглядом Земної Матері, безкраї савани Пусток на сході поколіннями лишаються суворими, випаленими й сухими. Та нещодавно друїди-таурени, що медитують на Узвишші Старійшин у Тандер Блафі, відчули дивні потоки енергії, які прокидаються глибоко під спраглими рівнинами. Життя зароджується там, де йому не місце, і Коло Кенарія побоюється, що сила, яка спричинила цей сплеск, може таїти небезпеку для землі та її створінь."},{t="На схід, за Великі Ворота",b="Щоб розслідувати ці дивні події, Верховний Друїд Гамуул Рунтотем вислав на місце Тонгу Рунтотема. Розуміючи, що безкрая глушина таїть надто багато небезпек для одного дослідника, Гамуул просить мандрівників, які покидають Малгор, поспішити слідом за Тонгою. Дорога на схід повз Село Бладгуф і крізь гірські перевали веде просто до Перехрестя — курявного, гамірного серця земель Орди в Пустках, — де Тонга шукає відповідей."}},faq={{q="Чому Гамуула Рунтотема непокоять Пустки?",a="Гамуул і друїди Тандер Блафа відчули, як у землю Пусток просочується неприродний сплеск сили. Раптове буяння життя в такому сухому, суворому кліматі свідчить, що під поверхнею діють незвичні сили.",al={"чому оази пусток","занепокоєння гамуула","чому посилати на перехрестя"}},{q="Де знайти Тонгу Рунтотема?",a="Тонга Рунтотем — на Перехресті в центрі Пусток. Щоб знайти його, ідіть головною східною дорогою з Малгора, перейдіть у Пустки й звертайте на північне відгалуження стежки, доки не дійдете до поселення.",al={"де тонга рунтотем","місце тонги","тонга перехрестя"}},{q="Чи доступне це завдання лише тауренам?",a="Верховний Друїд Гамуул Рунтотем дає це завдання насамперед мандрівникам, що виходять із Малгора. Але шукачі пригод будь-якої раси Орди можуть самі зустріти Тонгу на Перехресті й допомогти дослідити оази.",al={"чи не таурени можуть оази пусток","хто дає оази пусток"}},{q="Що чекає в кінці дороги із Села Бладгуф?",a="Дорога на схід від Села Бладгуф веде повз Велику Браму, що відділяє Малгор від Пусток. За горами зверніть на роздоріжжі на північ — і безпечно перетнете сувору глушину до Перехрестя.",al={"дорога до перехрестя","шлях з мулґору в пустки"}},{q="Що за дивні сили відчуває Гамуул?",a="Друїди відчувають магічні течії, що породжують зелені оази з джерелами посеред пустельного краю, відомого лютими посухами. Тонгу Рунтотема послали з'ясувати, чи це буяння — благословення чи небезпечна скверна.",al={"які сили в пустках","таємниця оаз","неприродна енергія пусток"}},{q="Чому Пустки вважають такими небезпечними для молодих шукачів пригод?",a="Пустки — безкрає прикордоння, що кишить хижаками: тут нишпорять раптори, рівнинні довгоступи й ворожі племена кентаврів. Гамуул радить мандрівникам суворо триматися торгових шляхів, які патрулюють, щоб сувора глушина їх не здолала.",al={"небезпека пусток","чому триматися дороги"}}},fp="17,423,28.514.0,26.469.0,52.244.0,33.233.0,39.210.0,58.219.0,42.214.0,66.240.0"}
P.entries["quest:8866"] = {n="Бронзборід Старійшина",s="Під час Місячного фестивалю мандрівники можуть зустріти Старійшину Бронзбірда в дворфійському гірському місті Айронфорджі. Хто вшанує його під час цього свята предків, отримає мудре слово й знак його прихильності. Ця зустріч відбиває глибоку шану, яку народ Каз Модану плекає до своїх пращурів і давньої спадщини.",h="Під час Місячного фестивалю мандрівники можуть зустріти Старійшину Бронзбірда в дворфійському гірському місті...",kw={"старійшина бронзбірд","місячний фестиваль","монета роду","айронфордж","предки","клан бронзбірд"},ang={["faction:Alliance"]="Старійшина мирно перебуває в столиці, Айронфорджі, і вітає членів Альянсу, що прагнуть вшанувати давні традиції під горою.",["faction:Horde"]="Дістатися до Старійшини Бронзбірда — небезпечне вторгнення в укріплене серце Айронфорджа: щоб привітати його, знадобиться потайливість або неабияка зухвалість.",["race:Dwarf"]="Для дворфів вшанувати Старійшину Бронзбірда — це пряме єднання з благородними предками, що збудували своє гірське королівство з каменю й заліза."},sec={{t="Шана гірському клану",b="Під час Місячного фестивалю духи й шановані старійшини з'являються по всьому Азероту, щоб поділитися мудрістю з тими, хто вшановує минуле. В Айронфорджі Старійшина Бронзбірд — утілення непохитної стійкості клану Бронзбірд. Коли шукачі пригод приходять віддати йому шану, він стримано тішиться, що народи цієї землі досі визнають і шанують родовід давніх рас."},{t="Знаки шани предків",b="Ця зустріч не вимагає ні великого випробування, ні небезпечної мандрівки — лише зупинитися, визнати присутність старійшини й привітати його. Навзаєм Старійшина Бронзбірд бажає добра й дарує Монету Роду. Ці священні святкові знаки — відчутне нагадування про живий зв'язок між сучасними героями й поколіннями, що викували Каз Модан із каменю й вогню."}},faq={{q="Хто такий Старійшина Бронзбірд?",a="Старійшина Бронзбірд — предок-дворф, якого шанують під час Місячного фестивалю: він перебуває в підземній твердині Айронфорджа, щоб вітати гостей і славити їхню спадщину.",al={"старійшина бронзбірд","хто старійшина","старійшина айронфорджа"}},{q="Що означає вшанування Старійшини Бронзбірда?",a="Привітати його — означає вшанувати предків під час Місячного фестивалю. Він хвалить мандрівників за те, що вони пам'ятають коріння й давні жертви ранніх рас Азероту.",al={"навіщо вшановувати бронзбірда","мета старійшини бронзбірда"}},{q="Де в Айронфорджі знайти Старійшину Бронзбірда?",a="Він стоїть в Айронфорджі, і до нього можуть дійти ті, хто мандрує гірським містом у пошуках старійшин свята, щоб віддати їм шану.",al={"місце старійшини бронзбірда","де бронзбірд старійшина","місце старійшини айронфорджа"}},{q="Чи можуть гравці Орди поговорити зі Старійшиною Бронзбірдом?",a="Старійшина Бронзбірд привітає кожного, хто захоче з ним привітатися, але шукачам пригод Орди доведеться пробратися в укріплені глибини Айронфорджа й ухилятися від вартових-дворфів, щоб до нього дійти.",al={"чи орда може це завдання","старійшина бронзбірд орда"}},{q="Яку нагороду дає старійшина?",a="Він дає благословення предків разом зі святковою монетою — знаком прихильності й доказом шани до давніх поколінь.",al={"нагорода старійшини бронзбірда","який знак він дає"}},{q="Чи доведеться битися в цьому завданні?",a="Щоб поговорити з ним, битися не треба: досить шанобливо підійти до поважного старійшини, хоча ворожа територія дорогою може бути небезпечною.",al={"чи треба битися","бій зі старійшиною бронзбірдом"}}},fp="21,329,27.426.0,26.399.0,25.184.0,45.179.0,46.138.0,47.173.0,34.137.0,35.164.0"}
P.entries["quest:887"] = {n="Флібустьєри Південних морів",s="«Флібустьєри Південних морів» — вступне доручення-винагорода від Ґазлоу в Раджеті, покликане приборкати місцеве піратство. Розлючений піратськими нападами на гоблінські торгові кораблі, головний інженер наймає шукачів пригод, щоб атакувати табір піратів Південних морів на Узбережжі Крамарів трохи на південь від містечка.",h="«Флібустьєри Південних морів» — вступне доручення-винагорода від Ґазлоу в Раджеті, покликане приборкати...",kw={"флібустьєри південних морів","ґазлоу","раджет","пірати","купецьке узбережжя","картель стімвідл"},ang={["class:Rogue"]="Табір Флібустьєрів Південних морів сповнений нагод для кишенькових злодіїв — якщо ви зумієте прослизнути повз пильних вартових і важку берегову артилерію.",["faction:Horde"]="Раджет — важливий коридор поповнення запасів для Орди в Калімдорі; очищення морських шляхів від нападників захищає лінії постачання, що тягнуться вглиб Пусток."},sec={{t="Скалка в боці Ґазлоу",b="Раджет — найголовніший нейтральний торговий порт центрального Калімдору, що тримається на постійному русі купецьких кораблів між східними континентами й Калімдором. Проте Флібустьєри Південних морів облаштували укріплений табір на пляжі просто на південь, на Узбережжі Крамарів. З цього плацдарму морські розбійники полюють на гоблінські вантажні кораблі, що прибувають і відпливають, висмоктують прибутки й розхитують місцеві морські шляхи."},{t="Байдужість Андермайну",b="Гнів Ґазлоу спрямований не лише на самих піратів, а й на, як він вважає, бездарність морського командування картелю Стімвідл. Попри величезні суми, які Торгові Принци вклали в оборонні флоти, Віцеадмірал Ґреззлік так і не навів ладу на морі. Роздратований повільністю Андермайну, Ґазлоу оминає флотські канали й наймає вільних найманців, щоб прорідити піратських головорізів і гармашів."}},faq={{q="Хто такі Флібустьєри Південних морів?",a="Флібустьєри Південних морів — горезвісне угруповання піратів-людей, дворфів і гномів, що розбійничають у південних океанах і на Великому Морі. У Пустках вони тримають озброєний плацдарм на березі трохи на південь від Раджета, грабуючи торгові кораблі й товари, що прямують до Калімдору.",al={"пірати південних морів","хто такі флібустьєри південних морів","переказ про флібустьєрів"}},{q="Чому Ґазлоу так переймається цими піратами?",a="Ґазлоу керує портом Раджет від імені картелю Стімвідл. Кожен торговий корабель, перехоплений чи пограбований флібустьєрами, прямо зменшує прибутки картелю й підриває славу Раджета як безпечної торгової гавані.",al={"чому ґазлоу хоче піратів мертвими","мотив ґазлоу","проблема піратів раджета"}},{q="Де піратський табір?",a="Табір Південних морів — просто на південь від Раджета вздовж берега, на Узбережжі Крамарів. Там укріплені намети, витягнуті на берег шлюпки й гарматні позиції, біля яких стоять каноніри Південних морів.",al={"де пірати","місце канонірів","місце піратського табору"}},{q="Хто такий Віцеадмірал Ґреззлік?",a="Віцеадмірал Ґреззлік — офіцер, що відповідає за торгові флоти картелю Стімвідл і захист їхніх морських шляхів. Ґазлоу вважає його здебільшого нікчемним, бо пірати зухвало розбійничають просто біля берегів Пусток.",al={"хто такий ґреззлік","віцеадмірал ґреззлік","адмірал стімвідл"}},{q="Що буде, коли табір проріджено?",a="Проріджування оборонців табору розв'язує лише частину проблеми. Коли розбійників і канонірив розбито, Ґазлоу береться вистежувати цінний вантаж, який вони захопили, і це веде просто до розслідування про його зниклі поставки.",al={"що далі","продовження флібустьєрів південних морів","зниклий вантаж"}},{q="Чи пов'язані Флібустьєри Південних морів з Альянсом чи Ордою?",a="Ні. Флібустьєри Південних морів діють цілком поза обома фракціями й без розбору грабують і кораблі Альянсу, і судна постачання Орди, і нейтральні гоблінські вантажні кораблі.",al={"чи флібустьєри з орди","чи пірати з альянсу","фракція південних морів"}}},fp="20,287,25.442.0,22.467.0,33.283.0,50.240.0,33.218.0,29.259.0,36.239.1,67.171.0"}
P.entries["quest:888"] = {n="Викрадена здобич",s="«Викрадена здобич» завершує зусилля Ґазлоу повернути цінний вантаж, захоплений Флібустьєрами Південних морів біля узбережжя Раджета. Замість того щоб повертати кожен утрачений ящик, гоблінський очільник зосереджується на двох головних речах: партії чобіт від шевця й тендітній телескопічній лінзі, потрібній, щоб завершити його обсерваторію.",h="«Викрадена здобич» завершує зусилля Ґазлоу повернути цінний вантаж, захоплений Флібустьєрами Південних морів...",kw={"викрадена здобич","ґазлоу","телескопічна лінза","партія чобіт","флібустьєри південних морів","раджет"},ang={["profession:Engineering"]="Обсерваторія Ґазлоу показує гоблінську точну оптику: щоб збудувати практичну прибережну споруду, мають зійтися і важке будівництво, і тонка робота зі склом.",["profession:Tailoring"]="Привезення чобіт аж від Дріззліка з Буті Бей показує, наскільки широко розкинулася мережа торгівлі готовою шкірою й шевськими виробами між портами Стімвідлу."},sec={{t="Піратське захоплення",b="Флібустьєри Південних морів давно дошкуляють купецьким шляхам Великого моря, але укріплений табір просто на південь від Раджета звів їх у пряму сутичку з Ґазлоу. Коли купецькі кораблі, що прямували до порту, перехопили й пограбували, картель Стімвідл утратив чималі припаси. Другорядні товари можна було списати на звичайні морські ризики, але цінний особливий крам вартував того, щоб найняти дужих найманців і вдертися до піратської твердині."},{t="Загублені деталі",b="Пріоритети Ґазлоу були цілком практичні. Одна річ — важлива партія чобіт від Дріззліка з порту Буті Бей, якої дуже потребували місцеві робітники. Друга — куди особливіша: шліфована телескопічна лінза для помітної вежі-обсерваторії над Раджетом. Її парна лінза безпечно прибула суходолом із караваном через Дуротар, а морську половину перехопили просто на воді. Без неї обсерваторія лишалася порожнім каркасом."}},faq={{q="Чому Ґазлоу так переймається саме цими двома речами?",a="Ґазлоу визнає, що повернути весь захоплений вантаж неможливо, але партію чобіт від Дріззліка з Буті Бею й лінзу для телескопа нічим замінити. Чоботи потрібні місцевим робітникам, а точна лінза — щоб добудувати обсерваторію над Раджетом.",al={"чому чоботи й лінза","речі ґазлоу","що вкрали"}},{q="Звідки взялися дві лінзи для обсерваторії?",a="Щоб обсерваторія працювала як слід, потрібні дві лінзи. Більша щасливо прибула з караваном суходолом через Дуротар. Меншу відправили морем, але флібустьєри Південних морів перехопили її, напавши на корабель біля узбережжя Пусток.",al={"походження лінзи","лінзи обсерваторії","як ґазлоу дістав лінзи"}},{q="Хто такий Дріззлік?",a="Дріззлік — гоблін-чоботар, що працює в Буті Бей на півдні Східних Королівств. Він пошив і відправив партію взуття для робітників Ґазлоу в Раджеті, перш ніж пірати перехопили вантажний корабель.",al={"дріззлік буті бей","хто надіслав чоботи","дріззлік"}},{q="Де сховані вкрадені речі?",a="І ящики з чобітьми, і лінзу для телескопа сховали в піратському таборі Південних морів на Узбережжі Крамарів, трохи на південь від Раджета.",al={"де чоботи","місце піратського табору","де лінза"}},{q="Що буде після цього завдання?",a="«Викрадена здобич» — останній розділ цього ланцюжка розслідувань про піратів Південних морів. Коли речі повернуто, Ґазлоу дякує, хвалить вашу надійність і запрошує й далі працювати на його торгову справу в Раджеті.",al={"продовження викраденої здобичі","наступне завдання","що після викраденої здобичі"}},{q="Навіщо Раджету обсерваторія?",a="Гоблінська інженерія значною мірою спирається на спостереження, навігацію й розвідку навколишніх земель і морських шляхів. Добудована обсерваторія дасть проводу Раджета змогу стежити за торговими флотами, суперницькими кораблями й загрозами, що наближаються, по всьому Узбережжю Крамарів.",al={"телескоп раджета","обсерваторія ґазлоу","навіщо ґазлоу телескоп"}}},fp="12,322,16.494.0,18.474.0,61.282.0,47.273.0,16.220.0,34.144.0,30.249.1,37.278.0"}
P.entries["quest:889"] = {n="Дух вітру",s="«Дух вітру» — повторюваний обряд, який пропонує полонений шипогрив Понівечозуб у Таборі Тауражо. Спрямовуючи залишкову силу кривавих скалок Аґамаґґана, Понівечозуб наповнює мандрівників прудкістю, щоб ті швидше долали неосяжні савани Пусток.",h="«Дух вітру» — повторюваний обряд, який пропонує полонений шипогрив Понівечозуб у Таборі Тауражо.",kw={"дух вітру","понівечозуб","аґамаґґан","криваві скалки","табір тауражо","прудкість"},ang={["class:Druid"]="Друїди, що вивчають Пустки, часто вважають залишкову силу Дикого Бога Аґамаґґана в цих обрядах захопливим, хоч і сирим, проявом первісної природи.",["class:Shaman"]="Єднання з духом вітру через викристалізувану божественну суть перегукується з шаманськими традиціями шанування стихійних сил і сил предків.",["faction:Horde"]="Вартові Табору Тауражо пильно стежать за Понівечозубом, але розвідники Орди раз у раз користуються його знаннями магії кривавих скалок, щоб швидше долати південні рівнини."},sec={{t="Дар кривавих скалок",b="На посушливих просторах Пусток швидко перетнути відкриту місцину часом означає вижити, а не загинути від хижих звірів чи мандрівних загонів кентаврів. Полонений шипогрив Понівечозуб, замкнений у Таборі Тауражо, знає приховану силу, що дрімає в червоних кришталевих кривавих скалках, розкиданих по краю. Отримавши десять таких реліквій, він черпає з їхнього первісного відгуку й дарує Дух вітру — сплеск прудконогої сили, щоб мандрівник міг випередити завиваючі вітри рівнин."},{t="Прадавній подих Аґамаґґана",b="Шипогриви шанують Аґамаґґана — Великого Вепра, що пролив свою кров на центральний Калімдор під час прадавньої Війни Прадавніх. Навіть у неволі Понівечозуб добре знає обряди дикого бога. Сила пролитої божественної крові не просто змінює тіло — вона пробуджує дику снагу, тож мандрівник може зрівнятися швидкістю з галопом стад жевр. Хоч шипогриви — запеклі вороги Орди, Понівечозуб охоче ділиться дарами Аґамаґґана з кожним, хто живить його обряди свіжими скалками."}},faq={{q="Що таке Дух вітру?",a="Це тимчасове благословення, яке дає Понівечозуб у Таборі Тауражо. За десять кривавих уламків він дарує мандрівникам більшу швидкість бігу, щоб легше перетинати Пустки.",al={"що таке дух вітру","баф духу вітру","баф швидкості понівечозуба"}},{q="Хто дає Дух вітру?",a="Обряд править Понівечозуб — шипогрив, якого Орда тримає в полоні в Таборі Тауражо, — коли ви заслужите його співпрацю.",al={"хто дає дух вітру","понівечозуб","хто приймає криваві уламки"}},{q="Навіщо Понівечозубові криваві уламки?",a="Криваві уламки — кришталеві скалки, що утворилися з пролитої крові Аґамаґґана. Понівечозуб черпає з них приховану первісну силу прадавнього напівбога, щоб творити свої благословення.",al={"навіщо криваві уламки","призначення кривавих уламків","що робить понівечозуб з уламками"}},{q="Чи можна отримати це благословення не раз?",a="Так. Якщо щоразу приносити Понівечозубові десять кривавих уламків, він знову й знову даруватиме благословення, коли б ви не повернулися.",al={"чи повторюваний дух вітру","чи можна ще раз","повторюваний баф"}},{q="Чому шипогрив допомагає членам Орди?",a="Понівечозуб у полоні в Тауражо: він виміняв знання предків про магію Аґамаґґана на власне виживання й має справу з мандрівниками, що збирають цінні для нього священні уламки.",al={"чому понівечозуб допомагає","дружній вепролюд","чому допомагати орді"}},{q="Скільки триває благословення?",a="Понівечозуб зауважує, що чари тривають недовго, але, перш ніж згаснути, дають досить прудкості, щоб значно полегшити мандри Пустками.",al={"скільки триває баф","тривалість духу вітру","чи баф швидкості триває"}}},fp="18,258,24.545.0,26.545.0,31.173.0,34.118.0,42.194.0,43.140.0,47.180.0,32.157.0"}
P.entries["quest:89"] = {n="Міст Еверстілл",s="Міст Еверстілл — відбудова, яку очолює Бригадир Ослоу в Лейкширі, щоб полагодити пошкоджений кам'яний міст містечка. Робота зупинилася: залізо для будівництва під час останнього вторгнення орків пустили на зброю, а валку із заміною зі Стормвінда перехопили гноли Редріджу.",h="Міст Еверстілл — відбудова, яку очолює Бригадир Ослоу в Лейкширі, щоб полагодити пошкоджений кам'яний міст...",kw={"міст еверстілл","бригадир ослоу","озеро незрушне","залізо","гноли","лейкшир"},ang={["faction:Alliance"]="Перерізані шляхи постачання Лейкширу — ще один яскравий вияв байдужості Стормвінда до віддалених земель: місцевим бригадирам доводиться наймати мечі, щоб захистити торгівлю на дорогах.",["profession:Blacksmithing"]="Нестача заліза показує, у якому відчаї були захисники Лейкширу: кувати зброю з будівельних шпичаків і заклепок — останній засіб, що врятував життя ціною важливої споруди."},sec={{t="Відрізане містечко",b="Кам'яний міст через Озеро Незрушне — життєва артерія Лейкширу: він з'єднує західні дороги до Лісу Елвінн із протилежним берегом і північними перевалами. Під час нещодавніх набігів орків містечко опинилося на межі загибелі. Коли на кону було виживання, Лейкшир переплавив будівельне залізо на боєприпаси, клинки й латні обладунки, щоб відбити загарбників Блекрок, — і міст лишився недобудованим і вразливим."},{t="Викрадені вантажі",b="Бригадир Ослоу звернувся до Дому Вельмож і Стормвінда по нові будівельні матеріали, щоб завершити ремонт. Валку із залізом відправили, але вона так і не дійшла. Загін гнолів Редріджу влаштував засідку на дорозі й потягнув важливі залізні шпичаки й заклепки до своїх таборів на північних пагорбах. Без відважних мандрівників, готових повернути вкрадене, відбудова мосту стоїть, а гноли й орки дедалі міцніше стискають гори."}},faq={{q="Чому Міст Еверстілл не добудовано?",a="Щоб пережити недавнє вторгнення орків, Лейкширу довелося переплавити будівельне залізо на зброю, кулі й обладунки. Нову партію матеріалів, надіслану зі Стормвінда, перехопили й пограбували місцеві гноли, тож Бригадир Ослоу лишився без того, чим завершити роботу.",al={"чому зламаний міст","хто зламав міст еверстілл","зламаний міст лейкширу"}},{q="Хто такий Бригадир Ослоу?",a="Бригадир Ослоу — майстер-будівничий, що керує відбудовою мосту через Озеро Незрушне. Лишившись без підтримки й матеріалів зі столиці, він покладається на мандрівних шукачів пригод, щоб повернути вкрадені будівельні припаси з пагорбів.",al={"бригадир ослоу","хто такий ослоу"}},{q="Хто вкрав припаси для мосту?",a="Гноли Редріджу влаштували засідку на караван зі Стормвінда й потягли залізні палі й заклепки до своїх таборів у пагорбах за Лейкширом.",al={"хто вкрав залізні заклепки","хто забрав залізо мосту"}},{q="Чому Стормвінд не надіслав варту, щоб захистити караван?",a="Король Варіан Рінн зник, і Дім Вельмож Стормвінда здебільшого відмовляє віддаленим землям у військовій допомозі. Гори Редріджу лишили самотужки відбиватися від гнолів і орків Блекрок лише з мізерною підтримкою міських ополченців.",al={"допомога стормвінда лейкширу","чому немає вартових"}},{q="Чому Лейкшир переплавив своє залізо?",a="Під час останнього вторгнення орків оборонцям Лейкширу катастрофічно бракувало військового спорядження. Щоб вистояти, містечко переплавило запаси будівельного заліза на обладунки, мечі й набої.",al={"чому топити залізо","вторгнення орків реджридж"}},{q="Які припаси потрібні, щоб полагодити міст?",a="Бригадирові Ослоу потрібні саме важкі залізні палі й залізні заклепки, щоб надійно підперти й закріпити прольоти мосту через Озеро Незрушне.",al={"матеріали для мосту","що потрібно ослоу"}}},fp="20,319,14.449.0,16.491.0,39.292.0,21.244.0,30.165.0,56.254.0,39.212.0,46.137.0"}
P.entries["quest:890"] = {n="Зниклий вантаж",s="Ґазлоу чекає на затриманий вантаж, відправлений через Велике море з порту Буті Бей. Підозрюючи або плутанину в портових паперах, або Флібустьєрів Південних морів, він посилає гінців на пристані Раджета звірити записи Начальника Пристані Діззівіга.",h="Ґазлоу чекає на затриманий вантаж, відправлений через Велике море з порту Буті Бей.",kw={"зниклий вантаж","ґазлоу","діззівіг","раджет","буті бей","флібустьєри південних морів"},ang={["faction:Horde"]="Раджет тримається нейтралітету й править за важливий порт для мандрівників Орди між Калімдором і Долиною Стренглторну, тож торгівля на пристанях — спільний інтерес.",["profession:Engineering"]="Постійна потреба Ґазлоу в запчастинах, екзотичному імпорті й спорядженні на замовлення з Буті Бей показує, як важко тримати машини Раджета на ходу далеко від гоблінських промислових центрів."},sec={{t="Рятівна нитка Раджета",b="Раджет процвітає як торговий плацдарм картелю Стімвідл у Калімдорі. Кораблі раз у раз перетинають Велике море з Буті Бей, везучи фабричні товари, екзотичні припаси й важкі вантажі, без яких не обійтися стрімкому будівництву й торговим справам порту. Коли вантаж, що мав прибути, зникає, це б'є по справах Головного Інженера Ґазлоу, який ретельно відстежує кожен ящик, що потрапляє до порту."},{t="Звірка вантажу",b="Хоч Флібустьєри Південних морів кишать на узбережжі на південь від містечка й раз у раз перехоплюють купецькі кораблі, Ґазлоу надто розважливий, щоб діяти, не перевіривши власних книг. Перш ніж звинувачувати піратів чи кидати найманців у бій, він відсилає свої особисті облікові записи просто Начальникові Пристані Діззівігу. Діззівіг наглядає за розвантаженням і зберіганням корабельних вантажів, тож лише він може визначити, чи вантаж загинув у морі, чи його просто засунули не на той склад."}},faq={{q="Що в зниклому вантажі?",a="Ґазлоу загалом каже про важливі товари з Буті Бею, але Начальник Пристані Діззівіг зауважує, що головний інженер, мабуть, хвилюється за замовлення чобіт від Дріззліка.",al={"вантаж ґазлоу","що вкрали","товари зниклого вантажу"}},{q="Хто такий Начальник Пристані Діззівіг?",a="Начальник Пристані Діззівіг відає вантажними відомостями на причалах Раджета — що прибуває й що відходить. Від імені картелю Стімвідл він керує перевантаженням між океанськими кораблями й місцевими складами.",al={"діззівіг","хто такий діззівіг","начальник пристані раджета"}},{q="Чому Ґазлоу підозрює Флібустьєрів Південних морів?",a="Флібустьєри Південних морів отаборилися на Узбережжі Крамарів трохи на південь від Раджета. Вони раз у раз нападають на торгові шляхи між Калімдором і Східними Королівствами, тож коли зникає купецький вантаж, підозрюють насамперед їх.",al={"роль флібустьєрів","пірати-злодії","чому пірати"}},{q="Звідки йшов вантаж?",a="Вантаж ішов із Буті Бею — головного портового міста гоблінів на південному краю Долини Стренглторну у Східних Королівствах.",al={"походження вантажу","звідки він","вантаж буті бею"}},{q="Що буде, коли віддати книгу обліку Діззівігу?",a="Діззівіг звіряє свої вантажні відомості з книгою обліку Ґазлоу, щоб з'ясувати, чи вантаж помилково потрапив на склади Раджета, чи його захопили ще до розвантаження.",al={"наступні кроки діззівіга","продовження книги обліку"}},{q="Чому Ґазлоу сам не перевірить причали?",a="Як Головний Інженер і ватажок Раджета, Ґазлоу керує справами містечка й розбудовою зі свого головного кабінету. Він воліє платити мандрівним шукачам пригод, щоб ті бігали з паперами по поселенню.",al={"чому посилати мене","лінощі ґазлоу"}}},fp="20,265,24.406.0,27.524.0,32.185.0,28.212.0,50.258.0,33.138.0,49.163.0,44.201.0"}
P.entries["quest:891"] = {n="Гармати Північної Варти",s="Капітанові Тало'тасу Брайтсану з Раджета остогидло, що його торгові кораблі розносять на тріски гармаші Альянсу з Твердині Північної Варти. Він наймає звитяжців Орди, щоб ті вирушили вздовж Узбережжя Крамарів, змусили замовкнути офіцерів артилерії твердині й забрали відзнаки полеглих піхотинців.",h="Капітанові Тало'тасу Брайтсану з Раджета остогидло, що його торгові кораблі розносять на тріски гармаші...",kw={"гармати північної варти","твердиня північної варти","тало'тас брайтсан","капітан фермаунт","медаль терамора","раджет"},ang={["faction:Horde"]="Удар по Твердині Північної Варти прямо знешкоджує войовниче укріплення Альянсу, що зазіхає на Пустки, і вбезпечує кордони Калімдору для Орди.",["race:Human"]="Трагічна параноя, що охопила Твердиню Північної Варти, показує, під яким тиском живуть прикордонні гарнізони Терамора — відрізані від дому й схильні до безоглядної ворожості."},sec={{t="Загроза на узбережжі",b="Твердиня Північної Варти нависає над південним узбережжям Пусток — укріплений бастіон людей Терамора. Її заснували, щоб охороняти інтереси Альянсу й стежити за діями Орди в Калімдорі, але солдати всередині піддалися тяжкій параної. Вбачаючи ворога в кожному незнайомому вітрилі, їхні батареї на мурах відкривають вогонь без розбору й загрожують мирним торговим кораблям і каперським суднам Раджета."},{t="Змусити мури замовкнути",b="Капітан Брайтсан не дозволить топити свої кораблі безкарно. Удар по Північній Варті спрямований на її командування — на Капітан Фермаунт і її головних гармашів, Вессана й Смайта. Знищивши їх і зірвавши медалі Терамора з солдатів гарнізону, звитяжці вносять безлад в артилерію твердині й дають морським справам Раджета перепочинок на Узбережжі Крамарів."}},faq={{q="Чому Твердиня Північної Варти стріляє по кораблях із Раджета?",a="Людські вояки у Твердині Північної Варти охоплені шаленою підозріливістю. Боячись нападів Орди й місцевих піратів, їхні запальні каноніри взяли за звичку стріляти майже по кожному кораблю, що пропливає повз Узбережжя Крамарів, хоч під нейтральним, хоч під ворожим прапором.",al={"чому стріляють по кораблях","чому північна варта нападає на раджет","гармати північної варти стріляють"}},{q="Хто такий Капітан Тало'тас Брайтсан?",a="Капітан Тало'тас Брайтсан — капітан-капер із кривавих ельфів, що базується в гоблінському порту Раджет. Він командує торговим флотом і захищає місцеве судноплавство від агресивних суперників, зокрема від надто ревних сил Альянсу у Твердині Північної Варти.",al={"хто дає це завдання","тало'тас брайтсан","видавець раджета"}},{q="Хто такі Капітан Фермаунт, Канонір Вессан і Канонір Смайт?",a="Капітан Фермаунт командує гарнізоном Твердині Північної Варти, а Вессан і Смайт — старші каноніри, що керують гарматними батареями над морем. Їхня смерть розладнує командування фортеці й виводить із ладу важкі гармати.",al={"фермаунт вессан смайт","офіцери північної варти","цілі гармат північної варти"}},{q="Що таке Медалі Терамора?",a="Медалі Терамора — військові відзнаки, які носять піхотинці й вартові у Твердині Північної Варти. Капітан Брайтсан просить їх як певний доказ того, що за загибель каперів помщено, а гарнізон твердині порідів.",al={"медаль терамора","навіщо збирати медалі","звідки медалі"}},{q="Де Твердиня Північної Варти?",a="Твердиня Північної Варти стоїть на південно-східних кручах Пусток, просто на південь від Раджета, на березі, відомому як Узбережжя Крамарів.",al={"де північна варта","місце північної варти","де гармати північної варти"}},{q="Чи Твердиня Північної Варти офіційно належить Терамору?",a="Так. Твердиню Північної Варти заснувало королівство Терамор, щоб закріпитися військово на материку Калімдор. Але її відрізаний гарнізон діє з лютою агресією й глибокою підозрою до всього, що рухається Пустками.",al={"чи північна варта належить тераморові","фракція альянсу північна варта","джайна північна варта"}}},fp="22,293,24.434.0,22.385.0,54.304.0,36.255.0,67.264.0,26.246.0,33.149.0,48.252.0"}
P.entries["quest:892"] = {n="Зниклий вантаж",s="Після перевірки на пристанях Начальник Пристані Діззівіг повертає Ґазлоу його облікову книгу з чистими записами: порт тут ні до чого, винні місцеві пірати. Отримавши папери назад, гоблінський очільник задумує відплату Флібустьєрам Південних морів, щоб повернути втрачений вантаж.",h="Після перевірки на пристанях Начальник Пристані Діззівіг повертає Ґазлоу його облікову книгу з чистими...",kw={"зниклий вантаж","діззівіг","ґазлоу","облікова книга","флібустьєри південних морів","раджет"},ang={["class:Rogue"]="Порпання в портових паперах показує, як легко товари зникають між морем і берегом, — класичний прийом контрабандистів.",["faction:Alliance"]="Діяльність у Пустках вимагає обачних союзів, і допомога проводові Раджета дає надійну опору в центральному Калімдорі.",["faction:Horde"]="Раджет нейтральний, але задоволений Ґазлоу — це стабільні торгові шляхи й гоблінський нейтралітет, вигідні Орді."},sec={{t="Книги зведено",b="Раджет живе торгівлею, але гамірний порт поруч із Пустками — це постійний головний біль із постачанням. Коли очікуваний вантаж зникає, Ґазлоу підозрює помилку в портовому обліку чи шахрайство на пристанях. Переглянувши декларацію, Начальник Пристані Діззівіг запевняє, що його книги чисті, а записи про прийом вантажів зведено до копійки, — отже, зниклий крам так і не потрапив на пристань."},{t="Погляд на флібустьєрів",b="Діззівіг очистив внутрішні справи порту від підозр у розкраданні, тож лишається один імовірний винуватець — Флібустьєри Південних морів, що отаборилися трохи далі вздовж узбережжя. Діззівіг повертає книгу разом зі згадкою про окремі ящики з Андермайну, що чекають на отримувача, і скеровує шукача пригод назад до головного інженера Раджета. Переконавшись у вірності свого начальника пристані, Ґазлоу перемикається з облікових книг на організацію походу по вкрадену здобич."}},faq={{q="Що в книзі обліку Ґазлоу?",a="У книзі обліку Ґазлоу — вантажні відомості, переліки вантажів і портові журнали прийому товарів, що прибувають до Раджета. Начальник Пристані Діззівіг переглядає її, щоб перевірити, чи зниклі ящики взагалі зносили з кораблів.",al={"що таке книга обліку","книга обліку ґазлоу","вантажна відомість"}},{q="Хто насправді вкрав вантаж Ґазлоу?",a="Ґазлоу підозрює Флібустьєрів Південних морів — місцеву зграю піратів, що стоїть табором на узбережжі на південь від Раджета. Записи Діззівіга не показують жодних розбіжностей на причалах, тож Ґазлоу звертає увагу на розбійників.",al={"хто вкрав вантаж","хто забрав вантаж","у кого вантаж"}},{q="Чому Ґазлоу довіряє Начальникові Пристані Діззівігу?",a="Ґазлоу довіряє Діззівігу, бо той у нього на платні й має славу надійного служаки. Бос вважає, що Діззівіг не такий дурний, щоб його дурити, і вірить на слово, що книги чисті.",al={"чи діззівіг бреше","чи ґазлоу довіряє діззівігу","чи діззівіг чесний"}},{q="Що за речі з Андермайна згадує Діззівіг?",a="Діззівіг згадує, що отримав окремі товари з Андермайна, столиці гоблінів на острові Кезан: вони чекають, коли Ґазлоу знайде хвилинку між справами містечка й забере їх.",al={"вантаж з андермайна","що йде з андермайна","товари андермайна"}},{q="Куди веде це розслідування далі?",a="Повернувши книгу обліку Ґазлоу, ви переходите просто до завдання «Викрадена здобич», де вас наймають пробратися до таборів Флібустьєрів Південних морів на південному узбережжі Пусток і повернути втрачений вантаж.",al={"яке завдання далі","наступний крок після зниклого вантажу","куди йти далі"}},{q="Де знайти Начальника Пристані Діззівіга?",a="Начальник Пристані Діззівіг наглядає за причалами Раджета: він стоїть біля пірсів, де торгові кораблі пришвартовуються, щоб завантажитися й розвантажитися.",al={"де діззівіг","місце діззівіга","знайти начальника пристані"}}},fp="20,318,27.420.0,23.454.1,28.227.0,38.218.0,44.222.0,57.194.0,40.209.1,38.145.0"}
P.entries["quest:893"] = {n="Зброя на вибір",s="Таттернак Стілфордж, коваль Орди в Таборі Тауражо, перевіряє чутки, що південні шипогриви-Гостромани виготовляють напрочуд міцну зброю. Отримавши від Вождя доручення оцінити цю загрозу, він залучає мандрівників, щоб здобути зброю просто в загонів шипогривів за Полем Велетнів. Вивчення цих зразків показує, що шипогриви куди небезпечніші й технічно вправніші, ніж спершу вважала Орда.",h="Таттернак Стілфордж, коваль Орди в Таборі Тауражо, перевіряє чутки, що південні шипогриви-Гостромани...",kw={"зброя на вибір","таттернак стілфордж","гостромани","шипогриви","поле велетнів","табір тауражо"},ang={["faction:Horde"]="Табір Тауражо лишається вразливим на південному рубежі, тож відомості про військовий поступ Гостроманів вкрай важливі для захисту торгових шляхів через Пустки.",["profession:Blacksmithing"]="Для коваля оцінка здобутої зброї показує, як якість ворожих матеріалів прямо визначає тактичну готовність на рубежі.",["race:Orc"]="Оркська честь вимагає шанувати бойову силу, а обов'язок Таттернака перед Траллом — вчасно визнати, коли супротивник стає справді небезпечним."},sec={{t="Дивний поступ",b="Шипогривів Пусток зазвичай мають за диких, грубих тварюк із примітивними знаряддями з дерева, кістки й каменю. Проте до Табору Тауражо дійшли чутки, що плем'я Гостроманів далеко на півдні почало виставляти напрочуд міцне бойове спорядження. Таттернак Стілфордж, оркський коваль, що діє за наказами Вождя Тралла, зацікавився цими чутками. Хоч він і сумнівався, що шипогриви здатні збагнути справжню металургію, але хотів доказів, щоб з'ясувати, чи вони опанували нові прийоми, чи знайшли кращі запаси."},{t="Озброєння Гостроманів",b="Щоб вивчити їхнє ремесло, Таттернакові потрібні були різноманітні зразки з арсеналу племені. Він послав розвідників на південь, повз велетенські кістяки Поля Велетнів, до бойових таборів Гостроманів. Там воїни мусили вирвати кинджали-штрикачі в скрадачів-шипогривів, обвуглені жезли в їхніх провидців і важкі бойові щити в шалених штурмовиків. Кожна річ давала уявлення про бойові й містичні мистецтва, що живлять нинішній наступ Гостроманів на землі Орди."},{t="Недооцінений ворог",b="Узявши до рук здобуті зразки, Таттернак змінив скепсис на тривогу. Зброя показувала таку майстерність і міцність, що перекреслювали уявлення Орди про можливості шипогривів. Визнавши, що Орда небезпечно недооцінила плем'я, коваль відклав роботу в кузні, щоб ретельніше дослідити матеріали, підозрюючи, що Гостроманам у війні допомагає якась стороння сила чи новознайдений ресурс."}},faq={{q="Хто такий Таттернак Стілфордж?",a="Таттернак Стілфордж — орк-коваль і зброяр у Таборі Тауражо на півдні Пусток. Виконуючи наказ Вождя Тралла підтримувати прикордонну оборону Орди, він вивчає ворожу зброю й кує спорядження для місцевих загонів.",al={"таттернак стілфордж","хто дає зброю на вибір","коваль тауражо"}},{q="Навіщо Таттернакові зброя шипогривів?",a="Надійшли звістки, що південне плем'я Гостроманів почало орудувати напрочуд міцною зброєю, хоча вправних ковалів у нього ніколи не було. Таттернак хоче оглянути їхні кинджали, чарівні палички й щити, щоб зрозуміти, як вони їх роблять і чи не стали вони небезпечнішими.",al={"навіщо збирати зброю вепролюдів","причина зброї на вибір","мотиви таттернака"}},{q="Де шипогриви Гостромани, які потрібні для цього доручення?",a="Потрібні шипогриви живуть у таборах на крайньому півдні Пусток, за Полем Велетнів, на захід від дороги, що веде до Великого Підйомника й Тисячі Голок.",al={"де вепролюди","місце зброї на вибір","де знайти гостроманів"}},{q="Які шипогриви носять потрібну зброю?",a="Скрадачі Гостроманів носять Кинджали Гостроманів, віщуни Гостроманів орудують Обвугленими Чарівними паличками Гостроманів, а шаленці Гостроманів мають міцні Бойові Щити Гостроманів.",al={"хто лишає кинджал","хто лишає жезл","хто лишає щит"}},{q="Що Таттернак з'ясовує, оглянувши зброю?",a="Оглянувши речі, Таттернак підтверджує, що зброя напрочуд добре зроблена й набагато перевершує те, чого Орда чекала від шипогривів. Це спонукає його дослідити сировину, якою вони користуються, у наступному дорученні — «Новий зразок руди».",al={"що з'ясовує таттернак","наслідок зброї на вибір","чи вепролюди ковалі"}},{q="Чому Орду непокоїть, що шипогриви виготовляють зброю?",a="Щоб утримати безкраї Пустки від численних місцевих загроз, Орда покладається на кращу ковальську майстерність і дисципліновану силу. Якщо плодючі шипогриви Гостромани зможуть масово кувати міцну зброю із заліза чи сталі, вони легко здолають прикордонні застави на кшталт Табору Тауражо.",al={"чому зброя вепролюдів важлива","рівень загрози вепролюдів"}}},fp="17,455,21.538.0,26.476.0,25.450.1,29.245.0,42.298.0,55.174.0,42.176.0,47.265.1,62.279.0"}
P.entries["quest:894"] = {n="Самофланж",s="За дорученням гоблінського інженера Спаттервалва з Раджета шукачі пригод вирушають на північ, до дослідницької застави Венчурної Компанії на південний захід від Багнистого Болота. Їхня мета — знайти загадковий пристрій, відомий лише як самофланж. Маючи при собі викрадену інструкцію з експлуатації, допитливий дослідник мусить упоратися з норовливим пультом керування, щоб видобути деталь.",h="За дорученням гоблінського інженера Спаттервалва з Раджета шукачі пригод вирушають на північ, до...",kw={"самофланж","спаттервалв","венчурна компанія","багниста драговина","пульт керування","інженерія"},ang={["faction:Horde"]="Загарбницька експлуатація й хімічні стоки Венчурної Компанії загрожують крихкій природі Пусток, тож зрив їхніх робіт — нагальна справа для місцевих оборонців Орди.",["profession:Engineering"]="Інженери оцінять одержимість Спаттервалва кресленнями конкурентів — наочний приклад безжальності гоблінського промислового шпигунства."},sec={{t="Чудернацька штуковина",b="Гобліни славляться потягом до винаходів, цікавістю й прибутком, але навіть майстра Спаттервалва спантеличила остання розробка, що вийшла з розкопок Венчурної Компанії на півночі Пусток. На південний захід від Багнистого Болота конкуренти майструють пристрій під назвою «самофланж». Не знаючи ні його точного механічного призначення, ні прибуткових можливостей, Спаттервалв прагне заволодіти обладнанням, щоб розібрати й відтворити його конструкцію, перш ніж нею скористаються комерційні суперники."},{t="Проникнення на установку",b="Здобути пристрій — справа непроста. Венчурна Компанія люто охороняє свої роботи: довкола установки — озброєні наглядачі, лісоруби й складна техніка. Спаттервалв дає перехоплену інструкцію з експлуатації, щоб безпечно вимкнути норовливу установку. Діставшись до центрального пульта керування, дослідник бачить безладне розмаїття важелів, лампочок і манометрів, що підтримують оптимальний тиск у трьох ключових клапанах, — і все це під замкненою панеллю."}},faq={{q="Що таке самофланж?",a="Навіть Спаттервалв до кінця не знає, що це таке й що воно робить. Це засекречена дослідна механічна деталь, створена Венчурною Компанією на її об'єкті на південний захід від Багнистого Болота.",al={"що таке самофланж","призначення самофланжа","що робить самофланж"}},{q="Хто такий Спаттервалв?",a="Спаттервалв — гоблін-інженер і майстер на всі руки в Раджеті. Зацікавлений виробничими таємницями Венчурної Компанії, він наймає шукачів пригод, щоб ті зривали її роботи й захоплювали її технічні досягнення.",al={"хто спаттервалв","місце спаттервалва","видавець"}},{q="Де пульт керування?",a="Пульт — на дослідному об'єкті Венчурної Компанії на північ від Перехрестя, на південний захід від забрудненої Багнистого Болота в Пустках.",al={"місце пульта","де пульт","де знайти самофланж"}},{q="Що Венчурна Компанія робить у Пустках?",a="Венчурна Компанія — безсовісний картель, що женеться за прибутком і виснажує природні ресурси Калімдору. У Пустках вона вирубує ліси, бурить нафту й ставить дослідні установки на кшталт тих, що довкола Багнистого Болота.",al={"венчурна компанія в пустках","чому тут венчурна компанія","діяльність у болоті слизу"}},{q="Як безпечно від'єднати самофланж?",a="На пульті керування три відкриті клапани й замкова щілина. Якщо діяти за здобутою Спаттервалвом інструкцією, можна оминути запобіжні блокування й, покрутивши клапани, від'єднати модуль.",al={"як користуватися пультом","інструкція пульта керування","керівництво"}},{q="Чи Спаттервалв працює на Венчурну Компанію?",a="Ні. Спаттервалв діє як незалежний агент чи суперник, що прагне перебити й викрасти інженерні відкриття Венчурної Компанії, щоб вивчити їх самому.",al={"чи спаттервалв працює на венчурну","фракція спаттервалва"}}},fp="11,373,22.541.0,20.487.0,22.190.0,20.194.0,37.155.0,42.210.0,44.216.0,47.160.0"}
P.entries["quest:895"] = {n="РОЗШУКУЄТЬСЯ: барон Лонгшор",s="«РОЗШУКУЄТЬСЯ: барон Лонгшор» — оголошення про нагороду, яке Головний Інженер Ґазлоу вивісив на пристанях Раджета. Його ціль — Барон Лонгшор, горезвісний піратський капітан родом із Ґілнеаса, що командує кораблями Флібустьєрів Південних морів. Присутність Лонгшора на Узбережжі Крамарів — пряма загроза гоблінському торговельному мореплавству по всьому краю.",h="«РОЗШУКУЄТЬСЯ: барон Лонгшор» — оголошення про нагороду, яке Головний Інженер Ґазлоу вивісив на пристанях...",kw={"розшукується","барон лонгшор","ґазлоу","ґілнеас","флібустьєри південних морів","нагорода"},ang={["faction:Alliance"]="Хоч Лонгшор родом із Ґілнеаса, його піратство зриває нейтральне мореплавство, на яке покладаються мандрівники Альянсу між Калімдором і Східними Королівствами.",["faction:Horde"]="Очищення околиць Раджета від Флібустьєрів Південних морів тримає порт відкритим і привітним для припасів Орди, що надходять у Пустки.",["race:Human"]="Ґілнеаський барон на чолі головорізів у Калімдорі — нагадування про те, як далеко морями розбрелися дезертири й вигнанці зі Східних Королівств."},sec={{t="Піратство на Узбережжі Крамарів",b="Води біля Пусток — важливі морські шляхи картелю Стімвідл, що поєднують Раджет із Буті Бей і далекими краями. На жаль, Флібустьєри Південних морів укріпили табори на узбережжі на південь від містечка. Під командуванням таких постатей, як Барон Лонгшор, ці головорізи дошкуляють купецьким кораблям, зривають торгівлю й висмоктують усі соки з місцевої гоблінської управи."},{t="Капітан із Ґілнеаса",b="Відомо, що Лонгшор походить із відрізаного від світу людського королівства Ґілнеас, тож його присутність у Калімдорі — незвичайна й небезпечна дивовижа. Капітан піратського корабля «Необачний», він висаджує свої команди на берег трохи на північ від Твердині Північної Варти. Замість великої дипломатії Ґазлоу розв'язує проблему практичним гоблінським способом: оголошує відкриту нагороду за голову пірата, яку можна впізнати."}},faq={{q="Хто такий Барон Лонгшор?",a="Барон Лонгшор — капітан піратів родом із Ґілнеасу, що командує кораблем «Безтурботний» у Флібустьєрів Південних морів. Він розбійничає на березі на південь від Раджета, грабуючи морські шляхи.",al={"барон лонгшор","хто такий лонгшор","капітан лонгшор"}},{q="Чому Ґазлоу хоче його смерті?",a="Піратство Лонгшора прямо загрожує торговим перевезенням Ґазлоу з Раджета. Щоб торгівля йшла безпечно, а прибутки Стімвідла були захищені, Ґазлоу призначив нагороду за голову Лонгшора.",al={"чому вбити лонгшора","причина нагороди ґазлоу","чому розшукують лонгшора"}},{q="Де знайти Барона Лонгшора?",a="Він буває в таборах Флібустьєрів Південних морів на Узбережжі Крамарів на південь від Раджета, трохи на північ від Твердині Північної Варти.",al={"місце лонгшора","де лонгшор","місце барона лонгшора"}},{q="Яким кораблем командує Барон Лонгшор?",a="Він капітан «Безтурботного» — грізного піратського корабля, відомого морякам у відкритому морі довкола Узбережжя Крамарів.",al={"корабель лонгшора","назва човна лонгшора","безтурботний корабель"}},{q="Чи Барон Лонгшор — шляхтич Альянсу?",a="Хоча він носить титул барона й походить із Ґілнеасу, він діє суто як корсар-ренегат на чолі Флібустьєрів Південних морів і нинішньому проводові Альянсу не підкоряється.",al={"чи лонгшор з альянсу","пірат-шляхтич гілнеаса","лонгшор гілнеас"}},{q="Де висить оголошення про нагороду?",a="Оголошення про розшук висить на дошці біля банку в портовому містечку Раджет.",al={"де оголошення про розшук","місце плаката лонгшора","як почати завдання лонгшора"}}},fp="23,350,28.382.0,22.405.0,23.193.0,31.209.0,35.129.0,39.116.0,37.188.0,35.84.0"}
P.entries["quest:896"] = {n="Скарб шахтаря",s="Начальник Пристані Діззівіг із Раджета прочуває про надзвичайну знахідку в Шахті Кам'яної Жили Венчурної Компанії — смарагд завбільшки з кулак. Не бажаючи, щоб безжальний гірничий синдикат нажився на ньому, Діззівіг наймає шукача пригод, щоб той відбив Смарагд Котяче Око в наглядачів шахти — за частку прибутку.",h="Начальник Пристані Діззівіг із Раджета прочуває про надзвичайну знахідку в Шахті Кам'яної Жили Венчурної...",kw={"скарб шахтаря","смарагд котяче око","шахта кам'яної жили","діззівіг","венчурна компанія","раджет"},ang={["class:Rogue"]="Пробратися до ворожого гірничого табору й позбавити жадібних наглядачів пильно стереженого самоцвіту — саме для цього існують усі хитрощі розбійника.",["faction:Horde"]="Удар по управителях Венчурної Компанії в Шахті Кам'яної Жили зриває плани загарбницького промислового картелю, що зазіхає просто на землі Орди в Пустках.",["profession:Mining"]="Рудокопи оцінять неймовірну рідкісність цілого смарагду завбільшки з кулак — такий зразок майже ніколи не переживає видобутку без тріщин чи сколів."},sec={{t="Очі на пристанях",b="Як портовий урядовець, що керує гамірною гаванню між Раджетом і Буті Бей, Начальник Пристані Діззівіг чує чи не кожну таємницю, яку шепочуть на торгових шляхах. Коли дійшли чутки про величезний самоцвіт завбільшки з кулак, знайдений глибоко в Шахті Кам'яної Жили, Діззівіг одразу побачив вигідну нагоду. Безоглядний відкритий видобуток Венчурної Компанії на півночі Пусток не здобуває їй друзів, тож навряд чи хтось ставитиме запитання, якщо її найбільша недавня знахідка тихо зникне."},{t="Частка з жили",b="Шахта, багата на валуни, на північний схід від Багнистого Болота повна робітників, але Діззівіг розумів, що простому копачеві не дозволять лишити собі такий рідкісний скарб. Смарагд Котяче Око швидко конфіскували наглядачі й силовики Венчурної Компанії, що охороняють ділянку. Щоб повернути самоцвіт, доведеться зустрітися з цими важко озброєними управителями віч-на-віч, забрати камінь і доставити його Діззівігу, щоб той оцінив його за вигідними цінами Андермайну."}},faq={{q="Хто такий Начальник Пристані Діззівіг?",a="Начальник Пристані Діззівіг — гоблін-портовий урядник у Раджеті. Він наглядає за вантажами й пасажирами, що перетинають море до Буті Бею й назад, і, користаючись своїм становищем, торгує цінними плітками, чутками й купецькими відомостями.",al={"діззівіг","хто дає скарб шахтаря","начальник пристані раджета"}},{q="Де Шахта Кам'яної Жили?",a="Шахта Кам'яної Жили — на півночі Пусток, серед пагорбів трохи на північний схід від залитої нафтою промислової ділянки на Багнистому Болоті.",al={"місце шахти кам'яної жили","де смарагд","шахта венчурної компанії в пустках"}},{q="У кого в шахті Смарагд Котяче Око?",a="Самоцвіт забрало начальство, а не прості робітники. Його можна здобути, здолавши наглядачів і силовиків Венчурної Компанії, що керують роботами в Шахті Кам'яної Жили й довкола неї та стережуть їх.",al={"хто лишає смарагд котяче око","смарагд котяче око випадає","де смарагд котяче око"}},{q="Що Венчурна Компанія шукає в Пустках?",a="Венчурна Компанія — агресивний, ніким не стримуваний гоблінський торговий синдикат, що прагне лише швидко виснажити ресурси. На півночі Пусток вона веде руйнівне буріння на Багнистому Болоті й посилені розкопки в Шахті Кам'яної Жили, добуваючи деревину, нафту й мінеральні багатства й не зважаючи на місцеву природу.",al={"чому венчурна компанія в пустках","венчурна компанія пустки"}},{q="Чому Діззівіг згадує Андермайн?",a="Андермайн — підземне острівне місто-столиця й прабатьківщина гоблінських картелів. Як головний господарський і торговий осередок гоблінів, він визначає ринкові ціни на дорогоцінні камені й рідкісні товари по всьому Азероту.",al={"згадка андермайна","ціни на самоцвіти андермайн"}},{q="Чи справді Діззівіг ділиться прибутком?",a="Вірний гоблінській діловій етиці, Діззівіг дотримує угоди й, коли ви принесете Смарагд Котяче Око, віддає обіцяні п'ятдесят відсотків від його оціночної вартості на ринку Андермайна.",al={"чи діззівіг ділиться порівну","виплата діззівіга"}}},fp="15,333,17.524.0,17.472.0,28.262.0,39.168.0,43.248.0,54.326.0,38.241.0,41.196.1"}
P.entries["quest:897"] = {n="Жнець",s="«Жнець» — завдання, що починається зі знахідки відтятої голови дивного чужинського комахоподібного хижака на півдні Пусток. Принесений Джорнові Скайсіру в Табір Тауражо, цей тривожний зразок відкриває похмурі наслідки для духовної й природної рівноваги краю.",h="«Жнець» — завдання, що починається зі знахідки відтятої голови дивного чужинського комахоподібного хижака на...",kw={"жнець","силітиди","джорн скайсір","табір тауражо","передчуття","пустки"},ang={["class:Druid"]="Друїди, що вивчають відродження Калімдору, одразу відчувають згубну, паразитичну природу цих чужинських копачів, що вторгаються в савану.",["class:Shaman"]="Шамани помітять досаду Джорна Скайсіра: дух уже покинув голову, і єднання зі стихійними силами не допоможе дізнатися справжнє походження істоти.",["faction:Horde"]="Табір Тауражо — південний щит Орди в Пустках, тож будь-який хижак-загарбник на довколишніх кручах — важливе питання безпеки.",["race:Tauren"]="Для шу'гало найголовніше — берегти злагоду Земної Матері; зустріч із сутністю, що кидає виклик природному ладу, віщує глибокий духовний розлад."},sec={{t="Неприродний прибулець",b="Серед саван південних Пусток мандрівники часом натрапляють на моторошне видовище — відтяту голову силітида, відомого як Жнець. На відміну від місцевих левів, рапторів і кодо, що бродять степами, ця хітинова комаха здається цілком чужою природному ладу Калімдору. Її присутність свідчить про наступ чужинського життя, якому не місце на відкритих рівнинах."},{t="Передчуття Джорна Скайсіра",b="Отримавши голову істоти в Таборі Тауражо, тауренський містик Джорн Скайсір оглядає рештки. Дух звіра вже відлетів, тож він не може провидіти його походження, але одразу розуміє, що це глибока загроза. Джорн боїться, що вторгнення цієї істоти в Пустки може віщувати Орді похмуре майбутнє, і застерігає, що під пісками визрівають темніші таємниці."}},faq={{q="Що таке Жнець?",a="Жнець — великий силітид-комаха, що нишпорить на півдні Пусток. Його хітинова, чужорідна будова цілком відрізняється від місцевих звірів краю.",al={"хто такий жнець","який це жук жнець","істота жнець"}},{q="Хто такий Джорн Скайсір?",a="Джорн Скайсір — шанований старійшина й духовний провідник тауренів у Таборі Тауражо. Він стежить за духовним здоров'ям рівнин і радить у справах, що загрожують рівновазі землі.",al={"джорн скайсір","хто здає завдання","джорн тауражо"}},{q="Звідки взявся Жнець?",a="Джорн Скайсір не може з однієї лише відтятої голови розгадати, звідки він точно, але це паросток вуликів силітидів, що поширюються з глибоких пустель на півдні.",al={"звідки силітиди","походження жнеця","джерело силітидів"}},{q="Чому ця істота непокоїть Джорна Скайсіра?",a="Неприродна подоба й чужий дух істоти глибоко бентежать Джорна. Він відчуває, що її поява в Пустках — не випадковість, а зловісне попередження про неприродну загрозу, що насувається.",al={"чому джорн стривожений","реакція джорна скайсіра","похмуре майбутнє"}},{q="Як почати це завдання?",a="Завдання починається, коли ви вбиваєте рідкісного силітида, відомого як Жнець, на півдні Пусток і забираєте його відтяту голову, — тоді вам слід шукати поради в старійшин Табору Тауражо.",al={"як отримати завдання","голова жнеця випадає","почати жнеця"}},{q="Що Джорн радить робити далі?",a="Джорн не закликає до негайного удару: він розуміє, що Орда має спершу підготуватися й пильнувати, поки таємниця силітидів, що наступають, поволі розкривається.",al={"завдання далі","що після голови жнеця","наступний крок джорна"}}},fp="13,277,21.396.0,26.406.1,22.183.0,20.203.0,35.172.0,43.195.0,28.188.0,35.176.0"}
P.entries["quest:898"] = {n="На волю з Твердині",s="«На волю з Твердині» — завдання із супроводом у Пустках, у якому шукачі пригод з Орди визволяють Гілтареса Файрбоу з людського полону у Твердині Північної Варти. Схоплений після того, як його корабель перехопили й потопили, ельф-матрос прагне відчайдушно втекти, щоб повернутися до свого капітана в Раджеті.",h="«На волю з Твердині» — завдання із супроводом у Пустках, у якому шукачі пригод з Орди визволяють Гілтареса...",kw={"на волю з твердині","гілтарес файрбоу","твердиня північної варти","тало'тас брайтсан","супровід","раджет"},ang={["faction:Horde"]="Удар углиб Твердині Північної Варти, щоб визволити ув'язненого контрабандиста, — ще один приємний удар по войовничому плацдарму Терамора на узбережжі Пусток."},sec={{t="Ув'язнений у Північній Варті",b="Твердиня Північної Варти — військове вістря Терамора на узбережжі Пусток, пильне й вороже до будь-якої уявної загрози. У тенета цієї параної й потрапив Гілтарес Файрбоу. Його корабель, що возив самогон торговим шляхом між Раджетом і портом Буті Бей, сили Альянсу обстріляли й пустили на дно. Єдиного вцілілого, витягнутого з уламків, Гілтареса кинули в підземелля Північної Варти, звинувативши в тому, що він ворожий агент, який змовляється проти Альянсу."},{t="Втеча контрабандиста",b="Хоч тюремники й малюють його небезпечним диверсантом, Гілтарес наполягає, що він лише скромний матрос, якого спіймали з незаконним трунком. З допомогою сил Орди, готових ударити по Північній Варті, він робить відчайдушну спробу втекти, пробивається з фортеці й тікає узбережжям на північ, до Раджета. Там Капітан Тало'тас Брайтсан вітає члена команди, що повернувся, і знову приймає його до лав Каперів Тало'дана."}},faq={{q="Хто такий Гілтарес Файрбоу?",a="Гілтарес Файрбоу — ельф-матрос, що ходить під командою Капітана Тало'таса Брайтсана. Він служив на судні, яке возило самогон між Раджетом і Буті Беєм, доки вояки Терамора не потопили його корабель і не закували його в кайдани.",al={"ґілтарес","хто такий ґілтарес файрбоу","хто в'язень північної варти"}},{q="Чому сили Терамора заарештували Гілтареса?",a="Солдати Альянсу з Твердині Північної Варти перехопили його корабель біля узбережжя Пусток і пустили на дно. Надзвичайно підозріливий до всіх суден біля своєї твердині, гарнізон визнав корабель із самогоном ворожим, а Гілтареса — ворожим Альянсу агентом.",al={"чому терамор заарештував ґілтареса","чому ґілтарес у в'язниці","чому потопили корабель"}},{q="Куди йде Гілтарес, коли його звільнено?",a="Гілтарес тікає на північ із Твердині Північної Варти східним узбережжям Пусток, доки не дістанеться нейтрального гоблінського порту Раджет. Там він повертається до Капітана Брайтсана біля причалів.",al={"куди супроводжувати ґілтареса","місце призначення ґілтареса","куди йде супровід"}},{q="Хто такі Капери Тало'дана?",a="Капери Тало'дана — морська команда під проводом Капітана Тало'таса Брайтсана, що діє з Раджета. Вони займаються перевезеннями й незаконною контрабандою, зокрема возять підпільний самогон через море між Калімдором і Східними Королівствами.",al={"капери тало'дана","команда брайтсана","кого веде брайтсан"}},{q="Чому Твердиня Північної Варти нападає на цивільні чи контрабандні кораблі?",a="Твердиня Північної Варти — фортеця Терамора в Пустках, що стоїть просто між землями Орди й важливими морськими шляхами. Через загострену підозріливість і суворі військові накази її командири бачать майже в кожному судні не з Альянсу підривну операцію Орди чи піратську загрозу.",al={"чому північна варта ворожа","агресія терамора в пустках","призначення північної варти"}},{q="Що віз затоплений корабель?",a="Корабель віз партію незаконного самогону для розподілу між Раджетом і Буті Беєм, а не зброю чи військові припаси.",al={"що було на кораблі","вантаж ґілтареса","що перевозили"}}},fp="18,279,24.492.0,19.448.0,27.223.0,47.318.0,35.200.1,33.246.0,60.290.0,40.148.0"}
P.entries["quest:899"] = {n="Зжертий ненавистю",s="«Зжертий ненавистю» — похмуре доручення від Манкріка на Перехресті в Пустках. Змучений жорстокою засідкою, що розлучила його з дружиною, скорботний орк обертає болісну невідомість на невпинну кровну помсту шипогривам-Щетиноспинам. Він закликає мандрівників Орди винищувати цих тварюк десятками й принести величезну купу їхніх іклів.",h="«Зжертий ненавистю» — похмуре доручення від Манкріка на Перехресті в Пустках.",kw={"зжертий ненавистю","манкрік","щетиноспини","шипогриви","помста","перехрестя"},ang={["class:Warrior"]="Воїн знає, що рану серця не завжди перев'яжеш, і єдині ліки для Манкріка — зустрічати сталь сталлю на колючих рівнинах.",["faction:Horde"]="Шипогриви загрожують важливим шляхам між Дуротаром, Малгором і Південними Пустками, тож особиста війна Манкріка прямо збігається з убезпеченням земель Орди.",["race:Orc"]="Горе Манкріка й незламне прагнення помститися за рідних глибоко відгукуються в традиційній оркській честі й у суворій правді освоєння нової домівки в Калімдорі."},sec={{t="Одержимий помстою",b="Під пекучим сонцем Перехрестя стоїть Манкрік — воїн, яким заволоділо горе. Переживши жорстокий набіг шипогривів, після якого він лишився скаліченим, а його дружина зникла, він проводить дні, вдивляючись у посушливий обрій, — чи не з'явиться десь свинолюд. Його жага їхньої крові не вгамовується, хоч він власноруч порубав чимало, і змушує шукати допомоги в побратимів з Орди."},{t="Ікла Щетиноспинів",b="Манкрік не шукає миру чи розради — він вимагає трофеїв нещадної різанини: шістдесят іклів шипогривів-Щетиноспинів. Для нього кожне розтрощене ікло — дещиця страждання, поверненого чудовиськам, що зруйнували його життя. Купи кісток не загоять його горя й не вгамують жаги відплати, але вигляд закривавлених Щетиноспинів дає пораненому воїнові скороминуче, гірке вдоволення."}},faq={{q="Навіщо Манкрікові шістдесят іклів шипогривів?",a="Манкріка цілком поглинули горе й гнів після жорстокої засідки шипогривів, що розлучила його з дружиною. Шістдесят іклів — навмисне жорстока кількість, щоб завдати племені Щетиноспинів тяжких утрат і дати йому хоч трохи розради від страждань своїх кривдників.",al={"навіщо шістдесят іклів","завдання іклів манкріка","чому стільки іклів"}},{q="Де відбувається це завдання?",a="Манкрік дає це завдання на Перехресті в центрі Пусток і посилає шукачів пригод проти шипогривів Щетиноспинів, що живуть у чагарниках і тернових укріпленнях поблизу.",al={"де зжертий ненавистю","місце зжертого ненавистю"}},{q="Чи принесені ікла вдовольняють помсту Манкріка?",a="Не зовсім. Манкрік визнає, що жага помсти не згасла, але, бачачи, яких нищівних утрат зазнали шипогриви, він похмуро всміхається: вони нарешті відчули його біль.",al={"чи манкрік перестане ненавидіти","кінець завдання манкріка"}},{q="Чому Манкрік згадує Табір Тауражо?",a="Похмуро розмірковуючи, Манкрік питає себе, чи не варто було після засідки тікати на південь, до Табору Тауражо, а не на північ, до Перехрестя, і чи не обернулися б тоді інакше і бій, і його пошуки.",al={"чому тауражо","табір тауражо манкрік"}},{q="Хто такі Щетиноспини?",a="Щетиноспини — агресивне плем'я шипогривів, корінне для Пусток. Затято ревниві до своєї землі й ворожі до чужинців, вони постійно воюють з Ордою й нападають на мандрівників на рівнинах зі своїх зарослих тернами таборів.",al={"що таке щетиноспини","плем'я щетиноспинів"}},{q="Чи пов'язане це з пошуками дружини Манкріка?",a="Так. Пекуча ненависть Манкріка походить саме від тієї засідки, де його з дружиною здолали. Поки шукачі пригод обнишпорюють рівнини, щоб дізнатися про її долю в супутньому завданні «Загублена в бою», це доручення втілює його чисте прагнення поквитатися з її кривдниками.",al={"зв'язок із загубленою в бою","завдання дружини манкріка"}}},fp="18,377,21.412.0,24.400.0,43.295.0,33.179.0,52.216.0,38.229.0,25.226.0,44.281.0"}
P.entries["quest:9"] = {n="Поля смерті",s="«Поля смерті» — завдання Альянсу від Фермера Салдіна у Вестфолі. Салдін доручає шукачам пригод знищити здичавілих Жнивних Вартових, що заполонили його посіви й сусідні ниви. Це завдання показує, як занепало місцеве землеробство після того, як Братство Дефіас розладнало життя краю.",h="«Поля смерті» — завдання Альянсу від Фермера Салдіна у Вестфолі.",kw={"поля смерті","фермер салдін","жнивні вартові","ферма салдина","автоматони","вестфол"},ang={["faction:Alliance"]="Для мандрівників Альянсу допомога Салдінові — це прямий внесок у захист одного з небагатьох уцілілих джерел їжі в краї, покинутому короною Стормвінда.",["profession:Engineering"]="Інженери впізнають у Жнивних Вартових механічні дива з годинниковим механізмом, які без належного догляду пішли шкереберть."},sec={{t="Обложене господарство",b="Коли розбійники й злочинці прокотилися краєм, багато фермерів Вестфолу покинули свої наділи, але Фермер Салдін і його родина вирішили не відступати. На жаль, злодії, що самовільно оселилися довкола, — не єдина загроза, що душить Ферму Салдина. Механічні Жнивні Вартові, створені доглядати й берегти зерно, вийшли з-під контролю: вони походжають борознами й нападають на кожного, хто наблизиться."},{t="Розчистити землю",b="Щоб ферма могла працювати й далі, Салдін просить перехожих мандрівників розібрати двадцять ворожих автоматонів на його полях і сусідніх ділянках. Знищення цих механізмів дає врожаю Салдіна тимчасовий перепочинок і зберігає рідкісний острівець упертої надії, що житницю Вестфолу колись удасться відвоювати."}},faq={{q="Хто дає завдання «Поля смерті»?",a="Завдання дає Фермер Салдін на Фермі Салдина, при дорозі в центрі Вестфолу.",al={"видавець полів смерті","хто дає поля смерті","завдання салдіна"}},{q="Хто такі Вартові Жнив?",a="Вартові Жнив — заводні опудала, зроблені, щоб доглядати посіви й стерегти поля від шкідників. Коли у Вестфолі почалися заворушення й люди покидали землю, багато цих механізмів лишилися без нагляду чи були перепрограмовані й люто обернулися проти тих самих фермерів, яким мали служити.",al={"що таке вартові жнив","переказ про вартових жнив","механічні опудала вестфолу"}},{q="Чому Фермер Салдін не втік із Вестфолу, як інші?",a="На відміну від сусідів, що покинули садиби злодіям і розбійникам, Салдін не хоче віддавати свій хліб. Він уперто тримається свого клаптя землі й з допомогою найнятих шукачів пригод відбивається від збунтованих машин.",al={"чому салдін не втік","переказ про фермера салдіна","салдін лишається"}},{q="Що треба зробити в завданні «Поля смерті»?",a="Вам доручено знищити двадцятьох Вартових Жнив, що блукають полями Салдіна й навколишніми покинутими фермами.",al={"мета полів смерті","скільки вартових жнив","кого вбивати в полях смерті"}},{q="Кого Салдін називає «злодіями»?",a="Салдін має на увазі злодіїв і розбійників, сяк-так об'єднаних у Братство Дефіас, чиї набіги й вимагання вигнали більшість поселенців з їхньої землі.",al={"хто злодії","злодії салдіна","хто вигнав фермерів із вестфолу"}},{q="Чи розв'язує це завдання біди фермерів Вестфолу?",a="Знищення двадцятьох Вартових Жнив дає фермі Салдіна змогу перевести подих, але загальна загроза від бандитів і зламані машини по всьому краю нікуди не діваються.",al={"чи вестфол оговтається","кінець полів смерті","результат салдіна"}}},fp="18,302,23.401.0,17.315.0,40.96.0,26.284.0,57.217.0,46.122.0,39.162.0,59.192.0"}
P.entries["quest:90"] = {n="Пряний шашлик із вовка",s="«Пряний шашлик із вовка» — кулінарне завдання Альянсу, яке дає Шеф-кухар Ґруал у Таверні «Багряний Крук» у Даркширі. Ґруал хоче приготувати фірмову страву закладу й доручає шукачам пригод уполювати диких вовків у Сутінколіссі та принести рідкісні приправні трави з квіткової крамниці в Стормвінді. Завдання показує щоденні виклики виживання й винахідливість, без яких не нагодувати обложене селище.",h="«Пряний шашлик із вовка» — кулінарне завдання Альянсу, яке дає Шеф-кухар Ґруал у Таверні «Багряний Крук» у...",kw={"пряний шашлик із вовка","шеф-кухар ґруал","фелісія ґамп","вовки","кулінарія","даркшир"},ang={["class:Hunter"]="Вистежувати ненажерливі вовчі зграї Сутінколісся — класичне мисливське ремесло: так ви захищаєте селище й водночас поповнюєте комору таверни.",["faction:Alliance"]="Доставка між Даркширом і Стормвіндом показує, як відрізані поселення королівства покладаються на столичні ринки, навіть коли військових гарнізонів їм не дають.",["profession:Cooking"]="Рецепт Шеф-кухаря Ґруала вчить, як мисливці в глушині використовують жорстке м'ясо хижаків, приглушуючи дикий присмак вишуканими міськими прянощами."},sec={{t="Страва для Даркшира",b="Даркшир — відрізане поселення серед жахіть Сутінколісся, куди рідко заходять торговельні каравани, а звичайне хліборобство цілком занепало. Попри вічний морок і причаєну нежить, містянам однаково треба їсти. Шеф-кухар Ґруал, що порядкує на кухні Таверни «Багряний Крук», з користю обертає небезпечну лісову живність на харч: м'ясо диких вовків стає в нього ситними шашликами. Місцеві ліс і ґрунт не годяться для ніжних культур, тож Ґруал покладається на особливі прянощі зі столиці, щоб жорстке лісове м'ясо стало смачним."},{t="Дорога до Стормвінда",b="Щоб завершити рецепт Ґруала, мандрівники мусять роздобути пісні стегна лютих вовків, що нишпорять Сутінколіссям, і вирушити на північ до Стормвінда. Потрібні приправні трави продає травниця й квіткарка Фелісія Ґамп, чия крамниця «Запашні Квіти» біля каналу межує з Торговим Кварталом і Старим Містом. Це доручення підкреслює тонкий зв'язок Даркшира з рештою королівства: королівська військова допомога зійшла нанівець, але дрібні громадські зв'язки й шляхи постачання між міськими купцями й віддаленими селищами ще ледве тримаються."}},faq={{q="Хто такий Шеф-кухар Ґруал?",a="Шеф-кухар Ґруал — міський кухар у Таверні «Багряний Крук» у Даркширі. Він годує гостей, місцевих і бійців Нічної Варти, готуючи ситні страви з будь-якої дичини, яку можна вполювати в навколишніх лісах.",al={"шеф-кухар ґруал","ґруал даркшир","хто дає пряний шашлик із вовка"}},{q="Де взяти Стормвіндські Приправні Трави?",a="Приправні трави можна придбати у Фелісії Ґамп, що тримає крамницю «Пахучі Квіти» в Стормвінді. Її крамниця — на стежці вздовж каналу між Торговим Кварталом і Старим Містом.",al={"місце стормвіндських трав","де феліція ґамп","де приправні трави"}},{q="Де водяться вовки для вовчих боків?",a="Дикі вовки блукають темними лісами Сутінколісся, особливо в гаях і на стежках одразу за Даркширом. Будь-який місцевий вовк дасть пісне м'ясо, потрібне Шеф-кухареві Ґруалу.",al={"де пісні боки вовків","вовчі боки сутінковий ліс","де полювати на вовків"}},{q="Чому Даркширу потрібне вовче м'ясо для їжі?",a="Поля Сутінколісся зруйновані й відрізані потворами, тож тримати худобу чи вирощувати збіжжя майже неможливо. Місцеві виживають, полюючи на небезпечних звірів, що нишпорять за межами містечка, зокрема на всюдисущих вовків.",al={"чому їсти вовків","харчування даркширу","чому шашлик із вовка"}},{q="Чому Ґруал не може роздобути трави в самому Сутінколіссі?",a="Всеосяжне прокляття, що нависло над Сутінколіссям, зіпсувало чимало місцевих рослин, тож їстівних чи запашних кухонних трав майже не лишилося. Ґруалові доводиться приправляти страви садовими травами, привезеними зі Стормвінда.",al={"чому купувати трави в стормвінді","трави сутінкового лісу"}},{q="Чи пов'язане це завдання з більшою історією?",a="Це окреме місцеве завдання з колоритом, а не частина великого сюжету. Але воно яскраво показує простий, самостійний побут мешканців Даркшира та їхній крихкий шлях постачання зі Стормвінда.",al={"чи шашлик із вовка важливий","значення пряного шашлика"}}},fp="20,399,20.603.0,21.527.0,18.221.0,47.194.0,47.192.0,43.244.0,46.232.0,44.221.0"}
P.entries["quest:900"] = {n="Самофланж",s="Це завдання вимагає вимкнути хитромудру машинерію, що живить бурові роботи Венчурної Компанії на півночі Пусток. Перекривши три окремі клапани керування, шукачі пригод можуть безпечно знеструмити центральну установку. Перекриті клапани зупиняють мінливий потік палива й тиску, що тримає машину в дії.",h="Це завдання вимагає вимкнути хитромудру машинерію, що живить бурові роботи Венчурної Компанії на півночі...",kw={"самофланж","клапани","венчурна компанія","багниста драговина","пульт керування","інженерія"},ang={["faction:Horde"]="Зупинка машин Венчурної Компанії вберігає північні Пустки від неконтрольованого промислового виснаження.",["profession:Engineering"]="Інженери впізнають класичну гоблінську конструкцію: надпотужні, нестабільні паливні лінії з мінімумом автоматичних запобіжників, які доводиться перекривати вручну, щоб уникнути катастрофічного зворотного удару тиску."},sec={{t="Приборкати установку",b="Машинерія Венчурної Компанії на Багнистому Болоті настільки ж небезпечна, наскільки й складна. Біля центрального пульта керування циферблати й індикатори ясно показують, що головний механізм не вимкнеш простим клацанням перемикача. Щоб уникнути вибуху чи поломки, спершу треба вручну впоратися з лініями подачі."},{t="Три клапани",b="Потік до установки регулюють три окремі клапани: головний клапан керування, паливний клапан керування й клапан-регулятор. Кожен треба вручну перекрити проти високого тиску. З кожним закритим клапаном сяйливі індикатори на пульті змінюють колір із зеленого на жовтий, і зрештою можна безпечно ввімкнути центральний вимикач."}},faq={{q="Навіщо перекривати ці клапани?",a="Пульт стежить за трубами тиску й пального, що йдуть до машини. Якщо спробувати вимкнути апарат із відкритими трубами, можна пошкодити установку чи спричинити лихо, тож спершу треба перекрити паливну, регулювальну й головну магістралі.",al={"навіщо закривати клапани","призначення клапанів самофланжа","що роблять клапани"}},{q="Що буде, коли всі три клапани закрито?",a="Закриті клапани знижують внутрішній тиск і перекривають пальне. Блимаючі вогники на пульті тьмяніють і з зелених стають жовтими, і головний вимикач нарешті вільно зрушує.",al={"лампи пульта","що після закритих клапанів"}},{q="Хто збудував цю машину?",a="Апарат збудувала Венчурна Компанія — безжальний гоблінський торговий картель, що видобуває нафту й сировину на півночі Пусток.",al={"хто зробив самофланж","машина венчурної компанії"}},{q="Де клапани?",a="Три клапани розташовані просто довкола центрального пульта керування й головних механізмів на розкопках Венчурної Компанії в Пустках.",al={"місце клапанів","де клапани"}},{q="Чому Орду цікавить цей пристрій?",a="Важка промисловість Венчурної Компанії нищить Пустки й зазіхає на землі Орди. Зрозумівши й зруйнувавши їхню техніку, можна приборкати їхній руйнівний визиск.",al={"чому орду цікавить пристрій","самофланж орда"}},{q="Що таке самофланж?",a="Самофланж — заплутана технічна гоблінська деталь, як саме вона працює всередині, мало хто, крім інженерів, розуміє, але, схоже, без неї не обходиться бурове обладнання високого тиску.",al={"значення самофланжа","що таке самофланж"}}},fp="11,332,20.338.0,16.339.0,49.249.0,46.213.0,23.146.0,29.146.0,43.176.0,22.189.0"}
P.entries["quest:901"] = {n="Самофланж",s="Це завдання — вирішальний крок до вимкнення машинерії Венчурної Компанії на Багнистому Болоті на півночі Пусток. Уже перекривши навколишні клапани, посланець мусить здобути ключ від пульта у Винахідника Сніґґлза, щоб відкрити головний блок керування й вийняти загадковий самофланж.",h="Це завдання — вирішальний крок до вимкнення машинерії Венчурної Компанії на Багнистому Болоті на півночі...",kw={"самофланж","винахідник сніґґлз","ключ від пульта","венчурна компанія","багниста драговина","інженерія"},ang={["faction:Horde"]="Диверсія проти обладнання Венчурної Компанії на Багнистому Болоті допомагає стримати виснаження краю й отруйні стоки на півночі Калімдору.",["profession:Engineering"]="Делікатний процес, коли спершу манометри установки переводять у стан спокою, а вже тоді відкривають корпус, показує звичайні, хоч і чудернацькі, гоблінські правила механічної безпеки."},sec={{t="Відімкнути механізм",b="Перш ніж головну деталь можна буде фізично вийняти, машинерію треба повністю знеструмити й відімкнути. Коли допоміжні клапани перекрито, а тиск стравлено, циферблати й манометри термінала завмирають у стані спокою. Проте сам корпус лишається надійно замкненим від диверсій, і відімкнути його можна лише ключем, який носить головний гоблінський інженер бурової ділянки."},{t="Винахідник Сніґґлз",b="Венчурна Компанія покладається на Винахідника Сніґґлза, що пильнує тонку рівновагу її промислового обладнання на Багнистому Болоті. Сніґґлз носить ключ від пульта при собі й мешкає в хатині трохи на північний схід від головної установки. Здолати інженера — остання перешкода між посланцем і самофланжем, захованим у корпусі."},{t="Знеструмлення",b="Ключ Сніґґлза, повернутий у пульті, відмикає замкнений корпус. Останнє клацання — і червоний сигнальний вогник на рамі згасає, а залишкове електричне гудіння цілком стихає. Запобіжники пульта вимикаються, і внутрішнє осердя стає доступним."}},faq={{q="Де знайти Винахідника Сніґґлза?",a="Винахідник Сніґґлз — у невеликій гоблінській хижі трохи на північний схід від головного пульта керування на Багнистому Болоті на півночі Пусток.",al={"знайти сніґґлза","місце сніґґлза","де винахідник сніґґлз"}},{q="Для чого Ключ від Консолі?",a="Ключ від Консолі відмикає головний пульт керування на Багнистому Болоті й знеструмлює систему, щоб можна було вийняти самофланж усередині.",al={"навіщо ключ від консолі","що відкриває ключ","як користуватися ключем"}},{q="Чому пульт треба було вимкнути, перш ніж застосовувати ключ?",a="Машину спершу треба було перевести в стан спокою, стравивши клапани апарата. Відмикати й чіпати механізми під повним робочим тиском було б небезпечно.",al={"чому спершу вимкнути","клапани перед ключем"}},{q="На кого працює Винахідник Сніґґлз?",a="Винахідник Сніґґлз — інженер на службі Венчурної Компанії, безжального торгового й видобувного об'єднання, що плюндрує північ Пусток.",al={"фракція сніґґлза","чи сніґґлз з венчурної компанії"}},{q="Що таке самофланж?",a="Самофланж — незрозуміла, складна інженерна деталь, без якої не працюють важкі бурові й насосні машини Венчурної Компанії.",al={"що означає самофланж","що таке самофланж"}},{q="Що буде, коли застосувати ключ до пульта?",a="Відімкнений пульт цілком знеструмлюється, тривожні вогники гаснуть, і ви можете дістати сам самофланж.",al={"що далі","після ключа від консолі"}}},fp="11,304,23.388.0,17.362.0,11.283.1,35.140.0,33.155.0,62.185.0,36.154.0,22.145.0,48.138.0"}
P.entries["quest:902"] = {n="Самофланж",s="Це завдання — кульмінація розслідування щодо машинерії Венчурної Компанії на півночі Пусток. Знешкодивши захист системи й вимкнувши пульт керування, ви виймаєте сам невловимий самофланж і несете його до Раджета на оцінку. Він виявляється куди примхливішим і крихкішим, ніж будь-хто міг передбачити.",h="Це завдання — кульмінація розслідування щодо машинерії Венчурної Компанії на півночі Пусток.",kw={"самофланж","спаттервалв","спілка винахідників","раджет","венчурна компанія","андермайн"},ang={["faction:Horde"]="Справи з гоблінськими портами на кшталт Раджета означають і роботу з мінливим брухтом Венчурної Компанії — нагадування місцевим шукачам пригод з Орди, що нейтральне гоблінське підприємництво часто йде в парі з вибуховою незграбністю."},sec={{t="Видобути осердя",b="За лицьовою панеллю пульта Венчурної Компанії ховається спантеличливе плетиво дротів, безцільних трубок і химерних інженерних рішень. Глибоко в цьому механічному лабіринті лежить головна деталь, що спантеличила інженерів усього краю, — самофланж. Один рішучий ривок — і пристрій вискакує з гнізда, готовий постати перед гобліном, який і затіяв увесь цей пошук."},{t="Крихкі винаходи",b="Повернувшись до Раджета, Спаттервалв охоче забирає дивний пристрій і обіцяє переслати його до штаб-квартири Спілки Винахідників в Андермайні на ретельне вивчення. Та гоблінська цікавість бере гору. Щойно він кладе самофланж, щоб нетерпляче глянути на нього, тендітний механізм миттю розбивається об підлогу, і Спаттервалвові лишається гарячково рятувати дослідження."}},faq={{q="Що ж насправді таке самофланж?",a="Навіть для досвідчених механіків самофланж — незбагненне плетиво дротів, трубок і дивних дрібничок. Нібито він — головний вузол у пульті керування Венчурної Компанії, але ні Спаттервалв, ні ті, хто його здобуває, так до кінця й не розуміють, як він працює.",al={"що таке самофланж","призначення самофланжа","що він робить"}},{q="Навіщо Спаттервалвові самофланж?",a="Спаттервалв збирається відправити деталь на південь через Велике Море, до штабу Спілки Винахідників в Андермайні. Тамтешні гоблінські винахідники славляться тим, що розбирають і вивчають чужі технічні розробки — якщо, звісно, пристрій протримається до огляду.",al={"навіщо спаттервалву","хто хоче самофланж"}},{q="Що станеться, коли віддати самофланж?",a="Sputtervalve intends to send the samophlange to the Tinkers' Union in Undermine, though he is curious to inspect it himself first.",al={"чи самофланж зламається","що робить спаттервалв із ним"}},{q="Хто збудував пульт, у якому був пристрій?",a="Пульт і самофланж збудувала Венчурна Компанія, що діє з Багнистого Болота на півночі Пусток. Її роботи горезвісні абиякими, вкрай брудними технічними експериментами.",al={"хто зробив самофланж","творець консолі"}},{q="Куди Спаттервалв посилає мене після цього?",a="The investigation continues with Sputtervalve's associate Wenikee Boltbucket, another engineer in the Barrens.",al={"наступне завдання після самофланжа","що робити далі"}},{q="Де знайти Спаттервалва?",a="Спаттервалв стоїть на причалах і працює в майстернях портового містечка Раджет на східному узбережжі Пусток.",al={"місце спаттервалва","де спаттервалв","де здати самофланж"}}},fp="11,355,19.396.0,19.390.1,31.276.0,43.273.0,48.130.1,49.215.0,44.110.1,30.137.0"}
P.entries["quest:903"] = {n="Хижаки Пусток",s="«Хижаки Пусток» — мисливський обряд від Серґри Даркторн на Перехресті. У межах низки випробувань бойової вправності мисливцям доручено вистежити хижих нишпорок савани, що ховаються у високій степовій траві. Принесені кігті доводять, що мисливець гідний зустрітися з найбільшими звірами рівнин.",h="«Хижаки Пусток» — мисливський обряд від Серґри Даркторн на Перехресті.",kw={"хижаки пусток","нишпорка савани","серґра даркторн","кігті нишпорки","ечеякі","мисливець"},ang={["class:Hunter"]="Вистежування нишпорок савани у високих чагарниках — важливий вишкіл у читанні слідів, розпізнаванні прихованих звірів і приборканні лютих котячих хижаків.",["faction:Horde"]="Приборкання дикої місцевості довкола Перехрестя забезпечує безпечний прохід обозам із припасами, що курсують між Дуротаром, Малгором і південними заставами.",["race:Tauren"]="Хоч це й кривава справа, винищення хижаків-одинаків шанує природну рівновагу й захищає вразливі каравани, що перетинають родові мисливські угіддя."},sec={{t="Справжній хижак",b="Довівши свою вправність у сутичках із лякливими степовими довгоступами й упертими жеврами рівнин, мисливці, що прагнуть схвалення Серґри Даркторн, зустрічаються зі смертоноснішим викликом. Нишпорки савани — верховні скрадачі центральних Пусток, що зливаються із золотавими й вохристими чагарниками на південний захід від Перехрестя. На відміну від стадних травоїдів, ці великі коти полюють свідомо: влаштовують засідки у високій траві й перетворюють необачних мандрівників на жертв."},{t="Хижак чи здобич",b="Серґра Даркторн наголошує на ризику полювання на звірів, для яких полювання — ремесло. Щоб здобути їхні лапи й кігті, шукач пригод мусить навчитися читати траву й ударити раніше, ніж кіт стрибне. Сім здобутих кігтів нишпорки доводять, що мисливець має досить хитрості й швидкої реакції, щоб вижити в сутичках із найсмертоноснішою звіриною Калімдору."},{t="Крок до поборника",b="Повернення з пригорщею кігтів підтверджує, що мисливець опанував основи виживання на відкритій савані. Задоволена бойовою вправністю, Серґра готує мисливця до випробування справжньої доблесті — викликати й убити Ечеякі, білого лева, якого шанують як поборника серед хижаків Пусток."}},faq={{q="Хто доручає це полювання?",a="Це полювання доручає Серґра Даркторн, досвідчена мисливиця-орчиха на Перехресті в Пустках, як частину традиційної низки мисливських обрядів.",al={"видавець завдання","хто дає хижаків пусток","серґра даркторн"}},{q="Де водяться саванні скрадачі?",a="Вони крадуться високою травою на південний захід від Перехрестя, зливаючись зі степом, де полюють на жевр і необережних мандрівників.",al={"де скрадачі","місця скрадачів","де саванний скрадач"}},{q="Яких трофеїв вимагає Серґра?",a="Мисливці мають відтяти й принести сім Кігтів Нишпорки, щоб довести, що здолали цих кішок у відкритому бою.",al={"що мені потрібно","предмети хижаків пусток","кігті"}},{q="До чого веде це полювання?",a="Убивши скрадачів, ви доводите, що готові кинути виклик Ечеякі — знаменитому білому левові Пусток.",al={"наступне завдання","що після хижаків","ечеякі"}},{q="Чому Серґра посилає мандрівників полювати на хижаків?",a="Окрім того, що проріджує небезпечних звірів, які загрожують дорогам, Серґра своїми випробуваннями перевіряє, чи розуміє мисливець рівновагу між хижаком і здобиччю, — і відсіює необачних, перш ніж ті зійдуться з більшими загрозами.",al={"чому полювати на скрадачів","мета полювання","причина"}},{q="Чи небезпечні саванні скрадачі для поселення?",a="Скрадачі рідко нападають просто на укріплені табори на кшталт Перехрестя, але вони чатують біля південних доріг і полюють на мандрівників, гінців і в'ючних тварин.",al={"чи скрадачі нападають на перехрестя","загроза перехрестю"}}},fp="23,350,15.447.0,16.349.0,28.322.1,21.161.0,40.131.0,37.102.0,28.106.1,46.204.0,50.177.0"}
P.entries["quest:905"] = {n="Люті косокігті",s="Серґра Даркторн посилає честолюбних мисливців на південь від Перехрестя, щоб кинути виклик лютим косокігтям, що скрадаються Пустками. Здобувши пір'я сонцелуских рапторів і встромивши його просто в гнізда звірів, мисливці доводять свою відвагу й здобувають повагу серед ворожої дикої глушини.",h="Серґра Даркторн посилає честолюбних мисливців на південь від Перехрестя, щоб кинути виклик лютим косокігтям...",kw={"люті косокігті","косокігті","раптори","серґра даркторн","застояна оаза","мисливець"},ang={["class:Hunter"]="Увійти в гніздове лігво хижака, що боронить свою землю, і кинути виклик його пануванню — одне з найпряміших застосувань майстерності виживання в дикій глушині Калімдору.",["faction:Horde"]="Зграї рапторів уздовж Золотого Шляху постійно загрожують важливим караванам і самотнім гінцям між Перехрестям і південними заставами.",["race:Orc"]="Випробування себе в сутичках із суворою звіриною відбиває головне оркське переконання: щоб вижити в Дуротарі й Пустках, потрібні сила, стійкість і непохитні нерви."},sec={{t="Випробування нервів",b="Для Серґри Даркторн полювання в Пустках — ніколи не просте вбивство, а тривалий обряд посвяти. Уже випробувавши мандрівників у сутичках із меншими звірами, вона доручає мисливцям розшукати лютих сонцелуских рапторів на південь від Перехрестя. Здобути їхнє пір'я — лише перше випробування. Щоб справді довести свій гарт, мисливці мусять віднести ці трофеї в саме серце рапторових земель на південний захід від Застояної Оази й осквернити їхні гнізда, показавши цілковите безстрашшя."},{t="Гнізда косокігтів",b="На південний захід від Застояної Оази, неподалік Золотого Шляху, три окремі гнізда рапторів — позначені характерними червоними, синіми й жовтими яйцями — правлять за спільні угіддя для лютих косокігтів. Заходити в ці гніздовища надзвичайно небезпечно, адже раптори люто боронять свої кладки від усього, що наближається. Покласти пір'я полеглих родичів просто в їхні кладки — незаперечна заява про владу над звірами."},{t="Загартований саваною",b="Повернення на Перехрестя після сміливої вилазки до гнізд доводить не лише бойову вправність — воно показує, що посушливі рівнини змінюють мисливця. Як зауважує Серґра, щоб вийти з рапторового лігва живим, треба чимало сирої відваги. У безжальному світі Пусток кожна сутичка або гартує молодого воїна, або лишає його кістки серед ребер кодо, розкиданих по землі."}},faq={{q="Навіщо Серґра Даркторн просить класти пір'я в гнізда рапторів?",a="Серґра Даркторн хоче, щоб ви показали найвищу перевагу й відвагу. Убиваючи сонцелуских рапторів і встромляючи їхнє пір'я просто в їхні барвисті кладки, ви доводите їхній зграї та родичам, що не боїтеся їх.",al={"чому гнізда косокігтів","навіщо пір'я в гніздах","чому осквернити гнізда"}},{q="Де гнізда косокігтів?",a="Гнізда лежать на південь від Перехрестя й на південний захід від Застояної оази, біля Золотого Шляху. Вони неподалік невеликого пагорба з величезними кістками кодо, трохи на схід від придорожнього рову.",al={"де гнізда","місце гнізд косокігтів","місце синього жовтого червоного гнізда"}},{q="Які раптори живуть у цій частині Пусток?",a="Тут водяться сонцелускі косокігті та їхні родичі. Це хитрі, агресивні хижі ящери, що полюють зграями й люто боронять свої кладки довкола Золотого Шляху й сусідніх Угідь Рапторів.",al={"види рапторів пусток","сонцелускі раптори","що таке косокігті"}},{q="Де зібрати Сонцелуске Пір'я?",a="Сонцелуске пір'я падає із сонцелуских рапторів і косокігтів, що блукають рівнинами на південь від Перехрестя й по всіх сусідніх Угіддях Рапторів аж до східних пагорбів.",al={"де взяти пір'я","випадіння сонцелуского пір'я","як отримати пір'я рапторів"}},{q="Хто така Серґра Даркторн?",a="Серґра Даркторн — досвідчена мисливиця-орчиха на Перехресті. Вона оцінює новоприбулих шукачів пригод Орди, посилаючи їх на випробування по всіх Пустках, щоб перевірити їхнє чуття до виживання й бойову дисципліну.",al={"хто така серґра","переказ про серґру даркторн"}},{q="Чи веде це завдання до інших полювань?",a="Так. Це доручення — частина ширшої низки полювань Серґри Даркторн у Пустках, що завершується полюванням на Ішу Авак, легендарну морську потвору біля узбережжя Пусток.",al={"що після лютих косокігтів","ланцюжок полювань перехрестя","завдання після гнізд"}}},fp="21,296,15.502.0,20.463.0,23.435.0,70.244.0,39.184.0,55.215.0,41.176.0,24.220.0,36.177.1"}
P.entries["quest:906"] = {n="Зрада зсередини",s="«Зрада зсередини» — завдання Орди, що завершує полювання на ватажка, який стоїть за запеклими набігами Гостроманів у центральних Пустках. Принісши відтяту голову Лока Оркбейна Торкові на Перехрестя, ви доводите, що найлютіший тактик шипогривів нарешті поліг.",h="«Зрада зсередини» — завдання Орди, що завершує полювання на ватажка, який стоїть за запеклими набігами...",kw={"зрада зсередини","лок оркбейн","торк","понівечозуб","гостромани","перехрестя"},ang={["faction:Horde"]="Смерть Лока Оркбейна вбезпечує важливі шляхи між Табором Тауражо й Перехрестям і притуплює загрозу Гостроманів для нових поселень у Калімдорі.",["race:Orc"]="Прізвисько Лока — Оркбейн, тобто погибель орків, — прямо говорить про його довгу історію різанини оркських поселенців і обозів на посушливих рівнинах."},sec={{t="Голова зрадника",b="Замкнений у клітці в Таборі Тауражо, полонений шипогрив-Гостроман Понівечозуб розкриває, що жорстокими нападами шипогривів на каравани Орди керує Лок Оркбейн. Щойно ватажка вбито глибоко в південних колючих лабіринтах, Понівечозуб віддає череп Лока, потішаючись, що орки пожинатимуть плоди внутрішньої племінної зради й навіть не здогадаються, що їм допоміг полонений шипогрив."},{t="Убезпечити Перехрестя",b="Похмурий трофей Лока, принесений на північ Торкові на Перехрестя, знімає величезний тиск зі шляхів постачання Орди по всій центральній савані. Торк не може повірити, що самотній мандрівник здолав грізного ватажка, і визнає, що підозрював за злагодженими нападами зовсім іншого натхненника. Смерть Лока розколює наступ Гостроманів і кидає їхні скелясті лігва в безлад."}},faq={{q="Хто такий Понівечозуб?",a="Понівечозуб — полонений шипогрив із Гостроманів, якого тримають у дерев'яній клітці в Таборі Тауражо. Озлоблений тим, що власне плем'я його покинуло, він з помсти показує шукачам пригод Орди, як убити воєначальників свого племені.",al={"понівечозуб","полонений вепролюд","в'язень тауражо"}},{q="Ким був Лок Оркбейн?",a="Лок Оркбейн був знаним вождем у племені Гостроманів, що організовував люті набіги із засідок на застави Орди й шляхи постачання, які в'ються через Пустки.",al={"лок","лок оркбейн","ватажок гостроманів"}},{q="Чому Торкові важлива смерть Лока?",a="Як командир, що боронить Перехрестя, Торк організовує оборону від невгамовних рейдерів із тернових хащ. Знищення Лока Оркбейна прибирає головного тактика, що влаштовував напади на Золотому Шляху.",al={"чому торк хоче смерті лока","набіги на постачання перехрестя"}},{q="Чому Понівечозуб допоміг знищити власного вождя?",a="Понівечозуб глибоко озлоблений на провід свого племені й понад родинні узи шанує неприкриту силу. Допомагаючи поборникам Орди стратити Лока, він тішить свою ненависть і водночас і з-за ґрат зберігає містичний зв'язок з Аґамаґґаном.",al={"чому понівечозуб зрадив","мотив понівечозуба"}},{q="Куди веде цей ланцюжок завдань?",a="Ця здача завершує ланцюжок замахів, хоча Понівечозуб і далі обмінює стихійні благословення Аґамаґґана на Криваві Уламки, зібрані із шипогривів по всіх Пустках.",al={"наступне завдання після зради зсередини","що після зради зсередини"}},{q="Де знайти Торка?",a="Торк стоїть на варті в поселенні Перехрестя на півночі центральних Пусток і керує обороною й постачанням.",al={"місце торка","де торк"}}},fp="20,279,16.387.0,23.402.1,19.211.0,20.169.0,38.208.0,53.241.0,33.207.0,23.134.0"}
P.entries["quest:907"] = {n="Розлючені громоящери",s="«Розлючені громоящери» — мисливське випробування Орди від Джорна Скайсіра в Таборі Тауражо. У межах більшого обряду посвяти в Пустках мисливцям доручено зустрітися з величезними громоящерами, що бродять південними рівнинами, і принести їхню кров.",h="«Розлючені громоящери» — мисливське випробування Орди від Джорна Скайсіра в Таборі Тауражо.",kw={"розлючені громоящери","громоящери","кров громоящера","джорн скайсір","табір тауражо","мисливець"},ang={["class:Hunter"]="Двобій із громоящером перевіряє вашу роботу ніг: треба тримати дистанцію від нищівних тупотів і виснажувати супротивника з неймовірно товстою шкурою.",["faction:Horde"]="Винищення розлючених звірів убезпечує шляхи довкола Табору Тауражо й захищає каравани та воїнів, що мандрують південними Пустками.",["race:Tauren"]="Для шу'гало полювання на великих громоящерів довкола Табору Тауражо — традиційний вияв шани, стійкості й рівноваги на родових рівнинах."},sec={{t="Випробування південних рівнин",b="Довівши свій гарт у сутичці з раптором Ішамугале, мисливці повертаються до Табору Тауражо. Там тауренський старійшина Джорн Скайсір перевіряє, чи дасть мисливець раду масі й люті найбільших травоїдів краю. Громоящери, від яких двигтить південь Пусток, — від буремордів до громоголовів — грізні супротивники, чия важка хода може розчавити необачного."},{t="Шлях хижака",b="І для тауренських, і для оркських мисливців убити громоящера — не просто винищення, а вияв витримки, вміння вибрати позицію й сили. Джорн вимагає зразків їхньої могутньої крові як речового доказу того, що мисливець стояв просто на шляху гуркітливих велетнів і вийшов із цілими кістками. Здобутий трофей відкриває шлях до останньої здобичі Джорна — у небі."}},faq={{q="Де знайти громоящерів для цього полювання?",a="Громоящери блукають рівнинами довкола Табору Тауражо на півдні Пусток. Грозорилів, грозошкурих і громоголових можна знайти на пасовищах на північ, схід і південь від табору.",al={"місце громоящерів","де штормороти","де знайти громоящерів"}},{q="Хто посилає мене на це полювання?",a="Це завдання дає Джорн Скайсір, старійшина-мисливець із тауренів у Таборі Тауражо. Воно йде одразу після полювання на прудкого раптора Ішамугале.",al={"видавець завдання","хто дає розлючених громоящерів","джорн скайсір"}},{q="Чим громоящери особливо небезпечні?",a="Велетенська вага й електрична природа роблять їх серйозною загрозою. Вони легко розчавлять необережного мисливця ногою чи приголомшать його оглушливим тупотом, сповненим сили бурі.",al={"чому вони небезпечні","бій з громоящерами"}},{q="Що Джорн робить із зібраною кров'ю?",a="Кров — насамперед незаперечний доказ, що ви стали віч-на-віч із цими істотами й повалили їх у ближньому бою. Джорн оглядає її, щоб переконатися, що ви пережили зустріч із цими велетнями й лишилися з цілими кістками.",al={"навіщо кров громоящерів","призначення крові"}},{q="Що йде після цього завдання?",a="Принісши кров Джорнові Скайсіру, ви переходите до завдання «Крик громояструба» — наступного етапу південних мисливських випробувань, що відправляє вас по крилатих хижаків рівнин.",al={"наступне завдання","що після розлючених громоящерів"}},{q="Яке місце це посідає у випробуваннях Серґри Даркторн?",a="Серґра Даркторн починає ваші мисливські випробування на півночі Пусток біля Перехрестя — з рівнинних довгоступів, жевр і рапторів, — а тоді посилає вас на південь, до Тауражо, вчитися в Джорна Скайсіра на важчій здобичі.",al={"полювання перехрестя","ланцюжок серґри даркторн"}}},fp="23,263,29.400.0,23.401.0,51.187.0,26.143.0,50.176.0,43.214.0,28.173.0,49.218.0"}
P.entries["quest:90902"] = {n="Віднайти Світло",s="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні закликає новопіднятих паладинів Відступників знову прийняти Святе Світло. Звернення до святої сили завдає нестерпного болю плоті нежиті, тож молодим паладинам доводиться спрямовувати зцілення на поранених Вартових Смерті попри пекучі муки.",h="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні закликає новопіднятих паладинів Відступників знову...",kw={"віднайти світло","араміс гаммергенд","паладин","святе світло","зцілення","похоронний подзвін"},ang={["class:Paladin"]="Для паладина-нежиті відновити зв'язок зі Світлом — горнило віри й витривалості, доказ того, що святі обітниці здатні пережити саму смерть попри пекельний біль, який вони приносять.",["race:Undead"]="Цей обряд показує люту стійкість Відступників, які навіть пекучі муки Світла обертають на дисципліновану зброю задля свого виживання."},sec={{t="Болісне возз'єднання",b="Для колишніх поборників Срібної Длані й полеглих лицарів Лордерону пробудження в нежитті означає зіткнення з жахливою правдою: Святе Світло досі відгукується на їхній поклик, але випалює їхні зсохлі тіла зсередини. Араміс Гаммергенд пояснює новопіднятим паладинам Відступників, що вміння, колись звичні, як дихання, тепер приносять нестерпний біль. Свята енергія за своєю природою ворогує з мерзенною магією, що підтримує нежиття, тож спрямовувати Світло можна лише чистою силою волі та болісною наполегливістю."},{t="Очищення через страждання",b="Замість дозволити цим мукам зупинити себе, паладини Відступників бачать у болю тривке свідчення віри. Вартові Смерті по всьому Похоронному Подзвону зазнають тяжких поранень у боях із безтямними зомбі, і саме цим лицарям-нежиті випадає їх відновлювати. Араміс навчає, що долати пекучий біль — це як розробляти атрофований м'яз: самі муки стають відзнакою честі й живим доказом того, що Світло їх не покинуло."}},faq={{q="Чому Світло завдає болю паладинам-Відступникам?",a="Святе Світло за своєю суттю протилежне некротичній енергії, на якій тримається нежиття. Воля й переконання дають Відступникові змогу спрямовувати силу Світла, але коли ця священна енергія тече мертвою плоттю, вона завдає нестерпного пекучого болю.",al={"чому світло завдає болю нежиті","святе світло палить нежить","чому біль при зціленні"}},{q="Хто такий Араміс Гаммергенд?",a="Араміс Гаммергенд — паладин-нежить, наставник у Похоронному Подзвоні. Він веде щойно пробуджених паладинів-Відступників, допомагаючи їм заново викувати розірваний зв'язок зі Святим Світлом.",al={"хто такий араміс гаммергенд","переказ про араміса гаммергенда","видавець завдання"}},{q="Чому вартові смерті в Похоронному Подзвоні поранені?",a="Вартові смерті — вояки, що боронять Похоронний Подзвін від безтямної нежиті, здичавілих решток Погибелі й ворожих звірів, які оточують поселення, поки щойно пробуджені встають із могил.",al={"чому вартові смерті поранені","поранений вартовий смерті","оборонці похоронного подзвону"}},{q="Чи може нежить від природи володіти Святим Світлом?",a="Так, якщо зберегла віру, силу волі й пам'ять про колишні обітниці. Світло відгукується на щире переконання, хоча мертвому тілу доводиться платити за це жорстоку ціну.",al={"чи відступники можуть бути паладинами","нежить і світло","переказ про паладинів відступників"}},{q="Що Араміс має на увазі, називаючи біль знаком честі?",a="Араміс бачить у пекучих муках не прокляття, а незаперечний доказ того, що Світло досі слухає. Паладини-Відступники терплять пекучий жар своїх заклять, щоб показати свою непохитну відданість і мету.",al={"біль очищає","що значить знак честі","промова араміса"}},{q="Де відбувається це завдання?",a="Воно відбувається цілком у Похоронному Подзвоні — відлюдному стартовому притулку на південному заході Галявин Тірісфалю, де щойно підняті Відступники вперше вступають у своє існування нежиті.",al={"де це завдання","місце завдання","завдання похоронного подзвону"}}},fp="23,301,17.508.0,30.452.0,48.258.0,25.173.0,46.193.0,42.180.0,58.211.0,33.171.0"}
P.entries["quest:91"] = {n="Закон Соломона",s="Закон Соломона — місцева постанова, оголошена через Пристава Конакера в Ратуші Лейкшира. Вона засуджує гнолів Тіньової Шкури Редріджу до смерті за змову з Морґантом, ворогом Стормвінда. Шукачам пригод доручено виконати суворий вирок прикордонного правосуддя й принести амулети, зняті з гнолів.",h="Закон Соломона — місцева постанова, оголошена через Пристава Конакера в Ратуші Лейкшира.",kw={"закон соломона","пристав конакер","ратуша лейкшира","гноли Тіньової Шкури","морґант","магістрат соломон"},ang={["class:Mage"]="Морґант уособлює збочення таємного знання, оберненого на темний терор, тож його поплічники — першочергова ціль для дисциплінованих чарівників.",["class:Paladin"]="Покарати мерзенних гнолів, які з власної волі служать темному чаклунові, — відповідь на поклик нести святе правосуддя й захист обложеним прикордонним містечкам.",["faction:Alliance"]="Виконуючи постанову Соломона, ви зміцнюєте верховенство закону на східному прикордонні, де регулярних військ Стормвінда помітно бракує."},sec={{t="Прикордонне правосуддя в Лейкширі",b="Лейкшир здебільшого відрізаний від безпосередньої військової підтримки Стормвінда, тож Магістрат Соломон і міські урядники змушені правити Редріджем із суворою прикордонною рішучістю. Зі своєї ратуші Пристав Конакер діє як правиця місцевого магістратського суду. Коли містечку загрожують зовнішні вороги, суд не має іншої ради, як призначати нагороди за голови злочинців, покладаючись на вільних найманців і мандрівних захисників, щоб утримати закони королівства."},{t="Допомога ворогові Корони",b="Юридичною підставою для винищення клану гнолів Тіньової Шкури є їхній союз із Морґантом — чаклуном-ренегатом, що засів у східних пагорбах. За законами Лейкширу й королівства Стормвінд, пряма допомога оголошеному ворогові королівства неминуче карається смертю. Гноли активно виконують волю Морґанта, тож суд вважає їх не просто дикими падальниками, а зрадниками, що воюють проти корони й підлягають страті."}},faq={{q="Хто такий Соломон і що за його закон?",a="Соломон — це Магістрат Соломон, цивільний очільник Лейкшира. «Закон Соломона» — його місцеві укази й закони Стормвінда, за якими допомога оголошеному злочинцеві королівства — державна зрада, що карається смертю.",al={"хто такий соломон","значення закону соломона","що таке закон соломона"}},{q="Хто такий Морґант і чому він непокоїть Лейкшир?",a="Морґант — маг-відступник, що живе в східних передгір'ях Редріджу. Оголошений ворогом Стормвінда, він мерзенною магією тероризує місцевих жителів і підкорив своїй темній волі гнолів Тіньової Шкури.",al={"хто такий морґант","історія морґанта","чому морґант небезпечний"}},{q="Чому полюють саме на гнолів Тіньової Шкури?",a="Гноли завжди небезпечні для місцевих поселенців, але клан Тіньової Шкури перейшов просто на службу темному чаклунові Морґанту. Цей відкритий союз за міським указом робить їх законною ціллю для страти.",al={"чому вбивати тіньових шкур","гноли тіньової шкури реджридж","чому гноли мішень"}},{q="Для чого кулони?",a="Кулони, які носять гноли Тіньової Шкури, — доказ їхньої смерті. Пристав Конакер вимагає від шукачів пригод здати десять таких кулонів, щоб засвідчити виконання вироку суду, перш ніж виплатити нагороду.",al={"чому кулони тіньових шкур","призначення кулонів","кулони як доказ"}},{q="Де Пристав Конакер веде свої справи?",a="Пристав Конакер працює в Ратуші Лейкшира поряд із Магістратом Соломоном та іншими урядовцями, що відають справами Редріджу.",al={"місце конакера","де пристав конакер","суд лейкширу"}},{q="Чому Стормвінд не надсилає королівських солдатів, щоб із цим розібратися?",a="Королівство Стормвінд розпорошило сили й нині потерпає від політичного паралічу й заворушень на своїх землях. Прохання Лейкшира про військове підкріплення раз у раз лишаються без уваги, тож Магістратові Соломону доводиться наймати шукачів пригод.",al={"де армія стормвінда","чому немає вартових для гнолів","стормвінд покинув лейкшир"}}},fp="13,319,29.490.0,28.461.0,35.248.0,54.227.0,56.212.0,26.220.0,49.150.0,60.260.0"}
P.entries["quest:91208"] = {n="Прийняти і відпустити",s="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні доручає новопіднятим паладинам простягнути руку побратимці-лицарці, яка не може змиритися з нежиттям. Утікши в жаху до пагорбів, щойно повернута воїтелька стикається з болісним усвідомленням: вона стала тим, із чим колись боролася.",h="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні доручає новопіднятим паладинам простягнути руку...",kw={"прийняти і відпустити","араміс гаммергенд","паладин","божевілля","пагорби","похоронний подзвін"},ang={["class:Paladin"]="Це завдання б'є в саме серце дилеми паладина в нежитті: зіткнутися з жахом того, що ви стали тим, що присягалися винищувати.",["race:Undead"]="Психологічна ціна пробудження у Тірісфалі ламає чимало умів; мати справу з тими, кого поглинула паніка, — трагічна дійсність раннього життя Відступників."},sec={{t="Гірке воскресіння",b="Пробудження зі смерті в лавах Відступників приголомшує будь-кого, та для колишніх паладинів Срібної Длані удар особливо глибокий. Присвятивши смертне життя винищенню нежиті в служінні Святому Світлу, ці люди раптом виявляють, що їхні душі знову прив'язані до розкладеної плоті. Хтось пристосовується під наставництвом Араміса Гаммергенда, а когось переповнюють жах і сум'яття, і вони тікають у нетрі Тірісфалю, замість зустріти своє похмуре нове існування віч-на-віч."},{t="Милосердне звільнення",b="Араміс Гаммергенд сподівається, що побратим-лицар зуміє достукатися до паладинки, яка в паніці сховалася в пагорбах на захід від каплиці, — зі співчуттям і розумінням. На жаль, тягар переміни доводить її до цілковитого божевілля. Коли до неї підходять, вона сліпо кидається в бій зі страху й люті, не лишаючи вибору, крім як убити її. Для тих Відступників, чий розум розбивається вже на могилі, швидкий кінець — єдине милосердя, що лишилося."}},faq={{q="Хто така налякана паладинка?",a="Це щойно пробуджена Відступниця, що за життя була паладинкою. Охоплена жахом, коли прокинулася нежиттю, вона в цілковитій паніці втекла з Похоронного Подзвону в сусідні західні пагорби.",al={"хто налякана паладинка","паладинка в пагорбах","кого знайти в прийняти і відпустити"}},{q="Чому налякана паладинка нападає?",a="Прокинувшись саме тією істотою, з якою колись воювала, вона нажахана й не може прийняти своє нове існування. Араміс попереджає, що деякі щойно пробуджені паладини стають буйними, і просить підійти до неї зі співчуттям.",al={"чому налякана паладинка вороже","чому нападає","чи можна врятувати паладинку"}},{q="Хто дає завдання «Прийняти і відпустити»?",a="Це доручення дає Араміс Гаммергенд, наставник паладинів біля церкви в Похоронному Подзвоні, щойно пробудженим лицарям, яким треба зрозуміти крихкий душевний стан своїх воскреслих побратимів.",al={"видавець прийняти і відпустити","завдання араміса гаммергенда","де почати прийняти і відпустити"}},{q="Чи можуть Відступники досі володіти Світлом?",a="Так. Пробуджені паладини на кшталт Араміса Гаммергенда досі служать Світлу, і він сподівається привести до нього й щойно пробуджених паладинів.",al={"паладини нежиті світло","чи відступники-паладини користуються світлом","нежить і світло"}},{q="Де знайти налякану паладинку?",a="Вона втекла просто на захід від церкви в Похоронному Подзвоні й ховається серед лісистих пагорбів над поселенням.",al={"місце наляканої паладинки","де вона","де в похоронному подзвоні"}},{q="Що буде після завдання «Прийняти і відпустити»?",a="Ви повертаєтеся до Араміса Гаммергенда й розповідаєте, як намагалися допомогти наляканій паладинці. Тоді він скеровує вас на подальше навчання, щоб відточити вашу дисципліну паладина-Відступника.",al={"наступне завдання прийняти і відпустити","після прийняти і відпустити"}}},fp="15,283,21.505.0,18.425.1,30.189.0,39.223.1,36.188.0,35.129.0,40.111.0,46.180.1"}
P.entries["quest:91209"] = {n="Продовжуй навчання",s="Це завдання велить новопіднятим паладинам Відступників залишити Похоронний Подзвін і вирушити до Брілла по поглиблене навчання. Доручена Арамісом Гаммергендом подорож знайомить молодого святого воїна з ширшими небезпеками Галявин Тірісфалю. Вона також суворо попереджає про глибоку підозру, з якою нежить ставиться до носіїв святої сили.",h="Це завдання велить новопіднятим паладинам Відступників залишити Похоронний Подзвін і вирушити до Брілла по...",kw={"продовжуй навчання","араміс гаммергенд","шарі стілвелл","паладин","брілл","похоронний подзвін"},ang={["class:Paladin"]="Для паладина-нежиті цей перехід — тверезе нагадування: володіння святою силою робить вас чужинцем навіть серед побратимів-Відступників.",["race:Undead"]="Завдання висвітлює внутрішню напругу в суспільстві Відступників, де вірність землі Лордерону стикається з незагоєною травмою, пов'язаною зі Святим Світлом."},sec={{t="Вихід із Похоронного Подзвону",b="Щойно пробуджена душа опановує ази бою й спрямування святої сили в замкненому цвинтарі Похоронного Подзвону, Араміс Гаммергенд відсилає її на схід, у ширші простори Галявин Тірісфалю. Мета — Брілл, жвава застава краю, що править за адміністративний осередок центрального Тірісфалю. Там Шарі Стілвелл наглядає за поступом тих, хто наважився йти шляхом паладина в нежитті."},{t="Хистке покликання",b="На прощання Араміс дає пораду, яка підкреслює непросту дійсність паладина-нежиті. Лордерону досі потрібні захисники від зовнішніх загроз, та володіння Святим Світлом під знаменом Сильвани Віндраннер викликає гірку підозру. Незліченні Відступники зазнали мук або смерті від рук святих фанатиків, тож сама присутність Світла породжує недовіру серед їхніх побратимів по нежитті."}},faq={{q="Хто дає це завдання і де його знайти?",a="Завдання дає Араміс Гаммергенд, наставник паладинів у Похоронному Подзвоні на Галявинах Тірісфалю.",al={"хто дає завдання","з чого почати","місце араміса гаммергенда"}},{q="Де здати завдання «Продовжуй навчання»?",a="Завдання здають Шарі Стілвелл, наставниці паладинів у містечку Брілл, трохи на схід головною дорогою від Похоронного Подзвону.",al={"де здати продовжуй навчання","місце шарі стилвелл","місце здачі"}},{q="Чому Відступники не довіряють паладинам?",a="Багато Відступників глибоко ображені на Святе Світло — і через муки, яких воно завдає тілу нежиті, і через жорстокі переслідування з боку святих орденів на кшталт Багряного Хрестового Походу. Обираючи шлях паладина, Відступник опиняється незатишно близько до сил, яких більшість нежиті боїться чи зневажає.",al={"чому нежить не довіряє паладинам","упередження до паладинів відступників","близькість до світла"}},{q="Чи може взяти це завдання Відступник будь-якого класу?",a="Ні. Це завдання — саме вступний перехід для паладинів-Відступників, що вирушають зі стартових земель Похоронного Подзвону в ширший світ, до Брілла.",al={"чи це завдання лише паладина","вимога класу"}},{q="Що таке Брілл?",a="Брілл — важливе містечко в центрі Галявин Тірісфалю, головний осередок для мандрівників, вартових і ремісників із Відступників, трохи на північ від руїн над Андерсіті.",al={"що таке брілл","переказ про брілл"}},{q="Які загрози нависли над Лордероном, за словами Араміса?",a="Хоч Лордерон і зруйнований, йому постійно загрожують шалені рештки Погибелі, ворожі звірі й мстиві угруповання живих на кшталт Багряного Хрестового Походу.",al={"загрози лордерону","чому захищати лордерон"}}},fp="22,342,18.436.0,20.392.0,46.111.0,42.137.0,38.288.0,39.160.0,14.155.0,53.166.0"}
P.entries["quest:913"] = {n="Крик громояструба",s="«Крик громояструба» — вінець мисливських випробувань Джорна Скайсіра на півдні Пусток. За дорученням старійшин Табору Тауражо мисливець мусить розшукати крилатого змія, що ширяє над чагарниками, і принести його крила на доказ своєї влади над найлютішими звірами савани.",h="«Крик громояструба» — вінець мисливських випробувань Джорна Скайсіра на півдні Пусток.",kw={"крик громояструба","громояструб","крила громояструба","джорн скайсір","табір тауражо","мисливець"},ang={["class:Hunter"]="Здолати повітряного змія на кшталт громояструба — перевірка вашої дисципліни в стрільбі й терпіння, офіційний обряд посвяти в справжню майстерність рівнин.",["faction:Horde"]="Приборкання й убезпечення небезпечного рубежу довкола Табору Тауражо гарантує безпеку мандрівникам Орди, що йдуть головним шляхом через Пустки.",["race:Tauren"]="Для шу'гало вистежування громояструба в небі — священне випробування шани й честі, що доводить уміння мисливця єднатися з найпрудкішими дітьми Земної Матері й мірятися з ними силою."},sec={{t="Вінець випробування",b="Довівши свій гарт у сутичках зі степовими довгоступами, нишпорками й розлюченими громоящерами, мисливці в Пустках отримують від Джорна Скайсіра останній виклик. Громояструб вважається одним із найлютіших повітряних хижаків, що живуть у чагарниках довкола Табору Тауражо. Щоб убити його, потрібні терпіння, влучне око й чуття неба, яким мало хто з наземних хижаків може похвалитися."},{t="Шлях мисливця",b="Повернення з крилами громояструба завершує науку новачка під пильним оком Табору Тауражо. Для тауренів полювання — не просто вбивство, а безперервний духовний шлях у злагоді із Земною Матір'ю та природним ладом дикої природи. Здолавши таке горде створіння, мисливець показує, що діє із силою, відвагою й честю, — чеснотами, без яких не варто вирушати в суворіші глушини за межами центральних рівнин."}},faq={{q="Що таке громояструб?",a="Громояструби — крилаті хижаки зі зміїними тілами, що живуть у Пустках. Вони ширяють над посушливими рівнинами, полюючи згори на дрібнішу здобич, і завдяки блискавичним ударам і спритності в повітрі панують у небі довкола Табору Тауражо.",al={"що таке громояструби","істота громояструб","літаючий змій пусток"}},{q="Хто дає це завдання?",a="Це випробування дає Джорн Скайсір, шанований мисливець-таурен із Табору Тауражо на півдні Пусток, коли ви покажете себе в сутичці з розлюченими громоящерами краю.",al={"хто починає крик громояструба","видавець завдання"}},{q="Де водяться громояструби?",a="Вони ширяють у відкритому небі й над скелястими кручами по всьому півдню Пусток, здебільшого над рівнинами обабіч доріг на північ і захід від Табору Тауражо.",al={"де знайти громояструбів","місця громояструбів"}},{q="Що для тауренів означають здобуті крила?",a="Відтяті крила — відчутний доказ чистого й шляхетного полювання. У тауренів трофеї з небезпечної здобичі показують, що мисливець здолав звіра, і водночас віддають шану гордості й люті полеглої істоти.",al={"чому приносити крила","значення крил громояструба"}},{q="Куди веде це мисливське випробування далі?",a="Пройшовши випробування Джорна Скайсіра, ви завершуєте навчання в Таборі Тауражо, і Джорн посилає вас до своєї родички, Магрен Скайсір, що вартує біля щербатих берегів півдня Пусток.",al={"що після крику громояструба","наступне завдання після громояструба"}},{q="Як це пов'язано із Серґрою Даркторн на Перехресті?",a="Це випробування — південний розділ великих мисливських обрядів, що почалися під проводом Серґри Даркторн на Перехресті. Опанувавши північних звірів, обдарованих мисливців посилають на південь, до Табору Тауражо, вчитися далі в Джорна Скайсіра.",al={"зв'язок із серґрою даркторн","ланцюжок полювань перехрестя"}}},fp="22,295,28.413.0,15.441.0,22.232.0,21.184.0,29.153.0,51.246.0,40.196.0,60.256.0"}
P.entries["quest:914"] = {n="Ватажки Ікла",s="«Ватажки Ікла» — ключове завдання Орди від Нари Вайлдмейн на висотах Тандер Блафа. Воно посилає шукачів пригод у Печери Стогонів, щоб повалити чотирьох ватажків спотворених Друїдів Ікла й забрати їхні самоцвіти сну. Зупинити цих свавільних друїдів конче потрібно, щоб їхній зміїний кошмар не опанував Пустки назавжди.",h="«Ватажки Ікла» — ключове завдання Орди від Нари Вайлдмейн на висотах Тандер Блафа.",kw={"ватажки ікла","друїди ікла","нара вайлдмейн","самоцвіти сну","печери стогонів","наралекс"},ang={["class:Druid"]="Для друїдів-тауренів ця місія глибоко особиста. Бачити, як інші слуги природи обертають Смарагдовий Сон на отруйну пошесть, — нестерпна образа кенарійських засад.",["faction:Horde"]="Пустки — життєво важливе перехрестя між Оргріммаром, Тандер Блафом і островами Темного Спису. Дозволити фанатичній секті поклонників змій спотворювати землю — значить загрожувати стабільності всієї Орди.",["race:Tauren"]="Здоров'я Земної Матері — серцевина віри тауренів, тож неприродна скверна, що сочиться з джерел Пусток, — пряме блюзнірство проти землі, якою вони кочують."},sec={{t="Спотворене видіння",b="Архідруїд із нічних ельфів Наралекс спустився до підземних джерел Печер Стогонів із безкорисливою метою: скористатися Смарагдовим Сном, щоб повернути посушливим Пусткам буйну життєву силу. Та коли його сон пустив коріння, мрія трагічно обернулася на кошмар наяву. Послушники, що пішли з ним, утратили відданість гармонії природи, скорилися зловісним зміїним духам і взяли собі ім'я Друїдів Ікла."},{t="Чотири самоцвіти сну",b="Щоб переробити Пустки на свій гадючий едем, ватажки відколотої секти спрямовують спотворену силу сну крізь особливі осередки — самоцвіти сну. Лорд Кобран, Леді Анакондра, Лорд Пайтас і Лорд Серпентіс мають по одному такому самоцвіту. Доки ці артефакти в їхніх руках, їхній спотворювальний вплив просочуватиметься в ґрунт і води Калімдору."},{t="Полегшення в Тандер Блафі",b="Нара Вайлдмейн, що пильнує природну рівновагу з Тандер Блафа, відчуває духовні муки, які котяться з печер просто в її розум. Вистеживши чотирьох зміїних лордів і забравши в них самоцвіти, герої Орди ламають провід секти, звільняють друїдку-тауренку від докучливих кошмарів і рятують довколишні рівнини від неприродної пошесті."}},faq={{q="Хто ватажки Друїдів Ікла?",a="Секту ведуть четверо занепалих друїдів: Леді Анакондра, Лорд Кобран, Лорд Пайтас і Лорд Серпентіс. Кожен із них зрікся колишнього вчення про природу, щоб утілювати зміїну подобу й спрямовувати магію жахіття в Печерах Стогонів.",al={"імена ватажків ікла","боси печер стенань","хто веде друїдів ікла"}},{q="Що таке камені снів?",a="Камені снів — провідники, які носить кожен із чотирьох ватажків у Печерах Стогонів. Вони зосереджують спотворену, отруєну жахіттям енергію, що просочується зі сну Наралекса, і живлять намагання секти змінити Пустки.",al={"що таке камені снів","самоцвіти кобрана","переказ про камені снів"}},{q="Навіщо Нарі Вайлдмейн ці камені?",a="Нара Вайлдмейн — друїдка-тауренка з Тандер Блафа, що відчуває душевні й духовні хвилі жахіття. Обличчя зіпсованих ватажків переслідують її уві сні, і їй треба зламати їхню силу, щоб уберегти і власний розум, і майбутнє Пусток.",al={"хто нара вайлдмейн","навіщо вбивати ватажків","мотив нари вайлдмейн"}},{q="Чи Друїди Ікла завжди були лихими?",a="Ні. Спершу це були шляхетні друїди з нічних ельфів, що пішли за Наралексом у печери, сподіваючись зцілити суху савану. Коли Наралекс поринув у жахіття, його енергія спотворила їхній розум і перетворила їх на фанатичний зміїний культ.",al={"походження друїдів ікла","чому друїди стали лихими","учні наралекса"}},{q="Де здати це завдання?",a="Завдання починається й закінчується в Нари Вайлдмейн на Узвишші Старійшин у Тандер Блафі. Зібравши всі чотири камені в глибинах Печер Стогонів, вам доведеться повернутися до Малгора, щоб віддати їх їй.",al={"здати ватажків ікла","де нара вайлдмейн","віддати ватажків ікла"}},{q="Чи смерть ватажків зцілює Наралекса?",a="Вбивство чотирьох ватажків розбиває верхівку секти й зупиняє поширення їхнього обряду, але саме собою Наралекса не будить. Щоб пробудити сплячого майстра, потрібні інші друїдські обряди глибше в печерах.",al={"чи врятує це наралекса","наслідок вбивства ватажків"}}},fp="19,380,18.437.0,19.391.0,32.382.1,46.237.0,24.222.0,37.254.0,40.233.0,30.207.0,38.231.0"}
P.entries["quest:916"] = {n="Отрута Вебвуда",s="«Отрута Вебвуда» — завдання Альянсу в Тінедолі, що на Тельдрассилі. Учений Ґілшалан Віндвокер доручає юним нічним ельфам зібрати отруйні залози велетенських павуків Вебвуда, щоб дослідити, як ріст нового Світового Дерева вплинув на корінну живність.",h="«Отрута Вебвуда» — завдання Альянсу в Тінедолі, що на Тельдрассилі.",kw={"отрута вебвуда","павуки","ґілшалан віндвокер","печера тіньової нитки","тінедол","тельдрассил"},ang={["class:Druid"]="Друїди кровно зацікавлені у висновках Ґілшалана, адже розуміння того, зцілює чи спотворює Тельдрассил довколишню живність, — осердя пильності Кола Кенарія.",["race:NightElf"]="Для юних нічних ельфів, що дорослішають у Тінедолі, це завдання — ранній урок того, якою крихкою й непередбачуваною стала природа під гіллям Тельдрассила."},sec={{t="Цікавість природознавця",b="Ґілшалан Віндвокер прибув до Тінедола вивчати неприродні розміри й агресію місцевих павуків Вебвуда, що заполонили Печеру Тіньової Нитки. Він зауважує, що ці створіння — родичі куди менших видів з інших країв. Підозрюючи, що величезні магічні сили Тельдрассила спричиняють стрімкі й тривожні мутації місцевої фауни, він просить отруйні залози, щоб порівняти їхні біологічні властивості зі звичайними павуками."},{t="Нависла загроза в Тінедолі",b="Павуки Вебвуда, що живуть довкола Печери Тіньової Нитки й усередині неї, стають дедалі небезпечнішими для юних новачків нічних ельфів у долині. Збирання їхньої отрути слугує двом цілям: воно проріджує небезпечне місцеве нашестя й дає дослідникам із Дарнасуса прямі біологічні докази бурхливого впливу Тельдрассила на дику природу."}},faq={{q="Хто такий Ґілшалан Віндвокер?",a="Ґілшалан Віндвокер — дослідник із нічних ельфів біля Алдрассила в Тінедолі. Він вивчає місцевих звірів Тельдрассилу, щоб з'ясувати, як стрімкий ріст Світового Дерева впливає на тутешню природу.",al={"ґілшалан","хто дає отруту вебвуда","видавець отрути вебвуда"}},{q="Чому павуки Вебвуда такі великі?",a="Від природи вони родичі набагато менших павуків. Ґілшалан Віндвокер вважає, що стрімкий ріст і прихована магічна сила Тельдрассилу неприродно збільшили їх і спотворили їхню поведінку.",al={"гігантські павуки тельдрассила","чому павуки великі","мутації вебвуда"}},{q="Де Печера Тіньової Нитки?",a="Печера Тіньової Нитки — на півночі Тінедолу, серед кам'янистих гребенів за тренувальними майданчиками біля Алдрассила.",al={"місце печери тіньової нитки","де вебвуди","печера павуків вебвуда"}},{q="Що Ґілшалан зробить з отруйними мішечками?",a="Він збирається відвезти отруту до Дарнасуса, щоб порівняти її хімічні й магічні властивості з отрутою звичайних лісових павуків і знайти відхилення, спричинені Світовим Деревом.",al={"навіщо отруйні мішечки","дослідження отрути ґілшалана","вивчення отрути в дарнасусі"}},{q="Чи є в Печері Тіньової Нитки інші завдання?",a="Так. Збираючи отруту, шукачі пригод часто допомагають Діранії Сілвершайн неподалік урятувати Іверрона — ельфа, якого отруїли ті самі павуки в Печері Тіньової Нитки.",al={"інші павучі завдання","завдання печери тіньової нитки","завдання іверрона"}},{q="Яке завдання йде після «Отрути Вебвуда»?",a="Дослідивши отруту, Ґілшалан просить шукачів пригод принести Яйце Павука Вебвуда з глибин Печери Тіньової Нитки, щоб вивчити їхній життєвий цикл.",al={"наступне завдання отрути вебвуда","що після отрути вебвуда","продовження ґілшалана"}}},fp="13,247,24.442.0,32.357.0,28.207.0,37.205.0,27.131.0,43.185.0,44.162.0,33.152.0"}
P.entries["quest:917"] = {n="Яйце Павука Вебвуда",s="Ґілшалан Віндвокер доручає юним захисникам у Тінедолі добути невилуплене павуче яйце з глибин Печери Тіньової Нитки. Зібравши зразки отрути, він потребує живих особин, щоб дослідити неприродну агресію живності Тельдрассила. Невилуплена кладка дозволяє вченим безпечно вивчати цих створінь, не впокорюючи дорослих павуків.",h="Ґілшалан Віндвокер доручає юним захисникам у Тінедолі добути невилуплене павуче яйце з глибин Печери Тіньової...",kw={"яйце павука вебвуда","павуки","ґілшалан віндвокер","печера тіньової нитки","тінедол","дарнасус"},ang={["class:Druid"]="Вивчення яєць і отрути дає дослідникам Кола Кенарія змогу визначити, чи можна очистити зіпсуття, що змінює цих звірів, чи пошесть сягає глибше.",["race:NightElf"]="Для юних нічних ельфів добування цього яйця показує підступне зіпсуття, що охоплює Тельдрассил і змушує вчених вивчати живність рідного краю як ворожу загрозу."},sec={{t="Безпечний зразок",b="Здобувши сиру отруту агресивних павуків Вебвуда, що нишпорять околицями Тінедола, Ґілшалан Віндвокер потребує живих піддослідних, аби краще зрозуміти їхнє неприродне зіпсуття. Знаючи, що витягати з підземних глибин велетенського павука, який шалено пручається, для будь-якого новачка смертельно, Ґілшалан обирає практичніший спосіб: невилуплене яйце, взяте просто з виводкових кладок у Печері Тіньової Нитки."},{t="Шлях до столиці",b="Печера Тіньової Нитки — підземний розплідник дедалі ворожіших лісових павуків. Проникнення до печери й добування цілого яйця дає вченим контрольований зразок, що може вилупитися в ізоляції. Ґілшалан має намір спакувати яйце разом зі зразками отрути й відправити просто до Дарнасуса для подальшого вивчення — так завершується його польове дослідження, а новобранців скеровують до вищих обов'язків на гіллі Алдрассила."}},faq={{q="Чому Ґілшалан хоче яйце, а не дорослого павука?",a="Ґілшалан визнає, що зловити живого велетенського павука — надто небезпечно для недосвідченого новобранця, а втримати його самому — надто важко. Ціле, ще не вилуплене яйце дає змогу дослідникам безпечно перевезти живий зразок і підготувати утримання, перш ніж вилупиться виводок.",al={"чому яйце","чому не живого павука","навіщо яйце вебвуда"}},{q="Де знайти яйце павука Вебвуда?",a="Яйце лежить у павутинному гнізді глибоко в Печері Тіньової Нитки, що врізається в гілля й коріння на північному краю Тінедолу на Тельдрассилі.",al={"місце яйця","де яйце павука вебвуда","гніздо печери тіньової нитки"}},{q="Хто такий Ґілшалан Віндвокер?",a="Ґілшалан Віндвокер — дослідник із нічних ельфів біля Алдрассила в Тінедолі. Він розслідує раптові згубні недуги, що штовхають корінних істот Тельдрассилу до жорстокості.",al={"хто такий ґілшалан","переказ про ґілшалана"}},{q="Що буде з яйцем, коли його здано?",a="Ґілшалан готує яйце й зібрані флакони з отрутою до відправки в столицю, Дарнасус, де вчені й друїди зможуть дослідити їх у контрольованих умовах, коли його робота в Тінедолі завершиться.",al={"що ґілшалан робить з яйцем","куди йде яйце"}},{q="Що йде після цього доручення?",a="Коли яйце здобуто, Ґілшалан скеровує вас нагору Алдрассилом — відгукнутися на «Виклик Тенарона», що знайомить вас зі старшими друїдами, які опікуються серцем Тінедолу.",al={"наступне завдання після яйця вебвуда","що після яйця"}},{q="Чому павуки Вебвуда такі агресивні?",a="Павуки Тельдрассилу, як і багато тамтешніх звірів, піддаються неприродній скверні, що вкорінюється на молодому Світовому Дереві, і з колись лагідних чи байдужих звірів стають агресивними хижаками.",al={"чому павуки злі","осквернення павуків"}}},fp="11,383,15.437.0,23.476.0,58.293.0,31.150.0,28.194.0,46.214.0,38.156.0,42.204.0"}
P.entries["quest:918"] = {n="Насіння деревляників",s="«Насіння деревляників» — раннє завдання від ботаніка Деналана біля Озера Ал'Амет у Тельдрассилі. Стривожений дедалі більшою ворожістю місцевих елементалів природи, Деналан хоче зібрати їхнє насіння й перевірити, чи виростить збагачений ґрунт спокійніше, злагідніше покоління. Завдання відкриває тихі зусилля травників нічних ельфів зрозуміти ледь помітні недуги Світового Дерева.",h="«Насіння деревляників» — раннє завдання від ботаніка Деналана біля Озера Ал'Амет у Тельдрассилі.",kw={"насіння деревляників","деревляники","деналан","озеро ал'амет","ґрунт","тельдрассил"},ang={["class:Druid"]="Друїди мають глибоку спорідненість із духами природи. Допомога дослідженню Деналана береже рівновагу стихій без опори лише на криваве проріджування.",["profession:Herbalism"]="Збирачі, чутливі до флори Тельдрассила, оцінять ботанічні досліди Деналана, що вивчають тонкий зв'язок між рослинним насінням і збагаченим ґрунтом.",["race:NightElf"]="Для калдорей деревляники — прямий показник здоров'я Тельдрассила. Бачити, як ці лагідні духи дичавіють, — моторошний знак, що їхня нова домівка хвора."},sec={{t="Неспокійна природа",b="Деревляники — елементалі природи, корінні мешканці гілля Тельдрассила, нерозривно пов'язані зі здоров'ям і силою довколишньої флори. Зазвичай вони — мирне відображення лісової рівноваги, тож їхня недавня й незрозуміла ворожість стривожила місцевих нічних ельфів. Замість просто винищувати їх, ботанік Деналан сподівається зрозуміти джерело їхнього збурення."},{t="Насіння нового росту",b="Підозрюючи, що вада криється глибоко в самій землі, Деналан має намір проростити свіжих деревляників у збагаченому, дбайливо обробленому ґрунті. Збираючи насіння з деревляників, що блукають біля Озера Ал'Амет, він сподівається виплекати лагідніше покоління елементалів і з'ясувати, чи можна протидіяти зіпсуттю землі від самого коріння."}},faq={{q="Хто такі деревляники?",a="Деревляники — невеликі рослиноподібні елементалі природи, що живуть на Тельдрассилі. Вони відбивають природний лад і життєвий цикл рослин і звірів великого дерева.",al={"переказ про деревляників","хто такі деревляники","стихійці природи тельдрассила"}},{q="Чому деревляники стали агресивними?",a="Деналан підозрює якусь приховану ваду чи отруту в ґрунті Тельдрассилу. Деревляники — стихійні втілення природи дерева, тож вони відбивають скверну, що дедалі ширше розповзається островом.",al={"чому деревляники злі","ворожість деревляників","розлючені деревляники"}},{q="Хто такий Деналан?",a="Деналан — природознавець і ботанік із нічних ельфів, що доглядає невеликий сад-притулок на східному березі Озера Ал'Амет і вивчає незвичайні рослини й ґрунти Тельдрассилу.",al={"переказ про деналана","хто такий деналан","ботанік озера аль'амет"}},{q="Де зібрати насіння деревляників?",a="Деревляники блукають тінистими хащами, берегами й лісовими галявинами довкола Озера Ал'Амет у центрі Тельдрассилу.",al={"де насіння деревляників","місця деревляників","насіння озера аль'амет"}},{q="Що Деналан збирається робити з насінням?",a="Деналан хоче виростити насіння в особливих очищених ґрунтових сумішах, які сам розробив, сподіваючись отримати лагідних деревляників, вільних від неспокою лісу.",al={"що буде з насінням","план деналана","посадка насіння деревляників"}},{q="Як це пов'язано з ширшими негараздами Тельдрассилу?",a="Агресивність цих простих духів природи — одна з найперших ознак того, що Тельдрассил страждає від неприродної скверни, і це веде дослідників до глибших розслідувань у Дарнасусі.",al={"осквернення тельдрассила","чому тельдрассил хворіє","осквернення дерев"}}},fp="16,418,15.378.0,21.341.0,21.153.0,43.202.0,15.165.0,39.112.0,44.172.0,53.190.0"}
P.entries["quest:91859"] = {n="Дивна пара",s="Завдання «Дивна пара» починається, коли Треван Рол помічає незвичну двійцю, що проходить через Гробницю в Срібноліссі. Під знаменом Земляного Кільця таурен мандрував разом із високим ельфом — союз настільки рідкісний на землях Орди, що одразу викликає підозру.",h="Завдання «Дивна пара» починається, коли Треван Рол помічає незвичну двійцю, що проходить через Гробницю в...",kw={"дивна пара","треван рол","земляне кільце","високі ельфи","таурен","гробниця","вартовий смерті балдрен"},ang={["class:Shaman"]="Звістка про Земляне Кільце в товаристві ельфа незвична навіть для досвідчених шаманів, які знають, що традиції Кільця рідко пов'язані з кель'дореями.",["race:Tauren"]="Таурени-шукачі пригод можуть відчувати змішані почуття, бачачи, як їхній родич мандрує Лордероном разом з ельфом-чужинцем і привертає пильні погляди вартових-Відступників.",["race:Undead"]="Для Відступників, що стережуть Гробницю, кожен чужинець, який прослизає Срібноліссям, вимагає пильної уваги — надто за нинішнього розколотого політичного становища Лордерона."},sec={{t="Очі в Гробниці",b="Гробниця — похмура перевалочна застава, де до чужинців придивляються пильно, особливо до тих, хто заявляє про дипломатичні справи. Коли дорогою проходили двоє посланців, що називали себе членами Земляного Кільця, їх помітив місцевий розвідник Треван Рол. Таурен під плащем шаманського ордену нікого не здивував, а от його супутник у плащі з каптуром здався Відступникам украй дивним: це був безсумнівно високий ельф."},{t="Дивне товариство",b="Кель'дорей, що відкрито мандрує разом із членом шаманського кола Орди, природно, викликає питання у вартових-Відступників. Земляне Кільце зазвичай дбає про рівновагу стихій і рідко посилає високих ельфів до Лордерона — а тим паче як супутників тауренських посланців. Щоб з'ясувати, куди подалася ця незвична пара і які в неї справи в лісі, мандрівників посилають до Вартового Смерті Балдрена на краю містечка."}},faq={{q="Хто ці двоє мандрівників, про яких ідеться в завданні?",a="За словами Тревана Рола, мандрівники назвалися посланцями Земляного Кільця. Один із них — таурен, що цілком звично для цієї шаманської організації, а от його супутником виявився високий ельф, закутаний у плащ.",al={"хто дивна пара","хто пройшов крізь гробницю","хто були мандрівники"}},{q="Чому високий ельф у товаристві таурена — це так дивно?",a="Високих ельфів здавна пов'язують з Альянсом і тайною магією, а таурени — віддані члени Орди й глибокі знавці шаманства. Двоє представників цих народів, що разом під знаменом Земляного Кільця мандрують Срібноліссям, яке контролює Орда, — видовище надзвичайно рідкісне й підозріле.",al={"чому високий ельф із тауреном дивно","таурен і високий ельф"}},{q="Хто дає завдання «Дивна пара»?",a="Завдання дає Треван Рол у Гробниці — аванпості в Срібноліссі.",al={"видавець дивної пари","де взяти дивну пару"}},{q="Де знайти Вартового Смерті Балдрена?",a="Вартовий Смерті Балдрен стоїть на посту біля входу до Гробниці в Срібноліссі й наглядає за мандрівниками на дорозі.",al={"місце балдрена","де балдрен"}},{q="Що таке Земляне Кільце?",a="Земляне Кільце — давня організація шаманів, що дбає про рівновагу стихій і зцілює духовний розлад по всьому світу. Здебільшого до неї входять шамани-таурени й орки, але її посланці час від часу вирушають і в далекі краї.",al={"переказ про земляне кільце","що таке земляне кільце"}},{q="Чи ворог високий ельф Відступникам?",a="Відразу це не зрозуміло. Треван Рол зауважує, що ельф ховався під плащем і подорожував разом із тауреном під дипломатичним приводом, тож Відступники радше замислюються над їхньою метою, ніж нападають одразу.",al={"вороги чи ні","чи ельф ворог"}}},fp="14,275,21.425.0,22.473.0,50.210.0,53.314.0,36.91.0,35.136.0,25.270.0,41.206.0"}
P.entries["quest:919"] = {n="Паростки деревляників",s="«Паростки деревляників» — завдання від спостерігача за природою Деналана біля Озера Ал'Амет у центрі Тельдрассила. Стривожений раптовим і неприродним розмноженням лісових паростків на берегах озера, Деналан просить мандрівників викорінити їх, перш ніж вони виростуть у ворожих деревляників. Завдання показує перші ознаки того, що повзуче зіпсуття порушує рівновагу щойно вирослого Світового Дерева.",h="«Паростки деревляників» — завдання від спостерігача за природою Деналана біля Озера Ал'Амет у центрі...",kw={"паростки деревляників","деревляники","деналан","озеро ал'амет","зіпсуття","тельдрассил"},ang={["class:Druid"]="Друїди відповідають за тонку рівновагу природи; викорінювати уражені паростки — сумний, але необхідний обов'язок заради ширшої екосистеми.",["profession:Herbalism"]="Травники добре знають, як має рости здорова рослинність, і одразу розпізнають, що ці паростки хворі й неприродно скручені.",["race:NightElf"]="Для калдорей Тельдрассил мав стати новим прихистком, тож зіпсутий ріст біля священних вод, як-от Озера Ал'Амет, — глибоко тривожне знамення."},sec={{t="Прополювання Озера Ал'Амет",b="На тихих берегах Озера Ал'Амет дивні рослиноподібні створіння, відомі як деревляники, почали множитися з тривожною швидкістю. Замість рости в злагоді з лісом, молоді паростки деревляників виказують ознаки зіпсуття з тієї миті, як пускають коріння. Деналан, відданий учень природи, що живе біля озера, розуміє: ці паростки вже не зцілити. Якщо їх не спинити, вони швидко виростають у агресивних укритих корою створінь, що загрожують місцевій живності й необачним мандрівникам. Збирання й знищення паростків — перша лінія оборони, що тримає гай чистим."},{t="Ознаки глибшої скверни",b="Викорінення паростків допомагає впоратися з місцевою загрозою, та Деналан із жахом зауважує, як швидко вони з'являються. Їхнє нестримне розмноження — неприродне явище для Тельдрассила. Заражені паростки — не окреме нашестя, а симптом глибшої недуги, що загрожує корінню й ґрунту самого Світового Дерева, — загадка, яку Деналан і друїди Дарнасуса квапляться розгадати."}},faq={{q="Що таке паростки деревляників?",a="Паростки деревляників — це молоді, щойно зародені деревляники, невеликі рослинні елементалі, що живуть на гілках Тельдрассила. На жаль, ті, що проростають уздовж Озера Ал'Амет, уражені скверною й швидко виростають у ворожих, агресивних істот.",al={"що таке деревляники","переказ про паростки деревляників","що таке паросток"}},{q="Хто такий Деналан?",a="Деналан — травник і доглядач природи, що живе в тихому таборі біля берегів Озера Ал'Амет. Він пильнує рослинність на гілці Світового Дерева й вивчає зміни в довкіллі та дивну скверну, що поширюється Тельдрассилом.",al={"хто дає паростки деревляників","переказ про деналана","видавець озера аль'амет"}},{q="Чому ці паростки не можна просто вилікувати чи очистити?",a="Деналан помічає, що паростки вже безнадійно уражені скверною, щойно виходять на поверхню. Рятувати їх марно, тож єдиний практичний спосіб не дати їм вирости в небезпечних істот — знищувати їх.",al={"чи можна врятувати паростки","чому знищувати деревляників","чи паростки безнадійні"}},{q="Де ростуть паростки?",a="Паростки вкорінюються на мулистих берегах, мілинах і пишних узбережжях довкола Озера Ал'Амет у центрі Тельдрассила.",al={"місце паростків деревляників","де знайти паростки","паростки озера аль'амет"}},{q="Чому деревляники проростають такими агресивними?",a="Неприродний наплив ворожих деревляників спричиняє скверна, що просочується в ґрунт і води Тельдрассила. Навіть молоді пагони псуються, ще не встигнувши розквітнути, а це свідчить про глибшу пошесть, що вразила молоде Світове Дерево.",al={"чому деревляники злі","що осквернило паростки","осквернення деревляників"}},{q="Що буде після того, як паростки знищено?",a="Деналан продовжує з'ясовувати природу хвороби озера: досліджує зразки ґрунту, насіння й води, щоб відшукати корінь пошесті.",al={"наступне завдання після паростків","що після паростків деревляників"}}},fp="18,402,21.618.0,23.414.0,28.245.0,15.222.0,53.227.0,28.119.0,54.251.0,42.159.0"}
P.entries["quest:92"] = {n="Гуляш з Редріджу",s="Гуляш з Редріджу — місцева кулінарна традиція, яку підтримує Шеф-кухарка Бреанна в прибережному Лейкширі. Спустошивши комору, щоб прогодувати гарнізон Стормвінда під час нещодавніх набігів орків Блекрок, Бреанна просить мандрівних шукачів пригод поповнити запаси ситних гірських продуктів.",h="Гуляш з Редріджу — місцева кулінарна традиція, яку підтримує Шеф-кухарка Бреанна в прибережному Лейкширі.",kw={"гуляш з редріджу","шеф-кухарка бреанна","кулінарія","кондори","тарантули","лейкшир"},ang={["faction:Alliance"]="Мізерні запаси Лейкширу — промовисте нагадування про те, якої шкоди вторгнення орків Блекрок завдало місцевим гарнізонам Альянсу й мирному життю містечка.",["profession:Cooking"]="Для кулінарів, що мандрують Східними Королівствами, гуляш Шеф-кухарки Бреанни — приклад того, як винахідливі прикордонні кухарі перетворюють лютих гірських звірів на ситну й смачну страву."},sec={{t="Порожня гірська комора",b="Лейкшир постійно в облозі орків Блекрок, гнолів і лютих диких звірів. Коли на хребтах спалахнуло нещодавнє повстання орків, Шеф-кухарка Бреанна взяла на себе обов'язок годувати весь загін стормвіндських солдатів, що стояв у містечку. Утримання діючого гарнізону швидко спорожнило її полиці, і тепер у міської кухарки повно голодних ротів, але порожні комори."},{t="Гірські дари",b="Коли комора порожня, Шеф-кухарка Бреанна звертає погляд на небезпечну глушину за брамою Лейкширу. Її фірмовий гуляш потребує міцної суміші місцевого м'яса: жорсткого м'яса гірських кондорів, приправлених рил грізних великих кабанів-іклорізів і хрусткого м'яса з лап велетенських тарантулів, що нишпорять пагорбами."}},faq={{q="Чому в Шеф-кухарки Бреанни скінчилися харчі?",a="Під час нещодавнього повстання орків Блекрок Бреанні довелося годувати цілу бригаду військ Стормвінда, кинутих на оборону Лейкшира, — і її комори геть спорожніли.",al={"чому порожня комора","комора бреанни","чому немає їжі"}},{q="З чого готують Гуляш з Редріджу?",a="Для справжнього Гуляшу з Редріджу потрібні п'ять шматків Жорсткого М'яса Кондора, п'ять рил Величезного Кривавоіклого і п'ять порцій Хрусткого Павучого М'яса — усе це з тварин, що водяться в навколишніх горах.",al={"інгредієнти гуляшу","що в гуляші з редріджу","м'ясо гуляшу"}},{q="Де знайти Шеф-кухарку Бреанну?",a="Шеф-кухарка Бреанна порається біля свого вогнища й казанів у містечку Лейкшир на північному березі Озера Незрушного в Горах Редріджу.",al={"місце бреанни","де шеф-кухарка бреанна","кухарка лейкширу"}},{q="Чому Лейкшир просто не завозить їжу зі Стормвінда?",a="Гірські перевали кишать орками, загарбниками Блекрок і гнолами, а сили Стормвінда й так розпорошені, тож Лейкширу часто доводиться покладатися на місцеву дичину й заїжджих шукачів пригод.",al={"постачання стормвінда","чому не торгувати зі стормвіндом","нестача їжі в лейкширі"}},{q="Чи вважають Гуляш з Редріджу делікатесом?",a="Поєднання павучого м'яса, кабанячих рил і жилавої кондорятини чужинцям може здатися грубим, але Шеф-кухарка Бреанна й прикордонний люд Лейкшира вважають готову страву ситним гірським делікатесом.",al={"чи гуляш смачний","смачний гуляш","делікатес редріджу"}},{q="Яку бригаду мусила годувати Бреанна?",a="Бреанна куховарила для солдатів Стормвінда, розквартированих у Лейкширі, щоб відкинути орків Блекрок, які насідали з північних хребтів.",al={"бригада стормвінда","хто захищав лейкшир","війська в лейкширі"}}},fp="16,322,22.403.0,15.316.0,41.165.0,51.203.0,30.169.0,59.197.0,42.206.0,38.150.0"}
P.entries["quest:920"] = {n="Виклик Тенарона",s="«Виклик Тенарона» — важливий перелом для юних нічних ельфів у Тінедолі. Допомігши Ґілшалану Віндвокеру з місцевими лісовими небезпеками, ви одержуєте поклик піднятися на могутнє гілля Алдрассила — на розмову з Тенароном Стормґріпом. Цей виклик знаменує мить, коли новачок лишає позаду дрібні місцеві клопоти, щоб стати проти глибших духовних недуг Тельдрассила.",h="«Виклик Тенарона» — важливий перелом для юних нічних ельфів у Тінедолі.",kw={"виклик тенарона","тенарон стормґріп","ґілшалан віндвокер","алдрассил","тінедол","місячні колодязі"},ang={["class:Druid"]="З'явитися до Тенарона Стормґріпа — неодмінний крок, щоб дізнатися, як стежать за друїдською рівновагою Тельдрассила і як її підтримують.",["race:NightElf"]="Цей виклик знаменує ваше повноліття серед калдорей: від простого захисту лісу ви переходите до прямого служіння старійшинам, що доглядають Світове Дерево."},sec={{t="Поклик на гілля",b="Ваше вміння дати раду отруйним павукам і зіпсутій живності, що заворушилася в долині, не лишається непоміченим. Ґілшалан Віндвокер переказує, що сам Тенарон Стормґріп просить вас прибути. Навіть серед надзвичайно довговічних нічних ельфів змушувати старійшину-друїда чекати на вершині великого дерева Алдрассил вважається поганим тоном."},{t="Сходження на Алдрассил",b="Тенарон чекає у найвищій залі Алдрассила, споглядаючи зелене гілля Тінедола. Відгук на цей виклик веде просто до більших справ опіки: очищення місячних колодязів Тельдрассила й дослідження неприродного зіпсуття, що повзе в юну екосистему Світового Дерева."}},faq={{q="Хто такий Тенарон Стормґріп?",a="Тенарон Стормґріп — впливовий друїд нічних ельфів, що мешкає у найвищій залі Алдрассила в Тінедолі. Він дбає про духовний добробут долини й керує зусиллями зі стеження за священними водами Тельдрассила та їх очищення.",al={"хто такий тенарон","переказ про тенарона стормґріпа"}},{q="Де знайти Тенарона Стормґріпа?",a="Він у найвищій кімнаті Алдрассила — великого порожнистого дерева-міста в Тінедолі. Щоб дістатися до його оглядового місця біля крони, вам доведеться піднятися звивистими пандусами всередині дерева.",al={"знайти тенарона","місце тенарона","де тенарон"}},{q="Навіщо Тенарон мене кличе?",a="Коли ви доведете свою вартість, упоравшись зі зіпсованими скверною тваринами внизу, Тенарон доручить вам відповідальніші справи — зокрема оглянути священні місячні колодязі й перевірити їхні води на ознаки скверни.",al={"навіщо покликання","чого хоче тенарон"}},{q="Що буде після цього завдання?",a="Відгукнувшись на виклик, ви одразу переходите до ланцюжка «Корона Землі»: Тенарон доручає вам набрати води з місячних колодязів по всьому Тельдрассилу, щоб перевірити здоров'я дерева.",al={"наступне завдання","що після виклику тенарона"}},{q="Хто посилає вас до Тенарона?",a="Ґілшалан Віндвокер передає вам виклик, щойно ви допоможете йому з павуками Вебвуда, які сказилися від отрути й загрожують нижнім западинам Тінедолу.",al={"хто дає завдання","ґілшалан віндвокер"}},{q="Що таке Алдрассил?",a="Алдрассил — величезне дерево, що росте у відлюдній долині Тінедолу. Це головне поселення й навчальний притулок для молодих шукачів пригод із нічних ельфів на Тельдрассилі.",al={"переказ про алдрассил","що таке алдрассил"}}},fp="17,375,20.370.0,19.317.0,25.231.0,34.182.0,27.224.0,30.200.0,25.155.0,18.189.0"}
P.entries["quest:921"] = {n="Корона Землі",s="«Корона Землі» — вступний обряд від Тенарона Стормґріпа високо в Алдрассилі. Юних нічних ельфів, що готуються вийти за межі Тінедола, посилають набрати священної води з сусіднього місячного колодязя й зустрітися з болісною історією гори Гіджал і втраченого безсмертя їхнього народу.",h="«Корона Землі» — вступний обряд від Тенарона Стормґріпа високо в Алдрассилі.",kw={"корона землі","тенарон стормґріп","місячний колодязь","гора гіджал","нордрассил","безсмертя","алдрассил"},ang={["class:Druid"]="Місячні колодязі — неодмінне знаряддя Кола Кенарія: вони дають очищені провідники сили природи, конче потрібні для підтримання лісової рівноваги.",["class:Priest"]="Присвячені Елуні місячні колодязі — святині для роздумів, де води освячує погляд Матері-Місяця.",["race:NightElf"]="Цей обряд знаменує ваш вихід із Тінедола й пов'язує вашу особисту долю з жертвою на вершині гори Гіджал і з відповідальністю за Тельдрассил."},sec={{t="Урок недавньої історії",b="Перш ніж будь-який шукач пригод-початківець покине затишне гілля Тінедола, старійшини дбають, щоб він усвідомив, яку страшну ціну нещодавно заплатили калдореї. У битві за гору Гіджал Світове Дерево Нордрассил було принесено в жертву, щоб здолати Архімонда й вигнати Палаючий Легіон. З тим нищівним вибухом нічні ельфи втратили своє вічне безсмертя й священний щит. Тенарон Стормґріп — водночас наставник та історик: він дає новачкам цей обряд, щоб прищепити смирення й мету, перш ніж вони зустрінуть мінливий світ."},{t="Води колодязя",b="Завдання вимагає набрати кришталевою фіалою води з місячного колодязя на північ від Алдрассила. Ці місячні колодязі — не звичайні джерела: їхні води сповнені решток прадавнього Колодязя Вічності. Друїди спрямовують їхню відновлювальну силу в дику природу, а Вартові шанують їх як тихі святині богині Елуни, та калдореї лишаються вкрай обережними. Таємна магія в суспільстві нічних ельфів і досі суворо заборонена, адже джерело, що живить їхню землю, нагадує й про безрозсудні чари, які колись мало не розкололи світ."}},faq={{q="Хто такий Тенарон Стормґріп?",a="Тенарон Стормґріп — нічний ельф, що мешкає високо у верхніх гілках Алдрассила в Тінедолі. Він наставляє молодих нічних ельфів, які завершують початкове навчання, і доручає їм обряди, що знайомлять з урочистою історією їхньої раси, перш ніж відправити їх далі Тельдрассилом.",al={"тенарон стормґріп","хто дає корону землі","друїд алдрассила"}},{q="Навіщо набирати воду з місячного колодязя?",a="Набрати води в кришталевий фіал — перший крок обрядової і водночас цілком практичної подорожі островом. Вода місячного колодязя зберігає давню магію, якою друїди живлять землю, а сам обряд навчає молодих калдореїв священних обов'язків їхнього суспільства.",al={"навіщо вода з місячного колодязя","призначення кришталевої пляшки","мета місячного колодязя"}},{q="Чому нічні ельфи втратили безсмертя?",a="Під час Третьої війни нічні ельфи вивільнили прадавню силу, вплетену у Світове Дерево Нордрассіл, щоб знищити владику демонів Архімонда на вершині Гори Гіджал. Ця жертва стерла на порох авангард Легіону, але позбавила нічних ельфів вічної молодості й несприйнятливості до хвороб.",al={"чому нічні ельфи смертні","що сталося з безсмертям","знищення нордрассила"}},{q="Чи небезпечні місячні колодязі?",a="У місячних колодязях — розбавлена есенція, пов'язана з Колодязем Вічності. Друїди й жриці безпечно спрямовують її силу на зцілення, благословення й єднання з природою, але калдореї суворо забороняють чаклувати з її допомогою тайну магію — надто вже великих лих наробило безрозсудне чародійство в давнину.",al={"чи місячні колодязі арканні","чи безпечна вода колодязя","небезпека колодязя вічності"}},{q="Куди веде цей ланцюжок завдань далі?",a="Повернувши наповнений фіал, ви завершуєте перший урок ланцюжка «Корона Землі». Далі Тенарон спрямує вас до Доланаара й далі Тельдрассилом — очищати й доглядати священні місця на величезних гілках нового Світового Дерева.",al={"що після корони землі","ланцюжок корони землі","наступне завдання після тенарона"}},{q="Де місячний колодязь для цього завдання?",a="Місячний колодязь — за кілька кроків на північ від могутніх гілок Алдрассила, у мирному затишку лісів Тінедолу.",al={"де місячний колодязь","місце місячного колодязя в тіньовій долині","знайти колодязь"}}},fp="18,298,26.527.0,18.561.0,25.270.0,49.294.0,47.286.0,35.305.0,38.266.0,45.132.0"}
P.entries["quest:92124"] = {n="Опис книгозбірні",s="«Опис книгозбірні» — вступне завдання в Абатстві Нортшира від Брата Пакстона. Роздратований загубленими й переставленими томами, бібліотекар абатства посилає молодих шукачів пригод знайти свого помічника Деніела й перелічити архіви бібліотеки. Однак сумнозвісна звичка Деніела марити місцевими ремеслами робить пряму відповідь значно важчою, ніж хотілося б Пакстону.",h="«Опис книгозбірні» — вступне завдання в Абатстві Нортшира від Брата Пакстона.",kw={"опис книгозбірні","брат пакстон","деніел","бібліотека","книги","абатство нортшира"},ang={["class:Priest"]="Жерці, що вивчають священні архіви Нортширу, покладаються на лад у бібліотеці, аби зберегти святі писання й традиції Церкви.",["race:Human"]="Для молодих людей, що починають службу в Абатстві Нортшира, поєднувати чернечу вченість із практичним сільським життям — знайома боротьба."},sec={{t="Розпач бібліотекаря",b="Абатство Нортшира зберігає одні з найстаріших учених праць, духовних писань та історичних записів, що вціліли в Королівстві Стормвінд після Першої війни. Доглядати ці томи випало Брату Пакстону — скрупульозному ченцеві, який дуже пишається зібранням абатства. Останнім часом книги почали зникати з полиць, порушуючи архівний спокій Нортширу. Пакстону потрібен чіткий опис, аби зрозуміти справжній розмах утрат, та йому бракує терпіння ганятися за своїм замріяним помічником."},{t="Розсіяні інтереси Деніела",b="Деніел працює в бібліотеці абатства помічником Брата Пакстона, та думки юнака рідко затримуються на пергаменті й каталожних номерах. Натомість Деніела захоплюють практичні ремесла Лісу Елвінн — ковальство, шкіряництво, кравецтво й травництво. Це безмежно дратує Пакстона: кожен облік неминуче закінчується тим, що помічник просторікує про місцевих ремісників замість шукати загублені писання."}},faq={{q="Хто такий Брат Пакстон?",a="Брат Пакстон — чернець Абатства Нортшира, який опікується великою збіркою книг, святих писань і старовинних сувоїв абатства. Він швидко втрачає терпець, коли книги зникають або помічники ухиляються від своїх обов'язків.",al={"брат пакстон","хто дає опис книгозбірні","пакстон елвінн"}},{q="Хто такий Деніел?",a="Деніел — юний помічник Брата Пакстона в бібліотеці Абатства Нортшира. Йому доручено впорядковувати книги й проводити опис, але його легко відволікає пристрасть до ремесел і професій, якими живе Ліс Елвінн.",al={"хто такий деніел","помічник пакстона","деніел нортшир"}},{q="Чому з Абатства Нортшира зникають книги?",a="Брат Пакстон каже, що книги зникли, але не пояснює чому. Він просить Деніела описати книгозбірню й визначити, наскільки великі втрати.",al={"чому зникають книги","зниклі книги нортшира","втрачені книги абатства"}},{q="Де знайти Деніела?",a="Деніел в Абатстві Нортшира: він сидить серед полиць і столів абатської бібліотеки.",al={"де деніел","місце деніела","знайти деніела"}},{q="Чому Пакстон називає Деніела нікчемою?",a="Пакстон вважає Деніела нікчемою, бо хлопець постійно занедбує свої обов'язки в архіві. Замість каталогізувати книги й розставляти їх на полиці, Деніел годинами мріє й торочить про практичні ремесла.",al={"чому пакстон ненавидить деніела","деніел нікчема"}},{q="Якими ремеслами цікавиться Деніел?",a="Деніела захоплюють ремесла, якими займаються по всьому Лісі Елвінн, — ковальство, шкірництво, кравецтво. Праця руками йому миліша за запилені фоліанти.",al={"ремесла деніела","які професії любить деніел"}}},fp="14,399,25.520.0,27.451.0,22.229.0,14.245.0,44.150.0,26.114.0,36.207.0,41.176.0"}
P.entries["quest:922"] = {n="Релліан Ґрінспайр",s="Це доручення веде вас від приозерного притулку Деналана на Тельдрассилі до столиці — Дарнасуса. Насінина деревляника, передана друїдові Релліану Ґрінспайру, приносить тривожні вісті про скверну, що шириться гіллям Світового Древа.",h="Це доручення веде вас від приозерного притулку Деналана на Тельдрассилі до столиці — Дарнасуса.",kw={"релліан ґрінспайр","деналан","насінина деревляника","деревляники","озеро ал'амет","скверна","ценаріонський анклав"},ang={["class:Druid"]="Для посвячуваних Кола Кенарія це доручення показує, як глибоко непередбачена недуга проникла в новонароджену природу Тельдрассилу, і підкреслює нагальну потребу берегти тутешнє стихійне життя.",["race:NightElf"]="Деревляники мали квітнути разом із ростом Тельдрассилу, тож відкриття Релліана про спадкову скверну — тривожний знак для нової батьківщини калдореїв."},sec={{t="Гонець до столиці",b="Деналан доклав чимало зусиль, вирощуючи й вивчаючи рослини та стихійне життя довкола Озера Ал'Амет. Зібравши насіння місцевих деревляників, він посилає вас до Дарнасуса, щоб передати зразок його колезі Релліану Ґрінспайру. Релліан — такий самий друїд, що походжає спокійними терасами Ценаріонського Анклаву; він уже цікавився дослідженнями Деналана й сподівається виростити власного деревляника."},{t="Зіпсований паросток",b="Отримавши насінину, Релліан приносить замість наукового оптимізму похмурі новини. Його нещодавні дослідження підтвердили, що деревляники по всьому Тельдрассилу стають жертвами агресивної, всепроникної скверни. Гірше того, насіння, зібране із заражених особин, уже несе пошесть батьків. Релліан визнає, що очистити його йому самому не до снаги, і припускає, що лише глибока спорідненість Деналана з усім живим дає ще хоч якусь надію відновити рівновагу."}},faq={{q="Хто такий Релліан Ґрінспайр?",a="Релліан Ґрінспайр — друїд нічних ельфів, якого можна зустріти на стежках Ценаріонського Анклаву в Дарнасусі. Він підтримує тісні наукові зв'язки з Деналаном: обох цікавлять природа й духи стихій Тельдрассила.",al={"переказ про релліана ґрінспайра","хто такий релліан","місце релліана ґрінспайра"}},{q="Чому Деналан надсилає Релліанові насінину деревляника?",a="Деналан із вашою допомогою зібрав насіння деревляників біля Озера Ал'Амет. Пам'ятаючи, що Релліан цікавився будовою деревляників і мав власні теорії, Деналан передає йому насінину, щоб той спробував виростити деревляника в столиці.",al={"чому надсилати насінину деревляника","доручення деналана"}},{q="Яку проблему виявляє Релліан?",a="Релліан з'ясовує, що деревляників уразила неприродна скверна. Тож і зібране з них насіння вже спотворене хворобою батьків, і виростити здорові паростки неможливо, доки не знайдеться ліки.",al={"що не так із насіниною","осквернення деревляників"}},{q="Куди веде це завдання далі?",a="Релліан сам не може вилікувати зіпсоване насіння, тож пропонує вам дослідити мохові пухлини, що вражають деревляників, — він сподівається, що з нових зразків Деналан зможе створити ліки.",al={"що після релліана ґрінспайра","наступне завдання після релліана"}},{q="Де знайти Релліана Ґрінспайра?",a="Релліан прогулюється відкритими стежками Ценаріонського Анклаву в північно-західному куточку Дарнасуса.",al={"де релліан","місце релліана на мапі"}},{q="Чому Релліан не може сам очистити насіння?",a="Скверна вкоренилася надто глибоко для Релліанових умінь. Він покладається на надзвичайний хист Деналана до ботаніки й вирощування живого, вважаючи свого друга найкращою надією на зцілення наступних поколінь деревляників.",al={"чому релліан не очистить сам","сили друїда релліана"}}},fp="18,254,24.438.0,14.491.1,26.237.0,51.250.0,35.249.0,31.206.1,38.111.0,44.241.0"}
P.entries["quest:923"] = {n="Пухлини",s="Це завдання на допомогу Колу Кенарія в Дарнасусі посилає шукачів пригод проріджувати уражених деревляників довкола Озера Джерела на півночі Тельдрассилу. Збираючи мохові нарости з цих спотворених духів природи, друїди сподіваються дослідити отруту, що поширюється, і безпечно спалити зіпсовані нарости.",h="Це завдання на допомогу Колу Кенарія в Дарнасусі посилає шукачів пригод проріджувати уражених деревляників...",kw={"пухлини","моховий наріст","деревляники","озеро джерела","релліан ґрінспайр","коло кенарія","тельдрассил"},ang={["class:Druid"]="Для друїдів Кола Кенарія знищення зіпсованих духів природи — трагічний, але необхідний обов'язок, щоб хитка рівновага Тельдрассилу не зруйнувалася остаточно.",["profession:Herbalism"]="Травників і знавців рослин бентежить, що жива деревина й мох перетворюються не на здорове листя, а на отруйні злоякісні пухлини.",["race:NightElf"]="Раптова хвороба на щойно вирощеному Світовому Древі — тривожний знак для калдореїв, що ставить під сумнів обіцянку Фандрала Стаґгелма про незайманий прихисток."},sec={{t="Пошесть серед деревляників",b="Тельдрассил виростили як прихисток гармонії, але дивна недуга почала спотворювати його рослини й тварин. Деревляники — зазвичай сумирні духи природи з корою замість шкіри — стали ворожими й непередбачуваними. На їхній живій деревині виросли потворні мохові нарости, що пульсують мерзенною, неприродною отрутою. Поки кенарійські вчені на кшталт Деналана й Релліана Ґрінспайра шукають корінь цієї хвороби, істот, яких уже поглинуло зло, доводиться знищувати, щоб уберегти решту гілля."},{t="Стримування біля Озера Джерела",b="Wellspring Lake in northern Teldrassil has become a focal point for the outbreak. The timberlings wandering its shores are among the most heavily tainted on the entire world tree. Rellian Greenspyre charges travelers with cutting down these corrupted guardians and excising their growths. By bringing the tumors directly to the druids in Darnassus to be safely burned, the night elves hope to stem the spread of the contagion while they continue searching for the source of the disease."}},faq={{q="Чому на деревляниках ростуть пухлини?",a="Дивна хвороба вкоренилася серед диких духів Тельдрассила. Мохові пухлини — зовнішній прояв отруйної скверни, що тече їхніми тілами й перетворює природний захисний інстинкт на сліпу агресію.",al={"що не так із деревляниками","хвороба деревляників","чому деревляники хворі"}},{q="Хто такий Релліан Ґрінспайр?",a="Релліан Ґрінспайр — дослідник із нічних ельфів, пов'язаний із Колом Кенарія, що працює в Дарнасусі. Разом з іншими ботаніками, як-от Деналан, він вивчає дивну скверну, що вражає природу Тельдрассила.",al={"переказ про релліана ґрінспайра","хто такий ґрінспайр","релліан ґрінспайр"}},{q="Навіщо пухлини треба спалювати?",a="Rellian Greenspyre says the tumors are filled with poison that must be cleansed from Teldrassil. He asks for the growths to be brought to him so they can be burned.",al={"палити пухлини","чому палити пухлини","знищення мохових пухлин"}},{q="Де Озеро Джерела?",a="Озеро Джерела лежить на півночі Тельдрассила і живиться чистими водотоками гілки. Деревляники на його берегах помітно хворіші, ніж будь-де деінде.",al={"місце озера джерела","де деревляники","де мохові пухлини"}},{q="Чи можна вилікувати деревляників, а не вбивати?",a="Коло Кенарія наполегливо шукає ліки й джерело пошесті, але деревляникам біля Озера Джерела вже нічим не зарадиш. Доки джерело не знайдено, єдиний спосіб уберегти ліс — знищувати найагресивніших духів.",al={"чи можна врятувати деревляників","лікування деревляників"}},{q="Що буде, коли пухлини доставлено в Дарнасус?",a="Забравши й знищивши пухлини, Релліан відсилає шукачів пригод назад до ботаніка Деналана біля Озера Ал'Амет — вести далі розслідування скверни, що поширюється рослинністю Тельдрассила.",al={"після завдання пухлин","що далі з пухлинами"}}},fp="6,302,27.520.0,30.486.0,39.228.0,26.222.0,30.164.0,25.194.0,47.270.0,52.202.0"}
P.entries["quest:924"] = {n="Демонське Сім'я",s="Виконуючи накази, передані через Ніру Файрблейда, Ак'Зелот доручає мандрівникам Орди знешкодити Демонське Сім'я на Піку Жахливої Імли. Поклавши нестійкий Недосконалий Камінь Сили на вогняний вівтар, шукачі пригод розбивають могутній провідник, пов'язаний із Палаючим Легіоном, перш ніж його темний вплив пошириться Пустками.",h="Виконуючи накази, передані через Ніру Файрблейда, Ак'Зелот доручає мандрівникам Орди знешкодити Демонське...",kw={"демонське сім'я","ак'зелот","недосконалий камінь сили","пік жахливої імли","палаючий легіон","ніру файрблейд"},ang={["class:Warlock"]="Чорнокнижники розуміють, якої тонкої роботи вимагає створення каменів сили, що розхитують прив'язі Легіону, не спричинивши випадково катастрофічного демонічного колапсу.",["faction:Horde"]="Знищення опорних пунктів Легіону в Пустках захищає життєво важливе роздоріжжя караванів і торгові шляхи, на яких тримається молода Орда.",["race:Orc"]="Переживши загибель Дренору під демонічною скверною, орки мають мало терпіння до вівтарів Легіону, що гниють біля кордонів Дуротару."},sec={{t="Маяк серед скель",b="У зубчастій печері високо на Піку Жахливої Імли, над демонічним вогняним вівтарем, висить Демонське Сім'я. Цей артефакт — могутній пристрій Палаючого Легіону, що закріплює демонічні вібрації в запорошеному серці Пусток. Щоб протидіяти загрозі, чорнокнижник Ак'Зелот готує особливі камені сили, здатні розірвати зв'язок артефакту з Нижнім Світом, — якщо посланець устигне донести один із них на вершину, перш ніж його нестійка енергія згасне."},{t="Розірвати прив'язь",b="Нести тендітний камінь скелястими схилами Піка Жахливої Імли — перегони з часом, адже камінь поволі пожирає власну силу. Щойно його покладено на вогняний вівтар, каталізатор перевантажує Демонське Сім'я й розриває його зв'язок. Та знищення провідника має лиховісний наслідок: його раптова загибель посилає приголомшливі хвилі крізь ефір і сповіщає могутніх незримих господарів, що їхній цінний пристрій зруйновано."}},faq={{q="Що таке Демонське Сім'я?",a="Демонське Сім'я — артефакт Палаючого Легіону в печері на вершині Піку Жахливої Імли. Воно лежить над вогняним вівтарем і правує за провідник, яким демонічна сила й вплив ллються просто в Пустки.",al={"призначення демонського сім'я","що таке демонське сім'я","переказ про демонське сім'я"}},{q="Хто наказує знищити Демонське Сім'я?",a="Завдання дає чорнокнижник Ак'Зелот, що діє за вказівками й винагородою від Ніру Файрблейда — знаного чорнокнижника, який перебуває під Оргріммаром, у Тіньовій Розколині.",al={"хто хоче знищити демонське сім'я","ніру демонське сім'я","видавець ак'зелот"}},{q="Чому в Недосконалого Каменя Сили обмежений час?",a="Недосконалий Камінь Сили, створений Ак'Зелотом, від природи нестійкий. Його магічна оболонка недосконала, тож руйнівна енергія вигорає й поглинає камінь, якщо не донести його до демонічного вівтаря за короткий час.",al={"таймер недосконалого каменя сили","чому камінь минає","камінь зникає"}},{q="Де вогняний вівтар?",a="Демонічний вогняний вівтар — у печері біля вершини Піку Жахливої Імли, зловісної гори на північний захід від Перехрестя в північних Пустках.",al={"місце вогняного вівтаря","печера демонського сім'я","печера піку жахливої імли"}},{q="Що станеться, коли Демонське Сім'я знищено?",a="Розбивши Сім'я, ви розриваєте його зв'язок із Палаючим Легіоном, але бурхливий викид магії розходиться ефіром величезними хвилями. Ак'Зелот попереджає: могутні демонічні сутності відчули цей розлад і захочуть з'ясувати, хто зруйнував їхнє знаряддя.",al={"ударна хвиля демонського сім'я","наслідки демонського сім'я","хвилі сили"}},{q="Як це пов'язано з Ніру Файрблейдом?",a="Ніру Файрблейд разом з Ак'Зелотом вистежує ворожі чи шкідливі демонічні артефакти по всіх Пустках. Саме Ніру дає гроші й спорядження, якими винагороджують за знищення Демонського Сім'я.",al={"зв'язок із ніру","чи ніру добрий","участь ніру"}}},fp="14,331,21.467.0,21.460.1,23.215.0,45.194.0,50.230.0,35.161.0,46.259.1,41.209.0"}
P.entries["quest:92415"] = {n="Пам'ятай, що я люблю тебе",s="Завдання «Пам'ятай, що я люблю тебе» починається з подертого, заплямованого пергаменту, знайденого серед могил Руїн Лордерона, якими блукає нежить. Лист розповідає трагічну історію загубленої дитини з родини Гартвівер. Щоб знайти відповіді, цю крихку реліквію треба віднести на південь, до сиротинця в Стормвінді.",h="Завдання «Пам'ятай, що я люблю тебе» починається з подертого, заплямованого пергаменту, знайденого серед...",kw={"пам'ятай, що я люблю тебе","руїни лордерона","гартвівер","сиротинець","матрона найтінґейл","стормвінд","лист"},ang={["faction:Alliance"]="Безпечно донісши лист до Стормвінда, ви вшановуєте пам'ять північних родин, яких розлучило падіння Лордерона.",["race:Human"]="Для людей лордеронського роду цей згорток пергаменту — болісне нагадування про родини, розлучені, коли Столичне місто впало перед принцом Артасом і Погибеллю."},sec={{t="Благання з руїн",b="Серед зачумленої землі й шкандибаючої нежиті, що населяє руїни Столичного міста, уцілілі й шукачі поживи часом натрапляють на нагадування про спустошення Третьої війни. Цей подертий, закривавлений згорток пергаменту ледве вцілів на кладовищі, витоптаному нежиттю. У ньому згадано зниклу дитину з роду Гартвіверів — свідчення зламаних життів, коли принц Артас і Погибель пройшлися королівством."},{t="Дорога до сиротинця",b="Лордерон упав, катакомби під ним забрало собі Андерсіті, а нечисленні біженці, що втекли на південь, розсіялися по королівствах Альянсу. У Стормвінді Матрона Сиротинця Найтінґейл опікується дітьми, які втратили батьків у війнах. Передати їй закривавлений лист — одна з небагатьох надій, що вцілілу дитину з родини Гартвівер вдасться впізнати й дати їй відповідь."}},faq={{q="Де знаходять закривавлений лист?",a="Пошматований і заплямований згорток пергаменту знаходять на цвинтарі в Руїнах Лордерона — місцині, де тепер блукають неспокійні мерці й сили Відступників.",al={"де знайти лист","місце пергаменту","де починається це завдання"}},{q="Хто такі Гартвівери?",a="Про родину Гартвіверів поки відомо небагато. У листі, знайденому на цвинтарі в Руїнах Лордерона, згадано зникле дитя цієї родини, і з'являється надія, що дитина втекла на південь, до притулку Альянсу.",al={"гартвівери","хто такі гартвівери","переказ про гартвіверів"}},{q="Хто така Матрона Сиротинця Найтінґейл?",a="Матрона Сиротинця Найтінґейл опікується сиротинцем Стормвінда на Соборній Площі. Вона дає їжу, дах і настанови дітям, що лишилися без батьків через недавні війни.",al={"найтінґейл","матрона найтінґейл","матрона сиротинця"}},{q="Навіщо везти пам'ятку з Лордерона аж до Стормвінда?",a="Коли Погибель захопила Лордерон, багатьох осиротілих дітей вивезли на південь, до королівства Стормвінд. Сам пергамент підказує, що більше знатиме матрона, яка керує міським сиротинцем у Стормвінді.",al={"чому стормвінд","чому надсилати найтінґейл"}},{q="Чи можуть гравці Орди виконати це завдання?",a="Завдання веде до Матрони Сиротинця Найтінґейл у глибині Соборної Площі Стормвінда, тож ця подорож — справа Альянсу.",al={"версія для орди","чи орда може це"}},{q="У якому стані зараз Руїни Лордерона?",a="Наземні руїни столиці здебільшого покинуті, розвалюються, і там блукають мерці. Тим часом Леді Сильвана Віндраннер і Відступники укріпили свою підземну столицю, Андерсіті, у склепах під руїнами.",al={"стан руїн лордерона","хто контролює руїни лордерона"}}},fp="24,315,21.438.0,24.424.0,40.170.0,30.212.0,33.184.0,55.229.0,38.161.0,51.226.0"}
P.entries["quest:92460"] = {n="Час змужніти",s="«Час змужніти» — перший обряд посвяти для юних Небороджених, що вперше виходять за межі Села Тендаль на Острові Зефрас. Під проводом Ейлі Фаргарт новачки приходять до провідника села, Роріана Деньошукача, щоб отримати реліквію предків і урочисто присягнути допомагати шен'дорей.",h="«Час змужніти» — перший обряд посвяти для юних Небороджених, що вперше виходять за межі Села Тендаль на...",kw={"час змужніти","роріан деньошукач","ейлі фаргарт","реліквія предків","шен'дорей","село тендаль"},ang={["race:Skyborne"]="Цей обряд посвяти позначає ваш вступ у доросле життя й дарує вам священну родинну реліквію, яку ви носитимете, куди б не повіяли вітри."},sec={{t="Обряд посвяти",b="Для кожного юного Небородженого, що вступає в доросле життя, шлях починається в Селі Тендаль. За вказівкою Ейлі Фаргарт молодь прямує трохи на захід, до дерева-прадіда, де чекає старійшина села. Дорослішання серед шен'дорей — не просто віха в житті громади, а урочиста обітниця служити своєму народові серед дедалі більших місцевих негараздів."},{t="Реліквія предків",b="Біля входу до дерева-прадіда церемонію очолює Роріан Деньошукач. Він урочисто вручає посвячуваному реліквію предків — родинну спадщину, що переходила крізь покоління шен'дорей. Її носило багато тих, хто жив раніше, і вона — незгасний знак вітрів рідного дому, що повернеться до народу лише тоді, коли попіл її носія розвіють за вітром."}},faq={{q="Навіщо потрібен обряд «Час змужніти»?",a="Цей обряд — офіційний перехід до дорослого життя для молодих Небороджених: він урочисто приймає їх на дійсну службу шен'дорей і дарує їм родову реліквію.",al={"навіщо час змужніти","мета часу змужніти","обряд посвяти скайборнів"}},{q="Хто дає це завдання?",a="Ейлі Фаргарт, що наглядає за новачками в Селі Тендаль на Острові Зефрас, вітає вас і посилає познайомитися з проводом села.",al={"хто дає час змужніти","де починається час змужніти","місце ейлі фархарт"}},{q="До кого звертатися щодо обряду?",a="До Роріана Деньошукача, очільника Села Тендаль. Він стоїть біля входу до великого дерева-праотця трохи на захід від поселення.",al={"хто такий роріан","де роріан","місце роріана деньошукача"}},{q="Яку реліквію вручають під час обряду?",a="Роріан вручає успадковану реліквію змужніння, яку до вас носили покоління шен'дорей. За звичаєм вона лишається з вами до смерті, а тоді переходить до наступного покоління.",al={"яка реліквія","реліквія скайборнів","що отримаю"}},{q="Що тут означає «шен'дорей»?",a="Словом «шен'дорей» Роріан називає Небороджених, нагадуючи про їхню складну історію, спільні випробування й незмінну самобутність на Острові Зефрас.",al={"хто такі шен'дорей","значення шен'дорей","скайборни шен'дорей"}},{q="Куди веде шлях одразу після цього?",a="Після обряду посвяти Роріан звертає вашу увагу на місцеві негаразди, що загрожують острову, — почати можна із завдань «Рівновага в гармонії» та «Розслідування навали».",al={"яке завдання далі","наступні кроки після часу змужніти","після роріана"}}},fp="13,290,17.370.0,19.382.0,50.175.0,24.147.0,36.140.0,43.202.0,44.135.0,52.189.0"}
P.entries["quest:92461"] = {n="Рівновага в гармонії",s="«Рівновага в гармонії» — одне з перших доручень, яке Роріан Деньошукач дає молодим шукачам пригод на Острові Зефрас. Вам треба прорідити молодих вульдренів у Тендальському Гаю, щоб зберегти природну рівновагу острова. Через цю буденну необхідність новачки дізнаються, як чутливо місцеві звірі відгукуються на зміни магічних течій довкола.",h="«Рівновага в гармонії» — одне з перших доручень, яке Роріан Деньошукач дає молодим шукачам пригод на Острові...",kw={"рівновага в гармонії","вульдрени","тендальський гай","роріан деньошукач","острів зефрас","рівновага"},ang={["class:Druid"]="Наказ прорідити надто численних вульдренів суголосний із друїдською філософією, за якою іноді треба прорідити звірів, щоб уберегти здоров'я всієї природи.",["class:Hunter"]="Стежити за чисельністю стад і за тим, як місцеві звірі відгукуються на зміни довкілля, — основа вишколу для кожного слідопита в Тендальському Гаю."},sec={{t="Догляд за гаєм",b="Навіть у часи непевного майбутнього й дедалі більших небезпек щоденне виживання на Острові Зефрас вимагає скромної старанності. У Тендальському Гаю вульдренів стало більше, ніж може прогодувати край, і це загрожує тендітній гармонії, що тримає життя тварин острова. Роріан Деньошукач доручає юним захисникам тверезе завдання — зменшити їхню кількість, щоб відвернути загальну шкоду природі."},{t="Вітри неспокою",b="Відстріл диких звірів може здатися звичайною єгерською роботою, але сплеск чисельності вульдренів свідчить про глибші тривоги. Хоч зазвичай це сумирні істоти, звірина Зефраса співзвучна з повітрям острова й гостро реагує, коли магія, яку несуть вітри, втрачає рівновагу. Якщо вчасно виправити ці перекоси, сумирні істоти не переродяться на непередбачуваних і небезпечних шкідників."}},faq={{q="Навіщо треба проріджувати вульдренів?",a="Вульдренів у Тендальському Гаю розплодилося понад міру. Якщо їх не стримати, вони вичерпають місцеві ресурси й порушать тендітну рівновагу, на якій тримається життя інших мешканців гаю.",al={"навіщо вбивати вульдренів","вульдрени перенаселення","вульдрени гаю тендал"}},{q="Хто такий Роріан Деньошукач?",a="Роріан Деньошукач — старійшина, провідник і наставник на Острові Зефрас. Він опікується навчанням молодих шукачів пригод і нагадує їм, що захист рідного краю вимагає уваги і до великих криз, і до щоденного дбання про природу.",al={"переказ про роріана","хто такий роріан"}},{q="Чому вульдрени шаленіють?",a="Зазвичай вульдрени — сумирні створіння, але тварини Зефрасу відчувають, коли магія, вплетена у вітри острова, втрачає рівновагу, і тоді їхня поведінка раптово змінюється.",al={"чому вульдрени шаленіють","поведінка вульдренів"}},{q="Де відбувається це завдання?",a="Завдання виконують у Тендальському Гаю — на схід і південний схід від поселення на Острові Зефрас.",al={"місце гаю тендал","де гай тендал"}},{q="Чого Роріан хоче навчити?",a="Роріан учить, що захист рідної землі часто вимагає важких і неприємних заходів. Твердою рукою відновлювати природний лад — неодмінний обов'язок кожного, хто стає захисником.",al={"урок роріана","значення рівноваги в гармонії"}},{q="Що варто зробити, полюючи на вульдренів?",a="Неподалік Елатрелл Федерлайт просить шукачів пригод розібратися з роєм надокучливих цирусфлаїв, тож зручно водночас дослідити й навалу комах у гаю.",al={"інші завдання поруч","розслідування навали"}}},fp="18,356,17.414.0,15.396.0,37.226.0,28.236.0,30.198.0,32.114.0,38.201.0,46.177.0"}
P.entries["quest:92462"] = {n="Розслідування навали",s="«Розслідування навали» — одне з перших завдань для молодих шукачів пригод, що виходять у Тендальський Гай на Острові Зефрас. Рейнджер Елатрелл Федерлайт наказує прорідити набридливих цирусфлаїв, що почали роїтися в східних гаях. Якщо їх не спинити, ці комахи, що швидко плодяться, загрожують порушити спокій гаю й наразити на небезпеку місцеві поселення.",h="«Розслідування навали» — одне з перших завдань для молодих шукачів пригод, що виходять у Тендальський Гай на...",kw={"розслідування навали","цирусфлаї","елатрелл федерлайт","тендальський гай","рейнджери","острів зефрас"},ang={["class:Druid"]="Зберегти Тендальський Гай — значить упоратися з природними перекосами, перш ніж агресивні рої оголять ліс.",["class:Hunter"]="Для молодих стрільців і слідопитів вистежувати дрібних, юрких цирусфлаїв між деревами — цінна практика стрільби на випередження по швидких цілях у густих заростях."},sec={{t="Рій у кронах",b="Тендальський Гай здавна зберігав тендітну рівновагу, але останні донесення місцевих рейнджерів кажуть про раптовий сплеск чисельності набридливих цирусфлаїв на східному краю лісу. Поодинокі цирусфлаї — дрібні шкідники, але коли їх стає забагато, їхні рої швидко стають агресивними й руйнівними. Рейнджер Елатрелл Федерлайт не гає часу й посилає здібну молодь прорідити літаючих комах, поки вони цілком не заполонили гай."},{t="Перші кроки служби",b="Після посвяти в дорослі юних захисників одразу кидають у практичну справу — догляд за Островом Зефрас. Знищення шкідників може здатися чорною роботою, але берегти ліси від спалахів диких звірів і комах конче важливо для безпеки сусідніх поселень. А те, скільки нутрощів і комах налипає на мисливців, що повертаються, доводить: рій куди більший, ніж спершу боялися."}},faq={{q="Що таке цирусфлай?",a="Цирусфлаї — крилаті комахи-шкідники, що водяться в буйній зелені Острова Зефрас. Поодинці вони дрібні, але плодяться швидко й, якщо їх не стримувати, можуть утворити небезпечні рої в місцях на кшталт Тендальського Гаю.",al={"цирусфлай","цирусфлаї","що таке цирусфлаї"}},{q="Хто дає завдання «Розслідування навали»?",a="Завдання дає Елатрелл Федерлайт — слідопит Тендальського Гаю, що тримає під контролем місцеву звірину й навколишні ліси.",al={"видавець завдання","хто починає це","елатрелл федерлайт"}},{q="Де шукати цирусфлаїв?",a="Надокучливі цирусфлаї скупчуються в східній і південно-східній частинах Тендальського Гаю на Острові Зефрас і дзижчать у листі поруч із молодими вульдренами.",al={"де шукати мух","місце цирусфлаїв","мухи гаю тендал"}},{q="Чому так важливо винищити цирусфлаїв?",a="Одна комаха майже не становить загрози, але рої цирусфлаїв можуть швидко стати такими густими, що загрожуватимуть мандрівникам, об'їдатимуть місцеві рослини й порушать мирну рівновагу Тендальського Гаю.",al={"чому вбивати мух","чому винищувати цирусфлаїв","загроза цирусфлаїв"}},{q="Що далі після «Розслідування навали»?",a="Коли рій поріділо, шукачі пригод повертаються з доповіддю, і Елатрелл Федерлайт посилає їх до самого серця навали — битися з Цирусфлайною королевою.",al={"наступне завдання","що далі","продовження розслідування"}},{q="Яке місце це завдання посідає на початку подорожі Зефрасом?",a="Завдання стає доступним одразу після випробування «Час змужніти» і є одним із перших бойових доручень для щойно визнаних захисників Острова Зефрас.",al={"ланцюжок завдань","коли я отримаю це","вимога рівня"}}},fp="25,344,21.452.0,22.419.0,20.237.0,46.158.0,34.160.0,41.188.0,43.163.1,60.174.0"}
P.entries["quest:92463"] = {n="Цирусфлайна королева",s="«Цирусфлайна королева» — полювання на матріарху агресивного вулика комах у Тендальському Гаю на Острові Зефрас. Після першої розвідки навали Елатрелл Федерлайт посилає новобранців у серце гаю, щоб знищити королеву й винищити рій у самому його джерелі. Кінець її панування дає негайне полегшення місцевим рейнджерам, що намагаються тримати дику природу під контролем.",h="«Цирусфлайна королева» — полювання на матріарху агресивного вулика комах у Тендальському Гаю на Острові...",kw={"цирусфлайна королева","цирусфлаї","елатрелл федерлайт","тендальський гай","вулик","острів зефрас"},ang={["class:Hunter"]="Здолати агресивну королеву вулика й перехитрити її захисників-солдатів — раннє випробування у вистежуванні й винищенні звірів, що заслуговує прямої похвали місцевих рейнджерів.",["race:Skyborne"]="Очищаючи Тендальський Гай від навали, ви допомагаєте зберегти природну рівновагу й безпечні шляхи вашою батьківщиною — Островом Зефрас."},sec={{t="Удар по вулику",b="Перші зусилля проти цирусфлаїв показали: самим лише відганянням поодиноких робітниць навалу, що ширшає Тендальським Гаєм, не спинити. Елатрелл Федерлайт доручає здібним мандрівникам заглибитися в південно-східні закутки гаю, де лежить головний вулик. Там королева керує колонією під пильною охороною важчих солдатів."},{t="Тягар рейнджера",b="Здалеку звичайні цирусфлаї можуть видатися дрібними шкідниками, але їхні більші породи становлять серйозну небезпеку для кожного, хто проходить під гіллям Зефраса. Вистеживши матріарху й вистоявши проти її охорони, новачки доводять свою бойову вартість і здобувають щиру похвалу й повагу загону рейнджерів Федерлайт."}},faq={{q="Де Цирусфлайна королева?",a="Цирусфлайна королева звила гніздо в південно-східному куточку Тендальського Гаю на Острові Зефрас, біля самого серця комашиного вулика.",al={"місце королеви","де цирусфлайна королева","знайти королеву"}},{q="Чому недостатньо просто вбивати робочих комах?",a="Елатрелл Федерлайт розуміє, що, винищуючи робочих комах, які блукають гаєм, можна лише проріджувати краї рою. Доки королева жива, вона й далі плодитиме агресивних воїнів і поповнюватиме вулик, а загроза Тендальському Гаю не зникне.",al={"чому вбити королеву","проріджування вулика"}},{q="Хто доручає полювання на Цирусфлайну королеву?",a="Елатрелл Федерлайт дає це завдання, щойно перші донесення з лісу підтверджують, наскільки серйозна навала цирусфлаїв.",al={"хто дає це завдання","видавець королеви"}},{q="Чим королева небезпечніша за звичайних цирусфлаїв?",a="На відміну від звичайних робочих комах, що блукають гаєм, королеву оточують більші й набагато агресивніші воїни, які боронять її вулик.",al={"небезпека королеви","солдати цирусфлаїв"}},{q="Яке завдання передує цьому дорученню?",a="Це доручення йде одразу за завданням «Розслідування навали», яке й показало, як широко комахи розплодилися в гаю.",al={"попереднє завдання","що перед цим"}},{q="Яку роль у цій місцевості відіграє Елатрелл Федерлайт?",a="Елатрелл Федерлайт відповідає за безпеку диких земель на Острові Зефрас: стежить за загрозами в окрузі й навчає новачків лісового слідопитства й обов'язків слідопита.",al={"роль федерлайт","хто така федерлайт"}}},fp="19,408,17.391.0,17.339.0,37.134.0,43.244.0,44.122.0,61.148.0,36.149.0,55.165.0"}
P.entries["quest:92464"] = {n="Неспокій стихій",s="«Неспокій стихій» — вступне доручення від Роріана Деньошукача на Острові Зефрас. Відтоді як розумні стихійні покровителі острова пішли, менші духи вітру біля Тендальських Стоячих Каменів стали неспокійними й непередбачуваними. Вас посилають у Тендальський Гай розшукати ученицю Роріана, Ялу Віндвотчер, і з'ясувати, що бентежить місцевий вітер.",h="«Неспокій стихій» — вступне доручення від Роріана Деньошукача на Острові Зефрас.",kw={"неспокій стихій","духи вітру","роріан деньошукач","яла віндвотчер","тендальські стоячі камені","острів зефрас"},ang={["class:Shaman"]="Духи вітру Зефраса віддзеркалюють душевний клімат острова, мов дзеркало, тож цей неспокій — ясна пересторога про глибший розлад довкілля.",["race:Skyborne"]="Відколи стихійні покровителі пішли, вітри стали непередбачуваними, і ті, хто залежить від неба Острова Зефрас, мусять бути пильними."},sec={{t="Вітер змінюється",b="Поколіннями народ Зефраса жив поруч із могутніми розумними духами вітру, що вели й оберігали його. Відколи ці стихійні покровителі пішли, острів поринув у тривалий розлад. Ніхто з добрих розумів більше не доглядає за повітрям — лишилися тільки прості духи, що віддзеркалюють бурхливі почуття й сили, які витають над краєм."},{t="Тендальські Стоячі Камені",b="На північний схід від посту Роріана, біля прадавніх Тендальських Стоячих Каменів, повітря стало різко ворожим. Оскільки цим меншим утіленням бракує справжньої самосвідомості, їхній неспокій народжений не злобою, а відгуком на щось. Роріан послав свою ученицю, Ялу Віндвотчер, стежити за їхньою непередбачуваною поведінкою з краю гаю й з'ясувати, яка прихована напруга їх тривожить."}},faq={{q="Чому вітряні духи збурені?",a="На відміну від колишніх покровителів острова з-поміж стихій, ці вітряні духи не мають справжньої самосвідомості. Вони інстинктивно віддзеркалюють почуття, наміри й магічні сили довколишніх істот і подій, тож стають буремними щоразу, як місцеве довкілля втрачає рівновагу.",al={"чому стихійці розлючені","причина неспокою вітру","чому духи сердяться"}},{q="Що це за покровителі-стихії, про яких згадує Роріан?",a="Це були розумні, доброзичливі духи вітру, що колись жили пліч-о-пліч із мешканцями Зефрасу. Відколи вони пішли, острів, позбавлений їхнього врівноважувального впливу, не знає спокою.",al={"стихії-покровителі","хто залишив зефрас","вітряні духи зефраса"}},{q="Де знайти Ялу Віндвотчер?",a="Яла Віндвотчер перебуває на північному сході Тендальського Гаю, звідки видно Тендальські Стоячі Камені, біля яких збираються збурені вітряні духи.",al={"місце яли віндвотчер","де яла","учениця гаю тендал"}},{q="Хто такий Роріан Деньошукач?",a="Роріан Деньошукач — старійшина й провідник на Острові Зефрас, що пильнує духовну рівновагу острова й вивчає заворушення серед місцевих елементалів.",al={"хто такий роріан","роріан деньошукач"}},{q="Що буде, коли я знайду Ялу?",a="Розмова з Ялою веде до з'ясування справжньої причини заворушень біля стоячих каменів — починаючи із завдання «Підбурювачі».",al={"наступне завдання","що після неспокою стихій","продовження яли"}},{q="Чи небезпечні вітряні духи?",a="Вони прості за своєю природою, але збурений стан робить їх непередбачуваними й насторожливими. Доки причина заворушень не зникне, вони агресивно реагують на будь-яке вторгнення.",al={"чи духи ворожі","небезпека стихійців"}}},fp="16,384,20.361.0,27.381.0,34.281.0,50.197.0,34.148.0,28.167.0,32.150.0,31.163.0"}
P.entries["quest:92465"] = {n="Підбурювачі",s="«Підбурювачі» — одне з перших завдань на Острові Зефрас від Яли Віндвотчер. Войовничий культ Аль'Акет пробрався в Тендальський Гай і розбурхав мирних місцевих духів вітру, обернувши їх на ворожих елементалів. Шукачів пригод посилають розвіяти збурені вітри й вичистити навернених культистів, що загрожують краю.",h="«Підбурювачі» — одне з перших завдань на Острові Зефрас від Яли Віндвотчер.",kw={"підбурювачі","культ аль'акет","яла віндвотчер","тендальський гай","духи вітру","острів зефрас"},ang={["class:Druid"]="Осквернення природної гармонії Тендальського Гаю свавільними культистами робить захист його рідних духів нагальною справою.",["class:Shaman"]="Бачити, як природні духи вітру впадають у лютий шал через втручання культистів, — образа стихійної рівноваги, що вимагає втручання."},sec={{t="Неспокій у гаю",b="Над Тендальським Гаєм нависла тінь культу Аль'Акет. Відомі своїми тривожними задумами щодо Острова Зефрас, культисти вдерлися в гай і навмисно розлютили тендітних духів вітру, що там живуть. Колись мирні духи стали лютими й утворили нестійкі збурені вітри, які загрожують кожному, хто проходить цим краєм."},{t="Болісна необхідність",b="Яла Віндвотчер доручає мандрівним героям угамувати і розлючених елементалів, і навернених Аль'Акет, що роздмухують неспокій. Приборкання вітряних істот повертає гаєві крихкий спокій, але розправа з культистами — гіркий обов'язок: Яла оплакує кров шен'дорей, пролиту серед власного народу, проте визнає, що культ не лишає іншого вибору."}},faq={{q="Хто дає завдання «Підбурювачі»?",a="Завдання дає Яла Віндвотчер неподалік Тендальського Гаю на Острові Зефрас.",al={"видавець завдання","хто починає підбурювачів","яла віндвотчер"}},{q="Що культ Аль'Акет робить у Тендальському Гаю?",a="Культ Аль'Акет оселився в гаю й збурив місцевих духів вітру, доводячи мирних створінь до ворожого, лютого шалу.",al={"що роблять сектанти","чому аль'акет тут","мета навернених аль'акет"}},{q="Що таке Буремні Вітри?",a="Це прості вітряні духи Острова Зефрас, яких культисти Аль'Акет збурили й спотворили, перетворивши на агресивні вихори-елементалі.",al={"буремні вітри","вітряні духи","вітряні стихійці гаю тендал"}},{q="Чому Ялу Віндвотчер засмучує вбивство навернених?",a="Яла шкодує, що доводиться проливати кров шен'дорей у гаю: навернені Аль'Акет — їхні ж родичі, що піддалися небезпечному вченню культу.",al={"чому яла жалкує","проливати кров шен'дорей","цитата яли про завершення"}},{q="Яке завдання йде після «Підбурювачів»?",a="Виконавши «Підбурювачів» для Яли Віндвотчер, ви продовжуєте службу в завданні «Повернення до Роріана».",al={"яке завдання далі","продовження підбурювачів","куди йти після підбурювачів"}},{q="Де відбувається цей конфлікт?",a="Конфлікт точиться в Тендальському Гаю на Острові Зефрас.",al={"місце підбурювачів","зона гаю тендал","де гай тендал"}}},fp="9,306,20.341.0,19.371.0,30.83.0,49.143.0,27.155.0,57.170.0,29.119.0,36.81.0"}
P.entries["quest:92469"] = {n="Повернення до Роріана",s="«Повернення до Роріана» — доручення доставити нагальні донесення з поля назад до Тендальського Гаю на Острові Зефрас. Допомігши Ялі Віндвотчер дати відсіч загарбникам, шукач пригод вирушає сповістити Роріана Деньошукача, що культ Аль'Акет відверто посилив свою присутність, розбурхуючи місцевих духів вітру.",h="«Повернення до Роріана» — доручення доставити нагальні донесення з поля назад до Тендальського Гаю на Острові...",kw={"повернення до роріана","роріан деньошукач","яла віндвотчер","культ аль'акет","тендальський гай","донесення"},ang={["class:Druid"]="Захист Тендальського Гаю й мирної гармонії священних земель Острова Зефрас природно збігається з друїдськими обітницями.",["class:Shaman"]="Звістка про те, що Аль'Акет навмисно розбурхують духів вітру, б'є в саму суть шаманського обов'язку — берегти стихійну рівновагу."},sec={{t="Тривожне донесення",b="Після того як підбурювачам, що тривожили Острів Зефрас, дали відсіч, Яла Віндвотчер лишається добивати решту ворогів, а вам доручає важливу справу — доставити відомості. Тендальський Гай має знати, що загадкові Аль'Акет більше не діють лише в тіні."},{t="Загострення біля Стоячих Каменів",b="Отримавши донесення, Роріан Деньошукач визнає, що провідники Тендальського Гаю вже давно здалеку стежать за діями культу. Проте те, що культисти розбурхують місцевих духів вітру біля стоячих каменів, — зухвале й тривожне загострення, за яким провід гаю вже не може просто спостерігати."}},faq={{q="Хто посилає вас до Роріана?",a="Яла Віндвотчер посилає вас доповісти Роріанові після того, як ви допоможете приборкати ворожих підбурювачів, що загрожують околицям.",al={"видавець завдання","хто починає повернення до роріана","яла віндвотчер"}},{q="Де знайти Роріана Деньошукача?",a="Роріан Деньошукач — у Тендальському Гаю, поселенні, звідки провід гаю керує справами на Острові Зефрас.",al={"де роріан","місце роріана","роріан у гаю тендал"}},{q="Хто такі Аль'Акет?",a="Аль'Акет — культ, що діє на Острові Зефрас. Раніше за ним нишком стежили здалеку, але тепер, коли культисти збурили вітряних духів біля стоячих каменів, вони стали відкритою загрозою.",al={"що за культ","хто такі аль'акет","культ аль'акет"}},{q="Чому Роріан не здивувався новинам?",a="Роріан і провід гаю вже знали про пересування культу островом, але досі вирішували тихо спостерігати, а не вступати у відкрите протистояння.",al={"чи роріан знав","реакція роріана","чому не здивувався"}},{q="Що буде після доповіді Роріанові?",a="Вислухавши вашу доповідь і подякувавши за допомогу Тендальському Гаю, Роріан посилає вас до Етін Вітрів — членкині Ради Старійшин, яка вже придивляється до вас.",al={"наступне завдання","що після повернення до роріана","після повернення до роріана"}},{q="Чому Яла лишилася на місці?",a="Яла Віндвотчер вирішила лишитися там, де точився бій, щоб розібратися з рештою недобитків, а вас послала вперед із невідкладними вістями.",al={"чому яла лишилася","куди пішла яла","роль яли віндвотчер"}}},fp="16,323,13.301.0,33.337.1,35.120.0,38.125.0,21.215.0,41.185.0,44.177.1,25.158.0"}
P.entries["quest:92470"] = {n="Лиха матріархиня",s="«Лиха матріархиня» — випробування на виживання, яке Етін Вітрів призначає молодим посвячуваним у Селі Тендаль. Треба спуститися в південні печери, прорідити урсер-падальників і вбити їхню люту матір лігва, Урс'ану. Завершене полювання доводить, що шукач пригод має досить рішучості, щоб зустріти більші небезпеки Острова Зефрас.",h="«Лиха матріархиня» — випробування на виживання, яке Етін Вітрів призначає молодим посвячуваним у Селі Тендаль.",kw={"лиха матріархиня","урс'ана","урсери","етін вітрів","печера тендаль","острів зефрас"},ang={["class:Hunter"]="Вистежити люту печерну матріарху на кшталт Урс'ани — початкове випробування знання звірів і бойової рішучості для молодих мисливців.",["race:Skyborne"]="Для посвячуваних Небороджених перемога над земними хижаками на кшталт Урс'ани доводить, що вони самостійні й на землі та готові вийти за межі свого відлюдного дому."},sec={{t="Випробування рішучості",b="Етін Вітрів пильно стежить за новачками, що стають на ноги довкола Села Тендаль. Щойно посвячуваний покаже першу вправність, Етін призначає небезпечний обряд посвяти: прямий наступ на хижих звірів, що загрожують околицям. Посвячуваного посилають не просто битися на відкритих стежках, а просто в темні печери на півдні — прорідити місцеві зграї урсер і зійтися з їхньою праматір'ю."},{t="Загроза Урс'ани",b="Місцеві рейнджери здавна помічали лютість урсер, але жодна з них не загрожує прихисткові більше, ніж Урс'ана — їхня грізна матріарха. Засівши глибоко в Печері Тендаль, вона керує своїми падальниками й люто боронить лігво. Принесена відтята голова — остаточний доказ того, що шукач пригод уміє впоратися з лютими звірами й готовий вийти за межі рідного гаю."}},faq={{q="Хто доручає вбити Урс'ану?",a="Етін Вітрів пропонує це випробування в Селі Тендаль. Вона придивляється до обдарованих новачків, які привернули увагу місцевих очільників на кшталт Роріана, а тоді перевіряє їхню звитягу цим небезпечним полюванням.",al={"хто дає лиху матріархиню","видавець лихої матріархині","хто етін вітрів"}},{q="Де шукати Урс'ану й урсер-стерв'ятників?",a="Урс'ана й урсери-стерв'ятники живуть у печерах на південь і південний захід від Села Тендаль, на пагорбах Тендальського Гаю. Сама матріархиня влаштувала лігво в найглибшій частині печери.",al={"місце урс'ани","де урс'ана","печера урсер зефраса","місце печери тендал"}},{q="Що таке урсера?",a="Урсери — агресивні ведмедеподібні хижаки, що водяться на диких скелях Острова Зефрас. Якщо їх не стримувати, їхні зграї влаштовують лігва небезпечно близько до таких поселень, як Село Тендаль.",al={"що таке урсера","переказ про урсер","чи урсери ведмеді"}},{q="Що означає це полювання для шукача пригод?",a="Убивство Урс'ани — вирішальний обряд посвяти. Здолавши і непроханих культистів, і найнебезпечніших звірів гаю, мисливець доводить, що готовий покинути безпечне Село Тендаль і взятися за ширші обов'язки на всьому Острові Зефрас.",al={"чому вбивати урс'ану","значення лихої матріархині"}}},fp="14,358,17.444.0,22.427.0,38.202.0,54.220.0,18.209.0,57.267.0"}
P.entries["quest:92471"] = {n="Етін Вітрів",s="Це завдання — обряд посвяти для молодих шукачів пригод на Острові Зефрас: їх посилають з'явитися до однієї з провідних владних осіб острова. Пройшовши перші випробування під наглядом Роріана Деньошукача, багатонадійну молодь посилають у Тендальський Гай до Етін Вітрів — старійшини, що читає вітри й оцінює нове покоління.",h="Це завдання — обряд посвяти для молодих шукачів пригод на Острові Зефрас: їх посилають з'явитися до однієї з...",kw={"етін вітрів","рада старійшин","тендальський гай","роріан деньошукач","шен'дорей","острів зефрас"},sec={{t="Міра можливостей",b="Перші завдання, які ставлять перед новачками на Острові Зефрас, — не просто буденні клопоти: це неофіційні випробування, що з'ясовують, чи має молодь досить витримки й духу, щоб боронити батьківщину. Розуміючи, що острів чекають дедалі тяжчі випробування, наставники на кшталт Роріана Деньошукача пильно придивляються до тих, хто здатен узяти на себе більшу відповідальність."},{t="Читачка вітрів із Тендальського Гаю",b="Глибоко в Тендальському Гаю перебуває Етін Вітрів, шанована членкиня Ради Старійшин, що править Островом Зефрас. Етін проводить час, читаючи течії повітря й оцінюючи юних шен'дорей, коли вони дорослішають. Стати перед нею — означає, що посвячуваний переріс дрібні вартові обов'язки на околицях і готовий протистояти прямим загрозам громаді."}},faq={{q="Хто така Етін Вітрів?",a="Етін Вітрів — одна з очільниць Острова Зефрас і членкиня Ради Старійшин. Вона стежить за вітрами в Тендальському Гаю й сама оцінює молодих шен'дорей, що досягли повноліття, аби переконатися, що вони готові боронити свій дім.",al={"хто така етін","роль етін вітрів","етін зефрас"}},{q="Чому Роріан посилає гравців до Етін?",a="Роріан Деньошукач оцінює новачків за їхніми першими дорученнями. Щойно шукач пригод доведе свою спроможність і витривалість, Роріан скеровує його до Етін, щоб та оцінила його вміння й спрямувала на серйозніші виклики, що постали перед островом.",al={"чому роріан посилає до етін","навіщо зустрічатися з етін","мета завдання"}},{q="Де знайти Етін Вітрів?",a="Вона мешкає в Тендальському Гаю на Острові Зефрас, де вивчає плин вітрів і наглядає за випробуваннями змужніння місцевої молоді.",al={"місце етін","де етін","етін у гаю тендал"}},{q="Що таке Рада Старійшин?",a="Рада Старійшин — керівний орган, що веде шен'дорей на Острові Зефрас. Очільники на кшталт Етін засідають у цій раді, щоб дбати про виживання, провід і готовність своєї громади.",al={"рада старійшин зефраса","хто керує зефрасом"}},{q="Що буде після доповіді Етін?",a="Переконавшись, що молодий шукач пригод готовий служити Острову Зефрас, Етін доручає йому серйозні завдання, пов'язані з небезпеками диких земель, — від агресивних звірів до лихих матріархинь.",al={"наступне завдання після етін","чого хоче етін"}},{q="Що означає «змужніння» для шен'дорей на Острові Зефрас?",a="Для молоді Острова Зефрас змужніння — це випробування сили тіла й магії. Це не просто обряд: молоді шен'дорей мусять показати свої вміння на ділі старійшині острова, як-от Етін, перш ніж стати до служби.",al={"змужніння шен'дорей","змужніння на зефрасі"}}},fp="20,339,22.384.0,32.371.0,28.241.0,45.260.0,40.155.0,30.195.0,40.207.0,62.260.0"}
P.entries["quest:92472"] = {n="Наступний крок",s="Коли нагальні загрози від звірів біля Села Тендаль усунуто, старійшина Етін Вітрів скеровує мандрівників на південь, до Села Шен'дар. Ця подорож знаменує перехід від винищення дикої звірини до протистояння організованому фанатизму культу Аль'Акет, що шанує Владику Вітрів Аль'Акіра.",h="Коли нагальні загрози від звірів біля Села Тендаль усунуто, старійшина Етін Вітрів скеровує мандрівників на...",kw={"наступний крок","етін вітрів","культ аль'акет","аль'акір","село шен'дар","острів зефрас"},ang={["class:Shaman"]="Шамани розуміють небезпеку сліпого поклоніння смертних владикам стихій на кшталт Аль'Акіра, чия мінлива вдача частіше вимагає покори, ніж рівноваги.",["race:Skyborne"]="Для Небороджених протистояння Аль'Акет — пряма боротьба зі стихійним фанатизмом, що загрожує безпеці їхніх рідних поселень по всьому Острову Зефрас."},sec={{t="Прощання з Селом Тендаль",b="Довівши свою спроможність у боротьбі з місцевими хижаками й матріархами, що допікають північній глушині Острова Зефрас, шукачі пригод отримують ширші обов'язки. Старійшина Етін Вітрів розуміє, що звичайне винищення шкідників — справа другорядна порівняно зі справжньою небезпекою, яка пускає коріння по всьому острову. Щоб захистити мешканців острова, вправних захисників треба послати на підтримку віддалених поселень."},{t="Нависла тінь культу",b="Головна небезпека для південного Зефраса — культ Аль'Акет. Ці безжальні фанатики присвятили себе Аль'Акірові, Владиці Вітрів, володареві стихійного світу — Небесної Тверді. Їхня дедалі більша сила безпосередньо загрожує Селу Шен'дар. У відповідь Етін посилає мандрівників на південь дорогою, повз засідки на нагір'ї, щоб підсилити місцеву варту Констебля Аонди."}},faq={{q="Куди веде ця подорож?",a="Дорога веде від Села Тендаль на південь, через Високогір'я Шен'дар, і закінчується в Селі Шен'дар, де місцеву оборону очолює Констебль Аонда.",al={"куди йти","наступний центр","призначення"}},{q="Хто така Констебль Аонда?",a="Констебль Аонда — цивільна й військова влада, що підтримує лад у Селі Шен'дар. Нині вона мусить захищати поселення від дедалі грізніших культистів.",al={"констебль аонда","хто така аонда"}},{q="Що таке культ Аль'Акет?",a="Аль'Акет — жорстокі фанатики з Острова Зефрас, що поклоняються Ал'Акірові, Володарю Вітрів, повелителеві стихії повітря з Небесної Тверді. Їхнє стрімке зростання — пряма загроза поселенням острова.",al={"хто такі аль'акет","переказ про культ аль'акет","сектанти"}},{q="Хто такий Ал'Акір?",a="Ал'Акір, Володар Вітрів, — повелитель небес серед стихій і господар Небесної Тверді. Його шанують повітряні елементалі, а культ Аль'Акет фанатично йому поклоняється.",al={"хто такий ал'акір","володар вітрів","правитель небесної стіни"}},{q="Чому старійшина Етін відсилає мандрівників із Тендаля?",a="Упоравшись із нагальними загрозами довкола Тендаля, Етін скеровує випробуваних захисників до Села Шен'дар, де наступ культу Аль'Акет становить куди більшу небезпеку для всього острова.",al={"чому залишати тендал","мета етін"}},{q="Які небезпеки чатують на дорозі до Села Шен'дар?",a="Стежка на південь пролягає Високогір'ям Шен'дар, де засідники Аль'Акет і зграї культистів-головорізів нападають на мандрівників між поселеннями острова.",al={"небезпеки дороги","подорож на південь","небезпека нагір'я"}}},fp="13,301,23.394.0,30.408.0,29.148.0,23.168.0,26.187.0,15.153.0,56.201.0,52.161.0"}
P.entries["quest:92473"] = {n="Агресивне вторгнення",s="«Агресивне вторгнення» — доручення від Валреа Вейлвінд захистити місцеве поселення від доведених до відчаю звірів. Урсери із сусіднього лігва дедалі зухваліше забрідають у село й загрожують його мешканцям.",h="«Агресивне вторгнення» — доручення від Валреа Вейлвінд захистити місцеве поселення від доведених до відчаю...",kw={"агресивне вторгнення","урсери","валреа вейлвінд","тендальський гай","рейнджери","голод"},ang={["class:Druid"]="Друїди відчують, що тендітна рівновага гаю порушена: раптова агресія й виснаження місцевих урсер вказують на приховану біду в місцевій природі.",["class:Hunter"]="Мисливці одразу зрозуміють небезпеку голодних хижаків: доведені голодом до відчаю звірі забувають природну обережність щодо поселень розумних істот."},sec={{t="Доведені до відчаю хижаки",b="Урсери, що гніздяться на південний захід від села, стали нагальною загрозою. Нещодавно голодний молодий звір підійшов аж до підніжжя центрального дерева-старійшини селища й мало не пошматував малу дитину, що гралася неподалік. Рейнджерам поселення довелося вбити звіра, перш ніж сталася трагедія."},{t="Проріджування гаю",b="Розуміючи, що на заселені землі цих хижаків жене голод, рейнджери наказали прорідити найвиснаженіших урсер у Тендальському Гаю. Знищуючи доведених до відчаю, недогодованих звірів, що нишпорять біля лігв, Рейнджери Гаю сподіваються спинити подальше вторгнення, доки не з'ясують, що тривожить місцеву звірину."}},faq={{q="Хто дає завдання «Агресивне вторгнення»?",a="Завдання дає Валреа Вейлвінд із проводу слідопитів, які пильнують гай і захищають сусіднє поселення від хижих звірів.",al={"хто дає агресивне вторгнення","видавець агресивного вторгнення","завдання валреа вейлвінд"}},{q="Чому урсери підходять так близько до села?",a="Урсери потерпають від голоду й відчаю, тож вирушають далеко за межі звичних мисливських угідь — аж у саме серце поселення.",al={"чому урсери нападають","агресія урсер","чому урсери злі"}},{q="Де шукати миршавих урсер?",a="Миршаві урсери никають Тендальським Гаєм на південний захід від села — вони тримаються ззовні, біля входів до лігва, а не в глибині печери.",al={"де миршаві урсери","місця урсер","ведмеді гаю тендал"}},{q="Який випадок мало не скінчився трагедією й спонукав до цього полювання?",a="Молода урсера вибрела просто до старого дерева посеред села й спробувала напасти на хлопчика, що грався поруч. Слідопити вбили звіра в останню мить і врятували дитині життя.",al={"що сталося в селі","напад урсер на хлопчика","хлопчик біля старого дерева"}},{q="Чому урсери поводяться так непередбачувано?",a="Слідопити помітили, що останнім часом урсери стали незвично агресивними, але що спричинило раптову нестачу їжі й зміну поведінки — досі невідомо.",al={"що змінилося в урсер","чому урсери голодують"}},{q="Який доказ вимагає Валреа Вейлвінд?",a="Валреа просить шість кігтів Миршавої Урсери, здобутих у виснажених звірів, що никають гаєм, — так вона знатиме, що з небезпечними хижаками впоралися.",al={"що збирати","мета агресивного вторгнення"}}},fp="23,232,19.322.0,17.371.0,35.155.0,53.155.0,38.150.0,37.189.0,43.186.0,41.151.0"}
P.entries["quest:92474"] = {n="Падати зі стилем",s="«Падати зі стилем» — вступний обряд посвяти для юних Небороджених у Селі Тендаль. Його пропонує на вершині місцевої сторожової вежі пустотлива Міріаал Міствейк: новачки мають випробувати свій вроджений дар повільного падіння, стрибнувши з помосту до Роріана Деньошукача внизу.",h="«Падати зі стилем» — вступний обряд посвяти для юних Небороджених у Селі Тендаль.",kw={"падати зі стилем","міріаал міствейк","роріан деньошукач","повільне падіння","небороджені","село тендаль"},ang={["race:Skyborne"]="Це перше випробування знайомить новачків-Небороджених із практичним боком і культурними суперечками довкола їхньої вродженої магії ходіння вітром."},sec={{t="Стрибок із вежі",b="Високо над Селом Тендаль на Острові Зефрас Міріаал Міствейк запрошує юних Небороджених випробувати свою спадщину в зухвалій грі. Замість берегти свої вроджені магічні дари як священні реліквії під суворим замком, Міріаал заохочує новачків стрибати з краю сторожової вежі просто в повітря. Мета і практична, і грайлива: опанувати чуттєве мистецтво ходіння повітрям, перш ніж життя за межами гаю вимагатиме цього в небезпечну мить."},{t="Різні вдачі",b="Ця вправа яскраво показує два протилежні погляди серед Небороджених. Міріаал обожнює раптові спуски й задля розваги лякає глядачів, а Роріан Деньошукач уособлює традиційну обережність. Коли новачки плавно опускаються просто перед ним, Роріан дорікає за безрозсудне видовище й застерігає: хто бездумно виснажує свої магічні дари, той може лишитися безпорадним, коли вдарить небезпека. Та все ж він визнає, що виважена практика в безпеці села має право на існування."}},faq={{q="Навіщо це завдання?",a="Завдання вчить молодих Небороджених користуватися природженою здібністю «Хода по повітрю» й керувати повільним спуском із висоти.",al={"що робить це завдання","мета падати зі стилем","навіщо це завдання"}},{q="Хто й де дає це завдання?",a="Його дає Міріаал Міствейк, що чекає на верхівці дерев'яної вартової вежі над Селом Тендаль на Острові Зефрас.",al={"хто дає завдання","де почати падати зі стилем","видавець падати зі стилем"}},{q="Перед ким ви приземляєтеся?",a="You land near Rorian the Dayseeker, whom Myriaal hopes to startle with the jump.",al={"біля кого приземлитися","хто такий роріан","здати падати зі стилем"}},{q="Чому Роріана засмучує цей стрибок?",a="Роріан вважає, що природжені магічні дари слід берегти й ставитися до них дисципліновано, а не марнувати на жарти, які лякають людей.",al={"чому роріан сердиться","реакція роріана","чому роріан лає"}},{q="Яку здібність тут тренують?",a="Завдання вчить користуватися «Ходою по повітрю» — природженою здібністю Небороджених, що сповільнює падіння й рятує від ушкоджень при ньому.",al={"яка здібність потрібна","завдання ходи по повітрю","расова здібність скайборнів"}},{q="Де це відбувається?",a="Вправа відбувається в Селі Тендаль на Острові Зефрас — у прадавніх краях, звідки починають свій шлях Небороджені.",al={"місце завдання","де село тендал","яка це зона"}}},fp="18,290,21.475.0,27.510.0,34.154.0,30.114.0,28.80.0,32.144.0,32.123.0,27.117.0"}
P.entries["quest:92481"] = {n="Учень арканної магії",s="«Учень арканної магії» — вступне випробування й виклик для чарівників-новачків на Острові Зефрас. Його започатковує Роріан Деньошукач, коли новачки доведуть свою вартість: молоді маги мають переглянути Сяйливий Кристал Повернення й з'явитися до місцевої наставниці, Дорі Брайтвіспер.",h="«Учень арканної магії» — вступне випробування й виклик для чарівників-новачків на Острові Зефрас.",kw={"учень арканної магії","дорі брайтвіспер","сяйливий кристал повернення","маги","небороджені","острів зефрас"},ang={["class:Mage"]="Це завдання знаменує офіційний початок вашого навчання під проводом Дорі Брайтвіспер і подає ваш магічний шлях як спробу відновити давно втрачені тайни народу хмар.",["race:Skyborne"]="Дорі підкреслює, що тисячоліття відокремленості серед хмар призвели до згасання тайних традицій, тож молоді учні — ключ до відродження культурної спадщини."},sec={{t="Послання в кристалі",b="Коли молоді маги допомогли впоратися з набридливими вульдренами, що чаїлися біля Тендальського Гаю, їм довіряють дивний артефакт — Сяйливий Кристал Повернення. Залишений Дорі Брайтвіспер, наставницею тайної магії острова, кристал — магічно записане послання, що має перевірити здібності посвячуваного й запросити його до глибшого вивчення містичних наук."},{t="Нове відкриття тайної магії",b="За словами Дорі Брайтвіспер, за довгі тисячоліття відлюдного життя високо серед хмар володіння тайною магією серед її народу поволі згасало. Дорі бачить у кожному новому практикові не просто учня, а необхідного першопрохідця, покликаного відновити втрачені знання й повернути колись могутню магічну спадщину її народу."}},faq={{q="Що таке Сяйливий Кристал Повернення?",a="Сяйливий Кристал Повернення — невеликий магічний фокус, який Дорі Брайтвіспер довірила Роріанові Деньошукачу. У ньому записано послання, що має познайомити молодих учнів з основами тайного зв'язку.",al={"кристал повернення","повідомлення кристала","що робить кристал"}},{q="Хто така Дорі Брайтвіспер?",a="Дорі Брайтвіспер — місцева наставниця магів, що перебуває в будівлі позаду Роріана Деньошукача в Тендальському Гаю на Острові Зефрас. Дорі веде молодих магів, які прагнуть повернути своєму народові давні тайні традиції.",al={"хто така дорі","наставниця магів зефраса","місце дорі"}},{q="Чому тайна магія занепала серед мешканців Зефрасу?",a="Як пояснює Дорі, тайні мистецтва поступово занепадали впродовж тисячоліть, які її народ прожив відлюдно серед хмар. Тож наставники на кшталт Дорі охоче навчають новачків, щоб ті шукали й повертали втрачене.",al={"чому магія згасла","арканні знання скайборнів","втрачена аркана"}},{q="Хто дає це завдання?",a="Роріан Деньошукач пропонує це завдання в Тендальському Гаю на Острові Зефрас, щойно майбутній маг виконає попереднє завдання «Рівновага в гармонії».",al={"хто дає завдання","хто починає учня арканної магії","завдання роріана"}},{q="Де знайти Дорі Брайтвіспер?",a="Дорі Брайтвіспер — у будівлі просто позаду Роріана Деньошукача в Тендальському Гаю.",al={"місце дорі брайтвіспер","де наставниця магів","знайти дорі"}},{q="Що треба виконати, перш ніж узятися за це завдання?",a="Спершу треба виконати «Рівновагу в гармонії» — розібратися з місцевими вульдренами для Роріана Деньошукача.",al={"попереднє завдання","передумови","яке завдання перед цим"}}},fp="23,290,20.366.0,24.333.0,35.224.0,27.223.0,55.245.0,21.150.0,37.103.0,63.121.0"}
P.entries["quest:92482"] = {n="Шлях мисливця",s="«Шлях мисливця» — вступне навчальне завдання для молодих мисливців у Тендальському Гаю на Острові Зефрас. Довівши свою вартість у боротьбі з місцевими вульдренами, юні слідопити отримують від Роріана Деньошукача вказівку з'явитися до Тай'рі Фарсайт, щоб почати справжнє навчання.",h="«Шлях мисливця» — вступне навчальне завдання для молодих мисливців у Тендальському Гаю на Острові Зефрас.",kw={"шлях мисливця","тай'рі фарсайт","роріан деньошукач","тендальський гай","мисливці","острів зефрас"},ang={["class:Hunter"]="Це завдання — важливий обряд посвяти для молодих мисливців Острова Зефрас, що офіційно починає їхнє навчання під проводом Тай'рі Фарсайт."},sec={{t="Поклик до полювання",b="Повернувшись після проріджування вульдренів, що бешкетували на околицях Тендальського Гаю, молоді мисливці бачать, що їхні вміння привернули увагу місцевих. Роріан Деньошукач передає їм нашвидкуруч нашкрябаний виклик від Тай'рі Фарсайт, наставниці мисливців гаю. Для рейнджерів-новачків, що вирушають у ширшу глушину Острова Зефрас, це означає перехід від простої оборони острова до справжньої бойової науки й науки виживання."},{t="Наука Тай'рі",b="Тай'рі Фарсайт, яку можна знайти неподалік від центру села, зустрічає багатонадійних учнів із суворим тверезим поглядом. Наголошуючи, що вижити в неприборканій природі можна лише з гострими чуттями й блискавичною реакцією, вона ділиться порадами, вистражданими за довгі роки власного досвіду. Її наставництво — перші основоположні кроки для кожного острівного слідопита, що прагне відточити влучність і вміння виживати."}},faq={{q="Хто дає це завдання?",a="Роріан Деньошукач пропонує це завдання в Тендальському Гаю на Острові Зефрас після того, як ви допоможете йому з навалою вульдренів у завданні «Рівновага в гармонії».",al={"хто дає шлях мисливця","видавець завдання","завдання роріана"}},{q="Хто така Тай'рі Фарсайт?",a="Тай'рі Фарсайт — місцева наставниця мисливців у Тендальському Гаю, що перебуває поблизу центру села. Вона опікується навчанням і вишколом майбутніх стрільців і слідопитів острова.",al={"де тай'рі","наставниця мисливців гаю тендал","місце тай'рі фарсайт"}},{q="Навіщо Нашкрябана Записка?",a="Нашкрябану Записку лишила Тай'рі Фарсайт, поки ви розбиралися з вульдренами. У ній вона просить вас знайти її на сільській площі, щоб почати поглиблене навчання.",al={"нашкрябана записка","що в записці","записка мисливця"}},{q="Де відбувається це завдання?",a="Це завдання повністю відбувається в Тендальському Гаю — поселенні на Острові Зефрас.",al={"зона завдання","місце завдання мисливця","де гай тендал"}},{q="Що треба виконати перед цим завданням?",a="Спершу треба виконати «Рівновагу в гармонії» для Роріана Деньошукача й довести свою спроможність, упоравшись з агресивними вульдренами біля гаю.",al={"передумова шляху мисливця","як відкрити","попереднє завдання"}},{q="Чого Тай'рі Фарсайт навчає молодих мисливців?",a="Тай'рі Фарсайт — ваша класова наставниця. Розмова з нею знайомить вас з основами острівного слідопитства й відкриває доступ до базових умінь і бойових прийомів мисливця.",al={"що робить тай'рі","чому говорити з тай'рі"}}},fp="21,298,21.442.0,23.374.0,21.161.0,24.190.0,42.192.0,33.101.0,54.157.0,45.185.0"}
P.entries["quest:92483"] = {n="Як удома в тінях",s="«Як удома в тінях» — вступне завдання для розбійників на Острові Зефрас. Допомігши Роріанові Деньошукачу в Тендальському Гаю, молоді розбійники отримують виклик і вирушають до свого місцевого наставника, Акері Даскблейда. Це завдання знаменує мить, коли юні розбійники переходять від звичайних сільських клопотів до серйозного навчання скритності й бою.",h="«Як удома в тінях» — вступне завдання для розбійників на Острові Зефрас.",kw={"як удома в тінях","акері даскблейд","розбійники","тендальський гай","роріан деньошукач","острів зефрас"},ang={["class:Rogue"]="Це завдання офіційно починає ваше навчання розбійника на Острові Зефрас і знайомить вас з Акері Даскблейдом у сторожовій вежі Тендальського Гаю."},sec={{t="Темне запрошення",b="Поки молоді розбійники розправляються з найпростішими загрозами довкола Тендальського Гаю, на них звертає увагу Акері Даскблейд — наставник розбійників у гаю. Замість відкрито походжати поселенням, Акері передає просту записку через Роріана Деньошукача. Роріан визнає: хоч Акері й поводиться підозріло, цей наставник розуміє, яких практичних умінь потрібно, щоб вижити за захищеними межами гаю."},{t="Уроки у сторожовій вежі",b="Сховавшись у сільській сторожовій вежі, Акері Даскблейд не тратить часу на ввічливості. Щойно новачок з'являється, він одразу оцінює, як той ступає й наскільки пильний, і застерігає: недбалий крок за межами Тендальського Гаю веде просто в ранню могилу. Витримавши прискіпливий погляд Акері, розбійник робить свій перший офіційний крок до опанування скритності, точності й виживання на Острові Зефрас."}},faq={{q="Хто дає завдання «Як удома в тінях»?",a="Роріан Деньошукач пропонує це завдання в Тендальському Гаю на Острові Зефрас, коли ви виконаєте «Рівновагу в гармонії».",al={"хто починає як удома в тінях","видавець як удома в тінях","завдання роріана"}},{q="Де знайти Акері Даскблейда?",a="Акері Даскблейд — у сільській вартовій вежі в Тендальському Гаю на Острові Зефрас.",al={"місце акері даскблейда","де акері даскблейд","знайти акері"}},{q="Що за Проста Записка, яку дають у цьому завданні?",a="Просту Записку лишив Акері Даскблейд: він запрошує до себе обдарованих розбійників. Щоб виконати завдання, її треба прочитати, перш ніж говорити з Акері.",al={"проста записка зефрас","що за записка","прочитати просту записку"}},{q="Чи доступне це завдання всім класам?",a="Ні, це завдання лише для розбійників, що опановують своє ремесло в Тендальському Гаю.",al={"чи не розбійники можуть це","чи це лише для розбійників","вимога класу"}},{q="Чого навчає Акері Даскблейд?",a="Акері Даскблейд — місцевий наставник розбійників у Тендальському Гаю: він навчає скрадання, хитрощів і володіння клинком новачків, що вирушають у мандри Островом Зефрас.",al={"роль акері даскблейда","хто такий акері","наставник розбійників гаю тендал"}},{q="Яке завдання треба виконати спершу?",a="Спершу треба виконати «Рівновагу в гармонії» для Роріана Деньошукача — лише тоді він передасть вам записку від Акері.",al={"передумова як удома в тінях","попереднє завдання","як відкрити як удома в тінях"}}},fp="22,341,18.406.0,25.391.0,43.111.0,33.90.0,47.168.0,39.89.0,32.182.0,48.103.0"}
P.entries["quest:92484"] = {n="Прийняти стихії",s="«Прийняти стихії» — вступне завдання для шаманів у Тендальському Гаю на Острові Зефрас. Його дає Роріан Деньошукач, скеровуючи молодих послідовників до Вітротворця Боро, місцевого наставника шаманів. Воно відкриває тиху прірву, що пролягла між місцевим народом і стихійними духами вітрів.",h="«Прийняти стихії» — вступне завдання для шаманів у Тендальському Гаю на Острові Зефрас.",kw={"прийняти стихії","вітротворець боро","шамани","духи вітрів","тендальський гай","острів зефрас"},ang={["class:Shaman"]="Це завдання — перше офіційне знайомство посвячуваного з Вітротворцем Боро, яке відкриває трагічне мовчання стихійних вітрів і довічні пошуки відновленого єднання.",["faction:Horde"]="Для мандрівників з Орди, що навідуються на Острів Зефрас, це завдання показує особливі труднощі острівних закличників стихій порівняно з традиціями землі й духів на материку."},sec={{t="Поклик стихій",b="Коли молоді шамани допомогли впоратися з набридливими вульдренами довкола села, до них звертається Роріан Деньошукач. Поки вони були в полі, Вітротворець Боро лишив гудючий кристал повернення — знак того, що час починати справжнє навчання стихійному мистецтву в серці гаю."},{t="Мовчазні вітри",b="Під час зустрічі Вітротворець Боро розповідає про тяжкий стан місцевого шаманства. Духи чотирьох вітрів багато років тому раптово обірвали зв'язок і зреклися давнього єднання. Відтоді шамани Зефраса присвячують себе глибокому вивченню світу природи, сподіваючись суворим вишколом подолати мовчання й знову схилити духів до розмови."}},faq={{q="Хто дає завдання «Прийняти стихії»?",a="Завдання дає Роріан Деньошукач у Тендальському Гаю на Острові Зефрас — одразу після того, як ви допоможете розв'язати місцеву проблему з вульдренами.",al={"видавець прийняти стихії","хто починає прийняти стихії"}},{q="Де знайти Вітротворця Боро?",a="Вітротворець Боро — поблизу центру Тендальського Гаю на Острові Зефрас: він місцевий наставник шаманів.",al={"місце вітротворця боро","де боро","знайти вітротворця боро"}},{q="Чому духи стихій перестали говорити з тутешніми мешканцями?",a="За словами Вітротворця Боро, духи стихій багато років тому раптово урвали будь-яку розмову й покинули народ. Місцеві шамани й досі не розуміють до кінця, чому стався цей розрив, але продовжують навчання в надії відновити втрачений зв'язок.",al={"чому вітри мовчать","духи чотирьох вітрів мовчать","що сталося з духами вітру"}},{q="Що таке Гудючий Кристал Повернення?",a="Гудючий Кристал Повернення лишив Вітротворець Боро, поки ви допомагали поселенню. Оглянувши його, ви засвідчуєте готовність почати навчання стихій під проводом Боро.",al={"гудючий кристал повернення","кристал повернення зефрас"}},{q="Яке завдання веде до «Прийняти стихії»?",a="Воно йде після завдання «Рівновага в гармонії», де ви розбираєтеся з вульдренами, що порушують спокій в околицях.",al={"передумова прийняти стихії","що перед прийняти стихії"}},{q="Яку роль Вітротворець Боро відіграє в Тендальському Гаю?",a="Вітротворець Боро — наставник шаманів громади: він веде новопосвячених шляхом єднання зі стихіями й пізнання природи.",al={"що робить боро","роль вітротворця боро"}}},fp="22,301,25.298.0,16.367.0,43.140.0,33.129.0,63.252.0,35.199.0,56.105.0,53.138.0"}
P.entries["quest:92485"] = {n="Учень природи",s="«Учень природи» — початок офіційного навчання молодого друїда на Острові Зефрас. Допомігши відновити місцеву гармонію, друїди-новачки отримують виклик від Ксайтона Сільвервінда під гіллям Тендальського Гаю. Це брама до розуміння глибшої рівноваги між рослинами й тваринами острова.",h="«Учень природи» — початок офіційного навчання молодого друїда на Острові Зефрас.",kw={"учень природи","ксайтон сільвервінд","друїди","тендальський гай","роріан деньошукач","острів зефрас"},ang={["class:Druid"]="Цей обряд посвяти прямо пов'язує вас із Ксайтоном Сільвервіндом і починає ваше довічне навчання мистецтву дикої природи, ікла й гілки."},sec={{t="Виклик із гаю",b="Після того як місцеві негаразди, спричинені надто завзятою звіриною, вщухли, Роріан Деньошукач передає юним посвячуваним особисте запрошення. Складений пергамент, який лишив місцевий наставник Ксайтон Сільвервінд, запрошує майбутніх друїдів вийти вперед і присвятити себе глибшим таємницям дикої природи. Це знак того, що природні таланти посвячуваного помітили старійшини гаю."},{t="Хранителі живого полотна",b="Зустріч із Ксайтоном Сільвервіндом на нижньому ярусі великого дерева в Тендальському Гаю міцно прив'язує новачка до його покликання. Сільвервінд бачить у буйній флорі й фауні Острова Зефрас хитромудре живе полотно, яке потребує постійного збереження й пильної рівноваги. Іти шляхом ікла, пазура, пера й гілки можна лише з тривалим наставництвом, і ця зустріч знаменує справжній початок довічного опікування природою."}},faq={{q="Хто посилає гравця до Ксайтона Сільвервінда?",a="Роріан Деньошукач передає складений пергамент, що скеровує вас до Ксайтона Сільвервінда, після того як ви допоможете розв'язати проблему з вульдренами довкола гаю.",al={"хто дає учня природи","видавець","роріан"}},{q="Де знайти Ксайтона Сільвервінда?",a="Ксайтон Сільвервінд — на нижньому ярусі великого дерева в Тендальському Гаю, просто позаду Роріана Деньошукача на Острові Зефрас.",al={"місце ксайтона сільвервінда","де ксайтон","місце наставника друїдів"}},{q="Навіщо це завдання?",a="Це завдання знайомить молодих друїдів з їхнім класовим наставником Ксайтоном Сільвервіндом, який стає їхнім головним учителем і провідником у підтриманні природної рівноваги Острова Зефрас.",al={"навіщо це завдання","мета завдання","початок навчання друїда"}},{q="Чого Ксайтон Сільвервінд навчає молодих друїдів про Острів Зефрас?",a="Сільвервінд учить, що рослинний і тваринний світ острова — тонке, взаємопов'язане плетиво, яке потребує дбайливого догляду й рівноваги, що її підтримують дисципліною ікла, кігтя, пера й гілки.",al={"що каже ксайтон","рівновага природи зефраса","роль друїда на зефрасі"}},{q="Що треба виконати, перш ніж отримати цей виклик?",a="Новачки мусять спершу виконати «Рівновагу в гармонії» для Роріана Деньошукача — приборкати неслухняних вульдренів, — і лише тоді отримають записку від Сільвервінда.",al={"передумова","попереднє завдання","перед учнем природи"}},{q="Що написано в Складеному Пергаменті?",a="Складений Пергамент — записка від самого Ксайтона Сільвервінда, у якій він велить обдарованому молодому друїдові знайти його для подальшого навчання під кроною великого дерева.",al={"складений пергамент","записка сільвервінда","що на пергаменті"}}},fp="19,323,24.408.0,23.428.0,41.149.0,34.139.0,34.175.0,66.196.0,66.153.0,46.175.0"}
P.entries["quest:92532"] = {n="Шлях воїна",s="«Шлях воїна» — вступне бойове завдання для молодих бійців на Острові Зефрас. За вказівкою, переданою через Роріана Деньошукача, юні воїни вирушають до Майстрині Клинка Рен у сторожовій вежі Села Тендаль. Рен готова навчати бою й дисципліни тих, хто готовий стати щитом для свого народу.",h="«Шлях воїна» — вступне бойове завдання для молодих бійців на Острові Зефрас.",kw={"шлях воїна","майстриня клинка рен","воїни","село тендаль","роріан деньошукач","острів зефрас"},ang={["class:Warrior"]="Це завдання офіційно починає вашу бойову освіту в Селі Тендаль і знайомить вас із Майстринею Клинка Рен — вашою наставницею."},sec={{t="Виклик до сторожової вежі",b="Повернувшись до Роріана Деньошукача в Село Тендаль після того, як відновили рівновагу поблизу, майбутні бійці дізнаються, що їх помітила майстриня клинка поселення. Роріан передає зім'яту записку, написану самою Рен, із проханням до новачка знайти її особисто. Високо над поселенням, у сільській сторожовій вежі, Рен пильно стежить і за кордонами острова, і за новобранцями, які колись їх боронитимуть."},{t="Тягар захисника",b="У сторожовій вежі воїн знайомиться з бойовою філософією Майстрині Клинка Рен. Для Рен бойова майстерність — не просто вправа в грубій силі, а життєво важливий обов'язок вести, витримувати й захищати в дедалі непевнішому світі. Вона обіцяє новобранцеві свій провід, поки той відточує вміння, і пропонує суворий вишкіл, доки він не стане досить сильним, щоб зустріти більші небезпеки, які загрожують їхньому дому."}},faq={{q="Хто посилає мене до Майстрині Клинка Рен?",a="Роріан Деньошукач скеровує вас до Майстрині Клинка Рен після того, як ви виконаєте доручення в Селі Тендаль. Поки вас не було, Рен окремо попросила Роріана прислати вас до її вартової вежі, щойно ви повернетеся.",al={"хто починає це","видавець","роль роріана"}},{q="Де знайти Майстриню Клинка Рен?",a="Майстриня Клинка Рен — у вартовій вежі Села Тендаль на Острові Зефрас: звідти вона наглядає за селом і навчає молодих воїнів.",al={"де майстриня клинка рен","місце рен","сторожова вежа тендал"}},{q="Що таке Зім'ята Записка?",a="Зім'ята Записка — особистий виклик, який Роріан передає вам від імені Майстрині Клинка Рен: прочитавши його, ви маєте з'явитися до вартової вежі Села Тендаль на справжній бойовий вишкіл.",al={"зім'ята записка","що в записці","записка рен"}},{q="Чого Майстриня Клинка Рен навчає молодих воїнів?",a="Майстриня Клинка Рен наголошує на пильності, проводі й захисті. Вона нагадує учням: що більше світ змінюється й що грізніші небезпеки, то твердішою має бути воля воїна стати між бідою і своїм народом.",al={"навчання рен","чого вчить рен","мета воїна"}},{q="Чи обов'язкове це завдання для навчання воїнів на Острові Зефрас?",a="Це офіційне знайомство з вашою класовою наставницею в Селі Тендаль: завдання веде вас просто до Майстрині Клинка Рен, тож ви знатимете, куди повертатися по нові бойові прийоми.",al={"чи обов'язкове завдання","чи треба його робити","вступ наставника воїнів"}},{q="Що означають слова Рен «хай вітри ведуть тебе»?",a="Це традиційне благословення, що відображає острівну культуру Острова Зефрас: так мандрівникам бажають безпечної дороги, зосередженості й удачі, коли вони вирушають у незнайомі й небезпечні краї.",al={"хай вітри ведуть тебе значення","цитата про вітер","прощання рен"}}},fp="18,343,27.444.0,24.412.0,37.201.0,33.145.0,26.197.0,47.202.0,60.178.0,48.180.0"}
P.entries["quest:92544"] = {n="Головорізи Аль'Акет",s="Мирним дорогам довкола Тендальського Гаю загрожує жорстока банда культистів Аль'Акет, що засіла в сусідніх руїнах храму. Послані зі Святині Акіра з наказом тероризувати мандрівників і силоміць вербувати новобранців, ці фанатики — безпосередня небезпека для місцевих подорожніх. Ганаа Найтвінд доручає шукачам пригод зламати їхню владу й убити їхнього грубого командира.",h="Мирним дорогам довкола Тендальського Гаю загрожує жорстока банда культистів Аль'Акет, що засіла в сусідніх...",kw={"головорізи аль'акет","малдуко клаудкраш","ганаа найтвінд","святиня акіра","лортуна","тендальський гай"},sec={{t="Розбишаки-культисти в руїнах",b="На південний захід від Тендальського Гаю лежать прадавні руїни храму, що мали б давати мандрівникам тихий прихисток. Натомість ці землі захопили Аль'Акет — войовничий культ, гнаний фанатичними амбіціями. Ці культисти аж ніяк не мирні вірні: вони розбійничають на дорогах і силою насаджують свою волю, полюючи на тих, хто мандрує околицями гаю. Рейнджери, що стоять неподалік, підозрюють, що цих розбишак прислала просто Верховна Жриця Лортуна зі Святині Акіра, щоб залякати місцевих і змусити їх скоритися впливові культу."},{t="Малдуко Клаудкраш",b="Ватагою в руїнах храму верховодить Малдуко Клаудкраш — жорстокий ватажок, що насильством і страхом тримає в покорі і своїх послушників, і нічого не підозрюючих мандрівників. Маючи під рукою громил і щойно навернених неофітів, Малдуко звів войовничу заставу просто на порозі Тендальського Гаю. Знищивши Клаудкраша й розігнавши його поплічників, Ганаа Найтвінд сподівається зламати впевненість культу й послати ясне застереження: фанатизму й примусу в цих землях не терпітимуть."}},faq={{q="Хто такі Аль'Акет?",a="Аль'Акет — фанатичний культ, що діє на Зефрасі. Під проводом таких постатей, як Верховна Жриця Лортуна зі Святині Акіра, культисти силою, залякуванням і насильством змушують місцевих мандрівників і мешканців вступати до своїх лав.",al={"хто такі аль'акет","культ аль'акет","хто аль'акет"}},{q="Чому культисти нападають на Тендальський Гай?",a="Вони отаборилися в руїнах храму на південний захід від Тендальського Гаю, щоб влаштовувати засідки на мандрівників, які покидають околиці. Тероризуючи подорожніх на дорозі, вони сподіваються тиском і примусом схилити місцевих мешканців до покори культові.",al={"чому сектанти в гаю","чому гай тендал","мотив сектантів"}},{q="Хто такий Малдуко Клаудкраш?",a="Малдуко Клаудкраш — жорстокий громило, що очолює табір Аль'Акет у руїнах храму. Ганаа Найтвінд називає його чудовиськом: він керує головорізами й неофітами, що полюють на подорожніх на ближніх дорогах.",al={"малдуко","клаудкраш","хто такий малдуко клаудкраш"}},{q="Хто така Ганаа Найтвінд?",a="Ганаа Найтвінд — одна зі слідопитів, що охороняють Тендальський Гай. Вона стоїть на посту біля дороги, щоб попереджати мандрівників про засідку культистів неподалік, і покладається на вправних шукачів пригод, які усунуть загрозу.",al={"ганаа","ганаа найтвінд","видавець"}},{q="Хто послав цих культистів до руїн?",a="Ганаа підозрює, що їх прислала Верховна Жриця Лортуна, яка керує діями культу зі Святині Акіра.",al={"хто ними командує","ватажок культу","хто послав малдуко"}},{q="Що ще можна знайти біля руїн храму?",a="Окрім табору Аль'Акет, у прадавніх руїнах у південно-західній частині місцини є активна лінія сили.",al={"лінія сили руїн","таємниця руїн храму","руїни на південному заході"}}},fp="14,388,29.542.0,18.527.0,21.243.0,45.230.0,26.195.0,23.212.0,37.117.0,45.124.0"}
P.entries["quest:92597"] = {n="Читання ліній сили",s="«Читання ліній сили» — обряд посвяти для юних Небороджених, що відкривають свою магічну спадщину Високородних. За дорученням Фалорна Фоллвінда на Острові Зефрас посвячувані вирушають до стоячих каменів у Тендальському Гаю, щоб відчути сирі чародійські течії, які пульсують крізь стихійну землю, і зачерпнути з них сили.",h="«Читання ліній сили» — обряд посвяти для юних Небороджених, що відкривають свою магічну спадщину Високородних.",kw={"читання ліній сили","фалорн фоллвінд","лінії сили","високородні","тендальські стоячі камені","острів зефрас"},ang={["class:Mage"]="Для тих, хто опановує тайні мистецтва, відкриті лінії сили — безцінне джерело неприборканої сили серед довкілля, де панують стихійні бурі.",["race:Skyborne"]="Цей обряд пробуджує ваше вроджене високородне походження й навчає спрямовувати підземну силу ліній просто у ваші чари."},sec={{t="Тайні течії стихійного світу",b="Навіть у вітряних межах стихійного світу під землею пролягають приховані тайні русла. Поки Островом Зефрас блукають дивні елементалі й ворожі Аль'Акет, підземні лінії сили почали пробиватися на поверхню. Для тих, хто володіє магією, ці прориви — прямий доступ до неприборканих чародійських запасів, що дають силу кожному, хто має потрібну кров і знання, щоб їх спрямовувати."},{t="Спадок Високородних",b="Фалорн Фоллвінд закликає посвячуваних прийняти своє високородне походження, а не благати милості в духів вітру, як місцеві Вітротворці чи фанатики Аль'Акет. На думку Фоллвінда, вижити серед суворих сил стихійного світу можна не випрошуючи милосердя в чужих істот, а опанувавши внутрішню чародійську силу, що тече в них під ногами."},{t="Тендальські Стоячі Камені",b="На північний схід від поселення лежить Тендальський Гай, де прадавні стоячі камені позначають потужне сплетіння ліній сили. Оточене збуреними вітрами й наверненими Аль'Акет, це відкрите місце магічних течій дає посвячуваним змогу налаштувати чуття, злитися з пульсом лінії сили й розкрити всю повноту своїх природних расових здібностей."}},faq={{q="Хто дає завдання «Читання ліній сили»?",a="Завдання дає Фалорн Фоллвінд на Острові Зефрас молодим Небородженим, що вчаться опановувати свої родові тайні здібності.",al={"видавець","фалорн фоллвінд","хто починає читання ліній сили"}},{q="Де лінія сили?",a="Лінія сили — на північному сході, біля Тендальських Стоячих Каменів у Тендальському Гаю, серед ворожих елементалів і навернених Аль'Акет.",al={"місце лінії сили","де гай тендал","каміння гаю тендал"}},{q="Чому лінії сили є навіть у Царстві Стихій?",a="Приховані тайні канали пронизують землю навіть тут, у Царстві Стихій. Останнім часом ці лінії сили почали проступати на поверхню, і Небороджені дістали прямий доступ до потужних потоків сили.",al={"аркана в стихійній площині","лінії сили в царстві стихій"}},{q="Як Фалорн Фоллвінд ставиться до Вітротворців?",a="Фалорн зневажає Вітротворців: їхнє шанування духів повітря він вважає жалюгідним благанням до байдужих стихійних сутностей, нічим не кращим за поклоніння Аль'Акет.",al={"фалорн про вітротворців","переказ про вітротворців","вітротворці й високородні"}},{q="Яка здібність потрібна, щоб скористатися лінією сили?",a="Для завдання треба застосувати расову здібність Небороджених «Прочитати лінію сили», стоячи в осерді енергії біля стоячих каменів.",al={"здібність читання лінії сили","як читати лінію сили","расова здібність"}},{q="Що дає доступ до ліній сили?",a="Єднання з відкритими лініями сили спрямовує в того, хто до них звертається, сиру тайну енергію: вона посилює його магічну міць і дає різні ефекти залежно від природи каналу.",al={"що роблять лінії сили","користь ліній сили"}}},fp="21,298,38.429.0,16.379.0,24.352.0,42.128.0,30.149.0,49.203.0,47.180.0,49.137.0,49.178.0"}
P.entries["quest:92598"] = {n="Дар Небозору",s="«Дар Небозору» — один із перших обрядів посвяти для юних Вітротворців, що вчаться приборкувати свій вроджений зв'язок зі світом духів. За вказівкою Вентаарі Брайтвіш посвячувані вирушають до Сплетіння Стихій, щоб пробудити своє чуття й послухати шепіт духів напряму.",h="«Дар Небозору» — один із перших обрядів посвяти для юних Вітротворців, що вчаться приборкувати свій вроджений...",kw={"дар небозору","небозір","вентаарі брайтвіш","вітротворці","сплетіння стихій","тендальський гай"},ang={["class:Shaman"]="Шамани впізнають у Сплетінні Стихій священну землю, де межа між волею смертних і стихійними світами найтонша.",["faction:Horde"]="Як союзниця на Острові Зефрас, Орда покладається на надприродне передбачення Вітротворців, щоб долати незвідані небезпеки острова.",["race:Skyborne"]="Для Небороджених Небозір — не просто дивовижний хист, а право від народження, дароване стихійними покровителями, на якому тримається їхня культурна й духовна самобутність."},sec={{t="Священне чуття",b="Вітротворці мають вроджений зв'язок зі стихійними силами, що формують їхній світ, і втілює його священна здатність, відома як Небозір. Цей дар дає смертним чуттям налаштуватися на духовні хвилі й перекинути місток між живими й невидимим. Вітротворець може пробудити цей внутрішній зір будь-де в глушині, але біля місць зосередженої сили зв'язок поглиблюється, відкриваючи співзвучні дари й приховану мудрість, яку шепоче вітер."},{t="Сплетіння Стихій у Тендальському Гаю",b="На північний схід від поселення, серед прадавніх стоячих каменів, у Тендальському Гаю лежить Сплетіння Стихій. Такі місця — осередки, де збираються сирі сили й затримуються духи. Вентаарі Брайтвіш посилає новачків до цього священного місця не просто виконати доручення, а випробувати їхню духовну міць. Як і будь-яка здатність тіла чи розуму, Небозір потребує свідомої вправи, щоб дозріти, — тоді молодий Вітротворець зможе тлумачити мінливі знамення стихій, від яких залежить виживання його народу."}},faq={{q="Навіщо це завдання?",a="Завдання навчає молодих Вітротворців застосовувати на практиці здібність «Небозір». Вентаарі Брайтвіш посилає новачків до Стихійного Злиття, щоб вони відчули, як сила місця посилює їхнє духовне чуття.",al={"мета дару небозору","навіщо це завдання","навчання небозору"}},{q="Хто такий Вентаарі Брайтвіш?",a="Вентаарі Брайтвіш — духовний провідник і наставник, що опікується першими кроками Вітротворців на Острові Зефрас і вчить їх шанувати й розвивати свою стихійну спадщину.",al={"вентаарі","хто такий вентаарі брайтвіш","брайтвіш"}},{q="Що таке Стихійне Злиття?",a="Стихійне Злиття — осередок зосередженої духовної енергії, який часто позначають прадавні стоячі камені. Такі місця самі собою притягують духів стихій і посилюють здібності на кшталт «Небозору».",al={"що таке стихійне злиття","переказ про стихійне злиття","злиття гаю тендал"}},{q="Де Стихійне Злиття?",a="Злиття — серед стоячих каменів у Тендальському Гаю, трохи на північний схід від поселення на Острові Зефрас.",al={"де стихійне злиття","місце гаю тендал","місце каміння"}},{q="Чи можна користуватися «Небозором» будь-де?",a="Так. Вітротворець може вдатися до «Небозору» будь-де, але в Стихійному Злитті він отримує значно сильніше благо, а ще — додаткові прозріння від духів поблизу.",al={"чи можна небозір будь-де","небозір поза злиттям","де користуватися небозором"}},{q="Чому «Небозір» вважають необхідним для виживання?",a="«Небозір» долає прірву між смертними й духами стихій. За словами Вентаарі, уміння бачити й дослухатися до попереджень стихій — вирішальне, щоб оминати небезпеки, що насуваються, і вберегти свій народ.",al={"чому небозір важливий","небозір і виживання","виживання серед стихій"}}},fp="20,306,19.463.0,32.541.0,34.233.0,27.175.0,33.203.0,43.126.0,30.178.0,50.219.0"}
P.entries["quest:926"] = {n="Недосконалий Камінь Сили",s="Глибоко на посушливих просторах Пусток на магічних столах лежать загадкові камені, насичені магічною енергією. Навмисно створені зі смертельними вадами, ці нестійкі реліквії швидко пожирають власну силу, щойно їх відділяють від джерела.",h="Глибоко на посушливих просторах Пусток на магічних столах лежать загадкові камені, насичені магічною енергією.",kw={"недосконалий камінь сили","камені сили","магія","демонське сім'я","ак'зелот","пустки"},ang={["faction:Horde"]="Орда пильно стежить за магічними дивовижами, розкиданими по Пустках, остерігаючись свавільного чаклунства, що може загрожувати її шляхам постачання."},sec={{t="Нестійка робота",b="Недосконалі камені сили, розкидані по Пустках, — цікаві магічні аномалії. Хоч вони безперечно заряджені магічною суттю, їхню будову навмисно спотворили під час створення. Чиї б руки їх не виготовили, вони подбали, щоб камені лишалися вкрай нестійкими й за лічені миті після того, як їх візьмуть до рук, перетворювалися на мертву речовину."},{t="Енергія, що пожирає себе",b="Замість того щоб бути стійкими сховищами чи каталізаторами, ці камені одразу починають спалювати свою силу, щойно їх знімають з обрядових столів, де вони лежать. Через цю самопожиральну природу ніхто не може віднести їх далеко."}},faq={{q="Що таке Недосконалий Камінь Сили?",a="Недосконалий Камінь Сили — нестійкий предмет, заряджений сирою магічною силою. Його навмисно створили з вадами: щойно камінь зрушити з місця, він швидко витрачає свою енергію й поглинає сам себе.",al={"недосконалий камінь сили","що за камінь","переказ про камінь сили"}},{q="Чи можна зберегти камені назавжди?",a="Ні. Щойно камінь забрати зі столу, звідки він черпає стійкість, його магічна структура руйнується й швидко вичерпує власні запаси енергії.",al={"лишити недосконалий камінь","чи можна зберегти","зберегти камінь"}},{q="Хто користується цими каменями?",a="Камені готує чорнокнижник Ак'Зелот, а шукачі пригод з Орди за його дорученням несуть їх до вогняного вівтаря на Піку Жахливої Імли, щоб розірвати зв'язок Демонського Сім'я з Палаючим Легіоном.",al={"хто зробив камені сили","хто їх виготовив","творці каменів"}},{q="Чому вони важливі для Орди?",a="Тут ці камені — зброя Орди проти Палаючого Легіону. Ак'Зелот, діючи від імені Ніру Файрблейда, підготував їх так, щоб камінь, донесений до вогняного вівтаря на Піку Жахливої Імли, розірвав зв'язок Демонського Сім'я з Легіоном.",al={"інтерес орди","чому орді це потрібно"}}},fp="18,246,22.336.0,21.259.0,29.197.0,40.137.0,22.187.0,35.233.0"}
P.entries["quest:9260"] = {n="Розслідуй Погибель Стормвінда",s="Навала Погибелі принесла жахи Короля-Ліча просто до брами Стормвінда. За мурами столиці некрополі кидають тінь на землю, а потвори нежиті й культисти чаклують темну магію. Лейтенант Оррін набирає вправних захисників, щоб вибити загарбників, зібрати Некротичні Камені й розгадати зловісні рунічні кола, що пульсують біля їхніх таборів.",h="Навала Погибелі принесла жахи Короля-Ліча просто до брами Стормвінда.",kw={"погибель","навала","лейтенант оррін","некрополь","король-ліч","некротичний камінь","стормвінд"},ang={["class:Paladin"]="Сутичка з Погибеллю просто під Стормвіндом покладає на паладинів нагальний обов'язок — обрушити святий гнів на некромантські кола й захистити люд королівства.",["class:Priest"]="Спотворений шепіт у рунах навали дає жерцям змогу зазирнути в саму суть розтлінної магії Тіні, що скріплює передові сили Погибелі.",["faction:Alliance"]="Оборона брами Стормвінда від навали Погибелі — для Альянсу питання виживання: вона доводить, що навіть південна твердиня в межах досяжності Короля-Ліча."},sec={{t="Нежить на порозі столиці",b="Поява сил Погибелі так близько до Стормвінда — тривожний удар для королівства. Над головами нависають летючі некрополі, а шкандибала нежить і зловісні культисти закріплюються просто на порозі найбільшого бастіону людства. Лейтенант Оррін згуртовує захисників за міськими мурами, щоб відкинути цих загарбників, перш ніж вони прорвуть оборону столиці."},{t="Шепітливі руни",b="Мало просто відбиватися від ходячих мерців: завдання вимагає дослідити сяйливі рунічні кола, викарбувані в землі довкола ворожих таборів. Ці окультні кола потріскують тією самою лихою магією, що струменить від некрополів угорі. Ступивши в їхнє сяйво, можна почути моторошний шепіт, що висить у повітрі, — неприродні голоси свідчать, що кола слугують провідниками темного зв'язку, через який керують навалою."}},faq={{q="Хто такий Лейтенант Оррін?",a="Лейтенант Оррін — офіцер, що організовує оборону під стінами Стормвінда. Діючи разом зі Срібним Світанком, він гуртує місцевих бійців, щоб збирати відомості й руйнувати плацдарми Погибелі, які загрожують місту.",al={"оррін","лейтенант оррін","хто дає це завдання"}},{q="Чому Погибель нападає на Стормвінд?",a="Король-Ліч розіслав летючі некрополі й загарбницькі війська по всьому Азероту, щоб сіяти жах і поповнювати лави нежиті. Стормвінд — один із головних осередків опору живих, тож він стає першочерговою ціллю цих нападів.",al={"чому погибель нападає","вторгнення погибелі у стормвінд","чому атакують стормвінд"}},{q="Що таке сяйливі рунічні кола?",a="Рунічні кола — ритуальні знаки, які Погибель накреслила біля своїх передових таборів. Вони пульсують темною некромантичною силою й шепочуть неприродними голосами: загарбники користуються ними як магічними ретрансляторами для таємного зв'язку.",al={"рунічні кола","сяйливі руни","що роблять кола"}},{q="Що таке Тьмяні Некротичні Камені?",a="Тьмяні Некротичні Камені — магічні фокуси, які носять при собі нижчі загони вторгнення Погибелі. Вони випромінюють залишкову некротичну енергію і правлять водночас за доказ знищених загарбників і за дивовижу, що цікавить Срібний Світанок.",al={"тьмяний некротичний камінь","некротичні камені","що таке некротичні камені"}},{q="Яку роль у цьому завданні відіграє Срібний Світанок?",a="Срібний Світанок — незалежний орден, що поставив собі за мету викорінювати Погибель скрізь, де вона з'являється. Лейтенант Оррін діє від його імені: він здобуває відомості й камені, щоб допомогти ширшій війні ордену проти армій Короля-Ліча.",al={"срібний світанок","зв'язок срібного світанку"}},{q="Чи небезпечно підходити до рунічних кіл?",a="Від кіл віє тривожною енергією й лунає нестройний шепіт, але розвідники, які підходять до них обережно, можуть дізнатися щось важливе про зв'язок Погибелі, не втративши глузду.",al={"чи руни безпечні","шепіт у рунах"}}},fp="36,373,33.391.0,20.431.0,24.217.0,39.231.0,35.241.0,29.228.0,52.227.0,44.197.0"}
P.entries["quest:9261"] = {n="Розслідуй Погибель Айронфорджа",s="Лейтенант Невелл зі Срібного Світанку кличе відважних захисників: Погибель підступила просто до брам Айронфорджа. Війська нежиті й зловісні рунічні кола загрожують засніженим перевалам Дун Мороґа під некрополем, що ширяє в небі. Захисникам доручено знищувати ходячих мерців і розгадати призначення цих дивних сяйливих знаків.",h="Лейтенант Невелл зі Срібного Світанку кличе відважних захисників: Погибель підступила просто до брам...",kw={"погибель","айронфордж","лейтенант невелл","срібний світанок","рунічні кола","некрополь"},ang={["class:Paladin"]="Погибель — пряма протилежність Святому Світлу. Розслідувати рунічну злобу Короля-Ліча й очищати світ від його бездумних рабів — саме те, до чого покликаний паладин.",["class:Priest"]="Психічні відлуння, що шепочуть крізь рунічні кола, становлять особливу небезпеку для розуму звичайних вояків: щоб опиратися їм, потрібна духовна стійкість.",["faction:Alliance"]="Айронфордж — важлива господарська й військова опора Альянсу; плацдарм нежиті біля його брам загрожує шляхам постачання по всіх Східних Королівствах.",["race:Dwarf"]="Осквернення чистих снігів Дун Мороґа гнилими страхіттями обурює кожного дворфа. Захищати гірський вхід — означає боронити рідний дім і вогнище."},sec={{t="Смерть біля гірської брами",b="Навала Погибелі не зупиняється на Лордероні й заражених чумою північних землях. Летючі некрополі кидають похмурі тіні на весь Азерот, зокрема й на морозні висоти Дун Мороґа просто біля гірського входу до Айронфорджа. Срібний Світанок поставив спостерігачів на кшталт Лейтенанта Невелла, щоб стежити за цією повзучою пошестю й давати їй відсіч, перш ніж вона прорветься до твердині Бронзбірдів."},{t="Нечестиві письмена",b="Під тінню некрополя нежить облаштувала табори, позначені сяйливими рунічними колами й пульсуючими некротичними каменями. Ставши біля цих зловісних кіл, розвідники чують темні голоси, що шепочуть крізь розлиту довкола магію. Лейтенант Невелл доходить висновку, що кола — темні канали зв'язку, хоча й не знає, з ким саме зв'язується Погибель."}},faq={{q="Хто такий Лейтенант Невелл?",a="Лейтенант Невелл — офіцер Срібного Світанку в Айронфорджі, що організовує оборону від вторгнення Погибелі. Він доручає шукачам пригод збирати некротичні камені й з'ясувати призначення нечестивих знаків довкола таборів загарбників.",al={"невелл","лейтенант невелл","видавець"}},{q="Чому Погибель нападає на Айронфордж?",a="The assignment concerns Scourge forces camped outside Ironforge beneath a necropolis. Lieutenant Nevell asks defenders to thin their numbers and investigate the strange runic circles nearby.",al={"погибель біля айронфорджа","чому нежить у дун мороґу","вторгнення в айронфордж"}},{q="Що таке Тьмяні Некротичні Камені?",a="Тьмяні Некротичні Камені забирають у загарбників із Погибелі й приносять Срібному Світанку як доказ знищеної нежиті.",al={"некротичні камені","тьмяний некротичний камінь","камені погибелі"}},{q="Навіщо потрібні сяйливі рунічні кола?",a="Сяйливі рунічні кола з'являються поблизу військ навали Погибелі. Лейтенант Невелл просить вас з'ясувати, для чого вони.",al={"рунічні кола","сяйливі кола","що це за руни"}}},fp="36,360,27.391.0,19.398.1,25.260.0,39.190.0,29.112.0,49.123.0"}
P.entries["quest:9262"] = {n="Розслідуй Погибель Дарнасуса",kw={"погибель","дарнасус","лейтенант бейта","срібний світанок","рунічні кола","тельдрассил"},ang={["class:Druid"]="Некромантія й гниюча плоть, що шириться ґрунтом Тельдрассилу, — неприродна пошесть, яку кожен захисник дикої природи присягнувся знищити.",["class:Priest"]="Жерців чекає моторошне випробування — оглянути зіпсовані некромантські руни, спираючись на дисципліну розуму й віру, щоб устояти перед безумством, яке шепоче темною мережею Погибелі.",["faction:Alliance"]="Оборона Дарнасуса показує рішучість Альянсу стояти єдиним фронтом проти загрози всьому світові — війська навали Короля-Ліча.",["race:NightElf"]="Для калдореїв гнилі некрополі й нежить, що оскверняє все довкола, так близько від святої землі Тельдрассилу — потворне блюзнірство, яке треба негайно викорінити."},sec={{t="Чума на Світовому Древі",b="Навала Погибелі дісталася захищеного гілля Тельдрассилу. У небі з'являються летючі некрополі, що вивергають гулів, скелетів і некромантські страхіття просто під Дарнасусом. Лейтенант Бейта зі Срібного світанку очолює оборону столиці й збирає охочих, щоб послабити передові загони й добути відомості, перш ніж нежить захлесне батьківщину нічних ельфів."},{t="Шепіт у рунах",b="Окрім того, щоб нищити нежить і збирати її тьмяні некротичні камені, розвідникам велять оглянути дивні сяйливі рунічні візерунки, що пульсують на землі біля таборів навали. Хто підходить до цих кіл ближче, чує моторошний надприродний шепіт: руни виявляються неприродними передавачами, хоча Лейтенант Бейта й не знає, з ким саме зв'язується Погибель."}},faq={{q="Хто така Лейтенант Бейта?",a="Лейтенант Бейта — офіцерка Срібного Світанку в Дарнасусі. Вона організовує місцевий опір вторгненню Погибелі й роздає доручення, щоб зменшити кількість нежиті й вивчити її некромантичне знаряддя.",al={"хто дає розслідуй погибель дарнасуса","видавець бейта","переказ про лейтенанта бейту"}},{q="Чому Погибель нападає на Дарнасус?",a="The assignment concerns Scourge forces camped outside Darnassus beneath a necropolis. Lieutenant Beitha asks defenders to thin their numbers and investigate the strange runic circles nearby.",al={"чому нежить у дарнасусі","вторгнення в тельдрассил","король-ліч нападає на нічних ельфів"}},{q="Що за сяйливі рунічні кола під містом?",a="Сяйливі рунічні кола з'являються поблизу військ навали Погибелі. Лейтенант Бейта просить вас з'ясувати, для чого вони.",al={"руни погибелі дарнасус","рунічні кола біля дарнасуса","що за руни вторгнення"}},{q="Що таке Тьмяні Некротичні Камені?",a="Тьмяні Некротичні Камені забирають у загарбників із Погибелі й приносять Срібному Світанку як доказ знищеної нежиті.",al={"некротичні камені","що роблять некротичні камені","переказ про тьмяний некротичний камінь"}},{q="Хто фінансує чи очолює відсіч у Дарнасусі?",a="The Argent Dawn is coordinating this investigation through Lieutenant Beitha. The order is devoted to opposing the Scourge.",al={"хто очолює оборону дарнасуса","срібний світанок дарнасус"}},{q="Чи можуть рунічні кола зашкодити, якщо їх слухати?",a="Their exact effects are not established. Beitha asks defenders to investigate the strange energy around the circles.",al={"шепіт рунічних кіл","небезпека голосів рунічних кіл"}}},fp="36,311,26.419.0,21.418.1,25.226.0,39.190.0,52.123.0,29.112.0,52.123.0,44.116.0"}
P.entries["quest:9263"] = {n="Розслідуй Погибель Оргріммара",s="Погибель зухвало отаборилася просто під брамою Оргріммара, у тіні ширяючого некрополя. Лейтенант Даґел доручає захисникам відкинути нежить, зібрати некротичні камені й дослідити таємничі рунні кола, що гудуть некромантичною енергією. Це раптове вторгнення простягає руку Короля-Ліча до самого серця Дуротару.",h="Погибель зухвало отаборилася просто під брамою Оргріммара, у тіні ширяючого некрополя.",kw={"погибель","нежить","некрополь","лейтенант даґел","король-ліч","срібний світанок","дуротар","оргріммар"},ang={["faction:Horde"]="Військо загарбників, що стоїть табором на видноті веж Оргріммара, — нестерпна образа для Орди. Захищати Дуротар від прислужників Короля-Ліча — святий обов'язок кожного чемпіона, що складав присягу.",["race:Orc"]="Суху червону землю Дуротару здобуто кров'ю й тяжкою працею. Орки не дозволять бездумним чудовиськам сплюндрувати домівку, яку вони виборювали голими руками.",["race:Undead"]="Для Відступників Погибель — нагадування про колишнє рабство. Знищення цих загарбників — особиста помста за те, що рука Короля-Ліча досі сягає так далеко."},sec={{t="Нежить біля брами",b="Загроза Погибелі більше не обмежується зруйнованими королівствами Лордерона чи крижаними пустками півночі. Ширяючі некрополі з'явилися по всьому Азероту, кидаючи темні тіні навіть на Дуротар. На самому порозі Оргріммара зібралися сили нежиті: вони облаштовують табори й погрожують столиці Орди. Лейтенант Даґел і Срібний світанок координують оборону й закликають місцевих чемпіонів відкинути загарбників, поки ті не взяли місто в непробивну облогу."},{t="Некротичні реліквії й темний шепіт",b="Beyond simply slaying the encroaching monstrosities and gathering their dim necrotic stones, the defense hinges on understanding the invaders' methods. Encircling their camp are glowing runic sigils, resonant with the same dark power suffusing the necropolis above. Those brave enough to step into the runes encounter unnatural voices echoing through the ether—suggesting communication of some kind, although Dagel does not know whom the voices contact."}},faq={{q="Чому Погибель нападає на Оргріммар?",a="The assignment concerns Scourge forces camped outside Orgrimmar beneath a necropolis. Lieutenant Dagel asks defenders to thin their numbers and investigate the strange runic circles nearby.",al={"чому погибель в оргріммарі","нежить біля оргріммара","король-ліч нападає на оргріммар"}},{q="Хто такий Лейтенант Даґел?",a="Лейтенант Даґел — офіцер, що разом зі Срібним Світанком гуртує захисників проти вторгнення. Перебуваючи неподалік загрози, Даґел посилає бійців нищити нежить і досліджувати магічне знаряддя, яким вона користується на полі бою.",al={"лейтенант даґел","видавець даґел","хто такий даґел"}},{q="Що таке тьмяні некротичні камені?",a="Dim necrotic stones are recovered from Scourge invaders and brought to the Argent Dawn as proof of slain undead.",al={"некротичні камені","що таке тьмяні некротичні камені","тьмяні камені"}},{q="Що за сяйливі рунічні кола під містом?",a="The glowing circles carry the same strange energy as the nearby undead and necropolis. Dagel asks defenders to investigate their purpose.",al={"рунічні кола","сяйливі руни оргріммар","кола погибелі"}},{q="Чому Срібний Світанок діє в Дуротарі?",a="Срібний Світанок — незалежний орден, що викорінює Погибель скрізь, де вона з'являється. Вторгнення загрожує кожній живій цивілізації, тож орден разом із захисниками Орди обороняє кордони Оргріммара.",al={"срібний світанок в оргріммарі","чому срібний світанок тут","срібний світанок орда"}},{q="Чи небезпечний для міста некрополь у небі?",a="The necropolis looms over the Scourge encampment and shares its strange energy. Its presence makes the nearby undead threat a concern for the city.",al={"літаюча цитадель оргріммар","некрополь над дуротаром"}}},fp="36,377,19.509.0,33.455.1,39.189.0,24.248.0,33.112.0,52.137.0,43.230.0,49.147.0"}
P.entries["quest:9264"] = {n="Розслідуй Погибель Громового Бескиду",s="«Розслідуй Погибель Громового Бескиду» — оборонне завдання, яке Срібний світанок дає під стінами столиці тауренів. Поки летючі некрополі Короля-Ліча загрожують небу Калімдору, захисники мають винищувати навалу нежиті й з'ясувати, навіщо на скелях унизу світяться дивні рунічні кола.",h="«Розслідуй Погибель Громового Бескиду» — оборонне завдання, яке Срібний світанок дає під стінами столиці...",kw={"навала погибелі","некрополь","срібний світанок","лейтенант лісанде","тандер блаф","рунічні кола","король-ліч"},ang={["class:Shaman"]="Мерзенні некромантичні кола спотворюють природних духів землі, і шамани-захисники мусять очистити ґрунт від скверни, що розповзається.",["faction:Horde"]="Війна дісталася Малгора, і захисники Орди мають довести, що їхні землі не впадуть під раптовим наступом Короля-Ліча.",["race:Tauren"]="Летючі цитаделі й гнилі трупи оскверняють священні рівнини Земної Матері, тож захист скель — святий обов'язок кожного таурена."},sec={{t="Чума на плато",b="Навала Погибелі не розрізняє між розтрощеними королівствами Лордерона й мирними рівнинами Малгора. Коли Король-Ліч посилає некрополі грізно зависнути над великими поселеннями по всьому світу, Тандер Блаф опиняється під прямою загрозою. Лейтенант Лісанде зі Срібного світанку закликає дужих героїв Орди дати відсіч жахіттям, що отаборилися в тіні великого міста."},{t="Рунічний шепіт",b="Мало просто рубати шеренги ходячих трупів і збирати тьмяні некротичні камені як воєнні трофеї: дослідники мають оглянути рунічні кола, що світяться й гудуть лихою силою біля ворожих таборів. Варто підійти до цих магічних провідників — і розум чує моторошні голоси, що долинають здалеку. Так з'ясовується, що кола — це темні телепатичні ретранслятори, які пов'язують польові загони з похмурими умами, що керують навалою."}},faq={{q="Хто дає це завдання?",a="Це доручення дає Лейтенант Лісанде — офіцер Срібного Світанку, що перебуває біля Тандер Блафа, — щоб допомогти відбити довколишні сили Погибелі.",al={"видавець","хто дає завдання","лейтенант лісанде"}},{q="Чому Погибель нападає на Тандер Блаф?",a="Король-Ліч кинув у бій летючі некрополі, щоб водночас ударити по осередках життя по всьому Азероту й зламати та знищити живих на кожному континенті — зокрема й твердині Орди в Калімдорі.",al={"чому мулґор","чому нападають на тауренів","погибель у тандер блафі"}},{q="Навіщо потрібні сяйливі рунічні кола?",a="Сяйливі рунічні кола — темні магічні ретранслятори, через які Погибель зв'язується з далекими некрополями чи з некромантами й наглядачами, що керують наступом.",al={"рунічні кола","що роблять кола","призначення руни"}},{q="Що таке Тьмяні Некротичні Камені?",a="Тьмяні Некротичні Камені — уламки, що їх носять нижчі загарбники Погибелі й що аж гудуть від некромантичної енергії. Срібний Світанок збирає їх як доказ знищення мерців і щоб вивчити мерзенну магію, яка їх живить.",al={"некротичні камені","тьмяний некротичний камінь","що це за камені"}},{q="Чому Срібний Світанок тут, у Малгорі?",a="Срібний Світанок — нейтральна організація, цілком віддана боротьбі з Погибеллю. Вторгнення загрожує кожному живому смертному, тож офіцери Срібного Світанку організовують оборону разом і з Ордою, і з Альянсом.",al={"срібний світанок мулґор","срібний світанок орда"}},{q="Чи треба для цього завдання підніматися на летючий некрополь?",a="Ні. Розслідування цілком відбувається на землі, біля таборів під летючим некрополем, де зібрані рунічні кола й піші вояки.",al={"зайти в некрополь","увійти до некрополя"}}},fp="40,320,21.430.0,14.433.1,22.156.0,43.220.0,44.185.0,29.212.0,39.226.0,60.166.0"}
P.entries["quest:9265"] = {n="Розслідуй Погибель Андерсіті",s="Лейтенант Рукаґ посилає захисників Орди проти сил Погибелі, що наважилися отаборитися під Андерсіті. Агенти мають дослідити лиховісні рунічні кола, пов'язані з жахливим некрополем у небі, і принести Тьмяні Некротичні Камені як доказ знищення ворога.",h="Лейтенант Рукаґ посилає захисників Орди проти сил Погибелі, що наважилися отаборитися під Андерсіті.",kw={"розслідуй погибель андерсіті","лейтенант рукаґ","некрополь","рунічні кола","тьмяні некротичні камені","погибель","андерсіті"},ang={["faction:Horde"]="Честь велить прийти на захист Відступників і вберегти важливі позиції Орди у Східних Королівствах від Погибелі.",["race:Undead"]="Погибель — ваш колишній володар і одвічний поневолювач; відкинути її з ґрунтів Лордерона — справа чистого виживання й помсти."},sec={{t="На порозі",b="Навала Погибелі дісталася самих воріт занепалої столиці Лордерона. Замість того щоб ховатися за укріпленими брамами Андерсіті, командувачі Орди на кшталт Лейтенанта Рукаґа організовують негайний контрнаступ, щоб винищити мерців, перш ніж ті встигнуть піти в атаку."},{t="Некротичні реліквії",b="Під цитаделлю Погибель звела рунічні кола, що світяться й пульсують мерзенною некромантичною силою, відгукуючись на летючі некрополі, які затьмарюють небо. З убитих зайд Погибелі можна здобути Тьмяні Некротичні Камені — темні осередки, що живлять їхні жахливі обряди й підтримують неприродний похід."}},faq={{q="Хто наказує провести розслідування під Андерсіті?",a="Лейтенант Рукаґ, офіцер Орди, поставлений боронити Андерсіті, наказує воїнам розвідати, чому під брамою дедалі більше Погибелі, і знищити її загони.",al={"хто дає розслідуй погибель","лейтенант рукаґ","рукаґ андерсіті"}},{q="Що таке Тьмяні Некротичні Камені?",a="Тьмяні Некротичні Камені — тіньові магічні артефакти, які носять загарбники Погибелі. Вони гудуть мерзенною некромантією, і, принесені офіцерам Орди, правлять за доказ загибелі своїх власників.",al={"що таке некротичні камені","тьмяний некротичний камінь","камені погибелі"}},{q="Що таке сяйливі рунічні кола?",a="Це ритуальні кола, накреслені на землі біля таборів Погибелі. Вони випромінюють ту саму темну магію, що захищає й живить некрополь, який нависає над головою.",al={"рунічні кола біля андерсіті","сяйливе коло погибелі","руни погибелі"}},{q="Чому Погибель нападає під Андерсіті?",a="Король-Ліч прагне знищити Відступників, що вийшли з-під його влади, і підкорити руїни Лордерона, тож кидає некрополі й наземні війська на пряму облогу столиці.",al={"чому погибель біля андерсіті","вторгнення погибелі в андерсіті","андерсіті під атакою"}},{q="Чому це важливо для Відступників?",a="Відступники невтомно боролися, щоб вирватися з-під залізної волі Короля-Ліча. Погибель, що висадилася на самому їхньому порозі, загрожує свободі й незалежності їхнього молодого народу.",al={"загроза погибелі відступникам","нежить захищає андерсіті"}},{q="Чи можуть узятися за це завдання члени Орди, які не є Відступниками?",a="Так. Усіх членів Орди закликають допомогти обороні Лордерона, адже загроза Андерсіті — це загроза безпеці всього союзу.",al={"чи орки можуть це завдання","оборона андерсіті орда"}}},fp="40,295,15.288.0,15.322.0,51.175.0,29.180.0,35.169.0,51.164.0,37.183.0,49.150.0"}
P.entries["quest:927"] = {n="Серце, оплетене мохом",s="Оповите Мохом Серце — дивне зіпсуте осердя, вийняте з жахливого деревляника Блекмосса Смердючого. Укрите масним темним мохом, серце моторошно продовжує битися саме по собі, спонукаючи ботаніка Деналана з Озера Ал'Амет до дослідження.",h="Оповите Мохом Серце — дивне зіпсуте осердя, вийняте з жахливого деревляника Блекмосса Смердючого.",kw={"серце оплетене мохом","блекмосс смердючий","деревляник","деналан","озеро ал'амет","мох","зіпсуття"},ang={["class:Druid"]="Друїди Кола Кенарія пильно цікавляться такими аномаліями, як це уражене серце, що б'ється: вони прагнуть визначити, чи можна вичистити зіпсуття, чи воно свідчить про глибшу гниль.",["profession:Herbalism"]="Кожен, хто вивчає рослини, бачить: масний наріст на цій серцевині цілком неприродний — він кидає виклик звичним законам ботаніки, підтримуючи життя у відтятому серці.",["race:NightElf"]="Для калдорей бачити, як молоде Світове Дерево Тельдрассил плодить заражених агресивних деревляників на кшталт Блекмосса, — тверезий знак, що їхню нову домівку мучить повзуча хвороба."},sec={{t="Серцевина, що б'ється",b="Вирізане з решток Блекмосса Смердючого, це серце деревляника майже не впізнати під шаром темного масного моху. Єдине, що видає його справжню природу, — повільний ритмічний пульс, який не вщухає навіть після того, як серце відтяли від створіння. Така неприродна живучість натякає, що зіпсуття, яке шириться дикою рослинністю Тельдрассила, сягає куди глибше за звичайну гниль."},{t="Огляд Деналана",b="Деналан, уважний дослідник місцевої флори, що облаштувався біля Озера Ал'Амет, одразу розпізнає, яку похмуру правду несе ця знахідка. Деревляники мали б бути лагідними створіннями, сплетеними з гіллям Світового Дерева, та це серце виказує шалений уражальний вплив. Заінтригований і стривожений, Деналан вирішує посадити зіпсутий орган і вивчити його, щоб зрозуміти мерзенний мох, який укорінюється в ґрунті острова."}},faq={{q="Звідки взялося Оповите Мохом Серце?",a="Серце забирають у Блекмосса Смердючого — великого, глибоко зіпсованого скверною деревляника, що блукає дикими нетрями Тельдрассила.",al={"де взяти серце","серце оповите мохом випадає","блекмос смердюче серце"}},{q="Чому серце досі б'ється?",a="Темний маслянистий мох, що обліпив деревляника, схоже, підтримує в ньому неприродну життєву силу. Навіть вирізане з тіла, серце й далі повільно, уперто б'ється.",al={"чому серце б'ється","серце досі б'ється","серце деревляника б'ється"}},{q="Хто такий Деналан?",a="Деналан — природознавець із нічних ельфів, що доглядає розсадник біля берегів Озера Ал'Амет. Він присвятив себе вивченню рослинності Тельдрассила, її пагонів і скверни, що підступно вражає деревляників острова.",al={"хто такий деналан","де деналан","місце деналана"}},{q="Що Деналан зробить із серцем?",a="Деналан вирішує посадити серце в зачаровану діжку, щоб виростити й відокремити мерзенний мох, — він сподівається докопатися до першопричини хворобливого росту.",al={"що деналан зробить із серцем","посадка серця","дослідження серця деналана"}},{q="Якими мають бути деревляники насправді?",a="Від природи деревляники — мирні рослинні елементалі, народжені лісом. Проте по всьому Тельдрассилу темні сили й неприродна скверна довели багатьох із них до шаленства й агресії.",al={"що таке деревляники","переказ про деревляників","чи деревляники злі"}},{q="Скверна на серці — магічна чи природна?",a="Мох мерзенний і маслянистий, а не здоровий: це радше неприродна пошесть, що вражає природу Тельдрассила, ніж звичайне лісове гниття.",al={"чи мох магічний","джерело смердючого моху","мох тельдрассила"}}},fp="21,262,14.391.0,21.417.0,43.125.0,31.174.0,15.214.0,36.152.0,36.180.0,50.162.0"}
P.entries["quest:92706"] = {n="РОЗШУКУЄТЬСЯ: Бруз",s="«РОЗШУКУЄТЬСЯ: Бруз» — оголошення про нагороду, яке вивісив Ґазлоу в гоблінському порту Раджет. Величезна хижа акула оселилася біля портових пристаней і загрожуватиме судноплавству й прибережній торгівлі, доки хтось не покладе їй край.",h="«РОЗШУКУЄТЬСЯ: Бруз» — оголошення про нагороду, яке вивісив Ґазлоу в гоблінському порту Раджет.",kw={"розшукується","бруз","акула","ґазлоу","раджет","нагорода"},ang={["class:Hunter"]="Здолати верховного морського хижака на кшталт Бруза — неповторне випробування терпіння й влучності.",["profession:Cooking"]="Ґазлоу потрібен лише спинний плавець як доказ, але акула завбільшки з Бруза — це ціла гора свіжого прибережного м'яса для заповзятливих кухарів."},sec={{t="Жах затоки",b="Раджет живе торговим мореплавством і править за головні нейтральні ворота між Калімдором і Східними Королівствами. Цей постійний потік торгівлі робить води біля пристаней гамірними й метушливими, але останнім часом він приваблює куди небезпечнішого гостя. Велетенська акула, яку перелякані портові робітники прозвали «Брузом», почала никати затокою. Замість того щоб триматися глибини, звір навально нападає на човники, місцевих моряків і вантажі, що їх розвантажують, і зриває роботу порту."},{t="Нагорода Ґазлоу",b="Ґазлоу не може дозволити, щоб кораблі обминали його порт, боячись потрапити на зуби морській звірині. Тож він вивісив публічне оголошення, закликаючи всіх рибалок і обіцяючи щедру нагороду. Щоб її отримати, мисливець має вбити Бруза й принести спинний плавець хижака як доказ."}},faq={{q="Хто такий Бруз?",a="Бруз — горезвісна величезна й агресивна акула, що обрала собі мисливські угіддя біля портових причалів Раджета. Портові робітники дали чудовиську це прізвисько після кількох нападів на моряків і невеликі судна.",al={"що таке бруз","акула бруз","хто така акула бруз"}},{q="Чому Ґазлоу оголосив нагороду за Бруза?",a="Бруз заважає морським перевезенням, на яких тримається господарство Раджета. Ґазлоу залежить від сталої торгівлі й справних причалів, тож велетенська акула, що нападає на моряків і трощить човни, так шкодить справі, що за її тушу варто заплатити.",al={"чому вбити бруза","завдання ґазлоу про акулу","навіщо плавник бруза"}},{q="Де зазвичай буває Бруз?",a="Бруз чатує у водах просто біля узбережжя Раджета в Пустках і часто кружляє біля головних вантажних пірсів і входу до гавані.",al={"місце бруза","де бруз","знайти бруза"}},{q="Який доказ потрібен Ґазлоу?",a="Перш ніж розщедритися на нагороду, Ґазлоу вимагає спинний плавець Бруза — відчутний доказ того, що велетенського хижака справді вбито.",al={"здати бруза","що принести ґазлоу","спинний плавник бруза"}},{q="Чи можуть узятися за цю нагороду шукачі пригод і з Альянсу, і з Орди?",a="Так. Раджет перебуває під нейтральним управлінням картелю Стімвідл, тож Ґазлоу радий кожному вправному шукачеві пригод з будь-якої фракції, що готовий пірнути й розв'язати його акулячу проблему.",al={"чи розшукується бруз нейтральне","чи орда може розшукується бруз","чи альянс може бруза"}},{q="Чому оголошення звертається саме до рибалок?",a="В оголошенні про це не сказано. Воно просто починається словами «Рибалки, увага!» і обіцяє щедру винагороду тому, хто принесе Ґазлоу плавець акули.",al={"заклик до рибалок бруз","чи це рибальське завдання"}}},fp="13,226,19.503.0,16.291.0,13.212.0,39.239.0,29.143.0,45.141.0,57.198.0,50.142.0"}
P.entries["quest:92742"] = {n="Перевірка криниць",s="«Перевірка криниць» — дослідницьке доручення від Альби Фермун, яка прагне з'ясувати, звідки береться отрута, що просочується крізь ґрунт Вестфолу. Шукачів пригод відправляють із наборами для проб, щоб набрати ґрунтової води з криниць Садиби Дженсенів і Ферми Молсена.",h="«Перевірка криниць» — дослідницьке доручення від Альби Фермун, яка прагне з'ясувати, звідки береться отрута...",kw={"перевірка криниць","альба фермун","отрута","садиба дженсенів","ферма молсена","вестфол"},ang={["class:Druid"]="Неприродна отрута, що просочується крізь ґрунт і чисті ґрунтові води, свідчить про тяжку рану в рівновазі землі, яку треба зцілити.",["faction:Alliance"]="Відновлення продовольства у Вестфолі вкрай важливе для виживання Королівства Стормвінд, тож стан цих фермерських криниць — питання безпеки всього королівства."},sec={{t="Скверна у водоносному шарі",b="Відкриті рівнини Вестфолу тяжко потерпіли від занедбаності й розбою, але підступне забруднення під землею загрожує всьому, що ще лишилося від землеробства. Щоб зрозуміти, як отруюються ниви, Альба Фермун доручає дослідникам перевірити ґрунтові води безпосередньо. Набравши проб води на заселених фермах, дослідники сподіваються визначити природу отрути, що вражає ґрунт і все живе в краї."},{t="Ферми прикордоння",b="Обстеження зосереджене на двох важливих місцях — Садибі Дженсенів і Фермі Молсена. Обидві ділянки лежать серед розкиданих господарств, беззахисних перед мандрівними розбійниками Дефіасу й дикими звірами. Проби з їхніх криниць покажуть, чи ця скверна виникає природно, чи її спричинила магія, чи її навмисно занесли у водоносний шар, що живить край."}},faq={{q="Навіщо потрібна «Перевірка криниць»?",a="Альба Фермун хоче з'ясувати, звідки береться отрута, що вразила Вестфол, і з чого вона складається. Свіжі зразки ґрунтових вод із фермерських криниць — саме той матеріал, що потрібен для аналізу забруднення.",al={"навіщо перевірка криниць","мета перевірки криниць","для чого це завдання"}},{q="Хто дає це доручення?",a="Завдання дає Альба Фермун, яка розслідує скверну й неприродні отрути, що поширюються землеробським Вестфолом.",al={"хто дає перевірку криниць","завдання альби фермун","видавець"}},{q="Звідки треба взяти зразки?",a="Зразки води треба набрати з діючих криниць на Хуторі Дженсена й на Фермі Молсена у Вестфолі.",al={"куди йти","які криниці","місця криниць"}},{q="Що загрожує воді й ґрунту Вестфолу?",a="Невідома пошесть чи отрута поступово псує землю. Перевірка води з місцевих криниць — перший крок, щоб з'ясувати, чи забруднено водоносний шар під тутешніми господарствами.",al={"чому вестфол отруєний","що отруює землю","джерело отрути"}},{q="Забруднення природне чи штучне?",a="Це й є головне питання розслідування. Зразки з Хутора Дженсена й Ферми Молсена мають показати, чи гниль походить від природного псування ґрунтових вод, чи від навмисної диверсії.",al={"чи вода отруєна навмисно","хто отруїв криниці"}},{q="Чому саме Хутір Дженсена й Ферма Молсена?",a="Ці два господарства мають давні домашні криниці, що сягають підземних вод рівнини, тож вони найкраще підходять, щоб перевірити, як далеко зайшло забруднення.",al={"чому дженсен і молсен","чому саме ці ферми"}}},fp="17,250,21.416.0,21.376.0,41.207.0,22.144.0,35.111.0,46.187.0,43.206.0,42.186.0"}
P.entries["quest:92744"] = {n="Мурлокові зябра",s="«Мурлокові зябра» — завдання Альянсу у Вестфолі від Альби Фермун. Побоюючись, що скверна, яка вражає посіви, може отруїти й прибережні рибні промисли, шукачів пригод відправляють на Лонгшор по зябра мурлоків для екологічного аналізу. Будова тіла мурлоків надзвичайно чутлива до морських забруднень, тож їхні зябра покажуть, чи проникла отрута в море.",h="«Мурлокові зябра» — завдання Альянсу у Вестфолі від Альби Фермун.",kw={"мурлокові зябра","альба фермун","лонгшор","мурлоки","забруднення","вестфол"},ang={["class:Druid"]="Поширення скверни із суходолу на прибережні екосистеми загрожує спотворити місцеву дику природу, тож спостереження за видами-індикаторами на кшталт мурлоків — необхідний запобіжник.",["faction:Alliance"]="Король Варіан зник, нестача їжі вже розпалює невдоволення, тож захист решти продовольства Вестфолу життєво важливий для стабільності Стормвінда.",["race:Human"]="Для людей Стормвінда занепад Вестфолу — пряма загроза самому існуванню їхніх домівок, нив і обідніх столів."},sec={{t="Загроза узбережжю",b="Вестфол і так на межі руїни через масовий неврожай, вигнаних фермерів і розбій. Альба Фермун боїться ще смертоноснішого повороту: що скверна, яка вражає врожаї вглибині краю, почала стікати у Велике Море. Якщо прибережні води Вестфолу отруєні, то рибні запаси, які годують селян і поповнюють столи Стормвінда, можуть зникнути зовсім — і виснажене королівство скотиться в справжній голод."},{t="Вартові чистоти води",b="Хоч мурлоки й славляться впертістю та лютою вдачею, їхня земноводна природа робить їх чутливими природними біоіндикаторами. Дихальна система мурлоків безупинно фільтрує морську воду, тож тканина їхніх зябер надзвичайно сприйнятлива до чужорідних отрут, скверни й неприродних забруднень. Досліджуючи свіжі зябра, зібрані з мешканців припливів, що нишпорять Лонгшором, Фермун сподівається точно визначити, наскільки серйозне забруднення, що підступає."}},faq={{q="Навіщо Альбі Фермун зябра мурлоків?",a="Альба Фермун з'ясовує, чи не просочилася в море пошесть, що нищить урожаї Вестфолу. Мурлоки надзвичайно чутливі до забруднення води, тож їхні зябра діють як живі фільтри, на яких швидко проявляються найменші сліди отрути чи нечистот у морській воді.",al={"чому мурлокові зябра","альба фермун мурлоки","мета завдання"}},{q="Де шукати мурлоків для цього завдання?",a="Мурлоки живуть на Лонгшорі — довгій смузі пляжу вздовж західного узбережжя Вестфолу. Вони никають мілинами й припливними обмілинами одразу за кручами.",al={"де мурлоки","місце мурлоків лонгшор","місце зябр мурлоків"}},{q="Чим загрожує отруєння моря?",a="Вестфол — головна житниця королівства Стормвінд. Урожаї в глибині краю вже гинуть, тож прибережне рибальство стає життєво важливим джерелом харчів. Якщо отрута вразить морських мешканців біля узбережжя, королівство може поринути в неминучий голод.",al={"чому це важливо","небезпека голоду вестфолу","загроза стормвінду"}},{q="Чи мурлоки особливо схильні до хвороб?",a="Мурлоки — витривалі й живучі створіння, звиклі до суворих умов, але їхнє дихання земноводних миттєво реагує на хімічні чи магічні домішки у воді, тож вони ідеально підходять для вивчення забруднення води.",al={"фізіологія мурлоків","чи мурлоки хворіють"}},{q="Чи пов'язане це завдання з Братством Дефіас?",a="Братство Дефіас спричинило чимало хаосу й занедбання полів у Вестфолі, але це розслідування зосереджене саме на природній пошесті й збереженні джерел харчів для королівства.",al={"зв'язок з дефіас","чи це дефіас"}},{q="Хто така Альба Фермун?",a="Альба Фермун — дослідниця Альянсу у Вестфолі, що стежить за пошестю й занепадом природи, які загрожують землеробству краю.",al={"хто така фермун","переказ про альбу фермун"}}},fp="12,361,25.442.0,26.453.0,41.278.0,44.161.0,53.248.0,42.233.0,50.220.0,21.158.0"}
P.entries["quest:92745"] = {n="Стан копалень",s="«Стан копалень» — доручення від Альби Фермун у боротьбі із забрудненням довкілля по всьому Вестфолу. Отруйні стоки із захоплених розробок краю загрожують на десятиліття занапастити ниви. Щоб зупинити цю екологічну катастрофу, шукачів пригод відправляють зірвати розкопки під проводом Дефіасу і в Шахті Джанґолод, і в Кар'єрі Золотого Узбережжя.",h="«Стан копалень» — доручення від Альби Фермун у боротьбі із забрудненням довкілля по всьому Вестфолу.",kw={"стан копалень","альба фермун","шахта джанґолод","кар'єр золотого узбережжя","забруднення","братство дефіас"},ang={["class:Druid"]="Металеві отрути, що просочуються в землю, — нагальна екологічна загроза для рівнин і прибережних екосистем Вестфолу, яку треба негайно стримати.",["faction:Alliance"]="Вестфол годує населення Стормвінда; якщо дати Дефіасу занапастити його родючу землю, усьому королівству загрожує тривалий голод.",["profession:Mining"]="Безладні, грубі розробки в Джанґолоді й Кар'єрі Золотого Узбережжя ясно показують: для Дефіасу швидкий видобуток важить набагато більше, ніж безпека чи міцність виробок."},sec={{t="Отруєння землі",b="Колись Вестфол був головною житницею Стормвінда, але нещодавні проби води з місцевих криниць показали небезпечний вміст отруйних металів. Безрозсудні способи видобутку, які застосовує Братство Дефіас, призвели до того, що промислові стоки глибоко просочилися у водоносні шари краю. Якщо це забруднення не зупинити, навколишня земля стане безплідною й десятиліттями не зможе родити."},{t="Примусова й найманська праця",b="Rather than relying solely on their own highwaymen, the Defias use local creature populations as labor to strip Westfall of its natural wealth. Riverpaw gnolls are set to backbreaking work digging out stone and mineral veins at the Gold Coast Quarry, while kobold diggers are put to work tunneling into the depths of the Jangolode Mine. Cutting down their workforce strikes directly at their ability to process and distribute contaminated minerals."}},faq={{q="Чому з копалень Вестфолу витікають отруйні метали?",a="Братство Дефіас, безжально вичищаючи Вестфол від сировини, геть знехтувало безпекою й дбайливістю. Його безконтрольне видобування забруднило ґрунтові води шкідливими металевими стоками, отруюючи ґрунт і криниці поселень поблизу.",al={"чому токсична вода вестфол","забруднення копалень вестфолу","отруйний стік вестфол"}},{q="Хто стоїть за видобуванням у Вестфолі?",a="Видобування контролює Братство Дефіас. Воно захопило колишні королівські споруди й змусило покірних істот — гнолів Річколапів і кобольдів — виконувати небезпечну ручну роботу з видобутку руди.",al={"хто керує копальнями","хто контролює копальні вестфолу","видобуток дефіас"}},{q="Де працюють гноли Річколапів і кобольди?",a="Гноли Річколапів добувають руду в Кар'єрі Золотого Узбережжя на західному березі, а кобольди-копачі — у Шахті Джанґолод на півночі.",al={"де шахтарі","місце каменоломні золотого берега","місце копальні джанґолод"}},{q="Хто така Альба Фермун?",a="Альба Фермун — стурбована дослідниця й союзниця у Вестфолі, що перевіряє місцеві джерела води й прагне вберегти землеробський край від довготривалої руїни.",al={"хто дає стан копалень","переказ про альбу фермун","видавець"}},{q="Чому гноли й кобольди працюють на Дефіас?",a="The Defias use these creatures as labor to strip resources from the seized mines. Alba does not say how the workers were recruited.",al={"чому дефіас наймають гнолів","кобольди працюють на дефіас"}},{q="Чи зможе земля Вестфолу відновитися після такого забруднення?",a="За словами Альби Фермун, ґрунт відновиться, лише якщо швидко перекрити джерело отрути. Якщо видобування триватиме й далі, земля десятиліттями лишатиметься неродючою й ураженою.",al={"чи ґрунт вестфолу відновиться","чи виростуть знову врожаї"}}},fp="22,341,18.421.0,25.448.0,51.272.0,48.236.0,50.163.0,21.180.0,50.131.0,57.200.0"}
P.entries["quest:92747"] = {n="Шпигунство в Мунбруку",s="«Шпигунство в Мунбруку» — завдання Альянсу від Альби Фермун: розвідати захоплене поселення Мунбрук. Дослідники вважають, що загадкова отрута не походить із дрібніших розробок Вестфолу, тож звертають увагу на прадавні, давно покинуті Мертві Копальні під містечком, щоб знайти докази діяльного промислового виробництва.",h="«Шпигунство в Мунбруку» — завдання Альянсу від Альби Фермун: розвідати захоплене поселення Мунбрук.",kw={"шпигунство в мунбруку","альба фермун","мунбрук","мертві копальні","розвідка","вестфол"},ang={["class:Rogue"]="Непомітно прослизнути крізь Мунбрук — хрестоматійна нагода для розбійників зібрати відомості про діяльність Дефіасу, не здійнявши тривоги.",["faction:Alliance"]="Діяльне виробництво в Мунбруку — пряма загроза житниці Вестфолу й безпеці самого Стормвінда.",["profession:Mining"]="Шахтарі краще за будь-кого розуміють, які багатства й який розмах ховаються в глибоких штольнях під Мунбруком."},sec={{t="Отруйний слід",b="Обстеживши місцеві шахти по всьому Вестфолу, дослідники зайшли в глухий кут: отрута, що вражає край, схоже, не походить із жодної відомої наземної розробки. Лишається тільки одна велика розробка, яку ще не дослідили, — печерні, розлогі штольні Мертвих Копалень просто під зруйнованим містечком Мунбрук."},{t="Таємниці Мертвих Копалень",b="За офіційними відомостями, Мертві Копальні покинули після Першої війни, коли край заполонила Орда. Проте знахідки сучасного промислового обладнання й припасів, розкиданих Мунбруком, переконливо свідчать, що хтось потай веде масштабний видобуток і виробництво під личиною зруйнованого міста-привида."}},faq={{q="Хто дає завдання «Шпигунство в Мунбруку»?",a="Завдання дає Альба Фермун, що розслідує підозрілі отрути й промислову діяльність на спірних землях Вестфолу.",al={"видавець","хто дає шпигунство в мунбруку","альба фермун"}},{q="Чому Альба розслідує Мунбрук?",a="Інші місцеві копальні не мали ознак виробництва отрути, яку розслідують. А що Мунбрук стоїть просто над Мертвими Копальнями, Альба підозрює, що під містечком хтось таємно веде незаконну справу.",al={"чому мунбрук","що в мунбруку","розслідувати мунбрук"}},{q="Що таке Мертві Копальні?",a="Мертві Копальні — найглибші й найпросторіші золоті копальні краю. Їх покинули ще в Першу війну, після падіння Стормвінда, і відтоді вважали порожніми руїнами, де водяться хіба що паразити й розбійники.",al={"переказ про мертві копальні","що таке мертві копальні","історія мертвих копалень"}},{q="Що збирають під час цієї розвідки?",a="Розвідників посилають по Підозрілі Промислові Припаси, розкидані по Мунбруку: вони доводять, що біля шахтних стовбурів кипить промислова робота й переплавляння.",al={"підозрілі промислові припаси","предмети шпигунства в мунбруку"}},{q="Які загрози нині в Мунбруку?",a="Мунбрук захопило Братство Дефіас: воно використовує покинуті будинки як передовий плацдарм і стереже наземний вхід до підземних ходів.",al={"вороги мунбрука","хто контролює мунбрук"}},{q="Що доводять знайдені припаси?",a="Сучасне важке промислове обладнання в нібито покинутому містечку підтверджує, що якась згуртована сила веде виробництво на широку ногу, ховаючись від допитливих очей влади Стормвінда.",al={"що означають припаси","промисловість дефіас"}}},fp="19,335,13.336.0,24.345.1,32.154.0,36.209.0,23.207.0,53.178.0,40.191.0,39.218.0"}
P.entries["quest:92748"] = {n="Вибухова консультація",s="«Вибухова консультація» — завдання Альянсу, що починається у Вестфолі й спрямоване проти отруйного промислового виробництва, захованого глибоко в Мертвих Копальнях. Знахідки вказують, що місцеві ниви отруює важка техніка, тож шукачів пригод відправляють до Дворфійського Кварталу Стормвінда — найняти фахівця-інженера, здатного забезпечити потужну вибухівку.",h="«Вибухова консультація» — завдання Альянсу, що починається у Вестфолі й спрямоване проти отруйного...",kw={"вибухова консультація","спрайт джампспрокет","дворфійський квартал","мертві копальні","вибухівка","вестфол"},ang={["faction:Alliance"]="Це завдання показує взаємозалежність знесилених прикордонних громад Вестфолу й гамірних майстерень Дворфійського Кварталу Стормвінда.",["profession:Engineering"]="Інженери оцінять: грубою силою екологічне лихо Вестфолу не розв'язати — щоб вивести з ладу велику підземну техніку, потрібні особливі боєприпаси й ретельні технічні знання.",["race:Gnome"]="Гномська технічна винахідливість життєво важлива, щоб знешкодити підземні промислові загрози, з якими не дають ради звичайні війська Альянсу."},sec={{t="Джерело отрути",b="Поки Вестфол бореться з вигнаними волоцюгами й розбоєм Братства Дефіас, докази, зібрані по всьому краю, викривають значно організованішу, механізовану загрозу, що визріває під землею. Промислові відходи й їдкі отрути, що просочуються в навколишній ґрунт, ведуть просто в лабіринти тунелів Мертвих Копалень — отже, під землею невтомно працює організоване виробництво."},{t="Пошуки фахівців у Стормвінді",b="Звичайною зброєю укріплену підземну споруду не зруйнуєш. Щоб припинити отруєння Вестфолу, потрібен промисловий підрив, тож лунає терміновий заклик до Дворфійського Кварталу Стормвінда. Там, серед гуркоту кузень, майстрів-винахідників і торговців вибуховим порохом, треба найняти інженерний розум на ім'я Спрайт Джампспрокет, щоб вона вигадала вибухові ліки від цієї біди."}},faq={{q="Навіщо нам вибухівка в Мертвих Копальнях?",a="Докази, знайдені у Вестфолі, свідчать, що в Мертвих Копальнях прихована величезна промислова справа, яка виробляє отрути й псує довколишні поля. Трощити укріплені машини вручну марно — щоб вивести їх із ладу, потрібна потужна вибухівка.",al={"навіщо вибухівка в мертвих копальнях","навіщо нам бомби","причина токсинів мертвих копалень"}},{q="Хто дає це завдання?",a="Альба Фермун дає це доручення героям, що розслідують неприродні забруднення й неспокій, які загрожують Вестфолу.",al={"хто дає вибухову консультацію","початок вибухової консультації"}},{q="Хто така Спрайт Джампспрокет?",a="Спрайт Джампспрокет — гномка-інженерка з Дворфійського Кварталу Стормвінда. Вона славиться роботою зі складними механізмами й нестійкими сумішами, тож саме до неї звертаються по потужні підривні заряди.",al={"місце спрайт джампспрокет","хто така джампспрокет"}},{q="Чому по допомогу треба йти в Дворфійський Квартал?",a="Дворфійський Квартал — промислове серце Стормвінда: тут найкращі ковалі й майстри-винахідники королівства, а також постачальники вибухового порошку й інженерних деталей.",al={"чому дворфійський квартал","стормвіндський дворфійський квартал"}},{q="Чи допомагає в цьому уряд Стормвінда?",a="Король Варіан Рінн зник, а Дім Вельмож не поспішає посилати у Вестфол регулярні гарнізони, тож місцевим захисникам доводиться покладатися на незалежних добровольців і приватних майстрів зі столиці, а не на армійські полки.",al={"чи армія допомагає","чому стормвіндський інженер"}}},fp="22,361,14.433.0,29.390.0,43.266.0,22.113.0,27.211.0,44.180.0,52.238.0"}
P.entries["quest:92749"] = {n="Динамітний план",s="«Динамітний план» — завдання від винахідливої майстрині Спрайт Джампспрокет у Дворфійському Кварталі Стормвінда. Захоплена розмовами про промислову диверсію, вона шукає чималий запас грубого динаміту, щоб дати плану старт. Шукачі пригод мають виготовити чи роздобути ці боєприпаси, щоб підтримати її задуми.",h="«Динамітний план» — завдання від винахідливої майстрині Спрайт Джампспрокет у Дворфійському Кварталі...",kw={"динамітний план","спрайт джампспрокет","грубий динаміт","інженерія","дворфійський квартал","стормвінд"},ang={["faction:Alliance"]="Спрайт керує своїм вибуховим задумом із Дворфійського Кварталу — просто в мурах столиці Альянсу.",["profession:Engineering"]="Інженери можуть виготовити грубий динаміт із грубого вибухового пороху й лляної тканини, тож це завдання — проста перевірка початкової майстерності.",["race:Gnome"]="Спрайт Джампспрокет — утілення класичного гномського пориву: відповідати на складні промислові проблеми хитромудрими, вибухонебезпечними пристроями."},sec={{t="Іскри в Дворфійському Кварталі",b="Посеред гуркоту й диму Дворфійського Кварталу Стормвінда гномка-інженерка Спрайт Джампспрокет рідко цурається радикальних рішень. Коли мова заходить про промислову диверсію, її перший порив — не обережність, а запал. Для початку вона просить найманців, що проходять повз, роздобути їй в'язку грубого динаміту."},{t="Гномські амбіції",b="Щоб роздобути вибухівку, потрібна вправна рука за інженерним верстатом або хист торгуватися з міськими ремісниками. Десяти шашок грубого динаміту з лихвою вистачить, щоб зірвати будь-які промислові задуми, що розгортаються в довколишніх землях, — і це показує практичні, хоч і небезпечні методи, яким гноми віддають перевагу, розв'язуючи і механічні, і політичні негаразди."}},faq={{q="Хто така Спрайт Джампспрокет?",a="Спрайт Джампспрокет — інженерка, що працює серед кузень і майстерень Дворфійського Кварталу в Стормвінді. Вона славиться зухвалими й небезпечними інженерними задумами.",al={"спрайт джампспрокет","хто така спрайт","видавець"}},{q="Що потрібно Спрайт для цього доручення?",a="Їй потрібно десять шашок грубого динаміту. Їх можна виготовити за допомогою інженерії або здобути в торгівлі чи на аукціоні в інших майстрів.",al={"предмети динамітного плану","що мені потрібно","потрібні предмети"}},{q="Навіщо Спрайт грубий динаміт?",a="Спрайт зацікавилася нагодою влаштувати промислову диверсію й хоче почати справу з надійним запасом простих підривних зарядів.",al={"навіщо динаміт","призначення динаміту","мотив саботажу"}},{q="Куди здавати це завдання?",a="Спрайт Джампспрокет — у Дворфійському Кварталі в мурах Стормвінда.",al={"куди здати","місце здачі","місце спрайт"}},{q="Чи потрібна інженерія, щоб виконати це завдання?",a="Ні, інженерія не обов'язкова. Інженери можуть самі виготовити грубий динаміт, але будь-який шукач пригод може виміняти його в інших гравців або купити на аукціоні.",al={"чи потрібна інженерія","вимога інженерії","чи не інженери можуть це"}},{q="Як це пов'язано з ширшими негараздами довкола Стормвінда?",a="Спрайт так і не каже, проти чого спрямована її диверсія. Вона виявляє лише свій запал: щойно мова заходить про промислову диверсію, їй кортить почати з динаміту.",al={"проблеми стормвінда","саботаж у вестфолі","переказ про промисловий саботаж"}}},fp="15,300,30.336.0,17.397.0,27.195.0,36.167.0,37.152.0,29.90.0,47.190.0,58.157.0"}
P.entries["quest:92750"] = {n="Детонація на відстані",s="«Детонація на відстані» відправляє шукача пригод через усю столицю Стормвінда на пошуки особливих знань про вибухівку. За підказкою дивакуватої гномки-винахідниці Спрайт Джампспрокет ви вирушаєте до Розвідки Стормвінда, щоб роздобути дистанційний детонатор.",h="«Детонація на відстані» відправляє шукача пригод через усю столицю Стормвінда на пошуки особливих знань про...",kw={"детонація на відстані","спрайт джампспрокет","джаспер фел","si:7","детонатор","старе місто"},ang={["class:Rogue"]="Навідавшись до Джаспера Фела, ви потрапляєте в самий осередок операцій SI:7 у Старому Місті — серце людського таємного ремесла.",["profession:Engineering"]="Хоч інженери часто самі виготовляють ґноти й динаміт, щоб роздобути військові дистанційні спускові механізми, зазвичай потрібні знайомства серед фахівців із тихих диверсій.",["race:Gnome"]="Спрайт Джампспрокет утілює класичний гномський інтерес до інженерних задач, хоч по особливі шпигунські боєприпаси й звертається до людської розвідки."},sec={{t="Керований вибух",b="Хоч гобліни й гноми однаково славляться безрозсудним поводженням з леткими хімікатами, не кожен підрив вимагає стояти просто біля заряду. Коли звичайні ґноти загрожують життю й здоров'ю, дистанційна детонація стає конче потрібною. Спрайт Джампспрокет розуміє, що для керованого вибуху потрібні особливі спускові механізми, яких звичайні майстри не тримають у щоденних запасах."},{t="Звернення до SI:7",b="Замість звертатися до місцевих дворфійських підривників чи шукати звичайні інженерні припаси, Спрайт скеровує пошуки до Розвідки Стормвінда, що діє зі Старого Міста. Ця таємна мережа агентів королівства, відома в народі як SI:7, постійно береться за делікатні диверсії, таємне проникнення й прицільні підриви. Джаспер Фел, агент, що діє в столиці, — саме той темний знайомий, у якого водиться таке потаємне й небезпечне обладнання."}},faq={{q="Хто посилає вас на це доручення?",a="Завдання дає Спрайт Джампспрокет — гномка-винахідниця, прихильниця Альянсу, яку можна знайти в Дворфійському Кварталі Стормвінда.",al={"видавець","хто починає детонацію на відстані","завдання спрайт джампспрокет"}},{q="З ким треба поговорити в Стормвінді?",a="Вас посилають до Джаспера Фела — співробітника розвідки Стормвінда, що перебуває в столиці.",al={"куди здати","контакт розвідки стормвінда","місце джаспера фела"}},{q="Навіщо Спрайт Джампспрокет дистанційний детонатор?",a="Спрайт зауважує: хоч дистанційний підрив і не дає того хаотичного захвату, що некерований вибух, зате руки й ноги лишаються цілими, тож для небезпечної роботи з вибухівкою спусковий механізм на відстані куди практичніший.",al={"навіщо дистанційний детонатор","мета детонації"}},{q="Чому звертатися до розвідки Стормвінда, а не до інженера?",a="Розвідка Стормвінда має таємні запаси й особливе диверсійне спорядження, якого звичайні міські крамарі чи польові майстри відкрито не тримають і не продають.",al={"чому ес-ай сім","чому розвідка стормвінда"}},{q="Де в Стормвінді знайти Джаспера Фела?",a="Джаспер Фел — у Старому Місті, у штабі SI:7, звідки шпигуни й таємні агенти Стормвінда ведуть свої операції.",al={"джаспер фел стормвінд","кімната джаспера фела"}},{q="Яка фракція може взятися за це доручення?",a="Це доручення доступне лише членам Альянсу, адже воно спирається на співпрацю з королівською розвідкою Стормвінда.",al={"чи це лише для альянсу","чи орда може це"}}},fp="24,266,18.413.0,21.461.0,30.126.0,40.125.0,53.202.0,59.163.0,41.135.0,37.139.0"}
P.entries["quest:92751"] = {n="Детонація на відстані",s="«Детонація на відстані» — завдання Альянсу, яке дає Джаспер Фел із розвідувального кола Стормвінда. Дізнавшись про небезпечну діяльність під Мунбруком, цей майстер шпигунів видає особливий дистанційний детонатор, щоб підривати безпечно й не висадити в повітря своїх же агентів.",h="«Детонація на відстані» — завдання Альянсу, яке дає Джаспер Фел із розвідувального кола Стормвінда.",kw={"детонація на відстані","джаспер фел","набір дистанційного детонатора","si:7","спрайт джампспрокет","мунбрук"},ang={["class:Rogue"]="Справи з Джаспером Фелом показують розгалужену таємну мережу SI:7: шпигунські майстри королівства стежать за польовими агентами й тихо забезпечують їх потрібними знаряддями.",["faction:Alliance"]="Завдання відбиває боротьбу Стормвінда за Вестфол, де замість відкритого розгортання війська використовують таємну інженерію й розвідку.",["profession:Engineering"]="Інженери оцінять дослідний дистанційний детонатор, створений, щоб замінити ризиковані ручні ґноти під час складних підривів у печерах.",["race:Gnome"]="Доставка для Спрайт Джампспрокет показує гномську винахідливість у дії в Стормвінді: найновіші дослідні зразки для шпигунів королівства."},sec={{t="Очі в тінях",b="Джаспер Фел і агенти SI:7 стежать майже за всім, що відбувається в землях Стормвінда, особливо на неспокійних прикордонних землях на кшталт Вестфолу. Коли до Фела доходить звістка про вибухові справи в Мунбруку, він уже добре знає, що назріває в покинутих шахтних тунелях під сільським краєм."},{t="Дослідний зразок",b="Влаштовувати потужні вибухи в тісних печерних системах — очевидно небезпечно. Фел видає дослідний Набір Дистанційного Детонатора, розроблений інженерами, що співпрацюють з Альянсом, — тож будь-який вибух під Вестфолом можна безпечно запустити ззовні. Він доручає гінцеві доставити це обладнання Спрайт Джампспрокет у Дворфійський Квартал і тихенько нагадує не згадувати про участь SI:7 перед знайомими ельфами."}},faq={{q="Хто такий Джаспер Фел?",a="Джаспер Фел — агент, пов'язаний з розвідкою Стормвінда, SI:7. Діючи з тіні, він стежить за прихованими загрозами по всьому королівству й надає особливе знаряддя, щоб із ними впоратися.",al={"джаспер фел","хто дає детонацію на відстані","видавець"}},{q="Чому SI:7 цікавиться Мунбруком?",a="Мунбрук потрапив у лапи розбійників і злочинців, і саме там наземний вхід до Мертвих Копалень. Будь-яка діяльність чи підриви глибоко під Вестфолом одразу привертають увагу внутрішньої розвідки Стормвінда.",al={"чому розвідка цікавиться мунбруком","зв'язок з дефіас","печери вестфолу"}},{q="Хто така Спрайт Джампспрокет?",a="Спрайт Джампспрокет — гномка-агентка з Дворфійського Кварталу Стормвінда, що опікується особливим технічним спорядженням і дослідними зразками.",al={"спрайт джампспрокет","хто отримає детонатор","кому здати"}},{q="Що за «друг-ельф», про якого згадує Джаспер Фел?",a="Джаспер Фел має на увазі знайомого ельфа, що допомагає вам у боротьбі з бунтівниками Вестфолу. SI:7 воліє діяти таємно й так, щоб завжди можна було відхреститися, тож сторонні союзники не знають про пряму підтримку розвідки.",al={"друг-ельф","не кажи ельфу","ельф джаспера фела"}},{q="Навіщо Набір Дистанційного Детонатора?",a="Це дослідний інженерний зразок, що дає змогу підривати заряди з безпечної відстані, — так агенти можуть обвалити чи розчистити підземні ходи, не опинившись у пастці.",al={"дистанційний детонатор","набір детонатора","що робить набір"}},{q="Куди веде це завдання?",a="За завданням ви маєте доставити набір детонатора просто до Спрайт Джампспрокет у Дворфійський Квартал Стормвінда.",al={"куди йти","маршрут завдання","місце здачі"}}},fp="24,289,19.312.0,20.438.1,18.200.0,35.236.0,27.147.0,44.230.0,42.183.0,31.126.0"}
P.entries["quest:92752"] = {n="Вибухова консультація",s="«Вибухова консультація» — завдання у Вестфолі, пов'язане з гномкою-винахідницею Спрайт Джампспрокет і Альбою Фермун. Роздобувши надзвичайно нестабільний заряд, Спрайт доручає гінцеві безпечно доставити його назад, не підірвавши ненароком детонатор.",h="«Вибухова консультація» — завдання у Вестфолі, пов'язане з гномкою-винахідницею Спрайт Джампспрокет і Альбою...",kw={"вибухова консультація","спрайт джампспрокет","альба фермун","надруйнівна вибухівка","детонатор","вестфол"},ang={["faction:Alliance"]="Агенти Альянсу по всьому Вестфолу покладаються на незвичну зброю, щоб протистояти укріпленим розбійницьким таборам і здичавілим механізмам.",["profession:Engineering"]="Кожен практикуючий інженер упізнає типові ризики гномських боєприпасів: максимальна потужність у парі з детонатором, що спрацьовує від подиху.",["race:Gnome"]="Спрайт Джампспрокет уособлює вибуховий підхід Гномреґану до розв'язання проблем і несе на неспокійний фронт Вестфолу потужні технічні рішення."},sec={{t="Нестабільний вантаж",b="Гномська інженерія рідко славиться поміркованістю, і робота Спрайт Джампспрокет для Вестфолу цілком виправдовує цю славу. Довівши суміш до ладу, Спрайт видає в'язку Надруйнівної Вибухівки для Альби Фермун. Робота гінця у воєнному Вестфолі й так небезпечна — треба уникати розбійників Дефіасу й диких звірів, — а нести живі боєприпаси, що вибухають від найменшого дотику, — це вже зовсім інший рівень ризику."},{t="Обережно з вантажем",b="Передаючи заряд, Спрайт Джампспрокет дає просту, але життєво важливу пораду: стережіться детонатора. Хоч би для чого призначався цей нестабільний вантаж — розчищати перешкоди, руйнувати укріплення чи підривати діяльність Дефіасу на спірних рівнинах, — він має дістатися цілим, перш ніж Альба Фермун пустить його в хід."}},faq={{q="Хто дає завдання «Вибухова консультація»?",a="Завдання дає Спрайт Джампспрокет — гномка-винахідниця з Дворфійського Кварталу Стормвінда, що постачає особливу вибухівку.",al={"хто дає вибухову консультацію","видавець вибухової консультації","завдання спрайт джампспрокет"}},{q="Хто отримує вибухівку наприкінці завдання?",a="Готову Надруйнівну Вибухівку треба доставити просто до Альби Фермун у Вестфол.",al={"куди нести вибухівку","хто здає вибухову консультацію","вибухівка альби фермун"}},{q="Що вам доручено перевезти?",a="Спрайт довіряє вам пакунок Надруйнівної Вибухівки разом із ввімкненим і делікатним детонатором.",al={"що передає спрайт","предмет вибухової консультації","що за бомба"}},{q="Навіщо вибухівка у Вестфолі?",a="Вестфол охоплений боротьбою з Братством Дефіас і кишить ворожими механізмами та мародерами. Щоб трощити барикади, розчищати завалені шляхи чи знешкоджувати укріплені загрози на полях, часто потрібна потужна вибухівка.",al={"навіщо бомби","мета вибухівки у вестфолі","чому підривати у вестфолі"}},{q="Чи доступне це завдання шукачам пригод з Орди?",a="Ні. Спрайт Джампспрокет і Альба Фермун підтримують операції Альянсу, тож це завдання лише для гравців Альянсу.",al={"чи орда може вибухову консультацію","вибухова консультація орда"}},{q="Чи попереджає Спрайт Джампспрокет про якусь небезпеку?",a="Спрайт прямо застерігає, що бомбу зведено, тож у дорозі з детонатором треба поводитися надзвичайно обережно.",al={"чи попереджає спрайт","попередження про бомбу"}}},fp="22,272,19.431.0,18.319.0,44.133.0,52.98.0,43.115.0,38.246.0,45.132.0,60.123.0"}
P.entries["quest:92753"] = {n="Руйнування в Мертвих Копальнях",s="«Руйнування в Мертвих Копальнях» — таємна диверсійна місія, яку координує Альба Фермун, щоб ударити в саме серце промислового виробництва Братства Дефіас. Глибоко в лабіринтах тунелів під Мунбруком Братство тримає величезну металургійну кузню, яку підозрюють в отруєнні довколишньої землі. Шукачі пригод мають проникнути в комплекс, закласти потужну вибухівку біля ливарні й підірвати воєнну міць братства.",h="«Руйнування в Мертвих Копальнях» — таємна диверсійна місія, яку координує Альба Фермун, щоб ударити в саме...",kw={"руйнування в мертвих копальнях","мертві копальні","альба фермун","надруйнівна вибухівка","кузня","мунбрук"},ang={["faction:Alliance"]="Підрив кузні Дефіасу б'є просто по машинах і зброї, що загрожують суверенітету Стормвінда зсередини Вестфолу.",["profession:Mining"]="Колись Мертві Копальні були найприбутковішими золотими й залізними копальнями Стормвінда, а тепер Братство Дефіас перетворило їх на укріплений плавильний комплекс, що отруює землю."},sec={{t="Диверсія в ливарні",b="Мертві Копальні — це не лише золоті жили й злодюжки: під курною поверхнею Мунбрука лежить укріплений промисловий комплекс, що живить Братство Дефіас. Серед їхніх підземних споруд — важка металургійна кузня, де виплавляють метали й збирають машини. Альба Фермун вважає цю кузню ймовірним джерелом забруднення, що нищить край, тож її знищення — вкрай важлива мета."},{t="Вирішальний вибух",b="Reaching the heart of the Deadmines requires fighting through barricades, cutthroats, and goblin engineers. Armed with Extra-Destructive Explosives, an operative must plant the charge directly beside the forge works and make a hasty escape to the hills above Moonbrook, where Fairmoon waits so they can detonate the explosives and hopefully allow the land to heal."}},faq={{q="Яка мета цього доручення?",a="Треба проникнути в Мертві Копальні під Мунбруком, знайти металургійну кузню Братства Дефіас, закласти поруч Надруйнівну Вибухівку, а тоді зустрітися з Альбою Фермун біля виходу.",al={"мета завдання","що робити","що таке руйнування в мертвих копальнях"}},{q="Хто така Альба Фермун?",a="Альба Фермун — агентка Альянсу у Вестфолі, яка вважає, що пошесть і отрута, які псують край, походять від важкого переплавляння й промислової діяльності в Мертвих Копальнях.",al={"хто така альба","переказ про альбу фермун","видавець"}},{q="Чому кузню Дефіас вважають такою небезпечною?",a="Alba suspects that a large metallurgical forge in the Deadmines is the source of the poison. She hopes its destruction will allow the land to begin healing.",al={"чому знищити кузню","що робить кузня","отрута кузні"}},{q="Де гравець зустрічає Альбу після закладання вибухівки?",a="Альба Фермун чекає назовні, на пагорбах позаду Мунбрука біля верхнього виходу з Мертвих Копалень, готова здійснити підрив, щойно агент безпечно вибереться.",al={"де чекає альба","місце виходу з мертвих копалень","місце здачі"}},{q="Де в Мертвих Копальнях кузня?",a="Кузня — у глибині підземелля Мертві Копальні, за шахтними тунелями, у ливарних цехах, де працюють робітники Дефіас під наглядом гоблінів.",al={"де кузня","місце кузні в мертвих копальнях","знайти кузню"}},{q="Чи земля одразу оздоровиться, щойно кузню знищено?",a="Альба сподівається, що, коли важке переплавляння припиниться, земля довкола Мунбрука нарешті зможе відновитися, хоча на те, щоб змити сліди років промислу й занедбання з боку Дефіас, потрібен час.",al={"чи земля зцілиться","чи припиниться отрута","наслідки кузні"}}},fp="24,452,22.416.0,16.364.1,33.212.0,21.188.0,48.156.0,62.174.0,48.171.0,52.187.0"}
P.entries["quest:928"] = {n="Корона Землі",s="«Корона Землі» — перехідна подорож, що виводить юних нічних ельфів із Тінедола в ширші володіння Тельдрассила. Несучи священну воду місячного колодязя, освячену на вершині Алдрассила, мандрівники прямують на південь лісовою дорогою до Корітраса Мунрейджа в Доланаарі. Це випуск із відлюдного вишколу — до нагального екологічного захисту великого Світового Дерева.",h="«Корона Землі» — перехідна подорож, що виводить юних нічних ельфів із Тінедола в ширші володіння Тельдрассила.",kw={"корона землі","корітрас мунрейдж","тенарон стормґріп","місячний колодязь","тінедол","доланаар"},ang={["class:Druid"]="Перенесення освячених вод пов'язує молодих друїдів із тривалими, крихкими зусиллями плекати й урівноважувати буйну екосистему Тельдрассила.",["class:Priest"]="Нести воду місячного колодязя, освячену благодаттю Елуни, — священний обов'язок її жрецтва дбати про духовне здоров'я громади.",["race:NightElf"]="Крок за межі Тінедола — неодмінний обряд переходу для кожного юного калдорея, що вирушає служити своєму народові."},sec={{t="Прощання з галявиною",b="Довівши свою відданість збиранням зачарованої води з місячного колодязя Тінедола, посвячених кличуть до Тенарона Стормґріпа на вершину Алдрассила. Визнавши їхню готовність, Тенарон запечатує набрану воду в більшу посудину й велить вирушати за межі затишного гаю. Дорога на південь до Доланаара — головна артерія з Тінедола, що в'ється лісами, які стають дедалі непередбачуванішими й ворожішими."},{t="Дорога до Доланаара",b="Доланаар — перше велике село, яке зустрічають мандрівники, виходячи зі стартової долини. Поселення, що розкинулося вздовж брукованих стежок центрального Тельдрассила, вирує довкола власного незайманого місячного колодязя. Тут чекає Корітрас Мунрейдж — старійшина, якому доручено наглядати за ширшими зусиллями зі збереження на гіллі. Посудина, передана в його руки, пов'язує шукача пригод-початківця безпосередньо з ширшою, тривожною долею Світового Дерева."}},faq={{q="Що я несу до Доланаара?",a="Ви несете Частково Наповнену Посудину з освяченою водою з місячного колодязя в Тінедолі. Тенарон Стормґріп злив у цю посудину вашу першу пожертву, щоб Корітрас Мунрейдж міг продовжити обрядову роботу по всьому Тельдрассилу.",al={"що таке посудина","частково наповнена посудина","яка це вода"}},{q="Хто такий Корітрас Мунрейдж?",a="Корітрас Мунрейдж — старійшина нічних ельфів, що перебуває біля місячного колодязя в Доланаарі. Він залучає новоприбулих шукачів пригод до важливих обрядів і розслідувань, потрібних, щоб підтримати щойно вирощене Світове Дерево.",al={"хто такий корітрас","роль корітраса мунрейджа","де корітрас"}},{q="Чому Тенарон відсилає мене з Тінедолу?",a="Тінедол дає лише початковий вишкіл, а випробування, що постали перед Тельдрассилом, вимагають допомоги на всій гілці. Ви довели, що здатні впоратися з місцевими загрозами й вшанувати місячні колодязі, тож Тенарон посилає вас до Доланаара, де чекають ширші завдання.",al={"чому тенарон відсилає з тіньової долини","чому залишити тіньову долину","чому йти до доланаара"}},{q="Де дорога до Доланаара?",a="Ідіть бруківкою на південь від Алдрассила, повз ворота Тінедолу. Тримайтеся бруківки, коли стежка повертає на південь і захід, — і дійдете до села Доланаар.",al={"як дістатися доланаара","шлях до доланаара","дорога з тіньової долини"}},{q="Чому Тенарон застерігає про небезпечних звірів?",a="Навіть на священних гілках Тельдрассила тварини стали неприродно агресивними й збудженими. Хто зійде з мощеної стежки, ризикує наразитися на напади павуків, що стережуть свою територію, зіпсованих скверною нічних шаблезубів і агресивних деревоступів.",al={"чому небезпечні звірі","осквернені звірі тельдрассила","тримайся дороги"}},{q="Що буде, коли я дістануся Доланаара?",a="Корітрас Мунрейдж приймає посудину й доручає вам нові обов'язки — оглянути й благословити інші місячні колодязі Тельдрассила, що відкриває глибші негаразди, які вразили ліс.",al={"що після корони землі","наступне завдання доланаара","що робить корітрас"}}},fp="18,388,17.462.0,20.460.0,31.243.0,26.209.0,46.250.0,30.199.0,45.223.0,37.178.0"}
P.entries["quest:92819"] = {n="Руйнування в Мертвих Копальнях",s="«Руйнування в Мертвих Копальнях» — таємна місія під наглядом Альби Фермун у Вестфолі. Агента, якому доручено запустити вибуховий заряд, відправляють глибоко під землю краю, щоб підірвати пристрій і завдати нищівного удару по діяльності Дефіасу в лабіринтах тунелів.",h="«Руйнування в Мертвих Копальнях» — таємна місія під наглядом Альби Фермун у Вестфолі.",kw={"руйнування в мертвих копальнях","альба фермун","детонатор","диверсія","братство дефіас","вестфол"},ang={["class:Rogue"]="Проникнути на ворожу землю, закласти заряди й вислизнути до вибуху — класична вправа з таємної диверсії.",["faction:Alliance"]="Кожен удар по твердині Дефіасу в Мертвих Копальнях допомагає вберегти знесилені господарства Вестфолу й південний кордон Стормвінда.",["profession:Engineering"]="Підриви й дистанційні детонатори — суть цього доручення, тож воно припаде до смаку інженерам, які цінують тонке мистецтво керованого обвалу."},sec={{t="Диверсія під Вестфолом",b="Мертві Копальні здавна ховають головну силу Братства Дефіас — це і твердиня, і промисловий нервовий вузол просто під Вестфолом. Замість покладатися лише на прямий штурм кожного укріпленого коридору, Альба Фермун скеровує рішучу диверсію. Заклавши вибухівку й підірвавши її в підземному комплексі, агенти Альянсу прагнуть обвалити важливі споруди й зірвати всі задуми, які братство плете в темряві."},{t="Детонатор",b="Для цього доручення потрібні тверда рука й точний розрахунок часу. Альба видає детонатор, щоб підірвати заряди, закладені всередині твердині. Удар просто по вразливих місцях копальні гарантує, що Братство Дефіас зазнає тривалих втрат — у шляхах постачання, машинах і оборонних спорудах, — і це дасть захисникам Вестфолу нагорі дорогоцінний час."}},faq={{q="Хто дає завдання «Руйнування в Мертвих Копальнях»?",a="Це доручення дає Альба Фермун — агентка у Вестфолі, що посилає шукачів пригод з Альянсу завдати удару просто по твердині Братства Дефіас.",al={"хто дає руйнування в мертвих копальнях","видавець","завдання альби фермун"}},{q="Яка головна мета цього доручення?",a="Вам треба привести в дію детонатор у Мертвих Копальнях, щоб підірвати вибухівку й підкосити операції Дефіас, приховані під землею краю.",al={"що робити в руйнуванні в мертвих копальнях","мета руйнування","як виконати руйнування"}},{q="Чому саме Мертві Копальні треба підірвати?",a="Мертві Копальні — не просто покинута золота копальня: тут головні майстерні, склади й складальні цехи Братства Дефіас. Обваливши ключові місця вибухівкою, можна зірвати його підземну кампанію проти Вестфолу й Стормвінда.",al={"чому підірвати мертві копальні","саботаж мертвих копалень","навіщо детонатор у копальнях"}},{q="Де відбувається це завдання?",a="Доручення починається в Альби Фермун у Вестфолі й веде вас у розлогі підземні тунелі Мертвих Копалень під Мунбруком.",al={"місце руйнування","де руйнування в мертвих копальнях","місце детонатора"}},{q="Чи доступне це доручення гравцям Орди?",a="Ні. Альба Фермун працює лише з агентами Альянсу, які боронять Вестфол від дедалі грізнішого Братства Дефіас.",al={"чи руйнування лише для альянсу","чи орда може руйнування"}},{q="Чим Братство Дефіас загрожує Вестфолу?",a="Братство Дефіас вигнало фермерів, грабує поселення й захопило покинуті копальні Вестфолу. Діючи з глибин Мертвих Копалень, воно готує збройне повстання, яке прямо загрожує королівству Стормвінд.",al={"переказ про дефіас вестфол","чому битися з дефіас","що дефіас роблять у мертвих копальнях"}}},fp="24,262,25.499.0,13.386.0,46.165.0,46.154.0,41.268.0,33.139.0,43.132.0,57.242.0"}
P.entries["quest:929"] = {n="Корона Землі",s="«Корона Землі» — священне завдання від Корітраса Мунрейджа в Доланаарі: набрати освяченої води з місячного колодязя біля Села Зоряного Вітерця. В обмін на поповнення вод Дарнасуса юні нічні ельфи дізнаються трагічну історію, що привела їхній народ до вирощування могутнього гілля Тельдрассила.",h="«Корона Землі» — священне завдання від Корітраса Мунрейджа в Доланаарі: набрати освяченої води з місячного...",kw={"корона землі","корітрас мунрейдж","місячний колодязь","село зоряного вітерця","нордрассил","малфуріон стормрейдж","іллідан"},ang={["class:Druid"]="Місячні колодязі — життєво важливі провідники природної й зоряної магії, живі водойми, що пов'язують обов'язки вашого ордену в Дарнасусі з корінням Тельдрассила.",["race:NightElf"]="Кожен нічний ельф мусить зустрітися з втратою безсмертя й зникненням Малфуріона Стормрейджа, тож цей священний обряд збирання — неодмінний урок недавнього горя вашого народу."},sec={{t="Живлення місячних колодязів",b="Великий центральний місячний колодязь Дарнасуса потребує постійного зв'язку з меншими джерелами, розсіяними по короні Світового Дерева. Друїди виготовляють витончені нефритові фіали саме для того, щоб набирати й переносити ці сяйливі води, не порушуючи їхньої чистоти. Посилаючи посвячених пішки до Села Зоряного Вітерця, старійшини дбають і про те, щоб міські фонтани повнилися благодаттю Елуни, і про те, щоб молодь зрозуміла, якої праці вимагає живлення Тельдрассила."},{t="Відлуння Третьої війни",b="За виконану роботу посвячений одержує в нагороду усну історію. Корітрас Мунрейдж розповідає про розпач, що охопив калдорей одразу після битви за гору Гіджал. Жертва прадавнього Світового Дерева Нордрассил позбавила нічних ельфів дорогоцінного безсмертя, а серед руїни на волю вирвався Іллідан Стормрейдж, тоді як Шан'до Малфуріона Стормрейджа поглинув Смарагдовий Сон. Ця атмосфера скорботи й самотності заклала підґрунтя для суперечливого висадження Тельдрассила."}},faq={{q="Навіщо набирати воду з місячного колодязя?",a="Друїди Дарнасуса регулярно поповнюють головний міський місячний колодязь водою з лісових святинь довкола, підтримуючи священну мережу по всьому Тельдрассилу.",al={"навіщо вода з місячного колодязя","вживання води колодязя","мета нефритової пляшки"}},{q="Де місячний колодязь для цього завдання?",a="Місячний колодязь — одразу за Селом Зоряного Вітерця, на схід від Доланаара вздовж лісової стежки.",al={"де місячний колодязь","місце колодязя зоряного бризу","колодязь села зоряного бризу"}},{q="Хто такий Корітрас Мунрейдж?",a="Корітрас Мунрейдж — друїд нічних ельфів у Доланаарі, що проводить молодих шукачів пригод крізь обрядові обов'язки й знайомить з історією, пов'язаною зі здоров'ям Тельдрассила.",al={"хто дає завдання","переказ про корітраса мунрейджа"}},{q="Яку історію розповідає Корітрас, коли ви повертаєтеся?",a="Він розповідає про страшні наслідки Битви за Гору Гіджал: як згорів Нордрассіл, як зникло безсмертя калдореїв, як звільнили Іллідана і як зник Шан'до Малфуріон Стормрейдж.",al={"що каже корітрас","текст про корону землі"}},{q="Чому нічні ельфи почуваються втраченими після Гори Гіджал?",a="Нордрассіл дарував нічним ельфам вічне життя й захист. Пожертвувавши силою дерева, щоб знищити Архімонда, вони зруйнували своє позачасове існування й стали смертними, розгубленими й глибоко вразливими.",al={"чому нічні ельфи втратили безсмертя","що сталося після гіджала"}},{q="Що таке «Шан'до»?",a="«Шан'до» — шанобливе звертання дарнаською мовою, що означає «шановний учитель»; тут так називають Малфуріона Стормрейджа, верховного провідника друїдів.",al={"що означає шан'до","значення шан'до"}}},fp="18,313,24.463.0,23.498.0,46.189.0,44.106.0,26.168.0,46.200.0,47.222.0,18.146.0"}
P.entries["quest:93"] = {n="Сутінкові Крабові Котлети",s="У Шеф-кухаря Ґруала з Таверни «Багряний Крук» у Даркширі є таємниця знаменитих Сутінкових Крабових Котлет: краба в них немає зовсім. Допомагаючи зголоднілому й знервованому Тремтієві, шукачі пригод вирушають добувати ноги смертоносних павуків, що нишпорять північним Сутінколіссям, щоб приготувати улюблену місцеву закуску.",h="У Шеф-кухаря Ґруала з Таверни «Багряний Крук» у Даркширі є таємниця знаменитих Сутінкових Крабових Котлет...",kw={"сутінкові крабові котлети","шеф-кухар ґруал","тремтій","павуки","кулінарія","даркшир"},ang={["faction:Alliance"]="Ця страва показує хиткий стан південного прикордоння Альянсу: через занедбану інфраструктуру й перерізані шляхи постачання міста на кшталт Даркшира змушені харчуватися велетенськими паразитами.",["profession:Cooking"]="Шеф-кухар Ґруал показує, якої витримки вимагає від кухарів прикордоння: навіть страхітливих лісових хижаків на кшталт велетенських отруйних павуків можна обернути на гордість місцевої кухні."},sec={{t="Сумнівний делікатес",b="Сутінколісся давно потерпає від відрізаності, темної магії й перерваних шляхів постачання, тож мешканцям Даркшира довелося пристосувати свою кухню. Шеф-кухар Ґруал, кухар Таверни «Багряний Крук», розв'язав проблему браку м'яса, вигадавши Сутінкову Крабову Котлету. Хоч назва й натякає на дари далеких морів, Ґруал охоче визнає, що характерний пікантний смак страви дають виключно слизькі ноги місцевих велетенських павуків."},{t="Полювання на тенетників",b="Щоб виконати замовлення, Ґруал посилає мисливців на північ, до підніжжя пагорбів і річкових берегів, де отруйні павуки-тенетники плетуть свої пастки. У похмурому лісі, що кишить нежиттю й дикими звірами, добувати свіже павуче м'ясо — небезпечна справа, та воно лишається одним із небагатьох доступних джерел поживи в зотлілих хащах. Ґруал смажить приправлені павучі лапи на розпеченій пательні до хрусткої скоринки."},{t="Розрада для проклятої душі",b="Кулінарне доручення народжується з турботи про Тремтія — збудженого волоцюгу, що ховається в покинутому селищі Воронячий Пагорб на заході Сутінколісся. Поглинутий провиною й тремтячий від жаху, адже ненароком накликав на край жахіття, Тремтій ні про що, крім порожнього шлунка, думати не може. Гаряча партія смачних павучих котлет Ґруала стає для нього рідкісною, хоч і дивною, розрадою в жалюгідному вигнанні."}},faq={{q="Чи справді Сутінкові Крабові Котлети з краба?",a="Ні. Шеф-кухар Ґруал відверто зізнається шукачам пригод, що Сутінкові Крабові Котлети цілком зроблені з драглистих павучих лап. Даркшир не має виходу до моря чи свіжих крабів, тож Ґруал бере місцевих велетенських павуків: їхнє м'ясо схоже на крабове й дає гострувату, пікантну закуску.",al={"чи котлети з краба","таємниця крабових котлет","з чого котлети"}},{q="Де Шеф-кухар Ґруал бере павучі лапи?",a="Ґруал покладається на шукачів пригод, що здобувають драглисті лапи павуків-отрутоплетів. Ці агресивні павукоподібні гніздяться здебільшого на півночі Сутінколісся, між лісовим передгір'ям і річкою.",al={"де павучі лапи","місця павуків сутінкового лісу","де отруйні павуки"}},{q="Для кого готують ці котлети?",a="Ґруал подає їх відвідувачам у Даркширі, але цю партію замовлено для Тремтія — переляканого відлюдника, що голодує в місті-привиді Воронячий Пагорб на заході Сутінколісся й відчайдушно шукає, чим би вгамувати бурчання в животі.",al={"для кого котлети","хто їсть котлети","навіщо готувати котлети"}},{q="Чи навчить мене Шеф-кухар Ґруал готувати Сутінкові Крабові Котлети?",a="Шеф-кухар Ґруал суворо береже точний рецепт Сутінкових Крабових Котлет і не розкриває своєї фірмової суміші спецій. Утім, тих шукачів пригод, що йому допомагають, він винагороджує іншим рецептом зі свого кулінарного арсеналу.",al={"чи навчить мене ґруал","рецепт крабових котлет"}},{q="Чому Даркшир харчується павуками?",a="Дороги Сутінколісся облягають нежить, воргени Найтбейн і ворожі істоти, тож торговельні каравани й хліборобство майже завмерли. Свіжої худоби й привізних товарів обмаль, тож мешканці Даркширу винахідливо використовують будь-яку дичину, яку вдається впіймати.",al={"чому даркшир їсть павуків","нестача їжі в сутінковому лісі"}},{q="Чи знає Тремтій, що котлети з павуків?",a="Тремтієві кортить саме знаменитих Ґруалових крабових котлет, а з чого вони — йому байдуже. Скутий жахом і голодом у лісі, він радий будь-якій знайомій страві з Даркширу, хай яке моторошне її походження.",al={"чи тремтій знає про павуків","реакція тремтія"}}},fp="16,310,23.436.0,22.409.0,25.412.1,43.254.0,42.185.0,40.245.0,54.229.0,44.258.0,48.228.0"}
P.entries["quest:930"] = {n="Сяйливий плід",s="«Сяйливий плід» — завдання в Тельдрассилі, що починається з відкриття дивної плодоносної рослини, яка росте дико в лісі. Підозрюючи щось неприродне, юні шукачі пригод несуть сяйливий зразок травникові Деналану до Озера Ал'Амет на дослідження.",h="«Сяйливий плід» — завдання в Тельдрассилі, що починається з відкриття дивної плодоносної рослини, яка росте...",kw={"сяйливий плід","деналан","озеро ал'амет","болотяники","насіння","тельдрассил"},ang={["class:Druid"]="Для друїдів, відданих збереженню рівноваги природи, чужоземна нестійка флора, що неприродно буяє на священному гіллі Тельдрассила, — негайний тривожний сигнал.",["profession:Herbalism"]="Травники оцінять ботанічну проникливість Деналана щодо того, як чужоземне насіння перетинає континенти й мутує, потрапляючи в зачарований ґрунт.",["race:NightElf"]="Молодь калдорей дізнається від Деналана, що навіть юний ґрунт їхньої нової домівки, Тельдрассила, вразливий до непередбачуваних чужоземних пошестей."},sec={{t="Неприродний урожай",b="Мандруючи туманним гіллям Тельдрассила, дослідники часом натрапляють на дивну світну флору з великими круглими плодами. Зважаючи на тонку рівновагу Світового Дерева й недавню дивну поведінку острівної живності, незвичні ботанічні зразки вимагають уважного вивчення. Переконані, що дивний ріст не можна лишати без уваги, шукачі пригод зривають осяйний урожай, щоб віднести тому, хто знається на дикій флорі."},{t="Дослідження Деналана",b="Біля Озера Ал'Амет обізнаний садівник і травник Деналан приймає сяйливий плід із захопленням і тривогою водночас. Він зауважує, що зразок виглядає чужоземним, і припускає, що його насіння могло прибути з далеких земель за морем — можливо, навіть зі Східних Королівств. Та найбільше Деналана непокоїть те, як чужинське насіння зреагувало на ґрунт самого Тельдрассила, — реакція, що одразу спричиняє агресивний спалах ворожих болотяників, щойно хтось торкається плоду."}},faq={{q="Де росте Дивна Плодоносна Рослина?",a="Дивна Плодоносна Рослина росте в диких нетрях Тельдрассила, захована в підліску далеко від великих поселень. Торкнувшись її, ви отримуєте Сяйливий Плід — і завдання починається.",al={"де росте рослина","місце дивної рослини","як почати сяйливий плід"}},{q="Хто такий Деналан?",a="Деналан — травник і ботанік із нічних ельфів, що живе на березі Озера Ал'Амет. Він днями доглядає ґрунт, вивчає місцеву рослинність і стежить за дивними порушеннями в природі Тельдрассила.",al={"де деналан","деналан","кому здати сяйливий плід"}},{q="Чому плід світиться?",a="Чому плід світиться, не встановлено. Деналан вважає його незвичайним зразком і збирається його дослідити.",al={"чому плід світиться","що не так із плодом"}},{q="Що станеться, коли віддати плід Деналанові?",a="Принесіть сяйливий плід Деналанові до Озера Ал'Амет на огляд. Що він з'ясує і чим скінчиться доставка, стане відомо, коли ви повернетеся.",al={"що з'явиться після завдання","засідка болотяників"}},{q="Звідки, на думку Деналана, взялася ця рослина?",a="Деналан підозрює, що насіння рослини, можливо, походить з-за Великого Моря — його занесли до Калімдору з далекого східного континенту Азероту.",al={"звідки насіння","походження плоду"}},{q="Чи пов'язане це завдання з іншими негараздами в природі Тельдрассила?",a="Так. Воно стає частиною ширших досліджень Деналана: чому гілки Тельдрассила й місцеві лісові створіння, як-от деревляники й болотяні чудовиська, стають дедалі неспокійнішими й неприроднішими.",al={"осквернення тельдрассила","проблеми озера аль'амет"}}},fp="17,255,20.451.0,23.495.1,41.204.0,15.228.0,24.113.0,48.142.1,46.152.0,67.199.0"}
P.entries["quest:931"] = {n="Мерехтливе листя",s="Серед коріння й крон Тельдрассила знайдено дивовижну рослину, що випромінює неземне мерехтіння. Усвідомлюючи її рідкісність, мандрівники несуть зразок ботанікові Деналану до Озера Ал'Амет, щоб з'ясувати її походження.",h="Серед коріння й крон Тельдрассила знайдено дивовижну рослину, що випромінює неземне мерехтіння.",kw={"мерехтливе листя","деналан","озеро ал'амет","болото скорботи","рослина","тельдрассил"},ang={["class:Druid"]="Друїди, що пильнують рівновагу Великого Дерева, беруть на замітку чужорідні рослини, занесені до тонкої молодої крони Тельдрассила.",["profession:Herbalism"]="Травники й шанувальники рослин оцінять ботанічну інтригу: болотяна рослина буяє за тисячі миль від рідної екосистеми.",["race:NightElf"]="Для нічних ельфів, що доглядають нову домівку, досліди Деналана дають важливе розуміння того, наскільки витривалий насправді ґрунт Тельдрассила."},sec={{t="Дивне сяйво",b="Блукаючи зеленим гіллям Тельдрассила, уважні мандрівники можуть натрапити на дивну рослину з розлогим листям. На відміну від звичайної лісової зелені, її листя ловить світло й мерехтить пульсівним, звивистим сяйвом. Така неприродна поява впадає в око кожному, хто дбає про тонку, щойно народжену екосистему острова."},{t="Відкриття Деналана",b="Принесений ботанікові Деналану до Озера Ал'Амет живець відкриває несподівану правду. Деналан упізнає в рослині чужоземний зразок, не властивий півночі Калімдору: востаннє він бачив такий вид десятиліття тому, під час подорожі до далекого Болота Скорботи у Східних Королівствах. Зачарований тим, як таке насіння могло перетнути океан і вирости на Світовому Дереві до таких вражаючих розмірів, Деналан одразу береться вирощувати й випробовувати зразок."}},faq={{q="Звідки походить ця дивна рослина?",a="За словами ботаніка Деналана, батьківщина рослини — Болото Скорботи, каламутне мочарисько далеко на південному сході Східних Королівств. Живого її зразка він не бачив відтоді, як побував на тих болотах кілька десятиліть тому.",al={"походження рослини","звідки ця рослина","болотяна рослина"}},{q="Хто такий Деналан?",a="Деналан — допитливий ботанік і травник із нічних ельфів, що живе біля берегів Озера Ал'Амет на Тельдрассилі. Він вивчає й плекає молоду рослинність Тельдрассила і часто експериментує з чужоземним насінням і діжками для розсади.",al={"переказ про деналана","хто такий деналан"}},{q="Чому ця рослина росте на Тельдрассилі?",a="Це досі загадка природи. Деналан дивується, як насінина змогла подолати шлях зі Східних Королівств через Велике Море, а тоді ще й прорости й вирости в такий великий екземпляр у родючому ґрунті Тельдрассила.",al={"як потрапила на тельдрассил","чому тут рослина"}},{q="Що буде, коли віддати лист Деналанові?",a="Деналан одразу садить зразок у свою діжку біля Озера Ал'Амет, щоб провести досліди. Під його доглядом кілька пагонів швидко розпускаються, і вивчення екзотичної рослини триває далі.",al={"наступне завдання","випробування деналана","проросле листя"}},{q="Чи ця рослина поширює скверну на Тельдрассилі?",a="Ні. Чимало звірів Тельдрассила потерпає від прихованої скверни, але ця рослина, схоже, — просто незвичний екзотичний вид, що опинився не на своєму місці, а не носій скверни.",al={"чи рослина осквернена","осквернена рослина"}}},fp="20,224,14.334.0,19.478.1,50.222.0,15.252.0,40.225.0,47.204.1,47.188.0"}
P.entries["quest:932"] = {n="Спотворена ненависть",s="«Спотворена ненависть» — таємне завдання від Таллонкая Свіфтрута в Тельдрассилі. Він просить довірених звитяжців спуститися в печеру Скелі Скверни й стратити Лорда Меленаса — сатира, що збирає місцевих ґреллів в організовану зіпсуту силу небезпечно близько до поселень нічних ельфів.",h="«Спотворена ненависть» — таємне завдання від Таллонкая Свіфтрута в Тельдрассилі.",kw={"спотворена ненависть","лорд меленас","сатир","скеля скверни","ґрелли","таллонкай свіфтрут","тельдрассил"},ang={["class:Druid"]="Мерзенна присутність Меленаса та його зіпсутих ґреллів біля Скелі Скверни труїть крихку рівновагу щойно вирослих хащ Тельдрассила.",["race:NightElf"]="Кожен сатир — давнє нагадування про падіння ваших предків перед демонічними амбіціями; стяти Лорда Меленаса — і обов'язок перед Світовим Деревом, і акт спокути за предків."},sec={{t="Гірка ганьба",b="Для нічних ельфів сатири — жива пам'ять про давню зраду. Народжені з Високородних, що віддалися Палаючому Легіону під час Війни Прадавніх, ці козлоногі демони — болюча, невитравна пляма на історії калдорей. Те, що сатир закріпився просто тут, у Тельдрассилі, молодому Світовому Дереві, яке мало стати прихистком, місцеві захисники, як-от Таллонкай Свіфтрут, сприймають як гостру ганьбу."},{t="Загроза біля Скелі Скверни",b="На північ від найближчих стежок лежить Скеля Скверни — зіпсута система печер, що кишить здичавілими ґреллами. Лорд Меленас згуртував цих від природи хаотичних створінь у ворожу, впорядковану силу під своєю темною волею. Побоюючись того, що сатир замислив випустити на гілля Світового Дерева, Таллонкай вимагає усунути Меленаса швидко, тихо й рішуче — і принести на доказ його відтяту голову."}},faq={{q="Хто такий Лорд Меленас?",a="Лорд Меленас — сатир, що захопив печеру Скеля Скверни на півночі Тельдрассила. Він верховодить зграєю агресивних греллів-вояків і замишляє поширити скверну по всьому Світовому Дереву.",al={"лорд меленас","хто такий меленас","бос скелі скверни"}},{q="Де знайти Лорда Меленаса?",a="Він ховається в глибині Скелі Скверни — порізаної печерами скелі на північ від Доланаара на Тельдрассилі — серед греллів та інших зіпсованих скверною істот.",al={"місце меленаса","де меленас","як знайти скелю скверни"}},{q="Чому Таллонкай Свіфтрут хоче тримати це в таємниці?",a="Сатири — жахлива сторінка давньої історії нічних ельфів: вони зрадили свій народ під час Війни Прадавніх. Те, що один із них так зухвало засів у самому серці щойно посадженого Світового Дерева, — справжня ганьба, і Таллонкай воліє розв'язати справу, не здіймаючи загальної паніки.",al={"чому таємниця","чому це між нами","таємниця таллонкая"}},{q="Що пов'язує сатирів і греллів?",a="Грелли — дрібні, пустотливі й від природи зіпсовані скверною дикі створіння, що водяться по всьому Тельдрассилу. Сатири, хитрі й демонічні за своєю суттю, охоче залякують або підкоряють таких нижчих істот, змушуючи служити своїм мерзенним задумам.",al={"греллі й сатири","чому греллі йдуть за меленасом","зв'язок сатирів і греллів"}},{q="Звідки взагалі на Тельдрассилі сатири?",a="Тельдрассил виростили лише кілька років тому, без благословення Аспектів драконів. Хоч друїди й сподівалися на чистий прихисток, скверна й темні істоти швидко прокралися на острів, а сатири крадькома закріпилися в похмурих місцях на кшталт Скелі Скверни.",al={"сатири на тельдрассилі","звідки тут сатири","осквернення тельдрассила"}},{q="Хто такий Таллонкай Свіфтрут?",a="Таллонкай Свіфтрут — охоронець із нічних ельфів, що перебуває біля Доланаара. Він пильнує нові загрози Тельдрассилові й доручає шукачам пригод знешкоджувати осередки скверни поблизу.",al={"таллонкай","хто дає спотворену ненависть"}}},fp="14,280,17.452.0,22.395.0,20.193.0,30.143.0,51.299.0,50.218.0,54.273.0,27.189.0"}
P.entries["quest:933"] = {n="Корона Землі",s="«Корона Землі» — завдання Альянсу від Корітраса Мунрейджа в Доланаарі. Він велить вам набрати води з місячного колодязя біля Озерець Арлітрієну — у краї, якому дедалі більше загрожують знавіснілі фурболґи Вузлошкіри. Виконавши завдання, ви дізнаєтеся, як Архідруїд Фандрал Стаґгелм згуртував нічних ельфів, щоб виростити Тельдрассил після зникнення Малфуріона Стормрейджа.",h="«Корона Землі» — завдання Альянсу від Корітраса Мунрейджа в Доланаарі.",kw={"корона землі","корітрас мунрейдж","озерця арлітрієну","фандрал стаґгелм","вузлошкіри","місячний колодязь","тельдрассил"},ang={["class:Druid"]="Розкол Кола Кенарія під проводом Фандрала Стаґгелма стає зрозумілішим, коли Корітрас розповідає про відчайдушне прагнення повернути давнє безсмертя.",["race:NightElf"]="Цей відтинок вашої подорожі пояснює суперечливий політичний поштовх, що породив Тельдрассил після раптового зникнення Малфуріона."},sec={{t="Небезпечний місячний колодязь",b="Корітрас Мунрейдж доручає вам віднести турмалінову фіалу до місячного колодязя на південний схід від входу в Дарнасус, на берегах Озерець Арлітрієну. Дорога зовсім не спокійна. Колись мирні фурболґи Вузлошкіри піддалися раптовій кривавій люті: вони нападають на мандрівників із засідок і виснажують патрулі Вартових по всьому краю. Те, що перші звіти списували на окремі сутички, переросло в повсюдну загрозу, яка переслідує нову домівку нічних ельфів."},{t="Амбіції Фандрала Стаґгелма",b="Одержавши наповнену фіалу, Корітрас ділиться важливою історією створення Тельдрассила. Після Третьої війни Шан'до Малфуріон Стормрейдж зник, і друїди Кола Кенарія лишилися без проводу, розколоті. За його відсутності мантію лідера перебрав Архідруїд Фандрал Стаґгелм. Стаґгелм переконав Коло Древніх у Темному Узбережжі, що нічні ельфи не можуть дозволити собі бездіяльної жалоби: їм треба повернути втрачене безсмертя й зцілити свою цивілізацію, висадивши нове величезне Світове Дерево."}},faq={{q="Де місячний колодязь для цього завдання?",a="Місячний колодязь — на південний схід від головного входу до Дарнасуса, на південному березі Озерець Арлітрієну.",al={"місце колодязя арлітрієн","місце місячного колодязя","де наповнити пляшку"}},{q="Чому фурболги Вузлошкіри нападають?",a="Вузлошкіри здавна були мирним родом ведмедолюдів, але останнім часом по всьому Тельдрассилу їх охопила темна безтямна лють. Спершу Вартові вважали перші напади поодинокими випадками, але скверна швидко поширилася, і тепер фурболги — постійна загроза для поселень і патрулів поблизу.",al={"фурболги розлючені","вузлошкіри агресивні","чому фурболги нападають"}},{q="Що сталося з Малфуріоном Стормрейджем?",a="Шан'до Малфуріон Стормрейдж безслідно зник після Третьої війни. Ні друїди Кенарія, ні провід нічних ельфів досі не знають, що з ним сталося і де він нині спить.",al={"де малфуріон","що сталося з стормрейджем","малфуріон зник"}},{q="Хто вирішив посадити Тельдрассил?",a="Коли Малфуріон зник, провід над друїдами взяв Архідруїд Фандрал Стаґгелм. Він переконав Коло Прадавніх на Темному Узбережжі підтримати вирощування нового Світового Дерева, доводячи, що без нього калдореї не відродяться й не повернуть безсмертя, втрачене, коли загинув Нордрассіл.",al={"хто створив тельдрассил","стаґгелм світове дерево","чому виростили тельдрассил"}}},fp="18,377,19.474.0,27.513.0,37.131.0,41.317.0,37.210.0,32.292.0"}
P.entries["quest:934"] = {n="Корона Землі",s="«Корона Землі» — ключовий крок у ланцюжку завдань Доланаара, що досліджує недуги Тельдрассила. Корітрас Мунрейдж доручає шукачам пригод набрати води зі священного місячного колодязя на Галявині Оракула, а подорож використовує, щоб відкрити тривожну правду про створення Світового Дерева.",h="«Корона Землі» — ключовий крок у ланцюжку завдань Доланаара, що досліджує недуги Тельдрассила.",kw={"корона землі","галявина оракула","аметистова фіала","фандрал стаґгелм","ноздорму","алекстраза","корітрас мунрейдж"},ang={["class:Druid"]="Для Кола Кенарія відвідини Дерева Оракула підкреслюють ідейний розкол між наполегливими амбіціями Фандрала Стаґгелма й природною рівновагою, яку традиційно беріг Малфуріон Стормрейдж.",["faction:Alliance"]="Розуміння крихкого стану Тельдрассила пояснює невідступну пошесть і безумство створінь, що мучать найновішу столичну землю Альянсу.",["race:NightElf"]="Подорож торкається надій нічних ельфів на Тельдрассил після жертви Нордрассила в Третій війні."},sec={{t="Галявина Оракула",b="Корітрас Мунрейдж скеровує мандрівників далеко на північний захід Тельдрассила, під величну крону Галявини Оракула. Просто під могутнім гіллям Дерева Оракула лежить перший і найпотужніший місячний колодязь, зведений на острові. Наповнивши Аметистову Фіалу з його мерехтливих вод, шукачі опиняються віч-на-віч із головним святилищем, звідки друїди й саме дерево стежать за здоров'ям нової батьківщини."},{t="Відмовлене благословення",b="Коли ви повертаєте фіалу до Доланаара, Корітрас відкриває темну ваду у величному задумі Архідруїда Фандрала Стаґгелма. Після жертви Нордрассила на горі Гіджал Стаґгелм прагнув повернути нічним ельфам безсмертя: висадити Тельдрассил і попросити благословення Драконячих Аспектів. Але Ноздорму Позачасний відмовив, дорікнувши Стаґгелмові за його зухвалу пиху. Королева Алекстраза вчинила так само й не дала життєво важливого благословення Аспекта Життя — тож ріст Тельдрассила лишився бурхливим, недосконалим і вразливим до глибокого зіпсуття."}},faq={{q="Де місячний колодязь на Галявині Оракула?",a="Місячний колодязь — на північному заході Тельдрассила, просто на північ від головної дороги до Дарнасуса. Він лежить під могутніми гілками Дерева Оракула.",al={"місце галявини оракула","місце колодязя галявини оракула","колодязь оракула"}},{q="Хто такий Корітрас Мунрейдж?",a="Корітрас Мунрейдж — охоронець із нічних ельфів у Доланаарі. Він веде молодих захисників гілками Тельдрассила, щоб набрати води з місячних колодязів, і розповідає історію хибного початку дерева.",al={"корітрас","хто такий корітрас мунрейдж"}},{q="Чи повернув Тельдрассил безсмертя нічним ельфам?",a="Ні. Тельдрассил дав нічним ельфам новий дім, але безсмертя, яке вони втратили, пожертвувавши Нордрассілом у Третій війні, не повернулося.",al={"чи нічні ельфи безсмертні","безсмертя тельдрассила","чи ельфи знову живуть вічно"}},{q="Навіщо набирати воду на Галявині Оракула?",a="Місячний колодязь під Деревом Оракула — перший і наймогутніший колодязь острова. Його вода дає Корітрасові змогу оцінити глибинне духовне й природне здоров'я Тельдрассила.",al={"навіщо вода оракула","призначення аметистової пляшки"}}},fp="18,298,16.444.0,19.546.1,43.172.0,26.202.0,45.164.0,62.186.0"}
P.entries["quest:935"] = {n="Корона Землі",s="«Корона Землі» — вінець обрядів очищення священних місячних колодязів Тельдрассила. Передання зібраних вод Архідруїдові Фандралу Стаґгелму в Дарнасусі підкреслює дедалі більшу тривогу через хибне, неблагословенне існування Світового Дерева.",h="«Корона Землі» — вінець обрядів очищення священних місячних колодязів Тельдрассила.",kw={"корона землі","фандрал стаґгелм","архідруїд","ценаріонський анклав","місячні колодязі","аспекти","дарнасус"},ang={["class:Druid"]="Несучи води місячних колодязів Архідруїдові Кола Кенарія, ви стаєте просто перед Фандралом Стаґгелмом і бачите гострий політичний і духовний розкол, що охопив друїдський провід за відсутності Малфуріона.",["faction:Alliance"]="Для ширшого Альянсу Дарнасус — величава столиця давніх таємниць, та зіпсуті хащі довкола неї доводять, що й нічні ельфи стикаються з внутрішніми загрозами на власній священній землі.",["race:NightElf"]="Цей обряд оголює тиху тривогу під вашою новою домівкою: Тельдрассил висадили з гордині, без благословення Драконячих Аспектів, і його дедалі тяжча хвороба нагадує, який крихкий новий початок вашого народу."},sec={{t="Хибний початок",b="Тельдрассил виростили після Третьої війни, щоб дати нічним ельфам нову домівку й повернути втрачене безсмертя. Та Великі Аспекти Алекстраза й Ноздорму відмовили в благословенні й не схвалили створення дерева. Без їхнього божественного захисту Тельдрассил став жертвою повзучої хвороби: з гілля виринають химерні створіння, а колись мирні племена фурболґів поринають у безумство."},{t="Доставка Архідруїдові",b="Корітрас Мунрейдж доручає юним шукачам пригод збирати воду з місячних колодязів по всьому острову, щоб стежити за недугами гілля й гамувати їх. Злив ці зразки в одну посудину, Корітрас посилає гінця вглиб Дарнасуса, до Ценаріонського Анклаву. Там сидить Архідруїд Фандрал Стаґгелм, творець Тельдрассила, який бачить у повзучому зіпсутті не знамення гордині, а прикрий тягар, який мусить нести він сам."}},faq={{q="Навіщо Фандралові Стаґгелму ця вода з місячного колодязя?",a="Фандрал Стаґгелм доручив зібрати зразки води з місячних колодязів по всьому Тельдрассилу, щоб вивчити скверну, яка просочується Світовим Деревом, і дати їй раду. Як очільник, що наполіг на вирощуванні дерева, він відповідає за те, щоб упоратися з дивними звірами й навіженими фурболгами, які непокоять крону.",al={"навіщо фандралу вода","чому фандралу потрібна посудина","для чого вода"}},{q="Чому Тельдрассил потерпає від скверни й навіжених звірів?",a="На відміну від давнього Світового Дерева Нордрассіл, Тельдрассил посадили без благословення Алекстрази Життєдайниці чи Ноздорму Позачасового. Без захисту цих первісних Аспектів драконів нове дерево росте з глибокою вадою, і дивні злоякісні сили вкорінюються в ґрунті та спотворюють звірів і фурболгів довкола.",al={"чому тельдрассил хворіє","осквернення тельдрассила","чому фурболги шаленіють"}},{q="Де знайти Архідруїда Фандрала Стаґгелма?",a="Архідруїд Фандрал Стаґгелм — у Ценаріонському Анклаві в Дарнасусі. Його можна знайти на верхівці центрального друїдського павільйону, звідки видно священні гаї анклаву.",al={"де фандрал","місце фандрала стаґгелма","як знайти фандрала"}},{q="Хто такий Корітрас Мунрейдж?",a="Корітрас Мунрейдж — друїд у Доланаарі, що керує очищенням місячних колодязів по всьому Тельдрассилу. Він збирає очищені фіали, які приносять мандрівники, зливає їх в одну посудину й посилає гінців віднести її Архідруїдові Стаґгелму в Дарнасус.",al={"хто дає корону землі","роль корітраса","корітрас мунрейдж"}},{q="Що буде після цього завдання?",a="Доставивши наповнену посудину Фандралові Стаґгелму, ви завершуєте головний ланцюжок «Корона Землі» на Тельдрассилі. Стаґгелм доволі сухо приймає воду й знову зосереджується на ширших загрозах, що нависли над батьківщиною нічних ельфів.",al={"продовження корони землі","що після корони землі 6","наступне завдання після корони землі"}},{q="Чому Фандрал Стаґгелм такий зневажливий, отримавши посудину?",a="Фандрал Стаґгелм відомий своєю гординею й нетерплячістю, а ще він обтяжений нелегким обов'язком очолювати Коло Кенарія, доки Малфуріона Стормрейджа немає. Затримки й повільних гінців він зустрічає зверхньо, адже відчуває, що тягар виживання Тельдрассила лежить на його плечах.",al={"чому фандрал грубий","характер фандрала","чи фандрал завжди буркотливий"}}},fp="18,263,16.435.0,26.439.1,51.316.0,58.332.0,45.167.0,26.282.0,41.251.1,64.307.0"}
P.entries["quest:93552"] = {n="Збір вітрокаменів",s="«Збір вітрокаменів» — доручення від Далії Збирачки в Тендальському Гаю на Острові Зефрас. Оскільки прадавні стихійні сили, що підтримують острів, поволі згасають, сирі вітрокамені стали незамінним магічним паливом. Шукачів пригод посилають по всьому гаю зібрати кришталеві друзи вітрокаменів, перш ніж їхня сила зникне.",h="«Збір вітрокаменів» — доручення від Далії Збирачки в Тендальському Гаю на Острові Зефрас.",kw={"збір вітрокаменів","вітрокамені","далія збирачка","тендальський гай","якірні пілони","острів зефрас"},ang={["class:Mage"]="Для практиків тайної магії зосереджена стихійна сила вітрокаменів — суворе нагадування про те, якими крихкими стають магічні світи, коли зникають їхні стихійні джерела.",["profession:Mining"]="Збирання сирих вітрокаменів — знайомство зі здобуванням цінних мінералів і кристалів у неприборканій глушині Острова Зефрас."},sec={{t="Острів, що згасає",b="Острів Зефрас значною мірою тримається на рештках вітряної магії, але його природний захист слабне. Століття тому місцеві вітряні елементалі, що ділили острів із тутешніми ельфами, зникли геть. Відтоді розлита в повітрі магія, що тримає землю й величні якірні пілони, повільно й невпинно згасає. Щоб пережити це виснаження, мешканцям Тендальського Гаю треба берегти кожен можливий запас сирої сили."},{t="Цінність вітрокаменів",b="Вітрокамені — яскраво-сині кришталеві утворення, що природно розсипані по всьому Тендальському Гаю. У їхній крихкій оболонці — щільна, зосереджена вітряна магія, лишена з минулих віків. Вони не розв'язують біди назавжди, але дають ельфам острова надійне й безцінне джерело чародійської поживи й користі, тож збирання сирих друз — важлива щоденна праця."}},faq={{q="Що таке вітрокамені?",a="Вітрокамені — блакитні кристалічні поклади довкола Тендальського Гаю, що містять зосереджену сиру енергію вітру. Ельфи Острова Зефрас добувають їх як незамінне джерело магічного палива.",al={"сирий вітрокамінь","скупчення вітрокаменів","блакитні кристали"}},{q="Хто така Далія Збирачка?",a="Далія — ельфійка-збирачка з Тендальського Гаю на Острові Зефрас. Вона організовує збір життєво важливої сировини, передусім вітрокаменів, щоб підтримати магічні запаси острова, які дедалі меншають.",al={"далія","далія зефрас","збирачка далія"}},{q="Чому магія на Острові Зефрас слабшає?",a="Кілька століть тому зникли елементалі вітру, що жили пліч-о-пліч із місцевими ельфами. Без їхньої присутності чари, якими великі якірні пілони наділили острів, поволі вичерпуються.",al={"магія зефраса слабшає","згасання магії зефрас","якірні пілони"}},{q="Куди поділися елементалі вітру?",a="Їхня доля досі загадка. Відомо лише, що вони зникли кілька століть тому, а острів відтоді поволі вичерпує рештки своїх стихійних запасів.",al={"зниклі стихійці","де вітряні стихійці","стихійці зникли"}},{q="Що таке якірні пілони?",a="Великі якірні пілони — прадавні споруди на Острові Зефрас, наділені могутньою магією, що підтримує землю. Відколи елементалі зникли, їхня життєдайна енергія поступово слабшає.",al={"великі якірні пілони","переказ про якірний пілон"}},{q="Де шукати сирі вітрокамені?",a="Сирі вітрокамені розкидані по всьому Тендальському Гаю на Острові Зефрас — це сяйливі блакитні кристалічні виступи.",al={"місце вітрокаменів","кристали гаю тендал"}}},fp="21,334,15.455.0,23.384.0,20.187.0,27.205.0,40.210.0,33.169.0,27.187.0,33.148.0"}
P.entries["quest:937"] = {n="Зачарований гай",s="На Галявині Оракула, на північному заході Тельдрассила, Вартова Аринія Клаудзбрейк силкується захистити прадавнє Дерево Оракула від агресивних гарпій Кривавого Пера. Після того як посланого до Дарнасуса гінця вбили, захисників кличуть ударити у відповідь по гніздах гарпій і принести на доказ їхні пояси.",h="На Галявині Оракула, на північному заході Тельдрассила, Вартова Аринія Клаудзбрейк силкується захистити...",kw={"зачарований гай","галявина оракула","дерево оракула","гарпії кривавого пера","аринія клаудзбрейк","тельдрассил"},ang={["class:Druid"]="Друїди глибоко шанують розумних древнів; очищення гаю від гарпій, що загрожують Дереву Оракула, береже природну рівновагу галявини.",["faction:Alliance"]="Допомога Вартовим в убезпеченні священних гаїв Тельдрассила зміцнює зв'язки з проводом нічних ельфів у сусідньому Дарнасусі.",["race:NightElf"]="Захищати прадавніх духів Світового Дерева й берегти Вартових від наруги гарпій — урочистий обов'язок кожного калдорея."},sec={{t="Галявина в облозі",b="Галявина Оракула — одна зі священних обителей Тельдрассила, осердям якої є велетенський прадавній древень, відомий як Дерево Оракула. Вартову Аринію Клаудзбрейк відрядили з загоном воїнів пильнувати цей шанований стовбур. На жаль, дикі гарпії Кривавого Пера вдерлися до западин, агресивно гніздяться по всій довколишній кроні й загрожують кожному, хто наблизиться."},{t="Перерваний зв'язок із Дарнасусом",b="Напруга сягнула краю, коли Дерево Оракула спробувало послати до столиці, Дарнасуса, гінця з терміновою доповіддю. Посланець так і не вибрався з гілля: гарпії влаштували засідку й розтерзали його, перш ніж доповідь покинула галявину. У відповідь Аринія доручила місцевим шукачам пригод прорідити зграю й добути пояси Кривавого Пера, щоб відтіснити наступ."},{t="Виклик від Дерева",b="Щойно безпосередню загрозу від сусідніх гнізд зменшено, відгукується саме прадавнє дерево. Дерево Оракула скидає уламок своєї зачарованої кори, шукаючи посланця, що передасть його послання до рук найвищого проводу калдорей."}},faq={{q="Чому гарпії нападають на Галявину Оракула?",a="Клан Кривавого Пера густо гніздиться по всій півночі Тельдрассила. На Галявині Оракула гарпії оточили Дерево Оракула, люто стережуть свої гнізда й нападають на кожного, хто намагається дістатися священного місця чи покинути його.",al={"гарпії на галявині оракула","чому гарпії бладфезер нападають","гарпії дерева оракула"}},{q="Хто така Вартова Аринія Клаудзбрейк?",a="Аринія Клаудзбрейк — офіцерка Вартових, що разом із невеликим передовим загоном перебуває на Галявині Оракула. Її головне завдання — захищати Дерево Оракула від гарпій довкола й відновити зв'язок із Дарнасусом.",al={"аринія клаудзбрейк","хто дає зачарований гай","переказ про клаудзбрейк"}},{q="Що сталося з гінцем, якого послали до Дарнасуса?",a="Гінця, що ніс донесення від Дерева Оракула до Дарнасуса, гарпії Кривавого Пера підстерегли й убили на стежках галявини, перш ніж він дістався безпечного місця.",al={"гонець дерева оракула","мертвий гонець дарнасус"}},{q="Що таке Дерево Оракула?",a="Дерево Оракула — величезний розумний прадавній, що вкоренився на Галявині Оракула. Він стежить за гілками Світового Дерева й передає свою мудрість і застороги проводу нічних ельфів.",al={"дерево оракула тельдрассил","хто таке дерево оракула"}},{q="Який доказ потрібен Вартовій Клаудзбрейк?",a="Вартова Клаудзбрейк вимагає шість Поясів Кривавого Пера, знятих зі вбитих гарпій, — відчутний доказ того, що їхні гнізда довкола галявини поріділи.",al={"пояс бладфезер завдання","скільки поясів","доказ завдання"}},{q="Що буде, коли гарпій проріджено?",a="Щойно найближчі околиці убезпечено, Дерево Оракула скидає шматок власної кори, і шукач пригод може віднести його давно відкладене послання до Дарнасуса.",al={"наступне завдання після зачарованого гаю","що робить дерево оракула далі"}}},fp="19,311,19.405.0,26.391.0,23.248.1,43.222.0,35.216.0,46.163.0,24.185.0,45.153.0,39.192.1"}
P.entries["quest:93746"] = {n="Рішуча відповідь",s="«Рішуча відповідь» — завдання Орди на Острові Зефрас від Аєсси Донсінґер. Напруга сягає межі: загадковий Високий Орден утручається в землі й справи місцевих Вітротворців. Аєсса наказує завдати випереджального удару Белатаанові Брайтвішу на дорозі до Святині Акіра, щоб силою провести чіткі межі.",h="«Рішуча відповідь» — завдання Орди на Острові Зефрас від Аєсси Донсінґер.",kw={"рішуча відповідь","аєсса донсінґер","белатаан брайтвіш","високий орден","вітротворці","святиня акіра"},ang={["class:Shaman"]="Сутичка з Живими Бурями на дорозі показує буремну, неприборкану стихійну магію повітря, що пронизує весь Острів Зефрас.",["faction:Horde"]="Присутність Орди на Острові Зефрас тримається на надійних позиціях і на тому, щоб не давати суперникам на кшталт Високого Ордену зазіхати на інтереси союзників."},sec={{t="Провести межу",b="Вітротворці Острова Зефрас не терплять непроханого нагляду, а надто від такої потайної й розважливої організації, як Високий Орден. Попередні застереження лишилися без уваги, тож Аєсса Донсінґер змушена загострити справу. Щоб захистити свої інтереси, вона вирішує перехопити Белатаана Брайтвіша на відлюдному відтинку дороги, що веде на північ, до Святині Акіра, — так сутичка відбудеться подалі від цікавих очей у місті."},{t="Бурі на дорозі",b="Вилазка Белатаана на північ, до прадавньої Святині Акіра, одразу викликає підозру, хоча його справжні наміри лишаються неясними. Коли на відлюдній дорозі його перестрівають, зустріч швидко стає ворожою, і в бій втягуються Живі Бурі. Здолавши цих буремних елементалів і впокоривши Белатаана, ви пошлете Високому Орденові недвозначне послання: на втручання в справи Вітротворців відповідатимуть силою."}},faq={{q="Хто така Аєсса Донсінґер?",a="Аєсса Донсінґер дає завдання й стоїть на боці Орди та Вітротворців на Острові Зефрас. Вона пильно оберігає їхні володіння й безжальна до чужинців, що втручаються в їхні справи.",al={"аєсса донсінґер","хто дає рішучу відповідь","аєсса"}},{q="Хто такий Белатаан Брайтвіш?",a="Белатаан Брайтвіш — агент, пов'язаний із Високим Орденом. Його помічають, коли він сам прямує до Святині Акіра, і він стає ціллю Аєсси Донсінґер, яка хоче залякати його організацію.",al={"белатаан брайтвіш","белатаан","хто такий белатаан"}},{q="Що таке Високий Орден?",a="Високий Орден — угруповання на Острові Зефрас, чия діяльність іде всупереч місцевим Вітротворцям. Попри недвозначні попередження, його члени й далі пхають носа в справи, які їх не стосуються.",al={"високий орден","переказ про високий орден","що таке високий орден"}},{q="Де Святиня Акіра?",a="Святиня Акіра — на північ від містечка на Острові Зефрас. Белатаана перехоплюють на відлюдній дорозі, що веде до цієї місцини.",al={"святиня акіра","де святиня акіра","святиня акіра зефрас"}},{q="Чому Аєсса хоче, щоб Белатаана побили, а не вбили?",a="Аєсса відверто прагне передати послання, а не розв'язати повномасштабну війну. Побивши Белатаана й відпустивши його до старших, вона сподівається вселити страх і повагу до кордонів Вітротворців.",al={"вбити белатаана","чому пощадити белатаана","чому лише синці"}},{q="Що за Живі Бурі трапляються під час цього завдання?",a="Живі Бурі — стихійні сутності, що з'являються під час сутички з Белатааном на дорозі, віддзеркалюючи бурхливу стихійну енергію, якою живе Острів Зефрас.",al={"живі бурі","що таке живі бурі"}}},fp="15,343,16.443.0,18.419.1,25.193.0,28.200.0,23.198.0,36.140.0,57.210.0,56.172.0"}
P.entries["quest:938"] = {n="Імла",s="«Імла» — завдання-супровід у тінистому гіллі Тельдрассила. Знайшовши глибоко в лісі покинуту поранену сіру шаблезубу кішку, мандрівники мають безпечно провести її назад до Вартової Аринії Клаудзбрейк, що чекає біля місячного колодязя неподалік.",h="«Імла» — завдання-супровід у тінистому гіллі Тельдрассила.",kw={"імла","шаблезуба кішка","супровід","аринія клаудзбрейк","гарпії","тельдрассил"},ang={["class:Hunter"]="Кожен володар звірів упізнає люту відданість і розумний погляд в очах Імли, тож безпечно повернути її партнерці — справа професійної честі.",["faction:Alliance"]="Допомога Вартовим у Тельдрассилі зміцнює життєво важливу прихильність між молодим Альянсом і калдореями — захисниками Світового Дерева.",["race:NightElf"]="Зв'язок між Вартовою і шаблезубом — наріжний камінь військової справи й лісових переказів нічних ельфів; порятунок Імли підтримує це давнє священне товариство."},sec={{t="Поранена супутниця",b="У дикому підліску Тельдрассила причаїлася Імла — примітна сіра шаблезуба кішка з глибокими рваними ранами на спині й череві. Замість поводитися як дикий звір, Імла виявляє дивовижний спокій, а в її синіх очах світиться жвавий розум: вона одразу шукає в доброзичливих мандрівників проводу й захисту."},{t="Ціна засідки",b="Імла — улюблена супутниця Вартової Аринії Клаудзбрейк. Патрулюючи велике гілля біля Дерева Оракула, Аринія потрапила в засідку мерзенних відьом-гарпій, які напали на них обох і розлучили. Гадаючи, що її вірна улюблениця загинула кривавою смертю, Аринія в горі відступила до тихого місцевого місячного колодязя, де всупереч усьому відчайдушно сподівалася, що Імла вижила."}},faq={{q="Хто така Імла?",a="Імла — вірна сіра шаблезуба кішка, супутниця Вартової Аринії Клаудзбрейк. Її знаходять пораненою в лісах Тельдрассила: під час жорстокої засідки вона відбилася від своєї господині.",al={"імла кішка","що таке імла","хто така шаблезуба"}},{q="Хто поранив Імлу?",a="На Імлу та її господиню напали місцеві відьми, що чаїлися в лісах Тельдрассила. Нападниці розлучили їх і завдали кішці глибоких ран на спині й животі.",al={"хто поранив імлу","чому імла кровить","відьми влаштували засідку на імлу"}},{q="Куди треба провести Імлу?",a="Імлу треба безпечно довести до Вартової Аринії Клаудзбрейк, яка перебуває біля місячного колодязя неподалік Дерева Оракула.",al={"куди вести імлу","здати імлу","призначення імли"}},{q="Хто така Вартова Аринія Клаудзбрейк?",a="Arynia Cloudsbreak is a night elf Sentinel and Mist's companion. She is stationed at the moon well near the Oracle Tree.",al={"аринія клаудзбрейк","клаудзбрейк","власниця імли"}},{q="Чому Вартових нічних ельфів пов'язують із шаблезубами?",a="Вартові нічних ельфів тисячоліттями билися пліч-о-пліч із великими кішками Калімдору: ті були їм лютими напарниками в сутичках, розвідниками в тінистих гілках і вірними супутниками на все життя.",al={"нічні ельфи й коти","вартові й шаблезуби","чому шаблезуби"}},{q="Де Дерево Оракула відносно місця порятунку?",a="The Oracle Tree sits in northwestern Teldrassil, with a nearby moon well providing holy waters where Sentinel Arynia Cloudsbreak tends to her duties.",al={"місце дерева оракула","місячний колодязь імли"}}},fp="4,224,19.349.0,19.377.1,12.194.0,17.199.0,30.123.0,35.120.0,50.196.0,52.149.0"}
P.entries["quest:94"] = {n="Пильне око",s="«Пильне око» — завдання Альянсу від чарівника Теокрітуса з Вежі Азори в Лісі Елвінн. Налагодивши базовий ворожильний зв'язок проти свого суперника Морґанта, Теокрітус посилає шукачів пригод на схід, у Гори Редріджу, щоб помістити зачарований фокус на стародавню статую лева, що дивиться на Вежу Ілґалара.",h="«Пильне око» — завдання Альянсу від чарівника Теокрітуса з Вежі Азори в Лісі Елвінн.",kw={"пильне око","теокрітус","морґант","гліф азори","вежа ілґалара","статуя лева","ворожіння"},ang={["class:Mage"]="Для адептів чародійства ця місія показує далеке провидіння й ворожильні ретранслятори та протиставляє впорядковані академічні методи Теокрітуса з Елвінну беззаконному чаклунству Морґанта.",["faction:Alliance"]="Знешкодити людей-чаклунів-відступників на кшталт Морґанта конче потрібно, щоб убезпечити кордон між Лісом Елвінн і обложеними поселеннями Гір Редріджу."},sec={{t="Суперництво через кордон",b="Зі своєї вежі на сході Лісу Елвінн маг Теокрітус пильно стежить за темним чаклунством, що визріває в сусідніх пагорбах. Його головний ворог — Морґант, лютий чаклун грізної сили, який захопив Вежу Ілґалара серед скель Гір Редріджу. Прагнучи розкрити зловісні задуми Морґанта, перш ніж вони перехлюпнуть через кордон, Теокрітус створив Око Азори, щоб стежити за чарівником-відступником здалеку."},{t="Варта лева",b="Зорове ворожіння дає певні відомості, та їх замало, щоб прозирнути глибші задуми Морґанта. Теокрітус довіряє мандрівникам Гліф Азори й наказує дістатися до підніжжя Вежі Ілґалара. Там десятиліттями несе самотню варту Стара Статуя Лева. Вкладений у стерту заглибину біля основи статуї гліф пробуджує чародійний канал, що з'єднує камінь з Азорою й дає Теокрітусу змогу зазирнути просто в розум суперника."}},faq={{q="Хто такий Теокрітус?",a="Теокрітус — могутній чарівник Альянсу, що мешкає на верхівці Вежі Азори на сході Лісу Елвінн. Свої тайні студії він присвячує захисту краю від магічних загроз, і передусім — від чаклуна-ренегата Морґанта.",al={"теокрітус","маг вежі азори","хто дає пильне око"}},{q="Хто такий Морґант?",a="Морґант — лихий чарівник-ренегат із людей, що влаштував собі твердиню у Вежі Ілґалара в Горах Редріджу. Він запеклий суперник Теокрітуса, який побоюється темних задумів, що їх Морґант плете проти довколишніх земель.",al={"морґант","хто такий морґант","маг-суперник"}},{q="Де Стара Статуя Лева?",a="Стара Статуя Лева, вивітрена часом, стоїть на хребтах над Вежею Ілґалара, серед пагорбів на північному сході Гір Редріджу. Біля її підніжжя є неглибока западина, призначена для магічних фокусів на кшталт Гліфа Азори.",al={"місце старої статуї лева","де статуя","куди класти гліф азори"}},{q="Що робить Гліф Азори?",a="Гліф Азори — зачарований камінь, створений Теокрітусом. Вставлений у статую лева біля Вежі Ілґалара, він стає тайним підслуховувальним постом і ретранслятором, що зондує розум: крізь камінь Теокрітус може говорити й вивчати думки Морґанта.",al={"гліф азори","що робить гліф"}},{q="Що таке Вежа Ілґалара?",a="Вежа Ілґалара — висока відлюдна кам'яна вежа серед скель на північному сході Гір Редріджу. Цю вежу магів нині захопили й обороняють Морґант і його прислужники.",al={"вежа ілґалара","ілґалар"}},{q="Що далі, коли гліф встановлено?",a="Щойно Гліф Азори закріплено на статуї, Теокрітус промовляє крізь камінь і одразу дає наступне завдання, «Зазирнути глибше», — він починає розплутувати Морґантові підступи.",al={"наступне завдання","що після пильного ока"}}},fp="14,324,27.449.0,16.474.0,18.237.0,16.241.0,37.230.0,32.265.0,29.193.0,35.193.0"}
P.entries["quest:940"] = {n="Тельдрассил",s="Після очищення околиць Дерева Оракула від здичавілих гарпій Вартова Аринія Клаудзбрейк довіряє вам доставити звіт до Дарнасуса. Списана письменами кора адресована Архідруїдові Фандралу Стаґгелму й несе звістки про стан гілля та зіпсуття, що й далі мучить Світове Дерево.",h="Після очищення околиць Дерева Оракула від здичавілих гарпій Вартова Аринія Клаудзбрейк довіряє вам доставити...",kw={"тельдрассил","дерево оракула","аринія клаудзбрейк","фандрал стаґгелм","звіт","дарнасус"},ang={["class:Druid"]="Нести слово прадавнього Дерева Оракула просто до проводиря Кола Кенарія — значить побачити безнастанну боротьбу за очищення природної рівноваги Тельдрассила.",["faction:Alliance"]="Для звитяжців Альянсу, що завершують свої перші обов'язки на острові, ця місія — офіційне знайомство зі столицею нічних ельфів та її суворим проводом.",["race:NightElf"]="Доставивши цей звіт, ви стаєте віч-на-віч з Архідруїдом Стаґгелмом і бачите його особисту одержимість — повернути калдореям безсмертя через хворе гілля Тельдрассила."},sec={{t="Гонець до кам'яного міста",b="Глибоко в гіллі Тельдрассила Дерево Оракула пильнує ліс. Очистивши Зачарований гай від гнізд гарпій, Вартова Аринія Клаудзбрейк вирішує, що нарешті безпечно послати звістку проводові калдорей. Довіривши вам шматок списаної кори, вона посилає вас через хащі до Дарнасуса — великого «лісу з каменю», — щоб передати звіт Дерева Оракула просто в руки Архідруїда Фандрала Стаґгелма."},{t="Амбіції й розчарування Стаґгелма",b="Одержавши звіт, Фандрал Стаґгелм приймає його зі змішаними почуттями. Він вдячний за звістку, що гарпій відтіснили, та звіт підкреслює глибшу правду: щойно одну загрозу на Тельдрассилі зменшено, на її місці гноїться інша. Для Стаґгелма, який просував висадження нового Світового Дерева, щоб повернути нічним ельфам утрачене безсмертя, невідступні недуги гілля — гірке нагадування, що його великий труд ще далекий від завершення."}},faq={{q="Навіщо завдання «Тельдрассил»?",a="Це завдання — сюжетний місток між вашими пригодами в нетрях довкола Дерева Оракула й столицею. Вартова Аринія Клаудзбрейк доручає вам віднести Гравіровану Кору з донесенням Дерева Оракула Архідруїдові Фандралові Стаґгелму в Дарнасус.",al={"мета завдання тельдрассил","що робить це завдання","доставка тельдрассила"}},{q="Хто така Вартова Аринія Клаудзбрейк?",a="Аринія Клаудзбрейк — Вартова нічних ельфів, що перебуває біля Дерева Оракула в нетрях Тельдрассила. Вона стежить за загрозами в окрузі, як-от за місцевими гарпіями Кривавого Пера, і разом із Дарнасусом організовує оборону лісу.",al={"аринія клаудзбрейк","хто починає завдання тельдрассил"}},{q="Чому Аринія називає Дарнасус «кам'яним лісом»?",a="Нічні ельфи живуть у кроні Світового Дерева, але місто Дарнасус збудоване з величних мармурових і кам'яних храмів, мостів і павільйонів. Порівняно з дикими нетрями довкола Дерева Оракула столиця — справжній рукотворний кам'яний ліс.",al={"значення кам'яного лісу","чому кам'яний ліс"}},{q="Чому Фандрала Стаґгелма так непокоїть донесення Дерева Оракула?",a="Стаґгелм очолив вирощування Тельдрассила, сподіваючись повернути калдореям безсмертя після того, як у Третій війні постраждав Нордрассіл. Вісті від Дерева Оракула підтверджують, що скверна на Тельдрассилі поширюється, а звірі шаленіють, і це ставить під загрозу його задуми.",al={"реакція фандрала стаґгелма","чому стаґгелм стривожений"}},{q="Яке завдання веде до цього і що йде після нього?",a="Це завдання йде одразу після «Зачарованого гаю», де ви розбираєтеся з гарпіями, що загрожують Дереву Оракула. Коли ви доставите донесення, Архідруїд Стаґгелм відправить вас на Темне Узбережжя з наступним завданням — «Гай Прадавніх».",al={"ланцюжок завдань тельдрассила","яке завдання далі"}},{q="Де знайти Архідруїда Фандрала Стаґгелма?",a="Архідруїд Фандрал Стаґгелм — у Дарнасусі, на верхівці Ценаріонського Анклаву: звідти він наглядає за друїдами Кола Кенарія й веде врядування калдореїв.",al={"де фандрал","місце фандрала стаґгелма"}}},fp="10,307,29.453.0,35.481.0,46.270.0,35.212.0,51.265.0,68.291.0,48.246.0,47.191.0"}
P.entries["quest:941"] = {n="Посадити серце",s="«Посадити серце» — завдання для травника Деналана на березі Озера Ал'Амет у Тельдрассилі. Зчистивши задушливий мох із дивного дерев'яного серця, взятого із зіпсутого деревляника, Деналан перевіряє, чи зможе його особливо збагачений ґрунт очистити й зцілити скверну, що досі в ньому жевріє.",h="«Посадити серце» — завдання для травника Деналана на березі Озера Ал'Амет у Тельдрассилі.",kw={"посадити серце","деналан","деревляник","блекмосс смердючий","ґрунт","озеро ал'амет","тельдрассил"},ang={["class:Druid"]="Для друїда бачити, як осердя зіпсутого деревляника очищається в багатій землі, — підбадьорливий знак: неприродну скверну, що вразила гілля Світового Дерева, ще можна повернути назад природною турботою.",["profession:Herbalism"]="Майстерність Деналана в поживному ґрунті й оживленні рослин показує життєво важливий зв'язок між вивченням землі й зціленням пошкодженої флори.",["race:NightElf"]="Відновлення живої деревини й пробудження життя в полеглих лісових духах відображає відданість калдорей опіці над природою навіть попри тривожні недуги Тельдрассила."},sec={{t="Другий шанс на життя",b="Оглядаючи дивний дерев'яний орган, здобутий із зіпсутого деревляника на ім'я Блекмосс Смердючий, Деналан спромігся зішкребти мерзенний мох, що душив його поверхню. Та попри всі зусилля в деревині й далі пульсує глибша, неприродна скверна. Замість спалити чи викинути серце, Деналан покладається на свою довічну майстерність ботаніка й доглядача ґрунту. Він велить мандрівникам закопати серце просто у свій особистий ящик для розсади, довіряючи багатим поживним речовинам, які він змішав, повернути до здоров'я ту природну силу, що ще лишилася."},{t="Диво збагаченої землі",b="Коли почорніле дерев'яне серце кладуть у ящик Деналана, стається несподіване. Щойно торкнувшись родючого ґрунту, серце заривається в землю, немов кероване первісним інстинктом. За мить воно знову виринає на поверхню — очищене від мерзенного зіпсуття, з лагідним, дружнім теплом усередині. Очистивши зерня полеглого зараженого створіння, Деналан доводить: навіть коли дикі мешканці Тельдрассила стають жертвами неприродної пошесті, дбайливий догляд і священна земля ще здатні повернути злагоду."}},faq={{q="Звідки це зіпсоване серце?",a="Серце належало Блекмоссові Смердючому — зіпсованому скверною деревлянику, що чаївся на берегах Озера Ал'Амет. Його здобули оповитим сплутаним мерзенним мохом, і лише потім Деналан зішкріб його начисто.",al={"походження серця","звідки серце","серце блекмоса"}},{q="Хто такий Деналан?",a="Деналан — ботанік і травник із нічних ельфів, що доглядає відлюдний табір на східному краю Озера Ал'Амет. Він днями вивчає рослинність Тельдрассила, досліджує дивну скверну, що поширюється гілками, і змішує живильні ґрунти.",al={"хто такий деналан","переказ про деналана"}},{q="Чому серце садять у діжку, а не знищують?",a="Деналан вірить, що природу треба розуміти й зцілювати, а не просто нищити все зіпсоване. Він сподівається, що приготований ним живильний ґрунт очистить скверну й поверне серцю первісну, чисту життєву силу.",al={"чому саджати серце","чому лікувати серце"}},{q="Що станеться, коли закопати серце?",a="Серце відразу зарилося в ґрунт, а за кілька секунд виповзає назад на поверхню, цілком очищене від мерзенної скверни, і тихо пульсує — тепер це живий супутник.",al={"що буде в діжці","серце в землі"}},{q="Чи зцілює це скверну деревляників?",a="Це зцілює лише одне врятоване серце. Воно доводить, що окремих рослинних духів можна очистити дбайливістю й родючим ґрунтом, але загальна скверна, яка поширюється Тельдрассилом, лишається грізною небезпекою.",al={"чи деревляників вилікувано","лікування деревляників"}},{q="Чим особливий ґрунт у Деналановій діжці?",a="Деналан довго експериментував біля Озера Ал'Амет із компостом і сумішами живильного ґрунту, створюючи землю, достатньо сильну, щоб оживити кволі рослини й вигнати підступне гниття.",al={"ґрунт деналана","ґрунт у діжці"}}},fp="18,318,23.539.0,29.534.1,40.198.0,15.256.0,56.209.0,37.184.1,49.213.0,45.192.0"}
P.entries["quest:942"] = {n="Неуважний дослідник",s="Це завдання переносить археологічну загадку з Темного Узбережжя через Велике Море до Багнокраю. Головний археолог Ґрейвіскер довіряє вам дивну скам'янілість із Калімдору й посилає до археолога Флеґонґата в Гавані Менетіл, щоб розкрити її таємниці.",h="Це завдання переносить археологічну загадку з Темного Узбережжя через Велике Море до Багнокраю.",kw={"неуважний дослідник","головний археолог ґрейвіскер","археолог флеґонґат","гавань менетіл","скам'янілість","ліга дослідників"},ang={["faction:Alliance"]="Це завдання вимагає скористатися морськими шляхами Альянсу — переплисти з Калімдору до Гавані Менетіл, щоб підтримати зв'язок між осередками Ліги.",["race:Dwarf"]="Для дворфів-шукачів пригод це доручення показує, як далеко сягає Ліга Дослідників, поєднуючи польову роботу у віддаленому Калімдорі з ученими-побратимами в Каз Модані."},sec={{t="Цікава знахідка",b="Вивчаючи дивну скам'янілість, знайдену на Темному Узбережжі, головний археолог Ґрейвіскер помічає разючу схожість із реліквією, яку показували на конференції Ліги Дослідників в Айронфорджі. Ту першу знахідку представив археолог Флеґонґат, переконаний, що такі скам'янілості приховують сили, що чекають на пробудження. Ґрейвіскер вважає, що лише Флеґонґат здатен збагнути, чим така незвичайна ця калімдорська знахідка."},{t="Подорож через море",b="Нести таємничу реліквію — означає вирушити в далеку дорогу з Калімдору до Східних Королівств. Флеґонґата востаннє бачили в Таверні «Глибока Вода» в Гавані Менетіл, де він чекав на збройний супровід до Місця Розкопок Велґара. Коли скам'янілість опиниться в його руках, місцеве обстеження на Темному Узбережжі стане частиною археологічного розслідування, що охоплює цілі континенти."}},faq={{q="Чому Ґрейвіскер посилає мене аж до Гавані Менетіл?",a="Головний Археолог Ґрейвіскер пригадує, що Археолог Флеґонґат показував такий самий артефакт на щорічних зборах Ліги Дослідників в Айронфорджі. Вважаючи, що Флеґонґат знається на тому, як розкрити його приховану силу, Ґрейвіскер посилає вас туди, де Флеґонґата бачили востаннє, — у Гавань Менетіл.",al={"чому йти до менетіла","доручення ґрейвіскера про скам'янілість","чому мокрі землі"}},{q="Хто такий Археолог Флеґонґат?",a="Археолог Флеґонґат — дослідник Ліги Дослідників у Багнокраї. Пережидаючи затримки в Таверні «Глибока Вода» в Гавані Менетіл, він готується до експедиції на небезпечне Місце Розкопок Велґара.",al={"флеґонґат","переказ про археолога флеґонґата"}},{q="Що це за загадкова скам'янілість?",a="Це давній цікавий зразок, привезений з Темного Узбережжя. Флеґонґат раніше стверджував, що схожий зразок, який він вивчав, таїть приховану магічну чи історичну силу, яку ще належить розкрити.",al={"що за скам'янілість","походження загадкової скам'янілості","скам'янілість ремтревела"}},{q="Що каже Флеґонґат, коли ви віддаєте скам'янілість?",a="Флеґонґат вражений: артефакт, ідентичний його власному зразку, походить із далекого континенту Калімдор. Отже, давня історія пов'язує ці два материки.",al={"реакція флеґонґата","віддати скам'янілість"}},{q="Куди Флеґонґат хоче вирушити далі?",a="Флеґонґат чекає в Гавані Менетіл на супровід, щоб вирушити вглиб суходолу до Місця Розкопок Велґара — великих розкопок у Багнокраї.",al={"куди йде флеґонґат","розкопки флеґонґата"}},{q="Яке місце це завдання посідає в сюжеті «Неуважного дослідника»?",a="Це перехідний етап ланцюжка. Після того як ви супроводили й урятували Шукача Ремтревела на Темному Узбережжі й разом із Ґрейвіскером оглянули викопаний ним артефакт, розслідування переходить з півночі Калімдору просто до знавців Ліги у Східних Королівствах.",al={"неуважний шукач частина 4","контекст ланцюжка"}}},fp="28,253,19.451.0,23.391.0,60.307.0,31.223.0,30.190.0,52.202.0,37.159.0,68.255.0"}
P.entries["quest:943"] = {n="Неуважний дослідник",s="Це завдання — останній розділ пошуків, які почалися з розкопок шукача Ремтревела на Темному Узбережжі. Археолог Флеґонґат у Гавані Менетіл хоче поєднати знахідки Ремтревела зі своєю скам'янілістю та загубленим Каменем Релу, щоб розкрити приховані сили давніх реліквій титанів.",h="Це завдання — останній розділ пошуків, які почалися з розкопок шукача Ремтревела на Темному Узбережжі.",kw={"неуважний дослідник","археолог флеґонґат","камінь релу","шукач велґар","раптори","багнокрай"},ang={["faction:Alliance"]="Кур'єри й шукачі пригод Альянсу часто долають морську відстань між землями нічних ельфів на Темному Узбережжі й дворфськими поселеннями довкола Гавані Менетіл.",["race:Dwarf"]="Цей ланцюжок завдань утілює головну місію Ліги Дослідників — поєднувати віддалені розкопки на різних континентах, щоб скласти докупи спадщину дворфів і таємниці Титанів."},sec={{t="Археологія через континенти",b="Те, що почалося як супровід неуважного шукача Ремтревела на півночі Темного Узбережжя, веде через Велике Море на болота Багнокраю. Першу скам'янілість Флеґонґата зберігає шукач Велґар на своїх розкопках у Багнокраї. Переглянувши зібрані знахідки, археолог Флеґонґат розуміє, що для того, щоб розкрити таємничі сили скам'янілостей, потрібен ключовий артефакт — Камінь Релу."},{t="Загублений серед боліт",b="Перш ніж Флеґонґат устиг зустрітися з Велґаром, на його караван на дорозі напала зграя плямистих рапторів і проковтнула Камінь Релу. Щоб розгадати загадку, Флеґонґатові потрібен шукач пригод, який вполює хижих звірів, добуде проковтнутий камінь і забере першу скам'янілість із табору Велґара. Зібравши обидві скам'янілості й ключ, дворфські дослідники сподіваються з'ясувати справжнє походження й силу реліквій."}},faq={{q="Чому завдання з Темного Узбережжя закінчується в Багнокраї?",a="Ліга Дослідників веде роботи і в Калімдорі, і в Східних Королівствах. Головний Археолог Ґрейвіскер відправив скам'янілість Ремтревела з Темного Узбережжя через море Археологові Флеґонґату в Багнокрай — так спільне дослідження поєднало дві ділянки розкопок.",al={"чому мокрі землі темне узбережжя","зв'язок з гаванню менетіл","чому відправляють у мокрі землі"}},{q="Що таке Камінь Релу?",a="Камінь Релу — давній артефакт, який здобув Археолог Флеґонґат. Він вважає, що камінь діє як ключ чи каталізатор, здатний розкрити приховані магічні таємниці скам'янілостей, викопаних на Темному Узбережжі й у Багнокраї.",al={"камінь релу","що таке камінь релу","артефакт релу"}},{q="Хто такий Археолог Флеґонґат?",a="Археолог Флеґонґат — агент дворфійської Ліги Дослідників, що працює в Гавані Менетіл. Він вивчає давні артефакти з навколишніх розкопок і тісно співпрацює з Шукачами Ремтревелом і Велґаром, розшифровуючи рештки спадщини титанів.",al={"флеґонґат","хто такий флеґонґат"}},{q="У кого оригінальна скам'янілість?",a="Оригінальна скам'янілість Флеґонґата — у Шукача Велґара на його розкопках у Багнокраї. А скам'янілість Ремтревела з Темного Узбережжя ви вже доставили Флеґонґатові.",al={"де скам'янілість","у кого скам'янілість ремтревела","скам'янілість велґара"}},{q="Чому Камінь Релу опинився в рапторів?",a="Коли Флеґонґат ішов дорогою Багнокраю на пораду до Шукача Велґара, на нього напали плямисті раптори. У метушні нападу один із хижаків проковтнув камінь цілком.",al={"раптор проковтнув реліквію","чому камінь у рапторів"}},{q="Чого дворфи чекають від скам'янілостей?",a="Ліга Дослідників вважає, що давні скам'янілості з часів зорі Азероту таять приховану енергію титанів і забуту історію, яку можна пробудити й розтлумачити за допомогою особливих каменів-артефактів, як-от Камінь Релу.",al={"сила скам'янілості","що робить скам'янілість"}}},fp="28,284,29.440.0,19.436.1,48.280.0,26.238.0,31.248.0,28.173.0,38.195.0,45.213.0"}
P.entries["quest:944"] = {n="Глефа Володаря",s="Це завдання посилає шукачів пригод Альянсу на південь Темного Узбережжя розвідати моторошну Глефу Володаря на прохання Древа Знань Ону. Мета — з'ясувати, чи проник зловісний культ Молота Присмерку до решток полеглого давнього жаху.",h="Це завдання посилає шукачів пригод Альянсу на південь Темного Узбережжя розвідати моторошну Глефу Володаря на...",kw={"глефа володаря","ону","молот присмерку","флакон віщування","древо знань","темне узбережжя"},ang={["class:Druid"]="Друїди відгукуються на поклик Ону, щоб зрозуміти, як давня приспана скверна, похована глибоко в землі, тривожить навколишній край і його звірів.",["faction:Alliance"]="Сили Альянсу на Темному Узбережжі мусять не дати Молотові Присмерку пробудити давні жахіття, що можуть знищити поселення півночі Калімдору, яким і так непросто.",["race:NightElf"]="Для нічних ельфів Глефа Володаря — суворе нагадування про первісні жахи, старші за їхню цивілізацію, а божевільні культисти на священній землі Темного Узбережжя — нестерпна наруга."},sec={{t="Тривожна присутність",b="Досліджуючи порчу, що не відступає, і звірів, вигнаних зі своїх угідь, на Темному Узбережжі, Древо Знань Ону помічає тривожні ознаки. Наги на узбережжі — вже чимала біда, але присутність культу Молота Присмерку куди зловісніша. Ця фанатична секта поклоняється не звичайним темним силам — вона шанує давніх, первісних володарів світу, повалених у прадавні часи."},{t="Полеглий володар",b="На півдні лежить Глефа Володаря — похмурі розкопки довкола колосальної істоти, пронизаної величезною кам'яною зброєю. Ону дає Флакон Віщування й доручає розвідникам спуститися в яму, щоб перевірити, чи зібралися там культисти. Як застерігає Ону, хоча пронизане громаддя мертве вже цілу вічність, у його кістках досі жевріють крихти давньої згубної сили — здобич, перед якою Молот Присмерку не встоїть."}},faq={{q="Хто дає мені це доручення?",a="Завдання дає Ону — шановане Древо Знань, що стоїть біля дороги на півдні Темного Узбережжя, поблизу Гаю Прадавніх.",al={"хто дає завдання","хто видає глефу володаря","початковий неігровий персонаж"}},{q="Що таке Глефа Володаря?",a="Глефа Володаря — прадавнє місце на півдні Темного Узбережжя, де багато епох тому впав страхітливий прадавній володар, якому череп пронизала титанічна кам'яна глефа. Його величезний скам'янілий кістяк досі вгруз у землю.",al={"що таке глефа володаря","переказ про глефу володаря","череп велетня на темному узбережжі"}},{q="Чому культ Молота Присмерку цікавиться цим місцем?",a="Молот Присмерку поклоняється давнім темним силам прадавнього Азероту. Титанічна істота, пробита глефою, давно мертва, але в її рештках досі дрімають сліди й уламки первісної сили, і культисти відчайдушно прагнуть її опанувати.",al={"культ молота присмерку темне узбережжя","чому сектанти тут","молот присмерку глефа володаря"}},{q="Як доповісти Ону?",a="Вам не треба йти аж до самого Ону. Оглянувши котлован розкопок біля Глефи Володаря, скористайтеся Флаконом Віщування з торби, щоб викликати на землі Чашу Віщування, — через неї ви за допомогою магії говоритимете безпосередньо з Ону.",al={"куди доповісти","як користуватися флаконом віщування","чаша віщування"}},{q="Що йде після цієї розвідки?",a="Коли ви через Чашу Віщування підтвердите присутність культистів, Ону одразу посилає вас до їхнього табору в завданні «Сутінковий табір», щоб дізнатися більше про їхні дії.",al={"наступне завдання","продовження глефи володаря"}}},fp="19,263,21.390.0,15.433.0,29.133.0,28.221.0,57.264.0,28.258.0,32.201.0"}
P.entries["quest:94414"] = {n="Якорі Зефраса",s="«Якорі Зефраса» — вступне завдання від Галаана Гок-Ая на Острові Зефрас. Галаан пропонує мандрівникам позичити його далекий зір, щоб роздивитися прадавні якірні пілони, які тримають і бережуть летючий острів. Хоча здалеку високі моноліти здаються неушкодженими, Галаан попереджає, що стабілізувальна магія духів вітру почала хитатися.",h="«Якорі Зефраса» — вступне завдання від Галаана Гок-Ая на Острові Зефрас.",kw={"якорі зефраса","галаан гок-ай","якірні пілони","лінії сили","духи вітру","острів зефрас"},ang={["class:Shaman"]="Якірні пілони прямо залежать від благословення духів вітру, тож будь-яка нестійкість їхньої магії — нагальна справа стихій для шаманів, що прагнуть берегти рівновагу."},sec={{t="Прив'язь острова",b="The anchor pylons of Zephras are ancient, towering monoliths gifted by the spirits of the winds. Deeply woven into the isle's mystical foundation, they serve to bind, steady, and sustain the landmass amidst the churning skies. To look upon one is to witness the fragile balance keeping Zephras aloft, relying continuously on the benevolence of the wind spirits."},{t="Тривожна зміна",b="Хоча неозброєному оку якірні пілони здаються гордими й неушкодженими, вони стали непевними. Галаан Гок-Ай помічає, що магічна гармонія, яка їх підтримує, останнім часом стала нестійкою й мінливою. Без явних ознак фізичних пошкоджень цей непомітний занепад тихо тривожить тих, хто пильнує гаї, і натякає на глибші розлади, що загрожують острову."},{t="Дар Галаана",b="Не маючи ні вродженого небозору, що зазирає між світами, ні чародійської вправності, щоб черпати силу з глибинних ліній сили Зефраса, Галаан має простіший, але гостріший природний дар: ясний, незамутнений зір на величезні відстані. Ділячись цим поглядом, він дає іншим роздивитися далекі пілони в найдрібніших подробицях і заохочує новачків цінувати теперішнє, водночас пильнуючи мінливу долю рідного краю."}},faq={{q="Що таке якірні пілони на Зефрасі?",a="Якірні пілони — прадавні містичні споруди, дар духів вітрів. Вони скріплюють, утримують і магічно підтримують острів Зефрас, зберігаючи його стійким над світом унизу.",al={"що таке якорі","якірний пілон зефрас","що таке якірний пілон"}},{q="Що не так із якірними пілонами?",a="На пілонах не видно ні явних ушкоджень, ні зовнішнього руйнування, але їхня стабілізувальна магія останнім часом стала нестійкою й мінливою, і це викликає тривогу: що ж непомітно розхитує їхній зв'язок?",al={"чому якорі слабшають","проблема пілонів","що сталося з якорями"}},{q="Хто такий Галаан Гок-Ай?",a="Галаан Гок-Ай — спостерігач, що мешкає в гаях Острова Зефрас. Обдарований гострим далекосяжним природним зором, він стежить за здоров'ям землі й міркує про містичний добробут острова.",al={"переказ про галаана","хто такий галаан"}},{q="Який дар має Галаан?",a="Дар Галаана — надзвичайно гострий далекий зір. На відміну від містиків, що «Небозором» зазирають між світами чи спрямовують енергію ліній сили, Галаанова сила природна й буденна: вона дає йому змогу бачити далекі орієнтири з кришталевою чіткістю.",al={"дар галаана","як галаан бачить далеко"}},{q="Що таке «Небозір»?",a="«Небозір» — містичне чуття, яке мають деякі посвячені на Зефрасі: воно дає змогу проникнути крізь завісу й зазирнути просто між світами, значно перевершуючи звичайний зір.",al={"що таке небозір","значення небозору"}},{q="Звідки береться магія, що живить пілони?",a="The anchor pylons were granted to Zephras by the spirits of the winds. Halaan says the pylons bind and sustain the island, but does not explain the source of their continuing power.",al={"хто зробив пілони","походження якірних пілонів"}}},fp="22,370,19.361.0,18.378.0,13.412.0,38.198.0,37.200.0,23.200.0,22.249.0,17.190.0,51.181.0"}
P.entries["quest:945"] = {n="Втеча Терилюн",s="На півдні Темного Узбережжя юна Терілун забрела на зловісні розкопки біля Глефи Володаря й опинилася в пастці ворожих сектантів. Потрібен супровід від Альянсу, щоб вивести її в безпечне місце й донести звістку про її порятунок стривоженій сестрі, Терісіль, що живе біля Святилища Аессіни.",h="На півдні Темного Узбережжя юна Терілун забрела на зловісні розкопки біля Глефи Володаря й опинилася в пастці...",kw={"втеча терилюн","терілун","терісіль","глефа володаря","молот присмерку","супровід","завдання"},ang={["faction:Alliance"]="Допомагаючи мандрівникам, що потрапили в біду, на кшталт Терілун, ви зміцнюєте присутність Альянсу й прихильність до нього серед нічних ельфів, що боронять Ашенваль.",["race:NightElf"]="Глефа Володаря — прадавній шрам на історії Калімдору. Бачити, як ваші родичі-калдореї безтурботно забрідають на розкопки сектантів, — тверезе нагадування про загрози, що підкрадаються до Ашенвалю."},sec={{t="Небезпечна прогулянка",b="Глефа Володаря — одна з найтривожніших пам'яток Темного Узбережжя: над нею панує велетенський череп прадавнього чудовиська, пробитий величезним кам'яним клинком. Попри жах, що нависає над долиною, Терілун забрела в саме серце яру. Незабаром її притисли сектанти Молота Присмерку, і вціліла вона лише завдяки швидкій реакції та вмінню ховатися серед нерівної місцевості."},{t="Звістка до святилища",b="Сестра Терілун, Терісіль, живе далеко на півдні, біля тихого Святилища Аессіни. Терілун відома своєю допитливістю й не боїться забруднити вбрання, та навіть її рідних приголомшило те, що вона полізла на нечисті розкопки біля Глефи Володаря. Звістка про те, що Терілун у безпеці, приносить полегшення глибоко стривоженій сестрі, яка надто добре знає, які темні сили нині риються в прадавній землі Темного Узбережжя."}},faq={{q="Хто така Терілун?",a="Терілун — молода нічна ельфійка, охоча до пригод, що забрела на небезпечні розкопки біля Глефи Володаря на півдні Темного Узбережжя. Вона сестра Терісіль.",al={"терілун","хто така терілун","дівчина в пастці"}},{q="Хто така Терісіль?",a="Терісіль — сестра Терілун, що перебуває в тихому Святилищі Аессіни в Ашенвалі. Вона нажахана, дізнавшись, що сестра забрела так близько до темного, оскверненого місця.",al={"терісіль","сестра терілун"}},{q="Чому Глефа Володаря така небезпечна?",a="Глефа Володаря — давня зловісна ущелина, де лежать рештки слуги Древнього Бога. Тут кишать культисти Молота Присмерку: вони завзято розкопують це місце й нападають на кожного, хто туди потикається.",al={"небезпека глефи володаря","сектанти глефи володаря"}},{q="Куди треба провести Терілун?",a="Терілун треба вивести з найближчих околиць Глефи Володаря в безпечне місце, а тоді рятівникові слід вирушити до Святилища Аессіни й сповістити її сестру.",al={"куди вести терілун","куди йде терілун"}},{q="Де Святилище Аессіни?",a="Святилище Аессіни — на південному заході Ашенвалю, на захід від Астранаару. Це прихисток, присвячений лісовому духові Аессіні.",al={"місце святилища аессіни","де терісіль"}},{q="Як Терілун вижила серед культистів?",a="Терілун уникла полону лише тому, що вчасно знайшла тісну схованку серед скель, перш ніж культисти Молота Присмерку встигли її помітити.",al={"як терілун вижила"}}},fp="18,319,17.430.0,18.430.0,17.163.0,16.181.0,40.204.0,41.176.0,39.135.0,49.167.0"}
P.entries["quest:947"] = {n="Печерні гриби",s="«Печерні гриби» — доручення Альянсу від нічного ельфа Барітраса Муншейда в Обердайні. Готуючи особливе зілля, Барітрас посилає шукача пригод у приховану печеру за Водоспадом Скельного Джерела, щоб зібрати рідкісні гриби й перевірити тривожні передчуття, які відчули в Гаю Прадавніх.",h="«Печерні гриби» — доручення Альянсу від нічного ельфа Барітраса Муншейда в Обердайні.",kw={"печерні гриби","барітрас муншейд","бліда поганка","стебло стрункавки","водоспад скельного джерела","гай прадавніх"},ang={["faction:Alliance"]="Обердайн — головна твердиня Альянсу на узбережжі Калімдору, і зло, що підкрадається в східних горах, прямо загрожує стабільності всього берега.",["profession:Herbalism"]="Збирачі й травники оцінять полювання на Бліду Поганку й Стебла Стрункавки, хоча ці зразки ростуть у темних печерах, а не в пишному лісовому ґрунті.",["race:NightElf"]="Гай Прадавніх тонко відчуває природну рівновагу Темного Узбережжя, тож будь-яке збурення, яке там помітили під водоспадом, для калдореїв — нагальна тривога."},sec={{t="Рецепт за водоспадом",b="Для сильної суміші Барітрасові Муншейду потрібні особливі інгредієнти: Стебла Стрункавки й невловна Бліда Поганка. Ці гриби буяють у сирій, тінистій печері, схованій просто за Водоспадом Скельного Джерела на північному сході Темного Узбережжя. Сама алхімія делікатна, але зібрати ці зразки куди небезпечніше, ніж нарвати звичайних лісових трав."},{t="Пересторога Прадавніх",b="Барітрас уникав печери не з лінощів. Шановані деревні охоронці з Гаю Прадавніх суворо застерегли, що відчули, як у гірських печерах загніздилося щось мерзенне. Посилаючи витривалого дослідника замість іти самому, Муншейд прагне перевірити, чи справді обґрунтовані грізні передчуття старійшин про зло, що підкрадається на півночі Темного Узбережжя."}},faq={{q="Де починається це доручення?",a="Це доручення дає Барітрас Муншейд, що мешкає в прибережному поселенні нічних ельфів Обердайн у центрі Темного Узбережжя.",al={"де взяти печерні гриби","місце барітраса муншейда","початок печерних грибів"}},{q="Де ростуть гриби?",a="Вони ростуть у печері, схованій за Водоспадом Скельного Джерела, на гірському схилі на північний схід від Обердайна.",al={"де гриби","де струпні стебла","печера за водоспадом темного узбережжя"}},{q="Чому Барітрас Муншейд не піде по гриби сам?",a="Гай Прадавніх окремо порадив Барітрасові триматися подалі від водоспаду. Великі прадавні відчули, що в тій печері знайшло притулок неприродне зло, яке набирає сили.",al={"чому барітрас не йде сам","чому барітрас лишається в оберіжині"}},{q="Які саме гриби потрібні?",a="Для зілля Муншейдові потрібні п'ять Стебел Стрункавки й одна надзвичайно небезпечна Бліда Поганка.",al={"які гриби потрібні","які гриби для муншейда"}},{q="До чого веде це доручення далі?",a="Коли присутність у печері підтверджено, а гриби доставлено, шлях повертає на південь — до прадавнього захисника Ону в Гаю Прадавніх.",al={"наступне завдання після печерних грибів","продовження ону"}},{q="Чому прадавніх непокоїть Водоспад Скельного Джерела?",a="Гай Прадавніх застеріг Барітраса, що в печері за водоспадом, можливо, чаїться зло, яке набирає сили. Він просить мандрівника зібрати гриби й перевірити це попередження.",al={"попередження прадавніх про водоспад","чому розвідати печеру"}}},fp="14,322,25.366.0,21.406.1,27.136.0,32.122.0,61.183.0,35.115.0,35.153.0,55.168.1"}
P.entries["quest:948"] = {n="Ону",s="Це доручення скеровує мандрівників з Обердайна на південь, до Гаю Прадавніх, щоб порадитися з Ону. Ваші знахідки — дивні гриби з глибин печери біля Водоспаду Скельного Джерела — привернули нагальну увагу одного з найдавніших охоронців Темного Узбережжя.",h="Це доручення скеровує мандрівників з Обердайна на південь, до Гаю Прадавніх, щоб порадитися з Ону.",kw={"ону","древо знань","гай прадавніх","барітрас муншейд","водоспад скельного джерела","обердайн"},ang={["class:Druid"]="Друїди глибоко шанують Прадавніх як утілення мудрості природи. Дослідити дивні печерні нарости на прохання Ону — прямий обов'язок Кола Кенарія.",["faction:Alliance"]="Для мандрівників Альянсу, що допомагають убезпечити Темне Узбережжя, довіра й мудрість місцевих прадавніх украй важливі, щоб орієнтуватися в загадкових північних нетрях Калімдору.",["race:NightElf"]="Древа Знань — священні партнери калдореїв, що провадили ваш народ ще до Розколу. Відгукнутися на поклик Ону — урочистий обов'язок, щоб уберегти святість Темного Узбережжя."},sec={{t="Поклик Прадавніх",b="Коли мандрівник повертається до Обердайна з грибними зразками з глибин Водоспаду Скельного Джерела, Барітрас Муншейд розуміє, що справа сягає далеко за межі звичайної ботанічної цікавості. Звістка про отруєні печери швидко доходить до Ону — Древа Знань, що вкоренилося в тихому святилищі Гаю Прадавніх на південь від містечка. Хоч давні деревні створіння від природи терплячі й неквапливі, те, що Ону негайно хоче поради, свідчить: порча, що тече водами Темного Узбережжя, може бути пов'язана з давніми, тривожними силами."},{t="Дорога до Гаю",b="Південна дорога з Обердайна веде від прибережних руїн углиб суходолу, до гірських схилів. Гай Прадавніх — давній оплот природи, значною мірою вбережений від повзучого тління, що вразило узбережжя. Тут, серед височенних кам'яних курганів і споріднених духів, чекає Ону, готовий скерувати союзників до глибших, жахливіших пошестей, що ворушаться на краю нетрів."}},faq={{q="Хто такий Ону?",a="Ону — Древо Знань, колосальний розумний деревний охоронець, що присвятив себе збиранню й збереженню знань. Він очолює Гай Прадавніх на півдні Темного Узбережжя й ділиться мудрістю та порадами із захисниками краю.",al={"хто такий ону","особа ону","що таке ону"}},{q="Чому Ону хоче зі мною поговорити?",a="Нещодавно ви спускалися в печери під Водоспадом Скельного Джерела по зразки грибів для Барітраса Муншейда. Дивна природа знайденого там стривожила природознавців, і Ону просить вас прийти, щоб обговорити дедалі більшу скверну.",al={"чому ону кличе","причина розмови","чому йти до ону"}},{q="Де Гай Прадавніх?",a="Гай Прадавніх — на південь від Обердайна, у передгір'ї східного гірського пасма. Ідіть головною дорогою на південь Темним Узбережжям, а тоді поверніть на схід до гірських схилів — там і знайдете Ону.",al={"місце ону","де гай прадавніх","як знайти ону"}},{q="Що за істота Древо Знань?",a="Древа Знань — прадавні деревні істоти, союзники нічних ельфів і Кола Кенарія. Їх шанують за глибоку мудрість і пам'ять: вони — живі сховища природної магії й таємниць історії.",al={"прадавній знань","яка це істота ону","дерев'яник чи прадавній"}},{q="Чому виклик Ону вважають нагальним?",a="Прадавні славляться неквапливою, розважливою вдачею й рідко діють поспіхом. Як зауважує Барітрас Муншейд, коли така терпляча й розважлива істота, як Ону, сама кличе вас на раду, загроза Темному Узбережжю, певно, серйозна.",al={"чому терміново","чи ону стривожений","попередження барітраса"}},{q="Що далі після зустрічі з Ону?",a="Привітавши вас у Гаю Прадавніх, Ону просить допомогти розслідувати куди темнішу загрозу далі на південь уздовж узбережжя — зловісні розкопки довкола Глефи Володаря.",al={"наступне завдання після ону","що далі","куди ону посилає"}}},fp="3,267,27.538.0,20.427.0,11.238.0,35.259.0,35.208.0,44.211.0,39.231.0,34.209.1"}
P.entries["quest:949"] = {n="Сутінковий табір",s="«Сутінковий табір» — розвідувальна місія Альянсу проти потаємних культистів, що отаборилися довкола Глефи Володаря на півдні Темного Узбережжя. Побачивши їхнє обрядове місце крізь чашу віщування, дослідники мусять проникнути на розкопки, щоб з'ясувати, що саме хоче відкопати Молот Присмерку.",h="«Сутінковий табір» — розвідувальна місія Альянсу проти потаємних культистів, що отаборилися довкола Глефи...",kw={"сутінковий табір","молот присмерку","глефа володаря","сутінковий фоліант","розкопки","темне узбережжя"},ang={["class:Druid"]="Розкрити дослідження культу украй важливо для охоронців Кола Кенарія, що прагнуть, аби згубні давні сутності лишалися надійно похованими.",["faction:Alliance"]="Зупинивши дивні розкопки культу, ви не дасте наростаючій загрозі розхитати північ Калімдору.",["race:NightElf"]="Молот Присмерку оскверняє священні землі Калімдору темним чаклунством просто під гіллям давніх гаїв Темного Узбережжя."},sec={{t="Розвідка розкопок",b="Глефа Володаря здавна стояла зловісною закам'янілою загадкою серед скелястих пагорбів півдня Темного Узбережжя, але раптова поява культу Молота Присмерку перетворила давню дивину на справжню загрозу. Зазирнувши в їхні укріплення крізь чашу віщування, розвідників посилають у саму гущу табору, щоб з'ясувати справжні задуми культу, перш ніж ужити захисних заходів."},{t="Ілюстрований фоліант",b="Обшукавши табір, можна переконатися, що культисти — не просто мародери чи розбійники: їхньою справою керує глибоке окультне вчення. Глибоко в північному таборі лежить давній, ретельно переписаний від руки фоліант, оздоблений майстерними, але тривожними ілюстраціями. Цей текст доводить, що Молот Присмерку навмисно досліджує колосальну сутність, поховану під землею."}},faq={{q="Яка мета завдання «Сутінковий табір»?",a="Вам треба проникнути до табору Молота Присмерку біля Глефи Володаря на півдні Темного Узбережжя й здобути доказ, що розкриває задуми культистів, — рукописну книгу обрядів, яка лежить у їхньому таборі.",al={"мета сутінкового табору","що робити в сутінковому таборі"}},{q="Хто посилає вас розвідати табір?",a="Завдання дає сама Чаша Віщування на кручі над Глефою Володаря: так триває розслідування, розпочате на прохання прадавнього захисника Ону.",al={"хто дає сутінковий табір","видавець сутінкового табору"}},{q="Де в таборі шукати доказ?",a="Справжній доказ — Сутінковий Фоліант у північній частині табору. Інші книги в таборі можуть виявитися небезпечними приманками, що спускають на непроханих гостей захисну магію.",al={"де доказ у таборі","місце книги","місце фоліанта"}},{q="Чому Молот Присмерку отаборився біля Глефи Володаря?",a="Культисти одержимі давніми темними силами Древніх Богів та їхніх слуг. Вони розкопують величезну скам'янілу тушу, пришпилену велетенським кам'яним лезом, щоб вивчити чи пробудити прадавнє зло, яке там залишилося.",al={"чому сектанти біля глефи","мета молота присмерку на узбережжі"}},{q="Що буде, коли фоліант знайдено?",a="Здобутий фоліант веде до завдання «Повернення до Ону»: вам належить віднести знайдені записи на північ, до прадавнього деревного велетня в Гаю Прадавніх.",al={"наступне завдання після сутінкового табору","куди після фоліанта"}}},fp="17,319,15.403.0,20.395.1,44.211.0,38.174.0,36.178.0,52.225.0,36.160.0"}
P.entries["quest:95"] = {n="Помста Свена",s="Сповнений горя й жаги помсти, самітник Свен Йорґен просить мандрівників повернутися на його зруйнований хутір на сході Сутінколісся. Поки він роками переслідував таємничих вершників, що вирізали його родину, якась підозріла постать закопала біля його стодоли щось, що може дати відповіді.",h="Сповнений горя й жаги помсти, самітник Свен Йорґен просить мандрівників повернутися на його зруйнований хутір...",kw={"помста свена","свен йорґен","хутір йорґенів","темні вершники","перевал мертвого вітру","сутінколісся"},ang={["class:Paladin"]="Жорстока різанина безневинних, учинена зловісними силами з Перевалу Мертвого Вітру, вимагає праведної відплати й справедливості для загиблих.",["faction:Alliance"]="Різанина родини Йорґенів — ще одна ознака відрізаності Сутінколісся: без регулярних патрулів армії Стормвінда темні сили сягають дуже далеко."},sec={{t="Трагедія на хуторі",b="Колись Свен Йорґен був простим фермером, що обробляв поля на південному сході Сутінколісся. Його життя розлетілося на друзки, коли Темні Вершники в каптурах, що спустилися з Перевалу Мертвого Вітру, напали на хутір і вирізали його родину, поки він був відсутній. Повернувшись на місце різанини, Свен помітив невідому постать, що скрадалася біля стодоли й гарячково щось закопувала. Свен обрав помсту й одразу вирушив полювати на вбивць, лишивши заховане там, де воно було."},{t="Розкопуючи таємниці",b="Тепер Свен таборує на західних пагорбах, поглинутий гнівом, і йому потрібен хтось, хто повернеться на Хутір Йорґенів. За старим пнем між хатою й зруйнованою стодолою височіє купа поспіхом насипаної пухкої землі. Відкопати те, що там заховано, — перший крок до розуміння, чому темні вершники взагалі взялися за тихого фермера із Сутінколісся."}},faq={{q="Хто такий Свен Йорґен?",a="Свен Йорґен був звичайним фермером, що жив на південному сході Сутінколісся, біля кордону з Перевалом Мертвого Вітру. Повернувшись додому й заставши свою родину вбитою зловісними вершниками, він покинув ферму й став відлюдником, одержимим помстою винуватцям.",al={"хто такий свен","переказ про свена","історія свена"}},{q="Що сталося зі Свеновою фермою?",a="На Свенів хутір напали загадкові Темні Вершники, що вилітають із Перевалу Мертвого Вітру. Вони вирізали всю його родину й лишили господарство в руїнах, перш ніж Свен устиг повернутися й захистити своїх.",al={"трагедія ферми йорґенів","що сталося з фермою свена","чому ферма знищена"}},{q="Хто щось закопав за коморою?",a="Одразу після різанини Свен бачив, як біля комори нишпорила темна постать і щось закопувала. Але він кинувся в нетрі навздогін за Темними Вершниками, так і не встигнувши ні впіймати незнайомця, ні відкопати сховане.",al={"хто закопав річ","тінь на фермі свена","хто викопав горбок"}},{q="Де купа пухкої землі?",a="Купа пухкої землі — на Хуторі Йорґенів на південному сході Сутінколісся, просто за старим пеньком між коморою і зруйнованою хатою.",al={"де купа землі","місце горбка","де пеньок"}},{q="Хто такі Темні Вершники?",a="Темні Вершники — зловісні вершники в каптурах, що вилітають із Перевалу Мертвого Вітру. Про їхнє походження відомо мало, але після їхніх жорстоких набігів на Сутінколісся лишаються тільки смерть і руїна.",al={"хто темні вершники","переказ про темних вершників","вершники перевалу мертвого вітру"}},{q="Чому Свен сам не відкопав закопане?",a="Повернувшись додому й побачивши, як постать щось закопує, Свен, охоплений горем, одразу кинувся за Темними Вершниками, що відступали. А поки він облаштовував свій схований табір, ферму захопили, і повертатися туди самому йому було надто боляче.",al={"чому свен не відкопав","чому свен пішов"}}},fp="14,281,24.471.0,18.385.0,19.274.0,29.193.0,37.213.0,41.166.0,24.197.0,47.247.0"}
P.entries["quest:950"] = {n="Повернення до Ону",s="«Повернення до Ону» — завдання Альянсу, що завершує перше розслідування щодо культистів, які отаборилися на берегах Темного Узбережжя. Після рейду на табір культистів і спроби прочитати Сутінковий Фоліант шукач пригод здобуває одну сторінку божевільних каракуль, щоб віднести її Древу Знань Ону в Гаю Прадавніх.",h="«Повернення до Ону» — завдання Альянсу, що завершує перше розслідування щодо культистів, які отаборилися на...",kw={"повернення до ону","ону","сутінковий фоліант","божевільні каракулі","молот присмерку","гай прадавніх"},ang={["class:Druid"]="Хаотичний, протиприродний резонанс каракуль — образа природного ладу, який друїди бережуть пліч-о-пліч із прадавніми на кшталт Ону.",["faction:Alliance"]="Розслідуючи діяльність культу на берегах Темного Узбережжя, ви дбаєте, щоб поселення нічних ельфів на кшталт Обердайна лишалися захищеними від прихованих загроз.",["race:NightElf"]="Темні культисти, що оскверняють береги Темного Узбережжя, загрожують рівновазі, яку бережуть Древа Знань, тож пересторога Ону для калдореїв — глибоко особиста."},sec={{t="Погляд у безумство",b="Знайшовши Сутінковий Фоліант у таборі Молота Присмерку, кожен, хто зазирне в його сторінки, зазнає миттєвого нападу на чуття. Письмена пливуть і танцюють пергаментом, а колись вишукані завитки перетворюються на гротескні постаті. Розумове напруження таке нестерпне, що вирвати один аркуш із каракулями — це все, що здатен витримати смертний розум, перш ніж його здолає запаморочення."},{t="Давні підозри",b="Коли клаптик приносять Ону, височенне Древо Знань упізнає протиприродну ауру, що його просякає. Пергамент випромінює хаотичну, первісну магію, яку Ону прямо пов'язує з діяльністю давніх темних сил, похованих під землею. Хоча каракулі важко розшифрувати, вони підтверджують: присутність Молота Присмерку на Темному Узбережжі — не просто розбій, а частина глибшого, блюзнірського задуму."}},faq={{q="Що за сторінка з Сутінкового Фоліанта?",a="Сторінка, що зветься просто «Божевільні Каракулі», — вирваний аркуш зі священної книги культу. Погляд на неї завдає важких душевних мук: письмена скручуються в потворні мінливі візерунки, пов'язані з первісною магією Порожнечі.",al={"божевільні нашкрябані записи","що за каракулі","сторінка сутінкового фоліанта"}},{q="Хто такий Ону?",a="Ону — Древо Знань, що вкоренилося в Гаю Прадавніх на півдні Темного Узбережжя. Він мудрий охоронець і вчений, що веде нічних ельфів і союзників з Альянсу проти нових проявів скверни в лісі.",al={"хто такий ону","ону темне узбережжя","дерев'яник ону"}},{q="Що Ону дізнається з каракулів?",a="Ону відчуває, що від сторінки віє хаотичною первісною енергією, і розпізнає вплив прадавніх злих сутностей. Записи свідчать, що культисти Молота Присмерку завзято шукають місця з реліквіями й поховані сили по всьому Темному Узбережжю.",al={"що ону дізнається","значення каракулів"}},{q="Чому Молот Присмерку на Темному Узбережжі?",a="Культ приваблює Темне Узбережжя: тут він розкопує зруйновані ельфійські місця й шукає рештки прадавньої сили, пов'язаної з первісною темрявою й Древніми Богами, а безлад у краї допомагає приховувати обряди.",al={"культисти на темному узбережжі","чому молот присмерку тут"}},{q="Куди веде це розслідування далі?",a="Переконавшись у присутності культу, Ону звертає погляд на прадавні ельфійські руїни Матистри на півночі й посилає шукачів пригод забрати давні реліквії, перш ніж їх захоплять культисти.",al={"яке завдання далі","далі після повернення до ону"}},{q="Чому від читання фоліанта паморочиться в голові?",a="Сутінковий Фоліант списаний темною, божевільною магією Порожнечі й хаосу. Знаки затьмарюють розум смертних, викликаючи видіння й непритомність, щоб чужинці не розгадали їхніх таємниць.",al={"чому паморочиться в голові","дія фоліанта"}}},fp="13,336,22.414.0,18.421.1,46.218.0,11.210.0,39.241.0,42.194.0,40.208.1,42.205.0"}
P.entries["quest:95041"] = {n="Збирачі даних",s="«Збирачі даних» — завдання від Джемми Квіксвіч, гномки-вигнанки, що мешкає в Айронфорджі. Під час відчайдушної евакуації з Гномреґану вона переписала найцінніші родинні архіви на перфокарти, та загубила кілька з них у крижаних заметах біля міських брам. Повернути ці втрачені картки — означає врятувати все: від передових схем корабельної інженерії до незамінних родинних рецептів.",h="«Збирачі даних» — завдання від Джемми Квіксвіч, гномки-вигнанки, що мешкає в Айронфорджі.",kw={"перфокарти","квіксвіч","гномреґан","айронфордж","дані","архів","гноми"},ang={["faction:Alliance"]="Альянс значною мірою покладається на гномську винахідливість; допомагаючи переселенцям зберегти воєнні інженерні записи, ви рятуєте цінні технічні знання Альянсу від вічного забуття.",["profession:Cooking"]="Поряд зі світового рівня інженерними схемами лежить особистий рецепт чилі бабусі Квіксвіч — доказ, що добра їжа має не меншу сентиментальну цінність, ніж військова наука.",["profession:Engineering"]="Інженери оцінять величезну цінність, приховану на цих картках: справжні креслення корпусів субмарин Другої війни та складні арканотехнічні рівняння.",["race:Gnome"]="Для гномів-шукачів пригод повернення цих перфокарт — справа збереження культури: важливі винаходи й родинні спогади не повинні згинути в радіоактивних руїнах батьківщини."},sec={{t="Метушня в снігу",b="Коли навала трогів і радіаційна катастрофа, що настала за нею, вигнали гномів із Гномреґану, тисячі втікали з тим, що встигли вхопити в метушні. Джемма Квіксвіч завбачливо перенесла знання кількох поколінь родини на фізичні архіви з перфокарт. На лихо, з пошкодженої сумки кілька ключових карток випали на снігові поля довкола загиблого міста. Без цих перфокарт решта даних читається як нерозбірлива тарабарщина, і інтелектуальна спадщина родини опиняється під загрозою зникнення."},{t="Рівняння і чилі",b="Гномські архіви даних відображають химерну широту пріоритетів їхньої цивілізації. Записи родини Квіксвіч містять глибокі арканотехнічні польові рівняння, життєво важливі креслення корпусів субмарин часів Другої війни та секретний рецепт чилі бабусі Квіксвіч. Сторонньому поєднання військової інженерії з домашньою кухнею може здатися дивним, та для біженців в Айронфорджі зберегти домашній затишок не менш важливо, ніж технологічні дива."}},faq={{q="Хто така Джемма Квіксвіч?",a="Джемма Квіксвіч — гномка-біженка, якій вдалося втекти під час падіння Гномреґана; тепер вона в безпеці живе серед дворфійських залів Айронфорджа.",al={"джемма квіксвіч","хто дає збирачів даних","видавець збирачів даних"}},{q="Які дані зберігаються на загублених картках?",a="На перфокартах — архів родини Квіксвіч: тайнотехнічні рівняння, креслення корпусів підводних човнів ще з часів Другої війни й рецепт чилі бабусі Квіксвіч.",al={"що за перфокарти","що було на картках","архіви квіксвіч"}},{q="Де загубилися картки з даними?",a="Вони випали крізь дірку в Джемминій торбі, коли вона тікала з Гномреґана, і тепер лежать у снігу просто біля брами підземного міста в Дун Мороґу.",al={"де картки","місце карток з даними","де вона їх загубила"}},{q="Чому Джемма не може прочитати вцілілі картки без загублених?",a="Jemma says the data is too scrambled to recover without the missing punch cards. The quest does not explain how the cards encode or organize that information.",al={"чому потрібні всі картки","перемішані дані","дані перфокарт"}},{q="Яку роль гноми відіграли в Другій війні щодо підводних човнів?",a="Під час Другої війни гноми зробили великий внесок у воєнні зусилля Альянсу завдяки передовій інженерії — зокрема конструювали підводні човни й керували ними, протистоячи флоту Орди.",al={"гноми й підводні човни","креслення підводних човнів"}},{q="Чому гноми-біженці живуть в Айронфорджі?",a="Коли Гномреґан раптово впав під навалою трогів і внаслідок катастрофічного опромінення, уцілілі гноми втекли зі свого підземного дому, і Король Маґні Бронзбірд дав їм прихисток у сусідньому дворфійському місті Айронфордж.",al={"чому гноми в айронфорджі","гноми живуть з дворфами"}}},fp="13,403,22.544.0,19.469.0,24.143.0,38.187.0,34.180.0,66.158.0,65.204.0,45.234.0"}
P.entries["quest:95065"] = {n="Пора рибалити",s="«Пора рибалити» — просте доручення для Ґілберта Ґрея, літнього рибалки, що милується мальовничими краєвидами узбережжя в гавані Стормвінда. Наживка в нього скінчилася саме тоді, коли риба почала клювати, тож він покладається на перехожих: нехай збігають до міських каналів і поповнять його рибальську скриньку.",h="«Пора рибалити» — просте доручення для Ґілберта Ґрея, літнього рибалки, що милується мальовничими краєвидами...",kw={"рибальство","ґілберт ґрей","кетрін ліланд","наживка","гавань","стормвінд"},ang={["faction:Alliance"]="Допомога старому городянинові, як-от Ґілбертові Ґрею, — це ті скромні щоденні клопоти, на яких тримаються життя й дух Стормвінда.",["race:Human"]="Для людей, чий дім — Стормвінд, допомогти літньому сусідові провести тихе пообіддя за риболовлею — приємний відпочинок від королівської політики."},sec={{t="День біля води",b="Не всіх у Стормвінді поглинають політика, війна чи змови, що нависли над містом. Унизу, на краю гавані, Ґілберт Ґрей проводить тихі дні, насолоджуючись морським бризом і спостерігаючи, як його поплавець танцює на хвилях. Та захоплений рибалка легко втрачає лік своєму приладдю, а раптовий кльов швидко спустошує навіть повну бляшанку з наживкою. Щоб не покидати улюбленого місця, старий звертається до доброзичливих шукачів пригод — хай поповнять найнеобхідніше."},{t="Припаси вздовж каналів",b="Усі рибальські потреби Стормвінда задовольняє Кетрін Ліланд, яка тримає відому крамницю рибальського приладдя біля кам'яних каналів, на захід від гамірного Торгового Кварталу. Вона забезпечує рибалок усього міста блешнями, наживкою й практичними порадами, тож старим завсідникам на кшталт Ґілберта Ґрея ніколи не доводиться змотувати вудки завчасу через брак блискучої приманки чи звивистого черв'яка."}},faq={{q="Хто такий Ґілберт Ґрей?",a="Ґілберт Ґрей — літній рибалка, що проводить час біля води в гавані Стормвінда. Він радо днями закидає вудку в море, а коли власні запаси вичерпуються, просить перехожих шукачів пригод принести свіжої наживки й принад.",al={"ґілберт ґрей","старий ґрей","хто дає це завдання"}},{q="Хто така Кетрін Ліланд?",a="Кетрін Ліланд — постачальниця рибальського приладдя й наставниця рибалок у Стормвінді. Її крамничка стоїть на міських каналах трохи на захід від Торгового Кварталу: там вона продає рибалкам королівства снасті, наживку й дає поради.",al={"кетрін ліланд","торговка рибальством у стормвінді","ліланд стормвінд"}},{q="Де рибалить Ґілберт Ґрей?",a="Ґілберт Ґрей — біля води в гавані Стормвінда, де йому до вподоби відкритий морський краєвид подалі від тісних міських вулиць.",al={"місце ґілберта ґрея","де ґілберт ґрей","рибалка в гавані"}},{q="Що потрібно Ґілбертові Ґрею?",a="Ґілбертові Ґрею потрібні нічні черв'яки на наживку й блискуча блешня як принада — і те, і те можна купити в Кетрін Ліланд на каналах.",al={"предмети пори рибалити","яку наживку хоче ґрей"}},{q="Чому Ґілберт Ґрей сам не сходить по приладдя?",a="Коли ви з ним говорите, риба саме добре клює, і він не хоче втратити своє місце чи пропустити гарний улов, шкандибаючи аж до міста по нові запаси.",al={"чому ґрей не купить наживку","чому ґрею потрібна допомога"}},{q="Де саме на каналах крамничка Кетрін Ліланд?",a="Її крамничка — просто біля води каналу трохи на захід від Торгового Кварталу; до неї легко дістатися кам'яними доріжками, що тягнуться вздовж міських водних шляхів.",al={"місце крамнички ліланд","де магазин ліланд","торговий квартал канали"}}},fp="12,264,18.462.0,25.400.0,20.228.0,24.211.0,29.139.0,37.159.0,52.165.0,58.163.0"}
P.entries["quest:951"] = {n="Реліквії Матистри",s="Це завдання посилає шукачів пригод Альянсу на північ уздовж берегів Темного Узбережжя, щоб перебрати зарослі Руїни Матістри. Ону, Древо Знань, що вкоренилося в Гаю Прадавніх, шукає ці давні артефакти калдореїв, щоб зрозуміти, як культ Молота Присмерку використовує чаклунство нічних ельфів для своїх зловісних обрядів.",h="Це завдання посилає шукачів пригод Альянсу на північ уздовж берегів Темного Узбережжя, щоб перебрати зарослі...",kw={"реліквії матистри","руїни матістри","ону","молот присмерку","високородні","темне узбережжя"},ang={["class:Druid"]="Допомагаючи Ону, друїди служать одному з найвеличніших старійшин-вартових природи й бережуть давню історію Темного Узбережжя від спотворення темними культистами.",["faction:Alliance"]="Не дати Молотові Присмерку обернути давню магію на зброю — головне, щоб уберегти північ Калімдору від темних підземних сил.",["race:NightElf"]="Для нічних ельфів бачити, як реліквії їхньої слави доби до Розколу викопують із землі, — сумне нагадування про падіння їхньої цивілізації й тривожна пересторога: могутні мистецтва предків використовують апокаліптичні божевільці."},sec={{t="Тривожне відкриття",b="Коли шукачі пригод здобули отруєний пергамент у культистів, що чатують біля колосального пам'ятника, відомого як Глефа Володаря, Ону розшифрував тривожне одкровення. Текст виявився не писанням самого культу, а проклятим уривком давнього письма нічних ельфів. Зіпсований Молотом Присмерку, пергамент показав, що ці апокаліптичні фанатики приборкують забуту ельфійську магію, щоб пробудити чи викликати своїх давніх господарів назад у світ смертних."},{t="Занепала твердиня",b="Щоб протидіяти цьому темному задуму, Ону посилає героїв до Руїн Матістри на північно-східних берегах Темного Узбережжя. Колись Матистра була сяйливою твердинею цивілізації Високородних, доки не розкололася під час Розколу. Хоча місто обернулося на уламки, бур'ян і кубло наг, могутні рештки його первісних тайних і духовних чарів досі жевріють у розбитих урнах і давніх реліквіях, розкиданих по кам'яних фундаментах."},{t="Розгадати темні задуми",b="Збираючи вцілілі артефакти серед зарослих травою уламків руїн, захисники Темного Узбережжя сподіваються розгадати, якими саме прийомами культисти хочуть скористатися. Ону вивчає залишкову магію реліквій і змагається з часом, щоб розшифрувати плани культу, перш ніж Молот Присмерку остаточно схилить давнє чаклунство калдореїв до звільнення своїх підземних господарів."}},faq={{q="Що таке Реліквії Матистри?",a="Це уламки зачарованого посуду, урн і артефактів, що лишилися в Руїнах Матістри. Створені за розквіту давньої цивілізації нічних ельфів, ще до Великого Розколу, вони досі гудуть залишковою магічною енергією.",al={"що таке реліквії матистри","які реліквії","ельфійські реліквії матистри"}},{q="Навіщо Ону ці реліквії?",a="Ону дізнався, що культ Молота Присмерку намагається за допомогою давньої ельфійської магії повернути у світ своїх темних володарів. Вивчивши вцілілі реліквії з Матистри, Ону сподівається зрозуміти, як саме культ збирається використати цю прадавню силу.",al={"навіщо ону реліквії","призначення реліквій матистри"}},{q="Де розташовані Руїни Матістри?",a="Руїни — на північно-східному узбережжі Темного Узбережжя, на північ від руїн Амет'Арана й Башал'Арана, одразу за Вежею Альталакса.",al={"де руїни матістри","місце матистри"}},{q="Кого Молот Присмерку намагається повернути?",a="Культ відданий прадавнім злим володарям; Ону попереджає, що культисти користуються давньою ельфійською магією, щоб повернути цих старих володарів в Азерот.",al={"хто повелителі молота присмерку","господарі культу темне узбережжя"}},{q="Чим була Матистра, перш ніж стати руїною?",a="Тисячі років тому Матистра була великою твердинею й містом нічних ельфів. Вона перетворилася на руїну під час Великого Розколу, і відтоді її заполонили дикі хащі, привиди й мерзенні прибережні створіння, як-от наги.",al={"історія матистри","чим була матистра"}},{q="Хто дає завдання «Реліквії Матистри»?",a="Завдання дає Ону — прадавній деревний велетень, що вкоренився в Гаю Прадавніх у південно-центральній частині Темного Узбережжя, — після розслідування біля Глефи Володаря.",al={"хто дає реліквії матистри","видавець реліквій матистри"}}},fp="16,329,22.461.1,18.465.0,21.377.1,30.237.0,31.253.0,42.141.0,50.142.0,43.230.0,39.163.0"}
P.entries["quest:95161"] = {n="Пам'ятай, що я люблю тебе",s="«Пам'ятай, що я люблю тебе» — завдання Альянсу, що починається в сиротинці Стормвінда й веде мандрівників у похмурі ліси Сутінколісся. Отримавши моторошний Заплямований Кров'ю Лист, шукачі пригод мають розшукати нещодавно всиновленого сироту на ім'я Джеремі Гартвівер і його прийомну матір, Аветт Феллвуд.",h="«Пам'ятай, що я люблю тебе» — завдання Альянсу, що починається в сиротинці Стормвінда й веде мандрівників у...",kw={"сиротинець","джеремі гартвівер","аветт феллвуд","заплямований кров'ю лист","сутінколісся","стормвінд"},ang={["faction:Alliance"]="Пам'ятки про полеглу чи зниклу рідню, доставлені всиновленим сиротам, показують, якої особистої ціни коштує неспокій у королівстві.",["race:Human"]="Для людей Стормвінда це доручення поєднує відносно безпечне серце королівства з моторошними, забутими поселеннями Сутінколісся, де блукають привиди."},sec={{t="Звістка для сироти",b="Діти зі сиротинця Стормвінда несуть важкий тягар: їхні родини забрали війна, злидні й хаос, що охопив королівство. Джеремі Гартвівер теж був вихованцем сиротинця, доки його нещодавно не всиновила жінка на ім'я Аветт Феллвуд. Хоч життя в похмурих лісах Сутінколісся сповнене небезпек і тяжкої праці, вихователі вирішили, що там у хлопчика буде шанс на родину — краще, ніж сидіти замкненим у місті."},{t="Моторошна звістка",b="Завдання обертається довкола Заплямованого Кров'ю Листа для Джеремі, адресованого на руки Аветт Феллвуд. Розпитування ведуть мандрівників на південь, за межі безпечного Лісу Елвінн, у тінь Сутінколісся. Моторошний вигляд листа натякає на давню трагедію, що переслідує юного Джеремі далеко за брамою Стормвінда."}},faq={{q="Хто такий Джеремі Гартвівер?",a="Джеремі Гартвівер — хлопчик, що виріс у сиротинці Стормвінда. Нещодавно його всиновила Аветт Феллвуд, і він покинув місто, щоб жити й працювати в похмурому краї Сутінколісся.",al={"джеремі","хто такий джеремі","сирота джеремі"}},{q="Хто така Аветт Феллвуд?",a="Аветт Феллвуд — нова прийомна мати Джеремі, що живе в Сутінколіссі. Матрони Стормвінда вважають її милою жінкою, яка, певно, взяла Джеремі, щоб мати ще одну пару рук у щоденній праці.",al={"аветт","хто така аветт","прийомна мати"}},{q="Що таке Заплямований Кров'ю Лист?",a="Заплямований Кров'ю Лист — сумне послання для Джеремі Гартвівера, яке треба передати просто в руки його прийомній опікунці, Аветт Феллвуд. На ньому — відлуння насильства чи трагедії.",al={"лист із кров'ю","лист","що за лист"}},{q="Де знайти Аветт Феллвуд?",a="Аветт Феллвуд живе в Сутінколіссі — темному лісовому краї просто на південь від Лісу Елвінн, за річкою.",al={"місце аветт феллвуд","де аветт","знайти аветт"}},{q="Чому Джеремі відправили до Сутінколісся?",a="Джеремі всиновили із сиротинця Стормвінда. Сутінколісся — небезпечний і похмурий край, але його опікуни вважали, що жити в родині й допомагати чесною працею краще, ніж лишатися сиротою в притулку.",al={"чому сутінковий ліс","чому джеремі покинув стормвінд","сиротинець сутінкового лісу"}},{q="Яка фракція може взятися за це завдання?",a="Це завдання лише для Альянсу: воно починається в людській столиці Стормвінді й веде до Сутінколісся, яке контролює Альянс.",al={"чи це для альянсу","лише альянс","завдання орди"}}},fp="24,311,23.447.0,12.328.1,26.197.0,23.205.0,33.200.0,32.124.0,32.231.0,34.149.0"}
P.entries["quest:95189"] = {n="Герб Лордерона",s="Герб Лордерона — побита часом реліквія з королівським знаком занепалого північного королівства. Знайдений серед пустельних руїн Столичного міста, такий знак — рідкість відтоді, як королівство впало, і хтось у Стормвінді дуже хотів би його отримати.",h="Герб Лордерона — побита часом реліквія з королівським знаком занепалого північного королівства.",kw={"герб лордерона","лордерон","реліквія","леді дена кеннеді","стормвінд","біженці"},ang={["faction:Alliance"]="Герб Лордерона — символ наріжного каменя первісного Альянсу, тож його повернення — символічна перемога над спробою Погибелі й Відступників стерти все дощенту.",["race:Human"]="Для людей — надто тих, чиї родини колись жили на півночі, — герб болісно нагадує про велике королівство, що колись очолювало Альянс."},sec={{t="Розбита спадщина",b="Коли Погибель пронеслася королівством Лордерон, його палаци, архіви й горді знамена здебільшого знищили або лишили гнити в тіні Андерсіті. Уцілілі речі з королівським гербом — надзвичайна рідкість. Повернути цілий чи хоча б потертий герб із північних руїн — значить урятувати від забуття відчутний шматок людської історії."},{t="Притулок на півдні",b="Після Третьої війни тисячі північних біженців утекли на південь, до королівства Стормвінд, несучи з собою лише спогади про батьківщину. У Стормвінді Леді Дена Кеннеді охоче збирає такі рештки Лордерона, тож реліквії на кшталт цього герба дуже дорогі серцю південної столиці."}},faq={{q="Що таке Герб Лордерона?",a="Це вивітрена геральдична емблема з офіційним знаком Лордерона. Вона лишилася після того, як королівство впало під натиском Погибелі, і для вцілілих людей це цінна історична реліквія.",al={"герб лордерона","що таке герб лордерона","предмет герба лордерона"}},{q="Кому потрібен Герб Лордерона?",a="Герб приносять Леді Дені Кеннеді — шляхетній меценатці в Стормвінді, що збирає й зберігає рідкісні артефакти з полеглого північного королівства.",al={"хто бере герб","куди принести герб лордерона","здати герб"}},{q="Де знайшли герб?",a="Його знайшли в Руїнах Лордерона на Галявинах Тірісфалю — у зруйнованій столиці, під якою нині лежить твердиня Відступників Андерсіті.",al={"місце герба","герб у руїнах","де взяти герб"}},{q="Чому артефакти з Лордерона такі рідкісні?",a="Стрімке й катастрофічне падіння королівства під час Третьої війни обернулося планомірною різаниною його мешканців і руйнуванням маєтків. Мало які родинні реліквії пережили Погибель і подальше піднесення Відступників.",al={"чому реліквії лордерона рідкісні","рідкість артефактів лордерона"}},{q="Чому Стормвінд дбає про реліквії Лордерона?",a="Стормвінд прийняв хвилі біженців, лицарів і шляхти, що втекли від спустошення на півночі. Збереження реліквій вшановує полегле королівство-побратима в Альянсі й підтримує живою спадщину північних людей.",al={"чому стормвінд дбає","реліквії лордерона стормвінд"}},{q="Хто така Леді Дена Кеннеді?",a="Леді Дена Кеннеді — шляхтянка, що живе в Стормвінді й завзято рятує історичні рештки та родинні реліквії з Лордерона.",al={"леді дена кеннеді","хто така дена кеннеді"}}},fp="18,272,20.382.0,19.297.0,31.180.0,33.164.0,26.159.0,41.242.0,50.208.0,25.164.0"}
P.entries["quest:95195"] = {n="Закривавлена Відзнака",s="Закривавлені відзнаки — трагічні рештки полеглих оборонців Лордерона, розкидані серед зачумлених руїн королівства. Із давніми гербами Альянсу, ці пом'яті значки належали воякам, чиї родини втекли на південь, до Стормвінда, під час Третьої війни.",h="Закривавлені відзнаки — трагічні рештки полеглих оборонців Лордерона, розкидані серед зачумлених руїн...",kw={"закривавлена відзнака","лордерон","генерал маркус джонатан","стормвінд","полеглі","третя війна"},ang={["class:Paladin"]="Багато хто з полеглих у столиці бився пліч-о-пліч із лицарями Срібної Длані; повертаючи їхні медалі, ви вшановуєте загиблих братів і сестер святого ордену.",["faction:Alliance"]="Повернути ці відзнаки Генералові Маркусу Джонатану — справа обов'язку й пам'яті про вояків, що віддали життя, захищаючи первісний Альянс.",["race:Human"]="Для людей Альянсу ці значки — урочисте нагадування про падіння найвеличнішого людського королівства, що пов'язує біженців у Стормвінді з полеглими родичами на півночі."},sec={{t="Знаки полеглих",b="Коли принц Артас повернувся, щоб спустошити Лордерон разом із Погибеллю, його велике військо було розбите й вирізане. Безліч вояків полягли, захищаючи Столичне місто й навколишні землі, і по них лишилося небагато — іржаві обладунки та закривавлена мідь. Ці давні відзнаки Альянсу належали чоловікам і жінкам, що стояли до кінця проти навали нежиті. Утоптана в землю й уламки руїн, кожна медаль — пам'ятка останнього, відчайдушного бою королівства."},{t="Гонець для вигнанців",b="Багато хто з уцілілих лордеронців утік на південь, за море, і осів біженцями в Стормвінді. Десятиліття союзу й спорідненості пов'язують два людські королівства, і чимало людей на півдні прагнуть нарешті дізнатися про долю зниклих рідних. Генерал Маркус Джонатан, командир міської варти Стормвінда, бере ці закривавлені відзнаки на зберігання, щоб пам'ять про північних оборонців жила, а їхні вцілілі родини змогли нарешті дізнатися, що з ними сталося."}},faq={{q="Що таке Закривавлені Відзнаки?",a="Це військові відзнаки, які носили солдати королівства Лордерон, що билися й полягли під прапором Альянсу в Третій війні.",al={"закривавлена відзнака","що за відзнака","переказ про відзнаку"}},{q="Де знаходять ці відзнаки?",a="Їх знаходять по всіх Руїнах Лордерона на Галявинах Тірісфалю, де захисники королівства дали Погибелі свій останній бій.",al={"де випадають відзнаки","місце відзнак","значки руїн лордерона"}},{q="Навіщо вони Генералові Маркусу Джонатану?",a="Генерал Маркус Джонатан відповідає за оборону Стормвінда, де нині живе безліч біженців із півночі. Він збирає ці реліквії, щоб ушанувати жертву воїнів Лордерона, а їхні живі родичі на півдні змогли нарешті відпустити минуле.",al={"хто такий маркус джонатан","навіщо віддавати стормвінду","відзнаки маркуса джонатана"}},{q="Чому солдати Лордерона носили відзнаки Альянсу?",a="Перший Альянс викувався в Лордероні за короля Теренаса Менетіла II, щоб розбити Стару Орду. Лордерон був серцем і проводирем Альянсу Лордерона в Другій і Третій війнах.",al={"герб альянсу лордерона","значок альянсу лордерона"}},{q="Що сталося із солдатами, які носили ці відзнаки?",a="Вони загинули в Третій війні, коли принц Артас Менетіл зрадив королівство, убив свого батька й наслав на столицю Погибель.",al={"що вбило солдатів","доля солдатів лордерона"}},{q="Чи живі ще родичі цих солдатів?",a="Так. Тисячі мешканців і солдатів утекли з Лордерона під час чуми й вторгнення Погибелі, і зрештою знайшли прихисток у королівстві Стормвінд.",al={"біженці лордерона у стормвінді","хто сумує за солдатами"}}},fp="17,264,20.502.0,26.468.0,32.144.0,32.145.0,43.250.0,55.203.0,52.161.0,51.158.0"}
P.entries["quest:952"] = {n="Гай Прадавніх",s="«Гай Прадавніх» — завдання Альянсу на доставку, що веде шукачів пригод із Дарнасуса через море на Темне Узбережжя. На доручення Архідруїда Фандрала Стаґгелма гонець несе листа Ону — шанованому Древу Знань, що живе на південь від Обердайна.",h="«Гай Прадавніх» — завдання Альянсу на доставку, що веде шукачів пригод із Дарнасуса через море на Темне...",kw={"гай прадавніх","ону","древо знань","фандрал стаґгелм","темне узбережжя","обердайн","гіпогриф"},ang={["class:Druid"]="Листування між Архідруїдом у Дарнасусі та Ону показує молодим друїдам, як різняться вдачі старійшин Кола Кенарія: напористість Стаґгелма — і тихе терпіння Древа Знань.",["faction:Alliance"]="Для звитяжців Альянсу, що завершують справи в Дарнасусі, ця доставка — ранній привід відкрити шляхи гіпогрифів і дослідити прибережні землі Темного Узбережжя.",["race:NightElf"]="Це завдання — природний перехід із захищеної колиски Тельдрассилу до ширших диких просторів материкового Калімдору; воно підкреслює філософську відмінність між Фандралом Стаґгелмом і вченням Малфуріона Стормрейджа."},sec={{t="Прощання з гіллям",b="Допомігши в справах, пов'язаних із Галявиною Оракула на вершині Тельдрассилу, шукачі пригод раптом отримують від Архідруїда Фандрала Стаґгелма різкий наказ послужити далі. Стаґгелм не терпить, коли руки сидять без діла, тож доручає посланцеві перенести нагальну депешу через море до прадавніх лісів Темного Узбережжя й велить вирушити з міста на гіпогрифі."},{t="Два різні терпіння",b="Діставшись Темного Узбережжя й рушивши на південь від Обердайна до Гаю Прадавніх, посланець передає лист Ону. Високе Древо Знань приймає послання в тихій задумі й ледь помітно зауважує невгамовне нетерпіння Стаґгелма. Для Ону та прадавніх хранителів лісу все відбувається у свій час — це спокійна, незмінна мудрість, яку втілював шан'до Малфуріон Стормрейдж і якої Стаґгелмові явно бракує."}},faq={{q="Хто дає завдання «Гай Прадавніх»?",a="Завдання дає Архідруїд Фандрал Стаґгелм у Ценаріонському Анклаві Дарнасуса, після того як ви виконаєте його попереднє доручення, пов'язане з Галявиною Оракула.",al={"хто дає гай прадавніх","видавець гаю прадавніх","завдання фандрала стаґгелма"}},{q="Де Гай Прадавніх?",a="Гай Прадавніх — на материку, на Темному Узбережжі, просто на південь від портового Обердайна.",al={"місце гаю прадавніх","де гай прадавніх","місце ону"}},{q="Хто такий Ону?",a="Ону — мудре й шановане Древо Знань, що мешкає на Темному Узбережжі. Як захисник і літописець природної мудрості, він листується з друїдським проводом Дарнасуса.",al={"хто такий ону","ону темне узбережжя","прадавній знань ону"}},{q="Як дістатися з Тельдрассила на Темне Узбережжя?",a="Зазвичай мандрівники летять на гіпогрифі з Дарнасуса до Селища Рут'теран, а звідти — через воду до портового поселення Обердайн на Темному Узбережжі.",al={"як дістатися темного узбережжя","подорож до оберіжина","гіпогриф на темне узбережжя"}},{q="Чому Ону згадує Шан'до Стормрейджа?",a="Отримавши послання, Ону зауважує неспокійну квапливість Архідруїда Стаґгелма. Він міркує, що ліс живе у власному ритмі, — і цю позачасову терплячість розумів і шанував Шан'до Малфуріон Стормрейдж.",al={"чому ону згадує шан'до","коментар ону про малфуріона","згадка шан'до стормрейджа"}},{q="Які завдання йдуть перед цим?",a="Це завдання — останній крок короткого ланцюжка з трьох частин: він починається із «Зачарованого гаю», далі йде «Тельдрассил», а тоді вас відправляють на Темне Узбережжя.",al={"передумови гаю прадавніх","ланцюжок гаю прадавніх","завдання перед ону"}}},fp="21,265,18.383.0,22.447.0,43.149.0,43.118.0,11.183.0,43.178.0,39.210.0,33.162.0"}
P.entries["quest:953"] = {n="Падіння Амет'Арана",s="Вартова Тиша Мунблейд доручає шукачам пригод дослідити примарні руїни Амет'Арана на Темному Узбережжі й прочитати давні кам'яні скрижалі. Ці написи розповідають про трагедію й руйнування, що спіткали місто Високородних під час Розколу. Зібрані знання призначені для Кола Прадавніх в Обердайні — так повертається історія, здебільшого втрачена під час Війни Прадавніх.",h="Вартова Тиша Мунблейд доручає шукачам пригод дослідити примарні руїни Амет'Арана на Темному Узбережжі й...",kw={"падіння амет'арана","вартова тиша мунблейд","амет'аран","скрижалі","високородні","коло прадавніх"},ang={["class:Mage"]="Скрижалі дають тверезий погляд на вершини ельфійського чаклунства доби до Розколу — і на жахливу руїну, що настала, коли ця сила вийшла з-під контролю.",["faction:Alliance"]="Допомагаючи Вартовим зберегти історію Темного Узбережжя, ви бережете важливі знання для провідників нічних ельфів, що ведуть Альянс у Калімдорі.",["race:NightElf"]="Руїни Амет'Арана — похмуре нагадування про пиху ваших предків за часів королеви Азшари й про катастрофічні наслідки неприборканого тайного чаклунства."},sec={{t="Відлуння Високородних",b="Задовго до того, як узбережжя розкололося на імлисті простори Темного Узбережжя, Амет'Аран був квітучим поселенням, де добірні чаклуни королеви Азшари практикували могутню тайну магію. Після катастрофічного знищення Колодязя Вічності десять тисяч років тому від міста лишилися розбитий мармур і потріскані колони. Сьогодні тут досі блукають неспокійні, змучені духи Високородних, що загинули, коли їхня золота доба розлетілася на друзки."},{t="Віднайдені літописи",b="Війна Прадавніх кинула цивілізацію нічних ельфів у хаотичну боротьбу за виживання, тож напрочуд мало письмових свідчень пережили Великий Розкол неушкодженими. Вартова Тиша Мунблейд сама намагалася обстежити руїни й знайшла дві великі різьблені скрижалі — «Пісню про Амет'Аран» і «Падіння Амет'Арана», — перш ніж примарні духи Високородних змусили її відступити. Прочитані написи донесуть історичну правду про давнє лихо до вчених Кола Прадавніх в Обердайні."}},faq={{q="Що таке Амет'Аран?",a="Амет'Аран — давні руїни нічних ельфів у центрі Темного Узбережжя. Десять тисяч років тому тут було місто, де шляхта Високородних королеви Азшари відкрито вивчала й опановувала могутню тайну магію, — аж доки воно не загинуло під час Великого Розколу.",al={"переказ про амет'аран","що було амет'араном","хто жив в амет'арані"}},{q="Чому в Амет'Арані привиди?",a="Неспокійні привиди, що блукають руїнами, — духи Високородних, які тут жили й загинули. Раптова жорстока катастрофа, що зруйнувала Колодязь Вічності й розколола Калімдор, прикувала їхні душі до руїн у вічних муках.",al={"чому в амет'арані привиди","привиди амет'арана","неспокійні високородні"}},{q="Хто така Вартова Тиша Мунблейд?",a="Вартова Тиша Мунблейд — нічна ельфійка з Вартових, що несе службу біля дороги на Темному Узбережжі. Їй доручено розвідувати давні місця й шукати втрачені історичні записи для Кола Прадавніх в Обердайні.",al={"тиша мунблейд","хто дає падіння амет'арана"}},{q="Чому Коло Прадавніх хоче, щоб ці таблиці прочитали?",a="Знищення Колодязя Вічності кинуло Калімдор у величезні потрясіння й стерло з лиця землі безліч бібліотек і пам'яток. Після Війни Прадавніх уціліло так мало письмових свідчень, що ці таблиці — рідкісна розповідь очевидців про Розкол з погляду Високородних.",al={"чому читати таблиці","таблиці кола прадавніх","значення пісні амет'арана"}},{q="Де таблиці?",a="Дві великі таблиці — «Пісня Амет'Арана» й «Падіння Амет'Арана» — викарбувані на кам'яних стелах серед зруйнованих дворів Амет'Арана, довкола яких блукають привиди колишніх мешканців міста.",al={"де таблиці","місця таблиць амет'арана","як читати амет'аран"}},{q="Що сталося з Високородними Амет'Арана під час Розколу?",a="Коли наприкінці Війни Прадавніх Колодязь Вічності вибухнув, страшні поштовхи й тайна віддача розірвали Калімдор на шматки. Амет'Аран обвалився, поховавши своїх мешканців, і їхні привиди досі блукають серед уламків.",al={"як упав амет'аран","знищення амет'арана"}}},fp="22,378,23.450.0,26.515.0,19.237.0,35.260.0,32.210.0,56.292.0,30.233.0,66.238.0"}
P.entries["quest:95314"] = {n="Той зелений еліксир з Тіньової Долини",s="Каролай Еніс із Брілла шукає здобич із покинутого поселення Тіньова Долина, схованого глибоко в усамітненому Шепітливому Лісі. До падіння королівства село було горезвісне тим, що гнало Шепітливий Еліксир із дивних місцевих трав — міцне питво, яке цінували на чорному ринку навіть після заборони в Лордероні.",h="Каролай Еніс із Брілла шукає здобич із покинутого поселення Тіньова Долина, схованого глибоко в усамітненому...",kw={"зелений еліксир","тіньова долина","шепітливий ліс","каролай еніс","шепітливий еліксир","прокляття"},ang={["class:Rogue"]="Шепітливий Еліксир здавна цінували нелегальні отруйники й пройдисвіти, що діяли поза увагою колишніх магістратів Лордерону.",["profession:Herbalism"]="Еліксир завдячує своєю силою особливим травам, що буяють лише під моторошним склепінням усамітненого Шепітливого Лісу.",["race:Undead"]="Для Відступників повернення забутих настоянок Лордерону служить і прибутковій торгівлі, і аптекарським експериментам у молодому Андерсіті."},sec={{t="Заборонене вариво",b="Задовго до Третьої війни й приходу Погибелі відлюдкуваті мешканці Тіньової Долини варили особливу суміш, відому як Шепітливий Еліксир. Виготовлене з рідкісних трав, що ростуть лише в Галявинах Тірісфалю, питво здобуло лиху славу по всій півночі Лордерону. Попри офіційну заборону в Столиці — стольному місті королівства, — його незвичайні властивості робили його жаданим для містиків, отруйників і аптекарів-практиків, готових обійти королівські укази."},{t="Руїни в Шепітливому Лісі",b="Тіньова Долина ховається глибоко в Шепітливому Лісі на заході Тірісфалю. Її мешканці здавна були замкнутим, недовірливим людом, що рідко вітав чужинців. Після вторгнення Погибелі поселення запалося в руїну, та серед уламків досі лежать забуті запаси витриманого зеленого еліксиру. Каролай Еніс працює з Брілла і, користуючись стійким попитом підпілля, платить шукачам пригод, готовим кинути виклик моторошній тиші лісу."},{t="Шепітливе прокляття",b="Каролай воліє відмахуватися від чуток як від простих забобонів, та Шепітливий Ліс має темну славу. Місцеві перекази твердять, що сама земля й коріння лісу отруєні стародавнім прокляттям, яке просочується просто в рослини, що їх збирали броварі Тіньової Долини. Хай яка залишкова злоба навідує покинуте сільце, вона мало вгамувала апетит далеких покупців на його розлиті в пляшки рештки."}},faq={{q="Що таке Тіньова Долина?",a="Тіньова Долина була відлюдним селом, захованим у Шепітливому Лісі на заході Галявин Тірісфалю. Її потайні мешканці цуралися чужих і славилися передусім тим, що виганяли рідкісні настоянки з місцевих диких рослин, — доки край не захопила Погибель.",al={"де тіньова долина","хто жив у тіньовій долині","село тіньова долина"}},{q="Що таке Шепітливий Еліксир?",a="Це міцний зелений напій, зварений з особливих трав Тірісфалю. Його дуже прагнули містики, отруйники й аптекарі, а в Столиці до падіння Лордерона він був заборонений.",al={"що робить еліксир","переказ про зелений еліксир","шепітливий еліксир"}},{q="Хто така Каролай Еніс?",a="Каролай Еніс — винахідлива мешканка Брілла з Відступників. Вона торгує цінними й забороненими дивовижами: здобуває незаконні реагенти, як-от еліксир Тіньової Долини, і продає їх зацікавленим покупцям по всьому краю.",al={"каролай еніс","хто дає зелений еліксир","видавець бріллу"}},{q="Чому еліксир заборонили в Столиці?",a="Причину не названо. Каролай каже лише, що еліксир у місті заборонили і що аптекарі, містики й отруйники все одно його шукали. Дехто вважає, що Шепітливий Ліс проклятий і що еліксир із його коріння несе те саме прокляття, але Каролай відкидає це як забобон і ніяк не пов'язує із забороною.",al={"чому еліксир заборонений","чи еліксир отрута"}},{q="Чому Шепітливий Ліс вважають небезпечним?",a="Відлюдний ліс на захід від Похоронного Подзвону загалом вважають моторошним і проклятим. Ті, хто туди забрідав, розповідають про глибоке зло й дивні лісові явища, які, за чутками, отруїли трави, що ростуть на його ґрунті.",al={"чи шепітливий ліс проклятий","переказ про шепітливий ліс"}},{q="Хто ці покупці, яким потрібен еліксир?",a="За словами Каролай Еніс, чимало покупців прагнуть дістати вцілілі довоєнні пляшки, але хто вони — вона не каже.",al={"хто купує еліксир","покупці каролай еніс"}}},fp="28,340,13.457.0,30.465.0,20.427.1,19.249.0,26.193.0,21.218.0,46.329.0,50.219.0,39.131.0"}
P.entries["quest:954"] = {n="Башал'Аран",s="Демонічні сатири й люті грелли, що кишать у давньому місті нічних ельфів Башал'Арані, не наближаються до однієї святині, залитої неземним синім сяйвом. Тундріс Віндвівер, старійшина Обердайна, посилає шукачів пригод з'ясувати таємницю цього недоторканого прихистку.",h="Демонічні сатири й люті грелли, що кишать у давньому місті нічних ельфів Башал'Арані, не наближаються до...",kw={"башал'аран","астеріон","тундріс віндвівер","сатири","грелли","примара"},ang={["faction:Alliance"]="Розвідники Обердайна покладаються на мандрівників Альянсу, щоб проникати в спірні руїни Темного Узбережжя й знешкоджувати демонічні загрози, перш ніж ті дістануться узбережжя.",["race:NightElf"]="Башал'Аран — сумне нагадування про втрачене під час Розколу: тут примари ваших давніх родичів досі несуть самотню варту проти демонічної порчі, що підступає."},sec={{t="Маяк серед руїн",b="Колись Башал'Аран був славним поселенням давньої імперії калдореїв, але його розбитий мармур і зарослі арки тепер кишать демонічною скверною. Спотворені сатири й зіпсовані грелли жадібно живляться залишками магічних енергій руїн, і їхня злоба зростає з кожним днем. Та попри їхнє хиже панування, Тундріс Віндвівер з Обердайна помітив цікаву дивину: на західному урвищі серед руїн стоїть святиня, над якою горить примарне синє сяйво, і жоден демон до неї не наближається."},{t="Поранена примара",b="Прорвавшись крізь демонічні дозори до піднесеної святині, мандрівник переконується, що синє світло — не природне явище. Воно йде від Астеріона — давнього духа, чия варта тривала століттями самотності. Оточена завиванням звірів і мерзенними потворами, втомлена примара радіє навіть мандрівному незнайомцеві як перепочинку від десятиліть ізоляції."}},faq={{q="Де блакитне сяйво?",a="Блакитне сяйво світиться на невеликій кручі на західному краю руїн Башал'Арана, трохи на схід від Обердайна на Темному Узбережжі. Воно трохи здіймається над довколишніми мурами, що розсипаються.",al={"де блакитне сяйво","де астеріон","місце святилища башал'аран"}},{q="Чому сатири уникають святилища?",a="Поки що цього ніхто не знає. Святилище огортає дивне блакитне сяйво, і демонічні сатири та грелли, що кишать у руїнах, до нього не підходять. Тундріс Віндвівер посилає вас з'ясувати, звідки береться це сяйво.",al={"чому демони бояться","чому сатири тримаються осторонь"}},{q="Хто дає це завдання?",a="Тундріс Віндвівер — друїд нічних ельфів і старійшина Обердайна — дає завдання, помітивши неприродні рухи демонів у східних руїнах.",al={"хто дає завдання","видавець","місце тандріса віндвівера"}},{q="Що таке Башал'Аран?",a="Башал'Аран — давні руїни калдореїв у лісах Темного Узбережжя. Сплюндровані під час прадавнього Розколу, вони кишать магічними паразитами, греллами й сатирами, що прагнуть поживитися приспаними силами ліній сили.",al={"що сталося з башал'араном","історія башал'арана"}}},fp="11,275,21.501.0,17.354.1,31.197.0,35.204.0,28.159.0,20.223.0"}
P.entries["quest:955"] = {n="Башал'Аран",s="Астеріон, сумний привид Високородного, що блукає давніми руїнами Башал'Арана, шукає способу зняти магію скування, яка прив'язує його примарну подобу. Вірячи, що пустотливі місцеві грелли торкалися печаті, що його тримає, він доручає мандрівникам зібрати їхні сережки, щоб простежити залишкове відлуння її магії.",h="Астеріон, сумний привид Високородного, що блукає давніми руїнами Башал'Арана, шукає способу зняти магію...",kw={"башал'аран","астеріон","сережка грелла","грелли","печать","високородні"},ang={["class:Mage"]="Метод Астеріона — простежувати залишкові магічні випромінювання за зачарованими дрібничками — відбиває давні практики тайного віщування Високородних.",["faction:Alliance"]="Очищаючи околиці Башал'Арана від безладних греллів, ви допомагаєте Альянсу вгамувати підступну північ Темного Узбережжя.",["race:NightElf"]="Для калдореїв зустріч з Астеріоном — тверезе нагадування про давню цивілізацію, що загинула під час Розколу й лишила змучені душі прикутими до руїн на тисячоліття."},sec={{t="Мука, що триває століттями",b="Серед розбитого мармуру Башал'Арана перебуває Астеріон — давній дух нічного ельфа, що століттями терпить ув'язнення. Застряглий між життям і справжньою смертю, він животіє в болісному чеканні під склепінням лісів Темного Узбережжя. Прикутий до зруйнованого поселення тайним ремеслом, Астеріон не має змоги сам скинути кайдани, а його розум знесилили незліченні роки самотності й відчаю."},{t="Сліди в нетрях",b="Астеріон підозрює, що ключ до його звільнення — давня печать, схована десь у руїнах. Сам він не може прочісувати хащі й завали, але дикі грелли, що заполонили Башал'Аран, постійно нишпорять і крадуть дрібнички. Астеріон просить мандрівників зібрати сережки, які носять ці істоти, щоб прочитати залишкові магічні відбитки на цяцьках і знайти печать, що тримає його душу в муках."}},faq={{q="Хто такий Астеріон?",a="Астеріон — давній привид нічного ельфа, прикутий до руїн Башал'Арана на Темному Узбережжі. Століттями ув'язнений містичною печаткою, він у муках спостерігав, як минають епохи, і прагнув звільнитися зі свого примарного стану.",al={"переказ про астеріона","хто привид у башал'арані","видавець астеріон"}},{q="Навіщо Астеріонові сережки греллів?",a="Грелли — горезвісні збирачі, що тягнуть до себе блискучі дрібнички й прикраси. Астеріон вважає, що ці створіння торкалися магічної печатки, яка його тримає, тож на їхніх сережках може лишитися досить магічних слідів, щоб допомогти її відшукати.",al={"навіщо сережки греллів","призначення сережок греллів","завдання сережок темного узбережжя"}},{q="Що таке Башал'Аран?",a="Башал'Аран — давні руїни нічних ельфів на лісистому узбережжі Темного Узбережжя, що сягають часів до Великого Розколу. Тепер тут кишать дикі грелли, сатири й примарні рештки давно полеглих мешканців.",al={"що таке башал'аран","історія башал'арана","руїни башал'арана"}},{q="Що буде, коли сережки зібрано?",a="Астеріон оглядає сережки й відчуває: хоч самої печатки в греллів немає, вони торкалися її, як на його мірки, порівняно недавно. Цей слід дає йому змогу звузити пошуки в межах руїн.",al={"що показують сережки","чи у греллів була печатка","результат сережок греллів"}},{q="Чому Астеріон тут ув'язнений?",a="Астеріона прикувала до Башал'Арана давня магічна печатка, створена багато століть тому. Ці чари тримають його дух біля руїн і не дають відійти до мирного спочинку.",al={"хто зв'язав астеріона","як зв'язаний астеріон","печатка астеріона"}},{q="Хто такі грелли?",a="Грелли — дрібні злостиві лісові створіння, що водяться в лісах Калімдору. Вони славляться пустотливою вдачею, гострими кігтями й любов'ю до дрібничок, часто кишать у старих руїнах і нападають на перехожих.",al={"що таке грелл","переказ про греллів","грелли темного узбережжя"}}},fp="11,315,23.421.0,18.442.0,16.219.0,38.232.0,20.222.0,43.236.1,29.199.0,16.210.0"}
P.entries["quest:956"] = {n="Башал'Аран",s="Астеріон, дух нічного ельфа, ув'язнений серед зруйнованих колон Башал'Арана, шукає реліквію, що прив'язує його до цього світу. Відчувши серед місцевих греллів сліди магії своєї в'язниці, він посилає мандрівників полювати на сатирів, які ними верховодять, і повернути Стародавню Печатку з Місячного Каменю.",h="Астеріон, дух нічного ельфа, ув'язнений серед зруйнованих колон Башал'Арана, шукає реліквію, що прив'язує...",kw={"башал'аран","астеріон","стародавня печатка з місячного каменю","сатири","грелли","темне узбережжя"},ang={["class:Druid"]="Спотворений вплив сатирів і далі отруює звірів Темного Узбережжя й тривожить давніх духів, які мали б мирно спочивати в колообігу природи.",["faction:Alliance"]="Очищаючи руїни Темного Узбережжя від порчі сатирів, ви убезпечуєте північне узбережжя Калімдору й допомагаєте калдореям упокоїти своє трагічне минуле.",["race:NightElf"]="Башал'Аран — сумне нагадування про давнє минуле вашого народу: предки досі прикуті до землі сатирами, що втілюють демонічну зраду часів Розколу."},sec={{t="В'язниця з давнього каменю",b="Уже понад тисячу років дух Астеріона прикутий до занепалих руїн Башал'Арана. Навколишні мармурові колони — непохитна клітка, яку не здатні зламати ні його згасаюча духовна сила, ні давня магія. Прив'язаний проклятою реліквією, він століттями вдивляється в оповиті імлою крони Темного Узбережжя й гадає, чи не принесе йому звільнення хоч би вивітрювання каменю довкола."},{t="Сатири й Печатка з Місячного Каменю",b="Виявивши, що сусідні грелли несли сліди магії, яка тримає його в полоні, Астеріон дійшов висновку, що джерело чарів потрапило до рук сатирів, які верховодять цими безладними істотами. Блукаючи давніми гаями, ці демонічні нічні ельфи пильно тримають Стародавню Печатку з Місячного Каменю. Повернути цей талісман — вирішальний крок, щоб зламати незримі ґрати, які прив'язують Астеріона до його святині."}},faq={{q="Хто такий Астеріон?",a="Астеріон — давній привид нічного ельфа, ув'язнений у руїнах Башал'Арана. Скутий прадавньою магією, він понад тисячу років пробув між колонами святилища, не маючи змоги ні відійти у вічність, ні вийти за межі своєї кам'яної в'язниці.",al={"хто такий астеріон","переказ про астеріона","привид у башал'арані"}},{q="Чому Стародавня Печатка з Місячного Каменю в сатирів?",a="Сатири верховодять дикими греллами, що кишать на півночі Темного Узбережжя. Оскільки на греллах були сліди чарів ув'язнення, Астеріон зрозумів, що їхні підступні володарі-сатири заволоділи Стародавньою Печаткою з Місячного Каменю, щоб тримати місцевих духів у муках і на прив'язі.",al={"чому печатка в сатирів","печатка з місячного каменю сатирів","стародавня печатка"}},{q="Що буде, коли печатку повернуто?",a="Астеріон бере в руки ту саму реліквію, що століттями тримала його в неволі. Здобути Стародавню Печатку з Місячного Каменю — передостанній крок до його звільнення: тепер печатку можна розбити, і він нарешті знову вільно ходитиме лісами.",al={"що робить печатка","повернення печатки"}},{q="Що таке Башал'Аран?",a="Башал'Аран — давні руїни нічних ельфів на оповитих туманом берегах півночі Темного Узбережжя. Колись тут було розкішне поселення чи священна обитель, а тепер — руїни, де кишать грелли, сатири й ув'язнені духи давньої доби.",al={"переказ про башал'аран","що таке башал'аран"}},{q="Як довго Астеріон тут ув'язнений?",a="Астеріон ув'язнений понад тисячу років. Не маючи ні фізичних засобів, ні магії, щоб зруйнувати бар'єр, він мусив чекати крізь століття, гадаючи, чи звільниться колись.",al={"вік астеріона","як довго в пастці"}},{q="Чи може Астеріон просто піти зі святилища?",a="Ні. Стародавня Печатка з Місячного Каменю підтримує довкола святилища надприродний бар'єр. Кам'яні колони стають непроникною кліткою, що не дає його примарній постаті вийти за їхні межі.",al={"чи астеріон може піти","чому привид у пастці"}}},fp="11,291,25.425.0,29.449.0,16.239.0,50.265.0,40.232.1,20.235.0,40.201.0,46.187.0"}
P.entries["quest:957"] = {n="Башал'Аран",s="Це завдання доручає шукачам пригод допомогти ув'язненому духові Астеріона в руїнах Башал'Арана. Віднісши його печать скування на південь, до руїн-сестер Амет'Арана, вони намагаються розбити його давні кайдани.",h="Це завдання доручає шукачам пригод допомогти ув'язненому духові Астеріона в руїнах Башал'Арана.",kw={"башал'аран","астеріон","амет'аран","стародавня печатка з місячного каменю","атрікус","високородні"},ang={["class:Mage"]="Тривкі чари, що сковували Астеріона, і вцілілий вогонь Амет'Арана дають уявлення про сиру тайну силу, якою володіли давні чаклуни Високородних.",["faction:Alliance"]="Знімаючи давні прокляття на Темному Узбережжі, ви убезпечуєте кордони для нових поселень нічних ельфів, що розходяться від Обердайна.",["race:NightElf"]="Для нічних ельфів сучасного Калімдору звільнення Астеріона — тверезе зіткнення з минулим їхнього народу до Розколу й зі спадковою порчею знаті Високородних королеви Азшари."},sec={{t="В'язниця давнього чаклунства",b="Дух Астеріона тисячоліттями перебуває в Башал'Арані, прикутий у смерті Стародавньою Печаткою з Місячного Каменю. Викувану могутнім чаклунством касти Високородних ще до Великого Розколу, печатку не розбити звичайною силою. Щоб її знищити, потрібна особлива магія давнього полум'я, що досі жевріє серед поваленого каміння Амет'Арана на півдні."},{t="Руїни-близнюки Темного Узбережжя",b="Башал'Аран і Амет'Аран колись були квітучими поселеннями-сестрами цивілізації калдореїв — тоді, коли правила королева Азшара, а Колодязь Вічності ще був опорою їхньої імперії. Сьогодні обидва місця — зарослі, примарні руїни, сповнені неупокоєних привидів і мінливих тайних енергій. У кам'яній альтанці Амет'Арана містична жаровня з блакитним вогнем — єдина сила, здатна поглинути реліквію, що сковує Астеріона."},{t="Пробудження помсти",b="Коли печатку знищено, Астеріон нарешті вільний і дивиться на розколотий Калімдор, що так змінився від золотої доби, яку він пам'ятає. Та свобода не приносить йому спокою. Відчувши, що його колишній господар і тюремник, Високородний Атрікус, досі живий, Астеріон швидко обертає давній відчай на холодну, пекучу жагу помсти."}},faq={{q="Хто такий Астеріон?",a="Астеріон — дух нічного ельфа, ув'язнений у руїнах Башал'Арана. Він живе з часів правління королеви Азшари, десять тисяч років тому, і до зруйнованого міста його прикував колишній володар з-поміж Високородних.",al={"астеріон","хто привид","астеріон неігровий персонаж"}},{q="Де знищити Стародавню Печатку з Місячного Каменю?",a="Печатку треба віднести на південь, до Амет'Арана — руїн-близнюка Башал'Арана. Шукайте кам'яну альтанку, під якою стоїть велика кубічна жаровня з давнім зеленкувато-блакитним магічним вогнем.",al={"де полум'я","місце стародавнього полум'я","знищити печатку"}},{q="Що пов'язує Башал'Аран і Амет'Аран?",a="Це були міста-побратими давньої імперії нічних ельфів до Розколу. Обидва загинули десять тисяч років тому, лишивши по собі колони, де блукають привиди, залишкову тайну енергію й неспокійних духів.",al={"близнючі руїни","зв'язок з амет'араном","башал'аран і амет'аран"}},{q="Хто ув'язнив Астеріона?",a="Астеріон каже, що печать, яка його сковує, створив один із наймогутніших Високородних. Більше про його колишнього володаря розкриває ланцюжок завдань.",al={"хто ув'язнив астеріона","хто такий атрікус","господар астеріона"}},{q="Яку епоху пам'ятає Астеріон?",a="Востаннє Астеріон ходив світом, коли ще існував первісний Колодязь Вічності, імперією правила королева Азшара, а шляхта Високородних тримала свої пишні двори — до Розколу.",al={"минуле астеріона","епоха колодязя вічності","вік астеріона"}},{q="Чи звільнення дає духові Астеріона спокій?",a="Знищення печаті має зруйнувати в'язницю Астеріона. Як він відгукнеться на свободу, з'ясується, коли ви повернетеся до нього.",al={"чи астеріон знайде спокій","що з астеріоном","астеріон після звільнення"}}},fp="11,224,27.384.0,23.435.0,17.344.1,16.204.0,46.188.0,60.212.0,24.144.1,32.188.0,45.116.1"}
P.entries["quest:959"] = {n="Клопіт у доках",s="Кранівник Бігглфаз спричинив незграбну аварію з вантажем у доках Раджета, і дрібний бешкетник на прізвисько Скажений Маґґліш скористався нагодою, щоб поцупити безцінну пляшку витриманого трунку. Цей 99-річний портвейн, надісланий Бароном Ревілґазом просто Ґазлоу, треба повернути з темряви Печер Стогонів, перш ніж начальник доків звільнить недбалого кранівника.",h="Кранівник Бігглфаз спричинив незграбну аварію з вантажем у доках Раджета, і дрібний бешкетник на прізвисько...",kw={"клопіт у доках","кранівник бігглфаз","скажений маґґліш","99-річний портвейн","раджет","печери стогонів"},ang={["class:Rogue"]="Полювання на Скаженого Маґґліша — вправа з розпізнавання недбалого маскування: злодій покладається на найпростішу скритність у закамарках печер, щоб лишитися непоміченим.",["faction:Alliance"]="Хоч справа й відбувається глибоко в Пустках, де панує Орда, добрі стосунки з портовиками картелю Стімвідл гарантують безпечний прохід нейтральними водами.",["faction:Horde"]="Допомагаючи докерам Раджета, ви підтримуєте злагоджену роботу головного нейтрального порту, що з'єднує Калімдор зі Східними Королівствами."},sec={{t="Незграбна халепа",b="Раджет живе постійною морською торгівлею з Буті Бей через Велике Море, але гоблінська вправність часом тріщить під самою вагою вантажів. Коли в порт прибула незвично величезна ранкова партія, Кранівник Бігглфаз спробував зрізати кути, щоб швидше розвантажитися. Піднявши значно більше, ніж міг витримати його кран, він упустив увесь вантаж на причали. У метушні, що зчинилася, місцевий шкідник на прізвисько Скажений Маґґліш скористався розсипаними ящиками, вихопив одну цінну пляшку трунку й утік углиб суходолу."},{t="Дипломатичний трунок",b="Викрадений вантаж був куди ціннішим за звичайну порцію портового пійла. Ця пляшка 99-річного портвейну — особистий дипломатичний дарунок від Барона Ревілґаза, сумнозвісного володаря Буті Бей з Нападників Чорної Води, Ґазлоу — головному інженерові й наглядачеві Раджета. Втрата такого розкішного подарунка загрожує осоромити Бігглфаза й розлютити обох торгових магнатів. Опинившись під загрозою втратити роботу, а то й гірше, Бігглфаз вистежив злодія до зловісного входу в Печери Стогонів, але страх не дав йому піти за Маґґлішем усередину."},{t="Печерна схованка",b="Скажений Маґґліш не наважився заглибитися в спотворений світ снів самого підземелля — він сховався в розлогих вогких природних тунелях перед внутрішнім входом. Покладаючись на незграбну скритність і темні ніші, Маґґліш крадеться підземними печерами, сподіваючись, що переслідувачі здадуться. Щоб повернути портвейн, треба викурити злодія із зовнішніх закутків, перш ніж трунок розкоркують чи розіб'ють."}},faq={{q="Чому ця пляшка портвейну така важлива?",a="99-Річний Портвейн — це не звичайний ґроґ, а розкішний особистий дарунок Барона Ревілґаза з Буті Бей для Ґазлоу, ватажка Раджета. Якщо пляшку втрачено через пригоду в доках, це може страшенно розлютити керівництво Раджета, а Кранівник Бігглфаз ризикує втратити свій хліб.",al={"чому біґґлфаз дбає","99-річний портвейн","чому вино важливе"}},{q="Хто такий Скажений Маґґліш?",a="Скажений Маґґліш — злодій і шибеник, що ошивається в Раджеті й не пропускає нагоди. Коли Бігглфаз упустив на причал величезний вантаж, Маґґліш схопив рідкісну пляшку портвейну й чкурнув просто в сусідні Печери Стогонів, щоб там сховатися.",al={"хто такий маґґліш","хто вкрав портвейн","переказ про скаженого маґґліша"}},{q="Чи треба заходити в підземелля Печери Стогонів, щоб знайти злодія?",a="Ні. Скажений Маґґліш ховається у звивистих загальнодоступних печерних ходах перед порталом підземелля. Він уміє трохи скрадатися й чаїться у верхніх бічних тунелях або біля затоплених залів, що ведуть до головного входу.",al={"чи маґґліш в підземеллі","де скажений маґґліш","знайти маґґліша"}},{q="Як вантаж розсипався?",a="З Буті Бей прибула величезна партія вантажу, і Кранівник Бігглфаз спробував вивантажити більше ящиків за раз, ніж міг витримати його механізм. Перевантажений кран упустив вантаж, і цінний крам розлетівся по доках Раджета.",al={"чому ящики впали","що зробив біґґлфаз","аварія крана раджет"}},{q="Що пов'язує Раджет і Буті Бей?",a="Обидва портові міста — важливі осередки картелю Стімвідл, пов'язані торгівлею й каперськими флотами. Між Бароном Ревілґазом на півдні й Ґазлоу в Пустках регулярно ходять торговельні вантажі й офіційні знаки ввічливості, що підтримують їхню спільну торговельну імперію.",al={"раджет і буті бей","порти стімвідл","ревілґаз і ґазлоу"}},{q="Чому Бігглфаз сам не повернув пляшку?",a="Бігглфаз гнався за злодієм аж до входу в Печери Стогонів, але моторошна слава й чудовиська підземного лабіринту так налякали гобліна, що він зупинився на порозі.",al={"чому гоблін не повернув","чому біґґлфаз припинив погоню"}}},fp="20,361,15.535.0,18.522.0,18.419.0,40.271.0,20.238.0,65.208.0,31.240.0,55.258.0,50.207.0"}
P.entries["quest:95999"] = {n="РОЗШУКУЄТЬСЯ: спопелювач Гар'ім",s="РОЗШУКУЄТЬСЯ: спопелювач Гар'ім — оголошення про нагороду, яке влада Лейкширу вивісила за ворожого орківського командира, що засів у Долині Рендера. Гар'ім очолює небезпечний загін заклиначів тіні й, за чутками, діє разом із кланом Блекрок, що утримує Фортецю Кам'яної Варти. Магістрат Соломон обіцяє щедру нагороду за доказ його загибелі.",h="РОЗШУКУЄТЬСЯ: спопелювач Гар'ім — оголошення про нагороду, яке влада Лейкширу вивісила за ворожого...",kw={"спопелювач гар'ім","розшукується","долина рендера","заклиначі тіні","магістрат соломон","лейкшир"},ang={["class:Mage"]="Гар'ім і його заклиначі тіні — спотворений прояв нищівної таємної й тіньової магії, на який треба швидко відповісти контрзаклинаннями.",["faction:Alliance"]="Знищивши спопелювача Гар'іма, ви безпосередньо захищаєте беззахисних мешканців Лейкширу від ватажка орківського наступу та його надзвичайно небезпечних заклиначів тіні."},sec={{t="Вогонь у Долині Рендера",b="Гори Редріджу стають дедалі небезпечнішими, відколи орки Блекрок виходять зі своїх гірських твердинь. У Долині Рендера спопелювач Гар'ім очолює наступ і разом із вірними заклиначами тіні веде вперед темне чаклунство. Міська варта виснажена, війська корони здебільшого відсутні, тож Магістрат Соломон звернувся до вільних найманців, щоб знищити Гар'іма, який, за чутками, діє разом із Блекрок із Фортеці Кам'яної Варти."},{t="Доказ загибелі",b="Гар'ім славиться руйнівною магією й владою над заклиначами, що плетуть тіні. Щоб отримати нагороду містечка, мисливцям за головами доведеться заглибитися на ворожу територію, здолати спопелювача й принести його зламаний посох до ратуші Лейкширу як речовий доказ того, що загрозу знищено."}},faq={{q="Хто такий спопелювач Гар'ім?",a="Спопелювач Гар'ім — орк-воєвода й заклинач, що очолює вторгнення в Долині Рендера. Кажуть, він діє разом з орками Блекрок із Фортеці Кам'яної Варти й командує небезпечними тіньовими заклиначами.",al={"хто спопелювач гар'ім","гар'ім","спопелювач гар'ім хто"}},{q="Де знайти спопелювача Гар'іма?",a="Гар'ім отаборився серед ворожих орків у Долині Рендера на південному сході Гір Редріджу.",al={"місце гар'іма","де гар'ім","місце долини різників"}},{q="Хто оголосив нагороду за Гар'іма?",a="Нагороду від імені Лейкшира оголосив Магістрат Соломон, який відчайдушно прагне зупинити набіги орків, що насідають на обложене містечко.",al={"хто оголосив нагороду","нагорода соломона"}},{q="Який доказ потрібен, щоб отримати нагороду?",a="Перш ніж виплатити нагороду, Магістрат Соломон вимагає Зламаний Посох Спопелювача Гар’іма — доказ загибелі заклинача.",al={"доказ гар'іма","зламаний посох предмет"}},{q="Чим загрожують Гар'ім і його прибічники?",a="Гар'ім володіє смертоносною руйнівною магією, а поруч із ним — тіньові заклиначі. Їхня присутність зміцнює позиції клану Блекрок у Редріджі, і, якщо їх не зупинити, вони можуть знищити Лейкшир.",al={"здібності гар'іма","тіньові чародії реджридж"}},{q="Чому Лейкшир покладається на нагороди, а не на армію Стормвінда?",a="Серед політичних чвар і браку військ Стормвінд здебільшого полишив Редрідж боронитися самотужки, тож Магістрат Соломон мусить наймати охочих шукачів пригод, щоб ті знищували ватажків ворога.",al={"чому лейкшир покладається на нагороди","де армія стормвінда"}}},fp="26,345,25.467.0,15.302.0,26.204.0,38.125.0,33.149.0,43.132.0,45.192.0,68.180.0"}
P.entries["quest:96"] = {n="Поклик води",s="Це завдання — вінець виснажливого паломництва шамана до злагоди зі стихією води. Повернувши очищену Скалку Води до Іслен Вотерсір на узбережжі Пусток, новачок доводить свою злагоду з цілющими енергіями й здобуває Тотем Води.",h="Це завдання — вінець виснажливого паломництва шамана до злагоди зі стихією води.",kw={"поклик води","скалка води","тотем води","іслен вотерсір","малий прояв води","шаман"},ang={["class:Shaman"]="Цей обряд посвяти дає вам Тотем Води, що відкриває цілющі джерела й очисні фонтани — головне у вашій ролі духовного цілителя.",["faction:Horde"]="Випробування показує духовну відповідальність Орди: воно закликає молодих шаманів очищати сплюндровані землі і в Калімдорі, і у Східних Королівствах."},sec={{t="Довгий шлях додому",b="Пошуки води вимагають від новачка перетнути континенти, аж до сплюндрованих берегів Срібнолісся, щоб віч-на-віч зустрітися зі скверною. Вода — це життя, гнучкість і зцілення, але її податлива природа робить її особливо вразливою до помори й темної магії. Постоявши перед Малим Проявом Води й побачивши чисту стихійну волю, новачок отримує особливий дар — Скалку Води. Нести цей знак через море назад у випалені сонцем Пустки — відчутне нагадування, що вода поєднує всі далекі куточки світу."},{t="Тотем Води",b="Отримавши скалку, Іслен Вотерсір не просто оглядає доказ виконаного завдання — вона перевіряє, чи збагнув шаман рівновагу між збереженням і оновленням. Гниль, що наступає з Лордерону, часто приховує тихі перемоги, але навіть одне очищене джерело важить для духів. Визнавши цю пожертву, Іслен вручає шаманові Тотем Води. Це відчутне вогнище сили дає змогу спрямовувати в смертний світ очисні й цілющі потоки, що відновлюють ману, і закріплює вічне єднання шамана з припливами."}},faq={{q="Що таке Скалка Води?",a="Скалка Води — зосереджений стихійний уламок, який дарує Малий Прояв Води. Вона засвідчує, що новачок збагнув роль води як життєдайної сили й зумів дати відсіч скверні, що загрожує стихійним потокам.",al={"скалка води","уламок води","що за скалка"}},{q="Куди віднести Скалку Води?",a="Скалку треба повернути Іслен Вотерсір, що мешкає у відлюдному таборі на східному узбережжі Пусток, на південь від Раджета.",al={"куди віднести","хто отримає скалку","місце здачі"}},{q="Що я отримаю за це випробування?",a="За це останнє випробування шаман отримує свій Тотем Води — незамінний провідник, щоб закликати тотеми стихії води для зцілення й відновлювальної магії.",al={"нагорода завдання","нагорода тотем","що я отримаю"}},{q="Чому випробування відбувалося в Срібноліссі?",a="Води Срібнолісся тяжко уражені чумою й тіньовою магією. Відправивши шамана туди, наставники змушували його побачити, яка вразлива вода, і самому захистити її природну чистоту від тління.",al={"чому срібнолісся","чому східні королівства","вода срібнолісся"}},{q="Хто така Іслен Вотерсір?",a="Іслен Вотерсір — шаманка-тауренка, що живе на східному узбережжі Пусток. Вона наглядає за шаманськими випробуваннями води й навчає новачків єднатися з духами води й опановувати мистецтво зцілення.",al={"іслен","хто така іслен вотерсір"}}},fp="13,274,19.595.0,15.570.0,27.269.0,35.143.0,44.171.0,43.205.0,23.208.0"}
P.entries["quest:960"] = {n="Ону медитує",s="Досліджуючи Глефу Володаря на півдні Темного Узбережжя, Древо Знань Ону поринає в глибокий транс, щоб осмислити дедалі більшу загрозу. Шукачі пригод, що загубили свій містичний флакон віщування, можуть звернутися до древа, зануреного в роздуми, й отримати новий. Його думки зосереджені на зловісному союзі та мотивах культу Молота Присмерку й зміїстих наг.",h="Досліджуючи Глефу Володаря на півдні Темного Узбережжя, Древо Знань Ону поринає в глибокий транс, щоб...",kw={"ону медитує","ону","древо знань","флакон віщування","глефа володаря","молот присмерку"},ang={["class:Druid"]="Друїдів пов'язує з Древами Знань глибокий природний зв'язок. Підтримка спілкування через обряди віщування відбиває спосіб, у який Коло Кенарія обстежує отруєні землі здалеку.",["faction:Alliance"]="Убезпечити Темне Узбережжя від культистів і морських загарбників украй важливо для мандрівників Альянсу, що подорожують між Тельдрассилом і Ашенвалем.",["race:NightElf"]="Як охоронці рівноваги Калімдору, нічні ельфи шанують Древа Знань на кшталт Ону й покладаються на їхню позачасову мудрість, щоб тлумачити збурення в нетрях Темного Узбережжя."},sec={{t="Розум у глибоких роздумах",b="Ону — Древо Знань, що вкоренилося в Гаю Прадавніх на Темному Узбережжі, — живе сховище історії Калімдору. Коли надходять зловісні звістки про темні розкопки біля Глефи Володаря, Ону звертає свою неосяжну свідомість углиб себе. Він зосереджено міркує, що могло привабити і фанатичних культистів Молота Присмерку, і підступних наг до закам'янілих решток давнього громаддя. Для шукачів пригод, що виконують його розвідку, він лишається надійною опорою й дає нові флакони віщування, якщо старі загубилися в нетрях."},{t="Віщування глибин",b="Щоб стежити за руїнами, не ризикуючи сам, Ону покладається на віщування, налаштоване на природу. Шукачам пригод довіряють флакон віщування, що має викликати чашу віщування просто на розкопках, щоб Ону міг спілкуватися здалеку. Дорога на південь через Темне Узбережжя небезпечна — повна ворожих звірів і дозорів культистів, — тож Ону передбачає халепи. Його транс — не безпробудний сон, а уважна варта: він охоче дає ще один флакон священної води, щоб розслідування біля Глефи Володаря тривало без затримок."}},faq={{q="Чому Ону медитує?",a="Ону — Древо Знань, що розмірковує над тривожною присутністю культу Молота Присмерку й наг біля Глефи Володаря. Медитуючи, він прагне збагнути їхні задуми й скерувати шукачів пригод, що досліджують це місце.",al={"чому ону медитує","транс ону","що робить ону"}},{q="Навіщо ця взаємодія?",a="Це запобіжник для гравців, що виконують завдання «Глефа Володаря». Якщо ви загубили, знищили чи завчасно використали Флакон Віщування, розмова з Ону, що медитує, дасть вам новий флакон, щоб ви змогли завершити обряд.",al={"загублений флакон віщування","отримати інший флакон","заміна ону"}},{q="Де Ону?",a="Ону вкоренився в Гаю Прадавніх у південно-центральній частині Темного Узбережжя, неподалік головної дороги.",al={"місце ону","де ону"}},{q="Що робити з Флаконом Віщування?",a="Віднесіть флакон до Глефи Володаря й скористайтеся ним, щоб створити чашу віщування. Тоді Ону зможе говорити з вами через чашу.",al={"як користуватися флаконом віщування","чаша віщування темне узбережжя","призначення флакона віщування"}},{q="Що таке Глефа Володаря?",a="Глефа Володаря — величезні давні розкопки на півдні Темного Узбережжя, де лежить колосальний скам'янілий череп забутої сутності, пронизаний велетенським клинком. Культисти й наги зібралися там із невідомою лихою метою.",al={"що таке глефа володаря","пам'ятка на півдні темного узбережжя"}},{q="Чи можуть гравці Орди говорити тут з Ону?",a="Ні. Ону — союзник лише нічних ельфів і Альянсу. Шукачі пригод з Орди, що потикаються до Гаю Прадавніх, побачать, що Ону та його охоронці ворожі або не бажають співпрацювати.",al={"чи ону лише для альянсу","орда і ону медитує"}}},fp="17,366,28.564.0,18.581.0,22.227.0,40.244.0,21.106.0,39.127.0,28.246.0,41.185.0"}
P.entries["quest:96047"] = {n="Табірна наука 101: перша допомога",s="Це завдання спрямовує медиків-новачків у Дун Мороґу розширити своє вміння виживати далі за прості бинти. Звернувшись до Тамнера Пола в Хараносі, шукачі пригод учаться збирати повноцінну Аптечку, щоб зберегти життя табірникам у полі.",h="Це завдання спрямовує медиків-новачків у Дун Мороґу розширити своє вміння виживати далі за прості бинти.",kw={"перша допомога","аптечка","табір","тамнер пол","харанос","виживання"},ang={["faction:Alliance"]="Новобранці Альянсу, що проходять вишкіл у замерзлому серці Каз Модану, рано засвоюють: самодостатність і польова медицина — життєво важливі навички для будь-якого військового чи дослідницького загону.",["race:Dwarf"]="Дворфійські горяни, патрулюючи високі засніжені перевали Дун Мороґу, покладаються на міцне, практичне спорядження, тож табірна аптечка — неодмінна річ для виживання.",["race:Gnome"]="Біженцям і гномським мандрівникам, що діють із Хараноса, дієва польова медицина безцінна, поки вони виживають поза втраченими залами Гномреґану."},sec={{t="Лікування ран у нетрях",b="Шукачі пригод, які наважуються на замерзлі простори Дун Мороґу, швидко з'ясовують, що лляні клапті й поспішні шви — лише початок медицини виживання. Справжнє виживання в нетрях часто залежить від заздалегідь підготованих запасів на місці відпочинку. Тих, хто виявляє хист до базового лікування, спрямовують до ремісничих наставників у Хараносі, які навчать перетворювати сирі медичні припаси на повні набори для виживання в таборі."},{t="Уроки Хараноса",b="У гамірному селищі Харанос Тамнер Пол передає практичні прийоми оснащення експедиційних стоянок припасами на випадок біди. Уміння зібрати належну польову аптечку гарантує, що весь загін зможе перев'язати рани й відновити сили разом біля вогнища, перш ніж знову вирушити в пронизливий холод."}},faq={{q="Навіщо це доручення?",a="Доручення скеровує щойно навчених польових цілителів до Тамнера Пола в Харанос, який учить виготовляти справні Аптечки для таборів шукачів пригод.",al={"навіщо табірна наука 101","що робить це завдання","мета табірної науки"}},{q="Хто такий Тамнер Пол?",a="Тамнер Пол — наставник у містечку Харанос у Дун Мороґу. Він навчає вправних знавців виживання виготовляти ремісниче спорядження, щоб покращити свої табори в нетрях.",al={"хто такий тамнер пол","місце тамнера пола","де тамнер пол"}},{q="Де відбувається навчання?",a="Навчання відбувається в Хараносі — головному поселенні в центрі Дун Мороґу, на південь від Айронфорджа.",al={"куди йти","місце табірної науки","перша допомога харанос"}},{q="Чому табірна аптечка важлива?",a="У суворих нетрях під час походів поранення — звична справа. Окрема Аптечка дає шукачам пригод на привалі все необхідне для лікування, щоб мандрівники могли перев'язати рани й безпечно відновитися між боями.",al={"що робить аптечка","навіщо аптечка","користь табірної аптечки"}},{q="Чи треба мати медичну підготовку, перш ніж іти до Тамнера Пола?",a="Так. Від шукачів пригод очікують, що вони вже знають основи Першої допомоги й мають базові навички в цьому ремеслі, — лише тоді Тамнер Пол навчить їх складніших табірних рецептів.",al={"вимоги табірної науки","чи потрібна перша допомога","чи потрібна медична підготовка"}},{q="Чи може будь-який шукач пригод узятися за це?",a="Будь-який шукач пригод може опанувати Першу допомогу, хай яке в нього покликання, тож табірна медицина — практична навичка для кожного мандрівника Дун Мороґу.",al={"чи будь-хто може","вимоги до класу","хто вивчить табірну першу допомогу"}}},fp="22,236,26.437.0,23.337.0,33.161.0,19.174.0,36.111.0,38.218.0,62.176.0,39.143.0"}
P.entries["quest:962"] = {n="Зміїцвіт",s="«Зміїцвіт» — завдання зі збирання від Аптекарки Замах, посланниці Королівського Аптекарського Товариства в Тандер Блафі. Замах шукає зразки рідкісної трави, що росте в підземних глибинах Печер Стогонів, щоб допомогти дослідженням Відступників.",h="«Зміїцвіт» — завдання зі збирання від Аптекарки Замах, посланниці Королівського Аптекарського Товариства в...",kw={"зміїцвіт","аптекарка замах","королівське аптекарське товариство","печери стогонів","узвишшя духів","відступники"},ang={["faction:Horde"]="Це завдання скріплює ранній робочий союз Андерсіті з племенами Калімдору, що діляться ресурсами й рідкісними реагентами через океан.",["profession:Herbalism"]="Спотворене довкілля Печер Стогонів плекає унікальну флору, якої більше ніде не знайти на випаленій сонцем поверхні Пусток.",["race:Tauren"]="Гостинність до аптекарів-Відступників на Узвишші Духів відбиває дух Орди, хоча їхня зацікавленість смертельними сумішами різко контрастує з традиційним зціленням землі.",["race:Undead"]="Добуваючи зміїцвіт, ви прямо підтримуєте алхімічні починання Королівського Аптекарського Товариства в Лордероні за наказом Темної Леді."},sec={{t="Очі аптекарів",b="На Узвишші Духів у Тандер Блафі Аптекарка Замах представляє Королівське Аптекарське Товариство з Андерсіті. Поки господарі-таурени дбають про духовну рівновагу й зцілення пораненої землі, увага Замах прикута до рідкісних і отруйних матеріалів. Виділивши зразок незвичайної рослини — зміїцвіту, вона прагне отримати його у великих обсягах, щоб просунути дослідження, яких вимагають Леді Сильвана Віндраннер і Відступники."},{t="Глибини печер",b="Зміїцвіт не росте під відкритим сонцем Пусток — він буяє у вогких, звивистих гротах Печер Стогонів. Він виростає у вологому підземному кліматі, спотвореному сплюндрованими Друїдами Ікла, тож дістатися до нього важко, а стережуть його люті змієві мешканці печер. Замах відверто визнає, що чимало розвідників, яких посилали раніше, не повернулися, тож далі збирати зміїцвіт доведеться загартованим шукачам пригод."}},faq={{q="Хто така Аптекарка Замах?",a="Аптекарка Замах — дослідниця Королівського Аптекарського Товариства з Андерсіті. Вона перебуває в Тандер Блафі на Узвишші Духів і підтримує зв'язок між алхіміками Відступників і рештою Калімдору.",al={"замах","переказ про аптекарку замах","хто дає зміїцвіт"}},{q="Навіщо Королівському Аптекарському Товариству Зміїцвіт?",a="Замах вважає, що ця трава, якщо очищати її у великих кількостях, має значний прихований хімічний потенціал. Товариство невтомно шукає по всьому Калімдору рідкісні сильнодійні рослини, що можуть стати в пригоді в алхімічних дослідах Відступників.",al={"навіщо зміїцвіт","дослідження трав відступників","призначення зміїцвіту"}},{q="Де росте Зміїцвіт?",a="Зміїцвіт росте лише в підземних глибинах Печер Стогонів — у вогких кам'яних коридорах і ходах, вимитих під північними Пустками.",al={"де росте зміїцвіт","місце зміїцвіту"}},{q="Чому попередні розвідники не повернулися?",a="Печери Стогонів кишать здичавілими звірами, рапторами й зіпсованими скверною Друїдами Ікла. Менш досвідчених збирачів, яких посилали в заплутані тунелі, швидко здолали хижі мешканці печер і їхні отруйні захисники.",al={"зниклі розвідники","розвідники замах","чи печери стенань небезпечні"}},{q="Чи схвалюють таурени дослідження Замах?",a="Таурени Тандер Блафа дали Відступникам прихисток зі співчуття й бажання їх зцілити, але алхімічні практики Королівського Аптекарського Товариства часто балансують на межі неприродних дослідів, що непокоїть традиційних шаманів і друїдів.",al={"реакція тауренів","аптекарі підйому духів"}},{q="Чи потрібне травництво, щоб збирати Зміїцвіт?",a="Ні. Хоч це й рослина, будь-який шукач пригод, що наважиться спуститися в глибини Печер Стогонів, може зірвати її просто з долівки печери без жодної підготовки з травництва.",al={"чи потрібне травництво","збирання зміїцвіту професія"}}},fp="12,259,22.448.0,25.436.0,24.230.0,56.226.0,29.188.0,37.240.0,42.259.0,54.188.0"}
P.entries["quest:963"] = {n="Заради вічного кохання",s="«Заради вічного кохання» — трагічне завдання, яке дає Сереллеан Вайтклоу в Обердайні. Переслідуваний спогадами про втрачену кохану, Анаю Донраннер, Сереллеан просить шукача пригод вирушити до розбитих руїн Амет'Арана й звільнити її неспокійний дух від вічної муки.",h="«Заради вічного кохання» — трагічне завдання, яке дає Сереллеан Вайтклоу в Обердайні.",kw={"заради вічного кохання","сереллеан вайтклоу","аная донраннер","амет'аран","обердайн","підвіска"},ang={["class:Druid"]="Доля Сереллеана відбиває особисту ціну, яку заплатили друїди, що поринули в тисячолітній сон поруч із шан'до Стормрейджем, — і прокинулися у світі, досі позначеному їхніми давніми втратами.",["faction:Alliance"]="Допомагаючи Сереллеанові, герої Альянсу зазирають у трагічні, тисячолітні життя своїх союзників — нічних ельфів, — що звикають до світу наяву.",["race:NightElf"]="Для нічних ельфів Темного Узбережжя допомога Сереллеанові — щемке нагадування про незагоєні шрами Великого Розколу й падіння їхніх давніх міст."},sec={{t="Сон, повний горя",b="Десять тисяч років тому, під час Війни Прадавніх, катастрофа довкола Колодязя Вічності розірвала давній Калімдор. Серед жертв було й місто Амет'Аран, де Сереллеан Вайтклоу втратив кохану, Анаю Донраннер. Убитий відчаєм, Сереллеан пішов за шан'до Малфуріоном Стормрейджем у довгу сплячку друїдів, сподіваючись, що тисячоліття мандрів Смарагдовим Сном угамують його зболене серце. Натомість смуток не відпускав і йшов за ним крізь віки."},{t="Привид Амет'Арана",b="Прокинувшись нещодавно, Сереллеан блукав Темним Узбережжям у заціпенінні, доки ноги не привели його назад до сумних руїн Амет'Арана. Там, серед давнього каміння, він побачив змучений привид Анаї. Не в змозі підняти зброю на жінку, яку кохав, він благає мандрівників знищити її зболену подобу, забрати її підвіску й нарешті дати її неспокійній душі спокій."},{t="Прощання крізь завісу",b="When Anaya's pendant is returned to Auberdine, a spectral remnant of Anaya appears before Cerellean one last time. Freed from the lingering anguish that bound her to the ruins, she shares a brief farewell before fading away into the ether, leaving the grieving druid to weep in bittersweet solace by the seaside."}},faq={{q="Хто такий Сереллеан Вайтклоу?",a="Сереллеан Вайтклоу — друїд нічних ельфів, що перебуває в Обердайні. Утративши кохану Анаю під час Розколу десять тисяч років тому, він поринув у довгий друїдський сон разом із Шан'до Малфуріоном Стормрейджем і проніс свою незагоєну скорботу крізь тисячоліття.",al={"сереллеан","хто дає заради вічного кохання","переказ про сереллеана"}},{q="Хто така Аная Донраннер?",a="Аная Донраннер — нічна ельфійка, що жила в місті Амет'Аран до Великого Розколу. Вона загинула, коли місто впало після Війни Прадавніх, і відтоді її привид ув'язнений у руїнах.",al={"аная донраннер","хто така аная","аная темне узбережжя"}},{q="Де дух Анаї?",a="Її дух блукає давніми руїнами Амет'Арана, де кишать привиди, — на півдні Темного Узбережжя, на схід від головної дороги.",al={"місце анаї","де аная донраннер","місце підвіски анаї"}},{q="Чому Сереллеан не міг сам звільнити Анаю?",a="Навіть за десять тисяч років любов Сереллеана до Анаї була такою глибокою, що в нього не підіймалася рука вдарити її примару чи застосувати проти неї чари — навіть щоб покласти край її стражданням.",al={"чому сереллеан не звільнить анаю","чому сереллеан просить допомоги"}},{q="Що сталося з Амет'Араном?",a="Амет'Аран — давнє поселення нічних ельфів, зруйноване десять тисячоліть тому під час Розколу, що настав після Війни Прадавніх. Його руїни на Темному Узбережжі досі повні привидів і відлунь тайної магії.",al={"історія амет'арана","падіння амет'арана","що таке амет'аран"}},{q="Що станеться, коли повернути підвіску Анаї?",a="Звільнивши неспокійний дух Анаї, принесіть її підвіску Сереллеанові в Обердайн. Чим це скінчиться, стане відомо, коли ви повернетеся.",al={"здати підвіску анаї","кінець сереллеана","кінець вічного кохання"}}},fp="16,272,23.504.0,23.431.0,23.312.1,27.264.0,25.241.0,32.126.0,42.217.0,28.223.0,45.138.1"}
P.entries["quest:96390"] = {n="Задушити в зародку",s="«Задушити в зародку» — завдання від Провидця Землі Фарсена: знищити шпигунів Темного Заліза, що проникли в Дун Мороґ. Таємних агентів помітили біля Поселення Айронбенда, і вони загрожують безпеці батьківщини Бронзбірдів.",h="«Задушити в зародку» — завдання від Провидця Землі Фарсена: знищити шпигунів Темного Заліза, що проникли в...",kw={"темне залізо","шпигуни","фарсен","айронбенд","дун мороґ","карта"},ang={["faction:Alliance"]="Знешкодження ворожих розвідників у Дун Мороґу береже важливі шляхи постачання Айронфорджа й довколишні застави від диверсій.",["race:Dwarf"]="Для дворфів Бронзбірдів вичистити лазутчиків Темного Заліза з гір предків — справа захисту дому й давньої кланової помсти."},sec={{t="Очі на морозі",b="Дун Мороґ здавна був укріпленим прихистком дворфів Айронфорджа, та давня ворожнеча між дворфійськими кланами ніколи не спить по-справжньому. Лазутчики Темного Заліза прослизнули через високі перевали й засніжені скелі та підозріло скрадаються біля важливих розкопок і поселень. Провидець Землі Фарсен розуміє: навіть кілька прихованих спостерігачів можуть провіщати нищівний удар, — і кличе стійких захисників Альянсу викорінити їх, перш ніж їхні задуми вкореняться."},{t="Загроза біля Поселення Айронбенда",b="Шпигуни зосередили свої виправи довкола Поселення Айронбенда — важливого місця на сході Дун Мороґу. Хоч Фарсен спершу не може розгадати їхніх точних намірів, знищення таємних агентів дає речовий доказ їхнього більшого задуму. В обшуканих розвідників знаходять Карту Підземелля, і стає ясно: їхнє вторгнення — не просто розвідка, а підготовка, пов'язана з давніми підземними таємницями, як-от Зала Танів."}},faq={{q="Хто дає завдання «Задушити в зародку»?",a="Завдання дає Провидець Землі Фарсен після завдання «Спостереження Фарсена»: він просить допомогти впоратися з непроханими гостями в Дун Мороґу.",al={"хто дає задушити в зародку","видавець задушити в зародку","завдання фарсена"}},{q="Чому в Дун Мороґу шпигуни Темного Заліза?",a="Клан Темного Заліза постійно плете інтриги проти своїх родичів Бронзбірдів. Проникнувши на схід Дун Мороґу, їхні агенти можуть стежити за поселеннями й розкопувати чи розвідувати приховані підземні ходи біля Поселення Айронбенда.",al={"чому шпигуни темного заліза","що роблять темні залізні в дун мороґу","шпигуни айронбенд"}},{q="Де шпигуни Темного Заліза?",a="Вони зосередилися на сході, біля Поселення Айронбенда в східному Дун Мороґу, і чатують на засніжених околицях.",al={"місце шпигунів","де шпигуни темного заліза","де знайти шпигунів"}},{q="Що веде до цього доручення?",a="Це доручення йде після доповіді в завданні «Спостереження Фарсена»: оборона переходить від простого спостереження до активного знищення ворога.",al={"попереднє завдання","що перед задушити в зародку","передумова задушити в зародку"}},{q="Що вдається знайти, полюючи на шпигунів?",a="Зі вбитих шпигунів випадає Карта Темного Заліза, яка починає завдання «Карта Підземелля» й веде до глибших таємниць, пов'язаних із Залою Танів.",al={"що випадає зі шпигунів","карта темного заліза","наступне завдання після задушити в зародку"}},{q="Хто такий Провидець Землі Фарсен?",a="Провидець Землі Фарсен — уважний дворф у Дун Мороґу, що стежить за незвичними поштовхами в надрах і пересуваннями ворожих кланів у засніжених горах.",al={"хто такий фарсен","переказ про провидця землі фарсена"}}},fp="18,247,16.475.0,31.452.1,40.132.0,38.228.0,38.121.0,26.137.0,44.134.1,24.146.0"}
P.entries["quest:96391"] = {n="Карта Підземелля",s="Карта Підземелля, здобута в шпигунів, що проникли до Поселення Айронбенда, відкриває таємні мережі тунелів, прокопаних до коренів Айронфорджа. Її зубчасті руни Темного Заліза окреслюють прихований підземний шлях, що пронизує гору просто до давніх покоїв під нею. Доставити її Провидцю Землі Фарсену — перший крок до розкриття навислого вторгнення знизу.",h="Карта Підземелля, здобута в шпигунів, що проникли до Поселення Айронбенда, відкриває таємні мережі тунелів...",kw={"карта підземелля","темне залізо","тунелі","айронфордж","фарсен","шпигуни"},ang={["class:Shaman"]="Легкий порив вітру, що веде вас до Провидця Землі Фарсена, натякає на духів стихій, які застерігають про неприродні підземні розкопки під Дун Мороґом.",["faction:Alliance"]="Знешкодити цей підземний шлях проникнення конче потрібно, щоб зберегти безпеку Айронфорджа — північного якоря Альянсу.",["race:Dwarf"]="Для дворфів Бронзбірдів виявлення тунелів Темного Заліза, прорубаних просто до підвалин Айронфорджа, — грубе порушення недоторканності столиці."},sec={{t="Креслення проникнення",b="The parchment recovered from Dark Iron spies near Ironband's Compound displays an intricate maze of subterranean roads. Inscribed in harsh, jagged runes unique to the Dark Iron clan, the diagrams map deep underground passages that converge directly beneath Ironforge. The converging passages suggest a possible threat beneath the Bronzebeard capital, but the map's Dark Iron annotations remain uncertain."},{t="Шепіт на вітрі",b="Коли ви вивчаєте грубу картографію, неприродний порив вітру доносить ледь чутний шепіт дворфійського голосу, що закликає діяти негайно. Містичний знак ясно вказує, хто має почути про це першим: Провидець Землі Фарсен. Доповідь про ці відомості викриває перші кроки до давніх зал, запечатаних глибоко під містом, і загрозу прихистку гірського королівства."}},faq={{q="Звідки взялася ця підземна карта?",a="Карту носять шпигуни Темного Заліза, що розвідують околиці Поселення Айронбенда в Дун Мороґу. Її можна знайти, розбираючись із їхніми розвідниками в передгір'ї.",al={"випадіння карти","де знайти карту","як отримати підземну карту"}},{q="Що показує карта?",a="It outlines a complex network of underground highways and tunnels snaking through the earth, all converging directly beneath the city of Ironforge.",al={"що на карті","деталі карти","призначення карти темного заліза"}},{q="Хто такий Провидець Землі Фарсен?",a="Провидець Землі Фарсен — дворф-провидець з Орлиного Піку, що відчуває глибинні скелі й духів гори. Відчувши неприродний рух під землею, він потребує карти, щоб оцінити прорив під Айронфорджем.",al={"де фарсен","хто такий фарсен","провидець землі"}},{q="Чому дворфи Темного Заліза копають під Айронфорджем?",a="The map suggests a possible route beneath Ironforge, but its Dark Iron annotations have not been deciphered. Earthseer Farsen needs to examine it before the plan can be established.",al={"чому темні залізні копають","задум темного заліза в дун мороґу"}},{q="До чого веде це завдання?",a="Доставивши карту Провидцеві Землі Фарсену, ви починаєте розслідування в глибинах під містом, що веде просто до «Вторгнення у Старий Айронфордж» і відкриває шлях до Зали Танів.",al={"продовження підземної карти","наступне завдання після підземної карти"}},{q="Якою мовою написані руни на карті?",a="The map uses the jagged runic script of the Dark Iron dwarves. The person who finds it cannot be sure what the annotations say.",al={"руни на карті","мова темного заліза"}}},fp="15,383,27.404.0,20.344.1,41.165.0,23.147.0,24.216.0,49.181.0,29.201.1,45.127.0"}
P.entries["quest:96392"] = {n="Спостереження Фарсена",s="«Спостереження Фарсена» — завдання-спостереження від Провидця Землі Фарсена, гостя-шамана з клану Вайлдгаммерів, що розташувався високо над Кар'єром Гол'Болар. Завдяки шаманському далекозору провидця шукачі пригод на власні очі бачать, як дворфи Темного Заліза дедалі глибше проникають у серце Дун Мороґу. Цей важливий огляд — ранній крок на шляху до Зали Танів.",h="«Спостереження Фарсена» — завдання-спостереження від Провидця Землі Фарсена, гостя-шамана з клану...",kw={"фарсен","провидець землі","вайлдгаммер","гол'болар","темне залізо","далекозір","шаман"},ang={["class:Shaman"]="Провидці землі з клану Вайлдгаммерів показують земний і духовний зір своєї традиції — погляд на дворфійський шаманізм, вкорінений у скелях Орлиного Піку.",["faction:Alliance"]="Викриття змов Темного Заліза в Дун Мороґу життєво важливе для безпеки Айронфорджа та довколишніх гірських перевалів для всіх подорожніх Альянсу.",["race:Dwarf"]="Для захисників Бронзбірдів попередження від родича з Орлиного Піку показує, якою зухвалою стала інфільтрація Темного Заліза на їхню батьківщину."},sec={{t="Очі над хребтом",b="Умостившись над заметеними снігом розкопками Кар'єру Гол'Болар, Провидець Землі Фарсен пильно стежить за нижніми землями Дун Мороґу. Прибувши з півночі, зі скель Орлиного Піку, гість із клану Вайлдгаммерів приносить гостре духовне чуття в землі, які зазвичай патрулюють горяни Айронфорджа. Замість покладатися на простих розвідників, Фарсен уживає традиційні мистецтва свого клану, щоб стежити за підземним гуркотом і несподіваним рухом на схилах."},{t="Позичений зір",b="Щоб переконати мандрівників у близькій небезпеці, Фарсен позичає їм свій далекозір — шаманський дар, що переносить свідомість на величезні відстані. Крізь духовну лінзу стає очевидно: біди Дун Мороґу сягають далеко за неслухняних трогів і диких звірів. Дворфи Темного Заліза підібралися впритул до промислового серця Айронфорджа й окопуються для операції, яку треба зупинити негайно, доки вона не вкоренилася."}},faq={{q="Хто такий Провидець Землі Фарсен?",a="Провидець Землі Фарсен — дворф із Вайлдгаммерів, що прибув до Дун Мороґу з Орлиного Піку в Пригір'ї. Як провидець землі, він володіє шаманською магією, що дає змогу відчувати збурення в землі й бачити загрози здалеку.",al={"провидець землі фарсен","хто такий фарсен","фарсен вайлдхаммер"}},{q="Де відбувається це спостереження?",a="Провидець Землі Фарсен стоїть над Кар'єром Гол'Болар — важливими розкопками Бронзбірдів на сході Дун Мороґу.",al={"місце спостереження фарсена","де фарсен","огляд кар'єру"}},{q="Яку загрозу розкриває Фарсен?",a="Своїм шаманським далекобаченням Фарсен з'ясовує, що вороже налаштовані дворфи Темного Заліза закріпилися поблизу й становлять реальну й небезпечну загрозу для краю.",al={"що показує далекозорість","загроза темного заліза","видіння фарсена"}},{q="Як це пов'язано із Залою Танів?",a="Розслідування присутності Темного Заліза, виявленої під час спостереження Фарсена, починає довший ланцюжок завдань для шукачів пригод, які прагнуть потрапити до Зали Танів.",al={"настройка на залу танів","ланцюжок зали танів"}},{q="Чому дворф із Вайлдгаммерів бере участь в обороні Дун Мороґу?",a="Вайлдгаммери живуть у Пригір'ї, але кровні зв'язки й спільна ворожнеча до Темного Заліза часом приводять мандрівників на кшталт Фарсена до родових земель Бронзбірдів у Дун Мороґу.",al={"чому вайлдхаммер тут","дворф з орлиного піку в дун мороґу"}},{q="Що йде одразу після «Спостереження Фарсена»?",a="Коли ви побачите через його видіння, як проникає Темне Залізо, Фарсен підганяє вас далі — у завдання «Задушити в зародку», щоб дати відсіч ворогові, який підступає.",al={"наступне завдання","що після спостереження фарсена","задушити в зародку"}}},fp="14,364,21.463.0,17.448.0,24.219.0,33.127.0,31.165.0,44.164.0,59.191.0,52.174.0"}
P.entries["quest:96393"] = {n="Вторгнення у Старий Айронфордж",s="«Вторгнення у Старий Айронфордж» — кульмінація розслідування про лазутчиків Темного Заліза, що причаїлися глибоко під Айронфорджем. За вказівкою Провидця Землі Фарсена герої спускаються в давню Залу Танів під Старим Айронфорджем, щоб знищити ворожого командира Дурґена Дерджгаммера й доповісти про загрозу особисто Королю Маґні Бронзбірду.",h="«Вторгнення у Старий Айронфордж» — кульмінація розслідування про лазутчиків Темного Заліза, що причаїлися...",kw={"старий айронфордж","зала танів","дерджгаммер","темне залізо","фарсен","король маґні"},ang={["faction:Alliance"]="Зупинивши вторгнення, ви запобігаєте нищівному раптовому удару по головній твердині Альянсу у Східних Королівствах.",["race:Dwarf"]="Для Бронзбірдів лазутчики Темного Заліза, що причаїлися в забутих склепіннях під Високим Престолом, — нестерпне осквернення фортеці предків."},sec={{t="Прорив у склепіння",b="Після знахідки підземної карти, що розкрила пересування Темного Заліза, Провидець Землі Фарсен визначає натхненника підземного вторгнення. Глибоко в давніх кам'яних залах Старого Айронфорджа лежить вхід до Зали Танів. Поки верхнє місто клопочеться поверхневими справами, підступні сили прослизнули в ці заснулі печери просто під ногами королівства."},{t="Дурґен Дерджгаммер",b="Переклад захоплених документів Темного Заліза, зроблений Фарсеном, указує на єдиного командира, що керує операцією: Дурґена Дерджгаммера. Засівши глибоко в нижніх склепіннях, Дерджгаммер становить пряму загрозу серцю гірського королівства Бронзбірдів. Щоб зламати хребет вторгненню, шукачі пригод мають пірнути в глибини, здолати його і віднести його відрубану голову нагору, Королю Маґні Бронзбірду."},{t="Аудієнція в короля",b="Голова Дурґена Дерджгаммера, піднесена Королю Маґні Бронзбірду, підтверджує похмуру правду про загрозу Темного Заліза, що повзе крізь давнє коріння міста. Принісши і моторошний доказ перемоги, і особисте вітання від його давнього друга Фарсена, шукачі пригод офіційно завершують розслідування і впевнюються, що Маґні знає, що чаїться внизу."}},faq={{q="Що таке «Вторгнення у Старий Айронфордж»?",a="Це фінал ланцюжка завдань про діяльність Темного Заліза під Дун Мороґом. Його дає Провидець Землі Фарсен: гравцям треба спуститися до Зали Танів під Старим Айронфорджем і вбити командира Темного Заліза Дурґена Дерджгаммера.",al={"завдання вторгнення у старий айронфордж","завдання дурґена дерджгаммера"}},{q="Де відбувається це завдання?",a="Доручення веде шукачів пригод до Зали Танів — давньої підземної зали під Старим Айронфорджем, глибоко в скельній основі під гірською столицею.",al={"де зала танів","місце зали танів"}},{q="Хто такий Дурґен Дерджгаммер?",a="Дурґен Дерджгаммер — командир Темного Заліза, що веде підземне вторгнення до Зали Танів під Старим Айронфорджем. Провидець Землі Фарсен дізнається його ім'я із захоплених документів Темного Заліза.",al={"хто такий дерджгаммер","дурґен дерджгаммер"}},{q="Хто дає завдання і кому його здавати?",a="Завдання дає Провидець Землі Фарсен після того, як здобуто Карту Підземелля. Здавати його треба самому Королю Маґні Бронзбірду в Айронфорджі.",al={"хто дає вторгнення у старий айронфордж","кому здати вторгнення у старий айронфордж"}},{q="Як почати ланцюжок завдань, що веде до цього?",a="Ланцюжок починається із завдання «Гість у Дун Мороґу», яке дає Белдін Стілґрілл біля Хараноса в Дун Мороґу.",al={"як почати ланцюжок зали танів","початок для гостя в дун мороґу"}},{q="Що пов'язує Провидця Землі Фарсена й Короля Маґні?",a="Провидець Землі Фарсен вважає себе давнім другом Короля Маґні Бронзбірда й просить шукачів пригод передати йому особисте вітання, коли ті принесуть до тронної зали голову Дурґена Дерджгаммера.",al={"фарсен і маґні","переказ про провидця землі фарсена"}}},fp="23,341,20.394.0,18.411.1,22.347.1,32.237.0,33.165.0,26.200.0,41.150.0,50.117.0,63.190.0"}
P.entries["quest:96395"] = {n="Давня ворожнеча",s="Глибоко в історичній Залі Танів примарний слуга благає покласти край мукам полеглого правителя. Дух Фалдріма Анвілмара досі не відійшов, поглинутий давньою образою й позбавлений вічного спокою. Шукачам пригод доручено вгамувати неспокійного тана.",h="Глибоко в історичній Залі Танів примарний слуга благає покласти край мукам полеглого правителя.",kw={"давня ворожнеча","фалдрім анвілмар","зала танів","привид","тан","завдання"},ang={["class:Paladin"]="Дати спокій змученій душі — урочистий обов'язок святих воїнів, що присягнули нести мир стражденним мерцям.",["class:Priest"]="Жерці знають, що незгасна образа й неспокутуване горе можуть прикувати дух смертного до світу живих ще довго після того, як тіло обернулося на порох.",["race:Dwarf"]="Для дворфів зустріч із неспокійним таном власного народу — тверезе нагадування, що давня образа може пережити саму смерть."},sec={{t="Благання з-за могили",b="У кам'яних склепах Зали Танів смерть не дає швидкого перепочинку. Там досі блукає примарний слуга Фалдріма Анвілмара, якому ледве вистачає сили промовити крізь завісу смерті. Він не шукає волі для себе: його турбує лише господар, тож він благає мандрівників угамувати буремний дух тана."},{t="Тягар минулого",b="Смерть не звільнила Фалдріма Анвілмара від минулого. Прикутий до світу живих усепоглинною давньою образою, привид Фалдріма лишається збуреним і ворожим і не знайде спочинку, доки його не звільнять силою."}},faq={{q="Хто такий Фалдрім Анвілмар?",a="Фалдрім Анвілмар був таном дворфів, чия неспокійна примара тепер блукає Залою Танів. Його Примарний Прислужник каже, що Фалдріма пожирає давня ворожнеча й він не знаходить спокою. Більше про його життя чи рід у завданні нічого не сказано.",al={"переказ про фалдріма анвілмара","хто такий фалдрім","тан анвілмар"}},{q="Де Зала Танів?",a="Зала Танів — у печерах під Старим Айронфорджем, у межах дворфійської столиці Айронфордж.",al={"місце зали танів","де зала танів","вхід до зали танів"}},{q="Чому привид Фалдріма Анвілмара ворожий?",a="За словами примарного прислужника, колишнього тана пожирає давня ворожнеча. Історія дворфів просякнута століттями чвар між кланами, і невгасима ненависть Фалдріма не дає його духові відійти до мирного сну.",al={"чому фалдрім злий","чому тан нападає","пояснення давньої ворожнечі"}},{q="Хто дає завдання «Давня ворожнеча»?",a="Завдання дає Примарний Прислужник у Залі Танів. Прикутий до служби навіть після смерті, прислужник прагне лише спокою для свого колишнього господаря.",al={"хто починає давню ворожнечу","завдання привидного служки","видавець"}},{q="Що треба зробити, щоб виконати завдання?",a="Треба зустрітися з духом Фалдріма Анвілмара в Залі Танів, здолати в бою його неспокійний привид, щоб звільнити від мук, і доповісти Примарному Прислужникові.",al={"як закінчити давню ворожнечу","упокоїти фалдріма","мета давньої ворожнечі"}},{q="Чи пов'язаний Фалдрім із містечком Анвілмар?",a="Поки що невідомо. Ім'я Фалдріма збігається з назвою поселення Анвілмар у Долині Холодного Хребта, але в завданні нічого не сказано ні про його родину, ні про зв'язок із містечком.",al={"чи фалдрім з анвілмара","зв'язок анвілмара з колдрідж","родина анвілмар"}}},fp="17,276,21.348.0,22.214.1,24.233.0,36.102.0,45.234.0,38.168.0,39.186.0,43.166.0"}
P.entries["quest:96408"] = {n="Гість у Дун Мороґу",s="«Гість у Дун Мороґу» — завдання-розслідування від Белдіна Стілґрілла біля Хараноса. Горяни доповіли про незнайоме багаття високо на скелях над Кар'єром Гол'Болар, і треба розвідати, чи не загрожує чужинець місцевим дворфам.",h="«Гість у Дун Мороґу» — завдання-розслідування від Белдіна Стілґрілла біля Хараноса.",kw={"гість","дун мороґ","фарсен","стілґрілл","гол'болар","багаття","харанос"},ang={["class:Shaman"]="Зустріч із Провидцем Землі Фарсеном напряму пов'язана з духовним єднанням із гірським камінням — рідкісне видовище на засніжених висотах Дун Мороґу.",["faction:Alliance"]="Допомога місцевим горянам біля Хараноса гарантує, що шляхи постачання й робітники кар'єру лишаться в безпеці від непередбачених загроз.",["race:Dwarf"]="Для дворфів Бронзбірдів нагляд за непроханими спостерігачами над великими копальнями, як-от Гол'Болар, — звичайна безпекова справа для захисту кордонів Каз Модану."},sec={{t="Стовп диму на висотах",b="Горяни Дун Мороґу пильно стежать за скелями й засніженими долинами довкола Айронфорджа. Коли високо над Кар'єром Гол'Болар раптом з'явилося багаття, в Хараносі здивовано звели брови. Белдін Стілґрілл, стривожений незвичним табором просто над важливою дворфійською копальнею, наймає мандрівників, щоб ті вибралися на гребені й з'ясували, хто цей таємничий незнайомець — мирний подорожній чи зайда."},{t="Зустріч із провидцем землі",b="Розвідка гребеня показує, що мандрівник — це Провидець Землі Фарсен, містик, який розбив табір на продутих вітрами висотах. Далеко не мародер-трог і не відверто ворожий шпигун, цей таємничий спостерігач має глибокий духовний зв'язок із землею. Його присутність на кручі над кар'єром починає шлях до розкриття глибших заворушень, прихованих під Каз Моданом, що зрештою сплітається з таємницею Зали Танів."}},faq={{q="Хто посилає вас з'ясувати, що за гість?",a="Белдін Стілґрілл, що стоїть біля Хараноса в Дун Мороґу, дає завдання після того, як горяни повідомили про незнайоме вогнище на пагорбах.",al={"хто дає це завдання","початок завдання","завдання белдіна стілґрила"}},{q="Де загадковий табір?",a="Вогнище горить високо на засніжених хребтах на схід від Хараноса, просто над розкопками Кар'єру Гол'Болар.",al={"місце табору","де гість","місце гостя"}},{q="Хто цей гість, що дивиться на кар'єр?",a="Гість — Провидець Землі Фарсен, духовний спостерігач, що отаборився у відлюдному місці на висотах над кар'єром.",al={"хто такий фарсен","хто гість","провидець землі фарсен"}},{q="Чому дворфам здалося підозрілим вогнище?",a="Кар'єр Гол'Болар — важливі дворфійські розробки, які й так потерпають від місцевих трогів. Будь-який невідомий табір високо над котлованом цілком міг належати розвідникам чи ворожим силам, що стежать за пересуваннями дворфів.",al={"чому підозріло","чому розслідувати","чому посилають мене"}},{q="До чого веде це завдання?",a="Доповідь Провидцеві Землі Фарсену веде просто до завдання «Спостереження Фарсена» й стає першим кроком ланцюжка доступу до Зали Танів.",al={"що далі","наступне завдання","вступ до зали танів"}},{q="Чи треба битися з незнайомцем у таборі?",a="Ні. Белдін Стілґрілл готує вас до можливої сутички, але гість — Провидець Землі Фарсен, мирний спостерігач, що охоче з вами поговорить.",al={"чи гість ворожий","чи вбивати гостя","бій з гостем"}}},fp="23,274,28.427.0,21.440.1,41.138.0,41.132.0,42.114.1,48.212.0,31.154.1,46.153.1"}
P.entries["quest:965"] = {n="Вежа Альталакса",s="Вартова Елісса Старбріз, відповідальна за оборону Обердайна, підозрює лихі справи в давніх руїнах на півночі. Вона доручає шукачам пригод знайти Балтула Шедовстрайка — розвідника, якого послали стежити за загадковою Вежею Альталакса і який вчасно не доповів.",h="Вартова Елісса Старбріз, відповідальна за оборону Обердайна, підозрює лихі справи в давніх руїнах на півночі.",kw={"вежа альталакса","вартова елісса старбріз","балтул шедовстрайк","розвідник","обердайн","темне узбережжя"},ang={["faction:Alliance"]="Обердайн — головні ворота Альянсу на північ Калімдору, тож захист навколишніх доріг і кордонів важливий для всіх союзників, що сюди прибувають.",["race:NightElf"]="Руїни Альталакса — нагадування про занепале минуле Високородних давнього Калімдору, і вберегти Обердайн від порчі, що гноїться в тому камінні, — важливий обов'язок Вартових нічних ельфів."},sec={{t="Зниклий розвідник",b="Auberdine's sentinels must remain ever watchful over Darkshore's creeping perils. Sentinel Elissa Starbreeze noticed suspicious activity stirring around the Tower of Althalaxx in the northern reaches of the forest. She sent Balthule Shadowstrike to survey the ancient ruin. Days have passed without word from the scout, prompting Elissa to seek a willing traveler to journey north, locate Balthule, and ensure he has not met an untimely end."},{t="Очі над руїнами",b="Дорога на північ з Обердайна минає давні руїни калдореїв і перетинає Річку Скельного Джерела, перш ніж вийти до тінистих нетрів довкола вежі. Хоч Балтул і не міг передати звістку до Обердайна, він пережив свою першу розвідку. Коли його знаходять у навколишніх лісах, він підтверджує, що чуття не підвело Еліссу: в обваленій кам'яній вежі відбуваються темні й тривожні події."}},faq={{q="Хто така Вартова Елісса Старбріз?",a="Елісса Старбріз — Вартова нічних ельфів в Обердайні. Їй доручено захищати поселення від зовнішніх загроз по всьому Темному Узбережжю, і вона стежить за небезпеками в окрузі, як-от за Вежею Альталакса.",al={"елісса старбріз","хто дає завдання","видавець оберіжина"}},{q="Хто такий Балтул Шедовстрайк?",a="Балтул Шедовстрайк — розвідник, якого Вартова Елісса Старбріз послала стежити за загадковою діяльністю довкола Вежі Альталакса. Він чатує біля руїн, пильнуючи ворожі сили.",al={"балтул","хто розвідник","балтул шедовстрайк"}},{q="Де Вежа Альталакса?",a="Вежа — на північному сході Темного Узбережжя. Щоб дістатися до неї, вирушайте з Обердайна на схід, ідіть північною дорогою повз Башал'Аран і перейдіть міст через Річку Скельного Джерела, доки не побачите шпиль.",al={"місце вежі альталакса","де вежа","як знайти альталакса"}},{q="Навіщо взагалі послали розвідника до вежі?",a="Elissa sent Balthule to observe strange happenings around the Tower of Althalaxx while carrying out her charge to protect Auberdine.",al={"навіщо стежити за вежею","що не так в альталаксі","чому послали балтула"}},{q="Чому Балтул не повернувся до Обердайна?",a="Елісса не отримала донесення від Балтула й просить вас довідатися, що з ним. Коли ви його знайдете, Балтул сам пояснить, у якому він становищі.",al={"чому балтул зник","чи балтул в пастці","чому балтул лишився"}},{q="Чи має цей ланцюжок завдань продовження?",a="Так. Знайшовши Балтула Шедовстрайка, ви починаєте розслідування з кількох частин — про темні сили, що захопили Вежу Альталакса, та їхні зловісні задуми на Темному Узбережжі.",al={"чи це ланцюжок","яке завдання далі","ланцюжок альталакса"}}},fp="22,285,23.441.0,18.424.1,34.211.0,29.214.0,40.228.0,53.132.0,42.125.0,31.166.0"}
P.entries["quest:966"] = {n="Вежа Альталакса",s="Розслідуючи підозрілу діяльність довкола Вежі Альталакса на півночі Темного Узбережжя, розвідник Балтул Шедовстрайк шукає помічників, щоб дізнатися більше про чорнокнижників, які там гуртуються. За покинутими клаптиками пергаменту, відібраними у фанатиків, що отаборилися біля руїн, він намагається з'ясувати, хто такі ці культисти і яка їхня зловісна мета.",h="Розслідуючи підозрілу діяльність довкола Вежі Альталакса на півночі Темного Узбережжя, розвідник Балтул...",kw={"вежа альталакса","балтул шедовстрайк","культ темного берега","зношений пергамент","делґрен очищувач","чорнокнижники"},ang={["class:Paladin"]="Виявлення згуртованого темного культу на півночі Темного Узбережжя безпосередньо допомагає хрестовому походові Делґрена Очищувача — союзника, що присвятив себе вичищенню скверни й демонічної порчі.",["class:Warlock"]="Культ Темного Берега доводить, що незалежні ковени захоплюють давні руїни, щоб чинити свої викликання подалі від цікавих очей влади і Альянсу, і Орди.",["race:NightElf"]="Осквернення Вежі Альталакса людьми-культистами й демонами — ще одна наруга над давньою ельфійською спадщиною на берегах Калімдору."},sec={{t="Очі на мілинах",b="Балтул Шедовстрайк стоїть на варті на імлистому березі півночі Темного Узбережжя й пильно стежить за давніми руїнами, відомими як Вежа Альталакса. Його послали наглядати за цим місцем для Обердайна й попереджати Делґрена Очищувача про будь-яку небезпеку, але Балтул не наважувався покинути пост, щоб доповісти. Боячись проґавити важливі рухи темних чаклунів, що засіли в камінні, він натомість покладається на мандрівників, які розвідають табори довкола."},{t="Розгадати культ",b="Нижчі послідовники, що блукають зруйнованими околицями, носять уривки сувоїв і записок. Склавши докупи кілька зношених пергаментів, відібраних у цих зовнішніх культистів, Балтул натрапляє на тривожну назву — Культ Темного Берега. Ця тіньова секта йому зовсім невідома, і розвідник розуміє: небезпека куди організованіша, ніж звичайна зграя свавільних чорнокнижників, тож Делґрена треба попередити негайно."}},faq={{q="Хто такий Балтул Шедовстрайк?",a="Балтул Шедовстрайк — розвідник Альянсу, що стоїть на дорозі біля Вежі Альталакса на півночі Темного Узбережжя. Його послали стежити за підозрілими зібраннями біля вежі за дорученням проводу Обердайна й паладина Делґрена Очищувача.",al={"переказ про балтула шедовстрайка","хто такий балтул","балтул темне узбережжя"}},{q="Що таке Вежа Альталакса?",a="Вежа Альталакса — давні ельфійські руїни на півночі Темного Узбережжя. Останнім часом підступні чорнокнижники та їхні раби-культисти захопили околиці й саму вежу та правлять там темні обряди далеко від очей Обердайна.",al={"вежа альталакса","що таке альталакс","зруйнована вежа темного узбережжя"}},{q="Хто ці культисти довкола вежі?",a="Вони належать до Культу Темного Берега — таємної організації чорнокнижників і фанатиків, що зібралися в давніх ельфійських руїнах, щоб проводити темні обряди закликання.",al={"хто чорнокнижники","культ темного берега","фанатики темного берега"}},{q="Чому Балтул застерігає від того, щоб заходити у вежу?",a="Балтул зауважує, що чорнокнижники у верхній частині вежі набагато могутніші й небезпечніші за фанатиків, які отаборилися довкола серед руїн. Він радить спершу зібрати відомості на околицях, а вже тоді штурмувати твердиню.",al={"чи можна входити у вежу","чорнокнижники вежі небезпечні","всередині вежі"}},{q="Що розкривають пошарпані пергаменти?",a="Клаптики, які носять фанатики культу, вперше чітко підтверджують назву угруповання — Культ Темного Берега — і показують Балтулові, що захопники вежі — організована секта, чия присутність становить безпосередню загрозу краю.",al={"що на пергаментах","переказ про пошарпаний пергамент","записи культу"}},{q="Хто такий Делґрен Очищувач?",a="Делґрен Очищувач — паладин Альянсу на Посту Маестри в Ашенвалі, що вичищає демонічний і зіпсований скверною вплив. Він запідозрив, що у Вежі Альталакса вкорінюється щось лихе, і покладається на розвідників на кшталт Балтула.",al={"делґрен","хто такий делґрен","делґрен очищувач"}}},fp="22,337,20.454.0,20.404.1,29.253.0,31.250.0,43.171.0,50.247.0,35.255.0,28.265.0"}
P.entries["quest:96607"] = {n="Широкі простори",s="«Широкі простори» — вступний урок виживання, який бувалі мандрівники дають новоспеченим подорожнім по всьому Азероту. Присівши на хвилину біля теплого багаття, новачки дізнаються, як добрий відпочинок і підготовка зберігають життя шукачеві пригод поза міськими мурами. Це перший крок до опанування виживання в дикій природі й облаштування польових таборів.",h="«Широкі простори» — вступний урок виживання, який бувалі мандрівники дають новоспеченим подорожнім по всьому...",kw={"широкі простори","виживання","багаття","табір","відпочинок","ремесла","азерот"},ang={["faction:Alliance"]="У безпечному Лісі Елвінн люди-мандрівники засвоюють ці основи виживання від досвідчених подорожніх, перш ніж зіткнутися з суворішими загрозами, що чигають у Вестфолі й Редріджі.",["faction:Horde"]="Чи то перетинаючи посушливі рівнини Дуротару, чи обвітрені плато Малгору, знавці виживання Орди прищеплюють кожному молодому воїнові вміння розводити вогонь і дисципліну життя просто неба.",["profession:Cooking"]="Кожен табір у глушині починається з вогню, тож кулінарія — природна супутниця виживання просто неба. Після цього уроку майстри табірної справи одразу спрямовують вас на придорожню науку куховарства."},sec={{t="Уроки дороги",b="Хоч який гострий ваш клинок і хоч яка могутня магія, нетрі Азерота швидко стирають на порох кожного, хто нехтує основами виживання. Бувалі мандрівники, що стоять біля придорожніх галявин, дають цей простий урок подорожнім, які вирушають із рідних долин. Відпочинок біля багаття не лише дає перепочити натрудженим ногам — він заспокоює розум і готує дух до суворої дороги попереду. Лише ті, хто опанував дисципліну регулярного відпочинку й підготовки, мають шанс прожити досить довго, щоб здобути багатство й славу."},{t="Дім далеко від дому",b="Щойно шукач пригод усвідомлює цінність тріскучого вогню й доброго відпочинку, наставники відсилають його просто до міських ремісників. Табір у полі рідко обмежується жаринкою й постіллю; виживання вимагає практичних ремесел. Чи то кувати запасні заклепки, чи готувати похідні харчі, чи зашивати порване спорядження під зорями — кожне ремесло дає особливі табірні речі, що перетворюють голий схил на самодостатню стоянку."}},faq={{q="Хто дає цей урок новим мандрівникам?",a="Залежно від того, де ви перебуваєте, цю науку дають різні бувалі мандрівники. У Лісі Елвінн за неї береться досвідчений мандрівник Сем Сарсапарілла, а деінде своїм досвідом життя в нетрях діляться Ерік Брайтгаммер, Лайріна Даскблейд, Бракк, Елеанор Шеклтон, Каґа Вайлдгуф і Раан Вайлдвінд.",al={"хто дає широкі простори","хто починає широкі простори","видавець широких просторів"}},{q="Навіщо сидіти біля вогнища?",a="Тихо посидівши біля палахкого вогнища, шукач пригод переводить подих і отримує ефект «Посилений відпочинок». Свідомо відпочивати в дорозі вкрай важливо, щоб не втрачати сил у довгих мандрах нетрями.",al={"навіщо сидіти біля вогнища","що робить багаття","баф відпочинку"}},{q="Куди веде це навчання далі?",a="Коли ви відпочинете біля вогню, наставник посилає вас до найближчих поселень опановувати практичні ремесла. Звідти ви починаєте «Табірну науку 101: кулінарія», а також окремі уроки польового табору, пов'язані з тією професією, яку ви оберете.",al={"що після широких просторів","наступне завдання широких просторів","табірні завдання"}},{q="Чи можуть шукачі пригод з Орди теж узятися за цей урок?",a="Так. Виживати в суворих нетрях доводиться всім, хоч би кому ти служив. Бувалі наставники й Альянсу, і Орди — як-от Бракк, Елеанор Шеклтон і Каґа Вайлдгуф — навчають новачків своєї фракції тих самих основ табірного вміння.",al={"чи це лише для альянсу","широкі простори орда","чи орки можуть це"}},{q="Чому наставники радять звернутися до наставників ремесел?",a="Щоб вижити, мало просто сидіти біля вогню — шукачеві пригод потрібна самостійність. Наставники ремесел навчать вас виготовляти особливе табірне облаштування для вашого ремесла, хай то куховарство в дорозі, лагодження обладунків чи варіння ліків просто неба.",al={"чому вчитися професій","табірні приладдя наставники ремесел","зв'язок професій і табору"}},{q="Який досвід потрібен, перш ніж узятися за це завдання?",a="Зазвичай цей урок шукачі пригод отримують одразу після завдання «Шукач пригод», коли вже довели свою рішучість і вийшли з початкових осель у ширший край.",al={"вимоги широких просторів","як відкрити широкі простори","перед широкими просторами"}}},fp="18,359,20.539.0,21.445.0,40.310.0,47.231.0,35.262.0,52.261.0,61.278.0,59.186.0"}
P.entries["quest:96627"] = {n="Шукач пригод",s="«Шукач пригод» — завдання-дороговказ від Маршала Макбрайда в Долині Нортширу. Визнавши вашу ранню вправність, Макбрайд посилає вас за межі відлюдних земель абатства до Ґолдшира — придивитися до новоприбулого на ім'я Сем Сарсапарілла.",h="«Шукач пригод» — завдання-дороговказ від Маршала Макбрайда в Долині Нортширу.",kw={"шукач пригод","маршал макбрайд","сем сарсапарілла","ґолдшир","нортшир","дороговказ"},ang={["faction:Alliance"]="Для свіжих новобранців Альянсу, що завершують службу в Нортширі, це перший офіційний крок у ширше королівство Лісу Елвінн.",["race:Human"]="Захисники з людей, виходячи з Абатства Нортшира, роблять перші кроки до Ґолдшира — гамірного серця Елвінну."},sec={{t="Прощання з долиною",b="Щойно новобранці очищають Долину Нортширу від найближчих загроз — місцевих Дефіас і шкідників, — Маршал Макбрайд починає дивитися далі дорогою. Регулярні сили Стормвінда розтягнуті по всьому королівству, тож місцевий гарнізон мусить покладатися на перспективних бійців, щоб наглядати за подорожніми й мандрівниками, які блукають довколишніми лісами."},{t="Цікавий новачок",b="Замість військового наказу чи полювання за винагороду Макбрайд дає вам незвичне доручення: перевірити одного нового шукача пригод, поміченого біля Ґолдшира, на ім'я Сем Сарсапарілла. Це прохання стає переходом із відлюдної долини Нортширу в ширші й небезпечніші простори Лісу Елвінн."}},faq={{q="Хто дає мені це доручення?",a="Маршал Макбрайд, командир гарнізону Стормвінда в Долині Нортширу, дає це доручення, щойно ви доведете свою звитягу, боронячи абатство.",al={"хто дає завдання","хто дає шукача пригод","завдання маршала макбрайда"}},{q="Хто такий Сем Сарсапарілла?",a="Сем Сарсапарілла — шукач пригод, що затримався біля дороги поблизу Ґолдшира. Маршал Макбрайд прочуває про нього й просить вас з'ясувати, що той замислив.",al={"сем сарсапарілла","хто такий сем","шукач пригод у ґолдширі"}},{q="Де знайти Сема Сарсапаріллу?",a="Він біля головної дороги, що веде з Нортширу до містечка Ґолдшир у Лісі Елвінн.",al={"місце сема сарсапарілли","де сем","знайти сема сарсапаріллу"}},{q="Чому Маршала Макбрайда цікавить якийсь випадковий шукач пригод?",a="Нортшир і досі насторожі через розбійників і непроханих гостей. Макбрайд воліє пильно стежити за незнайомими найманцями й мандрівниками, що проходять краєм, і доручає надійним місцевим першими виходити з ними на зв'язок.",al={"чому посилати мене","мотиви макбрайда","чому шукати сема"}},{q="Чи треба покидати Долину Нортширу, щоб виконати це?",a="Так. Доручення веде вас крізь південну браму Долини Нортширу на лісову дорогу до Ґолдшира.",al={"за межами нортширу","чи покидати нортшир","йти до ґолдшира"}},{q="Чи це звичайне доручення військового командування Стормвінда?",a="Хоч його й дає офіцер Стормвінда, Макбрайд прямо називає його незвичним, а не звичайною вартовою службою: він покладається на вашу розважливість як незалежного захисника, а не на військовий статут.",al={"військо стормвінда","чи це стандартна служба","службова справа"}}},fp="14,244,18.338.0,18.303.0,26.159.0,24.165.0,33.105.0,56.225.0,52.129.0,63.210.0"}
P.entries["quest:96628"] = {n="Шукач пригод",s="«Шукач пригод» — місцеве доручення від Горянина Талоса біля південної брами Дун Мороґу. Перш ніж пропустити мандрівників гірським тунелем до Хараноса, Талос просить віднести пакунок припасів Еріку Брайтгаммеру — новоприбулому, що отаборився одразу за селищем.",h="«Шукач пригод» — місцеве доручення від Горянина Талоса біля південної брами Дун Мороґу.",kw={"шукач пригод","талос","брайтгаммер","харанос","припаси","горянин","дун мороґ"},ang={["faction:Alliance"]="Горяни покладаються на новобранців Альянсу, щоб ті носили важливі припаси крижаними дорогами і союзники-мандрівники за Хараносом не лишалися без провізії.",["race:Dwarf"]="Для юних дворфів, що покидають Долину Холодного Хребта, доставка провізії Еріку Брайтгаммеру — перша спільна справа з горянами у ширшому краї Дун Мороґу."},sec={{t="Послуга для горян",b="Охорона високих перевалів і тунелів між Долиною Холодного Хребта та ширшими сніговими просторами Дун Мороґу — важка праця для горян Айронфорджа. Стоячи на прикордонній брамі, Горянин Талос пильнує і місцеві небезпеки, і мандрівників на втоптаній стежці. Коли на пост доходить звістка про самотнього шукача пригод, що прибув до Хараноса, Талос просить надійних перехожих віднести потрібні припаси далі, щоб підтримати новачків, які вирушають у замерзлі скелі."},{t="Припаси для Хараноса",b="Дорога, що спускається з південного перевалу, в'ється до селища Харанос — головного осередку дворфійського ремесла й подорожей у центральному Дун Мороґу. Ерік Брайтгаммер нещодавно облаштувався одразу на околиці селища. Доставивши йому пакунок провізії від горян, мандрівники допомагають налагодити важливий зв'язок між вартовими на далеких гребенях і тими, хто мандрує нетрями."}},faq={{q="Хто дає завдання «Шукач пригод»?",a="Це завдання дає Горянин Талос. Він стоїть на варті біля брами гірського перевалу, що з'єднує стежку з Долини Холодного Хребта з рештою Дун Мороґу.",al={"видавець","хто дає шукача пригод","завдання талоса"}},{q="Хто такий Ерік Брайтгаммер?",a="Ерік Брайтгаммер — шукач пригод, що нещодавно прибув під дворфійське містечко Харанос. Горянин Талос посилає мандрівників віднести йому необхідний згорток припасів.",al={"де ерік брайтгаммер","хто шукач пригод","брайтгаммер"}},{q="Куди треба доставити припаси?",a="Доставка — під самим Хараносом у Дун Мороґу, на північ від тунелю Перевалу Холодного Кряжа, де стоїть Горянин Талос.",al={"куди доставити припаси","місце еріка брайтгаммера","куди нести згорток"}},{q="Чому Горянин Талос посилає припаси?",a="Горяни стежать за мандрівниками по всьому Дун Мороґу. Коли Талос дізнається, що біля Хараноса отаборився шукач пригод, він організовує, щоб йому віднесли харчі й підтримали на морозі.",al={"чому талос посилає припаси","мета талоса","причина згортка"}},{q="Що ви несете?",a="Ви несете Згорток Припасів, який Горянин Талос особисто передав для Еріка Брайтгаммера.",al={"які припаси","предмет згортка"}},{q="Чи доступне це завдання гравцям Орди?",a="Ні. Горянин Талос — дворфійський вартовий Альянсу в Дун Мороґу, тож це завдання лише для Альянсу.",al={"чи орда може це","чи це лише для альянсу","шукач пригод орда"}}},fp="14,279,28.484.0,21.418.0,36.140.0,25.178.0,36.132.0,43.199.0,27.102.0,41.118.0"}
P.entries["quest:96630"] = {n="Шукач пригод",s="«Шукач пригод» — коротке завдання в Тельдрассилі, що починається зі знахідки покинутого щоденника в хащах. Простий записник оповідає про скромні мандри й ночівлі під відкритим небом невідомого мандрівника; його належить доставити Ліріні Даскблейд поблизу Доланаара.",h="«Шукач пригод» — коротке завдання в Тельдрассилі, що починається зі знахідки покинутого щоденника в хащах.",kw={"шукач пригод","щоденник","ліріна даскблейд","доланаар","тельдрассил"},ang={["faction:Alliance"]="Для новачків Альянсу, що лише освоюються під Світовим Деревом, повернення загублених речей місцевим розвідникам допомагає підтримувати лад у гаях.",["race:NightElf"]="Юні нічні ельфи, що патрулюють Тельдрассил, часто знаходять сліди мандрівників і передають загублені особисті речі вартовим, як-от Ліріні Даскблейд."},sec={{t="Щоденник мандрівника",b="Серед густого гілля й сплетеного коріння Тельдрассила мандрівники часом натрапляють на покинуті особисті речі. Цей простий щоденник оповідає про непримітні, але щирі блукання безіменного шукача пригод. Замість великих подвигів чи небезпечних полювань на чудовиськ більшість його сторінок захоплено описує прості радощі ночівлі під сутінковою кроною."},{t="Доставка до Доланаара",b="Замість лишити особисту пам'ятку мокнути у вологих хащах, той, хто її знайшов, відчуває потяг віднести її до Доланаара. Ліріна Даскблейд, що стоїть на посту біля поселення нічних ельфів, приймає загублені сторінки — можливо, щоб дати завершення цій історії або з'ясувати, чиї мандри лишилися позаду."}},faq={{q="Що за щоденник згадано в завданні?",a="Це простий особистий записник, знайдений у нетрях Тельдрассила. Його записи розповідають про тихе життя й мандри незнайомої людини — про звичайні пригоди й незмінну любов до ночівлі просто неба.",al={"загублений щоденник","що за книга","щоденник шукача пригод"}},{q="Хто така Лайріна Даскблейд?",a="Лайріна Даскблейд — нічна ельфійка, що перебуває біля Доланаара. Саме їй має дістатися загублений щоденник, знайдений у лісі.",al={"лайріна","де лайріна даскблейд","кому здати"}},{q="Де відбувається це завдання?",a="Завдання відбувається на Тельдрассилі — великій гілці нічних ельфів, у нетрях довкола села Доланаар.",al={"де шукач пригод","зона завдання"}},{q="Чи описує щоденник небезпечних чудовиськ або битви?",a="Ні. Написаний він доволі просто й розповідає про скромне життя й мандри невідомої особи, особливо наголошуючи, як приємно ночувати в таборі.",al={"переказ про щоденник","що в щоденнику","що в ньому написано"}},{q="Хто може виконати це доручення?",a="Це доручення лише для членів Альянсу, що мандрують початковими землями Тельдрассила, — передусім для молодих нічних ельфів поблизу Доланаара.",al={"чи орда може це","завдання альянсу"}},{q="Чому щоденник треба віднести до Доланаара?",a="Доланаар — головне місце зустрічей і перехрестя цієї частини Тельдрассила, тож саме сюди найрозумніше приносити загублені особисті речі; до того ж неподалік на щоденник чекає Лайріна Даскблейд.",al={"чому доланаар","чому лайріна"}}},fp="14,259,20.373.0,20.307.0,43.220.0,25.128.0,33.135.0,56.177.0,27.153.0,36.218.0"}
P.entries["quest:96638"] = {n="Шукач пригод",s="«Шукач пригод» — вступне мандрівне завдання на Острові Зефрас. Його дає Етін Вітрів у Тендальському Гаю: мандрівників, що вже набралися досвіду, вона скеровує на південний захід, до Села Шен'дар, — зустрітися з Рааном Вайлдвіндом, бувалим мандрівником, що знає глушину.",h="«Шукач пригод» — вступне мандрівне завдання на Острові Зефрас.",kw={"шукач пригод","раан вайлдвінд","етін вітрів","село шен'дар","тендальський гай","острів зефрас"},ang={["race:Skyborne"]="Для юних Небороджених, що виходять із-під захищеного пологу Тендальського Гаю, зустріч із Рааном Вайлдвіндом — перший справжній крок у ширші, неприборкані простори рідного острова."},sec={{t="Прощання з гаєм",b="Тендальський Гай дає прихисток і тиху відраду, але ширші простори Острова Зефрас лишаються дикими й небезпечними. Етін Вітрів наглядає за посвячуваними й бачить, коли майбутній мандрівник готовий переступити знайомі межі. Тим, хто шукає слави, статків чи мети, вже замало лишатися за захищеними межами гаю."},{t="Провідник у дорозі",b="На південний захід від гаю, при дорозі до Села Шен'дар, уже отаборився інший мандрівник. Раан Вайлдвінд чимало часу провів, долаючи небезпеки за межами безпечного прихистку. Розшукавши його, молоді мандрівники отримують практичне знайомство з виживанням за межами Тендальського Гаю й учаться в того, хто вже ходив відкритими стежками."}},faq={{q="Хто посилає вас до Раана Вайлдвінда?",a="Завдання дає Етін Вітрів у Тендальському Гаю. Коли ви проявите себе в навколишніх лісах, вона радить знайти когось, хто на власні очі бачив решту острова.",al={"хто дає шукача пригод","хто починає шукача пригод","завдання етін"}},{q="Де знайти Раана Вайлдвінда?",a="Раан Вайлдвінд отаборився на південний захід від Тендальського Гаю, просто біля головної дороги до Села Шен'дар.",al={"місце раана вайлдвінда","де раан","як знайти раана"}},{q="Навіщо це доручення?",a="Воно правує за дороговказ: виводить мандрівників із безпечного Тендальського Гаю й знайомить із наставниками та викликами глибше на Острові Зефрас.",al={"навіщо шукач пригод","мета шукача пригод","чого вчить раан"}},{q="Що треба виконати, перш ніж отримати це завдання?",a="Спершу треба виконати для Етін Вітрів завдання про Лиху матріархиню — лише тоді вона спрямує вас дорогою до Раана Вайлдвінда.",al={"передумова шукача пригод","вимоги до шукача пригод"}},{q="Чи безпечне Село Шен'дар для мандрівників?",a="Село Шен'дар лежить далі на південний захід, за табором Раана. Це помітне поселення острова, але на дорогах і в нетрях довкола молодим шукачам пригод слід бути обережними.",al={"чи шен'дар безпечне","що таке село шен'дар"}},{q="Хто такий Раан Вайлдвінд?",a="Раан Вайлдвінд — завзятий мандрівник, що вирушив за межі Тендальського Гаю й отаборився біля Села Шен'дар; він дає поради й доручення новачкам, що йдуть цією дорогою.",al={"переказ про раана","хто такий раан вайлдвінд"}}},fp="14,245,17.355.0,19.347.0,36.193.0,31.125.0,33.169.0,64.136.0,39.184.0,21.182.0"}
P.entries["quest:96652"] = {n="Шукач пригод",s="Досліджуючи суворі пустки Дуротару, подорожні натрапляють на простий покинутий щоденник, що описує тихі мандри незнайомої постаті. Його сторінки тепло оповідають про життя просто неба й ночівлі під зорями; щоденник чекає, щоб його віднесли Бракку біля Гострого Пагорба.",h="Досліджуючи суворі пустки Дуротару, подорожні натрапляють на простий покинутий щоденник, що описує тихі...",kw={"щоденник","бракк","гострий пагорб","мандрівник","табір","дуротар"},ang={["class:Hunter"]="Мисливці, що все життя живуть із дарів землі, легко зрозуміють теплі записи щоденника, що раз у раз повертаються до радощів ночівлі в дикій природі.",["faction:Horde"]="Посушливими стежками Дуротару ходить багато новобранців; повернення загублених речей і доповідь розвідникам біля Гострого Пагорба допомагають тримати лад на центральному рубежі."},sec={{t="Нотатки мандрівника",b="Дуротар — суворий край, де виживання зазвичай важливіше за неквапливі подорожі, тож знайти книгу мандрівного літописця — незвична річ. Скромний щоденник, що лежав без нагляду в червоній пилюці, містить роздуми й пригоди когось геть невідомого героям Орди. Замість кривавих битв чи великих походів його сторінки зупиняються на простих радощах: спати під відкритим небом і розбивати табір у дикій природі."},{t="Доставка Бракку",b="Хто б не писав ці записи, він лишив досить вражень — чи зв'язків, — щоб вони вказували на Бракка, орка біля поселення Гострий Пагорб. Віднести особисті речі загублених подорожніх тутешнім розвідникам і робітникам табору — часто єдиний спосіб, щоб розсіяні мандрівники колись знову з'єдналися зі своїм майном або принаймні щоб їх пам'ятали ті, хто пильнує запилені дороги."}},faq={{q="Що в загубленому щоденнику?",a="Книжка напрочуд звичайна: у ній щоденні записи про тихі пригоди маловідомого шукача пригод. Особливо часто він згадує прості радощі й утіху від того, щоб розбити табір у нетрях.",al={"що каже щоденник","вміст загубленого щоденника","текст щоденника"}},{q="Хто написав щоденник?",a="На знайдених сторінках автор не названий; щоденник описує життя й мандри когось, про кого ви ніколи не чули, доки не натрапили на книжку в нетрях.",al={"хто шукач пригод","автор загубленого щоденника","хто написав цю книгу"}},{q="Хто такий Бракк?",a="Бракк — орк, що перебуває біля Гострого Пагорба в центрі Дуротара; саме йому віддають загублений щоденник.",al={"бракк разор гілл","хто такий бракк","де бракк"}},{q="Де знаходять щоденник?",a="Простий щоденник лежить покинутий десь на просторах Дуротара й чекає, доки його підбере перехожий мандрівник з Орди.",al={"де знайти щоденник","місце загубленого щоденника","початок шукача пригод"}},{q="Чому Бракка цікавить цей щоденник?",a="Бракк стоїть під самим Гострим Пагорбом, на жвавих стежках Дуротара, тож до нього стікаються речі, донесення й мандрівні справи, що проходять серцем земель Орди.",al={"чому нести бракку","мета бракка","щоденник бракка"}},{q="Чи загрожує небезпека шукачеві пригод, що його написав?",a="На знайдених сторінках немає жодних ознак лиха — лише теплі спогади про ночівлі в таборі. Утім, той, хто лишив свій дорожній щоденник у червоному пилу Дуротара, або загубив його ненароком, або несподівано подався далі.",al={"чи автор живий","чи шукач пригод помер","стан загубленого шукача пригод"}}},fp="14,268,18.468.0,17.374.0,32.220.0,22.178.0,13.98.0,27.130.0,39.185.0,41.252.0"}
P.entries["quest:96656"] = {n="Шукач пригод",s="Шукач пригод — вступне завдання, яке Екзекутор Аррен дає загартованим молодим поборникам Відступників за межами Похоронного Подзвону. Довівши надійність в ударах по Багряному Хрестовому Походу, ви вирушаєте дорогою до Брілла — розвідати, що за незнайомка крутиться біля поселення. Замість чергової шпигунки-фанатички завдання знайомить вас з Елеанор Шеклтон — незалежною мандрівницею, яка радо навчить практичних навичок виживання в дикій природі.",h="Шукач пригод — вступне завдання, яке Екзекутор Аррен дає загартованим молодим поборникам Відступників за...",kw={"шукач пригод","елеанор шеклтон","аррен","мандрівниця","виживання","брілл"},ang={["faction:Horde"]="Поки Екзекутор Аррен стереже молоді кордони володінь Відступників, мирний діалог із мандрівними виживальниками дає новачкам Орди цінні практичні навички.",["race:Undead"]="Для свіжих Відступників, що виходять за межі Похоронного Подзвону, зустріч із нейтральними мандрівниками на кшталт Елеанор — ранній урок: не кожен живий смертний у Лордероні одразу здіймає зброю на повернутих мерців."},sec={{t="Підозріла варта",b="Екзекутор Аррен пильно стежить за Похоронним Подзвоном і підступами до нього. Поки Багряний Хрестовий Похід активно шпигує в краї та просочується на північ Лордерону, кожен новоприбулий, помічений біля Брілла, заслуговує негайної перевірки. Побачивши вашу відданість у знищенні загроз від хрестоносців уздовж кордону, Аррен доручає вам тихо розвідати про невідому постать і з'ясувати, чи не становить вона прихованої небезпеки для Відступників."},{t="Мандрівниця в лісі",b="Коли ви знаходите Елеанор Шеклтон на узбіччі дороги біля Брілла, її наміри виявляються дуже далекими і від фанатичних змов Хрестового Походу, і від некромантії Погибелі. Незалежна мандрівниця, що перепочиває перед наступною подорожжю в дику глушину, Елеанор не має жодної ворожості до повсталих мерців. Натомість вона впізнає іскру шукача пригод у тих, кого послали її перевірити, і пропонує поділитися практичними основами виживання у відкритій глушині й облаштування табору."}},faq={{q="Чому Екзекутор Аррен хоче, щоб перевірили Елеанор?",a="Похоронному Подзвону й Бріллу постійно загрожують лазутчики Багряного Хрестового Походу й ворожі шпигуни. Кожного незнайомця, що никає біля великої дороги, вважають підозрілим, доки не з'ясується, що він має добрі наміри.",al={"чому перевіряти елеанор","хто послав мене до елеанор","завдання аррена про елеанор"}},{q="Хто така Елеанор Шеклтон?",a="Елеанор Шеклтон — незалежна шукачка пригод, що отаборилася біля дороги поблизу Брілла. Вона не має жодного стосунку до Багряного Хрестового Походу й захоплена лише мандрами нетрями та тим, щоб ділитися з іншими мандрівниками секретами виживання.",al={"хто така елеанор","переказ про елеанор шеклтон","хто шукач пригод"}},{q="Чи пов'язана Елеанор з Багряним Хрестовим Походом?",a="Ні. Щойно ви прибудете до її табору, Елеанор одразу пояснює, що не має нічого спільного із фанатичними хрестоносцями, які загрожують Галявинам Тірісфалю.",al={"чи елеанор з багряного хрестового походу","елеанор ворог","чи елеанор шпигунка"}},{q="Куди веде це завдання?",a="Доповідь Елеанор відкриває завдання «Широкі простори», у якому вона починає вчити вас основ виживання в нетрях і облаштування табору.",al={"що після шукача пригод","наступне завдання після шукача пригод","продовження елеанор шеклтон"}},{q="Де знайти Елеанор Шеклтон?",a="Вона отаборилася трохи осторонь головної дороги, що веде на схід до містечка Брілл на Галявинах Тірісфалю.",al={"місце елеанор","де елеанор шеклтон","табір елеанор у тірисфалі"}},{q="Чому Екзекутор Аррен обрав для цього доручення саме вас?",a="Ви здобули довіру Аррена, успішно викорінюючи агентів і гінців Багряного Хрестового Походу біля Похоронного Подзвону, і довели, що вам можна доручити делікатну розвідку.",al={"чому саме я","довіра аррена","чому аррен посилає мене"}}},fp="14,455,18.461.0,23.448.0,50.208.0,26.227.0,44.151.0,27.143.0,38.99.0,51.172.0"}
P.entries["quest:96658"] = {n="Табірна наука 101: кулінарія",s="«Табірна наука 101: кулінарія» навчає шукачів пригод-початківців найважливішого мистецтва — розпалювати вогонь і готувати їжу в дикій природі. Цей урок, доступний у початкових поселеннях і Альянсу, і Орди, знайомить із багаттям як головною опорою будь-якого похідного табору просто неба.",h="«Табірна наука 101: кулінарія» навчає шукачів пригод-початківців найважливішого мистецтва — розпалювати...",kw={"табірна наука","кулінарія","багаття","табір","виживання","вогонь"},ang={["faction:Alliance"]="Новачків, що покидають Нортшир, Дун Мороґ чи Тельдрассил, ведуть до таких містечок, як Ґолдшир, Харанос і Доланаар, — учитися самостійності, перш ніж іти в нетрі.",["faction:Horde"]="Виживання для Орди — друга натура, і молодих бійців у Дуротарі, Малгорі та Тірісфалі одразу спрямовують до багать у Гострому Пагорбі, Селі Бладгуф і Бріллі.",["profession:Cooking"]="Кулінарія — буквально іскра табірного життя: вона дає і життєво важливу їжу для відновлення сил, і центральне багаття, без якого не розбити стоянку просто неба."},sec={{t="Вогнище глушини",b="To survive outside fortified walls, every traveler must know how to build a fire. Beyond boiling water and roasting meat, a basic campfire serves as the vital foundation for pitching a camp in uncharted terrain. A basic campfire anchors the campsite this lesson introduces."},{t="Від жарин до таборів",b="Кухарі-підмайстри здатні підтримувати лише скромний вогонь із мінімальним облаштуванням, а опанування кулінарного мистецтва дає змогу розпалювати більші вогнища, здатні підтримувати складніші табори. Ба більше, шукачі пригод, що беруться й за інші практичні ремесла, відкривають способи виготовляти корисні речі, які доповнюють їхні стоянки."}},faq={{q="Навіщо це завдання?",a="Завдання скеровує нових шукачів пригод до місцевого наставника з кулінарії в найближчому поселенні, щоб вони опанували основи куховарства й навчилися розпалювати вогнище — осердя табору просто неба.",al={"навіщо табірна наука 101","мета табірної кулінарії","що робить це завдання"}},{q="Хто дає це завдання мандрівникам?",a="Цю науку в обох фракціях дають різні досвідчені провідники й шукачі пригод, серед них Елеанор Шеклтон, Ерік Брайтгаммер, Лайріна Даскблейд, Сем Сарсапарілла, Бракк, Каґа Вайлдгуф і Раан Вайлдвінд.",al={"хто дає табірну науку 101","видавець табірного завдання"}},{q="Куди здають завдання гравці Альянсу?",a="Шукачі пригод з Альянсу звертаються до таких наставників, як Томас у Ґолдширі, Ґремлок Пілснор у Хараносі чи Заррін у Доланаарі, — залежно від рідного краю.",al={"де здати за альянс","наставник кулінарії альянсу"}},{q="Куди здають завдання гравці Орди?",a="Шукачі пригод з Орди можуть пройти навчання в одного з наставників: Кухар Торка на Гострому Пагорбі, Вільям Пікман у Бріллі або Пайалл Сайлентстрайд у Селі Бладгуф.",al={"наставник кулінарії орди","де здати за орду"}},{q="Чи можна згодом збільшити табір?",a="Yes. As you increase your cooking skill, you can learn to light larger fires that can support more camp furnishings in the wilderness.",al={"більше багаття","покращити табір"}},{q="Чи можуть інші професії стати в пригоді в таборі?",a="Так. Вогнище — осердя табору — дає кулінарія, але й інші наставники ремесел навчать вас виготовляти корисне облаштування для табору, якщо ви опанували їхнє ремесло.",al={"табірні професії","обладнання табору"}}},fp="20,286,28.273.0,26.338.0,34.189.0,35.222.0,39.155.0,36.144.0,36.134.0,44.181.0"}
P.entries["quest:96659"] = {n="Шукач пригод",s="Коли молоді таурени готуються покинути прабатьківські навчальні угіддя на Плато Червоної Хмари, Вождь Гоквінд просить їх про останню послугу. Він довіряє їм клунок необхідних припасів для Каґи Вайлдгуф — досвідченої мандрівниці, що отаборилася біля Села Бладгуф і колись допомогла вождеві в його минулому.",h="Коли молоді таурени готуються покинути прабатьківські навчальні угіддя на Плато Червоної Хмари, Вождь Гоквінд...",kw={"шукач пригод","каґа вайлдгуф","вождь гоквінд","припаси","плато червоної хмари","село бладгуф","малгор"},ang={["faction:Horde"]="Вождь Гоквінд дбає, щоб мандрівні союзники Орди, покидаючи стартове плато, рано зав'язували стосунки з досвідченими мандрівниками й заставами Малгору.",["race:Tauren"]="Для молодих тауренів, що вперше виходять за межі Табору Нарачі, віддати борг честі Гоквінда Казі Вайлдгуф — перше служіння родичам на широких рівнинах Малгору."},sec={{t="Борг вождя",b="Перш ніж мандрівники зійдуть стежкою з плато на широкі рівнини Малгору, Вождь Гоквінд зупиняється, щоб залагодити незакриті особисті борги. Задовго до того, як він узявся вести нові покоління мисливців і шаманів у Таборі Нарачі, Гоквінд перетнувся з Каґою Вайлдгуф. Вождь каже про неї як про досвідчену шукачку пригод: Вайлдгуф надала вкрай потрібну допомогу, коли він найбільше її потребував. Почувши, що вона розбила табір одразу за Селом Бладгуф, Гоквінд користається відходом щойно випробуваних новачків, щоб послати харчі своїй давній добродійниці."},{t="Прощання з плато",b="Це доручення — ключовий обряд посвяти для молодих звитяжців Орди, що покидають Плато Червоної Хмари. Стежка вниз із плато веде просто до Села Бладгуф — культурного й господарського серця центрального Малгору. Несучи клунок із припасами через рівнини, ви з'єднуєте затишне навчальне життя плато з ширшою, дикішою боротьбою Об'єднаних Племен Тауренів."}},faq={{q="Хто така Каґа Вайлдгуф?",a="Каґа Вайлдгуф — бувала шукачка пригод із тауренів, що нещодавно отаборилася під самим Селом Бладгуф. Її пов'язує давня дружба з Вождем Гоквіндом: колись вона дуже йому допомогла.",al={"каґа вайлдгуф","хто такий вайлдгуф","де каґа"}},{q="Чому Вождь Гоквінд посилає ці припаси?",a="Гоквінд вважає, що молоді звитяжці, які вирушають до Села Бладгуф, — чудова нагода віддячити Вайлдгуф за давню послугу й подбати, щоб його подруга-мандрівниця мала свіжі припаси в дорогу.",al={"борг гоквінда","чому надсилати припаси","призначення згортка припасів"}},{q="Де табір Каґи Вайлдгуф?",a="Її табір — на рівнині під самим Селом Бладгуф, унизу звивистої південної стежки, що веде з Плато Червоної Хмари в центр Малгору.",al={"місце табору каґи","знайти каґу","табір села бладгуф"}},{q="Коли стає доступним це завдання?",a="Вождь Гоквінд дає це доручення, щойно мандрівник доведе свою звитягу на Плато Червоної Хмари й буде готовий вирушити на ширші простори Малгору.",al={"коли я отримаю шукача пригод","час завдання гоквінда","завдання виходу з плато"}},{q="Чи виводить це завдання з Табору Нарачі?",a="Так. Доставка припасів прямо спонукає покинути Табір Нарачі й вирушити стежкою до Села Бладгуф.",al={"вихід із плато червоної хмари","подорож до бладгуфа"}},{q="Що в Згортку Припасів?",a="У згортку — найнеобхідніші харчі, зібрані племенами Табору Нарачі, щоб шукач пригод міг вижити поза облаштованими поселеннями.",al={"що за припаси","вміст згортка припасів"}}},fp="14,306,23.521.0,16.370.0,21.217.0,44.208.0,38.139.0,38.157.0,48.133.0,43.148.0"}
P.entries["quest:967"] = {n="Вежа Альталакса",s="Це завдання пов'язує розслідування діяльності культу Темного Берега на півночі Темного Узбережжя з ширшою обороною півночі Калімдору. Балтул Шедовстрайк посилає кур'єра Альянсу на південь, до Посту Маестри в Ашенвалі, щоб попередити свого наставника Делґрена Очищувача про зловісне зібрання культу у Вежі Альталакса.",h="Це завдання пов'язує розслідування діяльності культу Темного Берега на півночі Темного Узбережжя з ширшою...",kw={"вежа альталакса","балтул шедовстрайк","делґрен очищувач","пост маестри","культ темного берега","паладин"},ang={["class:Paladin"]="Зустріч із Делґреном дає паладинам надихаючий приклад їхнього святого покликання в незнайомих землях: хрестоносець-людина, що орудує Світлом, здобуває глибоку довіру потайних нічних ельфів Калімдору.",["faction:Alliance"]="Співпраця Балтула на Темному Узбережжі й Делґрена в Ашенвалі показує, які важливі лінії зв'язку пов'язують розкидані гарнізони Альянсу на півночі Калімдору.",["race:NightElf"]="Для нічних ельфів ця місія свідчить про дедалі міцніше практичне партнерство між їхніми Вартовими й східними народами, що прийшли допомогти вичистити демонічні рештки з їхніх лісів."},sec={{t="Благання про підкріплення",b="Після перших сутичок із культистами Темного Берега довкола Вежі Альталакса розвідник із нічних ельфів Балтул Шедовстрайк розуміє, що загроза перевершує його самотню варту. Щоб дати рішучу відсіч, він пише докладне донесення й довіряє його посланцеві Альянсу для свого наставника — Делґрена Очищувача. Заклиначі культу сміливішають щогодини, тож звістка має дійти до досвідченого проводу, здатного очолити їх викорінення."},{t="Дорога до Ашенвалю",b="Щоб доставити донесення Балтула, доведеться пройти все Темне Узбережжя — довгим прибережним трактом на південь, з імли, через лісистий кордон до Ашенвалю. Делґрен Очищувач, що стоїть на Посту Маестри біля західної дороги, присвятив себе вичищенню демонів і нежиті, що досі блукають лісом. Хоч паладин-людина спершу не знав звичаїв нічних ельфів, він здобув глибоку взаємну повагу Вартових як незамінний союзник."},{t="Пробудження святого воїна",b="Делґрен отримує нагальний лист Балтула з похмурою рішучістю. Як воїн, відданий Святому Світлу, він вважає присутність темних культистів, порчі душ і демонічних потвор у цих давніх лісах нестерпною пошестю. Прочитавши, як міцно Темний Берег закріпився у зруйнованій вежі Високородних, Делґрен негайно готується очолити операцію й завдати удару у відповідь."}},faq={{q="Хто такий Делґрен Очищувач?",a="Делґрен Очищувач — паладин із людей, що перебуває на Посту Маестри в Ашенвалі. Відданий Святому Світлу, він ділиться своєю бойовою й духовною майстерністю з Вартовими нічних ельфів, щоб очищати їхні прадавні ліси від демонів і нежиті.",al={"делґрен очищувач","хто такий делґрен","переказ про делґрена"}},{q="Чому Балтул Шедовстрайк посилає гінця до Ашенвалю?",a="Балтул — розвідник біля Вежі Альталакса, що вивчає культ Темного Берега. Розуміючи, що темних обрядів культу й самих культистів стрімко більшає, він надсилає свої відомості наставникові Делґрену, щоб той організував удар.",al={"чому балтул надсилає листа до ашенвалю","причина листа балтула"}},{q="Що пов'язує Балтула й Делґрена?",a="Делґрен — наставник Балтула. Паладин із людей навчив нічного ельфа бойового мистецтва й познайомив його з ученням Святого Світла, і між ними, попри культурні відмінності, склалися незвично тісні узи.",al={"балтул і делґрен","як балтул і делґрен знайомі"}},{q="Де Пост Маестри?",a="Пост Маестри — застава Альянсу на заході Ашенвалю, біля головної дороги, що веде на південь із Темного Узбережжя. Це перший вартовий пункт для мандрівників між Темним Узбережжям і глибинами лісу.",al={"місце поста маестри","де пост маестри"}},{q="Що культ Темного Берега робить біля Вежі Альталакса?",a="Темний Берег — культ, що діє з руїн Вежі Альталакса, колишньої оселі Високородних на півночі Темного Узбережжя. Культисти практикують темні мистецтва, знаються з демонічними силами й загрожують наслати скверну на все узбережжя.",al={"культ темного берега альталакс","культисти вежі альталакса"}},{q="Як Делґрен ставиться до союзу з нічними ельфами?",a="Делґрен визнав, що, тільки прибувши до Калімдору, ніяк не міг звикнути до звичаїв і способу життя нічних ельфів. Але з часом, стоячи пліч-о-пліч із ними проти спільного зла, він пройнявся глибокою повагою до Вартових.",al={"делґрен і нічні ельфи","людський паладин і нічні ельфи"}}},fp="22,322,25.469.0,21.486.0,23.383.1,28.252.0,62.264.0,54.217.0,24.221.0,61.223.0,56.246.0"}
P.entries["quest:968"] = {n="Сили з глибин",s="Це завдання Альянсу дає Тундріс Віндвівер в Обердайні. Мандрівників посилають на південь, у розбиті руїни Амет'Арана, щоб вирвати магічні реліквії з рук неспокійних примар Високородних. Мета проста: повернути ці давні артефакти, доки їхнє приспане чаклунство не наробило Калімдору ще більше лиха.",h="Це завдання Альянсу дає Тундріс Віндвівер в Обердайні.",kw={"реліквія високородних","тундріс віндвівер","амет'аран","привиди","високородні","темне узбережжя"},ang={["class:Druid"]="Очищаючи Амет'Аран від зіпсованих тайних решток, ви допомагаєте загоїти духовні рани, що порушують природний спокій нетрів Темного Узбережжя.",["class:Mage"]="Суспільство калдореїв зі страху прагне розбити ці артефакти, але вчені тайних мистецтв бачать у них рідкісні, бездоганні зразки ремесла Високородних доби до Розколу.",["faction:Alliance"]="Допомагаючи нічним ельфам убезпечити їхні примарні землі, ви зміцнюєте присутність і згуртованість Альянсу в давніх лісах півночі Калімдору.",["race:NightElf"]="Для калдореїв зустріч із привидами Амет'Арана — сумне нагадування про пиху предків і катастрофічний розкол їхньої давньої імперії."},sec={{t="Відлуння в руїнах",b="На південь від Обердайна, на схід від прибережного тракту, лежать зарослі кам'яні фундаменти Амет'Арана. Десять тисяч років тому це поселення було оплотом Високородних — привілейованої знаті давньої імперії нічних ельфів. Коли їхні неприборкані тайні забави завершилися Розколом світу, Амет'Аран розлетівся на друзки. Та його мешканці так і не пішли по-справжньому. Вартові, що патрулюють Темне Узбережжя, доповідають: привиди цих аристократів досі блукають запалими площами, стискаючи зачаровані знаряддя й дрібнички, якими володіли за життя."},{t="Очистити тайне минуле",b="Для сучасного суспільства калдореїв тайна магія — не просто заборонене знання, а екзистенційна небезпека, що мало не знищила життя в Азероті. Тундріс Віндвівер розуміє: лишити ці знаряддя Високородних у примарних руках — означає лишити порчі відчинені двері. Посилаючи шукачів пригод вирвати реліквії в неспокійних духів, Тундріс хоче остаточно їх знищити, щоб приспане зіпсоване чаклунство більше ніколи не живило нового лиха."}},faq={{q="Де знайти реліквії Високородних?",a="Реліквії — у руїнах Амет'Арана, на південь від Обердайна, на схід від головної дороги Темним Узбережжям. Ці давні знаряддя носять духи, що блукають зруйнованими кам'яними дворами.",al={"де реліквії","місце амет'арана","де знайти реліквії"}},{q="Хто такий Тундріс Віндвівер?",a="Тундріс Віндвівер — учений і старійшина нічних ельфів у портовому Обердайні. Тісно співпрацюючи з місцевими Вартовими, він організовує захист Темного Узбережжя від залишків магічної скверни й давніх прокльонів, що лишилися по Розколу.",al={"тундріс віндвівер","хто дає знаряддя високородних"}},{q="Чому Тундріс хоче знищити ці реліквії?",a="Суспільство нічних ельфів суворо відкидає тайну магію через нищівний Великий Розкол, спричинений безрозсудним чародійством Високородних. Тундріс боїться, що тайна сила, яка досі жевріє в цих предметах, може пробудити приспане зло, якщо її не стримати.",al={"чому знищити реліквії","мета знарядь високородних"}},{q="Які духи блукають в Амет'Арані?",a="Це примарні рештки знаті Високородних, що загинула у Війні Прадавніх. Навіть по смерті вони чіпляються за колишню гордість, владу й магічні артефакти, знову й знову переживаючи своє зблякле життя серед зруйнованого каміння.",al={"привиди амет'арана","що за духи"}},{q="Чому Високородні досі прикуті до руїн?",a="Раптова, катастрофічна руїна під час Розколу прокотилася імперією з такою магічною люттю, що безліч душ лишилися в пастці — прикуті потрясінням і тайним відлунням до руїн своїх колишніх домівок.",al={"чому вони привиди","прокляття високородних"}},{q="Що стається з реліквіями, коли ви їх здаєте?",a="Тундріс Віндвівер забирає зібрані реліквії, маючи твердий намір розібрати й знищити їх назавжди, щоб їхню приспану тайну скверну ніколи більше не можна було ні використати, ні вивільнити.",al={"що тундріс робить із реліквіями","доля реліквій"}}},fp="22,360,19.561.0,23.480.0,37.224.0,27.257.0,46.238.0,38.236.0,47.216.0,50.202.0"}
P.entries["quest:97"] = {n="Легенда про Сталвана",s="Цей етап розслідування нарешті підтверджує зловісну правду, що пов'язує невловимого вчителя із записами Даркшира. Писар Долтрі встановлює, що почерк на знайдених документах належить Сталванові Містмантлу, і про це негайно доповідають Командирові Алтеї Ебонлок. Саме тоді підозри Нічної Варти тверднуть у незаперечний факт.",h="Цей етап розслідування нарешті підтверджує зловісну правду, що пов'язує невловимого вчителя із записами...",kw={"легенда про сталвана","писар долтрі","алтея ебонлок","сталван містмантл","нічна варта","даркшир"},ang={["faction:Alliance"]="Для слідчих Альянсу розплутування сліду Сталвана показує, наскільки важлива співпраця між знесиленим проводом Даркшира й мандрівними шукачами пригод, щоб уберегти південні землі королівства.",["race:Human"]="Люди бачать тут відображення трагічного занепаду власного суспільства: і шановані вчителі, і сільські містечка тихо зісковзують від цивілізації в божевілля й самотність."},sec={{t="Збіг у записах",b="Після пошуків у далеких маєтках, корчмах і міських архівах людських королівств розпорошений слід повертається до ратуші Даркшира. Писар Долтрі оглядає знайдені зразки почерку й порівнює їх із місцевими реєстрами. Висновок однозначний: почерк належить Сталванові Містмантлу. Будь-які сумніви в тому, чи справді вчитель бував у Сутінколіссі, розвіюються, і Нічна Варта отримує вагомий доказ, щоб узятися до справи як до нагальної місцевої загрози."},{t="Підозри Нічної Варти",b="Командир Алтея Ебонлок від самого початку розслідування мала похмурі передчуття щодо Сталвана. Сутінколісся й так прогинається під тягарем диких воргенів, кістяної нежиті й причаєних некромантів; невідомий убивця, що ховається в тінях лісу, — небезпека, яку вона не може ігнорувати. Підтвердження від Долтрі справджує її найчорніші побоювання, і Нічна Варта береться розшукати й знешкодити відлюдника раз і назавжди."}},faq={{q="Що з'ясував Писар Долтрі?",a="Писар Долтрі порівняв записи, зібрані вами в мандрах, з офіційними документами й підтвердив, що почерк точно збігається з почерком Сталвана Містмантла. Це довело, що підозрюваний — той самий учитель, який колись жив у містечку.",al={"що з'ясував долтрі","збіг почерку долтрі","доказ почерку сталвана"}},{q="Чому Командир Алтея Ебонлок так переймається Сталваном?",a="Командир Алтея Ебонлок очолює Нічну Варту — знесилену ополченську варту Даркширу. У краї, де й так повно жахіть, вона не може дозволити, щоб жорстока темна постать із лихим минулим вільно й безкарно розгулювала в межах Сутінколісся.",al={"чому алтея дбає","розслідування ебонлок","нічна варта сталван"}},{q="Де відбувається цей етап?",a="Увесь цей етап відбувається в містечку Даркшир. Писар Долтрі — у ратуші, а Командир Алтея Ебонлок патрулює неподалік, на центральних вулицях містечка.",al={"де цей етап","місце завдання","здача сталвана в даркширі"}},{q="Що буде після доповіді про збіг почерку?",a="Щойно Командир Ебонлок отримає підтвердження від Писаря Долтрі, розслідування переходить до активних пошуків Сталвана в моторошних нетрях Сутінколісся.",al={"що після збігу почерку","після долтрі","наступний крок ланцюжка сталвана"}},{q="Ким спершу був Сталван Містмантл?",a="Сталван Містмантл був шкільним учителем і домашнім наставником, родом із Сутінколісся. Подавшись шукати роботу на чужині, він пережив темний і трагічний злам, що зрештою повернув його в рідні ліси небезпечним відлюдником.",al={"ким був сталван","минуле сталвана","історія сталвана містмантла"}},{q="Навіщо знадобилося порівнювати почерк?",a="Події й звинувачення, пов'язані зі Сталваном, відбувалися в різних краях, зокрема в Мунбруку й Ґолдширі, тож офіційні записи були розрізнені. А в міських книгах Даркширу зберігалися перевірені місцеві зразки, що могли остаточно пов'язати чужі сліди саме з цією людиною.",al={"навіщо порівнювати почерк","чому долтрі перевіряв почерк","доказ особи сталвана"}}},fp="21,363,22.508.0,28.456.1,31.246.0,63.241.0,32.202.0,51.186.0,38.225.0,39.282.0"}
P.entries["quest:970"] = {n="Вежа Альталакса",s="Це завдання — переломний момент у розслідуванні зловісного Культу Темного Берега: переслідування переходить від зруйнованої Вежі Альталакса на Темному Узбережжі через кордон до Посту Маестри в Ашенвалі. Делґрен Очищувач посилає шукачів пригод у сусідні табори культистів, щоб здобути могутній Сяйливий Самоцвіт Душі. Розгадавши цей артефакт, можна побачити похмуре чаклунство, що живить вплив культу на північні ліси.",h="Це завдання — переломний момент у розслідуванні зловісного Культу Темного Берега: переслідування переходить...",kw={"вежа альталакса","культ темного берега","делґрен очищувач","самоцвіт душі","сарґат","ордил'аран"},ang={["class:Paladin"]="Очищати темні вмістища душ і рубати спотворених культистів — саме те, до чого покликаний паладин, що викорінює нечестиву порчу зі світу.",["class:Priest"]="Дослідження темного вмістища душі перегукується з покликанням жерця — протистояти порчі й нести розраду змученим душам.",["faction:Alliance"]="Злагоджені дії застав на Темному Узбережжі й в Ашенвалі убезпечують північний рубіж від темних чаклунів, що загрожують мандрівникам Альянсу.",["race:NightElf"]="Мерзенні культисти, що оскверняють давні руїни на кшталт Ордил'Арана й нівечать північні ліси, роблять знищення Культу Темного Берега нагальною справою для кожного нічного ельфа."},sec={{t="Благання через кордон",b="Після того як довкола Вежі Альталакса на півночі Темного Узбережжя виявили зловісну діяльність, донесення повели просто на південь, до Ашенвалю, — до Делґрена Очищувача. Перебуваючи на Посту Маестри, Делґрен давно протистоїть Культові Темного Берега, що вдирається в давні ельфійські ліси. Розуміючи, що загроза культу охоплює обидва краї, Делґрен вирішує вдарити в саме серце їхнього мерзенного чаклунства."},{t="Таємниці Ордил'Арана",b="На північний схід від Посту Маестри лежать Руїни Ордил'Аран, які тепер заполонили фанатичні культисти Темного Берега. Делґрен з'ясовує, що їхні посланці носять сяйливі самоцвіти душі — темні вмістища, зачаровані зловісною магією, що підтримує силу культу. Вистеживши культистів серед руїн і здобувши один із цих самоцвітів, Делґрен хоче зламати їхні чари й викрити справжнє джерело їхнього лиховісного обряду."},{t="Ув'язнений дух",b="Розгадавши мерзенні чари, вплетені в сяйливий самоцвіт душі, Делґрен знаходить не лише темні заклинання — він розплутує вмістище муки. Зламавши захист самоцвіту, він вивільняє дух Сарґата — одного з ельфів Амет'Арана, якого Атрікус Нарассін під час Розколу ув'язнив у самоцвіті душі й відтоді повільно висмоктує. Примара називає ім'я помічника Атрікуса — Ілкруда Маґтрулла, чий фоліант може розкрити, де зберігаються решта самоцвітів душі."}},faq={{q="Де знайти Сяйливий Самоцвіт Душі?",a="Сяйливий Самоцвіт Душі — у членів Культу Темного Берега, що засіли на північний схід від Посту Маестри, у Руїнах Ордил'Аран в Ашенвалі. Його носять різні культисти, що чаяться в руїнах, хоча, щоб його здобути, доведеться трохи потрудитися.",al={"де сяйливий самоцвіт душі","звідки випадає самоцвіт душі","самоцвіт душі темного берега"}},{q="Хто такий Делґрен Очищувач?",a="Делґрен Очищувач — звитяжець Альянсу на Посту Маестри на півночі Ашенвалю. Він завзято бореться з лихими силами, що вдерлися в ліс, і передусім вистежує й нищить Культ Темного Берега.",al={"делґрен","хто такий делґрен"}},{q="Що таке Культ Темного Берега?",a="Культ Темного Берега — лиха секта, що діє з Вежі Альталакса на Темному Узбережжі й давніх ельфійських руїн на кшталт Ордил'Арана в Ашенвалі. Її члени практикують темне чаклунство, ув'язнення душ і некромантичні обряди.",al={"культ темного берега","хто темний берег"}},{q="Чому завдання з Темного Узбережжя посилає мене в Ашенваль?",a="Розслідування починається біля Вежі Альталакса на Темному Узбережжі, але мережа культу тягнеться на південь, за межу, в Ашенваль. А Делґрен Очищувач на Посту Маестри знає, як протидіяти чарам культу, що ув'язнюють душі.",al={"чому пост маестри","чому йти в ашенваль"}},{q="Що станеться, коли самоцвіт душі буде розгадано?",a="Делґрен збирається розгадати темні чари на Сяйливому Самоцвіті Душі. Що він знайде, з'ясується, коли ви принесете йому самоцвіт.",al={"що в самоцвіті душі","привид самоцвіту душі"}},{q="Де Ордил'Аран?",a="Ордил'Аран — давні ельфійські руїни трохи на північний схід від Посту Маестри на півночі Ашенвалю, що їх нині заполонив Культ Темного Берега.",al={"місце ордил'арана","де ордил'аран"}}},fp="22,428,24.417.0,25.426.0,16.471.1,37.251.0,28.239.0,36.222.0,49.245.0,45.132.1,28.151.0"}
P.entries["quest:97005"] = {n="Чол'арук Пожирач",s="Чол'арук Пожирач — страхітлива потворна гидота, що ховається в печері на Тернистому Пагорбі в Пустках. Місцеві Гостромани звуть її Чол'аруком, тобто «Пожирачем», а чутки кажуть, що ця істота така велика, що може проковтнути орка цілком. Бейнгем прагне здобути її відтяту голову, щоб помститися за товаришів, загиблих від подібних жахіть.",h="Чол'арук Пожирач — страхітлива потворна гидота, що ховається в печері на Тернистому Пагорбі в Пустках.",kw={"чол'арук пожирач","тернистий пагорб","бейнгем","гидота","гостромани","пустки"},ang={["class:Hunter"]="Зустрітися з легендарним верховним хижаком, про якого кажуть, що він ковтає воїнів у повних обладунках цілком, — найвище випробування вправності й нервів слідопита.",["class:Warrior"]="Прохання Бейнгема промовляє просто до кодексу воїна: помститися за полеглих товаришів, кинувши виклик височенному жахіттю в його підземному лігві.",["faction:Horde"]="Чудовиська, що безкарно никають високими плато, загрожують мандрівникам і караванам, які пробираються через Пустки, тож знищення звіра — питання безпеки всього краю."},sec={{t="Жах Тернистого Пагорба",b="На північний захід від того місця, де в Пустках чекає Бейнгем, лежить плато, відоме як Тернистий Пагорб, — за нього здавна змагаються місцеві племена Гостроманів. Останнім часом пошепки ширяться чутки про жахливу присутність, що засіла в одній із його печер: потворну гидоту, яку Гостромани звуть Чол'аруком, тобто «Пожирачем». Багато мандрівників вважають розповіді про звіра, здатного одним ковтком проковтнути орка в обладунках, байками біля вогнища, але ті, хто на власні очі бачив різанину, знають, що загроза цілком реальна."},{t="Сплачений рахунок",b="Для Бейнгема Чол'арук — аж ніяк не міф. Він уже стикався з подібними жахіттями, носить на собі шрами й оплакує товаришів, що загинули від таких звірів. Знаючи, яку небезпеку становить ненажерлива гидота для всіх, хто мандрує саваною, він доручає досвідченим звитяжцям піднятися на плато, прорватися в підземне лігво, убити Чол'арука й забрати його величезну голову."}},faq={{q="Що за істота Чол'арук?",a="Чол'арук — страхітлива потвора, що чаїться в печері на Тернистому Пагорбі. Кажуть, вона така велетенська, що може проковтнути дорослого орка цілком, тож місцеві Гостромани прозвали її моторошним ім'ям «Пожирач».",al={"що за істота чол'арук","тип чудовиська чол'арука","хто пожирач"}},{q="Де лігво Чол'арука?",a="Чол'арук влаштував лігво в печері на високому плато Тернистого Пагорба, на північному заході Пусток.",al={"де чол'арук","місце чол'арука","печера терновий пагорб"}},{q="Хто такий Бейнгем і чому він хоче смерті Чол'арука?",a="Бейнгем, якого можна зустріти в Пустках, уже має досвід боротьби з такими звірами. Колись він утратив соратників через подібних потвор, тож прагне смерті Чол'арука заради честі й помсти за полеглих товаришів.",al={"хто дає чол'арука","чому вбити чол'арука","переказ про бейнгема"}},{q="Що означає «Пожирач»?",a="Місцеві шипогриви Гостромани дали Чол'арукові це ім'я через його ненаситну, ненажерливу вдачу: за чутками, він без вагань ковтає дорослих воїнів цілком.",al={"значення пожирача","чому називають пожирачем","гостромани і чол'арук"}},{q="Шипогриви Гостромани шанують Чол'арука чи бояться його?",a="Поки що невідомо. Гостромани називають цю істоту Чол'аруком або «Пожирачем», але в завданні не сказано, чи вони бояться страхітливої потвори, що ховається в печері на Тернистому Пагорбі, чи поклоняються їй.",al={"чи вепролюди люблять чол'арука","гостромани та чол'арук"}},{q="Який доказ потрібен, щоб підтвердити смерть Чол'арука?",a="Бейнгем просить принести відрубану голову Чол'арука — незаперечний доказ того, що потвору знищено.",al={"здати чол'арука","що принести бейнгему"}}},fp="21,309,20.512.0,15.379.0,35.232.0,34.114.0,51.209.0,29.172.0,52.195.0,52.125.0"}
P.entries["quest:971"] = {n="Знання в глибинах",s="«Знання в глибинах» — завдання Альянсу, яке дає Ґерріґ Боунґріп у Покинутій Печері Айронфорджа. Він посилає шукачів пригод за море, до затоплених руїн Чорноглибинних Печер в Ашенвалі, по давній Рукопис Лорґаліса. Під личиною вченого Боунґріп приховує зловісні наміри, пов'язані з темними сутностями й пророцтвами про кінець світу.",h="«Знання в глибинах» — завдання Альянсу, яке дає Ґерріґ Боунґріп у Покинутій Печері Айронфорджа.",kw={"ґерріґ боунґріп","рукопис лорґаліса","айронфордж","покинута печера","чорноглибинні печери","ті, що сплять"},ang={["class:Warlock"]="Боунґріп діє пліч-о-пліч із чорнокнижниками, що ховаються в Покинутій Печері Айронфорджа, і поділяє їхній голод до заборонених текстів, які розхитують межі світів.",["faction:Alliance"]="Допомога вченому з Альянсу здається нешкідливою, але справжні мотиви Боунґріпа та його темні спільники натякають на лихі задуми просто в стінах Айронфорджа."},sec={{t="Учений у тінях",b="Сховавшись у сирих закутках Покинутої Печери Айронфорджа, Ґерріґ Боунґріп видає себе за відданого збирача давніх текстів. Та в його наукових пошуках виразно бринить щось лиховісне. Звичайна історія чи міські хроніки Боунґріпа не цікавлять: він відверто полює на забуті знання, здатні відчинити двері й пробудити «Тих, Що Сплять». Його балачки про те, як вижити після «останніх днів», видають у ньому або дивака, або небезпечного прихильника темних сил, що дрімають."},{t="Затонулі руїни Лорґаліса",b="Bonegrip directs seekers halfway across Azeroth to the shadowed shores of Ashenvale, where the ancient night elven sanctuary of Blackfathom Deeps lies drowned. Before the Great Sundering tore Kalimdor apart, night elven scholars gathered immense magical knowledge in their coastal temples. Amidst the flooded corridors, now crawling with naga, satyrs, and Twilight's Hammer cultists, rests the Lorgalis Manuscript—a text of forbidden lore kept in a Pitted Iron Chest."},{t="Брати й сестри",b="When presented with the watersoaked manuscript, Bonegrip makes no effort to file it in Ironforge's Hall of Explorers. Instead, he openly rejoices that duplicates will be produced and disseminated among his mysterious 'brothers and sisters.' While grateful to the Alliance adventurer who retrieved it, Bonegrip's loyalties clearly lie with a clandestine sect eager to utilize the recovered lore for esoteric, world-altering rites. Bonegrip is associated with the Twilight's Hammer, whose followers seek forbidden knowledge of the Old Gods."}},faq={{q="Хто дає завдання «Знання в глибинах»?",a="Завдання дає Ґерріґ Боунґріп — дворф-шукач давніх знань, що мешкає в тьмяній Покинутій Печері в дворфійському гірському місті Айронфордж.",al={"хто дає знання в глибинах","де взяти завдання","хто починає знання в глибинах"}},{q="Що таке Рукопис Лорґаліса?",a="The Lorgalis Manuscript is a text Gerrig Bonegrip wants recovered from Blackfathom Deeps. It is kept in a Pitted Iron Chest among the flooded ruins.",al={"що таке рукопис лорґаліса","переказ про лорґаліса","яку книгу знайти"}},{q="Де Рукопис Лорґаліса?",a="Рукопис лежить глибоко в підземеллі Чорноглибинні Печери на Зорамському Узмор'ї, на північно-західному узбережжі Ашенвалю в Калімдорі.",al={"місце рукопису лорґаліса","де книга в чорноглибинних печерах","місце книги в печерах"}},{q="Хто такі «Ті, що Сплять», про яких згадує Ґерріґ Боунґріп?",a="Bonegrip uses this cryptic name for the slumbering powers described in the forbidden lore he collects. The quest's protected sections explore his darker connections.",al={"ті, що сплять","про кого говорить боунґріп","чому поклоняється ґерріґ"}},{q="Хто ці «брати й сестри», з якими Ґерріґ хоче поділитися рукописом?",a="Bonegrip's associates share his interest in forbidden lore. Recovering the manuscript can reveal more about whom he serves.",al={"брати й сестри ґерріґа","на кого працює ґерріґ","фракція боунґріпа"}},{q="Чому завдання з Айронфорджа посилає гравців аж до Ашенвалю?",a="Покинута Печера в Айронфорджі приваблює магів без дозволу, чорнокнижників і розбійників, що шукають таємниць, прихованих від світла. Боунґріп збирає давні могутні знання, а Рукопис Лорґаліса, якого він прагне, за чутками, лежить на дні Чорноглибинних Печер в Ашенвалі — давній оселі давно загиблих ельфів, що володіли великими знаннями.",al={"чому йти в ашенваль","завдання з айронфорджа до печер","подорож до чорноглибинних печер"}}},fp="22,354,24.495.0,27.469.0,20.538.1,43.154.0,32.148.0,41.146.0,55.165.0,77.123.1,68.325.0"}
P.entries["quest:972"] = {n="Водяна Сапта",s="«Водяна Сапта» — перехідне доручення, яке дає молодим шаманам Орди Іслен Вотерсір на узбережжі Пусток. Отримавши обрядовий напій, шаман вирушає за Велике море, у сплюндровані землі Срібнолісся, щоб зустрітися з оскверненим джерелом.",h="«Водяна Сапта» — перехідне доручення, яке дає молодим шаманам Орди Іслен Вотерсір на узбережжі Пусток.",kw={"водяна сапта","сапта","іслен вотерсір","срібнолісся","тотем води","шаман"},ang={["class:Shaman"]="Водяна Сапта — важливий поворот у ваших стихійних випробуваннях: вона відкриває вам очі на світ духів, перш ніж ви здобудете владу над цілющим Тотемом Води.",["faction:Horde"]="Випробування показує міжконтинентальну єдність нової Орди: новачків посилають із вибілених сонцем рівнин Калімдору в примарні ліси Лордерону."},sec={{t="Видіння води",b="У стихійних традиціях шаманів Орди сапта — алхімічний напій, створений, щоб налаштувати чуття просто на духів світу. Звичайні очі бачать лише спокійні струмки чи стоячі ставки, а сапта пронизує завісу фізичного світу й відкриває стихійних істот, що живуть у течії."},{t="Дорога до Срібнолісся",b="Шаман, що довів свою відданість духам, отримує напій просто з рук Іслен Вотерсір — самітниці, що живе на пустельних берегах на південь від Раджета. Замість того щоб випробувати сапту в посушливих долинах Калімдору, Іслен велить новачкові вирушити далеко за Велике море, у похмурі, покинуті ліси Срібнолісся, щоб протистояти стихійній скверні, що отруює струмки Лордерону."}},faq={{q="Що таке водяна сапта?",a="Сапта — обрядовий еліксир, який готують шаманські наставники. Випита, вона загострює духовне чуття, і той, хто її скуштував, може бачити духів стихій, незримих для смертного ока, й говорити з ними.",al={"що таке водяна сапта","значення водяної сапти","що робить сапта"}},{q="Хто така Іслен Вотерсір?",a="Іслен Вотерсір — майстриня-шаманка, що живе в самотніх роздумах на східному узбережжі Пусток, на південь від Торгового Узбережжя. Вона веде молодих шаманів Орди тяжким шляхом єднання зі стихією води.",al={"переказ про іслен вотерсір","хто така іслен"}},{q="Чому шаман мусить вирушити до Срібнолісся?",a="Духи стихії води в Срібноліссі тяжко потерпають від скверни. Щоб завершити посвяту, шаман має перевезти сапту через море, на власні очі побачити зіпсоване джерело води й очистити його від скверни.",al={"чому срібнолісся","чому східні королівства"}},{q="Що станеться, коли випити сапту?",a="Випивши водяну сапту, шаман бачить зіпсованих водяних елементалів, що чаяться в отруєних озерцях Срібнолісся, і може зустрітися з джерелом тління.",al={"випити сапту","дія сапти"}},{q="Чи обов'язкове це випробування для всіх шаманів Орди?",a="Так. Шамани-орки, таурени й тролі однаково мусять відгукнутися на «Поклик води» й отримати цю сапту як неодмінний обряд посвяти, перш ніж здобути свій Тотем Води.",al={"хто бере це завдання","чи це класове завдання"}},{q="Де в Срібноліссі зіпсоване озерце?",a="Зіпсоване джерело — на узбережжі Срібнолісся, на захід від Гробниці.",al={"місце озерця срібнолісся","де водяне озерце"}}},fp="11,256,17.335.0,22.426.0,22.231.0,23.239.0,48.240.0,38.177.0,44.162.0,50.86.0"}
P.entries["quest:97279"] = {n="Заблукала зброя",s="Заблукала зброя — раннє тренувальне завдання в Долині Випробувань, яке дає наглядач Ґорнек. Молоді воїни прибувають юрбами, щоб служити Орді, і зброї не вистачає. Щоб довести свою дисципліну й підтримати табір, новобранці обшукують чагарі, збираючи спорядження, покинуте менш здібними попередниками.",h="Заблукала зброя — раннє тренувальне завдання в Долині Випробувань, яке дає наглядач Ґорнек.",kw={"заблукала зброя","ґорнек","кзан торнслеш","зброяр","долина випробувань","новобранці"},ang={["class:Warrior"]="Повага до зброї — основа для будь-якого воїна. Збирання зброї, яку покидали невдалі новобранці, наголошує на дисципліні й самостійності ще до справжнього бою.",["faction:Horde"]="Орда виживає в Дуротарі завдяки впертості й кмітливості, відмовляючись марнувати зброю навіть тоді, коли її покинули ті, хто не гідний її носити.",["profession:Blacksmithing"]="У Дуротарі на вагу золота кожен клапоть металу. Допомога Кзанові зібрати зіпсоване спорядження відображає обов'язок коваля повертати залізо й перековувати побиті леза на придатні знаряддя війни."},sec={{t="Озброїти нову кров",b="Долина Випробувань — кузня, де сирих новобранців гартують суворі червоні пустки Дуротару. Безліч претендентів виходить уперед, щоб присягнути своїми клинками вождю, і запаси зброї в таборі напружені до краю. Зброяр Кзан Торнслеш ледве встигає за попитом, особливо коли перші уроки виявляються смертельними або принизливими для неготових."},{t="Випробування кмітливості",b="Наглядач Ґорнек обертає цю нестачу на практичне випробування. Замість марнувати новий метал, він посилає новоприбулих збирати покинуті клинки й тупу тренувальну зброю, залишену невдахами, що впали або втекли в пилюці. Доставка зібраної зброї Кзанові дає ковалеві змогу полагодити й загартувати її для наступної хвилі, а новачків навчає: виживання в Орді вимагає не лише махати сталлю, а й збирати її."}},faq={{q="Чому довкола стільки покинутої навчальної зброї?",a="Не кожен охочий, що ступає в Долину Випробувань, має силу й рішучість, яких вимагає Орда. Боязкі чи недбалі новобранці раз у раз кидають спорядження в паніці або гинуть від місцевих кабанів і скорпідів, і видана їм зброя валяється в пилюці.",al={"чому тут стільки зброї","покинута зброя дуротару","зброя невдалих новобранців"}},{q="Хто такий Кзан Торнслеш?",a="Кзан Торнслеш — місцевий зброяр у Лігві в Долині Випробувань. Він споряджає новобранців, лагодить пошарпане навчальне спорядження й дбає про військові запаси Орди в початковій долині.",al={"кзан торнслеш","хто такий кзан","зброяр кзан"}},{q="Хто дає це доручення?",a="Це доручення дає Ґорнек — наглядач, що стоїть біля Лігва. Він стежить за новоприбулими охочими, оцінює їхні здібності й посилає розв'язувати нагальні справи на випробувальних землях.",al={"хто дає заблукалу зброю","завдання ґорнека"}},{q="Що Кзан зробить із цією підібраною зброєю?",a="Кзан лагодить, гострить і відновлює потовчену навчальну зброю. Ресурсів у Дуротарі обмаль, а новобранці прибувають безперестанку, тож підібране залізо й дерево мусять знову послужити наступній хвилі.",al={"що кзан робить зі зброєю","ремонт зброї кзаном"}},{q="Де відбувається це завдання?",a="Воно відбувається в Долині Випробувань — відлюдному каньйоні на півдні Дуротара, де молоді орки й тролі Темного Спису починають свій шлях воїнів Орди.",al={"місце долини випробувань","де заблукала зброя"}},{q="Чому Орда просто не викує зовсім нову зброю?",a="Дуротар — суворий, посушливий край, де мало легкодоступних покладів заліза, а молода Орда не може дозволити собі марнотратства. Перероблені навчальні клинки невдах дають змогу зберегти метал для військ на передовій.",al={"чому не викувати нову","нестача металу в дуротарі"}}},fp="15,323,20.384.0,25.431.0,62.279.0,23.243.0,21.204.0,46.201.0,33.160.0,54.215.0"}
P.entries["quest:973"] = {n="Вежа Альталакса",s="Це завдання — п'ятий розділ розслідування у Вежі Альталакса, що веде шукачів пригод Альянсу з Темного Узбережжя на південь, до Ашенвалю. Делґрен Очищувач посилає вас убити Ілкруда Маґтрулла, орка-чорнокнижника, що засів у спотвореному Святилищі Вогняного Шраму, і забрати його езотеричний фоліант.",h="Це завдання — п'ятий розділ розслідування у Вежі Альталакса, що веде шукачів пригод Альянсу з Темного...",kw={"вежа альталакса","ілкруд маґтрулл","святилище вогняного шраму","делґрен очищувач","чорнокнижник","ашенваль"},ang={["class:Paladin"]="Діяти пліч-о-пліч із Делґреном Очищувачем, знищуючи викликачів Скверни й конфіскуючи зіпсовані фоліанти, — класичне покликання Святого Світла проти демонічної порчі.",["class:Warlock"]="Двобій з Ілкрудом Маґтруллом зводить вас із побратимом по темних мистецтвах, який стереже свої нечестиві тексти викликаними сукубами й блукачами Порожнечі.",["faction:Alliance"]="Це завдання виводить шукачів пригод Альянсу з безпечного Темного Узбережжя вглиб уражених демонами закутків Ашенвалю, щоб очистити їх від дедалі грізнішої темної загрози.",["race:NightElf"]="Святилище Вогняного Шраму — мерзенне осквернення давніх лісів Ашенвалю, тож знищити Ілкруда — означає боронити священні землі предків."},sec={{t="Полювання в Ашенвалі",b="Ідучи слідом темної діяльності культистів, виявленої у Вежі Альталакса на Темному Узбережжі, святий воїн Делґрен Очищувач упізнає почерк небезпечного чаклуна — орка-чорнокнижника Ілкруда Маґтрулла. Діючи з демонічної виразки, відомої як Святилище Вогняного Шраму, на південному заході Ашенвалю, Ілкруд своїми темними оборудками загрожує поширити мерзенну магію чистими ельфійськими лісами. Делґрен доручає вам убити чорнокнижника й забрати його гримуар, щоб викрити задуми його господаря."},{t="Лігво чорнокнижника",b="Святилище Вогняного Шраму — понівечені Скверною руїни, що кишать демонічними невільниками. На кам'янистому підйомі до святилища стоять зловісні червоні стовпи, а в ньому живе Ілкруд разом із викликаним сукубом і вартовими-вбивцями Скверни. Здолавши орка в самому серці його володінь Скверни, Делґрен може перешукати фоліант Ілкруда в пошуках темних знань і наказів, що ведуть до зловісних обрядів в Альталаксі."}},faq={{q="Хто такий Делґрен Очищувач?",a="Делґрен Очищувач — звитяжець Альянсу на Посту Маестри, заставі нічних ельфів на межі Темного Узбережжя й Ашенвалю. Він керує боротьбою з демонічною скверною й культистами, що діють у краї.",al={"делґрен","переказ про делґрена","хто починає завдання"}},{q="Хто такий Ілкруд Маґтрулл?",a="Ілкруд Маґтрулл — грізний орк-чорнокнижник, що влаштував лігво в Святилищі Вогняного Шраму на південному заході Ашенвалю. Спершу Делґрен вважав його дрібною прикрістю, але зв'язок Ілкруда з темними обрядами у Вежі Альталакса робить його важливою ціллю.",al={"ілкруд","хто такий ілкруд маґтрулл","орк-чорнокнижник ашенваль"}},{q="Де Святилище Вогняного Шраму?",a="Святилище — на південному заході Ашенвалю, на південь від Святилища Аессіни й на захід від Астранаару. Це осквернена обитель, де кишать демони, а шлях до вівтаря Ілкруда обрамлюють два помітні червоні стовпи.",al={"місце святилища вогняного шраму","де ілкруд","як дістатися ілкруда"}},{q="Навіщо Делґренові фоліант Ілкруда Маґтрулла?",a="У фоліанті Ілкруда — його темні обряди й листування. Делґрен хоче розшифрувати записи, щоб з'ясувати, яка лиха змова пов'язує орка-чорнокнижника з культистами, що засіли біля Вежі Альталакса.",al={"навіщо фоліант","що у фоліанті ілкруда","призначення фоліанта"}},{q="Як це завдання пов'язує Темне Узбережжя з Ашенвалем?",a="Історія починається з розслідування біля Вежі Альталакса на північному узбережжі Темного Узбережжя. Що глибша таємниця, то далі мережа культистів веде шукачів пригод — через усе Темне Узбережжя до спірних лісів Ашенвалю.",al={"зв'язок темного узбережжя й ашенвалю","ланцюжок альталакса"}},{q="Що буде, коли фоліант здобуто?",a="Делґрен вивчає текст, щоб розгадати глибші задуми культистів біля Вежі Альталакса, — це веде до останніх сутичок ланцюжка.",al={"що після фоліанта","що йде після альталакса 5"}}},fp="22,305,21.502.0,18.385.1,28.227.0,24.253.0,38.211.0,46.206.0,51.230.0,39.167.0"}
P.entries["quest:97558"] = {n="Шкури для Відступників",s="Похмура необхідність існування нежиті в Галявинах Тірісфалю, де Відступники мусять добувати звірині шкури, щоб заміняти свою зотлілу плоть. Шелін Робарт доручає шукачам пригод зібрати шкури темних гончаків, перетинки крил сутінкових кажанів і шкіру мурлоків, щоб латати пошкоджені тіла.",h="Похмура необхідність існування нежиті в Галявинах Тірісфалю, де Відступники мусять добувати звірині шкури...",kw={"шкури","шелін робарт","темні гончаки","сутінкові кажани","мурлоки","латки","плоть"},ang={["profession:Tailoring"]="Кравецтво Відступників часто межує з ремеслом трунаря: навички шиття потрібні не лише для одягу, а й щоб пришивати сирі звірині перетинки до зотлілих тіл.",["race:Undead"]="Суворе нагадування про практичний тягар стану Відступників, де виживання вимагає ручного догляду й пересаджених клаптів замість природного загоєння."},sec={{t="Ціна нежиття",b="Плоть Відступників не загоюється сама. Тілесні рани лишають гнилі прогалини, які не відновлюються звичайним біологічним шляхом. Щоб зберігати форму й підтримувати тіла в робочому стані, Відступники мусять добувати органічний матеріал зі світу живих і нашивати на свої ушкодження латки."},{t="Особливі матеріали",b="Не кожна шкура служить тій самій анатомічній меті. Товста шкура темного гончака дає міцність для широких, надійних латок. Ніжні перетинки крил сутінкових кажанів досить легкі й податливі, щоб укривати обличчя та пальці, не створюючи цупких, незграбних шарів. А гнучку шкіру мурлоків Темноплавців збирають, щоб вистилати внутрішні оболонки й чутливі місця — як-от внутрішній бік щік і рот."}},faq={{q="Навіщо Відступникам шкури тварин?",a="Шкіра нежиті не загоюється й не відновлюється сама. Щоб пережити поранення й зупинити розкладання, Відступники здирають шкіру й перетинки з живих істот і латають ними, пришиваючи до своїх пошкоджених тіл.",al={"навіщо відступникам шкури","переказ про цілення нежиті","чи нежить лікується"}},{q="Хто така Шелін Робарт?",a="Шелін Робарт — доглядальниця з Відступників на Галявинах Тірісфалю, що дбає про запаси для лікування й частини тіл. Вона збирає різні шкури й біологічні матеріали, щоб ушкоджені Відступники мали чим латати свої гниючі тіла.",al={"шелін","хто така шелін робарт"}},{q="Чому потрібні саме перетинки крил сутінкових кажанів?",a="Перетинки крил сутінкових кажанів надзвичайно тонкі й м'які порівняно з важчими шкурами. Тож вони ідеально підходять, щоб покривати чутливі й складні частини тіла — обличчя чи пальці, — і пересаджена шкіра не стає надто товстою чи жорсткою.",al={"крила сутінкових кажанів","чому перетинки сутінкових кажанів"}},{q="Для чого шкура мурлоків?",a="Шкура мурлоків-Темноплавців має особливу вологість і гнучкість, тож добре підходить для внутрішніх оболонок і делікатних слизових поверхонь, як-от внутрішній бік щік і рота.",al={"навіщо шкура мурлоків","шкіра мурлоків нежить"}},{q="Де шукати ці матеріали?",a="Усі три види істот водяться в моторошних краях Галявин Тірісфалю. Темні гончаки й сутінкові кажани никають лісами й узбіччями, а мурлоки-Темноплавці гніздяться на північному узбережжі й на внутрішніх водоймах.",al={"де взяти шкури","звірі тірисфалю"}},{q="Чи часто Відступники використовують шкури тварин?",a="Так. Добувати тканини з тварин і знайдених решток — звична частина щоденного виживання Відступників. Без запасної плоті й шкур незагоєні рани лишали б кістки, нутрощі й м'язи цілком відкритими для негоди.",al={"чи всі відступники користуються шкурами","плоть відступників"}}},fp="22,266,20.316.0,21.383.0,38.240.0,23.247.0,51.273.0,29.175.0,32.197.0,46.256.0"}
P.entries["quest:976"] = {n="Припаси для Обердайна",s="«Припаси для Обердайна» — завдання на супровід, у якому шукачі пригод з Альянсу захищають Фіро Айронгенда, поки той везе важливі припаси й донесення з Посту Маестри на північ, до Темного Узбережжя. Через дедалі більшу загрозу, що йде від Вежі Альталакса, і ворожих лазутчиків в Ашенвалі безпечний шлях аж ніяк не гарантований.",h="«Припаси для Обердайна» — завдання на супровід, у якому шукачі пригод з Альянсу захищають Фіро Айронгенда...",kw={"припаси для обердайна","фіро айронгенд","пост маестри","супровід","темне узбережжя","ашенваль"},ang={["faction:Alliance"]="Захищаючи цей шлях, ви дбаєте, щоб застави Ашенвалю лишалися пов'язаними з осередком постачання в Обердайні, і бережете хиткі позиції Альянсу на півночі Калімдору.",["race:Human"]="Фіро Айронгенд уособлює готовність людей підтримувати союзників-калдореїв глибоко в незнайомих, небезпечних прадавніх лісах.",["race:NightElf"]="Припаси й донесення, що йдуть на північ, безпосередньо допомагають вартовим в Обердайні протистояти темряві, що густішає по всьому Темному Узбережжю та на межі з Ашенвалем."},sec={{t="Небезпечна дорога на північ",b="Пост Маестри стоїть на західному прикордонні Ашенвалю — тиха застава між неспокійними хащами лісу та стривоженими землями Темного Узбережжя. Після розслідування зловісних подій довкола Вежі Альталакса Делґрен Очищувач збирає важливі припаси й донесення для Вартової Старбріз в Обердайні. Замість ризикувати самотніми гінцями застава покладається на озброєний супровід, що йде разом із Фіро Айронгендом лісовою дорогою."},{t="Тіні вздовж стежки",b="Подорож показує, наскільки небезпечною стала глушина довкола дороги. На шляху Фіро чекають злагоджені засідки. Сектанти Темного Берега прагнуть не пропустити жодного донесення про свої демонічні обряди, розвідники Відступників чатують у лісовому підліску, а люті ватажки — Балізар Похмурий, Аліґар Мучитель і Кедакар Лютий — намагаються знищити обоз, перш ніж він дістанеться кордону."}},faq={{q="Хто такий Фіро Айронгенд?",a="Фіро Айронгенд — кур'єр-людина на Посту Маестри на заході Ашенвалю. Делґрен Очищувач доручив йому доставити до Обердайна важливі послання й припаси, але Фіро достатньо обережний, щоб не вирушати в дорогу без надійних охоронців.",al={"фіро","фіро айронгенд","хто дворф-супровід"}},{q="Навіщо Обердайну ці припаси?",a="Темному Узбережжю й півночі Ашенвалю дедалі більше загрожують скверна й демонічні культисти, що діють із Вежі Альталакса. Вартовим нічних ельфів в Обердайні, яких на місці очолюють такі постаті, як Вартова Старбріз, потрібні свіжі припаси й найновіші відомості, щоб і далі боронити узбережжя.",al={"навіщо припаси оберіжину","припаси для оберіжина","вартова старбріз"}},{q="Хто нападає на Фіро в дорозі?",a="Фіро застерігає, що лісом никають небезпечні вороги, і просить охорони. Хто саме нападає, з'ясується під час супроводу.",al={"хто нападає на фіро","нападники на фіро","хто нападає на дорозі"}},{q="What is the connection to the Tower of Althalaxx?",a="Delgren the Purifier has been orchestrating efforts to uncover and disrupt the dark rituals of the cultists at the Tower of Althalaxx. This escort is the culmination of that investigative chain, ensuring that intelligence and vital support reach the Night Elf leadership in Auberdine.",al={"althalaxx connection","tower of althalaxx","delgren connection"}},{q="Where do I report after protecting Feero?",a="After seeing Feero safely through the ambushes in Ashenvale, you report back to Delgren the Purifier at Maestra's Post to confirm the delivery succeeded.",al={"turn in supplies to auberdine","where do i go after escorting feero","quest turn in"}}},fp="21,347,21.488.0,23.428.1,22.248.0,39.317.0,33.151.0,49.284.0,41.153.0"}
P.entries["quest:97894"] = {n="Справи в Обердайні",s="«Справи в Обердайні» — доручення від дворфа-торговця Борґуса Стілгенда в Стормвінді. Борґус просить мандрівників, що пливуть на захід, навідати його брата Ґорболда, який нещодавно взявся торгувати в портовому містечку нічних ельфів Обердайні. Це завдання поєднує гамірні доки людської столиці з туманними берегами північного Калімдору.",h="«Справи в Обердайні» — доручення від дворфа-торговця Борґуса Стілгенда в Стормвінді.",kw={"обердайн","борґус стілгенд","ґорболд стілгенд","темне узбережжя","гавань стормвінда","торгівля"},ang={["faction:Alliance"]="Пряме морське сполучення між Гаванню Стормвінда й Обердайном зміцнює торгові та військові зв'язки людського королівства із землями калдореїв на півночі Калімдору.",["race:Dwarf"]="Дворфійська торгівля сягає далеко за гори Каз Модану: заповзятливі купці на кшталт Стілгендів відкривають прилавки навіть у тихих, оповитих тінню поселеннях нічних ельфів."},sec={{t="Дворф далеко від дому",b="Родина Стілгендів славиться гострим розумом і чесною торгівлею, і Борґус охоче за неї ручається. Його брат, Ґорболд Стілгенд, нещодавно перетнув Велике Море, щоб тримати торговий прилавок в Обердайні. Постачати кораблі, що заходять до Темного Узбережжя, здавалося легким шляхом до багатства, але тижні цілковитої тиші непокоять Борґуса: як насправді ведеться його братові так далеко від Айронфорджа й Стормвінда?"},{t="Морський шлях",b="Колись, щоб доплисти зі Східних Королівств до дикого Калімдору, доводилося вирушати заплутаними шляхами через Гавань Менетіл чи нейтральні гоблінські порти на кшталт Буті Бей. Борґус скеровує мандрівників до корабля біля найпівденнішого причалу Гавані Стормвінда — прямого морського сполучення з довгими дерев'яними пірсами Обердайна."}},faq={{q="Хто такий Борґус Стілгенд?",a="Борґус Стілгенд — дворф-крамар у Стормвінді. Пишаючись славою своєї родини як чесних торгівців, він шукає перехожих шукачів пригод, щоб передати вісточку братові Ґорболду за море.",al={"борґус","хто дає справи в оберіжині","борґус стілгенд"}},{q="Де Ґорболд Стілгенд?",a="Ґорболд Стілгенд — в Обердайні, головному портовому поселенні Темного Узбережжя на північно-західному березі Калімдору. Він тримає крамничку для кораблів, що прибувають.",al={"де ґорболд","знайти ґорболда стілгенда","місце ґорболда"}},{q="Як дістатися зі Стормвінда до Обердайна?",a="Корабель відпливає просто з найпівденнішого причалу Гавані Стормвінда й перевозить пасажирів через Велике Море до доків Обердайна на Темному Узбережжі.",al={"корабель до оберіжина","як дістатися темного узбережжя зі стормвінда","корабель зі стормвінда до оберіжина"}},{q="Чому Борґус тривожиться за брата?",a="Кілька тижнів тому Ґорболд поїхав до крамнички в Обердайні, сподіваючись добре заробити на постачанні морських суден. Але відтоді він не надіслав додому жодної звістки, тож Борґус просить мандрівників з'ясувати, що сталося.",al={"чому перевіряти ґорболда","що сталося з ґорболдом"}},{q="Що за поселення Обердайн?",a="Обердайн — прибережний прихисток, збудований і заселений здебільшого нічними ельфами. Розташований на Темному Узбережжі, він — головний морський вузол Альянсу й переправа між північчю Калімдору та острівним краєм Тельдрассил.",al={"що таке оберіжин","містечко оберіжин"}},{q="Чим славиться родина Стілгендів?",a="Стілгенди — дворфійська купецька родина, що живе з торгівлі й крамничок і хвалиться тим, що завжди пропонує чесну угоду і мандрівникам, і портовим робітникам.",al={"родина стілгендів","стілгенди"}}},fp="21,329,21.430.0,18.345.0,24.185.0,35.169.0,42.162.0,40.238.0,37.232.0,39.163.0"}
P.entries["quest:97914"] = {n="Розширення обріїв",s="«Розширення обріїв» — дипломатичне доручення гінця, що починається на Темному Узбережжі й напряму пов'язує поселення нічних ельфів Обердайн із людським королівством Стормвінд. На прохання Тундріса Віндвівера шукач пригод везе через океан офіційне листування Міському Архітекторові Баросу Алекстону, щоб зміцнити зв'язки й торгівлю між двома далекими землями Альянсу.",h="«Розширення обріїв» — дипломатичне доручення гінця, що починається на Темному Узбережжі й напряму пов'язує...",kw={"обердайн","тундріс віндвівер","барос алекстон","міський архітектор","темне узбережжя","морський шлях"},ang={["faction:Alliance"]="Це доручення показує, якої щоденної, практичної праці потребує, щоб злютувати різні народи двох континентів в єдину дієву фракцію.",["race:Human"]="Повернення до Стормвінда з печаткою калдорейської гавані показує, як широко сягає вплив відбудованого королівства.",["race:NightElf"]="Для калдореїв відкриття морських шляхів до Східних Королівств — докорінний розрив із десятьма тисячами років відлюдництва, що нерозривно пов'язує ваш народ із людською цивілізацією."},sec={{t="Міст між двома півкулями",b="Тисячоліттями нічні ельфи жили в лісах Калімдору, відгороджені від Східних Королівств. Після Третьої війни їхній вступ до Великого Альянсу потребував справжніх зв'язків — не лише ідейних, а й торгових та морських. Обердайн — головний північний порт калдорейського материка, проте він довго лишався в тіні прадавніх зруйнованих міст, як-от Амет'Аран і Башал'Аран. Тепер, коли між Обердайном і Стормвіндом проклали прямий морський шлях, місцеві провідники прагнуть закріпити нові судноплавні маршрути й вплести свою прибережну громаду в ширшу мережу Альянсу."},{t="Послання Міському Архітекторові",b="Листування, яке везуть через Велике Море, адресоване особисто Баросу Алекстону, Міському Архітекторові Стормвінда. Як головний будівничий, відповідальний за відбудову людської столиці та її господарство, Алекстон опікується великими громадськими спорудами й постачанням. Мета ж самого Тундріса простіша: він хоче, щоб праця Обердайна дістала визнання, а про його дім дізналися."}},faq={{q="Хто дає вам це завдання?",a="Це доручення дає мандрівникам Тундріс Віндвівер, впливовий нічний ельф з Обердайна. Відчуваючи, що Обердайн обділяють увагою і високі гілки Дарнасуса, і далекі союзники за океаном, він прагне налагодити офіційний зв'язок із людським королівством.",al={"хто дає розширення обріїв","видавець розширення обріїв","завдання тундріса"}},{q="Хто такий Барос Алекстон?",a="Барос Алекстон — Міський Архітектор Стормвінда. Шанований міський будівничий і колишній член Гільдії Каменярів, що лишився вірним короні, він наглядає за будівництвом і утриманням споруд по всій столиці.",al={"переказ про бароса алекстона","хто такий барос","архітектор стормвінда"}},{q="Чому Обердайн звертається до Стормвінда?",a="Обердайн хоче, щоб його гавань визнали важливими воротами для припасів, торгівлі й подорожей Альянсу. Відколи відкрилися нові морські шляхи між Темним Узбережжям і Східними Королівствами, місцеві очільники сподіваються зміцнити господарські й транспортні зв'язки з людським королівством.",al={"чому оберіжин пише до стормвінда","зв'язок оберіжина і стормвінда","чому звертатися до людей"}},{q="Як подорожувати між Обердайном і Стормвіндом?",a="Тепер Обердайн з'єднує з королівством Стормвінд нове судно: воно перетинає Велике Море й заходить просто в Гавань Стормвінда, привозячи на береги Обердайна життя й припаси.",al={"корабель до стормвінда","як дістатися стормвінда з оберіжина"}},{q="Що таке Амет'Аран і Башал'Аран?",a="Це були квітучі міста Високородних на давньому Темному Узбережжі, доки Великий Розкол десять тисяч років тому не розтрощив континент. Нині вони лежать у руїнах, де блукають привиди, і в історії калдореїв їх згадують куди частіше, ніж живі поселення на кшталт Обердайна.",al={"переказ про амет'аран","башал'аран","давні міста темного узбережжя"}},{q="Чому лист треба віднести архітекторові, а не Королю Андуїну чи Болварові?",a="У завданні не сказано, чому Тундріс обрав саме його. Тундріс просто просить, щоб лист дістався людині на ім'я Барос Алекстон, Міському Архітекторові Стормвінда, аби праця Обердайна дістала визнання.",al={"чому барос алекстон","чому не болвар","чому не верховний лорд болвар"}}},fp="18,372,24.620.0,31.370.0,28.266.0,22.231.0,43.263.0,53.180.0,36.261.0,66.187.0"}
P.entries["quest:97919"] = {n="Табірна наука 101: перша допомога",s="«Табірна наука 101: перша допомога» знайомить шукачів пригод-початківців у Лісі Елвінн із практичним мистецтвом виживання — польовою медициною. Урок спрямовує мандрівників до Мішель Белль у Ґолдширі, щоб навчитися готувати Аптечку для таборів у глушині.",h="«Табірна наука 101: перша допомога» знайомить шукачів пригод-початківців у Лісі Елвінн із практичним...",kw={"табірна наука","перша допомога","аптечка","мішель белль","ґолдшир","бинти"},ang={["class:Rogue"]="Діючи в тіні, далеко від підтримки, розбійники залежать від польової медицини: перев'язати кровоточиві рани, перш ніж рушити до наступної цілі.",["class:Warrior"]="Не маючи вроджених цілющих заклять, бійці передової значною мірою покладаються на бинти й польові аптечки, щоб пережити тривалі походи в дикій природі.",["faction:Alliance"]="Ґолдшир лишається ключовим перехрестям для мандрівників Альянсу, що починають свій шлях із Нортширу в ширше королівство Елвінну."},sec={{t="Польова медицина в дорозі",b="Шукачі пригод, що мандрують Лісом Елвінн, швидко дізнаються: бої й суворе виживання в дикій природі дорого коштують. Міські цілителі й корчми дають перепочинок, та подорож небезпечними землями часто вимагає негайної самостійної допомоги. Перша допомога — практичний засіб від кровотеч і травм, що дає змогу гоїти рани, не покладаючись на чародійські ритуали чи святі молитви."},{t="Припаси для табору",b="Надійний табір — це більше, ніж вогонь і постіль; це тимчасовий прихисток від небезпек глушини. Навчаючись у Мішель Белль у ґолдширській Корчмі «Лев'яча Гордість», вправні цілителі вчаться збирати спеціальні аптечки. Медичні припаси під рукою в таборі дають утомленому загону змогу обробити поранення й відновити сили, перш ніж зустріти небезпеки попереду."}},faq={{q="Навіщо це завдання?",a="Це завдання скеровує шукачів пригод, що опанували основи Першої допомоги, до Мішель Белль у Ґолдшир. Вона навчає, як виготовити Аптечку, щоб табір у нетрях завжди мав необхідні засоби для лікування.",al={"мета табірної першої допомоги","що робить це завдання","навіщо табірна наука 101 перша допомога"}},{q="З ким треба поговорити в Ґолдширі?",a="Вам треба поговорити з Мішель Белль — наставницею в Ґолдширі. Щойно ви покажете достатню майстерність у Першій допомозі, вона поділиться прийомами виготовлення табірного приладдя для польової медицини.",al={"з ким говорити в ґолдширі","хто така мішель бель","наставник табору ґолдшира"}},{q="Чому Перша допомога важлива для мандрівників?",a="У мандрах завжди є ризик зазнати поранень від звірів, розбійників і суворої негоди. Перша допомога дає кожному — хай він володіє божественною магією, тайною чи жодною — змогу перев'язати рани й відновитися між сутичками.",al={"чому перша допомога важлива","чи перша допомога корисна","переказ про першу допомогу"}},{q="Де Ґолдшир?",a="Ґолдшир — головне селище Лісу Елвінн, трохи на південь від Стормвінда, на головному торговому шляху. Тут можна поповнити припаси, знайти місцевих наставників і відпочити в Корчмі «Лев'яча Гордість».",al={"де ґолдшир","місце ґолдшира","як знайти мішель бель"}},{q="Чи потрібна попередня підготовка, щоб виконати це доручення?",a="Так. Мішель Белль вимагає, щоб ви показали вправність у Першій допомозі, перш ніж вона навчить вас виготовляти табірні набори для цієї професії.",al={"вимоги табірної науки 101","потрібна перша допомога","передумови"}},{q="Яке місце Аптечка посідає в таборі?",a="Табір у нетрях дає безпечне місце для відновлення сил, а Аптечка в ньому гарантує, що поранені мандрівники матимуть під рукою бинти й ліки, потрібні, щоб рятувати життя далеко від міських цілителів.",al={"вжиток табірної аптечки","предмет табору перша допомога","навіщо аптечка"}}},fp="22,239,26.409.0,25.391.0,34.232.0,41.207.0,41.226.0,27.208.0,47.151.0,42.221.0"}
P.entries["quest:97920"] = {n="Табірна наука 101: риболовля",s="«Табірна наука 101: риболовля» знайомить рибалок-початківців у Лісі Елвінн із практичним ремеслом виживання в глушині й облаштування табору. Розшукавши місцевого знавця риболовлі Лі Брауна біля Ґолдшира, мандрівники вчаться застосовувати рибальські знання для виготовлення затишних дрібниць для стоянки — як-от декоративного акваріума, що підбадьорює шукачів пригод.",h="«Табірна наука 101: риболовля» знайомить рибалок-початківців у Лісі Елвінн із практичним ремеслом виживання в...",kw={"табірна наука","риболовля","лі браун","акваріум","ґолдшир","табір"},ang={["faction:Alliance"]="Люди-мандрівники, що починають свої пригоди в Лісі Елвінн, можуть покластися на знайомі води Ґолдшира, щоб опанувати основи самостійного життя в глушині."},sec={{t="Табірне ремесло для рибалок",b="Риболовлю часто вважають самотньою розвагою для тихих берегів озер і річок, та бувалі знавці виживання розуміють: табірне життя потребує більшого, ніж їжа й дах. Затишні речі на кшталт акваріума приносять легкість і бадьорість утомленим мандрівникам, що відпочивають між вилазками, і підтверджують переконання: ясний розум і високий дух гартують грізних бійців."},{t="Досвід Лі Брауна",b="Бувалий рибалка Лі Браун, що оселився біля води за Ґолдширом, допомагає рибалкам-новачкам, які прагнуть розширити своє ремесло. Тих, хто виявив достатню вправність із вудкою й волосінню, направляють до нього — навчитися, як простий улов і базові матеріали перетворити на корисні поліпшення для табору."}},faq={{q="Навіщо це завдання?",a="Завдання скеровує охочих рибалок до Лі Брауна поблизу Ґолдшира. Щойно ви покажете базову вправність у риболовлі, він навчить вас виготовляти особливі табірні речі, як-от акваріум, щоб зробити придорожній табір затишнішим.",al={"навіщо табірна риболовля","що дає табірна наука 101","мета завдання"}},{q="Хто такий Лі Браун?",a="Лі Браун — обізнаний наставник рибалок, що стоїть біля Кришталевого Озера під самим Ґолдширом у Лісі Елвінн. Він навчає вудіння й розповідає, як змайструвати табірне приладдя для рибалок.",al={"де лі браун","хто навчає риболовлі в таборі","лі браун"}},{q="Що Акваріум дає табору?",a="Акваріум — табірна окраса, що дарує затишок і радість шукачам пригод на привалі. Приємна атмосфера в таборі підносить дух, і шукачі пригод почуваються готовими й спроможними протистояти небезпекам нетрів.",al={"ефект акваріума","що робить акваріум","навіщо акваріум"}},{q="Де відбувається навчання?",a="Завдання відбувається в Лісі Елвінн і веде гравців до водойм довкола Ґолдшира, де збираються місцеві рибалки.",al={"місце завдання","куди йти","наставник табору елвінн"}},{q="Чи потрібна попередня майстерність у риболовлі, щоб виконати це?",a="Так. Лі Браун навчає лише тих мандрівників, що вже набили руку в закиданні вудки й показали базову вправність у рибальському ремеслі.",al={"вимога риболовлі","чи потрібна риболовля","вимога майстерності"}},{q="Чи допомагає табір у бою?",a="Так. Доглянутий табір дарує затишок, що зміцнює тілесну й душевну готовність шукача пригод, а це прямо позначається на його витривалості й бойовій вправності в полі.",al={"чи табір допомагає в бою","баффи табору","навіщо табір"}}},fp="20,358,21.392.0,21.312.0,34.220.0,17.215.0,40.218.0,36.123.0,50.138.0,29.187.0"}
P.entries["quest:97957"] = {n="Табірна наука 101: травництво",s="Табірна наука 101: травництво скеровує травників-початківців до місцевих наставників ремесла по всьому Азероту — як-от до Фарузи у Бріллі, — щоб опанувати виготовлення Ароматичних Свічок. Ці запашні вироби дають життєво важливу відновлювальну підтримку заклиначам, які відпочивають у таборах серед дикої природи.",h="Табірна наука 101: травництво скеровує травників-початківців до місцевих наставників ремесла по всьому...",kw={"табірна наука","травництво","фаруза","ароматичні свічки","табір","елеанор шеклтон"},ang={["class:Mage"]="Заклиначі цінують травників, які виготовляють Ароматичні Свічки: їхній заспокійливий дим допомагає відновити зосередженість і дух далеко від затишку таверни.",["profession:Herbalism"]="Замість просто варити зілля чи продавати стебла, травники можуть прямо підтримувати загони шукачів пригод, виготовляючи запашні Ароматичні Свічки для багаття.",["race:Undead"]="Мандрівники з Відступників, що діють із Похоронного Подзвону та Брілла, вчаться у Фарузи робити практичні похідні речі з усохлої рослинності Тірісфалю."},sec={{t="Зілля для табору",b="Травництво зазвичай мають за підґрунтя алхімії, та практичне виживання в полі не менше залежить від зібраних коренів і квітів. Досвідчені мандрівники скеровують охочих збирачів до майстрів-травників краю — навчитися готувати Ароматичні Свічки. У Галявинах Тірісфалю Елеанор Шеклтон посилає перспективних збирачів до Фарузи у Бріллі, щойно ті покажуть базову вправність."},{t="Пожива для розуму",b="Життя в дорозі тяжко виснажує розум заклиначів і духовників. Ароматичні Свічки виділяють відновлювальні пахощі, покликані підняти дух і заспокоїти втомлений розум. Насичуючи свічки сушеними рослинами, збирачі дають важливу підтримку цілителям і магам, чиї магічні запаси вичерпуються в тривалих мандрах, — варто лише розбити табір і запалити свічку."}},faq={{q="Навіщо це завдання?",a="Завдання спонукає травників досягти базової вправності, щоб наставник із травництва навчив їх виготовляти Ароматичні Свічки. Ці свічки підтримують і допомагають заклиначам під час відпочинку в нетрях.",al={"навіщо табірне травництво","що дає табірна наука 101","мета табірного травництва"}},{q="Хто дає це завдання на Галявинах Тірісфалю?",a="На Галявинах Тірісфалю цю пораду травникам дає Елеанор Шеклтон, скеровуючи їх до Фарузи в сусідньому Бріллі.",al={"хто дає табірне травництво тірисфаль","завдання елеанор шеклтон"}},{q="Що дає Ароматична Свічка?",a="Ароматичні Свічки наповнюють табір благодатною атмосферою: підносять дух і допомагають цілителям та чарівникам відновити зосередженість під час відпочинку в полі.",al={"ефект ароматичної свічки","навіщо ароматичні свічки"}},{q="Хто навчає рецепта Ароматичної Свічки?",a="Шукачів пригод, що мають достатню вправність, навчають місцеві наставники з травництва. На Галявинах Тірісфалю цим займається Фаруза в Бріллі, а в інших містах і містечках — наставники на кшталт Джанді в Оргріммарі, Рейни Стоунбренч в Айронфорджі й Малорна Блейдліфа в Доланаарі.",al={"хто навчає ароматичної свічки","де здати табірне травництво"}},{q="Чи можуть узятися за це завдання члени інших фракцій і рас?",a="Так. Елеанор Шеклтон і Фаруза опікуються мандрівниками на Галявинах Тірісфалю, а інші дарувальники завдань і наставники дають таку саму науку травникам по всьому Калімдору й Східних Королівствах.",al={"чи це лише для орди","табірне травництво альянс"}},{q="Яка майстерність потрібна, щоб пройти навчання?",a="Травники мають показати справжню вправність у своєму ремеслі, досягнувши майстерності травництва двадцять, — лише тоді наставник навчить рецепта свічки.",al={"скільки травництва потрібно","рівень майстерності табірної науки"}}},fp="22,259,18.400.0,23.318.0,34.223.0,41.136.0,31.176.0,38.256.0,56.196.0,58.140.0"}
P.entries["quest:97960"] = {n="Табірна наука 101: білування",s="Табірна наука 101: білування — вступна настанова з виживання для збирачів-початківців у Галявинах Тірісфалю і по всьому Азероту. Вона скеровує білувальників, що вже попрактикувалися у своєму ремеслі, до майстрів краю — навчитися робити міцний похідний стілець із добутих шкур.",h="Табірна наука 101: білування — вступна настанова з виживання для збирачів-початківців у Галявинах Тірісфалю і...",kw={"табірна наука","білування","ранд робарт","стілець","шкури","табір"},ang={["faction:Horde"]="Мисливці й збирачі Орди використовують кожен клапоть убитого звіра, щоб ніщо не пропало марно на безжальній дорозі.",["race:Undead"]="Навіть Відступники, вільні від смертної втоми, бачать практичну користь у впорядкованому похідному таборі, полюючи на зачумлених звірів Тірісфалю."},sec={{t="Затишок у глушині",b="Виживання в глушині вимагає більшого, ніж гострий клинок: треба вміти берегти сили між випробуваннями. Шукачі пригод на кшталт Елеанор Шеклтон наголошують, що звірині шкури дають більше, ніж просто крам на продаж. Опанувавши базові польові навички, білувальники можуть робити з вичинених шкур необхідні табірні вигоди — як-от стільці, — щоб утомлені мандрівники могли як слід відпочити й відновитися перед наступною небезпечною зустріччю."},{t="Опанування ремесла",b="У Галявинах Тірісфалю молодих білувальників з Відступників, що досягли початкової вправності, скеровують до Ранда Робарта, який веде своє ремесло при дорозі між Бріллом і руїнами Столиці над Андерсіті. Робарт ділиться практичними прийомами перетворення грубої шкіри на зручне табірне сидіння — мистецтво, яке повторюють майстри білування по всіх землях і Орди, і Альянсу."}},faq={{q="Навіщо це завдання?",a="Завдання скеровує молодих білувальників до вправного наставника ремесла, який навчить їх змайструвати табірне крісло зі здобутих шкур тварин.",al={"що дає табірне білування","навіщо табірна наука білування","нагорода табірної науки 101"}},{q="Хто дає цю науку на Галявинах Тірісфалю?",a="На Галявинах Тірісфалю завдання дає Елеанор Шеклтон, скеровуючи нових білувальників до Ранда Робарта на великій дорозі між Бріллом і Андерсіті.",al={"хто дає цю науку тірисфаль","завдання елеанор шеклтон"}},{q="Яка майстерність потрібна, щоб виконати це доручення?",a="Вам треба підняти майстерність білування щонайменше до 20, — лише тоді наставник визнає вас досить досвідченим, щоб навчити виготовляти табірне спорядження.",al={"який рівень білування потрібен","вимоги табірного білування","потрібна майстерність білування"}},{q="Де знайти Ранда Робарта?",a="Ранд Робарт стоїть біля головної дороги, що йде на південь від Брілла до входу в Андерсіті на Галявинах Тірісфалю.",al={"де ранд робарт","місце ранда робарта","ранд робарт тірисфаль"}},{q="Чи можуть члени інших фракцій навчитися цього прийому?",a="Так. Відступники вчаться в Ранда Робарта, а такі самі наставники навчають білувальників у Ґолдширі, Айронфорджі, Доланаарі, Оргріммарі, Селі Бладгуф і Селі Шен'дар.",al={"чи це лише для орди","чи альянс може табірне білування","табірне крісло альянсу"}},{q="Чим корисне табірне крісло?",a="Табірне крісло дає зручне місце, щоб посидіти й відновити сили в нетрях, тож шукач пригод лишається відпочилим і пильним перед новими боями.",al={"навіщо табірне крісло","що робить крісло"}}},fp="21,270,20.439.0,19.382.0,34.152.0,44.157.0,51.149.0,32.127.0,51.169.0,36.153.0"}
P.entries["quest:981"] = {n="Вежа Альталакса",s="Це доручення — тріумфальне завершення кампанії проти Культу Темного Берега у Вежі Альталакса. Знищивши провід культу в зловісних руїнах Темного Узбережжя, шукач пригод несе звістку на південь, до Ашенвалю, Делґренові Очищувачу. Це важлива перемога Альянсу у вичищенні демонічної порчі з давніх кордонів нічних ельфів.",h="Це доручення — тріумфальне завершення кампанії проти Культу Темного Берега у Вежі Альталакса.",kw={"вежа альталакса","культ темного берега","делґрен очищувач","балтул шедовстрайк","пост маестри","перемога"},ang={["class:Paladin"]="Донесення Делґренові Очищувачу особливо важливе для паладинів, які поділяють його святу місію — очищати світ від демонічної порчі й лихих культів.",["faction:Alliance"]="Знищення культу захищає суходільну дорогу між Темним Узбережжям і Ашенвалем, і розвідники та мандрівники Альянсу можуть не боятися демонічних засідок.",["race:NightElf"]="Для нічних ельфів очищення Вежі Альталакса прибирає мерзенну пошесть із давніх руїн Високородних, розкиданих їхніми священними прибережними лісами."},sec={{t="Загрозу обірвано",b="Тижнями Вежа Альталакса була гнійною раною на півночі Темного Узбережжя, яку захопили фанатики Культу Темного Берега та їхні тіньові господарі. Невтомне стеження, збирання відомостей і запеклі сутички крок за кроком розібрали діяльність культу. Коли його чаклунів убито, а темні обряди зірвано, нагальну загрозу демонічного проникнення на Темне Узбережжя нарешті відвернуто."},{t="Донесення на Пост Маестри",b="Після смерті ватажка культу Балтул Шедовстрайк посилає переможця на південь, до Посту Маестри під кронами Ашенвалю. Там чекає Делґрен Очищувач — відданий воїн Святого Світла, що керував хрестовим походом проти лиходіїв Альталакса. Звістка про падіння культу заспокоює захисників краю й приносить звитяжцеві незмінне благословення та заслужену вдячність Делґрена."}},faq={{q="Яка мета цього завдання?",a="Це завдання — остаточна здача довгого сюжету про Вежу Альталакса. Вам треба лише вирушити з околиць вежі на Пост Маестри в Ашенвалі й доповісти Делґренові Очищувачу про вирішальну перемогу.",al={"мета вежі альталакса","здати вежу альталакса","де здати завдання 981"}},{q="Хто такий Делґрен Очищувач?",a="Делґрен Очищувач — звитяжець Альянсу на Посту Маестри на півночі Ашенвалю. Володіючи Святим Світлом, він присвятив себе викоріненню скверни й боротьбі з демонічними загрозами на кшталт Культу Темного Берега по всій півночі Калімдору.",al={"хто такий делґрен","переказ про делґрена","делґрен очищувач"}},{q="Хто такий Балтул Шедовстрайк?",a="Балтул Шедовстрайк — агент Альянсу, що перебуває біля Вежі Альталакса на Темному Узбережжі. Тісно співпрацюючи з Делґреном, він стежить за пересуваннями культу й допомагає шукачам пригод зруйнувати темну зграю зсередини.",al={"балтул","переказ про балтула","хто балтул шедовстрайк"}},{q="Що Культ Темного Берега робив біля вежі?",a="Культ Темного Берега захопив давні руїни Вежі Альталакса, щоб правити темні обряди, закликати демонічних сутностей і поширювати свій лихий вплив прибережними землями Темного Узбережжя.",al={"культ темного берега","що сталося в альталаксі","переказ про вежу альталакса"}},{q="Де Пост Маестри?",a="Пост Маестри — застава Альянсу на північному заході Ашенвалю, трохи на південь від переходу межі з Темним Узбережжям на головній дорозі.",al={"місце поста маестри","де пост маестри","місце делґрена"}},{q="Чи Культ Темного Берега знищено цілком?",a="Його провід у Вежі Альталакса страчено, а головний обряд зірвано, але розпорошені культисти й рештки секти досі тиняються відлюдними закутками Калімдору. Утім, організовану загрозу на Темному Узбережжі розгромлено.",al={"чи культ зник","чи темний берег знищено","чи ми вбили культ"}}},fp="22,390,16.431.0,24.418.0,31.228.0,28.247.0,29.233.0,56.205.0,32.143.0,52.238.0"}
P.entries["quest:98190"] = {n="Друг родини",s="«Друг родини» — нагальне доручення гінця з Гавані Менетіл у Багнокраї. Побоюючись місцевих загроз, як-от орків Драконячої Пащі, влада гавані доручає шукачеві пригод доставити безцінну Статуетку Менетіла просто Верховному Лордові Болвару Фордрагону у Фортецю Стормвінда.",h="«Друг родини» — нагальне доручення гінця з Гавані Менетіл у Багнокраї.",kw={"друг родини","статуетка менетіла","болвар фордрагон","фортеця стормвінда","драконяча паща","гавань менетіл"},ang={["class:Paladin"]="Ім'я Менетіла нагадує про покровителя-засновника Лицарів Срібної Длані, тож збереження цієї реліквії — урочистий обов'язок для кожного святого воїна.",["faction:Alliance"]="Доставлена реліквія вшановує історичний північний Альянс і не дає безцінному символу потрапити в лапи клану Драконячої Пащі.",["race:Human"]="Для людей збереження артефакту династії Менетілів — це збереження гордої й трагічної пам'яті про загиблий Лордерон і утвердження обов'язку Стормвінда як останнього великого людського королівства."},sec={{t="Хитка гавань",b="Гавань Менетіл — важлива морська брама, що пов'язує північ Східних Королівств із півднем. Названий на честь покійного короля Лордерона Теренаса Менетіла II, порт стоїть відрізаним серед підступних боліт і войовничих ворогів. Коли місцеві загрози наростають, провід гавані розуміє: безцінні реліквії загиблого північного королівства не можуть лишатися в безпеці на такій відкритій заставі."},{t="Загроза Драконячої Пащі",b="Багнокрай досі кишить рештками клану Драконячої Пащі — лютими орками, відомими своїм темним минулим і безжальним пристосуванством. З огляду на їхню близькість і жагу завоювань, захисники гавані бояться, що Драконяча Паща ні перед чим не спиниться, аби пограбувати такі історичні скарби, як Статуетка Менетіла, — а то й осквернити такий символ чи обернути його собі на зброю."},{t="Просто до Верховного Лорда",b="Щоб не ризикувати затримками у звичайних бюрократичних чи військових ланках, гінцеві наказано оминути весь ланцюг командування. Реліквію відсилають просто у Фортецю Стормвінда, до рук Верховного Лорда Болвара Фордрагона, регента при юному королі Андуїні Рінні, вірячи, що провід столиці найкраще вбереже частку спадщини Лордерона."}},faq={{q="Що таке Статуетка Менетіла?",a="Статуетка Менетіла — цінна родинна реліквія, пов'язана з королівським родом Лордерона й Королем Теренасом Менетілом II. Вона уособлює історичні узи між північним королівством і Альянсом, тож на неї полюють мародери й вороги.",al={"реліквія менетіла","що за статуетка","переказ про статуетку"}},{q="Чому статуетка не може лишитися в Гавані Менетіл?",a="Гавань Менетіл відрізана від світу й оточена ворожими болотами, дворфами Темного Заліза, мурлоками й ворожими орками. Гарнізон вважає поселення надто вразливим, щоб надійно вберегти таку значущу реліквію.",al={"чому статуетку забирають","чи гавань менетіл небезпечна"}},{q="Хто такі Драконяча Паща і навіщо їм статуетка?",a="Клан Драконячої Пащі — угруповання орків, що окопалося в Багнокраї. Посадовці гавані бояться, що вони охоче пожертвують воїнами, аби пограбувати шановані реліквії Альянсу й, можливо, осквернити їх чи використати на зло.",al={"драконяча паща","навіщо оркам статуетка"}},{q="Чому реліквію треба доставити просто Болварові Фордрагону?",a="Як регент Стормвінда й захисник юного Короля Андуїна, Верховний Лорд Болвар Фордрагон має найвищу владу в столиці. Якщо віддати реліквію просто йому, вона мине бюрократичну тяганину й опиниться під найнадійнішою охороною.",al={"чому болвар","чому в обхід ланцюга командування"}},{q="Де знайти Верховного Лорда Болвара Фордрагона?",a="Верховний Лорд Болвар Фордрагон стоїть у тронній залі Фортеці Стормвінда, поруч із хлопчиком-королем Андуїном Рінном.",al={"місце болвара","де болвар"}},{q="Як Гавань Менетіл пов'язана з Королем Теренасом?",a="Гавань Менетіл назвали на честь Короля Теренаса Менетіла II, який правив Лордероном і підтримував Альянс Лордерона в Другій війні, доки не загинув трагічною смертю в Третій.",al={"чому гавань менетіл","зв'язок теренаса менетіла"}}},fp="22,291,19.430.0,20.362.0,24.373.0,31.240.0,48.205.0,46.226.0,51.236.0,43.118.0,49.192.0"}
P.entries["quest:98191"] = {n="Друг родини",s="Верховний Лорд Болвар Фордрагон доручає шукачеві пригод доставити рідкісну Статуетку Менетіла до Собору Світла. Ця реліквія, що зображує покійного короля Лордерону Теренаса Менетіла II, почала вбирати святу силу. Її передають Лордові Ґрейсонові Шедовбрейкеру на вічне зберігання в духовному серці Стормвінда.",h="Верховний Лорд Болвар Фордрагон доручає шукачеві пригод доставити рідкісну Статуетку Менетіла до Собору...",kw={"статуетка менетіла","теренас менетіл","болвар фордрагон","ґрейсон шедовбрейкер","собор світла","паладин"},ang={["class:Paladin"]="Для паладина берегти реліквію короля Теренаса, якої відчутно торкнулося Світло, — вияв глибокої шани до правителя, що колись благословив заснування Лицарів Срібної Длані.",["class:Priest"]="Свята енергія, що зібралася в простій різьбленій подобі, підтверджує: духовна спадщина вірних Лордерону живе й після того, як саме королівство зруйноване.",["faction:Alliance"]="Король Теренас Менетіл II був наріжним каменем Альянсу Лордерону, тож будь-який пов'язаний із ним артефакт — дорогоцінний символ єдності й пам'яті."},sec={{t="Рідкісна пам'ятка",b="Король Теренас Менетіл II був творцем Великого Альянсу під час Другої війни й людиною глибокої побожності. Попри свою величезну вагу серед людських королівств, Теренас був надзвичайно скромним і, як відомо, не любив пам'ятників на свою честь. Через цю його неохоту замовили дуже мало його зображень, і ще менше з них уціліло під час жахливого спустошення й навали Погибелі, що захлиснула Лордерон."},{t="Дотик благодаті",b="Оглянувши вцілілу Статуетку Менетіла, Верховний Лорд Болвар Фордрагон бачить у ній щось значно більше, ніж просто майстерну різьбу. Саме Святе Світло почало збиратися в різьбленій фігурці, наповнюючи її тихим духовним відгомоном. Вирішивши, що королівський палац у Фортеці Стормвінда — не належне святилище для такої священної речі, Болвар велить перенести її через місто до Собору Світла й передати в надійні руки наставника паладинів Лорда Ґрейсона Шедовбрейкера."}},faq={{q="Хто такий Король Теренас Менетіл II?",a="Король Теренас Менетіл II був улюбленим правителем королівства Лордерон. Під час Другої війни він згуртував розрізнені людські держави разом із дворфами, гномами й високими ельфами у Великий Альянс, який зрештою розгромив Орду орків. Він загинув, коли впало його королівство.",al={"теренас менетіл","хто такий теренас","король лордерона"}},{q="Чому статуї Короля Теренаса такі рідкісні?",a="Попри величезний авторитет і любов народу, Король Теренас славився особистою скромністю й не любив пишних пам'ятників на свою честь. Його подобу вирізьбили в небагатьох статуях і пам'ятних знаках, і майже жоден із них не пережив руйнування Лордерона Погибеллю.",al={"чому мало статуй","рідкість статуетки теренаса","чому мало пам'ятників"}},{q="Чому Статуетка Менетіла сяє Світлом?",a="Bolvar notices that the Light seems to have coalesced in the statuette. He speaks of Terenas as a good and devout man, but does not explain why this particular likeness has gathered holy power.",al={"чому статуетка світиться","свята статуетка","світло що збирається"}},{q="Хто такий Лорд Ґрейсон Шедовбрейкер?",a="Лорд Ґрейсон Шедовбрейкер — бувалий паладин із людей, лицар Срібної Длані й шанований наставник Собору Світла. Він перебуває на Соборній Площі, навчає майбутніх паладинів і опікується святими справами вірян Стормвінда.",al={"хто такий шедовбрейкер","роль лорда ґрейсона"}},{q="Чому Верховний Лорд Болвар відсилає статуетку до Собору?",a="Болвар шанує Теренаса як батька Альянсу, але статуетка помітно набралася святої сили. Він вважає, що таке вмістилище Світла належить не придворним урядовцям у Фортеці Стормвінда, а Соборові Світла під опікою святих орденів.",al={"чому відсилати до собору","чому не лишити у фортеці"}},{q="Де Собор Світла?",a="Собор Світла височіє над Соборною Площею в самому серці Стормвінда, між Дворфійським Кварталом, Торговим Кварталом і Кварталом магів. Це головне святилище й осередок богослужінь Церкви Святого Світла в південних королівствах.",al={"де собор світла","місце соборної площі"}}},fp="22,330,18.456.0,16.505.0,33.294.0,40.275.0,53.193.0,34.252.0,61.275.0,40.275.0"}
P.entries["quest:982"] = {n="Глибокий океан, безкрає море",s="«Глибокий океан, безкрає море» — завдання Альянсу, яке дає Ґорболд Стілгенд в Обердайні. Шукачі пригод мають пірнути у води на північ від селища й дістати особисті скриньки з двох затонулих кораблів нічних ельфів — «Срібної Зорі» та «Туманної Завіси». На обидва кораблі напали прибережні мурлоки, і вцілілі члени команди прагнуть хоч якоїсь розради.",h="«Глибокий океан, безкрає море» — завдання Альянсу, яке дає Ґорболд Стілгенд в Обердайні.",kw={"глибокий океан безкрає море","ґорболд стілгенд","срібна зоря","туманна завіса","мурлоки","обердайн"},ang={["faction:Alliance"]="Спільне горе команди в Обердайні показує тісну морську співпрацю дворфів і нічних ельфів на узбережжі Калімдору.",["race:Dwarf"]="Ґорболд Стілгенд показує типовий для дворфів порив ушановувати полеглих товаришів і підтримувати побратимів-моряків у чужих портах.",["race:NightElf"]="Загиблі капітани були мореплавцями з нічних ельфів, що служили морській торгівлі Обердайна, тож повернення їхніх речей — справа честі предків."},sec={{t="Трагедія біля берега",b="Води біля Темного Узбережжя стають дедалі небезпечнішими — не лише через підступні течії й природні рифи, а й через агресивні прибережні племена. Кораблі «Срібна Зоря» й «Туманна Завіса» заходили до порту Обердайн, коли на них навалилися зграї мурлоків. Жоден корабель не вцілів — обидва пішли на дно на мілині на північ від поселення. Уцілілі члени команди дісталися берега, але втрата кораблів і капітанів кинула на порт важку тінь."},{t="Повернути втрачену пам'ять",b="Ґорболд Стілгенд, дворф, що працює в Обердайні, береться вшанувати загиблих капітанів — нічних ельфів. Хоча кораблі тепер — підводні руїни, які місцеві мурлоки привласнили як трофеї й гнізда, капітанські скриньки досі лежать замкнені в затоплених трюмах. Повернення журналів і особистих речей дасть уцілілим морякам в Обердайні змогу гідно оплакати своїх командирів і упокоїти їхні душі."}},faq={{q="Де затонулі кораблі?",a="Уламки «Срібної Зорі» й «Туманної Завіси» лежать під водою біля Темного Узбережжя, просто на північ від доків Обердайна.",al={"де затонулі кораблі","місце уламків","де срібна зоря"}},{q="Що сталося зі «Срібною Зорею» й «Туманною Завісою»?",a="Обидва кораблі потрапили в засідку мурлоків, коли пливли морем до Обердайна. Команди не встояли, обидва капітани загинули, а кораблі затонули й лягли на морське дно.",al={"як потонули кораблі","чому кораблі розбилися","що потопило туманну завісу"}},{q="Хто такий Ґорболд Стілгенд?",a="Ґорболд Стілгенд — дворф, що мешкає в портовому Обердайні нічних ельфів. Він опікується вцілілими моряками в місті й доручає шукачам пригод повернути речі загиблих капітанів.",al={"хто дає глибокий океан","переказ про ґорболда стілгенда"}},{q="Що в скриньках?",a="У скриньках — особисті речі й журнали загиблих капітанів із нічних ельфів, дорогі серцю вцілілих членів команд, які врятувалися з корабельної аварії.",al={"що в скриньках","вміст скриньки капітана"}},{q="Чому вцілілі так дорожать цими речами?",a="Капітани були шанованими мореплавцями з нічних ельфів. Повернути їхні журнали й речі означає дати вцілілій команді змогу попрощатися, і, як вірять, це допоможе духам капітанів знайти спокій.",al={"чому вцілілі дорожать речами","чому допомагати капітанам"}},{q="Які істоти тепер живуть на затонулих кораблях?",a="Уламки захопили мурлоки: вони вважають розбиті корпуси своїми трофеями й никають у водах довкола.",al={"хто охороняє кораблі","істоти біля затонулих кораблів"}}},fp="20,359,21.488.0,24.426.0,35.143.0,54.185.0,25.193.0,29.164.0,54.177.0,42.115.0"}
P.entries["quest:983"] = {n="Дзижчалка 827",s="«Дзижчалка 827» — перша ланка дослідної мережі зв'язку, яку гном Візбанґ Кранктоґґл збудував уздовж берегів Темного Узбережжя. Ці цікаві механічні пристрої постійно ламаються й мають ексцентричну конструкцію: для польового ремонту їм потрібні частини місцевих тварин. Відновивши замовклу машину, Візбанґ може випробувати свою мережу голосового зв'язку на великі відстані просто з Обердайна.",h="«Дзижчалка 827» — перша ланка дослідної мережі зв'язку, яку гном Візбанґ Кранктоґґл збудував уздовж берегів...",kw={"дзижчалка 827","візбанґ кранктоґґл","нога повзуна","повзуни","обердайн","темне узбережжя"},ang={["profession:Engineering"]="Органічний хітин і кінцівки членистоногих замість литих латунних шестерень — квінтесенція гномської імпровізації, що міняє довговічність на матеріали, які можна знайти просто під ногами.",["race:Gnome"]="Пристрій Візбанґа — класична гномська амбіція: спроба принести технологічний зв'язок у давній, дикий край, що не бачив ні телефону, ні радіо.",["race:NightElf"]="Брязкітливі, задимлені дзижчалки — дивне більмо на оці священних, похмурих берегів Калімдору, хоча нічні ельфи Обердайна терплять експерименти майстра."},sec={{t="Гномські винаходи на давніх берегах",b="Перебуваючи в Обердайні, ексцентричний гном-інженер Візбанґ Кранктоґґл задумав подолати великі відстані дикого узбережжя низкою звукових ретрансляторів далекої дії — дзижчалок. Призначені передавати голос на великі відстані, ці пристрої, обвішані важелями, різко контрастують із давніми руїнами й похмурими лісами Темного Узбережжя. Та, як і багато амбітних гномських винаходів, вони хронічно нестабільні й потребують майже постійного догляду, щоб їхні шестерні не спинялися."},{t="Екологічне обслуговування",b="Замість тягати нетрями виточені залізні шестерні й мідні шпильки Візбанґ вдався до нестандартного рішення: кожну дзижчалку він зробив так, щоб її можна було обслуговувати деталями, здобутими з місцевих звірів. Дзижчалка 827, що стоїть трохи на південь від Обердайна на імлистому березі, сконструйована працювати з міцними, членистими ногами місцевих припливних і рифових повзунів. Щойно ноги потрапляють у приймальний бункер, машина сама себе складає й оживає, транслюючи з гучномовців далекий голос Візбанґа."}},faq={{q="Що таке Дзижчалка?",a="Дзижчалка — машина для голосового зв'язку на великій відстані, яку винайшов гном Візбанґ Кранктоґґл. Оснащена важелями й внутрішнім механізмом, вона має передавати голоси через дикі простори Темного Узбережжя, щоб люди могли говорити за багато миль.",al={"що робить дзижчалка","призначення дзижчалки","гномський ящик темного узбережжя"}},{q="Навіщо металевій машині крабові лапи?",a="Візбанґ навмисно сконструював кожну Дзижчалку так, щоб вона працювала на органічних деталях від місцевих тварин як на підручних запчастинах. Поставивши Дзижчалку 827 біля пляжу, де водяться повзуни, він подбав, щоб мандрівники могли полагодити механізм у скрутну хвилину хітиновими кінцівками замість рідкісного обробленого металу.",al={"навіщо крабові лапи","ремонт крабовими лапами","чому годувати лапами"}},{q="Де Дзижчалка 827?",a="Дзижчалка 827 стоїть на березі Темного Узбережжя, недалеко на південь від прибережного Обердайна.",al={"місце дзижчалки 827","де дзижчалка 827","знайти дзижчалку 827"}},{q="Хто такий Візбанґ Кранктоґґл?",a="Візбанґ Кранктоґґл — гном-винахідник, що зупинився на верхньому поверсі корчми в Обердайні. Честолюбний і заповзятливий, він намагається збудувати мережу зв'язку по всьому Темному Узбережжю, хоч його дослідні зразки раз у раз ламаються.",al={"візбанґ кранктоґґл","хто зробив дзижчалку","гном оберіжина"}},{q="Де взяти Лапи Повзуна для ремонту?",a="Лапи Повзуна можна здобути з карликових припливних повзунів і молодих рифових повзунів, що снують піском і мілинами пляжу Темного Узбережжя трохи на південь від Обердайна.",al={"місце лап повзуна","як отримати лапи повзуна","карликовий приливний повзун"}},{q="Що буде, коли Дзижчалку 827 полагоджено?",a="Коли Лапи Повзуна закинуто в приймач, машина перемелює їх і вставляє на місце, знову оживає з гудінням і передає голос Візбанґа з Обердайна. Утішений успіхом, він одразу просить вас вирушити далі вздовж узбережжя й полагодити наступний пристрій у мережі — Дзижчалку 411.",al={"після дзижчалки 827","далі ланцюжок дзижчалки","завершення дзижчалки 827"}}},fp="11,384,36.502.0,22.539.0,18.258.0,47.302.0,29.121.0,27.256.0,45.164.0,42.278.1"}
P.entries["quest:98362"] = {n="До Тандер Блафа",s="«До Тандер Блафа» — тріумфальне повернення молодого друїда-таурена з Місячного Гаю, де він зустрівся з Колом Кенарія. Здобувши прихильність Великого Духа Кота, учень повертається до Турака Рунтотема на Узвишші Старійшин, щоб опанувати мистецтво перевтілення в кота.",h="«До Тандер Блафа» — тріумфальне повернення молодого друїда-таурена з Місячного Гаю, де він зустрівся з Колом...",kw={"друїд","котяча подоба","турак рунтотем","місячний гай","великий дух кота","дендрит старблейз","коло кенарія"},ang={["class:Druid"]="Цей обряд пробуджує ваші хижі інстинкти й дарує владу над скраданням і пазурами — так, як навчає Турак Рунтотем.",["faction:Horde"]="Хоч Коло Кенарія зберігає нейтралітет, друїди Орди мусять повертатися до своєї столиці, щоб їхня зростаюча сила служила захистові рідних.",["race:Tauren"]="Ця подорож показує, як таурени відновлюють зв'язок із традиціями Кенарія, несучи науку священного Місячного Гаю назад на Узвишшя Старійшин у Тандер Блафі."},sec={{t="Повернення з Місячного Гаю",b="Довівши свою проникливість і гідність перед Дендритом Старблейзом і Великим Духом Кота серед священних дерев Місячного Гаю, молодий друїд має принести благословення духа назад до Малгора. Єднання з такими первісними силами — переломна мить у навчанні друїда: воно поєднує давні вчення нічних ельфів із власною земною спадщиною тауренів."},{t="Опанувати котячу подобу",b="На вас чекає Турак Рунтотем — високо на Узвишші Старійшин у Тандер Блафі. Дендрит допоміг поєднатися з самим духом, а от провести тілесне перевтілення випадає Туракові. Коли благословення Великого Духа Кота визнано, старий наставник передає священне знання, потрібне, щоб прибрати стрімку, хижу котячу подобу."}},faq={{q="Де починається й закінчується це завдання?",a="Завдання дає Дендрит Старблейз у священному прихистку Місячний Гай. Воно відсилає мандрівника назад на Узвишшя Старійшин у Тандер Блафі, до Турака Рунтотема.",al={"де здати завдання","хто починає до тандер блафа","здати до тандер блафа"}},{q="Навіщо це завдання?",a="Це завершальний перехід друїдського випробування кота. Отримавши благословення Великого Духу Кота в Місячному Гаю, новачок має повернутися до свого наставника в Тандер Блафі, щоб нарешті навчитися приймати Котячу подобу.",al={"навіщо до тандер блафа","що дає до тандер блафа","завдання форми кота"}},{q="Хто такий Турак Рунтотем?",a="Турак Рунтотем — шанований старійшина друїдів-тауренів на Узвишші Старійшин у Тандер Блафі. Він опікується навчанням і посвятою молодих друїдів Орди, що прагнуть жити в гармонії з природою й опанувати свої подоби.",al={"переказ про турака рунтотема","хто такий турак"}},{q="Хто такий Дендрит Старблейз?",a="Дендрит Старблейз — нічний ельф, хранитель із Кола Кенарія, що наставляє друїдів-гостей у Нічному Притулку в Місячному Гаю. Він єднає давні традиції калдореїв і практики тауренів, хай яка напруга між фракціями.",al={"роль дендрита старблейза","нічний ельф у місячному гаю"}},{q="Що таке Великий Дух Кота?",a="Великий Дух Кота — давня первісна сутність, яку шанують друїди: він уособлює хижацький інстинкт, скрадливість і спритність. Кожен друїд, що прагне прийняти котячу подобу, мусить пройти випробування, щоб здобути його благословення й збагнути його подвійну натуру — грайливу й смертоносну.",al={"переказ про духа кота","дух кота"}},{q="Чи мають друїди Альянсу подібне завдання?",a="Так. Друїди нічних ельфів проходять подібний обряд у Місячному Гаю, але повертаються до свого наставника в Дарнасус, а не на обвітрені плато Малгору.",al={"версія для альянсу до тандер блафа","повернення нічного ельфа форми кота"}}},fp="16,278,21.359.0,22.359.0,36.169.0,34.235.0,23.236.0,26.240.0,29.262.0,43.168.0"}
P.entries["quest:98387"] = {n="Блокада Блекрок",s="Блокада Блекрок — військове завдання Альянсу від Маршала Марріса в Лейкширі. Протистоячи оркам Блекрок, що наступають на схід від Озера Незрушного, міська варта прагне заморити загарбників голодом і забрати їхню зброю.",h="Блокада Блекрок — військове завдання Альянсу від Маршала Марріса в Лейкширі.",kw={"блокада блекрок","маршал марріс","орки блекрок","фортеця кам'яної варти","лейкшир","редрідж"},ang={["class:Warrior"]="У тісних сутичках із загартованими орками Блекрок позбавити ворога важких тесаків і припасів — основа прикордонної війни.",["faction:Alliance"]="Кожна зброя, відібрана в авангарду Блекрок, дає дорогоцінний час Лейкширу, який мусить відбиватися від ворожих військ без вагомої допомоги Стормвінда."},sec={{t="Війна на виснаження",b="Клан Блекрок зухвало вдерся в Гори Редріджу, але цей нахабний наступ на землі Альянсу розтягнув його постачання до межі. Відрізані від звичних обозів, передові загони змушені виживати серед суворих пагорбів Редріджу. Маршал Марріс розуміє: навіть люті орки не можуть вести війну без постійного припасу харчів і сталі."},{t="Розгромити передові табори",b="Орківські табори на південь від Фортеці Кам'яної Варти — вістря наступу Блекрок. Нападаючи на ці табори, спустошуючи їхні схованки й забираючи щербаті бойові сокири, захисники Альянсу сподіваються підірвати бойову силу авангарду й зламати його дух."}},faq={{q="Яка мета «Блокади Блекрок»?",a="Мета — підірвати передові табори клану Блекрок на південь від Фортеці Кам'яної Варти. Нападаючи на шляхи постачання, забираючи харчі й захоплюючи зброю, варта Лейкшира сподівається заморити орків голодом і послабити їхній наступ на Редрідж.",al={"що таке блокада блекрок","мета блокади блекрок","призначення блокади"}},{q="Хто дає це доручення?",a="Маршал Марріс, командир міської варти Лейкшира, керує обороною Редріджу й спрямовує зусилля, щоб зірвати постачання Блекрок.",al={"хто дає блокаду блекрок","видавець","завдання маршала маріса"}},{q="Де табори Блекрок?",a="Воєнні табори, на які спрямовано удар, — на східних пагорбах Гір Редріджу, трохи на південь від Фортеці Кам'яної Варти, через річку від Лейкшира.",al={"де орки","місце табору блекрок","де табір кам'яної варти"}},{q="Чому Лейкшир робить ставку на виснаження, а не на прямий штурм?",a="Варті Лейкшира бракує людей, а підкріплень від Стормвінда — кіт наплакав. Це війна на виснаження: зухвалий наступ орків Блекрок на землі Альянсу лишив їх вразливими й без припасів, вони залежать від ресурсів навколишніх гір, а з порожнім шлунком війська не повоюєш.",al={"чому виснажувати орків","чому не штурмувати кам'яну варту","стратегія лейкширу"}},{q="Яку зброю забирають в орків?",a="Розвідники й солдати Альянсу збирають Зужиті в Боях Сокири, які носить передовий загін Блекрок, — так загарбників роззброюють, а з їхніх передових таборів забирають важку зброю.",al={"які предмети потрібні","які сокири","переказ про зношені сокири"}},{q="Чи ці орки пов'язані з Ордою Тралла?",a="Ні. Орки Блекрок у Редріджі належать до відступницької Темної Орди, що засіла в Горі Блекрок. Вони не визнають проводу Тралла й люто ворожі і до Альянсу, і до нової Орди.",al={"чи це орда","чи блекрок орда","клан блекрок тралла"}}},fp="18,226,18.396.0,26.291.0,43.267.0,27.167.0,46.134.0,67.307.0,49.166.0,46.205.0"}
P.entries["quest:98389"] = {n="Світло в темряві",s="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні доручає шукачам пригод із Відступників врятувати новопідняту нежить, що потрапила в пастку в Лощині Нічної Павутини. Воно висвітлює делікатні стосунки між носіями Святого Світла з нежиті та людом, який їм глибоко не довіряє. Допомагаючи полеглим родичам, ці носії святої сили сподіваються довести свою вірність Сильвані та справі Відступників.",h="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні доручає шукачам пригод із Відступників врятувати...",kw={"світло в темряві","араміс гаммергенд","лощина нічної павутини","павуки","порятунок","святе світло"},ang={["class:Priest"]="Для Відступників, які спрямовують святу енергію, ця місія ілюструє тонку линву між залишковою смертною вірою і суворою дійсністю нежиття.",["race:Undead"]="Це завдання показує складну внутрішню боротьбу Відступників — те, як окремі з них долають упередження серед власного щойно повсталого народу."},sec={{t="Хистка віра",b="Святе Світло горезвісно болісне й небезпечне для нежиті, та дехто з Відступників зберігає зв'язок зі священною магією, якою володів за життя. У Похоронному Подзвоні такі постаті, як Араміс Гаммергенд, прагнуть довести, що їхня віра не обернула їх проти власного народу. Щоб розвіяти підозру, нібито носії святої сили повернуться проти іншої нежиті як проти потвор, вони діяльно використовують свої вміння й співчуття, щоб захищати родичів."},{t="Лощина Нічної Павутини",b="На північний захід від Похоронного Подзвону лежить Лощина Нічної Павутини — вогка печера, що кишить лютими павуками. Свіжопіднята нежить, ще спантеличена пробудженням і не здатна себе захистити, раз у раз забрідає в лощину й опиняється в коконах липкого павутиння. Порятунок цих нещасних Відступників служить подвійній меті: зберегти новобранців для Темної Леді й довести очільникам на кшталт Екзекутора Аррена, що носії Світла — віддані слуги Відступників."}},faq={{q="Хто дає завдання «Світло в темряві»?",a="Завдання дає Араміс Гаммергенд — служитель Світла, що перебуває в Похоронному Подзвоні на Галявинах Тірісфалю.",al={"видавець","хто починає світло в темряві","завдання араміса гаммергенда"}},{q="Де Западина Нічного Павутиння?",a="Западина Нічного Павутиння — на північний захід від Похоронного Подзвону, серед пагорбів Галявин Тірісфалю.",al={"місце западини нічного павутиння","де обплутані жертви","де печера"}},{q="Чому Відступники не довіряють тим, хто володіє Світлом?",a="Святе Світло пече й небезпечне для плоті нежиті. Чимало Відступників бояться, що кожен, хто володіє святою силою, може побачити в них потвор, яких треба знищити, а не братів, яких треба прийняти.",al={"чому боятися світла","чому відступники ненавидять паладинів","святий страх відступників"}},{q="Хто ці жертви, обплутані павутинням?",a="У коконах — щойно пробуджені шукачі пригод із Відступників, що необачно забрели в павучі печери, ще не встигнувши освоїтися.",al={"хто обплутаний","що всередині павутиння","жертви в пастці"}},{q="Хто такий Екзекутор Аррен і чому Араміс хоче справити на нього враження?",a="Екзекутор Аррен відповідає за військовий і громадський лад у Похоронному Подзвоні. Здобути його довіру вкрай важливо для тих, хто володіє святою силою й хоче безболісно влитися до лав Відступників.",al={"хто такий екзекутор аррен","чому аррен важливий"}},{q="Чи справді нежить може володіти Святим Світлом?",a="Так: завдяки неймовірній силі волі й відданості дехто з нежиті зберігає зв'язок зі Світлом, хоча спрямовувати його нестерпно боляче, а власне суспільство дивиться на таких із підозрою.",al={"чи нежить володіє світлом","переказ про світло нежиті"}}},fp="23,388,18.444.0,18.480.0,44.104.0,36.90.0,51.201.0,40.137.0,63.169.0,43.194.0"}
P.entries["quest:98397"] = {n="До Дарнасуса",s="«До Дарнасуса» — завершення подорожі друїда нічних ельфів до єднання з Великим Духом Кота. Довівши свою гідність Дендритові Старблейзу в Місячному Гаю, ви повертаєтеся до Ценаріонського Анклаву, щоб опанувати мистецтво перетворення на кота.",h="«До Дарнасуса» — завершення подорожі друїда нічних ельфів до єднання з Великим Духом Кота.",kw={"до дарнасуса","великий дух кота","котяча подоба","дендрит старблейз","матренґіл берволкер","ценаріонський анклав","друїд"},ang={["class:Druid"]="Це завдання знаменує ваш перехід до полювання з тіні: ви отримуєте змогу спрямовувати силу Великого Духа Кота просто через котячу подобу.",["faction:Alliance"]="Друїди Альянсу повертаються з нейтральних земель Місячного Гаю до Дарнасуса й зміцнюють магічний захист своєї батьківщини.",["race:NightElf"]="Повернення до Дарнасуса вшановує традиції нічних ельфів, які Коло Кенарія береже під Світовим Древом Тельдрассилом."},sec={{t="Повернення до Анклаву",b="Поєднавшись із Великим Духом Кота під проводом Дендрита Старблейза в Місячному Гаю, молодий друїд нічних ельфів має повернутися на Тельдрассил. Старблейз визнає, що ви довели себе гідним учнем, і скеровує вас назад до вашого головного наставника — Матренґіла Берволкера, що чекає під гіллям Ценаріонського Анклаву в Дарнасусі."},{t="Природа кота",b="Коли ви прибуваєте до Дарнасуса, Матренґіл Берволкер визнає, що ви увібрали мудрість Великого Духа Кота. На його думку, кожне покоління друїдів проходить випробування, яке визначає ця прадавня сутність — така ж грайлива, як і смертоносна. Тепер, коли зв'язок налагоджено, а дух готовий, Матренґіл передає вам останні обряди, потрібні, щоб прийняти граційну котячу подобу."}},faq={{q="Навіщо це завдання?",a="Це завдання завершує ваше випробування Великим Духом Кота. Коли ви виконаєте доручення Дендрита Старблейза в Місячному Гаю, воно скерує вас назад до Матренґіла Берволкера в Дарнасус, щоб той навчив вас приймати котячу подобу.",al={"навіщо це завдання","мета до дарнасуса","завдання форми кота"}},{q="Хто посилає вас назад до Дарнасуса?",a="Дендрит Старблейз — старший друїд, що мешкає в Нічному Притулку у священному прихистку Місячний Гай, — дає вам це завдання, коли ви отримаєте благословення Великого Духу Кота.",al={"хто починає це завдання","видавець"}},{q="Де знайти Матренґіла Берволкера?",a="Матренґіл Берволкер — у Ценаріонському Анклаві, друїдській святині в північно-західній частині Дарнасуса на Тельдрассилі.",al={"місце матренґіла","де берволкер"}},{q="Що означає Великий Дух Кота?",a="Великий Дух Кота — давній дикий дух природи, що уособлює спритних і смертоносних хижаків. Друїди мусять здобути його прихильність і збагнути його подвійну натуру — грайливість і смертоносність, — перш ніж їм дозволять приймати його подобу.",al={"переказ про духа кота","що таке великий дух кота"}},{q="Чи всі друїди проходять однакове випробування?",a="За словами Матренґіла Берволкера, усі друїди мусять пройти випробування Великого Духу Кота, щоб опанувати його подобу, але саме випробування від покоління до покоління буває різним.",al={"чи випробування друїдів однакові","випробування поколінь"}},{q="Чи можуть узятися за це завдання не нічні ельфи?",a="Саме це завдання — для друїдів-нічних ельфів Альянсу, що повертаються до Дарнасуса. Друїди-таурени мають власний шлях: побувавши в Місячному Гаю, вони доповідають своїм наставникам у Тандер Блафі.",al={"чи це лише для альянсу","чи таурени можуть це"}}},fp="12,246,21.359.0,21.391.0,34.229.0,32.172.0,39.143.0,49.232.0,44.180.0,36.193.0"}
P.entries["quest:984"] = {n="Наскільки велика загроза?",s="«Наскільки велика загроза?» — завдання Альянсу, яке дає Терентіс в Обердайні. Побачивши, як божевілля фурболгів укорінюється на Тельдрассилі, друїд посилає розвідників дослідити місцеві поселення фурболгів на Темному Узбережжі, щоб з'ясувати, чи та сама темна скверна перетнула море.",h="«Наскільки велика загроза?» — завдання Альянсу, яке дає Терентіс в Обердайні.",kw={"наскільки велика загроза","терентіс","фурболги","тельдрассил","амет'аран","обердайн"},ang={["class:Druid"]="Фурболгів пов'язують глибокі узи з природою й давніми духами нетрів, тож їхнє раптове падіння в порчу — тяжка тривога для друїдів, покликаних відновлювати рівновагу Калімдору.",["faction:Alliance"]="Обердайн — головні ворота Альянсу на материкову північ Калімдору, тож захистити його від загроз із нетрів украй важливо для безпеки й постачання краю.",["race:NightElf"]="Для калдореїв бачити, як давні союзники на кшталт фурболгів так скоро після Третьої війни піддаються безглуздій темряві, — і гірка трагедія, і пряма небезпека для священних земель."},sec={{t="Тіні за морем",b="Нічні ельфи півночі Калімдору здавна підтримували приязні чи мирні стосунки з місцевими племенами фурболгів. Та після Третьої війни дивна порча почала затьмарювати розум фурболгів на Тельдрассилі, і це обернулося жорстокими викраденнями й дикими нападами на колишніх союзників. Друїд Терентіс, що перебуває в Обердайні, боїться, що ця зловісна недуга не обмежилася Світовим Деревом, а вже шириться серед материкових племен на імлистих берегах Темного Узбережжя."},{t="Буря, що насувається",b="Розвідка табору фурболгів біля руїн Амет'Арана підтверджує найгірші підозри Терентіса. Тамтешні фурболги виявляють безладну, ворожу агресію й несуть явні ознаки тієї самої порчі, що вразила північ. Через близькість до Обердайна вони вже не мирні сусіди з нетрів, а нагальна загроза для поселення Альянсу."}},faq={{q="Хто такий Терентіс?",a="Терентіс — друїд нічних ельфів у прибережному прихистку Обердайн. Не маючи спокою через розповіді про нічних ельфів, на яких нападали й яких брали в полон навіжені фурболги на Тельдрассилі, він стежить за новими загрозами на Темному Узбережжі й придушує їх.",al={"видавець терентіс","хто дає наскільки велика загроза","терентіс оберіжин"}},{q="Чому фурболги на Темному Узбережжі стають ворожими?",a="Terenthis has seen hints of corruption in Darkshore and suspects the furbolgs may be affected, as some on Teldrassil were. He asks for their camps to be investigated because he has not yet established widespread signs.",al={"чому фурболги ворожі","осквернені фурболги темного узбережжя","осквернення фурболгів"}},{q="Де табір зіпсованих скверною фурболгів?",a="Табір — у глибині суходолу в центрі Темного Узбережжя, трохи на північ від давніх руїн Високородних Амет'Арана й на південний схід від Обердайна.",al={"місце табору","де табір фурболгів","місце загрози"}},{q="Як це пов'язано з подіями на Тельдрассилі?",a="На Тельдрассилі кілька зіпсованих скверною фурболгів викрали й поранили Вартових і мирних нічних ельфів. Терентіс згадує ці недавні рятувальні вилазки, коли намагається з'ясувати, чи не спіткала така сама біда материкове Темне Узбережжя.",al={"зв'язок з тельдрассилом","фурболги тельдрассила","чому терентіс згадує тельдрассил"}},{q="Що буде після доповіді Терентісові?",a="Report any signs of corruption to Terenthis in Auberdine. His response to the findings is revealed when you return.",al={"наступне завдання","що після наскільки велика загроза","продовження завдання"}},{q="Чому нічних ельфів так непокоять табори фурболгів біля Обердайна?",a="Обердайн — головний порт Альянсу й життєво важливий шлях постачання на материку. Глибоко зіпсовані скверною ворожі племена, що оселилися на відстані удару, роблять торговельні шляхи, розвідувальні загони й саме містечко вразливими до раптових нападів.",al={"загроза оберіжину","чому турбують фурболги"}}},fp="17,284,22.502.0,17.381.1,17.245.0,50.218.0,42.141.0,45.214.0,47.115.0,68.246.0"}
P.entries["quest:98407"] = {n="Демонстрація сили",s="Демонстрація сили — оборонне завдання Альянсу в Горах Редріджу від Помічника Фелдона. Щоб зупинити зграї гнолів, які підступають до Лейкширу, шукачів пригод посилають полювати на гнолів-трощителів і збирати їхні нашийники з шипами — щоб відбити гнолам охоту вдиратися в людські поселення.",h="Демонстрація сили — оборонне завдання Альянсу в Горах Редріджу від Помічника Фелдона.",kw={"демонстрація сили","помічник фелдон","гноли","нашийники з шипами","лейкшир","редрідж"},ang={["class:Warrior"]="Гноли поступаються лише прямому, нищівному насильству, тож чесна дисципліна передової — найкращий спосіб зламати їхні лави.",["faction:Alliance"]="Лейкшир — один із найсхідніших бастіонів Альянсу на півдні Східних Королівств; захистити його кордони від навали звіролюдей вкрай важливо для спокою всього краю.",["race:Human"]="Хуторяни й містяни Редріджу — такі самі піддані Стормвінда, залишені небезпечно беззахисними; вони покладаються на одноплемінників, щоб відбити диких мародерів."},sec={{t="Зухвалий наступ",b="Гори Редріджу здавна були прихистком диких племен гнолів, але останнім часом вони дедалі зухвалішають. Замість того щоб сидіти високо в скелястих пагорбах, ватаги гнолів-грабіжників отаборилися тривожно близько до Лейкширу й віддалених людських хуторів. Військо Стормвінда розпорошене й не може виділити підкріплення для сільського прикордоння, тож місцева влада мусить покладатися на мандрівних шукачів пригод, щоб захистити околиці, перш ніж ці ватаги наберуться духу вдарити по самому містечку."},{t="Говорити їхньою мовою",b="Помічник Фелдон розуміє, що гноли — жорстокі, неорганізовані створіння, які поважають лише грубу силу. Щоб загнати їх назад у глушину, дипломатичні заклики чи напівзаходи марні. Фелдон хоче вдарити по їхньому найлютішому авангарду — гнолах-трощителях — і забрати їхні нашийники з шипами як похмурий доказ переваги. Розбивши їхніх передових бійців і виставивши напоказ трофеї їхньої поразки, захисники Лейкширу сподіваються залякати решту зграй і змусити їх відступити назад у високогір'я."}},faq={{q="Хто дає це завдання і де він?",a="Завдання дає Помічник Фелдон — міський вартовий, що стоїть на околиці біля Лейкшира в Горах Редріджу.",al={"хто дає завдання","місце помічника фелдона","видавець демонстрації сили"}},{q="Чому гноли підступають так близько до Лейкшира?",a="Гноли — агресивні пристосуванці, що раз у раз перевіряють межі дозволеного. Лейкширу бракує оборонців, а військової допомоги від Стормвінда — обмаль, тож гноли так осміліли, що влаштовують мисливські табори просто під землями, заселеними людьми.",al={"чому гноли так близько","чому гноли нападають","загроза гнолів реджридж"}},{q="Яких ворогів треба здолати в цьому дорученні?",a="Ціль — гноли-трощителі, найнебезпечніші й найагресивніші ударні бійці місцевих зграй, що носять важкі шипасті нашийники.",al={"які гноли","яких мобів убивати","гноли-побивачі"}},{q="Чому Помічникові Фелдону потрібні саме шипасті нашийники?",a="У гнолів панує жорстока ієрархія й сила. Забрати шипасті нашийники їхніх трощителів — пряма демонстрація сили, яка має налякати вцілілих гнолів і змусити їх відступити назад у пагорби.",al={"чому шипасті нашийники","призначення нашийників","навіщо забирати нашийники"}},{q="Чи може Стормвінд прислати солдатів, щоб упоратися з гнолами?",a="Стормвінд здебільшого полишив Редрідж боронитися самотужки. Серед внутрішньої непевності й браку військ по всьому королівству столиця майже не надсилає підкріплень, тож місцеві помічники мусять покладатися на незалежних звитяжців.",al={"допомога стормвінда реджриджу","чому немає армії стормвінда","де вартові"}},{q="Де в Редріджі зазвичай таборують гноли?",a="Табори гнолів розкидані по пагорбах і невисоких хребтах довкола Озера Незрушного та вздовж доріг, що ведуть на схід до Кам'яної Варти.",al={"табори гнолів","де знайти гнолів","місця гнолів реджридж"}}},fp="13,284,19.520.0,23.530.0,49.120.0,49.244.0,50.136.0,56.214.0,55.228.0,52.149.0"}
P.entries["quest:985"] = {n="Наскільки велика загроза?",s="«Наскільки велика загроза?» — завдання Альянсу, яке дає нічний ельф Терентіс в Обердайні. Після розвідки ворожого табору фурболгів Чорнолісся на південь від містечка шукачів пригод посилають знищити зіпсованих слідопитів і вітромовців, перш ніж їхній шал загрожуватиме поселенню.",h="«Наскільки велика загроза?» — завдання Альянсу, яке дає нічний ельф Терентіс в Обердайні.",kw={"наскільки велика загроза","терентіс","фурболги чорнолісся","похмурий кіготь","мох скверни","обердайн"},ang={["class:Druid"]="Друїди гостро відчувають цю трагедію, бо біда фурболгів віддзеркалює безупинні страждання лісу під порчею моху Скверни.",["faction:Alliance"]="Обердайн — важливий портовий оплот Альянсу на Темному Узбережжі, тож знищення ворожих таборів поблизу украй важливе для безпеки краю.",["race:NightElf"]="Для нічних ельфів проріджувати Чорнолісся — гірке горе: століття спорідненості з фурболгами розбила демонічна пошесть, що лишилася після Третьої війни."},sec={{t="Необхідне проріджування",b="Після першої розвідки на південь від Обердайна Вартові дійшли висновку, що фурболги Чорнолісся становлять пряму загрозу для біженців і захисників Темного Узбережжя. Терентіс доручає мандрівникам, здатним до бою, вдарити просто по їхньому табору й знищити слідопитів і вітромовців Чорнолісся, щоб зламати їхній наступальний порив."},{t="Трагедія зіпсованих",b="Нічні ельфи здавна вважають фурболгів духовною ріднею й давніми союзниками в нетрях. Та злоякісне поширення моху Скверни й демонічної порчі на півночі Калімдору звело плем'я Чорнолісся з розуму. Ліків, що повернули б фурболгам розум, не знають, тож захисники Обердайна вважають насильство похмурою необхідністю, щоб уберегти невинних від загибелі."},{t="Прихід Похмурого кігтя",b="Коли мандрівник доповідає Терентісові про виконане, до Обердайна вбігає білий ведмідь на ім'я Похмурий кіготь і мчить до нічного ельфа. Його поява віщує нагальні новини про звірів і порчу, що спустошують узбережжя, і запускає наступний етап оборони Обердайна."}},faq={{q="Чому Терентіс хоче знищити фурболгів Чорнолісся?",a="Плем'я Чорнолісся на південь від Обердайна піддалося скверні й стало жорстоким і нерозсудливим. Їхній табір прямо загрожує поселенню, а ліків від їхньої скверни поки не знайдено, тож Терентіс наказує завдати випереджального удару, щоб уберегти Обердайн.",al={"чому вбивати фурболгів чорнолісся","причина винищення фурболгів","завдання терентіса про фурболгів"}},{q="Де табір фурболгів Чорнолісся?",a="Табір — трохи на південь від Обердайна, у прибережному лісі Темного Узбережжя, серед зіпсованих скверною дерев, де зібралося плем'я Чорнолісся.",al={"місце фурболгів чорнолісся","де слідопити й вітрогуди","табір фурболгів темне узбережжя"}},{q="Хто такий Похмурий кіготь?",a="Похмурий кіготь — білий ведмідь, пов'язаний із розслідуваннями в нетрях Темного Узбережжя.",al={"білий ведмідь оберіжин","похмурий кіготь ведмідь"}},{q="Що доводить фурболгів до божевілля?",a="Фурболгів отруїли мох Скверни й рештки демонічної скверни, що лишилися після Третьої війни. Темна енергія, яка спустошує Темне Узбережжя, спотворює і розум, і тіло, доводячи мирні племена до некерованої агресії.",al={"чому фурболги шаленіють","осквернення фурболгів темного узбережжя","що осквернило чорноліссе"}},{q="Чому нічним ельфам так не хочеться вбивати фурболгів?",a="Фурболгів і нічних ельфів тисячі років єднали дружба й шанування природи. Вбивати їх для нічних ельфів — усе одно що різати власних братів із дикого лісу, але скверна не лишає іншого вибору.",al={"нічні ельфи й фурболги","чому оплакувати фурболгів"}},{q="Чим різняться перше й друге завдання «Наскільки велика загроза?»?",a="Перше завдання перевіряє вміння розвідувати: вам треба знайти табір Чорнолісся й спостерігати за ним. Друге — пряме бойове доручення: коли загрозу підтверджено, треба проредити слідопитів і вітромовців табору.",al={"частини наскільки велика загроза","різниця між завданнями"}}},fp="17,277,16.332.0,24.358.0,18.281.1,54.277.0,44.150.0,16.84.1,39.227.0,47.250.0,79.225.0"}
P.entries["quest:98576"] = {n="Гліфічний Пергамент",s="Гліфічний Пергамент — вступний виклик для майбутніх магів у Долині Випробувань. Передане через Ґорнека, письмове послання веде новачків до Май'ї, наставниці магів-тролів біля Лігва, щоб розпочати їхню дисципліну в таємній магії.",h="Гліфічний Пергамент — вступний виклик для майбутніх магів у Долині Випробувань.",kw={"маг","май'а","гліфічний пергамент","долина випробувань","таємна магія","ґорнек"},ang={["class:Mage"]="Це послання знаменує ваше офіційне визнання учнем таємної магії й скеровує вас до Май'ї, щоб почати вчитися й розширювати свою книгу заклинань.",["faction:Horde"]="Наставництво в Долині Випробувань дбає, щоб навіть такі мінливі мистецтва, як таємна магія, плекалися з дисципліною на зміцнення майбутнього Орди.",["race:Troll"]="Май'а втілює дедалі міцніші традиції таємної магії Темного Списа: вона ділиться своїм космічним знанням, щоб вести і тролів-одноплемінників, і новобранців-союзників."},sec={{t="Виклик до навчання",b="Поки нові новобранці доводять свою тілесну стійкість у сутичках із тутешніми шкідниками Дуротару, ті, хто має хист до таємної магії, не можуть покладатися лише на грубу силу. Ґорнек передає письмове повідомлення, списане рунами, яке велить чарівникам-початківцям розшукати Май'ю — вона наглядає за першим магічним навчанням найновіших новобранців Орди."},{t="Шлях таємної магії",b="Стоячи одразу біля входу до Лігва, Май'а стримує амбіції молодих чарівників. Замість безоглядно жбурляти сире чаклунство, вона наголошує на терпінні, вчасності й виваженому розумі. Під її проводом новачки вчаться бачити всесвіт як тонкі нитки, які треба ткати, а не як буремну стихію, яку треба спустити з ланцюга."}},faq={{q="Хто надсилає Гліфічний Пергамент?",a="Пергамент надсилає Май'а — наставниця магів, що стоїть біля Лігва в Долині Випробувань. Лист у Ґорнека, і він віддає його, щойно молодий маг починає свої випробування.",al={"хто писав гліфічний пергамент","хто надіслав","автор пергаменту"}},{q="Де знайти Май'а?",a="Май'а — у Долині Випробувань у Дуротарі, просто біля входу в Лігво, разом з іншими класовими наставниками.",al={"де май'а","місце май'а","знайти май'а"}},{q="Навіщо це завдання?",a="Воно знайомить молодих магів з їхньою класовою наставницею. Розмова з Май'а починає ваше справжнє навчання тайних мистецтв і відкриває доступ до нових заклять і основ вишколу.",al={"що робить гліфічний пергамент","навіщо це завдання","мета завдання"}},{q="Як Май'а дивиться на магію?",a="Май'а вчить, що тайна магія вимагає розуму, стриманості й виваженого терпіння. Справжній маг не діє зопалу, а уважно спостерігає й завдає удару в точно вибрану мить, відповідаючи так, як годиться.",al={"чого вчить май'а","переказ про май'а"}},{q="Чому в Долині Випробувань магів навчає троль?",a="Долина Випробувань приймає і молодих орків, і тролів Темного Спису, що вступають до лав Орди. Заклиначі Темного Спису на кшталт Май'а діляться мудрістю й майстерністю володіння космічними силами, навчаючи новачків.",al={"чому троль-маг","тролі й аркана","наставник-троль у землях орків"}},{q="Хто передає пергамент гравцеві?",a="Ґорнек — головний наглядач випробувань у центральному таборі Долини Випробувань — передає пергамент, коли ви повертаєтеся до нього під час перших доручень.",al={"хто дає гліфічний пергамент","завдання ґорнека"}}},fp="17,250,18.345.0,21.326.0,32.183.0,26.132.0,34.186.0,37.221.0,54.209.0,41.159.0"}
P.entries["quest:986"] = {n="Зниклий господар",s="«Зниклий господар» доручає шукачеві пригод Альянсу зібрати матеріали для пошуків Волкора — нічного ельфа, що зник у нетрях Темного Узбережжя. Терентіс в Обердайні пропонує виткати зачарований маскувальний плащ, щоб захистити рятівника, але для цього потрібні шкури найлютіших місячних скрадачів узбережжя.",h="«Зниклий господар» доручає шукачеві пригод Альянсу зібрати матеріали для пошуків Волкора — нічного ельфа, що...",kw={"зниклий господар","волкор","терентіс","похмурий кіготь","шкура місячного хижака","місячні скрадачі"},ang={["class:Druid"]="Друїди оцінять шану Терентіса до природної потайності місячних скрадачів: їхню дику сутність він обертає на захисне маскування.",["class:Hunter"]="Мисливці впізнають зв'язок між Волкором і Похмурим кігтем, а також майстерність, потрібну, щоб вистежити й вполювати матріархів і вожаків Темного Узбережжя.",["race:NightElf"]="Пошуки Волкора відбивають обов'язок нічних ельфів берегти своїх родичів і диких супутників у неприборканих куточках Темного Узбережжя."},sec={{t="Пошуки в нетрях",b="Стежачи за загрозами на берегах Темного Узбережжя, Терентіс в Обердайні непокоїться за долю Волкора та його товариша — Похмурого кігтя. Південні околиці краю славляться небезпекою через агресивних хижаків і зіпсованих звірів. Замість посилати розвідника без захисту Терентіс вигадує план: виткати захисний плащ, сповнений чарів дикої ілюзії."},{t="Шкури зграї",b="Щоб виткати плащ, здатний збити з пантелику звірів Темного Узбережжя, звичайних шкур не досить. Терентісові потрібні вишукані шкури, здобуті саме зі старих вожаків чи матріархів місячних скрадачів. Ці грізні великі коти нишпорять лісами на південь від Обердайна біля Річки Дикого Закруту й аж до лісистого кордону з Ашенвалем."},{t="Делікатна магія",b="Готове вбрання з хутра місячних скрадачів і чарів природи дає власникові змогу безперешкодно проходити ворожими землями, шукаючи Волкора. Проте Терентіс попереджає, що ілюзія крихка: будь-яке важке зусилля чи бій розвіюють чари й лишають шукача беззахисним."}},faq={{q="Хто такий Волкор?",a="Волкор — нічний ельф, розвідник чи слідопит, що зник у нетрях на півдні Темного Узбережжя. Його супутник Похмурий кіготь і Терентіс в Обердайні шукають, де він, — так і починаються пошуки.",al={"хто такий волкор","переказ про волкора","зниклий господар волкор"}},{q="Хто дає це доручення?",a="Терентіс — нічний ельф з Обердайна на Темному Узбережжі — дає завдання, після того як шукачі пригод допоможуть йому з попередніми місцевими клопотами.",al={"видавець завдання","де взяти зниклого господаря","місце терентіса"}},{q="Де водяться вожаки й матріархині місячних скрадачів?",a="Ці дорослі місячні скрадачі никають півднем Темного Узбережжя, особливо біля берегів Річки Дикого Закруту й далі на південь, ближче до межі з Ашенвалем.",al={"місця шкур місячних скрадачів","де місячні скрадачі","коти вайлдбенд"}},{q="Навіщо потрібен плащ?",a="Терентіс хоче зробити зачарований плащ, що ховає власника від ворожих звірів Темного Узбережжя, — так можна буде шукати Волкора, не наражаючись раз у раз на напади.",al={"що робить плащ","плащ терентіса","зачарування плаща"}},{q="Чому Терентісові потрібні саме ці шкури?",a="Звичайні шкури не мають сили й природної потуги, щоб утримати маскувальні чари. Витримати зачарування можуть лише товсті, міцні шкури вожаків і матріархинь.",al={"чому вожаки й матріархині","чому саме ці шкури"}},{q="Чи має маскувальний плащ обмеження?",a="Так. Терентіс попереджає, що чари крихкі. Говорити з іншими можна, але різкі дії чи бій швидко розвіють ілюзію.",al={"чи плащ має обмеження","чи ілюзія зникає"}}},fp="13,298,23.399.0,18.341.0,14.304.0,14.185.0,21.154.0,49.157.0,30.179.0,39.181.0,43.157.0"}
P.entries["quest:98601"] = {n="Важкий шлях",s="Важкий шлях — формальний початок навчання паладина Відступників в Похоронному Подзвоні. Упоравшись із безтямною нежиттю, що повстає зі склепів, щойно пробуджені поборники Світла отримують наказ з'явитися до Араміса Гаммергенда в сільській церкві, щоб зіткнутися з болісною дійсністю володіння святою енергією в нежитті.",h="Важкий шлях — формальний початок навчання паладина Відступників в Похоронному Подзвоні.",kw={"важкий шлях","араміс гаммергенд","паладин","освячений сувій","сарвіс","горнило"},ang={["class:Paladin"]="Це завдання — засадниче випробування паладина Відступників: свята сила тут не легке благословення, а болісне горнило дисципліни й витривалості.",["race:Undead"]="Для Відступників звернення до Світла доводить, що відданість і дисципліна здатні пережити фізичну смерть, навіть якщо магія діяльно спалює посудину, яка її спрямовує."},sec={{t="Смердючий сувій",b="Коли щойно пробуджений паладин Відступників закінчує винищувати здичавілу нежить біля склепу, Жрець Тіні Сарвіс вручає несподівану посилку. Освячений Сувій випромінює святу енергію так потужно, що жрець тіні помітно сахається й прямо просить носія відійти. Для адепта тіні й тління сама аура Святого Світла — як відкритий вогонь."},{t="Горнило святого вогню",b="В оскверненій церкві Похоронного Подзвону чекає Араміс Гаммергенд, наставник паладинів Відступників. Там, де інші раси володіють Світлом природно й радісно, нежить, що звертається до нього, зазнає пекучих, нутряних мук. Араміс не пом'якшує удару: спрямовувати святу силу крізь гниючу посудину — чиста мука, та він вимагає, щоб його учні приймали біль, а не сахалися від нього, і використовували його як горнило, що гартує їхню новознайдену рішучість."}},faq={{q="Чому Жерцеві Тіні Сарвісу не подобається сувій?",a="Жрець Тіні Сарвіс відданий магії тіні й дбає про своїх братів-нежить. Освячений Сувій випромінює чисту святу енергію, яка від природи ворожа плоті нежиті й глибоко непокоїть тих, хто служить Тіні.",al={"чому сарвіс не любить сувій","святий сувій сарвіса","реакція жреця тіні на сувій"}},{q="Чи можуть Відступники справді володіти Святим Світлом і не гинути?",a="Відступники можуть володіти Світлом завдяки самій лише силі волі й вірі, але це завдає їм пекучого болю всередині й знову розпалює мертві нервові закінчення, тож вони відчувають власне тління. Щоб спрямовувати Світло, потрібна величезна душевна витривалість.",al={"переказ про паладинів відступників","нежить і світло","чи світло шкодить відступникам"}},{q="Хто такий Араміс Гаммергенд?",a="Араміс Гаммергенд — наставник паладинів у каплиці Похоронного Подзвону. Він веде щойно піднятих паладинів із Відступників, навчаючи їх витримувати муки, яких завдає Світло нежиті, і кувати з нього дієву зброю.",al={"хто такий араміс гаммергенд","наставник паладинів похоронного подзвону","роль араміса"}},{q="Де відбувається це завдання?",a="Завдання починається в Жерця Тіні Сарвіса на центральній галявині Похоронного Подзвону й закінчується за кілька кроків, у зруйнованій сільській каплиці, де перебуває Араміс Гаммергенд.",al={"де важкий шлях","місце завдання","де церква похоронного подзвону"}},{q="Чи треба читати Освячений Сувій, щоб виконати завдання?",a="Ні, читати сувій не обов'язково: ваше навчання просунеться, щойно ви поговорите з Арамісом Гаммергендом у церкві.",al={"читати освячений сувій","чи обов'язково читати сувій","пропустити читання сувою"}},{q="Чому шлях називають «важким»?",a="Ця назва відбиває суворий шлях паладина з Відступників. Інші воїни Світла знаходять у вірі розраду й утіху, а паладин-нежить мусить терпіти пекучий святий вогонь, що струменить мертвою плоттю щоразу, як він благословляє чи завдає удару.",al={"чому важкий шлях","значення назви"}}},fp="16,322,16.384.0,25.449.0,49.238.0,54.230.0,25.226.0,33.179.0,63.159.0,35.256.0"}
P.entries["quest:99"] = {n="Безумство Аруґала",s="«Безумство Аруґала» досягає вершини в небезпечному розслідуванні прокляття, що тримає Село Пайрвуд. Далар Донвівер доручає агентам Орди здобути зачаровані кайдани з селян, щоб розгадати викривлену роботу Архімага Аруґала. Розплутування цих пут відкриває трагічну магію, що тримає поселення в тіні воргенів.",h="«Безумство Аруґала» досягає вершини в небезпечному розслідуванні прокляття, що тримає Село Пайрвуд.",kw={"безумство аруґала","село пайрвуд","кайдани пайрвуда","далар донвівер","воргени","мунрейдж","прокляття"},ang={["class:Mage"]="Для знавців чарівної магії Аруґалові кайдани — похмуре нагадування про те, як чаклунство Кірін-Тору може скотитися в божевілля, коли змішується з викликаними потойбічними звірами.",["faction:Horde"]="Здобувши ці кайдани, ви ламаєте містичну хватку Аруґала над дорогою, що веде на південь, до Стіни Ґреймейна.",["race:Undead"]="Відступники дивляться на Село Пайрвуд з холодною зацікавленістю й безжальним прагматизмом і прагнуть розібрати Аруґалові чари, щоб убезпечити південне Срібнолісся."},sec={{t="Подвійне життя Пайрвуда",b="На південь від Гробниці лежить Село Пайрвуд — поселення, що застрягло в моторошному стані. За денного сонця його мешканці живуть як звичайні людські селяни — полохливі й відлюдні. Та щойно на ліс спадають сутінки, їхні людські тіла розриваються, і вони обертаються на диких воргенів Мунрейдж, що блукають вулицями під владою Аруґала. Далар Донвівер прагне розгадати чарівні пута, що спричиняють цей щодобовий жах."},{t="Розбити кайдани",b="Щоб дослідити чари, які тримають Пайрвуд у неволі, Донвіверу потрібні зачаровані Кайдани Пайрвуда, зняті просто з перетворених селян. Це не просто залізо: ці пута гудуть залишковим чаклунством невдалих Аруґалових захисних чарів. Вивчаючи їхню чарівну будову, маг-Відступник сподівається збагнути механізми звірячого перетворення й знайти спосіб нарешті повалити архімага-ренегата з Фортеці Шадовфенг."}},faq={{q="Чому мешканці Села Пайрвуд уночі перетворюються на воргенів?",a="Архімаг Аруґал наклав на Село Пайрвуд спотворені чари. Удень його закляття підтримують ілюзію людської подоби чи приспаний людський стан, а з настанням ночі селяни перетворюються на воргенів Мунрейджів, підвладних йому.",al={"пайрвуд день ніч","прокляття пайрвуда","чому людина а потім вовк"}},{q="Що таке Кайдани Пайрвуда?",a="Це зачаровані пута, які носять прокляті мешканці Села Пайрвуд. Аруґал використовував їх у своїх чарах над селом, а Далар Донвівер вивчає прокляття за їхньою залишковою енергією.",al={"кайдани пайрвуда","кайдани аруґала"}},{q="Хто такий Далар Донвівер?",a="Далар Донвівер — маг із Відступників у Гробниці в Срібноліссі. Він очолює магічне розслідування Відступників щодо воргенів, яких закликав Архімаг Аруґал.",al={"далар донвівер","хто видавець гробниці"}},{q="Чи зцілює це завдання Село Пайрвуд?",a="Ні. Здобуті кайдани дають Даларові Донвіверу змогу зрозуміти Аруґалову магію, але прокляття й далі тримає Пайрвуд у нескінченних муках.",al={"чи можна вилікувати пайрвуд","чи зцілять людей пайрвуда"}},{q="Як Аруґал керує селянами?",a="Безрозсудними чарами й зачарованими кайданами Аруґал підкорив селян своїй волі, змусивши їх набути звірячої подоби й стерегти підступи до його володінь у Фортеці Шадовфенг.",al={"аруґал і пайрвуд","як аруґал керує ними"}},{q="Що буде після ланцюжка «Безумство Аруґала»?",a="Це доручення — останній розділ ланцюжка «Безумство Аруґала». Зібрані знання дають Відступникам змогу повністю оцінити загрозу Фортеці Шадовфенг і спланувати падіння Аруґала.",al={"після безумства аруґала","фінал безумства аруґала"}}},fp="14,342,26.434.0,23.448.1,64.222.0,31.198.0,24.175.0,48.176.1,38.183.0,61.185.1"}
P.entries["quest:990"] = {n="Похід до Ашенвалю",s="«Похід до Ашенвалю» — завдання-мандрівка для Альянсу, що посилає досвідчених шукачів пригод на південь із Темного Узбережжя в первісні ліси Ашенвалю. Вартова Селарін, що прибула до Обердайна по допомогу, посилає мандрівників доповісти Рейн Вульфраннер у містечку Астранаар, де вартові борються з порчею, що ширшає.",h="«Похід до Ашенвалю» — завдання-мандрівка для Альянсу, що посилає досвідчених шукачів пригод на південь із...",kw={"похід до ашенвалю","вартова селарін","обердайн","рейн вульфраннер","астранаар","завдання"},ang={["faction:Alliance"]="Як звитяжець Альянсу, відгукнувшись на заклик Астранаару, ви зміцнюєте зв'язки з нічними ельфами й головну опору свого союзу на півночі Калімдору.",["race:NightElf"]="Для нічних ельфів ця мандрівка — повернення в священне серце Калімдору: ви відгукуєтеся на заклик своїх сестер захистити прадавні святі землі від протиприродної гнилі."},sec={{t="Прощання з узбережжям",b="Відгукнувшись на заклик Вартової Селарін в Обердайні, мандрівники залишають позаду похмурі сірі пляжі й затінені руїни узбережжя. Вартова впізнає вправних бійців і розвідників, здатних постояти за себе, і посилає їх просто в серце лісових земель нічних ельфів. Із місцевими загрозами Темного Узбережжя покінчено, тож увага звертається до значно більших небезпек, що насуваються з півдня."},{t="Дорога до Астранаару",b="Шлях на південь пролягає прадавньою дорогою нічних ельфів, що в'ється крізь густі прадавні крони Ашенвалю. Рейн Вульфраннер, ватажок вартових в Астранаарі, терміново кличе підкріплення. Демонічна скверна, шалені звірі й вторгнення чужинців на родові землі — вартові в Астранаарі розпорошені до краю й потребують допомоги ззовні, щоб утримати священний ліс."}},faq={{q="Хто посилає вас у цей похід?",a="Вартова Селарін — нічна ельфійка, яку Рейн Вульфраннер послала до Обердайна по допомогу, — скеровує вас на південь, до Астранаару.",al={"видавець","хто починає похід до ашенвалю","селарін"}},{q="Хто така Рейн Вульфраннер?",a="Рейн Вульфраннер — очільниця Вартових в Астранаарі, що організовує оборону Ашенвалю й спрямовує зусилля, щоб зупинити скверну, яка вражає ліс.",al={"рейн","вульфраннер","керівниця астранаара"}},{q="Чому шукачів пригод посилають до Ашенвалю?",a="Прадавні ліси Ашенвалю піддаються скверні, що поширюється, і дедалі більшим загрозам ззовні. Місцеві Вартові нічних ельфів не дають ради й нагально потребують вправних союзників, які допомогли б мешканцям і захисникам Астранаару.",al={"чому ашенваль","що відбувається в ашенвалі","осквернення ашенвалю"}},{q="Чи безпечна дорога між Темним Узбережжям і Ашенвалем?",a="Вартова Селарін окремо радить триматися дороги. Хто зійде зі стежки в лісову гущавину, наразиться на агресивних хижаків, сатирів і ворожі сили, що никають дикими прикордонними землями.",al={"безпека дороги","чи безпечна дорога до ашенвалю"}},{q="Що робити, коли я дістануся Астранаару?",a="Коли ви доповісте Рейн Вульфраннер, вона порадить поговорити з іншими мешканцями й захисниками Астранаару, адже багатьом із них потрібна негайна допомога з місцевими бідами.",al={"що робити в астранаарі","прибуття до астранаара"}},{q="Для якого рівня шукачів пригод це призначено?",a="Зазвичай ця подорож знаменує завершення пригод на Темному Узбережжі десь на 19 рівні й переводить шукачів пригод середнього рівня на ширше й запекліше спірне прикордоння Ашенвалю.",al={"який рівень","вимога рівня"}}},fp="17,339,17.409.0,21.425.0,27.126.0,24.193.0,44.232.0,49.209.0,44.192.0,46.171.0"}
P.entries["quest:991"] = {n="Очищення Рейн",s="«Очищення Рейн» починається, коли Рейн Вульфраннер просить шукача пригод розшукати її зниклого друга Тероніса. Шукаючи спосіб зупинити шалену агресію фурболгів по всьому Ашенвалю, Тероніс вирушив до Озера Фалатім, щоб здобути чарівний самоцвіт.",h="«Очищення Рейн» починається, коли Рейн Вульфраннер просить шукача пригод розшукати її зниклого друга Тероніса.",kw={"очищення рейн","рейн вульфраннер","тероніс","озеро фалатім","мурлоки","завдання"},ang={["faction:Alliance"]="Новобранці Альянсу, що прибувають до Астранаару, швидко дізнаються: священні гаї Ашенвалю в облозі ворожих диких звірів, фурболгів і загарбників-мурлоків.",["race:NightElf"]="Зникнення Тероніса — ще один гіркий удар для нічних ельфів, чиї сили й так розпорошені на зцілення Ашенвалю й захист святилищ від порчі."},sec={{t="Тривога за друга",b="Рейн Вульфраннер служить разом із вартовими в Астранаарі, боронячи Ашенваль від дедалі більших загроз. Одним із її найближчих товаришів був Тероніс, який сам узявся знайти могутній захист від дедалі жорстокіших племен фурболгів. Коли минали дні, а він не повертався, Рейн дуже стривожилася: вона не могла покинути свій пост, але боялася найгіршого."},{t="Пошуки жезла",b="Тероніс ішов за чутками про могутній жезл, викуваний покійним лихим чарівником, вірячи, що його магія може вгамувати лють фурболгів. Щоб відновити артефакт, йому був потрібен зачарований самоцвіт, схований в ельфійському святилищі на Озері Фалатім, біля гір на заході. На лихо, тихі води нещодавно захопили агресивні племена мурлоків."},{t="Трагедія на Озері Фалатім",b="Слід Тероніса до острова посеред Озера Фалатім відкриває похмуре видовище. Тероніс так і не вибрався з вод живим: його тіло лежить у святилищі, вкрите глибокими ранами від мурлоцької зброї та пазурів, — передчасний кінець його пошуків."}},faq={{q="Хто така Рейн Вульфраннер?",a="Рейн Вульфраннер — нічна ельфійка, союзниця Вартових Ашенвалю, що перебуває в Астранаарі. Вона керує обороною лісу від ворогів, що наступають.",al={"хто така рейн","рейн вульфраннер","видавець"}},{q="Хто такий Тероніс?",a="Тероніс був близьким другом Рейн Вульфраннер і шукав давніх магічних способів урятувати ліс. Вірячи, що зачарований жезл може заспокоїти зіпсованих скверною фурболгів, він сам вирушив здобувати складники для нього.",al={"хто такий тероніс","історія тероніса","зниклий друг"}},{q="Де зник Тероніс?",a="Тероніс зник біля Озера Фалатім — водойми біля підніжжя західних гір Ашенвалю, яку заполонили ворожі мурлоки.",al={"де тероніс","місце тероніса","озеро фалатім"}},{q="Навіщо Тероніс шукав самоцвіт?",a="Самоцвіт був необхідним складником, щоб наснажити магічний жезл, створений покійним лихим чарівником. Тероніс сподівався використати силу жезла, щоб зупинити напади розлючених фурболгів.",al={"який самоцвіт","навіщо самоцвіт","самоцвіт тероніса"}},{q="Що сталося з Теронісом?",a="Рейн не має від нього звісток відтоді, як він подався до Озера Фалатім. Ідучи його слідом, ви дізнаєтеся, що з ним сталося.",al={"як помер тероніс","хто вбив тероніса","убивця тероніса"}},{q="Чому фурболги нападають в Ашенвалі?",a="Фурболги Ашенвалю після Третьої війни піддалися демонічній скверні й шаленству, і колись мирні племена невпинно й жорстоко нападають на своїх давніх союзників.",al={"напади фурболгів","чому фурболги агресивні","божевілля фурболгів"}}},fp="17,245,18.364.0,21.353.0,24.268.1,24.182.0,16.210.0,29.155.0,34.185.0,25.98.1,41.194.0"}
P.entries["quest:99134"] = {n="Послух",s="Послух — завдання від Екзекутора Зиґанда в Галявинах Тірісфалю. Невдоволений вправністю місцевого гарнізону Вартових Смерті, Зиґанд наймає сторонніх шукачів пригод, щоб ті фізично покарали розледачілих вартових-нежить.",h="Послух — завдання від Екзекутора Зиґанда в Галявинах Тірісфалю.",kw={"послух","зиґанд","дисципліна","вартові смерті","спонукач екзекутора","покарання"},ang={["faction:Horde"]="Похмурі методи командирів Відступників показують сувору, безжальну дійсність життя й управління в північних володіннях Орди.",["race:Undead"]="Для Відступників військова дисципліна — питання виживання виду. Вартові, що піддаються апатії, наражають на небезпеку всю територію Галявин Тірісфалю."},sec={{t="Порядок у нежитті",b="Вартові Смерті — військовий хребет Відступників по всьому Лордерону, та свобода від залізної волі Короля-Ліча приносить власні ускладнення: апатію, втому й недбалість. Наглядачі на кшталт Екзекутора Зиґанда не терплять послаблення дисципліни, надто коли Багряний Хрестовий Похід і Погибель нишпорять кордонами Тірісфалю. Щоб тримати війська в тонусі, офіцери покладаються на тупі знаряддя й жорсткий нагляд заради бойової готовності."},{t="Реєстр Екзекутора",b="Екзекутор Зиґанд навмисно залучає до покарань незалежних виконавців, а не бійців із самого гарнізону. За допомогою Спонукача Екзекутора сторонні нагадують недбалим Вартовим Смерті, що виживання на службі Темній Леді вимагає цілковитої пильності. Ті, хто нехтує обов'язками, швидко засвоюють: нежиття не дає прихистку від наслідків."}},faq={{q="Хто дає завдання «Послух»?",a="Завдання «Послух» дає Екзекутор Зиґанд — вимогливий офіцер Відступників на Галявинах Тірісфалю, що відповідає за оборону краю й вимагає від своїх військ суворого послуху.",al={"хто дає послух","видавець послуху","завдання екзекутора зиґанда"}},{q="Чому Екзекутор Зиґанд хоче покарати Вартових Смерті?",a="Зиґанд вважає підлеглих йому Вартових Смерті нездарами, яким бракує завзяття. Безтурботність загрожує виживанню Відступників у Тірісфалі, тож він запроваджує сувору дисципліну, щоб струснути вартових і змусити їх пильнувати.",al={"чому бити вартових смерті","чому мотивувати вартових смерті","причина зиґанда"}},{q="Чому Зиґанд доручає це шукачеві пригод, а не іншому солдатові?",a="Зиґанд зауважує, що ви, чужинець, який ще не належить до Вартових Смерті, поки не встигли його розчарувати.",al={"чому я","чому зиґанд наймає сторонніх"}},{q="Що таке Спонукач Екзекутора?",a="Спонукач Екзекутора — каральне знаряддя, яке видає Екзекутор Зиґанд. Ним боляче нагадують про обов'язок Вартовим Смерті, що байдикують на постах по Галявинах Тірісфалю.",al={"спонукач екзекутора","що таке спонукач"}},{q="Що буде, якщо відмовитися виконати наказ Зиґанда?",a="Зиґанд попереджає: за вагання чи відмову ваше ім'я потрапить до його книги, і наступного разу дисциплінувати когось пошлють уже по вас.",al={"погрози зиґанда","загроза облікової книги"}},{q="Як Відступники ставляться до болю?",a="Зиґанд зараховує біль до тих небагатьох утіх, які ще лишилися йому по смерті. Його захоплення покараннями відбиває його власну сувору вдачу.",al={"чи нежить відчуває біль","біль відступників"}}},fp="10,234,26.467.0,21.367.0,31.174.0,54.215.0,61.123.0,33.183.0,42.162.0,30.139.0"}
P.entries["quest:99141"] = {n="Терпіння",s="Терпіння — завдання від Екзекутора Зиґанда в Галявинах Тірісфалю, яке вимагає суворої військової звітності заради Темної Леді. Оскільки чергові польові донесення запізнюються, Зиґанд відряджає шукача пригод зібрати звіти від сусідніх Вартових Смерті та одного незвичайного вартового. Доручення підкреслює сувору, безкомпромісну дисципліну, яку насаджують по всіх володіннях Відступників.",h="Терпіння — завдання від Екзекутора Зиґанда в Галявинах Тірісфалю, яке вимагає суворої військової звітності...",kw={"терпіння","зиґанд","донесення","діллінджер","крістоф","ґордо","ставок тихої води"},ang={["faction:Horde"]="Завдання дає гостям з Орди зазирнути в похмуру, суворо дисципліновану командну структуру, яку офіцери Сильвани Віндраннер насаджують по всьому Тірісфалю.",["race:Undead"]="Для щойно звільнених Відступників виконання наказів Зиґанда закріплює сувору дійсність виживання в Лордероні: цілковита відданість Темній Леді й нульова терпимість до невдач."},sec={{t="Воля Темної Леді",b="Екзекутор Зиґанд командує місцевою безпекою в Галявинах Тірісфалю і не терпить жодних послаблень пильності. Для Зиґанда служити Леді Сильвані означає ніщо інше, як цілковиту ефективність. Коли чергові польові донесення не надходять на його пост вчасно, він бачить у цьому неприпустиме порушення обов'язку, а не дрібну затримку. Замість покинути пост і розбиратися самому, він посилає новоприбулих агентів Відступників приструнити недбалих підлеглих і пересвідчитися, що кордони в безпеці."},{t="Вартові галявин",b="Донесення стосуються вартових на ключових спостережних пунктах довкола Брілла. Вартовий Смерті Діллінджер пильнує цвинтар на заході, де часто ворушаться здичавіла нежить і недобитки Погибелі. На сході Вартовий Смерті Крістоф наглядає за заставою, що стереже підступи до Столиці — колишнього стольного міста — і східні дороги. Найнезвичайніший серед них — Ґордо, здоровенна гидота, що тиняється біля Ставка Тихої Води: з його простим розумом військове діловодство — вельми сумнівне сподівання."}},faq={{q="Хто такий Екзекутор Зиґанд?",a="Екзекутор Зиґанд — високопоставлений офіцер Відступників, що підтримує лад і оборону довкола Брілла на Галявинах Тірісфалю. Він звітує безпосередньо командуванню, яке служить Леді Сильвані, і вимагає бездоганного виконання від усіх підлеглих.",al={"зиґанд","хто такий зиґанд","роль екзекутора зиґанда"}},{q="Чому Зиґанд посилає шукача пригод збирати донесення?",a="Кілька польових вартових не надіслали вчасно своїх донесень. Не маючи терпіння до затримок і не бажаючи покидати свій пост, Зиґанд посилає щойно випробуваних Відступників збирати прострочені донесення по околицях.",al={"чому терпіння","чому збирати донесення"}},{q="Хто такий Ґордо і чому в нього донесення?",a="Ґордо — гидота, що блукає на заході біля Ставка Тихої Води. Зиґанд чекав від нього донесення про стан справ, як і від будь-якого польового вартового, але, отримавши його, Екзекутор швидко розуміє, що чекати письмових відомостей від гидоти було ганебним недоглядом.",al={"ґордо","чому в потвори донесення","хто такий ґордо"}},{q="Де Вартовий Смерті Діллінджер?",a="Вартовий Смерті Діллінджер стоїть трохи на захід від Брілла, біля місцевого цвинтаря, — він пильнує рештки Погибелі й щойно піднятих мерців.",al={"місце діллінджера","знайти діллінджера","де діллінджер"}},{q="Де стоїть Вартовий Смерті Крістоф?",a="Вартовий Смерті Крістоф — на заїжджому дворі біля дороги на схід від Брілла: він стереже підступи від непроханих гостей і стежить за рухом на дорозі.",al={"місце крістофа","знайти крістофа","де крістоф"}},{q="Що станеться, коли здати донесення Ґордо?",a="Екзекутор Зиґанд визнає, що чекати від гидоти зв'язного письмового донесення було дурною помилкою. Він мовчки змиряється з наслідками й просить, щоб цей ганебний недогляд лишився суворо між вами двома.",al={"результат донесення ґордо","ґордо пише"}}},fp="8,361,30.486.0,23.490.0,23.260.0,54.244.0,43.288.1,38.153.0,38.157.0,46.224.1"}
P.entries["quest:99142"] = {n="Могильне зілля",s="Могильне зілля — алхімічне завдання від Молодшого Аптекаря Голланда в Галявинах Тірісфалю. Голланд видозмінював дике Зілля Приречення і пересаджував його на проклятому Хуторі Балнірів, вирощуючи сильний новий зразок, що несподівано приваблює місцеву Погибель.",h="Могильне зілля — алхімічне завдання від Молодшого Аптекаря Голланда в Галявинах Тірісфалю.",kw={"могильне зілля","гробнична трава","голланд","хутір балнірів","зілля приречення","алхімія"},ang={["profession:Herbalism"]="Гробнична Трава показує, як штучне алхімічне втручання може докорінно змінити властивості й поведінку спустошених трав на кшталт Зілля Приречення.",["race:Undead"]="Дослідження Молодшого Аптекаря Голланда показують невпинне прагнення аптекарів Відступників перетворювати спустошену флору Тірісфалю на алхімічні знаряддя на замовлення."},sec={{t="Вирощування Голланда",b="Молодший Аптекар Голланд не задовольняється простим збиранням місцевих трав для Королівського Аптекарського Товариства — він плекає власні великі амбіції. Зібравши Зілля Приречення й піддавши його незначним алхімічним змінам, він пересадив ці пагони в землю Хутора Балнірів, щоб вивести вдосконалений зразок, який охрестив Гробничною Травою. Голланд бачить у цій гібридній рослині осердя своєї праці й провісника власної долі."},{t="Небажана принада",b="Голланд розраховував на алхімічну силу, та пересадження Гробничної Трави на Хутір Балнірів дало непередбачений побічний ефект. Блукаючі недобитки Погибелі, що кишать на спустошених полях, виявили до буйної рослини моторошний, нездоланний потяг. Голланд покладається на перехожих мандрівників: ті мають пробитися крізь нежить, що насідає, і зібрати дозрілий урожай, щоб він міг продовжити експерименти."}},faq={{q="Що таке могильне зілля?",a="Могильне зілля — алхімічно змінений різновид Зілля Приречення, який вирощує Молодший Аптекар Голланд. Він бере місцеве Зілля Приречення, змінює його хімічними реагентами й висаджує в отруєний ґрунт Хутора Балнірів.",al={"що таке могильне зілля","переказ про могильне зілля","рослина могильне зілля"}},{q="Хто такий Молодший Аптекар Голланд?",a="Голланд — член Королівського Аптекарського Товариства, що працює на Галявинах Тірісфалю. Честолюбний і часто доведений до розпачу помічниками на кшталт гидоти Ґордо, Голланд проводить власні садівничі й алхімічні досліди, щоб піднятися в чині.",al={"хто такий голланд","молодший аптекар голланд","аптекар голланд"}},{q="Де вирощують могильне зілля?",a="Голланд садить свої змінені рослини на Хуторі Балнірів — покинутому господарстві на сході Галявин Тірісфалю, що занепало й спустошене пошестю.",al={"де могильне зілля","місце могильного зілля","бур'ян на фермі балніра"}},{q="Чому могильне зілля приваблює Погибель?",a="Голланд помітив, що безмозку Погибель, яка блукає Хутором Балнірів, ніби інстинктивно тягне до зміненої рослини, хоча й не знає чому; йому це просто цікаво.",al={"чому погибель хоче зілля","погибель тягнеться до зілля","реакція погибелі"}},{q="Чим могильне зілля відрізняється від звичайного Зілля Приречення?",a="Зілля Приречення — дика рослина, що росте біля братської могили на північ від цвинтаря Брілла. Могильне зілля з'являється, коли Зілля Приречення штучно змінюють алхімією й вибірково пересаджують у ґрунт хутора під наглядом Голланда.",al={"зілля приречення проти могильного","різниця між зіллями"}},{q="Хто такий Ґордо, про якого згадує Голланд?",a="Ґордо — гидота, створена Відступниками, що блукає дорогами Галявин Тірісфалю; Голланд часто доручає йому прості завдання, що виявляються надто складними для його неповороткого розуму.",al={"хто такий ґордо","ґордо зустріч","ґордо тірисфаль"}}},fp="9,263,21.442.0,21.406.0,18.223.0,33.257.0,25.149.0,43.180.0,48.250.0,34.179.0"}
P.entries["quest:99156"] = {n="Тиловий патруль",s="Тиловий патруль — важливе оборонне доручення від Вартової Смерті Ліннеї в Галявинах Тірісфалю. Замість відбиватися від звичайних заблукалих гулів, патрульним доручають вистежити Ріптіра — гидоту, що блукає біля Долини Отруйного Павутиння, хоч ніколи не мала пройти повз Заслон.",h="Тиловий патруль — важливе оборонне доручення від Вартової Смерті Ліннеї в Галявинах Тірісфалю.",kw={"тиловий патруль","ріптір","гидота","ліннея","заслон","долина отруйного павутиння"},ang={["faction:Horde"]="Безпека східного кордону Тірісфалю гарантує, що лінії постачання Заслону й Андерсіті не підірвуть здичавілі жахіття.",["race:Undead"]="Відступники не можуть дозволити собі війну на два фронти; будь-який витвір Погибелі, що блукає за їхніми оборонними загорожами, — смертельна небезпека для їхнього королівства."},sec={{t="Пролом на кордоні",b="Заслон — єдина укріплена перепона, що відділяє Галявини Тірісфалю від жахіть, якими повняться Західні Чумні Землі. Стратегія війська Відступників тримається на суворо одному фронті. Якщо безтямна нежить прослизне в тил, лінії постачання фронту можна задушити за мить. Поодинокі духи чи гулі зрідка обходять загорожі, та звістки про гидоту, що блукає галявинами, свідчать про серйозний провал стримування."},{t="Загроза Ріптіра",b="Потвору-відступника на ім'я Ріптір бачили, як вона сунула поблизу Долини Отруйного Павутиння, за передовими редутами Заслону. Гидоти — величезні машини різанини, зшиті з трупів і темної некромантії. Вони не проходять укріплені вузькі проходи непоміченими, тож Вартову Смерті Ліннею глибоко тривожить, як саме істота перетнула периметр. Ліннея вимагає серце Ріптіра як беззаперечне підтвердження його знищення."}},faq={{q="Хто дає завдання «Тиловий патруль»?",a="Наказ про патруль дає Вартова Смерті Ліннея — Вартова Смерті з Відступників на Галявинах Тірісфалю, що звітує Екзекуторові Зиґанду.",al={"хто дає тиловий патруль","видавець тилового патруля","хто дає це завдання"}},{q="Що таке Ріптір?",a="Ріптір — гидота, що вийшла з-під контролю; її помітили на східних галявинах біля Долини Отруйного Павутиння, у тилу передових оборонних рубежів.",al={"хто такий ріптір","що таке ріптір","переказ про ріптіра"}},{q="Чому гидота біля Долини Отруйного Павутиння так тривожить?",a="Гидоти — величезні створіння, для виготовлення яких потрібні темна некромантія й тяжка праця. Непомітно прослизнути крізь сильно укріплений Заслон мало б бути неможливо, тож це свідчить про тривожний прорив або невідомий шлях у тил Відступників.",al={"чому ріптір так турбує","чим небезпечна потвора тут","прорив заслону"}},{q="Де зазвичай буває ця потвора?",a="Ріптіра бачили в лісах і на галявинах сходу Галявин Тірісфалю, поблизу Долини Отруйного Павутиння.",al={"де ріптір","місце ріптіра","де знайти потвору"}},{q="Який доказ потрібен, щоб завершити патруль?",a="Вартова Смерті Ліннея вимагає Серце Ріптіра, щоб переконатися, що велетенську потвору знищено назавжди.",al={"що принести ліннеї","предмет здачі","доказ смерті ріптіра"}},{q="Хто керує обороною Заслону?",a="У завданні не названо командира Заслону. Вартова Смерті Ліннея підпорядкована Екзекуторові Зиґанду в Бріллі, який отримує її подання про відзнаки за патрулі, що тримають Погибель на відстані.",al={"хто керує заслоном","начальник ліннеї","екзекутор зиґанд"}}},fp="17,285,24.457.0,21.441.1,39.121.0,16.124.0,53.248.0,33.117.0,44.112.0,40.189.0"}
P.entries["quest:993"] = {n="Зниклий господар",s="Зібравши шкури й тонку нитку, ви несете готовий Зачарований Плащ Місячного Скрадача в нетрі Темного Узбережжя, щоб знайти зниклого нічного ельфа Волкора. Ведені його вірним білим ведмедем Похмурим кігтем, ви мусите розшукати пораненого розвідника, перш ніж ворожі фурболги його доб'ють.",h="Зібравши шкури й тонку нитку, ви несете готовий Зачарований Плащ Місячного Скрадача в нетрі Темного...",kw={"зниклий господар","волкор","похмурий кіготь","зачарований плащ місячного скрадача","терентіс","фурболги"},ang={["class:Hunter"]="Те, як Похмурий кіготь знаходить дорогу, щоб привести допомогу Волкорові, підкреслює надзвичайний розум і відданість добре вишколених звірів Калімдору.",["faction:Alliance"]="Обердайн залежить від розвідників на кшталт Волкора, що стежать за дедалі сильнішою порчею племен фурболгів Темного Узбережжя, тож його порятунок — головна справа для застави.",["race:NightElf"]="Непохитна вірність Похмурого кігтя, що шукає допомоги для свого господаря Волкора, показує зв'язок між розвідниками нічних ельфів і їхніми звірами-супутниками."},sec={{t="Маяк у лісі",b="Коли Терентіс в Обердайні виткав Зачарований Плащ Місячного Скрадача, пошуки зниклого розвідника Волкора починаються по-справжньому. Його товариш-ведмідь, Похмурий кіготь, повернувся на дорогу на південь від поселення й чатує на будь-якого союзника, якого пошле Терентіс. Привітавшись із вірним звіром знайомим знаком, мандрівники рушають за ним із битого шляху просто до печери, де ховається Волкор."},{t="Схованка в темряві",b="Волкор знайшов притулок у печері, тяжко поранений місцевими зіпсованими фурболгами. Затиснутий у пастці й стікаючи кров'ю, він міг покладатися лише на потайність і кмітливість Похмурого кігтя, щоб його не здолали. Зачарований плащ дає йому укриття й надію, потрібні, щоб спланувати втечу, хоча через рани зворотна дорога до Обердайна для нього небезпечна."}},faq={{q="Хто такий Волкор?",a="Волкор — розвідник нічних ельфів із Темного Узбережжя, що зник, коли вирушив до ворожих таборів фурболгів. Під час сутички його тяжко поранили, і він ледве доповз до печери неподалік, а його супутник-ведмідь Похмурий кіготь пішов по допомогу.",al={"переказ про волкора","хто зниклий господар"}},{q="Як знайти схованку Волкора?",a="Похмурий кіготь чекає біля дороги на південь від Обердайна. Помахайте звірові — так він зрозуміє, що ви та підмога, яку послав Терентіс, і побіжить просто до відлюдної печери, де Волкор виходжує свої рани.",al={"де волкор","знайти печеру волкора","як іти за похмурим кігтем"}},{q="Навіщо потрібен Зачарований Плащ Місячного Скрадача?",a="Терентіс зачарував плащ, зшитий із тонких ниток і шкур місячних скрадачів, щоб той ненадовго давав сильну магічну невидимість. Його чари дають змогу безперешкодно проходити повз створіння Темного Узбережжя, поки ви шукаєте Волкора, а потім плащ віддають йому.",al={"плащ місячного скрадача","магія плаща"}},{q="Хто напав на Волкора?",a="На Волкора напали й поранили його зіпсовані скверною племена фурболгів, що никають Темним Узбережжям. Йому вдалося уникнути загибелі, але через рани він не міг сам дістатися назад до Обердайна.",al={"хто поранив волкора","чому волкор кровить"}},{q="Що буде, коли Волкора знайдено?",a="Отримавши зачарований плащ, Волкор переводить подих і просить допомогти йому вибратися з нетрів: ви можете або обережно вивести його крадькома, або прорубати шлях крізь фурболгів силою.",al={"наступне завдання волкора","після зниклого господаря"}}},fp="13,276,21.399.0,18.402.1,14.248.0,37.223.0,55.241.0,20.211.0,34.243.1"}
P.entries["quest:994"] = {n="Втеча силою",s="«Втеча силою» — завдання Альянсу на Темному Узбережжі, в якому шукач пригод допомагає Волкорові прорватися крізь навколишні загрози в прямому бою. Коли вони пробиваються крізь небезпеки нетрів до дороги й Волкор возз'єднується з вірним товаришем Похмурим кігтем, шукач пригод доповідає про його порятунок Терентісові в Обердайні.",h="«Втеча силою» — завдання Альянсу на Темному Узбережжі, в якому шукач пригод допомагає Волкорові прорватися...",kw={"втеча силою","волкор","похмурий кіготь","терентіс","вартова селарін","обердайн"},ang={["faction:Alliance"]="Допомагаючи місцевим розвідникам, ви зміцнюєте зв'язок між молодим Альянсом і нічними ельфами й доводите цінність фракції в захисті північного рубежу Калімдору.",["race:NightElf"]="Рятувати розвідників на кшталт Волкора украй важливо, щоб калдореї втримали хиткий контроль над Темним Узбережжям, де дикі звірі, порча й чужинці загрожують лісам їхніх предків."},sec={{t="Прямий шлях назовні",b="Коли застрягнеш у небезпечних нетрях Темного Узбережжя, не завжди обираєш тиху ходу. Перед лицем небезпеки нічний ельф Волкор погоджується на пряму стратегію — прорубатися крізь ворожих істот довкола до безпечного місця. Замість намагатися непомітно вислизнути, Волкор покладається на бойову майстерність, щоб прорубати прохід просто до головної дороги."},{t="Зустріч на дорозі",b="Благополучно діставшись тракту, Волкор возз'єднується з Похмурим кігтем — своїм непохитним товаришем-ведмедем, що чекав біля стежки. Убезпечивши втечу, Волкор готується до нової дороги й просить шукача пригод доповісти безпосередньо Терентісові в Обердайні. Звістка про те, що Волкор у безпеці, заспокоює провід нічних ельфів і одразу привертає увагу Вартової Селарін, вказуючи на глибші негаразди, що визрівають на півдні, в Ашенвалі."}},faq={{q="Хто такий Волкор?",a="Волкор — розвідник чи лісовик із нічних ельфів на Темному Узбережжі, що зник разом зі своїм супутником Похмурим кігтем. Коли його знаходять шукачі пригод, послані Терентісом, йому потрібна допомога, щоб вибратися від ворожих звірів і з небезпечної місцини.",al={"особа волкора","хто такий волкор","волкор темне узбережжя"}},{q="Хто такий Похмурий кіготь?",a="Похмурий кіготь — вірний супутник Волкора, ведмідь. Поки Волкор був у пастці, Похмурий кіготь лишався окремо біля дороги — саме там і було місце зустрічі після втечі Волкора.",al={"похмурий кіготь","ведмідь волкора","вихованець волкора"}},{q="Чому Терентісові важливо, щоб Волкор повернувся?",a="Терентіс керує розвідниками й місцевою обороною з Обердайна. Розшукувати загублених союзників і оцінювати загрози на узбережжі вкрай важливо, щоб нічні ельфи утримали контроль над Темним Узбережжям, де ситуація стрімко погіршується.",al={"терентіс і волкор","чому допомагати волкору","завдання терентіса"}},{q="Що буде після цього завдання?",a="Report Volcor's safe passage to Terenthis in Auberdine. The chain then leads to Trek to Ashenvale.",al={"після втечі силою","що далі","наступне завдання після волкора"}},{q="Чи є інший спосіб завершити супровід Волкора?",a="Так. Рятуючи Волкора, шукачі пригод можуть обрати підхід: прорватися з боєм у завданні «Втеча силою» або тихо провести його повз небезпеку крадькома.",al={"інший спосіб втечі","втеча крадькома","вибір волкора"}},{q="Куди веде це завдання в ширшому сюжеті?",a="Порятунок Волкора — місток між місцевими сутичками на Темному Узбережжі й ширшою обороною земель нічних ельфів: він прямо відкриває доручення в Ашенвалі.",al={"сюжет волкора","ланцюжок темного узбережжя до ашенвалю"}}},fp="20,323,16.372.0,19.463.1,14.245.0,16.175.0,46.236.0,41.98.1,52.179.0,52.188.1"}
P.entries["quest:995"] = {n="Втеча крадькома",s="«Втеча крадькома» — завдання Альянсу із супроводом на Темному Узбережжі. Знайшовши розвідника нічних ельфів Волкора, що опинився в пастці глибоко в лігві фурболгів, шукач пригод допомагає йому безпечно прослизнути повз ворожих звірів на волю, а тоді доповідає Терентісові в Обердайні.",h="«Втеча крадькома» — завдання Альянсу із супроводом на Темному Узбережжі.",kw={"втеча крадькома","волкор","терентіс","лігво фурболгів","супровід","обердайн"},ang={["class:Rogue"]="Розбійники цінують тактичне чуття Волкора — оминути закріпленого ворога, а не марнувати час і кров у безрозсудній бійці в лоб.",["faction:Alliance"]="Успішна втеча Волкора доводить проводові нічних ельфів в Обердайні, що союзникам з Альянсу, які не є калдореями, можна довіряти делікатні операції в нетрях.",["race:NightElf"]="Для нічних ельфів допомога Волкорові зміцнює важливу мережу розвідників, що стежать за неспокійними лісами Калімдору, поки порча шириться зі спотворених курганів і лігв."},sec={{t="Розвідник у пастці",b="Волкора, посланця, якого відрядили вглиб Темного Узбережжя розслідувати дедалі грізніші загрози краю, загнали в кут у печері фурболгів. У меншості й відрізаний від головних доріг, він покладається на союзника, що опинився поруч, аби організувати втечу, перш ніж ворожі фурболги збагнуть, що він вислизає."},{t="Обережна втеча",b="Замість самогубної атаки в лоб Волкор обирає обережність. Покладаючись на тіні й виважені маневри, він прослизає повз зіпсованих мешканців печери. Знаючи, що найважливіше — швидкість і тиша, Волкор щойно за входом до печери розлучається з рятівником і мчить уперед пішки, наказавши йому зустрітися в поселенні Обердайн."},{t="Донесення в Обердайні",b="Повернувшись до Обердайна, шукач пригод приносить звістку про порятунок Терентісові — провідникові нічних ельфів, що координує захист неспокійного узбережжя. Терентіс бачить у безпечному поверненні Волкора доказ того, що темряві, яка насувається на Темне Узбережжя й нетрі за ним, можна протистояти дисципліною й злагодженістю."}},faq={{q="Хто такий Волкор?",a="Волкор — розвідник нічних ельфів, що за дорученням старших заглибився в нетрі Темного Узбережжя. Він опинився в пастці у ворожій печері фурболгів, доки його не врятував шукач пригод з Альянсу.",al={"переказ про волкора","хто такий волкор","волкор темне узбережжя"}},{q="Чому Волкор, вибравшись із печери, тікає сам?",a="Волкор зауважує, що, вибравшись із тісних печерних ходів, сам рухатиметься швидше. Він велить шукачеві пригод зустрітися з ним в Обердайні, а не триматися разом на відкритих дорогах.",al={"чому волкор іде","волкор розділяється"}},{q="Хто такий Терентіс?",a="Терентіс — помітний очільник нічних ельфів в Обердайні. Він керує місцевою розвідкою й організовує відсіч скверні та ворожим мешканцям, що загрожують Темному Узбережжю.",al={"терентіс оберіжин","хто такий терентіс"}},{q="Де відбувається порятунок?",a="Порятунок починається в глибині печери фурболгів у диких спірних лісах Темного Узбережжя, далеко від безпечного Обердайна.",al={"місце печери волкора","де печера волкора"}},{q="Що буде після цього завдання?",a="Коли Волкор у безпеці, а Терентіс вислухав доповідь, гравців скеровують на наступний етап подорожі — на південь, до Ашенвалю, у завданні «Похід до Ашенвалю».",al={"що після втечі крадькома","наступне завдання після волкора"}},{q="Яка альтернатива скраданню в цьому порятунку?",a="Волкор пропонує інший підхід: замість того щоб вибиратися крадькома, шукачі пригод можуть прорватися самою силою — це окремий варіант супроводу з боєм.",al={"втеча силою","інше завдання волкора","крадькома проти сили"}}},fp="22,259,17.293.0,16.380.0,22.325.0,14.196.0,52.198.0,17.191.0,34.137.0,41.179.0,50.190.0"}
P.entries["quest:997"] = {n="Земля Деналана",s="«Земля Деналана» — доручення, що веде на південь від поселення Доланаар до тихих вод Озера Ал'Амет. Сірал Блейдліф просить мандрівників власноруч доставити затриману посилку з рідкісним збагаченим ґрунтом її колезі-ботаніку Деналану, який вивчає гілля та флору нового Світового Дерева.",h="«Земля Деналана» — доручення, що веде на південь від поселення Доланаар до тихих вод Озера Ал'Амет.",kw={"земля деналана","деналан","сірал блейдліф","ґрунт","озеро ал'амет","доланаар"},ang={["class:Druid"]="Друїди мають природну спорідненість із працею Деналана, адже стеження за ростом і рівновагою флори Тельдрассила — запорука захисту природи на новому гіллі.",["profession:Herbalism"]="Травникам припаде до душі озерний прихисток Деналана, адже його досліди зосереджені на розумінні крихкого молодого рослинного життя, властивого лише щойно вирослому Світовому Дереву.",["race:NightElf"]="Для нічних ельфів, що виходять із Тінедола, допомога Сірал і Деналанові — раннє знайомство з ширшою опікою, потрібною, щоб підтримувати Тельдрассил."},sec={{t="Кур'єр для Доланаара",b="Коли мандрівники проходять через Доланаар, прямуючи на південь до Озера Ал'Амет, Сірал Блейдліф зупиняє їх із задавненим дорученням. Її колега-дослідник Деналан замовив особливий пакунок рідкісної землі аж із Дарнасуса для своїх ботанічних досліджень. Посилка затрималася в дорозі й лише нещодавно прибула до Доланаара. Щоб багатий ґрунт не зіпсувався й не лежав без діла, Сірал шукає люб'язного кур'єра, готового віднести його лісовою стежкою до озерного табору Деналана."},{t="Вирощуючи Тельдрассил",b="Деналан тримає самотню робітню на східному березі Озера Ал'Амет, де спостерігає, як укорінюється молода екосистема Тельдрассила. Тельдрассил юний — він стрімко виріс після катаклізму на горі Гіджал, і його флора поводиться несподівано. Деналан випробовує унікальні суміші ґрунту й зразки, щоб перевірити життєвість і поведінку острівних деревляників і місцевих рослин, тож свіжа посилка рідкісної землі вкрай важлива для його дослідів."}},faq={{q="Хто такий Деналан?",a="Деналан — дослідник і травник із нічних ельфів, що отаборився на східному березі Озера Ал'Амет. Він вивчає, вирощує й випробовує неповторну рослинність Тельдрассила.",al={"переказ про деналана","хто такий деналан","деналан неігровий персонаж"}},{q="Де знайти Сірал Блейдліф?",a="Сірал Блейдліф мешкає в Доланаарі — головній заставі нічних ельфів у центрі Тельдрассила: там вона розподіляє припаси для досліджень і допомагає мандрівникам, що подорожують гілками.",al={"місце сірал блейдліф","де сірал"}},{q="Навіщо рідкісна земля?",a="У партії — особливо удобрений ґрунт зі столиці, Дарнасуса. Деналан вирощує на ньому дослідні посадки й перевіряє, як місцеві паростки Тельдрассила, зокрема деревляники, реагують на різні умови росту.",al={"навіщо деналану земля","призначення рідкісної землі"}},{q="Де Озеро Ал'Амет?",a="Озеро Ал'Амет лежить на південь від Доланаара — тиха водойма серед південного коріння Тельдрассила.",al={"місце озера ал'амет","як дістатися озера ал'амет"}},{q="Чому партія затрималася?",a="Пакунок мав дістатися з Дарнасуса й, поки добирався звивистими дорогами Тельдрассила, зазнав невідомих затримок, перш ніж нарешті прибув до розподільного пункту в Доланаарі.",al={"чому земля запізнилася","затримка посилки"}},{q="До чого веде доставка цієї землі?",a="Отримавши рідкісний ґрунт, Деналан просить посланця допомогти зібрати паростки й насіння деревляників на берегах озера — так починається глибша низка польових ботанічних досліджень.",al={"продовження землі деналана","що далі"}}},fp="15,297,22.508.0,22.469.0,15.208.0,33.178.0,32.234.0,23.118.0,26.178.0,40.181.1"}
P.entries["quest:cutting-teeth"] = {n="Проба зубів",s="Проба зубів — перше випробування для новобранців, що прибувають у Долину Випробувань у Дуротарі. Наглядач Ґорнек доручає новачкам прорідити плямистих вепрів, які блукають сусідніми кактусовими городами на червоній землі, і так перевіряє їхню базову бойову готовність. Пройти цей скромний обряд посвяти — означає довести, що майбутній воїн чи чарівник має хребет, потрібний для служби Орді.",h="Проба зубів — перше випробування для новобранців, що прибувають у Долину Випробувань у Дуротарі.",kw={"проба зубів","вепри","ґорнек","долина випробувань","новобранці","перше завдання"},ang={["faction:Horde"]="Кожен молодий герой, що ступає в Дуротар, має починати від самої землі, доводячи, що майбутнє Орди тримається на крові й поті, а не на незаслуженій славі.",["race:Orc"]="Орківська культура понад усе цінує практичне виживання й воїнську честь; навіть скромне винищення вепрів — священний перший крок у доросле життя й службу новій державі Тралла.",["race:Troll"]="Поки плем'я Темного Списа відбудовується поруч з орками-союзниками, молоді тролівські розвідники й містики теж мають довести свою самостійність серед безжальних хижаків Дуротару."},sec={{t="Міра хребта",b="Долина Випробувань не потурає мріям про велич. Хоч молоді новобранці можуть марити полюванням на велетенських звірів у Пустках чи славою на полях битв, наглядач Ґорнек починає їхню оцінку зі значно приземленіших справ. Проріджування плямистих вепрів довкола городів долини — базова перевірка: вона показує, чи вміє новобранець тримати зброю або накласти закляття, чи впорається з дикою люттю й чи має досить глузду, щоб пережити свою найпершу сутичку."},{t="Приборкання червоного пилу",b="Окрім перевірки сирих новобранців, винищення плямистих вепрів має й практичну господарську мету для поселення в червоній пустелі. Здичавілі свині блукають городами на північ і північний схід від табору, риють кактусові грядки й загрожують убогим припасам, вирощеним на суворому ґрунті Дуротару. Посилаючи претендентів їх вибити, табір тримає місцевих шкідників у шорах і водночас кує з молодих орків і тролів умілих захисників нової держави."}},faq={{q="Чому Ґорнек посилає новобранців на кабанів, а не на більших звірів?",a="Як визнає сам Ґорнек, живі новобранці для Орди куди корисніші за мертвих. У Пустках водяться могутні кодо й хижаки, але посилати проти них необстріляного новачка — це просто марна різанина. Кабани ж — надійна перевірка базових бойових навичок без зайвих втрат.",al={"чому кабани","чому вбивати кабанів","полювання ґорнека на кабанів"}},{q="Де водяться плямисті кабани?",a="Плямисті кабани риються в чагарниках і на земляних грядках на північ і північний схід від центральної галявини Долини Випробувань.",al={"місце кабанів","де кабани","знайти плямистих кабанів"}},{q="Що означає вислів «проба зубів»?",a="Цей вислів означає перший практичний досвід у ремеслі чи покликанні. Для майбутнього захисника Орди це перехід від тренувальних опудал і порожніх балачок до справжньої боротьби за виживання, де ллється кров.",al={"що значить проба зубів","значення проби зубів"}},{q="Хто дає це випробування?",a="Доручення дає Ґорнек — наглядач у серці Долини Випробувань, що оцінює й скеровує новобранців, які прибувають на вишкільні землі Дуротара.",al={"хто дає пробу зубів","видавець проби зубів","випробування ґорнека"}},{q="Чи завершує це навчання в Долині Випробувань?",a="Ні. Ґорнек попереджає, що бої з кабанами — лише розминка. Після цього доручення одразу настають небезпечніші випробування — зокрема сутички з непроханими гостями й збирання життєво важливих ресурсів долини.",al={"чи це останнє завдання","що після проби зубів"}},{q="Чим кабани заважають у долині?",a="Дикі кабани агресивно никають місцевими земляними грядками й заростями, наражаючи на небезпеку робітників і поїдаючи ті кілька витривалих рослин, як-от кактусові плоди, якими живе табір.",al={"проблема кабанів","кабани долини випробувань"}}},fp="13,382,21.488.0,19.449.0,67.301.0,36.136.0,55.225.0,23.166.0,56.205.0,46.182.0"}
P.entries["quest:galgar-s-cactus-apple-surprise"] = {n="Сюрприз із Кактусових Яблук від Ґалґара",s="Сюрприз із Кактусових Яблук від Ґалґара — просте доручення для молодих воїнів і новачків у випаленій сонцем Долині Випробувань. Шукаючи порятунку від нищівної спеки Дуротару, орк Ґалґар просить подорожніх назбирати диких кактусових яблук, щоб приготувати свої знамениті освіжні ласощі. Завдання навчає новобранців збирати харч і виживати в посушливому краї.",h="Сюрприз із Кактусових Яблук від Ґалґара — просте доручення для молодих воїнів і новачків у випаленій сонцем...",kw={"ґалґар","кактусові яблука","сюрприз","кулінарія","долина випробувань","спека"},ang={["faction:Horde"]="Кожен новобранець, що ступає в Долину Випробувань, швидко дізнається: витримати нищівне сонце Дуротару — така сама частина вишколу, як і бій.",["profession:Cooking"]="Страва Ґалґара показує винахідливість, потрібну, щоб із жорсткої колючої пустельної рослинності приготувати поживну їжу й освіжні ласощі.",["race:Orc"]="Освоєння Дуротару означало пристосуватися до посушливого краю, і прості страви з місцевих кактусів утілюють практичну здатність орків процвітати на новій землі."},sec={{t="Виживання в червоних пустках",b="Багряна земля Долини Випробувань славиться своєю безжальністю. Між виснажливими бойовими вправами й лютими сутичками з тутешніми звірами виснаження й зневоднення настають швидко. Для молодих орків і тролів Темного Списа, що роблять перші кроки як захисники Орди, навчитися жити з дарів землі не менш важливо, ніж махати сокирою. Кактуси по всій долині родять стиглі, соковиті яблука, що дають негайний перепочинок від гнітючого пустельного сонця."},{t="Делікатес долини",b="Ґалґар, що стоїть на тренувальних землях, перетворив збирання місцевих плодів на мистецтво. Його знаменитий Сюрприз із Кактусових Яблук став легендою серед мешканців долини: він остуджує швидше, ніж стрибок у річкову воду. Наймаючи завзятих новобранців збирати колючі плоди з сусідніх кактусів, Ґалґар тримає свою кухню повною й дбає, щоб жоден новий мандрівник не вирушав у Дуротар із порожнім шлунком."}},faq={{q="Хто такий Ґалґар?",a="Ґалґар — орк, що мешкає в Долині Випробувань у Дуротарі. Замість того щоб наглядати за бойовим вишколом, він готує освіжні харчі й ласощі, як-от свій знаменитий Сюрприз із Кактусових Яблук, щоб новобранці легше переносили пустельну спеку.",al={"хто такий ґалґар","переказ про ґалґара","хто дає завдання кактусових яблук"}},{q="Що таке Сюрприз із Кактусових Яблук?",a="Це популярні місцеві ласощі й освіжна закуска, яку Ґалґар готує зі свіжих кактусових яблук, зібраних з диких пустельних кактусів. Учні цінують її за те, що вона швидко рятує від спеки й угамовує спрагу під пекучим сонцем Дуротара.",al={"їжа сюрприз із кактусових яблук","що за сюрприз","рецепт ґалґара"}},{q="Де ростуть кактусові яблука?",a="Кактусові яблука ростуть невеликими гронами на землі біля підніжжя квітучих кактусів, розкиданих серед червоних скель і каньйонів Долини Випробувань.",al={"де кактусові яблука","знайти кактусові яблука","як отримати кактусові яблука"}},{q="Чому Ґалґар просить новобранців їх зібрати?",a="У Долині Випробувань страшенна спека, а Ґалґар не може покинути свій пост, щоб самому никати пустелею. Він пропонує поділитися своїми хвалебними ласощами з кожним перехожим новачком, що наважиться піти в чагарники й назбирати для нього сировини.",al={"чому збирати кактусові яблука","чому ґалґару потрібні яблука"}},{q="Чи пов'язане це завдання з ширшим сюжетом?",a="Ні. Це окреме завдання на збирання, яке має навчити новобранців добувати ресурси з довкілля, поки вони проходять перші випробування для Орди.",al={"чи є ланцюжок","продовження кактусових яблук","що після сюрпризу з яблук"}},{q="Чому в Долині Випробувань так важливо вміти збирати харчі?",a="Дуротар — суворий, немилосердний край із посушливих скель і чагарників. Ватажки Орди вважають, що вміння вижити на мізерних природних ресурсах Дуротара — необхідний вишкіл для кожного, хто хоче витримати випробування ширшого світу.",al={"чому збирати харчі","виживання в дуротарі"}}},fp="30,363,24.470.0,17.431.0,14.265.0,30.242.0,30.154.0,44.257.0,46.178.0,50.231.0"}
P.entries["quest:lazy-peons"] = {n="Ліниві пеони",s="Наглядачеві Тазз'рілу вже несила терпіти, що робітники Долини Випробувань засинають на роботі. Отримавши його обтяжений кийок, молоді новобранці обходять долину, щоб привести до тями сплячих пеонів і подбати, щоб життєво важлива деревина й далі текла до поселень Дуротару.",h="Наглядачеві Тазз'рілу вже несила терпіти, що робітники Долини Випробувань засинають на роботі.",kw={"пеони","наглядач тазз'ріл","кийок наглядача","деревина","долина випробувань","робітники"},ang={["faction:Horde"]="Кожна застава в Дуротарі покладається на деревину, яку рубають ці пеони, тож базова дисципліна робітників — справа спільного виживання.",["race:Orc"]="Для молодих орків, що дорослішають, дисциплінувати робочу силу власних родичів — ранній урок суворих реалій і практичної дисципліни, потрібних, щоб вирізьбити державу з дикої землі.",["race:Troll"]="Тролі Темного Списа, що навчаються поруч із союзниками, на власні очі бачать дивне поєднання грубої сили й управлінського відчаю, яке визначає орківське будівництво."},sec={{t="Байдики на сонці",b="Будівництво нового дому на посушливих рівнинах Дуротару вимагає величезної кількості деревини, каменю й просто важкої праці. Більша частина цього тягаря лягає на касту пеонів — орків, яким бракує воїнської вправності, та які становлять працьовитий хребет Орди. На лихо Наглядача Тазз'ріла, пекуча спека й виснажлива праця в Долині Випробувань роблять надто легкою спокусу для цих робітників ушитися під тінисте дерево на самовільну дрімоту."},{t="Швидка побудка",b="Замість дозволити продуктивності зупинитися, Наглядач Тазз'ріл вдається до доволі прямолінійного способу керування — Кийка Наглядача. Довіривши цей тупий дисциплінарний інструмент новобранцям Орди, він посилає їх долиною гамселити сплячих робітників по голові. Злякано прокинувшись, очманілі пеони поспіхом повертаються рубати дрова, нагадавши собі, що лінивим рукам немає місця у виживанні Дуротару."}},faq={{q="Чому пеони засинають?",a="Заготовляти важкі колоди під пекучим сонцем Дуротара — тяжка, виснажлива праця. Коли над душею не стоїть наглядач, пеони раз у раз нишком утікають відпочити в затінку великих дерев.",al={"чому пеони сплять","ліниві пеони","пеони сплять на роботі"}},{q="Хто такий Наглядач Тазз'ріл?",a="Наглядач Тазз'ріл — орк-наглядач у Долині Випробувань. Він керує робітниками, що заготовляють деревину й припаси для будівництва молодої Орди.",al={"тазз'ріл","хто дає лінивих пеонів"}},{q="Що таке Кийок Наглядача?",a="Це важкий шкіряний кийок, яким Наглядач Тазз'ріл приводить до тями ледачих робітників. Швидкого удару по голові якраз досить, щоб розбудити сплячого пеона й не скалічити його.",al={"кийок","палиця пеонів","знаряддя кийок"}},{q="Яку роль пеони відіграють в Орді?",a="Пеони — робітничий стан орківського суспільства. Вони кремезні, але непридатні до війни, тож працюють будівничими, рудокопами й лісорубами, живлячи воєнну машину й поселення Орди.",al={"роль орочих пеонів","що таке пеони","каста пеонів"}},{q="Де знайти сплячих пеонів?",a="Вони по всій Долині Випробувань — і на північ, і на південь від Лігва. Шукайте під широкими кронами дерев, куди робітники ховаються в затінок.",al={"місця лінивих пеонів","де ліниві пеони","знайти сплячих пеонів"}},{q="Що буде, коли пеонів розбуджено?",a="Коли ви повернете кийок Наглядачеві Тазз'рілу, він дасть вам нове доручення — дістати його загублене кайло з глибини сусідньої печери.",al={"після лінивих пеонів","що далі після лінивих пеонів","наступне завдання після пеонів"}}},fp="10,277,19.426.0,20.419.0,33.197.0,25.186.0,32.185.0,37.227.0,35.162.0,42.146.1"}
P.entries["quest:sarkoth"] = {n="Саркот",s="Високо на південному плато Долини Випробувань чаїться Саркот — надзвичайно лютий скорпід, чиє отруйне жало поставило молодого мисливця Темного Списа на поріг смерті. Лежачи пораненим під деревом, умирущий троль Гана'зуа благає перехожого воїна вбити звіра й принести його скалічений пазур, щоб урятувати його честь.",h="Високо на південному плато Долини Випробувань чаїться Саркот — надзвичайно лютий скорпід, чиє отруйне жало...",kw={"саркот","гана'зуа","скорпід","плато","долина випробувань","честь","пазур"},ang={["faction:Horde"]="У безжальному середовищі Долини Випробувань прийти на поміч полеглим товаришам — ось що визначає силу громади, яку прагне плекати Орда Тралла.",["race:Orc"]="Орки розуміють муку смерті без перемоги; помста за Гана'зуа дарує невипробуваному розвідникові воїнське вдоволення бачити свого ворога поваленим.",["race:Troll"]="Для одноплемінника з Темного Списа відгукнутися на благання Гана'зуа — урочистий обов'язок спорідненості: подбати, щоб гідний опір члена племені визнали, а не загубили в пісках Дуротару."},sec={{t="Справа честі",b="Випробування в долині мають гартувати майбутніх воїнів Орди, та сувора пустеля рідко дає другий шанс. Вистежуючи отруйну тутешню звірину долини, молодий троль-розвідник Гана'зуа натрапив на скорпіда, значно більшого й смертоноснішого за решту. Хоч він і завдав важкого удару, що скалічив одну з клешень, хвіст Саркота впився йому в груди, і він лишився стікати кров'ю в сухій червоній пилюці. Перед лицем того, що здається кінцем його життя, у нього лишилося єдине бажання: щоб звір не пережив його."},{t="Жах плато",b="Саркот нишпорить піднесеним плато над південними околицями Долини Випробувань. Позначений розтрощеною клешнею від удару Гана'зуа, страхітливий звір панує на високому хребті й кидається на кожного, кому стане зухвалості піднятися кам'янистою стежкою. Убивство створіння й повернення його пошрамованого пазура Гана'зуа дає пораненому розвідникові гірку розраду — відчутний доказ того, що його останній відчайдушний удар послабив чудовисько настільки, щоб його можна було здолати."}},faq={{q="Де знайти Саркота?",a="Саркот никає на високому плато на південь від місця, де лежить поранений Гана'зуа. Щоб дістатися до нього, шукайте земляний підйом, що в'ється схилами каньйону, — там, на хребті, і блукає великий скорпід.",al={"місце саркота","де саркот","як дістатися саркота"}},{q="Хто такий Гана'зуа?",a="Гана'зуа — молодий троль Темного Спису, що проходить мисливські випробування в Долині Випробувань. Пошматований і отруєний Саркотом, він лежить під деревом і відчайдушно шукає шукача пригод, який помстився б за нього, перш ніж рани доконають його.",al={"ґана'зуа","троль помирає долина випробувань","видавець саркота"}},{q="Навіщо Гана'зуа клешня Саркота?",a="Під час бою Гана'зуа завдав лютого удару й розтрощив Саркотові клешню, перш ніж той його вжалив. Понівечена клешня стане доказом смерті чудовиська, і Гана'зуа пишатиметься, знаючи, що його останній бій був не зовсім марним.",al={"чому клешня саркота","доказ покаліченої клешні","честь ґана'зуа"}},{q="Чи помирає Гана'зуа від отрути?",a="Він тяжко поранений і гірко переживає свої, як йому здається, невдачі, але смерть Саркота дає Гана'зуа досить надії, щоб послати вас до Лігва по лікарську допомогу, а не змиритися зі смертю під деревом.",al={"чи ґана'зуа виживе","доля ґана'зуа","чи ґана'зуа мертвий"}},{q="Чим Саркот відрізняється від інших скорпідів?",a="На відміну від звичайних скорпідів, що снують дном долини, Саркот значно більший, агресивніший і має виразні сліди недавнього бою, зокрема пошкоджену клешню.",al={"чим відрізняється саркот","чому саркот особливий","бос скорпід дуротару"}},{q="Яке доручення йде після вбивства Саркота?",a="Коли ви повернете клешню Саркота Гана'зуа, він квапить вас мерщій повернутися до Лігва, розповісти ватажкам табору про його біду й привести допомогу, поки отруйна рана не стала смертельною.",al={"завдання після саркота","наступний крок ґана'зуа","завдання назад до лігва"}}},fp="7,323,17.545.0,18.451.0,25.181.0,16.238.0,38.247.0,33.217.1,49.201.0,49.183.1"}
P.entries["quest:your-place-in-the-world"] = {n="Твоє місце у світі",s="Цей простий обряд посвяти — мить, коли молодий майбутній герой виходить уперед, щоб служити Орді. Його дає Калтунк у Долині Випробувань, посилаючи невипробуваних новобранців просто до Ґорнека, щоб розпочати базовий бойовий вишкіл. Це найперший крок до честі й виживання в суворих землях Дуротару.",h="Цей простий обряд посвяти — мить, коли молодий майбутній герой виходить уперед, щоб служити Орді.",kw={"калтунк","ґорнек","долина випробувань","новобранець","перше завдання","орда"},ang={["faction:Horde"]="Кожен молодий новобранець Орди в Дуротарі має довести, що має досить впертості боронити свою молоду державу, перш ніж узяти зброю в ім'я Вождя.",["race:Orc"]="Для орків досягти повноліття й з'явитися на службу в Долину Випробувань — глибоко культурна віха, зосереджена на особистій честі й воїнській готовності.",["race:Troll"]="Оселившись у Дуротарі поруч з орками-союзниками, тролі Темного Списа навчаються тут пліч-о-пліч із побратимами, щоб кувати єдність і спільне виживання."},sec={{t="Дорослішання в Дуротарі",b="In the arid canyon of the Valley of Trials, young orcs and darkspear trolls must prove their worth before they can ever set foot in the wider world. Life under Warchief Thrall demands strength, vigilance, and discipline. Kaltunk evaluates every eager recruit, temperately dampening their dreams of wrestling demons and dragons to redirect them toward realistic duties. New recruits begin their training here, learning humility before claiming glory."},{t="Прибуття до Ґорнека",b="За кілька кроків від Калтунка сидить Ґорнек — суворий ветеран біля табірного вогнища. Ґорнек оцінює новоприбулих скептичним оком, часто бурчачи про жалюгідний матеріал, що прибуває до табору. Та саме його обов'язок — загартувати цих бійців-початківців суворими випробуваннями, починаючи з винищення тутешніх шкідників, що загрожують припасам табору."}},faq={{q="Навіщо це завдання?",a="Це вступний обряд посвяти для молодих новобранців у Долині Випробувань. Він офіційно зараховує вас на службу Орді й знайомить із Ґорнеком, який дає вам перші справжні бойові доручення.",al={"навіщо це завдання","перше завдання орди","твоє місце у світі"}},{q="Хто такий Калтунк?",a="Калтунк — орк-наглядач біля входу в Долину Випробувань. Він вітає новобранців, що досягли повноліття, оглядає їх і скеровує до відповідних наставників і ватажків табору.",al={"роль калтунка","хто дає завдання"}},{q="Хто такий Ґорнек?",a="Ґорнек — досвідчений наставник Орди, що сидить біля вогнища в Долині Випробувань. Його завдання — випробовувати новобранців і гартувати з них справних бійців, перш ніж відпустити з каньйону.",al={"роль ґорнека","де ґорнек"}},{q="Куди веде це завдання далі?",a="Доповідь Ґорнекові веде просто до випробування «Проба зубів», де новобранців посилають у пилюку винищувати плямистих кабанів і доводити свою базову бойову вправність.",al={"що далі","після твого місця у світі"}},{q="Чому новобранців тримають у Долині Випробувань?",a="Долина Випробувань — відлюдний, захищений каньйон у Дуротарі, призначений, щоб навчати, оцінювати й відсіювати новобранців, перш ніж вони зустрінуть куди смертоносніших звірів, шипогривів і ворожих розвідників ширшого краю.",al={"чому долина випробувань","чому почати тут"}},{q="Чи різниться це завдання для орків і тролів?",a="І молоді орки, і тролі Темного Спису починають навчання разом у Долині Випробувань і отримують від Калтунка той самий вступний заклик до зброї.",al={"вступне завдання тролів","вступне завдання орків"}}},fp="23,330,24.449.0,19.377.0,34.217.0,15.200.0,14.215.0,32.168.0,46.217.0,47.152.0"}
P.entries["subzone:addle-s-stead"] = {n="Хутір Аддла",s="Хутір Аддла — покинута садиба на південному заході Сутінколісся, що тихо лежить у лісовому мороці на південь від Воронячого Пагорба. Перші господарі давно втекли, а хутір став потаємним плацдармом Братства Дефіас.",h="Хутір Аддла — покинута садиба на південному заході Сутінколісся, що тихо лежить у лісовому мороці на південь...",kw={"хутір аддла","дефіас","варіан рінн","змова","сутінколісся"},ang={["class:Rogue"]="Ця таємна застава показує, як глибоко й непомітно мережі Дефіас просочуються крізь кордони, ховаючи своїх агентів за завісою мороку Сутінколісся.",["faction:Alliance"]="Для слідчих Альянсу, що шукають зниклого короля Варіана Рінна, ця напіврозвалена хата зберігає важливі документи змовників, залишені Братством Дефіас."},sec={{t="Застава в пітьмі",b="Як і багато забутих садиб, розкиданих Сутінколіссям, Хутір Аддла занепав, коли край огорнули темрява й руїна. Проте порожнім він не лишився: його прибрало до рук Братство Дефіас. Агенти патрулюють околиці, причаюються в напіврозваленій хаті й ховають припаси в стодолі, користуючись тінистим прикриттям південно-західного Сутінколісся, щоб не потрапити на очі ні Нічній Варті, ні владі Стормвінда."},{t="Слід зникнення короля",b="Дефіас тут не просто грабують. Хутір Аддла служить таємною явкою, де Братство зберігає важливі записи. Ключові документи й переліки, що пов'язують місцевих змовників зі зникненням короля Варіана Рінна, ведуть саме до цієї ділянки землі, і непоказна занедбана ферма стає важливою ниткою в розплутуванні зради всередині Альянсу."}},faq={{q="Де Хутір Аддла?",a="Хутір Аддла — на південному заході Сутінколісся, трохи на південь від містечка Воронячий Пагорб і просто на захід від Огрського Кургану Вул'Ґол.",al={"місце хутора аддла","де хутір аддла","знайти хутір аддла"}},{q="Хто нині контролює Хутір Аддла?",a="Хутір міцно захопило Братство Дефіас — нічні бігуни, нічні леза й чародії, що використовують старий будинок і клуню як віддалену схованку.",al={"хто на хуторі аддла","мобі хутора аддла","вороги хутора аддла"}},{q="Чому ферму покинуто?",a="Як і більшість Сутінколісся, ферму покинули її господарі, коли ліс опинився під владою прокляття темряви, звірів і нежиті, що вигнало звідси простий люд.",al={"що сталося з фермою","хто був аддл","чому хутір аддла в руїнах"}},{q="Що приводить шукачів пригод з Альянсу на Хутір Аддла?",a="Шукачів пригод, що розслідують зникнення Короля Варіана Рінна, скеровують на Хутір Аддла, щоб здобути важливий Реєстр Дефіас, який пов'язує агентів-відступників із викраденням короля.",al={"чому йти на хутір аддла","завдання хутора аддла","зниклий король сутінкового лісу"}}},fp="13,242,21.445.0,35.406.1,31.134.0,37.166.0,26.177.0,50.180.1"}
P.entries["subzone:agama-gor"] = {n="Аґама'ґор",s="Аґама'ґор — велике стійбище шипогривів Щетиноспинів на півдні Пусток, трохи на північ від дороги, що веде від Табору Тауражо на захід до Малгору. Це постійна скалка в боці сусідньої застави Орди: тут кишать ворожі шипогриви, які затято тримаються за свою сувору землю.",h="Аґама'ґор — велике стійбище шипогривів Щетиноспинів на півдні Пусток, трохи на північ від дороги, що веде від...",kw={"аґама'ґор","шипогриви","щетиноспини","криваві скалки","табір тауражо","пустки"},ang={["faction:Horde"]="Безпека Табору Тауражо залежить від того, чи вдасться стримувати Щетиноспинів Аґама'ґора, тож знищення їхніх воїнів — першочергова справа для захисників Орди.",["race:Tauren"]="Розбійники Аґама'ґора, що засіли просто на шляху до Великої Брами й Малгору, становлять постійну небезпеку для шляхів постачання й паломників тауренів."},sec={{t="Твердиня Щетиноспинів",b="Аґама'ґор, що розкинувся на курних рівнинах південних Пусток, — укріплене поселення агресивного племені шипогривів Щетиноспинів. Шипогриви, що живуть небезпечно близько від Табору Тауражо, звели тут густу мережу терновиків, хиж і грубих тотемів. Їхня численність становить пряму загрозу для мандрівників між Пустками й трав'янистими пагорбами Малгору, тож розвідники й мисливці Орди ведуть проти них безупинну війну, щоб їх стримати."},{t="Криваві скалки й вигнанець",b="Окрім загальної ворожнечі між Ордою та шипогривами, Аґама'ґор — головне джерело загадкового багряного каміння, відомого як Криваві скалки. Ці геомантичні мінерали, які знаходять у Щетиноспинів із цього селища, дуже цінує Понівечозуб — вигнанець-шипогрив, якого тримають у полоні в Таборі Тауражо. Давні вірування пов'язують скалки зі священною суттю Аґамаґґана, тож шукачі пригод часто нападають на Аґама'ґор, щоб зібрати їх і виміняти на могутні племінні обереги."}},faq={{q="Що таке Аґама'ґор?",a="Аґама'ґор — велике поселення шипогривів Щетиноспинів на півдні Пусток. Воно лежить просто на північ від головної дороги, що веде на захід від Табору Тауражо до Малгору.",al={"огляд аґама'ґора","що за місце вепролюдів","табір вепролюдів біля тауражо"}},{q="Чому шипогриви Щетиноспини тут такі ворожі?",a="Шипогриви вірять, що вся земля, якої торкнувся полеглий прадавній бог-вепр Аґамаґґан, по праву належить їм. Тож Щетиноспини вважають тауренів і орків із сусіднього Табору Тауражо непроханими загарбниками, що зазіхають на їхню родову землю.",al={"чому вепролюди ворожі","ворожість вепролюдів","чому щетиноспини злі"}},{q="Що можна знайти в Аґама'ґорі?",a="Шипогриви Щетиноспини по всьому Аґама'ґору часто носять Кров'яні Скалки — кристалізовані поклади, насичені первісною силою, які можна обміняти у вигнанця-шипогрива Понівечозуба в Таборі Тауражо.",al={"що тут взяти","здобич аґама'ґора","чому вбивати щетиноспинів тут"}},{q="Хто такий Понівечозуб і як він пов'язаний із цим місцем?",a="Понівечозуб — шипогрив-вигнанець, якого тримають у клітці в Таборі Тауражо. Він плекає гірку образу на своїх родичів і охоче наділяє шукачів пригод з Орди захисними оберегами в обмін на Кров'яні Скалки, здобуті в його колишніх братів в Аґама'ґорі.",al={"зв'язок понівечозуба","хто такий понівечозуб","свиня-в'язень тауражо"}}},fp="9,311,24.479.0,22.458.0,18.164.0,49.247.0,31.194.0,56.247.0"}
P.entries["subzone:agamand-family-crypt"] = {n="Родинний Склеп Аґамандів",s="Родинний Склеп Аґамандів, схований у пагорбах одразу на північ від Млинів Аґаманда, — давнє місце спочинку однієї з найзаможніших фермерських династій Тірісфалю. Тепер його захопила Погибель під проводом Капітана Дарґола: гробниці розкрито, а сплячих предків піднято безтямними страхіттями.",h="Родинний Склеп Аґамандів, схований у пагорбах одразу на північ від Млинів Аґаманда, — давнє місце спочинку...",kw={"родинний склеп аґамандів","аґаманди","склеп","капітан дарґол","погибель","некромантія","тірісфаль"},ang={["race:Undead"]="Для Відступників захоплення склепу Капітаном Дарґолом — нестерпна присутність Погибелі в Тірісфалі, що глумиться з мертвих і загрожує північному кордону Андерсіті."},sec={{t="Неспокійні предки",b="До Третьої війни родина Аґамандів володіла великими маєтками по північних Галявинах Тірісфалю й ховала своїх предків у цьому мавзолеї на схилі пагорба. Коли Чума принесла королівству руїну, склеп потрапив у лабети Капітана Дарґола, агента Погибелі. Замість дати заможному роду спочивати з миром, Дарґол темною некромантією пробудив поховані скелети й мстиві привиди, перетворивши священне поховання на войовничий плацдарм Погибелі просто на краю земель Відступників."}},faq={{q="Де Родинний Склеп Аґамандів?",a="Склеп висічено в схилі пагорба трохи на північ від Млинів Аґаманда, на півночі Галявин Тірісфалю.",al={"місце склепу аґамандів","де склеп","як знайти склеп аґамандів"}},{q="Хто нині контролює склеп?",a="Гробницю утримує Капітан Дарґол — прислужник Погибелі, що спрямовує темну магію всередині й командує піднятими мерцями.",al={"хто в склепі аґамандів","бос склепу","капітан дарґол"}},{q="Що мене чекає в склепі?",a="Склеп повний пробуджених кістяків і неспокійних духів предків Аґамандів. Ведені темною магією, ці мстиві мерці нападають на кожного, хто ступає до гробниць.",al={"вороги склепу","що всередині склепу аґамандів","мобі склепу аґамандів"}},{q="Чи нежить у склепі — союзники Відступників?",a="Ні. Створіння всередині — раби Погибелі, підвладні Капітанові Дарґолу, тож вони ворожі і до Відступників, і до живих мандрівників.",al={"чи вони відступники","склеп аґамандів дружній","чому нападати на нежить"}}},fp="20,295,18.535.0,42.109.0,33.129.0,39.175.0,57.144.0"}
P.entries["subzone:agamand-mills"] = {n="Млини Аґаманда",s="Млини Аґаманда — розлогий комплекс ферм і вітряків на північних висотах Галявин Тірісфалю. Колись гордий маєток заможної династії Аґамандів, він занепав і став найбільшою твердинею Погибелі в краї.",h="Млини Аґаманда — розлогий комплекс ферм і вітряків на північних висотах Галявин Тірісфалю.",kw={"млини аґаманда","аґаманди","вітряки","погибель","твердиня","капітан дарґол","девлін аґаманд","тірісфаль"},ang={["race:Undead"]="Для Відступників повернення Млинів Аґаманда — не просто тактика; це особиста помста Погибелі й зведення рахунків колишніми слугами маєтку, як-от Коулменом Фартінґом."},sec={{t="Дім, розділений зсередини",b="Століття тому заможні дворяни-переселенці зі Строму заснували маєток Аґамандів і збудували розгалужену мережу млинів по північному Тірісфалю. Коли спалахнула Третя війна й Погибель прокотилася Лордероном, патріарх Ґреґор Аґаманд відмовився тікати: він укріпив садибу й переконав челядь і робітників стати на бій. Їхні припаси й кам'яні стіни могли б вистояти, та наймолодший син, Девлін Аґаманд, зрадив свою кров. Девлін перебив вартових маєтку й упустив ходячих мерців до спалень. Підкошені зсередини, решта захисників були винищені, а родина поповнила безтямні лави нежиті."},{t="Бастіон гнилі",b="Сьогодні Млини Аґаманда — найукріпленіший бастіон Погибелі в Галявинах Тірісфалю, що становить пряму загрозу державі Відступників. Гнилі вітряки крутяться над зараженими полями, де кишать примари, зомбі й кістяні страхіття. Під маєтком Капітан Дарґол командує гарнізоном із глибин Родинного Склепу Аґамандів, вправляючись у некромантії, щоб воскрешати покоління предків Аґамандів. З Брілла Магістрат Севрен і Вартові Смерті ведуть діяльну кампанію, щоб зачистити млини й викорінити присутність Погибелі, перш ніж вона рушить на Андерсіті."}},faq={{q="Чому Млини Аґаманда кишать Погибеллю?",a="Коли Погибель спустошувала Лордерон, родина Аґамандів укріпила свій маєток і спробувала вистояти проти орди нежиті. Проте наймолодший син, Девлін Аґаманд, зрадив родину й відчинив ворота Погибелі — усіх усередині вирізали й підняли з мертвих.",al={"що сталося з млинами аґаманда","чому нежить біля млинів","переказ про млини аґаманда"}},{q="Хто нині контролює млини?",a="Маєток став передовою заставою Погибелі в краї на чолі з Капітаном Дарґолом. Дарґол засів у глибині укріпленого Родинного Склепу Аґамандів, де темною магією підіймає тіла предків, роблячи з них нових солдатів.",al={"хто керує млинами аґаманда","ватажок погибелі тірисфаль","хто головний на млинах"}},{q="Чому Відступникам важливе це місце?",a="У млинах — найбільше скупчення безмозких сил Погибелі, що лишилися на Галявинах Тірісфалю. Якщо їх не зупинити, загін Капітана Дарґола загрожуватиме Бріллу й може перекрити дороги на південь, до Андерсіті.",al={"чому бріллу напасти на аґаманд","інтерес відступників до млинів аґаманда"}},{q="Хто такі Аґаманди?",a="Це був давній заможний шляхетний людський рід, що походив від переселенців зі Стромґарда, які понад тисячу років тому купили родючі землі в Тірісфалі. Нині його підняті з мертвих нащадки — серед них Ґреґор, Нісса, Турман і Девлін — блукають маєтком безмозкими рабами.",al={"хто такі аґаманди","рід аґамандів","ґреґор аґаманд"}}},fp="13,244,15.662.0,16.563.0,42.290.0,33.222.0,42.218.0,27.266.0"}
P.entries["subzone:agmond-s-end"] = {n="Кінець Аґмонда",s="Кінець Аґмонда — покинуті дворфські розкопки серед південних пагорбів Пустищ. Колись це була багатообіцяльна розвідувальна експедиція шукача Аґмонда, та табір перетворився на бойню, коли троги, що прогризали собі нори, налетіли на розкопки й убили їхнього провідника.",h="Кінець Аґмонда — покинуті дворфські розкопки серед південних пагорбів Пустищ.",kw={"кінець аґмонда","розкопки","троги","пустища","дворфи","телдурін"},ang={["race:Dwarf"]="Табір — тверезе нагадування про те, як небезпечно розкопувати прадавні землі землян без належної збройної підтримки."},sec={{t="Моторошні розкопки",b="Як і багато місць у посушливих Пустищах, Кінець Аґмонда починався як дворфська справа: розкопати прадавні реліквії й зазирнути в поховану історію землі. Ця мрія раптово обірвалася, коли з довколишніх розколин хлинули люті троги й здолали гірників. Сам Аґмонд загинув під час нападу — звідси й похмура назва місця. Нині зруйновані розкопки цілком заполонили троги Кам'яного Сховища, а потрощені ящики й покинуті інструменти лежать там, де їх кинули."},{t="Самотній сусід",b="Трохи на північ від зруйнованих розкопок стоїть самотній табір Телдуріна Загубленого. Життя по сусідству з лютими трогами навряд чи пішло на користь його розуму, та він — одна з небагатьох душ, що наважуються жити в південній пустелі поблизу приреченого місця."}},faq={{q="Хто такий Аґмонд?",a="Аґмонд був дворфом-шукачем, що очолив розкопки на півдні Пустищ. Його розвідка скінчилася катастрофою: з-під землі вилізли троги й вирізали його разом з експедицією.",al={"хто такий аґмонд","переказ про аґмонда"}},{q="Які істоти живуть у Кінці Аґмонда?",a="Зруйновані розкопки цілком заполонили ворожі троги: вони вирізали дворфів-рудокопів і привласнили розорений табір і довколишні скелі.",al={"мобі кінця аґмонда","хто тут живе"}},{q="Хто живе біля Кінця Аґмонда?",a="Неподалік, на південних пагорбах, отаборився дворф-відлюдник Телдурін Загублений, що настороже стежить за безплідним краєм.",al={"хто поруч","місце телдуріна"}},{q="Навіщо дворфи взагалі тут копали?",a="Дворфи-шукачі часто розвідують Пустища в пошуках артефактів титанів, давніх руїн і багатих рудних жил, хоча чимало таких експедицій недооцінюють лютих створінь, що чаяться під землею.",al={"навіщо дворфи копали","мета розкопок"}}},fp="12,266,21.475.0,17.267.0,15.181.0,36.158.0,28.137.0,49.204.0"}
P.entries["subzone:aku-mai-s-lair"] = {n="Лігво Аку'мая",s="Лігво Аку'мая — найглибша й найтемніша печера Чорноглибинних Печер. Ця затоплена западина за Святилищем Місячної Святині — гніздовище Аку'мая, страхітливої гідри, яку шанують як провісника Древніх Богів.",h="Лігво Аку'мая — найглибша й найтемніша печера Чорноглибинних Печер.",kw={"аку'май","гідра","чорноглибинні печери","молот присмерку","древні боги","святилище місячної святині"},ang={["class:Druid"]="Гидка мутація й протиприродна порча, що розходяться від водяного кубла Аку'мая, — тяжка пошесть для природних водойм і звірів Калімдору.",["race:NightElf"]="Для нічних ельфів бачити, як осквернений храм Елуни обернувся на брудне гніздо мерзенного породження Древніх Богів, — нестерпна наруга над священною землею Ашенвалю."},sec={{t="Серце глибин",b="Запечатане за Святилищем Місячної Святині, Лігво Аку'мая — вершина порчі, що охопила Чорноглибинні Печери. Щоб увійти до печери, треба провести темний обряд: запалити чотири жаровні обабіч статуї наги й тим пробудити вартових, що присягнули боронити поріг. За важкими двостулковими дверима лежить затоплений грот, куди не сягає сонце. Тут і культисти Молота Присмерку, і наги-загарбники збираються, щоб шанувати Аку'мая — давню триголову гідру, яку вважають первісним пожирачем і живим слугою Древніх Богів."},{t="Провісник загибелі",b="Через Аку'мая лігво стає осередком апокаліптичних задумів Молота Присмерку. Культисти шанують велетенського звіра як прикмету обіцяної доби темряви й вірять, що його поява й годування провістять падіння підземних в'язниць, де ув'язнено їхніх давніх божеств. Живлене жертвами й ревно захищене темною магією, підземне озеро — похмурий символ давнього зла, що видирається назад у Калімдор."}},faq={{q="Де Лігво Аку'мая?",a="Лігво Аку'мая — у самому кінці печерного комплексу Чорноглибинних Печер в Ашенвалі, одразу за запечатаними дверима Святилища Місячної Святині.",al={"де лігво аку'мая","як дістатися кімнати аку'мая","місце лігва аку'мая"}},{q="Як відчинити двері до Лігва Аку'мая?",a="Подвійні двері до лігва відчиняються, коли запалити чотири обрядові жаровні довкола статуї наги в Святилищі Місячної Святині й відбити хвилі створінь, закликаних їх боронити.",al={"відчинити двері аку'мая","як відімкнути лігво аку'мая","запалити вогні аку'мая"}},{q="Хто живе в цій печері?",a="У печері мешкає Аку'май — велетенська триголова гідра, отруєна прадавніми темними силами, улюбленець і втілення волі Древніх Богів.",al={"хто в лігві аку'мая","що живе в лігві","бос лігва аку'мая"}},{q="Чому культ Молота Присмерку тут поклоняється?",a="Молот Присмерку шанує Аку'мая як провісника кінця світу, чиє піднесення віщує звільнення їхніх темних володарів з підземних в'язниць, щоб зруйнувати світ.",al={"чому сектанти поклоняються аку'маю","молот присмерку лігво аку'мая","чому молот присмерку тут"}}},fp="14,237,19.545.0,17.489.0,32.158.0,44.209.0,31.154.0,50.174.0"}
P.entries["subzone:aldrassil"] = {n="Алдрассил",s="Алдрассил — велетенське дерево-оселя й поселення в серці Тінедолу на північному сході Тельдрассила. Головний прихисток і місце навчання молодих калдореїв; у його вирізьблених порожнинах знайшли притулок наставники, крамарі та місцеве керівництво.",h="Алдрассил — велетенське дерево-оселя й поселення в серці Тінедолу на північному сході Тельдрассила.",kw={"алдрассил","тінедол","тельдрассил","дерево","наставники","тенарон стормґріп"},ang={["class:Druid"]="Алдрассил показує схильність калдореїв до живої архітектури, виплеканої з живого дерева без порушення рівноваги лісу.",["race:NightElf"]="Для багатьох молодих калдореїв вирізьблені порожнини й пандуси Алдрассила — перший спогад про громадське життя й основа їхнього раннього навчання."},sec={{t="Серце Тінедолу",b="Здіймаючись над відлюдною долиною Тінедолу, Алдрассил — водночас прихисток і громадський осередок для молодих нічних ельфів, що роблять перші кроки у світі. Усередині й довкола велетенського стовбура цього прадавнього дерева в'ються пандуси, що ведуть повз наставників класів і ремісників до високого сідала, звідки Тенарон Стормґріп наглядає за безпекою гаю. Поки Світове Дерево Тельдрассил тягнеться через увесь обрій, Алдрассил дає безпечну, надійну крону, де новачки опановують своє мистецтво, перш ніж спуститися в неспокійні хащі Калімдору."}},faq={{q="Що таке Алдрассил?",a="Алдрассил — величезне порожнисте дерево й поселення в центрі Тінедолу, на північному сході Тельдрассила. Це початковий прихисток, де молоді нічні ельфи здобувають вишкіл, припаси й настанови.",al={"дерево алдрассил","що таке алдрассил","велике дерево тіньової долини"}},{q="Хто очолює поселення в Алдрассилі?",a="Тенарон Стормґріп наглядає за Тінедолом зі своєї оселі на самій верхівці Алдрассила: він організовує оборону долини й наставляє щойно пробуджених калдореїв.",al={"хто керує алдрассилом","ватажок алдрассила","місце тенарона стормґріпа"}},{q="Які послуги тут можна знайти?",a="У дереві — класові наставники для молодих нічних ельфів-воїнів, розбійників, друїдів, мисливців і жерців, а також місцеві крамарі, зброярі й дарувальники завдань, що дбають про нагальні потреби долини.",al={"наставники алдрассила","торговці алдрассила","що є в алдрассилі"}}},fp="9,254,19.549.0,18.215.0,38.156.0,32.205.0"}
P.entries["subzone:alexston-farmstead"] = {n="Хутір Алекстона",s="Хутір Алекстона — занедбана ферма у Вестфолі, що заросла бур'янами й де никають зіпсовані Вартові Урожаю. Колись тут минуло дитинство міського архітектора Стормвінда Бароса Алекстона, а тепер хутір лежить у руїні, як і більшість житниці довкола.",h="Хутір Алекстона — занедбана ферма у Вестфолі, що заросла бур'янами й де никають зіпсовані Вартові Урожаю.",kw={"хутір алекстона","барос алекстон","ферма","вартові врожаю","вестфол"},ang={["faction:Alliance"]="Ферма нагадує і про тихе працьовите коріння, з якого виросли найкращі уми Стормвінда, і про те, як Альянс досі змагається за захист власних кордонів."},sec={{t="Занепала садиба",b="Хутір Алекстона, що стоїть серед сухих рівнин Вестфолу, — ще одне похмуре свідчення занедбаності королівства. Як і сусідні садиби, ферму покинули господарі, коли краєм прокотився розбій. Нині поля заросли, а механічні Вартові Урожаю, яких лишили доглядати посіви, вийшли з-під контролю й люто нападають на кожного, хто наближається до спустілої хати."},{t="Скромне коріння",b="Попри сумний вигляд, ферма пов'язана з одним із найвідоміших громадян Стормвінда. Барос Алекстон, вправний архітектор, що допоміг спроєктувати частину відбудованої столиці, у юності гнув спину саме на цих полях. Він покинув хутір задовго до заворушень, щоб опанувати ремесло каменяра й будівничого, і лишив серед руїн пам'ятку свого раннього життя."}},faq={{q="Кому належить Хутір Алекстона?",a="Хутір названо на честь родини Бароса Алекстона, міського архітектора Стормвінда. Барос ще хлопчиком обробляв тут землю, а тоді перебрався до столиці вчитися архітектури.",al={"чия це ферма","власник алекстона","чий це хутір"}},{q="Чому ферму покинуто?",a="Як і більшість Вестфолу, хутір покинули через повсюдні заворушення й розбій Братства Дефіас. Королівство не могло дати захисту, тож фермери втекли, а господарство пішло в занепад.",al={"чому ферму покинуто","що сталося з фермою алекстона","хто зруйнував ферму"}},{q="Чому тут на людей нападають механічні опудала?",a="Механічних Стражів Врожаю збудували, щоб обробляти землю й захищати врожай від шкідників. Коли фермери втекли й ніхто їх не доглядав, їхній внутрішній механізм зламався, і вони стали лютими до будь-якої живої істоти.",al={"чому нападають опудала","вороже опудало","ворожі големи жнив"}},{q="Чи сховано щось у хаті?",a="Барос Алекстон лишив у хаті свій компас із часів юності. Мандрівників, що виконують доручення в Стормвінді, іноді просять забрати його з покинутого господарства.",al={"завдання тут","здобич на фермі","предмет бароса"}}},fp="18,240,18.427.0,12.388.0,32.191.0,26.216.0,52.246.0,46.182.0"}
P.entries["subzone:algaz-station"] = {n="Станція Алґаз",s="Станція Алґаз — дворфійська військова застава на північному заході Лох Модану, просто на південь від укріпленого перевалу Дун Алґаз. Її гарнізон горян стереже підступи до північних тунелів, охороняє мандрівників і пильнує прикордоння в бік Багнокраю.",h="Станція Алґаз — дворфійська військова застава на північному заході Лох Модану, просто на південь від...",kw={"станція алґаз","дун алґаз","горяни","перевал","лох модан","багнокрай"},ang={["faction:Alliance"]="Для шукачів пригод з Альянсу, що мандрують між Лох Моданом і північними болотами, застава — безпечний плацдарм і місце, де можна полагодити спорядження.",["race:Dwarf"]="Для дворфів-мандрівників Станція Алґаз — знайомий символ того, як далеко сягає влада Айронфорджа: королівські шляхи тут під охороною від загроз, що сповзають із гір."},sec={{t="Варта на північному перевалі",b="Станція Алґаз, що стоїть трохи на схід від Перевалу Північної Брами й на південь від Дун Алґаза, — важливий стратегічний дозорний пункт королівства Айронфорджа. Загін дворфійських горян несе тут постійну варту, тримаючи відкритою важливу дорогу між Лох Моданом і північними низинами для торгівлі й пересування військ. Зважаючи на часті загрози з довколишніх пагорбів — від мандрівних звірів до трогів, що наступають, — застава дає втомленим мандрівникам перепочинок, змогу полагодити спорядження й військову підтримку, перш ніж вони вирушать гірськими тунелями."}},faq={{q="Що таке Станція Алґаз?",a="Це військова застава Айронфорджа на північному заході Лох Модану. Вона правує за вартовий пост і перепочинок для горян, що патрулюють гірські перевали на північ до Дун Алґазу.",al={"що за місце","призначення станції алґаз","хто керує станцією алґаз"}},{q="Звідки назва станції?",a="Вона названа на честь Дун Алґазу — величезного дворфійського перевалу й системи тунелів просто на північ від станції, що з'єднує Лох Модан із Багнокраєм.",al={"чому станція так зветься","зв'язок із дун алґазом","значення назви"}},{q="Кого можна зустріти на Станції Алґаз?",a="На заставі несуть службу дворфійські горяни, зокрема Горянин Стормпайк, а також допоміжний люд на кшталт зброяра Ґотора Брумна, що лагодить мандрівникам спорядження.",al={"хто тут","неігрові персонажі станції алґаз","місце гірського стрільця сторміпайка"}}},fp="13,284,26.539.0,22.180.0,36.153.0,34.178.0"}
P.entries["subzone:altar-of-storms-burning-steppes"] = {n="Вівтар Бур (Палаючі Степи)",s="Вівтар Бур, що височіє серед зубчастих скель Палаючих Степів, — темний монумент, присвячений обрядам Скверни й демонічній силі. Зловісне місце утримують чорнокнижники клану Блекрок, що творять мерзенну магію в тіні Шпиля Блекрок. Його темна аура вабить честолюбних адептів тіні з усього Азерота.",h="Вівтар Бур, що височіє серед зубчастих скель Палаючих Степів, — темний монумент, присвячений обрядам Скверни...",kw={"вівтар бур","палаючі степи","блекрок","чорнокнижники","мор'зул","скакун жаху","скверна"},ang={["class:Warlock"]="Вівтар Бур і сусідні відлюдники, Мор'зул Бладбрінґер і Ґорзікі Вайлдайз, — ключова зупинка для чорнокнижників, які шукають матеріали й ритуали, щоб викликати грізного скакуна жаху.",["race:Orc"]="Вівтар — незручне нагадування про темне минуле Старої Орди, коли Рада Тіней Ґул'дана використовувала подібні мерзенні святилища, щоб насичувати огрів і воїнів темним чаклунством."},sec={{t="Спадщина тіні й полум'я",b="Вівтар Бур, зведений під час давніших воєн, щоб спрямовувати руйнівну магію Скверни, — похмурий пам'ятник темним угодам. У Палаючих Степах ці землі контролюють ворожі чорнокнижники клану Блекрок, що правлять окультні ритуали й звертаються до демонічних сил. Неподалік над вівтарем височіє табір відлюдника Ґорзікі Вайлдайза та його господаря Мор'зула Бладбрінґера: ці ренегати вивчають бурхливі енергії вівтаря й готують вимогливі ритуали для честолюбних чаклунів, які прагнуть більшої темної сили."}},faq={{q="Що таке Вівтар Бур?",a="Це осквернений кам'яний пам'ятник, на якому правлять темні обряди Скверни й спрямовують демонічну енергію. Збудований за часів воєн Старої Орди, він досі лишається діючим осередком темної сили, яку використовують чорнокнижники Блекрок.",al={"переказ про вівтар бур","що за вівтар","вівтар палаючих степів"}},{q="Хто нині контролює вівтар?",a="Ворожі чорнокнижники й послушники з клану орків Блекрок захопили землю довкола вівтаря: вони правлять темні церемонії й стережуть своє місце від непроханих гостей.",al={"хто біля вівтаря бур","вороги вівтаря бур","хто тут живе"}},{q="Хто такий Ґорзікі Вайлдайз?",a="Ґорзікі Вайлдайз — дивакуватий гоблін, знавець темних мистецтв, що мешкає на пагорбі над вівтарем разом зі своїм господарем Мор'зулом Бладбрінґером. Він допомагає могутнім чорнокнижникам, що прагнуть опанувати сильніші демонічні узи.",al={"ґорзікі вайлдайз","орк на пагорбі","хто такий ґорзікі"}}},fp="33,324,28.524.0,28.203.0,33.181.0,25.235.0"}
P.entries["subzone:alterac-mountains"] = {n="Гори Альтерак",s="Гори Альтерак — порізаний, засніжений хребет, що здіймається просто над пологими пасовищами Гілсбреда. Колись серце гордого людського королівства, тепер на їхніх схилах — зруйновані поселення, розбійницькі угруповання й небезпечна дика місцина, де мандрівники рідко ходять без охорони.",h="Гори Альтерак — порізаний, засніжений хребет, що здіймається просто над пологими пасовищами Гілсбреда.",kw={"гори альтерак","перенольд","синдикат","странбрад","огри","гілсбред"},ang={["class:Rogue"]="Гірські перевали кишать агентами Синдикату й найманими головорізами, тож ці пагорби — чудове випробувальне поле для виживання й контррозвідки.",["faction:Alliance"]="Для Альянсу Альтерак — гіркий пам'ятник зраді, де віроломство Перенольда мало не прирекло людство під час Другої війни."},sec={{t="Занепале королівство",b="Задовго до того, як пагорби поринули в хаос, це нагір'я було суверенним королівством Альтерак — одним із семи королівств, що постали з давнього Аратора. Ця спадщина розбилася під час Другої війни, коли король Ейден Перенольд уклав таємну угоду зі Старою Ордою, дозволивши оркам пройти крізь гори в обмін на безпеку свого королівства. Альянс Лордерона викрив зраду й скинув Перенольда, залишивши край розколотим воєнним станом і суперечками за землю."},{t="Дикі краї й розбійники",b="Після спустошень Третьої війни гори остаточно поринули в беззаконня. Позбавлені спадку вельможі королівства об'єдналися в Синдикат: вони діють із руїн Странбрада й замишляють повернути втрачену владу диверсіями й убивствами. Між лютими ограми Трощихребтами, що засіли в зруйнованій столиці, розбійними гнолами й зруйнованими магічними руїнами довкола Даларана перевали Альтерака лишаються одними з найнебезпечніших шляхів Лордерона."}},faq={{q="Яке королівство колись володіло цими горами?",a="Людське королівство Альтерак володіло цими горами впродовж поколінь після розпаду Імперії Аратор. Його столиця стояла серед найвищих вершин і панувала над дорогами між Лордероном, Далараном і Аратійським нагір'ям, доки не впала в Другій війні.",al={"хто володів альтераком","що було альтераком","королівство альтерак"}},{q="Чому Альтерак у руїнах?",a="Під час Другої війни Король Ейден Перенольд зрадив Альянс Лордерона, допомагаючи Орді. Коли зраду викрили, армії Альянсу розгромили війська Альтерака й позбавили династію корони. Без законного правителя й після спустошень Третьої війни королівство розсипалося на руїни.",al={"що сталося з альтераком","хто зруйнував альтерак","історія руїн альтерака"}},{q="Хто такий Синдикат, що ховається в пагорбах?",a="Синдикат — злочинне угруповання з колишньої шляхти Альтерака та її челяді. Під проводом Алідена Перенольда вони наймають розбійників, убивць і найманців-ренегатів, щоб розхитати край у надії силою відновити своє королівство.",al={"хто синдикат","що таке синдикат","чому розбійники в альтераці"}},{q="Які загрози чатують на засніжених вершинах?",a="Мандрівникам, що наважаться піднятися схилами, доведеться мати справу з жорстокими ограми Трощихребтами, зграями гірських гнолів, кобольдами-мародерами й розбійниками Синдикату, що патрулюють перевали.",al={"що живе в альтераці","чудовиська альтерака","загрози альтерака"}}},fp="17,274,14.492.0,22.502.0,42.266.0,24.302.0,43.246.0,36.195.0"}
P.entries["subzone:alterac-mountains-classic"] = {n="Гори Альтерак (класика)",s="Гори Альтерак — суворе, вічно захмарене нагір'я, що круто здіймається на північ від Передгір'я Гілсбреда; його зубчасті вершини вкриває вічний сніг. Колись тут було людське королівство Альтерак і вчені твердині Даларану, а нині край здебільшого лежить у руїнах, і за нього б'ються жорстокі огри, розбійники шляхетного роду та ворожі армії Долини Альтерак.",h="Гори Альтерак — суворе, вічно захмарене нагір'я, що круто здіймається на північ від Передгір'я Гілсбреда...",kw={"гори альтерак","альтерак","синдикат","странбрад","даларан","огри","долина альтерак"},ang={["class:Rogue"]="У відлюдній гірській долині на кордоні Альтераку ховається Маєток Рейвенголдт — давня оселя братства злодіїв і вбивць на чолі з Лордом Джорахом Рейвенголдтом.",["faction:Alliance"]="Альянс тримає в цих замерзлих пагорбах передову заставу під проводом Лейтенанта Гаґґердіна: тут набирають стійких бійців на підмогу дворфійській Варті Стормпайків у Долині Альтерак."},sec={{t="Зруйноване нагір'я",b="Гори Альтерак, що високо здіймаються над низинами Гілсбреда, — суворий край дощів, сосон і високогірних снігів. Колись тут трималися три великі людські сили — гірське королівство Альтерак, магократія Даларан і укріплене містечко Странбрад, — але зрада й війна звели край нанівець. Нині в зруйнованій столиці Альтераку отаборилися огри Трощихребти, Странбрад захопили розбійники, а уламки Даларану сховані під мерехтливим непрозорим фіолетовим куполом, поки вцілілі чарівники невтомно відновлюють своє зруйноване пристановище."},{t="Розбійники, звірі й війна",b="Крім місцевих гірських левів і єті, що никають обмерзлими хребтами, за нагір'я змагаються й відчайдушні смертні угруповання. Синдикат — позбавлені маєтностей людські вельможі, що подалися в розбійники, — орудує клинком і засідками зі старих садиб і таборів у передгір'ях, безупинно б'ючись з ограми, які дедалі глибше вдираються в їхні землі. А глибокі перевали до високих скель правлять за табори у кривавій війні між Експедицією Стормпайків і кланом Морозного Вовка за потаємні закутки Долини Альтерак."}},faq={{q="Що сталося з королівством Альтерак?",a="Альтерак зганьбився в Другій війні, коли його правитель, Король Ейден Перенольд, зрадив Великий Альянс, щоб допомогти Орді. Після війни королівство розформували. Без проводу його міста занепали, Странбрад перетворився на руїну, а столицю захопили брутальні огри Трощихребти.",al={"чому альтерак у руїнах","хто правив альтераком","падіння альтерака"}},{q="Хто ці розбійники Синдикату в горах?",a="Синдикат — злочинна організація, що складається переважно з колишньої шляхти Альтерака та її челяді. Утративши після зради Альтерака землі, становище й статки, вони взялися за шпигунство, вбивства й грабіж на дорогах, щоб повернути землі, які вважають своїми по праву.",al={"хто синдикат","чому розбійники в альтераці","бандити альтерака"}},{q="Що за величезний фіолетовий купол на березі озера?",a="Цей непроникний магічний купол оточує руїни Даларана. Після того як владика демонів Архімонд зрівняв місто з землею в Третій війні, уцілілі маги Кірін-Тору звели захисний бар'єр від Погибелі й Відступників, а під ним таємно відбудовують свої зруйновані вежі.",al={"фіолетова бульбашка в альтераці","що за бульбашка даларана","магічний щит даларана"}},{q="Як дістатися до Гір Альтерак?",a="Зазвичай мандрівники приходять пішки з Передгір'я Гілсбреда — північними дорогами від Таррен Мілла чи на північ від Саутшора. А сміливі плавці можуть перепливти Озеро Лордамер на південний схід від берегів Срібнолісся чи околиць Андерсіті.",al={"як дістатися альтерака","вхід до альтерака","шлях до альтерака"}}},fp="27,359,20.584.0,24.503.0,40.308.0,47.304.0,50.292.0,35.283.0"}
P.entries["subzone:alther-s-mill"] = {n="Млин Альтера",s="Млин Альтера — зруйнована лісопильня серед скелястих пагорбів на північний схід від Лейкшира в Горах Редріджу. Колись важливе джерело обробленої деревини для місцевих будівничих, покинуте обійстя стало притулком для диких стерв'ятників і хижаків. Для шукачів пригод, що прямують на схід до Кам'яної Варти, напіврозвалені будівлі — похмурий орієнтир, що позначає межу безпечних прикордонних земель.",h="Млин Альтера — зруйнована лісопильня серед скелястих пагорбів на північний схід від Лейкшира в Горах Редріджу.",kw={"млин альтера","лісопильня","гори редріджу","лейкшир","зламування замків","розбійники"},ang={["class:Rogue"]="Пройдисвіти Альянсу добре знають Млин Альтера: злодійські спілки використовують розкидані, забуті скриньки й відлюдну місцину як тихий полігон, щоб тренуватися в делікатному мистецтві зламування замків.",["faction:Alliance"]="Зруйнований млин — ще одне суворе нагадування про виснажені прикордонні гарнізони Стормвінда: цінне господарство лежить у руїні просто на виду в Лейкшира."},sec={{t="Покинутий прикордонний млин",b="Доки край не став здобиччю хижаків і орочих набігів, Млин Альтера вирував торгівлею деревиною, з якої будували Лейкшир і навколишні поселення. Тиха галявина на північний схід від Озера Незрушного давала зручний доступ до гірських лісів. Коли смута в Королівстві Стормвінд наростала, а клан Блекрок насунув із висот Кам'яної Варти, місцеві мельники покинули лісопильню, і сухі дерев'яні будівлі разом із колесом почали гнити."},{t="Тіні й мотлох",b="Без людей млин заполонили страхітливі тарантули, стерв'ятники й зухвалі грабіжники. Мандрівники, що зрізають дорогу до східних перевалів, мусять обережно обходити його затінені околиці. Останніми роками покинутим обійстям скористалися й тіньові ділки та злодії: серед розкиданих ящиків і в потаємних закутках вони відточують заборонене ремесло зламування замків і проворачують таємні оборудки подалі від очей міської варти Лейкшира."}},faq={{q="Що таке Млин Альтера?",a="Млин Альтера — зруйнована лісопильня на північний схід від Лейкшира в Горах Редріджу. Колись вона заготовляла й обробляла деревину для довколишніх поселень, доки дедалі більші небезпеки нетрів не змусили її покинути.",al={"млин альтера","що це за місце","що це за млин","що було млином альтера"}},{q="Чому млин покинуто?",a="Коли після Першої й Другої воєн оборона краю ослабла, агресивні звірі на кшталт велетенських павуків і набіги орків Блекрок зробили роботу на прикордонні надто небезпечною для простих робітників без захисту королівського війська.",al={"чому покинуто","хто покинув млин альтера","що сталося з мельниками"}},{q="Які істоти никають довкола млина?",a="Подвір'я й навколишні чагарники заполонили здебільшого велетенські гірські тарантули, стерв'ятники й хижаки, а ще — заблукані мародери, що ходять між Кам'яною Вартою й Озером Незрушним.",al={"вороги млина альтера","істоти біля млина","що тут живе"}},{q="Навіщо розбійники навідуються до Млина Альтера?",a="Відлюдне, завалене уламками подвір'я — улюблене місце випробувань для розбійників Альянсу: наставники посилають їх сюди вправлятися у зламуванні замкнених скринь і здобувати цінні злодійські свідоцтва.",al={"завдання розбійника біля млина","відмичка біля млина альтера","свідоцтво злодія"}}},fp="13,425,26.491.0,17.485.0,22.230.0,26.247.0,36.205.0,34.215.0"}
P.entries["subzone:ambermill"] = {n="Амбермілл",kw={"амбермілл","даларан","кірін-тор","лінії сили","жрець тіні аллістер","срібнолісся"},ang={["faction:Horde"]="Для агентів Відступників Амбермілл — один із небагатьох уцілілих осередків живого людського опору в Срібноліссі, що загрожує південному постачанню й ховає небезпечні таємниці магії."},sec={{t="Оплот Даларана",b="До Третьої війни Амбермілл був тихим лісорубним містечком на землях ґілнеаського вельможі Даріуса Кроулі. Коли король Ґенн Ґреймейн звів Стіну Ґреймейна, щоб відгородити своє королівство, Амбермілл разом із Селом Пайрвуд опинився по той бік стіни. У хаосі після падіння Лордерона сюди перебралися вцілілі чарівники Кірін-Тору й укріпили поселення. Тепер даларанські писарі заклять, заклиначі й учні патрулюють його будинки й стайні, використовуючи Амбермілл як передовий редут проти нежиті."},{t="Черпаючи з ліній сили",b="Інтерес Кірін-Тору до Амбермілла сягає далеко за межі простої оборони. Селище стоїть просто над приспаним вузлом енергії ліній сили. Шпигуни й скрадачі смерті Відступників, що стежать за містечком, з'ясували, що маги Даларана намагаються знову пробудити цей вузол для масштабної таємної роботи. Якщо їм це вдасться, сплеск магічної сили може загрожувати хиткій владі Відступників над Срібноліссям, тож Жрець Тіні Аллістер і скрадачі смерті влаштовують диверсії, крадіжки документів Кірін-Тору й убивства по всьому селищу."}},faq={{q="Чому чарівники Даларана захопили село в Срібноліссі?",a="Following the devastation of Dalaran during the Third War, surviving Kirin Tor forces moved into Ambermill to establish an outpost of living human resistance. Forsaken agents are investigating their activities.",al={"чому чарівники даларана тут","хто керує амбермілл","кірін тор срібнолісся"}},{q="Чи Амбермілл завжди належав Даларанові?",a="Ні. Спершу Амбермілл був селищем лісорубів королівства Ґілнеас на землях лорда Даріуса Кровлі. Він опинився відрізаним від батьківщини, коли Король Ґенн Ґреймейн замурувався за Стіною Ґреймейна.",al={"історія амбермілла","чий був амбермілл","гілнеас амбермілл"}},{q="Чому Відступники хочуть напасти на Амбермілл?",a="Ambermill is a fortified center of human opposition in Silverpine Forest. The Forsaken regard its Dalaran-supported forces and secret arcane work as a threat to their hold on the region.",al={"відступники амбермілл","чому вбивати чарівників амбермілла"}},{q="Що скрадачі смерті шукають в Амберміллі?",a="Від полонених людей скрадачі смерті Відступників дізналися, що чарівники Амбермілла зберігають під охороною документи з таємними планами й воєнними намірами Даларана, тож поселення стало головною ціллю для таємного проникнення й крадіжки.",al={"документи амбермілла","меннет каркад амбермілл"}}},fp="9,332,20.518.0,21.569.1,58.210.0,37.225.0,45.186.0,54.245.0"}
P.entries["subzone:amberstill-ranch"] = {n="Ранчо Амберстілл",s="Ранчо Амберстілл — тиха дворфська садиба при засніженій дорозі на Лох Модан, просто на північ від Кар'єру Гол'Болар. Це головне місце, де розводять і тренують славетних гірських баранів Айронфорджа. Шукачі пригод навідуються сюди, щоб придбати витривалого дворфського скакуна, навчитися верхової їзди або допомогти родині захистити худобу від місцевих хижаків.",h="Ранчо Амберстілл — тиха дворфська садиба при засніженій дорозі на Лох Модан, просто на північ від Кар'єру...",kw={"ранчо амберстілл","барани","скакуни","верхова їзда","дун мороґ","вендіго"},ang={["faction:Alliance"]="Міцні барани, вирощені Амберстіллами, дають Альянсу надійну кавалерію для холодного клімату, придатну для суворої гірської місцевості.",["race:Dwarf"]="Для дворфських шукачів пригод ранчо — предмет гордості й культурна основа: саме тут молоді герої здобувають свого першого барана породи Барак Тор'ол."},sec={{t="Домівка гірських баранів",b="Притулившись до скель Дун Мороґу, Ранчо Амберстілл славиться на весь Каз Модан найвитривалішими гірськими баранами Східних Королівств. Родина Амберстіллів порядкує в стайнях і загонах, навчаючи цих твердоногих тварин долати підступні снігові перевали й круті альпійські урвища. Окрім постачання їздових скакунів і свійської худоби, родині часто доводиться відбиватися від дикої звірини пагорбів — особливо від вендіго, яких приваблює запах свіжої отари."}},faq={{q="Чим славиться Ранчо Амберстілл?",a="Ранчо — головний осередок Альянсу з розведення гірських баранів Барак Тор'ол. Дворфи й шановані звитяжці Альянсу приходять сюди вчитися їзди верхи на баранах і купувати їздових тварин у місцевих конюхів.",al={"призначення амберстілл","навіщо йти на амберстілл","барани амберстілла"}},{q="Чи можуть тут купити їздових тварин не дворфи?",a="Баранів здавна дають лише дворфам, які розуміють їхню вперту вдачу. Представники інших рас Альянсу можуть навчитися їздити на них і купити їх, лише здобувши найвищу довіру й звеличення в Айронфорджі.",al={"купити барана не дворфу","людина купує барана","вимоги до скакуна барана"}},{q="Які загрози чатують на ранчо?",a="Отарі постійно загрожують голодні вендіго, що спускаються з крижаних круч. Найгорезвісніший хижак на навколишніх висотах — Ваґаш, велетенський вендіго, що раз у раз нападає на беззахисну худобу.",al={"небезпека амберстілла","загроза вендіґо","завдання вагаша"}},{q="Чи можна на ранчо отримати ще щось?",a="Юний Ярлін Амберстілл тримає домашніх зайців-біляків і охоче продає зайців у клітках мандрівникам, що шукають собі улюбленця в дорогу.",al={"кролик амберстілла","кролик-снігоступ вихованець","ярлін амберстілл"}}},fp="16,374,25.495.0,35.200.0,37.240.0,33.228.0,42.163.0"}
P.entries["subzone:ameth-aran"] = {n="Амет'Аран",s="Амет'Аран — давні руїни на півдні Темного Узбережжя, колись квітуче місто, де Високородні королеви Азшари віддавалися таємному чаклунству. Коли Великий Розкол зруйнував давній світ, місто впало разом із ним. Сьогодні його поламаними колонадами блукають мстиві привиди ельфів, що загинули тут.",h="Амет'Аран — давні руїни на півдні Темного Узбережжя, колись квітуче місто, де Високородні королеви Азшари...",kw={"амет'аран","високородні","атрікус нарассін","привиди","руїни","темне узбережжя"},ang={["class:Druid"]="Друїди бачать у руїнах незагойний шрам на тілі Темного Узбережжя, де змучені духи не знають спокою й порушують природну рівновагу дикого краю.",["race:NightElf"]="Для нічних ельфів Амет'Аран — похмурий пам'ятник гордині й віроломству касти Високородних, що накликала Розкол."},sec={{t="Місто чаклунів",b="До Великого Розколу Амет'Аран і його місто-сестра Башал'Аран були двома осередками влади Високородних на давньому узбережжі. Тішачись прихильністю королеви Азшари, місто славилося гамірними базарами й витонченими святилищами Елуни, хоча його знать присвятила себе нестримним таємним експериментам. Містом здалеку, з Вежі Альталакса, правив чаклун Атрікус Нарассін, і воно процвітало, доки катастрофічний обвал Колодязя Вічності не розірвав Імперію калдореїв на шматки."},{t="Зрада й вічні муки",b="Коли світ почав розриватися на частини, Атрікус Нарассін повернувся до Амет'Арану, обіцяючи переляканим підданим порятунок за допомогою могутньої захисної магії. Та замість захистити їх, чаклун вчинив жахливу зраду: під жорстоким приводом вічного збереження він викрав їхню життєву силу, щоб наповнити нею власні самоцвіти душ. Зруйнований катаклізмом і темною магією, Амет'Аран упав. Сьогодні його землями никають змучені привиди Високородних, що не можуть знайти спокою навіть через десять тисяч років після свого вбивства."}},faq={{q="Що сталося з Амет'Араном?",a="Амет'Аран уже лежав у руїнах в останні дні Імперії Калдореїв, а остаточно його знищено, коли десять тисяч років тому у Великому Розколі розлетівся Колодязь Вічності. У руїнах досі блукають духи Високородних, що тут загинули.",al={"чому амет'аран у руїнах","історія амет'арана","падіння амет'арана"}},{q="Хто ці привиди, що блукають руїнами?",a="Це неспокійні духи ельфів-Високородних, які жили в місті й практикували тайну магію до Великого Розколу. Не знаходячи спокою, вони блукають серед уламків у вічній муці й люті.",al={"привиди амет'арана","примари амет'арана","привиди високородних темного узбережжя"}},{q="Хто така Аная Донраннер?",a="Аная Донраннер жила в Амет'Арані й була коханою Сереллеана Вайтклоу. Вона загинула, коли місто впало під час Розколу, і її привид лишався прикутим до руїн, доки Сереллеан не попросив сторонньої допомоги, щоб нарешті звільнити її душу.",al={"аная донраннер","кохана сереллеана","втрачене кохання амет'арана"}},{q="Що за кам'яні таблиці в руїнах?",a="У руїнах є давні кам'яні таблиці з історією Амет'Арана й розповіддю про його падіння. Вартова Тиша Мунблейд намагалася розшифрувати їх, щоб передати історичне донесення Колу Кенарія, але ворожі привиди змусили її покластися на перехожих мандрівників.",al={"таблиці амет'арана","рунічні камені амет'арана","таблиці падіння амет'арана"}}},fp="10,301,19.524.0,28.517.1,28.254.0,39.209.0,25.251.1,46.276.0"}
P.entries["subzone:andorhal"] = {n="Андоргал",s="Колись квітуче хліборобське серце північного Лордерону, Андоргал став епіцентром загибелі королівства під час Третьої війни. Саме тут Кел'Тузад заразив зерно Чумою нежиття, накликавши жах на весь край. Нині зруйноване місто міцно тримає в залізних лещатах Погибель.",h="Колись квітуче хліборобське серце північного Лордерону, Андоргал став епіцентром загибелі королівства під час...",kw={"андоргал","кел'тузад","чума нежиття","утер","срібна длань","культ проклятих","лордерон"},ang={["class:Paladin"]="Андоргал — свята земля, освячена кров'ю Срібної Длані: саме тут Утер Світлоносець і його вірні лицарі прийняли свій трагічний останній бій проти Артаса.",["race:Undead"]="Для Відступників поля Андоргала — гірке нагадування про власне походження: саме тут Культ Проклятих спланував загибель їхнього смертного життя."},sec={{t="Епіцентр чуми",b="До Третьої війни Андоргал був заможною зерновою коморою Іствілду: сюди звозили зерно з усього Лордерону, а звідси розвозили на схід, до Гартглена й Стратгольма. Саме через цю розгалужену мережу постачання Кел'Тузад і Культ Проклятих обрали Андоргал плацдармом для свого жахливого задуму. Отруївши ящики із зерном Чумою нежиття, культ перетворив житницю королівства на рушій некрозу й заразив незліченних мешканців, перш ніж Корона бодай збагнула, що діється."},{t="Падіння Срібної Длані",b="Саме тут принц Артас Менетіл і Джайна Праудмур уперше зустрілися з Кел'Тузадом і вбили його, але смерть некроманта не стала кінцем. Коли Артас повернувся з Нортренду поборником Погибелі, він знову рушив на Андоргал, щоб забрати останки Кел'Тузада. Утер Світлоносець і рештки Срібної Длані прийняли тут відчайдушний останній бій, захищаючи прах короля Теренаса. Паладинів розгромили, Утер загинув від руки свого колишнього учня, а величне поселення перетворилося на оповитий чумною гниллю оплот Погибелі."}},faq={{q="Чому Андоргал такий важливий в історії чуми?",a="Андоргал був головним осередком розподілу зерна на півночі Лордерона. Кел'Тузад скористався цим шляхом постачання: заразив зерносховища Чумою Нежиття й відправив отруєний урожай Королівським Шляхом просто до Стратгольма й сусідніх міст.",al={"як почалася чума тут","чума зерна андоргала","чому андоргал важливий"}},{q="Хто нині контролює Андоргал?",a="Руїни Андоргала міцно тримає Погибель. Вартові-кістяки, некроманти й гулі никають обпаленими вулицями, стережучи осередок своєї першої перемоги в Західних Чумних Землях.",al={"хто править андоргалом","погибель в андоргалі","хто керує андоргалом"}},{q="Чи тут загинув Утер Світлоносець?",a="Так. Після падіння Столиці Утер і його паладини охороняли на околицях Андоргала урну з прахом Короля Теренаса. Артас напав на процесію, щоб забрати урну для решток Кел'Тузада, і зрештою на дорозі зійшовся в поєдинку зі своїм наставником і вбив його.",al={"де загинув утер","смерть утера андоргал","чи артас убив утера тут"}}},fp="8,321,25.521.0,27.529.0,53.272.0,32.206.0,36.273.0"}
P.entries["subzone:angerfang-encampment"] = {n="Табір Анґерфанґ",s="Табір Анґерфанґ — головна твердиня клану Драконячої Пащі в центрі Багнокраю. Ці орки-ренегати на чолі з Вождем Нек'рошем Скаллкрашером використовують розлогий табір як плацдарм, щоб загрожувати сусіднім дворфійським поселенням і плести задуми знищення Гавані Менетіл.",h="Табір Анґерфанґ — головна твердиня клану Драконячої Пащі в центрі Багнокраю.",kw={"табір анґерфанґ","драконяча паща","нек'рош","орки","багнокрай","гавань менетіл","фоліант кабали"},ang={["class:Warlock"]="Темні тіньові вартові в таборі носять Жезли Спрямування — артефакти, необхідні для зв'язувань, описаних у Фоліанті Кабали.",["faction:Alliance"]="Для захисників Гавані Менетіл Анґерфанґ — явна й нагальна загроза: повалити бойові прапори Нек'роша й здобути його голову вкрай важливо, щоб уберегти прибережні торгові шляхи."},sec={{t="Оплот серед драговини",b="Табір Анґерфанґ, що розкинувся в багнюці центрального Багнокраю, — укріплене серце влади Драконячої Пащі в цьому краї. На відміну від розпорошених загонів, що никають болотами, тут є добре захищені барикади, сторожові вежі й грізне військо воїнів, кісткових вартових і темних чаклунів, вірних старим звичаям. Звідси Драконяча Паща простягає свою військову силу на всі болота, нападає на мандрівників на дорогах і загрожує довколишнім дворфійським розкопкам, як-от Місцю Розкопок Велґара."},{t="Амбіції Нек'роша",b="Табором командує Вождь Нек'рош Скаллкрашер, син сумнозвісного чорнокнижника Некроса, який колись поневолив червоних драконів у Ґрім Батолі. Плекаючи глибоку ненависть до Альянсу, Нек'рош стягнув катапульти й підняв бойові прапори, готуючись до генерального штурму Гавані Менетіл. Знаючи про неминучу облогу, командири Альянсу в портовому місті посилають звитяжців у самісіньке черево Анґерфанґа — захопити прапори, розтрощити бойові машини й принести голову Нек'роша, перш ніж його наступ потопить гавань у вогні."}},faq={{q="Хто керує Табором Анґерфанґ?",a="Табором керує Вождь Нек'рош Скаллкрашер, син горезвісного чорнокнижника Драконячої Пащі Некроса Скаллкрашера. Зі свого командного намету в глибині табору Нек'рош спрямовує загони, що грабують край, і планує захопити Гавань Менетіл.",al={"хто керує анґерфанґом","бос анґерфанґа","хто головний тут","табір некроша"}},{q="Чи ці орки — союзники Орди Тралла?",a="Ні. Клан Драконячої Пащі тут не підкоряється Новій Орді Тралла. Вони тримаються темної спадщини Старої Орди й ворожі і до мандрівників Альянсу, і до мандрівників Орди. Воїни Тралла вважають їх здичавілими вигнанцями й навіть полюють на них заради матеріалів для обладунків.",al={"чи драконяча паща орда","чи анґерфанґ дружній до орди","чи анґерфанґ частина орди тралла"}},{q="Чому Альянс прагне знищити цей табір?",a="Капітан Стаутфіст і дворфійські захисники Гавані Менетіл з'ясували, що Нек'рош зібрав в Анґерфанґу катапульти й величезні сили, щоб обстріляти й захопити гавань. Альянс завдає випереджального удару, щоб зірвати облогу, перш ніж вона почнеться.",al={"чому нападати на анґерфанґ","капітан стаутфіст анґерфанґ","чому вбити некроша"}},{q="Чому чорнокнижники шукають цей табір?",a="Темні заклиначі Драконячої Пащі в Анґерфанґу носять Жезли Каналізування — знаряддя темних обрядів, яких прагнуть знавці демонічних мистецтв, щоб завершити Фоліант Кабали.",al={"завдання чорнокнижника анґерфанґ","том кабалу мокрі землі","жезл каналу анґерфанґ"}}},fp="20,284,21.531.0,19.554.1,35.252.0,45.277.0,52.249.0,41.191.0"}
P.entries["subzone:anvilmar"] = {n="Анвілмар",s="Анвілмар — укріплена дворфська застава в засніжених глибинах Долини Холодного Хребта в Дун Мороґу. Збудована довкола величезної кам'яної кузні, вона є головним тренувальним майданчиком і місцем збору молодих дворфів Бронзбірдів та гномських біженців, що починають свої пригоди.",h="Анвілмар — укріплена дворфська застава в засніжених глибинах Долини Холодного Хребта в Дун Мороґу.",kw={"анвілмар","долина холодного хребта","дун мороґ","дворфи","модімус анвілмар","морозогриви"},ang={["race:Dwarf"]="Для дворфів Анвілмар — початок шляху у великий світ; можливо, він носить ім'я давнього Верховного Короля, що колись правив єдиним дворфським королівством.",["race:Gnome"]="Гноми, що знайшли тут прихисток після падіння Гномреґану, зустрічають міцних дворфських союзників, тепле вогнище й наставників, готових допомогти їм призвичаїтися до замерзлої глушини."},sec={{t="Вогнище Холодного Хребта",b="Схований серед північних скель Долини Холодного Хребта, Анвілмар стоїть як незмінний символ дворфської стійкості. Над цим міцним кам'яним комплексом панує ревуча центральна кузня, а всередині знайшли місце наставники класів, торговці припасами та бувалі горяни, які муштрують новобранців, перш ніж відіслати їх у ширше королівство. Хоч поселення й сховане за високими заметами, воно постійно насторожі проти ворожих тролів Морозогривів та лютих диких звірів, що нишпорять замерзлою долиною."},{t="Спадок заліза й тролів",b="Своє горде ім'я поселення, найімовірніше, дістало від Верховного Короля Модімуса Анвілмара — давнього володаря, що правив усіма дворфськими кланами ще до Війни Трьох Молотів. Та його історія не обійшлася без лиха. Колись велетенський троль Морозогрив зумів прорвати оборону й спустошити анклав. Нині гарнізон пильнує, щоб вогонь у кузні не гаснув і подібне лихо більше ніколи не спіткало ці перші тренувальні угіддя."}},faq={{q="Що таке Анвілмар?",a="Анвілмар — дворфійська твердиня й поселення на півночі Долини Холодного Хребта в Дун Мороґу. Це перший збірний пункт і навчальний осередок для щойно набраних шукачів пригод із дворфів і гномів.",al={"що таке анвілмар","місце анвілмара","огляд анвілмара"}},{q="Чому він зветься Анвілмар?",a="Можливо, заставу названо на честь Верховного Короля Модімуса Анвілмара чи роду Анвілмарів. Модімус правив дворфськими кланами ще до Війни Трьох Молотів, але походження назви поселення не підтверджено.",al={"хто був анвілмар","походження назви анвілмар","значення назви"}},{q="Які загрози чатують на Анвілмар?",a="Заставі постійно загрожують місцеві тролі Морозогриви, що засіли серед скель Долини Холодного Хребта, а також небезпечні звірі на кшталт вовків і вендіго. Колись велетенський троль-Морозогрив навіть промчав поселенням, усе трощачи.",al={"вороги анвілмара","хто нападає на анвілмар","загрози анвілмара"}},{q="Чи можна тут опанувати професії?",a="В Анвілмарі гуде кузня, де можна кувати й плавити метал, але наставників ремесел тут немає. Молодим новобранцям доводиться йти глибше в Дун Мороґ — наприклад, до Хараноса чи Айронфорджа, щоб як слід опанувати ремесла.",al={"професії в анвілмарі","кузня анвілмара","ковальство анвілмар"}}},fp="8,291,23.496.0,27.451.0,17.214.0,25.199.0,32.255.0,31.257.0"}
P.entries["subzone:apothecarium"] = {n="Апотекаріум",s="Апотекаріум — південно-західний квартал Андерсіті й осідок Королівського Аптекарського Товариства. У його смердючих лабораторіях алхіміки-Відступники невтомно працюють під проводом Головного Аптекаря Фаранелла, створюючи згубні чуми, отрути й штучно виведені жахіття. Це похмуре серце біологічних досліджень Андерсіті, без якого не обійтися в боротьбі Леді Сильвани проти живих і Погибелі.",h="Апотекаріум — південно-західний квартал Андерсіті й осідок Королівського Аптекарського Товариства.",kw={"апотекаріум","андерсіті","аптекарі","фаранелл","алхімія","чума"},ang={["profession:Herbalism"]="Травники постачають огидним перегонникам Королівського Аптекарського Товариства рідкісні, уражені скверною рослини, зібрані в руїнах північних королівств.",["race:Undead"]="Для Відступників Апотекаріум — кузня їхнього виживання: тут створюють хімічну й зшиту зброю, без якої не втримати Лордерон проти переважаючих ворогів."},sec={{t="Кімната жахів",b="Апотекаріум займає південно-західну терасу підземної столиці — це лабіринт булькотливих чанів, секційних столів і їдких хімічних випарів. Під проводом Головного Аптекаря Фаранелла Королівське Аптекарське Товариство використовує цей квартал, щоб глибше пізнати смертність і тлін. Тут алхіміки й хірурги експериментують із пересадкою тканин, розтинами живих і складанням могутніх гидот. Їхня найголовніша мета, визначена Леді Сильваною Віндраннер, — створити нову чуму, здатну знищити і Погибель, і рештки людей у Лордероні."},{t="Осередок алхімії Відступників",b="Окрім великих військових задумів, квартал — головний осередок практичної алхімії й травництва Орди у Східних Королівствах. Новачки й майстри збираються біля отруйних каналів, щоб переганяти зілля, вивчати хвороби рослин і радитися з досвідченими знавцями."}},faq={{q="Навіщо Апотекаріум?",a="Апотекаріум — дослідницьке й виробниче крило Королівського Аптекарського Товариства. Тут алхіміки Відступників варять дослідні отрути, вдосконалюють Нову Чуму, збирають гидот і навчають алхімії та травництва.",al={"призначення апотекаріума","що тут відбувається","навіщо апотекаріум"}},{q="Хто очолює Апотекаріум?",a="Квартал і його дослідників очолює Головний Аптекар Фаранелл — головний учений Королівського Аптекарського Товариства, що діє з повної влади й під опікою Королеви Сильвани Віндраннер.",al={"хто очолює апотекаріум","хто керує апотекаріумом","фарранелл андерсіті"}},{q="Що намагається створити Королівське Аптекарське Товариство?",a="Головна його мета — виплекати смертоносну Нову Чуму, що має знищити і війська Погибелі Короля-Ліча, і будь-який живий людський опір, який оскаржує землі Відступників у Лордероні.",al={"дослідження чуми відступників","нова чума андерсіті","що вони варять"}},{q="Чи можуть гравці опанувати тут професії?",a="Так. Квартал — головний осередок алхіміків і травників столиці: у його переходах і залах чекають наставники вищого рівня.",al={"наставники апотекаріума","алхімія в андерсіті","наставник травництва андерсіті"}}},fp="12,415,18.603.0,26.285.0,34.255.0,27.202.0,54.199.0,35.144.0"}
P.entries["subzone:ariden-s-camp"] = {n="Табір Арідена",s="Табір Арідена — покинуте стійбище трохи на північ від стежки, що в'ється Перевалом Мертвого Вітру. Він занепадає в тіні Каражану — моторошна тиха дивина серед пустельних вітрів каньйону. Мандрівники між Сутінколіссям і Болотом Скорботи часто минають його з тривогою, не знаючи про проклятого крамаря, що колись поставив тут свій намет.",h="Табір Арідена — покинуте стійбище трохи на північ від стежки, що в'ється Перевалом Мертвого Вітру.",kw={"табір арідена","перевал мертвого вітру","каражан","аріден","шахрай","медів"},ang={["class:Mage"]="Для знавців таємної магії зруйнований табір — тривожне нагадування про гординю, що оточує Каражан: шарлатани, які зазіхають на спадщину Медіва, рідко виходять сухими з води.",["class:Rogue"]="Шахрай, що відкрив крамничку з підробленими реліквіями під найжахливішим шпилем Східних Королівств, — або надзвичайно честолюбний, або неймовірно нерозважливий."},sec={{t="Мовчазне стійбище",b="Ця занедбана стоянка, притулена до скель на північ від дороги ущелиною, що сполучає Сутінколісся з Болотом Скорботи, виглядає як звичайний привал для мандрівців, давно покинутий живими. Та в гнітючому мороці Перевалу Мертвого Вітру ніщо не лишається не зачепленим темним чаклунством. Табір належав крамареві на ім'я Аріден, який нахабно намагався збувати підроблені магічні дрібнички й дивовижі, нібито винесені з вежі Медіва. Хай яке багатство він шукав поблизу Каражану, його поглинули жахи, що досі витають над перевалом, — лишилися тільки вивітрене полотно, холодний попіл і невирішена таємниця."},{t="Безумство крамаря",b="Аріден був не просто невдахою-волоцюгою, а шахраєм, чий обман обернувся жахливою бідою поблизу оселі Стража. Його зухвале бажання нажитися на зловісній славі Каражану накликало похмуру долю на нього й на його спільників і прикувало його до тієї самої долини, яку він хотів використати. Рештки його притулку стоять неторкані — буденний надгробок на місці, де людська жадібність зіткнулася із силами, що далеко виходять за межі розуміння смертних."}},faq={{q="Де Табір Арідена?",a="Табір Арідена — на Перевалі Мертвого Вітру, трохи на північ від головної дороги, що з'єднує Сутінколісся на заході з Болотом Скорботи на сході, неподалік Каражана.",al={"місце табору арідена","де табір арідена","табір на перевалі мертвого вітру"}},{q="Чи є в таборі нині якісь загрози?",a="На самій галявині табору тихо й моторошно спокійно, але Перевалом Мертвого Вітру никають смертоносні огри Мертвого Вітру, примарні видіння й мерзенні крилаті звірі, що гніздяться біля Каражана.",al={"чи табір арідена небезпечний","мобі табору арідена"}}},fp="13,357,19.593.0,19.436.1,31.171.0,51.201.0"}
P.entries["subzone:astranaar"] = {n="Астранаар",s="Астранаар — головне поселення нічних ельфів у центральному Ашенвалі, збудоване на острові посеред спокійного озера, яке перетинає давня лісова дорога. Це серце діяльності Альянсу в краї: тут мандрівники знаходять надійний притулок від ворожих фурболгів, сатирів та Орди.",h="Астранаар — головне поселення нічних ельфів у центральному Ашенвалі, збудоване на острові посеред спокійного...",kw={"астранаар","ашенваль","нічні ельфи","озеро","валстанн стаґгелм","фурболги"},ang={["faction:Alliance"]="Астранаар — командний пункт Альянсу й головний вузол постачання для походів спірними нетрями Ашенвалю.",["race:NightElf"]="Для калдореїв Астранаар — головний оплот їхньої прадавньої батьківщини в серці Калімдору: він береже священні гаї, а поруч спочиває полеглий герой Валстанн Стаґгелм."},sec={{t="Серце лісу",b="Астранаар, що стоїть на острові посеред лісового озера, — найбільше поселення нічних ельфів в Ашенвалі. З берегом його з'єднують дерев'яні кладки над водою, а в місті живуть вартові, жерці й ремісники, які пильнують ліси. Окрім звичних вигод — корчми, крамарів і вправного шкірника, — на його високих помостах є приборкувач гіпогрифів, з яким можна полетіти до далеких застав Калімдору."},{t="Оплот в облозі",b="Попри спокійні води й сяйливі ліхтарі, Астранаар живе в постійній готовності. Місцеві ватажки на кшталт Рейн Вульфраннер організовують патрулі й оборону від осквернених фурболгів Будякохутрих, що підступають з півночі: тут бояться, що ті наважаться напасти просто на поселення. Місто береже й тиху давню скорботу: за озером, на кладовищі, спочиває Валстанн Стаґгелм, що поліг тисячу років тому у Війні Мінливих Пісків."}},faq={{q="Які послуги є в Астранаарі?",a="Астранаар пропонує мандрівникам Альянсу все необхідне: корчму, крамарів із загальними товарами, наставника-майстра шкірництва й приборкувача летунів, що сполучає з ключовими заставами Ашенвалю й Калімдору.",al={"послуги астранаара","що є в астранаарі","політний майстер астранаара"}},{q="Хто похований на цвинтарі за озером?",a="На цвинтарі біля озера — гробниця Валстанна Стаґгелма, сина Архідруїда Фандрала Стаґгелма, що загинув у давній Війні Рухомих Пісків проти кіраджі в Силітусі.",al={"могила астранаара","могила вальстанна стаґгелма","хто тут похований"}},{q="Чому Вартових в Астранаарі непокоять місцеві фурболги?",a="Фурболги Будякохутрі на півночі потрапили під темний, псувальний вплив. Вартова Рейн Вульфраннер боїться, що, якщо їх не зупинити, дедалі більша агресія підштовхне їх відкрито напасти на сам Астранаар.",al={"чому фурболги непокоять вартових","загроза будякохутрих","завдання рейн вульфраннер"}},{q="Чи можуть гравці Орди безпечно відвідати Астранаар?",a="Ні. Астранаар — сильно укріплена твердиня Альянсу, яку охороняють озброєні Вартові нічних ельфів, що нападають на членів Орди, щойно їх побачать.",al={"чи астранаар дружній до орди","орда в астранаарі"}}},fp="9,315,19.477.0,21.497.0,41.223.0,47.190.0,68.231.0,41.133.0"}
P.entries["subzone:auberdine"] = {n="Обердайн",s="Обердайн — приморське портове містечко нічних ельфів на похмурих берегах Темного Узбережжя, головна морська брама Альянсу до північного Калімдору. Сховане під хмарним небом і порослими соснами кручами, воно з'єднує острівну домівку на Тельдрассилі зі Східними Королівствами й слугує осередком влади серед дикого краю, що наступає.",h="Обердайн — приморське портове містечко нічних ельфів на похмурих берегах Темного Узбережжя, головна морська...",kw={"обердайн","порт","темне узбережжя","тундріс віндвівер","альянс","калімдор"},ang={["faction:Alliance"]="Цей порт — кровоносна жила подорожей і постачання Альянсу на півночі Калімдору: він забезпечує надійне сполучення між Стормвіндом, Айронфорджем і Дарнасусом.",["race:NightElf"]="Для калдореїв, що вирушають із Тельдрассилу, Обердайн — перший справжній осередок на материку, де давні традиції зустрічаються з дивними звичаями й гамірною діяльністю молодших союзників по Альянсу."},sec={{t="Брама до північного Калімдору",b="Обердайн, що лежить на березі Прихованого Моря, — єдине велике поселення, яке встояло на нинішньому Темному Узбережжі. На відміну від відлюдних міст у кронах Тельдрассилу, Обердайн дивиться назовні: це найжвавіший порт Альянсу на півночі. Звідси регулярно ходять кораблі до Гавані Менетіл у Східних Королівствах, а місцеві пороми курсують до Селища Рут'теран біля коріння Світового Дерева. Завдяки торгівлі в Обердайні панує розмаїтіший дух, ніж у традиційних ельфійських анклавах: гості бачать ліхтарі над брукованими вулицями, вивіски дарнаською й всезагальною мовами та заморських купців, серед них дворфів і гномів, що походжають між низькими дерев'яними будинками з арками."},{t="Прихисток в облозі",b="Містечком керують старійшина Тундріс Віндвівер і Рада селища Обердайн, які разом із місцевими Вартовими організовують оборону Темного Узбережжя. Попри роль важливого торгового вузла, високородні мешканці Дарнасуса часто дивляться на Обердайн скоса, вважаючи його торговців, рибалок і чужинців диваками. Містечко постійно потерпає від небезпек краю: агресивні мурлоки нападають на рибальські човни на узмор'ї, осквернені фурболги Чорнолісся тиснуть із півдня, а мерзенна магія, що стікає зі Сквернолісся, бентежить місцевих звірів."}},faq={{q="Куди ходять кораблі з Обердайна?",a="Доки сполучають північ Калімдору з ширшим світом Альянсу. Біля одного причалу стоїть пором до Селища Рут'теран біля підніжжя Тельдрассила, а біля іншого — великі океанські судна, що пливуть через Велике Море просто до Гавані Менетіл у Багнокраї.",al={"кораблі з оберіжина","куди йдуть кораблі","подорож з оберіжина"}},{q="Хто править Обердайном?",a="Обердайном опікується старійшина Тундріс Віндвівер разом із Радою Селища Обердайн. Оборону поселення ведуть Вартові, яких на місці очолює Вартова Ґлінда Нал'Шея.",al={"хто править оберіжином","керівник оберіжина","хто головний"}},{q="Чому в містечку нічних ельфів живуть дворфи й люди?",a="Обердайн — головний порт Альянсу на півночі Калімдору, тож чужоземні торгівці, ремісники й мандрівники прибувають саме сюди. Дворфи влаштували тут кузню, щоб обслуговувати кораблі й подорожніх, і через це містечко незвично різноманітне й гостинне порівняно з традиційними поселеннями нічних ельфів.",al={"чужинці в оберіжині","чому тут дворфи"}},{q="Чому нічні ельфи з Дарнасуса зверхньо дивляться на Обердайн?",a="Прихильники традицій і відлюдності в Дарнасусі часто вважають Обердайн зіпсованим мирською торгівлею й чужоземним впливом. Дехто з ортодоксальних ельфів має його мешканців за диваків, а жвавий торговий осередок, на їхню думку, погано пасує до суворо традиційного друїдського способу життя.",al={"суперництво дарнасуса й оберіжина","вигнанці оберіжина"}}},fp="9,353,28.711.0,19.550.0,35.261.0,20.188.0,60.308.0,57.277.0"}
P.entries["subzone:azurelode-mine"] = {n="Шахта Лазурової Жили",s="Шахта Лазурової Жили — діюча залізна копальня Альянсу в південно-західних пагорбах Передгір'я Гілсбреда. Її охороняє ополчення Саутшора, а працюють тут люди-робітники; надійний видобуток руди живить воєнні зусилля місцевих людей проти Відступників Таррен Мілла.",h="Шахта Лазурової Жили — діюча залізна копальня Альянсу в південно-західних пагорбах Передгір'я Гілсбреда.",kw={"шахта лазурової жили","залізо","саутшор","наглядач бондс","гірництво","гілсбред"},ang={["faction:Horde"]="Удар по Шахті Лазурової Жили відрізає Саутшор від свіжого заліза й прямо підтримує наступ Відступників у Передгір'ї.",["profession:Mining"]="Тунелі всередині й кряжі довкола Шахти Лазурової Жили багаті на залізну руду, хоча рудокопи Альянсу люто стережуть надра."},sec={{t="Жили передгір'я",b="Шахта Лазурової Жили, що лежить на південний захід від відкритих полів і трохи на захід від Саутшора, здавна видобуває багатства з рудних кряжів уздовж узбережжя. До того як запечатали Стіну Ґреймейна, ці пагорби вважалися частиною земель Ґілнеаса. Сьогодні люди-рудокопи працюють глибоко під землею під пильним оком Наглядача Бондса, добуваючи залізо, щоб кувати зброю й обладунки для захисників Альянсу, які тримають край проти Андерсіті."},{t="Важлива воєнна ціль",b="Шахта Лазурової Жили дає більшу частину сирого заліза, потрібного для утримання гарнізонів і міського ополчення Саутшора, тож вона опинилася просто під прицілом Орди. Таррен Мілл раз у раз б'є по її робітниках і охороні, намагаючись перерізати шляхи постачання, що підтримують людські твердині Гілсбреда."}},faq={{q="Хто контролює Шахту Лазурової Жили?",a="Шахту Лазурової Жили контролює Альянс, а працюють у ній людські рудокопи, пов'язані із Саутшором і селищем Гілсбред; на місці за ними наглядає Наглядач Бондс.",al={"хто керує лазуровою жилою","фракція шахти лазурової жили","чия лазурова жила"}},{q="Чому шахта важлива для Орди?",a="Шахта постачає життєво важливе залізо до зброярень Саутшора й місцевого ополчення Альянсу. Провід Таррен Мілла б'є по рудокопах і наглядачах, щоб підірвати виробництво людської зброї в Передгір'ї.",al={"чому нападати на лазурову жилу","битва за шахту гілсбреду","інтерес орди до шахти"}},{q="Чи Шахта Лазурової Жили завжди належала Гілсбреду?",a="Колись суворий хребет, де лежить Шахта Лазурової Жили, був у межах зовнішніх кордонів Ґілнеасу — ще до того, як Король Ґенн Ґреймейн звів Стіну Ґреймейна, відгородивши своє королівство від решти Лордерона.",al={"історія стіни грейманів","чи лазурова жила була гілнеаса","гілнеаська шахта"}},{q="Які метали тут добувають?",a="Шахта здебільшого дає залізну руду для людських зброярень поблизу.",al={"яка руда в лазуровій жилі","ресурси лазурової жили"}}},fp="14,261,22.430.0,23.300.0,28.163.0,39.197.0,44.199.0,27.63.0"}
P.entries["subzone:bael-dun-digsite"] = {n="Розкопки Бел'дуну",s="Розкопки Бел'дуну — дворфійська копальня, вирубана глибоко в горах уздовж західного краю Малгору. Закладена загоном Шукача Хазґорма з Бель Модану, вона в очах місцевих тауренів — пряме осквернення прабатьківської землі й образа Земній Матері.",h="Розкопки Бел'дуну — дворфійська копальня, вирубана глибоко в горах уздовж західного краю Малгору.",kw={"бел'дун","розкопки","дворфи","ліга дослідників","бель модан","малгор","титани"},ang={["faction:Alliance"]="Хоч копачами Бел'дуну рухає щира жага історичних відкриттів, вони зайшли надто глибоко в суверенні землі Орди, спричинивши криваві сутички з місцевими.",["race:Tauren"]="Рубці від вторгнення на західних пагорбах Малгору роблять Бел'дун прямою образою Земній Матері, що вимагає рішучих дій — захистити прабатьківську землю від чужинського осквернення."},sec={{t="Вторгнення в пагорби",b="Розкопки Бел'дуну, що примостилися на гірських схилах західного Малгору, — найпівденніший форпост експедиції дворфійської Ліги Дослідників, яка базується в Бель Модані в південних Пустках. Не зважаючи ні на кордони, ні на духовні традиції щойно осілих племен, дворфійські шукачі прибули з кирками, лопатами й вибуховим порохом, аби видобути стародавні реліквії титанів, поховані під рівнинами."},{t="Захист Земної Матері",b="Плем'я Бладгуф сприйняло ці загарбницькі розкопки як відвертий напад на Земну Матір. Бейн Бладгуф спершу закликав до обережності й намагався застерегти зайд, та дворфи навідріз відмовилися покинути свої траншеї. Дійшовши висновку, що дипломатія зазнала поразки, таурени постановили потрощити знаряддя експедиції й силою вигнати копачів, поки їхнє руйнівне копання не роздерло священну землю Малгору ще глибше."}},faq={{q="Чому дворфи копають у Малгорі?",a="Шукачі належать до дворфійської експедиції зі штабом у Бель Модані на півдні Пусток. Ведені прагненням Ліги Дослідників знайти давні артефакти й спадщину Титанів, вони заснували цю заставу там, де їхні прилади вказували на реліквії, знехтувавши правом тауренів на ці землі.",al={"чому дворфи тут","дворфи в мулґорі","дворфи бел'дуну"}},{q="Як плем'я Бладгуф ставиться до розкопок?",a="Таурени вважають ці роботи нестерпною раною на тілі Земної Матері. Коли дворфи відмовилися мирно піти після перших попереджень, Бейн Бладгуф і очільники села послали воїнів знищити знаряддя рудокопів і вигнати непроханих гостей із Малгору.",al={"що думають таурени","реакція бейна","відповідь тауренів на розкопки"}},{q="Що пов'язує Бел'дун і Бель Модан?",a="Бел'дун — допоміжні розкопки, засновані просто з фортеці й головних розкопок у Бель Модані, що лежать одразу за гірським хребтом на півдні Пусток.",al={"зв'язок з бель моданом","звідки ці дворфи"}},{q="Чому таурени просто не домовилися з експедицією?",a="Бейн Бладгуф спершу шукав дипломатичних рішень і офіційно попереджав очільників експедиції. Але дворфи вважали Малгор нічийною глушиною й цілком знехтували духовними переконаннями тауренів, тож племені не лишалося нічого, крім сили.",al={"чи таурени пробували мир","дипломатія з дворфами"}}},fp="16,299,22.420.0,26.432.0,35.308.0,52.266.0,55.172.0,59.263.0"}
P.entries["subzone:bael-dun-keep"] = {n="Фортеця Бел'дун",s="Фортеця Бел'дун — грізне дворфійське укріплення над розкопками Бель Модан на півдні Пусток. Під командуванням Генерала Твінбрейда ця фортеця тримає суперечливу присутність Альянсу в краї і втягує його в запеклий конфлікт із довколишніми землями Орди.",h="Фортеця Бел'дун — грізне дворфійське укріплення над розкопками Бель Модан на півдні Пусток.",kw={"фортеця бел'дун","бель модан","дворфи","генерал твінбрейд","стоунспайр","пустки"},ang={["faction:Alliance"]="Ця фортеця — ваш головний військовий плацдарм на півдні Пусток: вона береже цінні відкриття Ліги Дослідників від ворожих сил Орди.",["race:Tauren"]="Фортеця Бел'дун стоїть на священній землі, відібраній у племені Стоунспайр, — образливе нагадування про те, як Альянс зазіхає на вашу батьківщину."},sec={{t="Дворфійська твердиня на Калімдорі",b="Фортеця Бел'дун, збудована за кресленнями дворфійського архітектора Гаґґіса Боутмердера, — укріплене військове серце присутності Айронфорджа на півдні Пусток. Височіючи над широкими траншеями розкопок Бель Модана, вона захищає шукачів і археологів, які розшукують давні артефакти титанів. Гарнізон, добре озброєний залізом і гарматами, пильно стереже дворфійські шляхи постачання й демонструє військову силу Альянсу в самому серці Калімдору."},{t="Осередок кровопролиття",b="Будівництво Фортеці Бел'дун і розкопок поряд не минуло мирно: воно вигнало місцеве плем'я тауренів Стоунспайр з їхньої прадавньої домівки. Тепер Бел'дун — гаряча точка Пусток, що ось-ось вибухне. Ближні застави Орди вважають фортецю зухвалим військовим вторгненням, а Ґанн Стоунспайр веде проти загарбників особисту війну помсти. Між скривдженими тауренами, спритними розвідниками й насторожено ворожими заставами на кшталт Табору Тауражо фортеця постійно під загрозою набігів і диверсій."}},faq={{q="Хто контролює Фортецю Бел'дун?",a="У фортеці стоїть гарнізон дворфійських вояків, підпорядкованих Альянсу й Лізі Дослідників з Айронфорджа, на чолі з непохитним командиром Генералом Твінбрейдом.",al={"хто керує бел'дуном","хто керує фортецею бел'дун","генерал твінбрейд"}},{q="Чому Фортецю Бел'дун збудували на півдні Пусток?",a="Її заснували, щоб боронити Бель Модан — величезну археологічну експедицію, що шукає в Калімдорі реліквії титанів і давні витоки дворфів.",al={"чому дворфи в пустках","призначення бел'дуну","чому дворфи збудували тут"}},{q="Чому місцеві таурени нападають на Фортецю Бел'дун?",a="Розкопки й фортеця вигнали тауренів-Стоунспайрів з їхніх родових земель. Уцілілі на кшталт Ґанна Стоунспайра прагнуть помсти й знищення дворфійських загарбників.",al={"помста ґанна стоунспайра","чому таурени ненавидять бел'дун","ворожнеча стоунспайрів"}},{q="Хто був архітектором фортеці?",a="Дворфійські архітектурні записи свідчать, що фортецю спроєктував і збудував Гаґґіс Боутмердер.",al={"хто збудував фортецю","хеґіс боутмердер","креслення бел'дуну"}}},fp="13,304,32.528.0,25.523.0,27.162.0,51.142.0,49.187.0,38.102.0"}
P.entries["subzone:bael-modan"] = {n="Бель Модан",s="Бель Модан — укріплена дворфійська застава й місце археологічних розкопок на півдні Пусток. Її заснували дворфи-копачі, що шукають давні реліквії Титанів, і ця добре озброєна споруда розпалила запеклий конфлікт, вигнавши корінних тауренів Стоунспайр.",h="Бель Модан — укріплена дворфійська застава й місце археологічних розкопок на півдні Пусток.",kw={"бель модан","розкопки","ліга дослідників","сльоза місяців","фіґлі вигнанець","стоунспайр"},ang={["race:Dwarf"]="Розкопки — свідчення невтомного прагнення Ліги Дослідників розкрити історію Титанів, хоча грубі методи її командирів накликали люту ворожнечу місцевих племен.",["race:Tauren"]="Бель Модан — відкрита рана Пусток, збудована на руїнах священної землі племені Стоунспайр. Допомогти Ґаннові Стоунспайру помститися — справа племінної честі."},sec={{t="Відкопані таємниці й кров",b="Бель Модан — це укріплена Фортеця Бел'дун, ряд велетенських облогових гармат, майданчики для гірокоптерів і глибокий відкритий котлован. Дворфи-шукачі прибули на Калімдор, переконані, що під червоною землею похована давня споруда Титанів. Проте їхні вибухові роботи прорвалися просто крізь священну землю тауренів Стоунспайр. Замість домовлятися, дворфійська експедиція прогнала Стоунспайрів з прадавніх земель рушничним вогнем і вибухівкою, і вцілілі одноплемінники розсіялися, сповнені жаги помсти."},{t="Ціна відкопаних реліквій",b="Розкопки виявили значно більше, ніж давню кладку. Нещодавно дворфи-копачі відкопали артефакт, відомий як Сльоза Місяців, — реліквію, що викликає параною й божевілля в тих, хто поруч. Один вигнаний шукач, Фіґлі Вигнанець, цілком піддався її впливу — і щойно камінь знову опинився в його руках, обернувся на трога. Між смертоносними реліквіями й розлюченими тауренами, що шукають відплати за брамою, дворфійський табір постійно в небезпеці."}},faq={{q="Чому дворфи копають у Пустках?",a="Дворфи шукають давні споруди й реліквії Титанів, поховані під Калімдором. Їхні розкопки — частина ширшої експедиції, що прагне з'ясувати походження їхньої раси, яке, як вони вірять, пов'язане з похованими дослідницькими осередками Титанів.",al={"чому дворфи копають","призначення бель модана","що шукають дворфи"}},{q="Що сталося з тауренами, які тут жили?",a="Колись ця земля належала племені Стоунспайр, яке вважало ці пагорби святими. Прибувши, дворфи підірвали місце розкопок вибухівкою, вирізали чи вигнали тауренів і знищили їхнє село.",al={"таурени стоунспайр","хто жив у бель модані","село тауренів"}},{q="Хто такий Ґанн Стоунспайр?",a="Ґанн Стоунспайр — один із небагатьох уцілілих із племені Стоунспайр. Після того як спроби мирно владнати справу провалилися, він отаборився біля дороги під Бель Моданом і закликає мандрівників з Орди нищити дворфійські літальні машини й убивати офіцерів, винних у руйнуванні домівки його народу.",al={"ґанн","видавець ґанн"}},{q="Що таке Сльоза Місяців?",a="Сльоза Місяців — загадковий артефакт, який викопали дослідники. Він доводить до божевілля смертних, що беруть його до рук, і вигнанець-дворф Фіґлі став одержимим думкою повернути його.",al={"реліквія сльоза місяців","артефакт фіґлі"}}},fp="10,281,31.560.0,29.490.1,39.246.0,50.245.0,23.302.0,30.181.1"}
P.entries["subzone:bal-lal-ruins"] = {n="Руїни Бал'лал",s="Руїни Бал'лал — прадавні руїни тролів Ґурубаші на північно-західному узбережжі Долини Стренглторну, трохи на північ від Базового Базового Табору Ґром'ґол. Ці кам'яні підмурки, що розсипаються над каламутними водами Мерзотного Рифу, нині захопили ворожі тролі Кривавого Скальпа.",h="Руїни Бал'лал — прадавні руїни тролів Ґурубаші на північно-західному узбережжі Долини Стренглторну, трохи на...",kw={"руїни бал'лал","ґурубаші","кривавий скальп","тролі","долина стренглторну","риф"},ang={["faction:Horde"]="Бал'лал лежить трохи далі узбережжям від Базового Базового Табору Ґром'ґол, і тролі Кривавого Скальпа там — постійна докука для патрулів Орди вздовж берега.",["race:Troll"]="Для тролів Темного Списа, що стоять за Орду, такі місця, як Бал'лал, — тверезий погляд на руїни давньої слави Ґурубаші, які тепер тримають споріднені племена, засліплені невгамовною жагою крові."},sec={{t="Зруйнована застава над рифом",b="Руїни Бал'лал на узбережжі на північ від Базового Базового Табору Ґром'ґол — ще один уламок розтрощеної Імперії Ґурубаші. Колись це була частина величної тролячої цивілізації, що панувала на півдні Азероту, а тепер від неї лишилися порослі мохом кам'яні мури й потріскана кладка. Руїни прилягають просто до Мерзотного Рифу, і з них видно підступні прибережні мілини. Нині тут хазяйнують агресивні тролі Кривавого Скальпа, що люто боронять від чужинців вивітрені реліквії своїх предків."}},faq={{q="Хто контролює Руїни Бал'лал?",a="Нині руїни захопили тролі з племені Кривавий Скальп, які люто стережуть свою територію від чужинців, мандрівників і суперників.",al={"хто тут живе","мобі руїн бал'лал","хто на руїнах бал'лал"}},{q="Де Руїни Бал'лал?",a="Вони на північно-західному узбережжі Долини Стренглторну, просто на північ від Базового Базового Табору Ґром'ґол, з видом на Мерзенний Риф.",al={"місце руїн бал'лал","де руїни бал'лал","як знайти руїни бал'лал"}},{q="Яка історія цих руїн?",a="Як і більшість кам'яних споруд, розкиданих Долиною Стренглторну, Руїни Бал'лал сягають часів давньої Імперії Ґурубаші — ще до того, як вона розпалася на ворогуючі племена джунглевих тролів.",al={"переказ про бал'лал","історія руїн бал'лал","хто збудував бал'лал"}}},fp="13,269,31.527.0,27.153.0,36.151.0,33.193.0"}
P.entries["subzone:balia-mah-ruins"] = {n="Руїни Балія'ма",s="Руїни Балія'ма — порослі мохом рештки прадавнього поселення Ґурубаші на півночі Долини Стренглторну. Ці кам'яні тераси, що розсипаються, лежать на схід від Базового Базового Табору Ґром'ґол, по той бік річки, і нині їх захопили й стережуть воїни ворожого тролячого племені Череполомів.",h="Руїни Балія'ма — порослі мохом рештки прадавнього поселення Ґурубаші на півночі Долини Стренглторну.",kw={"руїни балія'ма","ґурубаші","череполоми","тролі","долина стренглторну","ґром'ґол"},ang={["faction:Horde"]="Ворожі Череполоми в Балія'ма, що засіли просто за річкою від Базового Базового Табору Ґром'ґол, — постійна загроза для розвідників і шляхів постачання Орди.",["race:Troll"]="Для тролів Темного Списа прогулянка цими прадавніми кам'яними терасами нагадує і про горду цивілізацію Ґурубаші, спільну для їхніх предків, і про темні чвари, що розірвали суспільство тролів джунглів."},sec={{t="Розтрощена спадщина",b="Як і чимало кам'яних споруд, розкиданих джунглями, Балія'ма — уламок розлогої Імперії Ґурубаші, що колись панувала на більшій частині півдня Східних Королівств. Після падіння давньої столиці землі Ґурубаші розкололися на ворожі угруповання. Нині руїни — твердиня племені Череполомів, які люто боронять кам'яні тераси від бродячих звірів, сусідніх огрів із кургану Мош'Оґґ і всіх чужинців, яким стане дурості перейти річку."}},faq={{q="Де Руїни Балія'ма?",a="Руїни — на півночі Долини Стренглторну, на схід-південний схід за річкою від застави Орди Базовий Табір Ґром'ґол і на південний захід від Кургану Огрів Мош'Оґґ.",al={"місце балі'ма","де балія'ма","карта руїн балія'ма"}},{q="Хто нині контролює руїни?",a="Нині руїни захопило плем'я Череполомів — вороже угруповання джунглевих тролів, що люто стереже давні кам'яні тераси.",al={"хто живе в балія'ма","які мобі в балія'ма","вороги балія'ма"}},{q="Яка історія Балія'ма?",a="Цей комплекс збудували за розквіту Імперії Ґурубаші. Коли імперія впала, місце занепало, і врешті його поглинули джунглі та вцілілі племена тролів.",al={"переказ про балія'ма","хто збудував балія'ма"}},{q="Чи пов'язані Череполоми в Балія'ма з іншими таборами тролів?",a="Так. Плем'я Череполомів має кілька таборів і руїн на півночі й у центрі Долини Стренглторну й веде безперервну війну за землі із суперницькими племенами, як-от Кривавий Скальп.",al={"череполоми в штормовій гущавині","череполоми балія'ма"}}},fp="15,283,20.498.0,38.164.0,33.148.0,33.200.0,67.205.0"}
P.entries["subzone:balnir-farmstead"] = {n="Хутір Балнірів",s="Хутір Балнірів — занедбаний маєток у східних Галявинах Тірісфалю, на північний схід від Руїн Лордерона. Колись славний розведенням знаменитих білих коней, яких любила королівська родина Лордерона, тепер він лежить у руїнах, заполонений блукаючою Погибеллю. Сьогодні маєток — сумний пам'ятник ранньому життю принца Артаса Менетіла й місце, де той здобув свого скакуна-нежить.",h="Хутір Балнірів — занедбаний маєток у східних Галявинах Тірісфалю, на північний схід від Руїн Лордерона.",kw={"хутір балнірів","артас менетіл","інвінсібл","коні","погибель","чумні землі","тірісфаль"},ang={["class:Mage"]="Магів Відступників посилають на ці уражені землі збирати вцілілі ротики Балнірів і вивчати їх, щоб виявити залишкову магічну заразу Погибелі.",["race:Undead"]="Для Відступників цей хутір — гірке нагадування про принца, який прирік Лордерон, а також набридлива прогалина в обороні, крізь яку Погибель із Чумних Земель прослизає за Оплот."},sec={{t="Спадщина королівських скакунів",b="Поколіннями родина Балнірів розводила легендарних білих жеребців Лордерона на своїй садибі серед хвилястих пагорбів Тірісфалю. Хлопчиком принц Артас Менетіл часто навідувався на ферму, тікаючи від придворного життя, і заприятелював із молодим Джарімом Балніром. Саме тут Артас допоміг прийняти лоша, яке назвав Інвінсіблом. Через роки, коли трагічний нещасний випадок під час верхової їзди обірвав життя скакуна, Інвінсібла на особисте прохання Артаса поховали в землі хутора."},{t="Спустошення й проникнення Погибелі",b="Коли принц Артас повернувся з Нортренду й сплюндрував столичне місто Лордерона, Погибель без жалю винищила родину Балнірів. Щойно ставши лицарем смерті, Артас рушив на хутір, щоб викопати й воскресити Інвінсібла Фростморном, лишивши по собі розриту, сплюндровану могилу. Після Третьої війни руїни правлять за плацдарм безтямної Погибелі, що прослизає повз Оплот. Вартові Смерті Відступників насторожено стежать за фермою, а маги Андерсіті збирають у саду вцілілі ротики, щоб перевірити, як глибоко чумна скверна проникла в ґрунт."}},faq={{q="Чому Хутір Балнірів важливий для принца Артаса?",a="У юності Артас часто тікав на хутір погратися із сином конярів. Він був при народженні свого улюбленого коня Інвінсібла, а згодом поховав його тут після фатального падіння. Поринувши в темряву, Артас повернувся, щоб відкопати Непереможного й підняти його з мертвих.",al={"ферма артаса","місце народження непереможного","зв'язок балнірів з артасом"}},{q="Хто жив на хуторі до чуми?",a="Господарство вели Джорум Балнір, його дружина Вара й син Джарім. Вони були майстрами-конярами й вирощували цінних білих коней для шляхти Лордерона. Усю родину вирізали, коли Погибель Артаса прокотилася Тірісфалем у Третій війні.",al={"хто володів фермою балнірів","родина балнірів","джорум балнір"}},{q="Чому Відступники нині стежать за фермою?",a="Безмозка Погибель часто прослизає повз Заслон із Чумних Земель і збирається на хуторі, загрожуючи східним підступам до Тірісфалю. До того ж учені Андерсіті вивчають витривалі ротики, що досі ростуть у садах, щоб виміряти, як далеко поширилася чумна зараза.",al={"чому відступники стежать","переказ про тиловий патруль","дракончики балнірів"}},{q="Чому Непереможного поховали на Хуторі Балнірів?",a="Коли Непереможний загинув, упавши під час їзди, Артас попросив поховати свого улюбленого коня на землі хутора. Повернувшись у Третій війні лицарем смерті, Артас підняв Непереможного з мертвих.",al={"поховання непереможного","могила непереможного","поховання коня артаса"}}},fp="16,385,24.502.0,35.561.0,57.306.0,45.263.0,45.283.0,46.212.0"}
P.entries["subzone:ban-ethil-barrow-den"] = {n="Курганне Лігво Бан'етіл",s="Курганне Лігво Бан'етіл — священне підземне святилище, видовбане в корінні Тельдрассила. Створене як місце спочинку для сплячих Друїдів Кігтя, печерний комплекс нещодавно поринув у хаос. Зіпсуті фурболги племені Вузлошкірів заполонили його зали, перетворивши місце мирного сну на небезпечне лігво божевілля.",h="Курганне Лігво Бан'етіл — священне підземне святилище, видовбане в корінні Тельдрассила.",kw={"курганне лігво бан'етіл","бан'етіл","друїди кігтя","фурболги","вузлошкіри","смарагдовий сон","тельдрассил"},ang={["class:Druid"]="Бан'етіл — священна земля для Кола Кенарія, збудована саме для того, щоб захищати Друїдів Кігтя, поки ті єднаються зі Смарагдовим Сном.",["race:NightElf"]="Захоплення Бан'етілу зіпсутими фурболгами-Вузлошкірами — тривожна ознака хвороби, що шириться їхньою новою домівкою, Тельдрассилом."},sec={{t="Осквернене святилище",b="Курганні лігва — священні покої спочинку, де друїди нічних ельфів сплять, посилаючи свій дух у Смарагдовий Сон. Курганне Лігво Бан'етіл було призначене саме для Друїдів Кігтя, що єднаються з природою. Поділене на верхні й нижні підземні покої, лігво колись бриніло тихою задумою й глибокою магією медитації. Та недуга, що охопила живність Тельдрассила, не оминула й фурболгів-Вузлошкірів: вони вдерлися до комплексу й перетворили його видовбані зали на укріплене кубло."},{t="Вторгнення Вузлошкірів",b="Збожеволілі від таємничої скверни, що пускає коріння по всьому Світовому Дереву, Вузлошкіри вигнали сплячих друїдів із Бан'етілу або поставили їх під загрозу. Тепер фурболги люто стережуть звивисті тунелі й нападають на кожного нічного ельфа, що наближається. Для захисників Тельдрассила повернути курганне лігво — нагальне завдання: не лише щоб відігнати ворожих фурболгів, а й щоб захистити вразливих друїдів і священні реліквії, замкнені в нижніх глибинах."}},faq={{q="Що таке Курганне Лігво Бан'етіл?",a="Курганне Лігво Бан'етіл — підземна западина на Тельдрассилі, створена нічними ельфами. Її збудували як прихисток для сплячих Друїдів Кігтя, поки їхні духи мандрують Смарагдовим Сном.",al={"що таке бан'етіл","призначення бан'етіл","що це за печера"}},{q="Чому в Курганному Лігві Бан'етіл фурболги?",a="Фурболги Вузлошкіри стали жертвами скверни, що поширюється серед створінь Тельдрассила. Ставши ворожими й ревно стережучи свою територію, вони вдерлися до курганного лігва, витіснили доглядачів і загрожують сплячим друїдам.",al={"чому фурболги в бан'етіл","будякохутрі в бан'етіл","хто захопив бан'етіл"}},{q="З яких частин складається курганне лігво?",a="Печерний комплекс поділяється на два головні пов'язані яруси: Верхнє Лігво біля вхідних ходів і Нижнє Лігво глибше серед підземного коріння.",al={"розташування бан'етіл","верхнє лігво нижнє лігво","рівні бан'етіл"}},{q="Чому курганні лігва такі важливі для друїдів?",a="Курганні лігва дають безпечний прихисток друїдам, що поринають у тривалий глибокий сон, аби перенести свою свідомість до Смарагдового Сну, — адже їхні тіла роками чи десятиліттями лишаються беззахисними.",al={"чому друїди сплять в лігвах","переказ про курганні лігва друїдів","курганне лігво смарагдового сну"}}},fp="20,368,19.540.0,23.472.0,29.189.0,51.224.0,40.159.0,43.209.0"}
P.entries["subzone:ban-ethil-hollow"] = {n="Лощина Бан'етіл",s="Лощина Бан'етіл — скелястий яр, що врізається в ліс одразу на південь від головної дороги між Доланааром і Дарнасусом. Вона стала небезпечним прихистком для зіпсутих, агресивних фурболгів, які постійно загрожують подорожнім. У глибині яру ховається вхід до Курганного Лігва Бан'етіл.",h="Лощина Бан'етіл — скелястий яр, що врізається в ліс одразу на південь від головної дороги між Доланааром і...",kw={"лощина бан'етіл","бан'етіл","яр","фурболги","доланаар","дарнасус","тельдрассил"},ang={["class:Druid"]="Лощина ховає вхід до Курганного Лігва Бан'етіл — священної землі, де друїди традиційно спочивають, єднаючись зі Смарагдовим Сном, а тепер їм загрожує скажена живність.",["race:NightElf"]="Бачити, як фурболги божеволіють так близько до дороги між Доланааром і Дарнасусом, — похмурий знак дедалі тяжчої хвороби Тельдрассила, що вимагає втручання молодих вартових і друїдів."},sec={{t="Небезпечний яр",b="Лощина Бан'етіл, що лежить осторонь шляху між Доланааром і Дарнасусом, — різке нагадування, що гілля Тельдрассила не зовсім безпечне. Фурболги, збожеволілі від дивної недуги, яка мучить Світове Дерево, знайшли притулок по всьому скелястому спуску. Вони часто чатують біля стежки, вичікуючи необачних гінців і мандрівних вартових, щоб напасти із засідки. У глибині яру — поріг Курганного Лігва Бан'етіл, де сплячі друїди й давні тунелі потерпають від навали знавіснілих звірів іззовні."}},faq={{q="Де Лощина Бан'етіл?",a="Лощина Бан'етіл — яр у центрі Тельдрассила, трохи на південь від головної дороги між селом Доланаар і столицею Дарнасусом.",al={"місце лощини бан'етіл","де лощина бан'етіл","знайти лощину бан'етіл"}},{q="Чому тутешні фурболги ворожі?",a="Фурболги по всьому Тельдрассилу піддалися скверні й шаленству, що охопили звірів Світового Дерева. Замість того щоб мирно жити поруч із нічними ельфами, як було здавна, ці племена стали люто ворожими й ревно стережуть свої землі.",al={"чому фурболги шаленіють","ворожі фурболги бан'етіл","напад фурболгів бан'етіл"}},{q="Що в Курганному Лігві Бан'етіл у глибині лощини?",a="Курганне Лігво Бан'етіл — підземний комплекс, у якому друїди нічних ельфів здавна поринали в глибокий сон і єдналися зі Смарагдовим Сном. Та відтоді як у лощині наростає скверна, лігво стало небезпечним місцем.",al={"що в курганному лігві","курганне лігво бан'етіл","лігво в лощині бан'етіл"}},{q="Чи безпечна дорога над лощиною?",a="Головну дорогу зазвичай патрулюють Вартові нічних ельфів, але фурболги з Лощини Бан'етіл часто вибираються з яру, щоб влаштовувати засідки на мандрівників. Тим, хто подорожує між Доланааром і Дарнасусом, варто бути насторожі.",al={"чи безпечна дорога","засідки фурболгів","чи безпечна дорога до дарнасуса"}}},fp="16,317,17.529.0,34.165.0,34.262.0,66.236.0,44.239.0"}
P.entries["subzone:bandarion-keep"] = {n="Фортеця Бандаріон",s="Фортеця Бандаріон — укріплений редут, пов'язаний із Вартою Тіра, у західних закутках Галявин Тірісфалю біля Шепітливого Лісу. Названа на честь Ґарека Бандаріона, застава править за відособлений оплот серед загроз, що не зникають уздовж лісового прикордоння. Її захисники мають справу з усім — від ворожих прибережних мурлоків до мандрівних фанатиків і неврівноваженої нежиті.",h="Фортеця Бандаріон — укріплений редут, пов'язаний із Вартою Тіра, у західних закутках Галявин Тірісфалю біля...",kw={"фортеця бандаріон","варта тіра","шепітливий ліс","мурлоки","паладини","відступники","тірісфаль"},ang={["class:Paladin"]="Для святих воїнів, що зіткнулися з холодною дійсністю нежиття, Фортеця Бандаріон — і притулок, і пересторога: дехто з паладинів, не зумівши примирити Світло зі своїм нежиттям, зламався й обернув зброю проти побратимів-Відступників.",["race:Undead"]="Ця фортеця далеко на західному краю Тірісфалю доводить, що Відступники мусять пильнувати не лише Погибель і Багряний Хрестовий Похід, а й розбрат у власних лавах."},sec={{t="Бастіон на західному кордоні",b="Фортеця Бандаріон біля відлюдного Шепітливого Лісу в західних Галявинах Тірісфалю — самотній вартовий Відступників. Названа на честь Ґарека Бандаріона, ця твердиня тісно пов'язана з Вартою Тіра. Інтенданти на кшталт Джоріна Кроджа старанно постачають гарнізон попри віддалене й важке становище далеко від людних дворів Андерсіті."},{t="В оточенні загроз",b="Утримувати фортецю — не спокійне призначення. Заставі постійно загрожують наскоки мурлоків Темноплавців з сусідніх вод, пробні сутички з Багряним Хрестовим Походом і заблукалі безтямні раби Погибелі, що шкутильгають крізь морок. Та ще гірші внутрішні небезпеки: дехто з паладинів, не здатних звикнути до свого нежиття серед Відступників, піддався божевіллю й обернув зброю проти власних побратимів."}},faq={{q="Де Фортеця Бандаріон?",a="Фортеця Бандаріон — у далеких західних нетрях Галявин Тірісфалю, неподалік загадкового Шепітливого Лісу.",al={"місце фортеці бандаріон","де фортеця бандаріон","як знайти фортецю бандаріон"}},{q="На честь кого названо Фортецю Бандаріон?",a="Твердиню названо на честь Ґарека Бандаріона — помітної постаті, пов'язаної з орденом, що тут стоїть.",al={"хто такий бандаріон","ґарек бандаріон","походження назви бандаріон"}},{q="Що таке Варта Тіра?",a="Варта Тіра — назва, яку вживають у зв'язку з Фортецею Бандаріон і паладинами-Відступниками, що там перебувають. Завдання бета-версії Forever вживають обидві назви як рівнозначні, тож незрозуміло, чи Варта Тіра — це організація, чи давніша назва місця.",al={"варта тіра","що таке варта тіра"}},{q="Які небезпеки загрожують фортеці?",a="Захисники фортеці раз у раз відбиваються від мурлоків-Темноплавців, б'ються з фанатиками Багряного Хрестового Походу, знищують безмозку Погибель, що блукає довкола, і приборкують навіжених паладинів із Відступників, які втрачають розум і нападають на своїх.",al={"хто нападає на фортецю бандаріон","загрози бандаріону","вороги бандаріону"}}},fp="14,382,31.385.0,21.405.0,32.118.0,35.112.0,20.229.0,31.223.0"}
P.entries["subzone:baradin-bay"] = {n="Затока Барадін",s="Затока Барадін — розлога водойма між берегами Каз Модану, Багнокраю, Аратійського нагір'я та південного Лордерону. Під час Другої війни її пильно патрулював могутній флот Кул Тіраса, а нині в її водах ховаються підступні рифи, затонулі бойові кораблі й ворожі морські хижаки.",h="Затока Барадін — розлога водойма між берегами Каз Модану, Багнокраю, Аратійського нагір'я та південного...",kw={"затока барадін","кул тірас","загублений флот","друга війна","гавань менетіл","морський шлях"},ang={["faction:Alliance"]="Затока Барадін — морська артерія, що поєднує дії Альянсу в Каз Модані з його заставами в Араті й Гілсбреді, хоча морські небезпеки й затонулі уламки роблять кожну переправу ризикованою.",["race:Human"]="Для людей, особливо тих, чий рід сягає Кул Тіраса чи Лордерону, затока — освячена й скорботна земля, де лежать водяні могили моряків Другої війни."},sec={{t="Стратегічний водний шлях",b="Затока Барадін, яку обрамлюють береги Дун Мороґа на півдні та Лордерону на півночі, — важливий морський шлях, що з'єднує гавані Східних Королівств. Її опорою є жваві порти — Гавань Менетіл у Багнокраї та Саутшор у Передгір'ї Гілсбреда. Та плавати цими водами небезпечно: мілкі піщані коси, зубчасті мілини й небезпечні мешканці — мурлоки, кроколіски й глибоководні акули — повсякчас загрожують і морякам, і мандрівникам."},{t="Цвинтар флотів",b="Під час Другої війни Затока Барадін бачила запеклі морські бої флотів Кул Тіраса з Ордою. Нині похмурі нагадування про ті битви всіюють узбережжя й морське дно. Розтрощені корпуси Третього флоту Кул Тіраса — тут їх звуть Загубленим Флотом — лежать напівзатоплені вздовж берега Багнокраю, а інші кораблі пішли на дно аж до Затопленого Рифу. Тепер довкола цих трухлявих дерев'яних руїн никають ворожі духи, спритні шукачі поживи й ненажерливі морські звірі."}},faq={{q="Які великі порти розташовані на Затоці Барадін?",a="Найпомітніші поселення на березі затоки — Гавань Менетіл у Багнокраї й Саутшор у Передгір'ї Гілсбреда, що забезпечують життєво важливе морське сполучення.",al={"порти затоки барадін","гавані затоки барадін","куди веде затока барадін"}},{q="Чому на березі затоки стільки затонулих кораблів?",a="Чимало уламків, зокрема Загублений Флот біля берегів Багнокраю й кораблі на Затопленому Рифі, — це судна флоту Кул Тіраса, потоплені в запеклих морських битвах Другої війни.",al={"затонулі кораблі мокрих земель","чому тут затонулі кораблі","походження загубленого флоту"}},{q="Які загрози чатують у водах Затоки Барадін?",a="Мілини кишать агресивними мурлоками й болотяними кроколісками, а глибші води — хижими крабами, акулами й неспокійними духами потопельників-моряків.",al={"чудовиська затоки барадін","мурлоки затоки барадін","чи безпечно плавати в затоці барадін"}},{q="Які землі межують із Затокою Барадін?",a="Затоку Барадін оточують північний захід Дун Мороґу, болотисті береги Багнокраю, скелі Аратійського нагір'я й узбережжя півдня Гілсбреда та Ґілнеасу.",al={"які зони межують із затокою барадін","географія затоки барадін"}}},fp="11,315,20.484.0,23.504.0,47.178.0,55.190.0,55.183.0,37.172.0"}
P.entries["subzone:bashal-aran"] = {n="Башал'Аран",s="Башал'Аран — давні руїни Високородних на півночі Темного Узбережжя, трохи на схід від Обердайна. До Великого Розколу це було квітуче місто-сестра Амет'Арану, а тепер тут кишать демонічні сатири й грелли, що живляться залишками таємної магії, а самотній ельфійський привид досі ув'язнений давнім прокляттям.",h="Башал'Аран — давні руїни Високородних на півночі Темного Узбережжя, трохи на схід від Обердайна.",kw={"башал'аран","астеріон","сатири","грелли","високородні","темне узбережжя"},ang={["race:NightElf"]="Башал'Аран — трагічне нагадування про безрозсудну таємну гординю, що прирекла давню Імперію калдореїв і проклала шлях демонічній скверні."},sec={{t="Розколоте місто-близнюк",b="До того як десять тисяч років тому Великий Розкол зламав давній Калімдор, королева Азшара оселила улюблених підданих із Високородних у містах-близнюках Башал'Аран і Амет'Аран. Під владою могутнього мага Атрікуса Нарассіна міста славилися розкішними ринками й храмами на честь Елуни. Коли Колодязь Вічності обвалилося, катаклізм спустошив обидва поселення. З причин, загублених у часі, Атрікус скористався своєю таємною майстерністю, щоб ув'язнити власного заступника, мага Астеріона, у печатці з місячного каменю в Башал'Арані. Навіть після смерті тіла привид Астеріона лишився прикутим до зруйнованої святині."},{t="Демонічна навала",b="Нині напівзруйноване каміння Башал'Арану захопили мерзенні зайди: сатири Дет'рилл і пустотливі грелли. Приваблені залишками магії, що досі чіпляється за давню кладку, ці осквернені створіння вбирають рештки енергії, щоб підживлювати свої мерзенні мистецтва. Хоч вони роями кишать у зруйнованих дворах і тероризують мандрівників на лісових стежках Темного Узбережжя, демони оминають центральну святиню, де Астеріон несе свою нескінченну варту."}},faq={{q="Чим був Башал'Аран до свого знищення?",a="Башал'Аран був пишним містом калдореїв, яке королева Азшара заснувала для улюбленої знаті з-поміж Високородних ще до Великого Розколу. Разом із містом-близнюком Амет'Араном ним правив маг-володар Атрікус Нарассін.",al={"історія башал'арана","хто збудував башал'аран","чим була ця руїна"}},{q="Що за привид блукає святилищем?",a="Це дух Астеріона — шанованого воїна-мага з Високородних, що колись наглядав і за Башал'Араном, і за Амет'Араном. Його загадково зрадив правитель Атрікус Нарассін і прикув до цього місця печаткою з місячного каменю, тож Астеріон лишається ув'язненим навіть по смерті.",al={"хто астеріон","привид башал'арана","чому тут привид"}},{q="Чому в руїнах живуть сатири?",a="Сатирів і греллів привабили до Башал'Арана рештки могутньої тайної енергії, що лишилася по давніх Високородних. Вони живляться цими залишковими магічними випарами, щоб посилити свою темну демонічну магію.",al={"чому сатири тут","переказ про сатирів дет'рілл","грелли башал'арана"}},{q="Що пов'язує Башал'Аран і Амет'Аран?",a="Башал'Аран і Амет'Аран були містами-побратимами, якими правили разом за королеви Азшари. Астеріон часто подорожував між обома поселеннями, дбаючи про потреби мешканців, доки обидва не зруйнував Розкол.",al={"зв'язок з амет'араном","близнючі міста темного узбережжя","амет'аран і башал'аран"}}},fp="11,326,21.622.0,19.462.0,45.226.0,38.265.0,36.209.0,42.224.0"}
P.entries["subzone:bathran-s-haunt"] = {n="Притулок Батрана",s="Притулок Батрана — давні руїни калдореїв на північному заході Ашенвалю, на схід від Зорамського Узмор'я. Нещодавно це місце захопили травники Відступників зі своєю охороною: вони збирають тутешні рослини для алхімічних досліджень, і довколишній ліс поволі в'яне.",h="Притулок Батрана — давні руїни калдореїв на північному заході Ашенвалю, на схід від Зорамського Узмор'я.",kw={"притулок батрана","волосся батрана","відступники","руїни","травництво","ашенваль"},ang={["profession:Herbalism"]="Ці руїни — унікальне місце для травника: наскільки відомо, лише тут росте Волосся Батрана, трава, цінована за рідкісні цілющі властивості.",["race:NightElf"]="Табір Відступників у Притулку Батрана — образа для спадщини калдореїв: тут нежить-загарбники оскверняють давню ельфійську кладку й отруюють священну землю."},sec={{t="Сплюндрований притулок у давньому лісі",b="На північ від Руїн Ордил'Аран серед густого ашенвальського листя стоять напівзруйновані колони нічних ельфів. Колись тиха пам'ятка калдореїв опинилася в тіні Відступників. Серед мармурових уламків нишпорять травники-нежить та їхні охоронці, що влаштували тут грубу лабораторію просто неба. Сама їхня присутність отруює давню землю: трава гниє й буріє, яскраві квіти в'януть, а гаєм розповзається неприродний тлін, поки вони методично збирають рідкісні лісові інгредієнти для своїх дослідів."},{t="Збір Волосся Батрана",b="Головна цінність цих руїн — Волосся Батрана, унікальна цілюща трава, що вкорінюється лише серед цього каміння. Розвідники нічних ельфів і Альянсу вважають присутність Відступників мерзенним оскверненням священної ельфійської землі, а нежить тим часом старанно видобуває з рослини її могутні властивості. Орда кровно зацікавлена в цьому врожаї, хоча таємні методи Відступників і отруєна ними земля викликають підозру і в чужинців, і в союзників."}},faq={{q="Де Притулок Батрана?",a="Притулок Батрана — на північному заході Ашенвалю, просто на північ від Руїн Ордил'Аран і вглиб суходолу на схід від Зорамського Узмор'я.",al={"де притулок батрана","місце притулку батрана","як дістатися притулку батрана"}},{q="Чому тут Відступники?",a="Травники з Відступників влаштували серед руїн табір і лабораторію, щоб збирати й вивчати неповторну рослинність лісу, передусім рідкісну цілющу рослину Волосся Батрана.",al={"що нежить робить в ашенвалі","чому відступники в притулку батрана","мета відступників батрана"}},{q="Що таке Волосся Батрана?",a="Волосся Батрана — особлива цінна трава з сильними відновлювальними властивостями, що росте лише довкола зруйнованих мурів Притулку Батрана.",al={"рослина волосся батрана","що таке волосся батрана","трава батрана"}},{q="Чому земля довкола руїн гине?",a="Тривала присутність Відступників і їхня алхімічна діяльність отруїли найближчу місцину: трава буріє й в'яне, а ніжні лісові квіти гинуть.",al={"чому трава руда","скверна в притулку батрана","чому земля гниє"}}},fp="15,277,38.528.0,29.506.0,33.144.0,26.202.0,23.154.0,41.171.0"}
P.entries["subzone:bay-of-storms"] = {n="Затока Бур",s="Затока Бур — широка, неспокійна затока, що врізається в скелясті східні кручі Азшари. У її бурхливих водах ховаються прадавні руїни, затоплені печери й небезпечні морські звірі, тож плавати вздовж цього узбережжя ризиковано.",h="Затока Бур — широка, неспокійна затока, що врізається в скелясті східні кручі Азшари.",kw={"затока бур","азшара","храм арккорана","кладка гетери","печера лускобородого","риболовля"},ang={["profession:Cooking"]="Бурхливі глибокі води Затоки Бур славляться серед прибережних рибалок рідкісним і цінним глибоководним уловом біля берегів Калімдору."},sec={{t="Буремне узбережжя",b="Затока Бур, що відкривається до Великого Моря, визначає значну частину мальовничого узбережжя Азшари. Це далеко не тиха гавань: її збурені води й скелясті виступи — дім небезпечних звірів і прадавніх морських загроз. У її водах і вздовж берегів лежать такі пам'ятні місця, як затонулий Храм Арккорана, коралові рифи Кладки Гетери й Печера Лускобородого, тож звичайні моряки здебільшого уникають затоки, лишаючи її прибережним чудовиськам."}},faq={{q="Де Затока Бур?",a="Затока Бур — на східному краю Азшари, вона відкривається просто у Велике Море біля узбережжя Калімдору.",al={"місце затоки бур","де затока бур","де затока"}},{q="Які помітні місця є в затоці?",a="У затоці кілька помітних прибережних місць, зокрема Храм Арккорана, риф, відомий як Кладка Гетери, і прихована схованка — Печера Лускобородого.",al={"пам'ятки затоки бур","що є в затоці бур","цікаві місця затоки бур"}},{q="Чому затокою небезпечно плавати?",a="Шалений прибій, гострі зубчасті скелі й ворожі морські створіння роблять затоку зрадливою для кораблів, а прибережних поселень, що могли б прийти на порятунок, тут майже немає.",al={"чи затока бур безпечна","чому небезпечно","небезпеки затоки"}}},fp="13,238,19.462.0,35.117.0,42.165.0,37.168.0"}
P.entries["subzone:bear-s-head"] = {n="Ведмежа Голова",s="Ведмежа Голова — відлюдна гірська місцина на південно-східних кручах Азшари. Вона названа на честь місцевих фурболгів із племені Деревопащих, чиї поселення розкидані на скелястих висотах, і правує за заставу, пов'язану з їхніми більшими осідками далі на півночі; а просто над нею, на скелі, стоїть святилище Архімага Ксилема.",h="Ведмежа Голова — відлюдна гірська місцина на південно-східних кручах Азшари.",kw={"ведмежа голова","фурболги","деревопащі","вежа ксилема","архімаг ксилем","азшара"},ang={["class:Mage"]="На високій кручі над Ведмежою Головою живе Архімаг Ксилем — могутній і дивакуватий чародій, до якого звертаються знавці тайної магії, що прагнуть вищої науки."},sec={{t="Застави фурболгів і магія на кручі",b="Ведмежа Голова, захована на південному сході Азшари, завдячує назвою таборам фурболгів із племені Деревопащих, не зачеплених порчею, які стоять на її висотах. Ці прості поселення — віддалені табори, пов'язані з великими лігвами фурболгів в Урсолані й Твердині Деревопащих на півночі. Високо на кручах просто над цією місциною стоїть Вежа Ксилема — дивовижне пристановище, де Архімаг Ксилем і жменька його учнів займаються тайними студіями в тихій самоті, далеко від решти неспокійного узбережжя."}},faq={{q="Чому ця місцина зветься Ведмежа Голова?",a="Край названо на честь сіл фурболгів-Деревопащих, розкиданих його пагорбами. Ведмежий народ тримає тут табори, що правлять за південні застави їхніх твердинь на півночі Калімдору.",al={"походження назви ведмежа голова","чому ведмежа голова","значення ведмежої голови"}},{q="Які фурболги живуть у Ведмежій Голові?",a="Тут живе плем'я Деревопащих. На відміну від багатьох інших племен фурболгів Калімдору, що стали жертвами демонічної скверни, Деревопащі здебільшого встояли перед нею й підтримують зв'язок зі своїми головними поселеннями в Урсолані й Твердині Деревопащих.",al={"фурболги ведмежої голови","тімбермоу ведмежа голова","яке плем'я фурболгів тут"}},{q="Що за вежа на скелях над Ведмежою Головою?",a="Цей шпиль на кручі належить Архімагові Ксилему — дивакуватому чарівникові з людей, що покинув Даларан і подався до Азшари, щоб навчатися на самоті разом із кількома учнями й соратниками з високих ельфів.",al={"вежа над ведмежою головою","хто живе у вежі","вежа ксилем"}}},fp="11,312,36.510.0,36.215.0,35.262.0,50.219.0"}
P.entries["subzone:beezil-s-wreck"] = {n="Уламки Бізіла",s="Уламки Бізіла — місце катастрофи нещасливого гоблінського цепеліна глибоко в трясовинах Багна Пилоброду. Розбите судно лежить на схід від Ферми Табети, і його вантаж — розкидані припаси й вибухові інженерні деталі — приваблює збирачів поживи.",h="Уламки Бізіла — місце катастрофи нещасливого гоблінського цепеліна глибоко в трясовинах Багна Пилоброду.",kw={"уламки бізіла","багно пилоброду","цепелін","гобліни","сіфорій","ферма табети","інженерія"},ang={["profession:Engineering"]="Покручені уламки гоблінського цепеліна ховають нестабільні механічні деталі — зокрема сіфорієві прискорювачі, яких жадав би будь-який майстер.",["race:Gnome"]="Огляд димних решток гоблінського суперника в повітроплаванні — моторошне нагадування про небезпеки, властиві будь-якій негномській повітряній конструкції."},sec={{t="Катастрофічне приземлення",b="Захований у вологій багнюці на схід від Ферми Табети, лежить розтрощений кістяк гоблінського цепеліна, відомий як Уламки Бізіла. Судно везло вантаж на південь через Калімдор, коли катастрофічно впало в болото. Уламки досі тліють серед сплутаного очерету, а ексцентричний капітан Бізіл, схоже, зник із багна, лишивши розкидані ящики й механізми, що цокають, повільно гнити в солоній воді."},{t="Пожива в багнюці",b="Попри суворе довкілля, місце катастрофи лишається ласим шматком для заповзятливих шукачів. Повітряне судно везло вибухонебезпечний вантаж — зокрема сіфорієві прискорювачі й важкі ящики, що вціліли після удару. Збирачі поживи, які наважуються пробиратися повз навколишніх звірів, нерідко ризикують життям, щоб забрати рештки загубленого вантажу, перш ніж їдка болотяна вода остаточно його зіпсує."}},faq={{q="Що таке Уламки Бізіла?",a="Уламки Бізіла — місце падіння гоблінського цепеліна в глибині Багна Пилоброду, просто на схід від Ферми Табети. Повітряний корабель упав, коли перевозив вантаж через болото.",al={"уламки бізіла","розбитий цепелін пилових боліт","що це за уламки"}},{q="Де пілот, Бізіл?",a="Пілота Бізіла ніде біля місця падіння не видно. Чи він утік у підступні нетрі, чи взагалі покинув болото — для тих, хто обшукує корпус, лишається загадкою.",al={"де бізіл","хто такий бізіл","місце бізіла"}},{q="Який цінний вантаж віз цепелін?",a="Цепелін був навантажений товарами й нестійкою гоблінською технікою, зокрема сіфорієвими прискорювачами. Ці цінні інженерні деталі роблять місце падіння частою ціллю шукачів пригод і мародерів.",al={"що було в цепеліні","підсилювачі сіфорію","вантаж уламків"}}},fp="14,263,20.440.0,19.403.0,23.186.0,27.189.0,46.203.0"}
P.entries["subzone:beggar-s-haunt"] = {n="Притон Жебрака",s="Притон Жебрака — покинута розвідувальна вежа Стормвінда на схилі пагорба на північному сході Сутінколісся, біля гірської дороги до Перевалу Мертвого Вітру. Колись її звели, щоб стерегти східні кордони королівства, а тепер вона стала заставою лазутчиків-Відступників глибоко на землях Альянсу.",h="Притон Жебрака — покинута розвідувальна вежа Стормвінда на схилі пагорба на північному сході Сутінколісся...",kw={"притон жебрака","вежа","відступники","аптекарське товариство","сутінколісся","лицарська улоговина"},ang={["faction:Alliance"]="Агенти Відступників у старій розвідувальній вежі Стормвінда, просто біля головного шляху, — тривожна ознака того, що Орда проникла під самий поріг Даркшира.",["race:Undead"]="Для агентів Відступників ця відлюдна застава — рідкісний і небезпечний плацдарм глибоко в людських землях півдня."},sec={{t="Вартова вежа в тіні",b="Притон Жебрака, що височіє над туманними пагорбами на схід від Маєтку Містмантл, колись був діяльним спостережним постом, де Вартові Стормвінда стерегли східні підступи до королівства. Коли Велике Селище поринув у морок нинішнього Сутінколісся, а королівські патрулі відійшли до Даркшира, кам'яну вежу покинули на поталу негоді. Нині її вигідне розташування служить куди зловіснішій меті: агенти Відступників, серед них члени Королівського Аптекарського Товариства та скрадачі смерті, проводять у зруйнованій твердині досліди й стежать за краєм просто під носом в Альянсу."},{t="Лицарська Улоговина й забуті мерці",b="За вежею крута звивиста стежка спускається до відлюдного ставка з водоспадом, відомого як Лицарська Улоговина. Тут лежить безіменна могила, яку обступають дві зловісні кам'яні статуї в каптурах, схожі на вартових обабіч Темного Порталу. Поховання неподалік, серед них могила Невідомого Солдата, свідчать про забуті сутички на цьому прикордонні задовго до того, як Відступники оселилися у вежі."}},faq={{q="Чому в Притоні Жебрака Відступники?",a="Агенти з Андерсіті, зокрема Аптекар Фостін із Королівського Аптекарського Товариства й Скрадач Смерті Зраедус, захопили покинуту вартову вежу. Звідси вони можуть стежити за пересуваннями Альянсу й нишком проводити досліди далеко на півдні.",al={"хто в притоні жебрака","чому тут орда","нежить у притоні жебрака"}},{q="Чи цю вежу збудували Відступники?",a="Ні. Вежу збудувало королівство Стормвінд як розвідувальну заставу. Коли місцева оборона ослабла, а край перетворився на Сутінколісся, Варта Стормвінда покинула її, і вежа стояла порожньою, доки її не захопили розвідники Відступників.",al={"хто збудував притон жебрака","історія притону жебрака","чи це вежа альянсу"}},{q="Що за дивна могила за вежею?",a="Стежкою позаду притону лежить Лицарська Лощина — відлюдне озерце під водоспадом із безіменною могилою, яку обрамлюють статуї вартових у каптурах, точнісінько як пам'ятники обабіч Темного Порталу.",al={"могила за вежею","статуї лицарського яру","статуї темного порталу сутінковий ліс"}},{q="Чи ворожий Притон Жебрака до мандрівників Альянсу?",a="Так. Відступники у вежі — досвідчені агенти, що вбивають кожного шукача пригод з Альянсу, який підійде надто близько до їхнього укріплення на схилі.",al={"чи вони нападуть","стражі притону жебрака","чи притон жебрака безпечний"}}},fp="14,297,27.594.0,38.408.0,41.251.0,48.233.0,43.202.0,48.155.0"}
P.entries["subzone:beren-s-peril"] = {n="Лихо Берена",s="Лихо Берена — відлюдна гірська печера серед скелястих пагорбів на південний захід від Амбермілла в Срібноліссі. Це вкорінений редут мерців-ренегатів, вірних Погибелі, що служать некромантові Тулу Рейвенклову й плетуть змову проти сусідніх Відступників.",h="Лихо Берена — відлюдна гірська печера серед скелястих пагорбів на південний захід від Амбермілла в...",kw={"лихо берена","тул рейвенклов","погибель","печера","гробниця","срібнолісся"},ang={["faction:Horde"]="Щоб убезпечити суворі стежки Срібнолісся, треба вичистити гнізда мерців-ренегатів, перш ніж вони переріжуть шляхи постачання між Гробницею й південними землями.",["race:Undead"]="Посіпаки Рейвенклова з Лиха Берена — гірке нагадування про те, як міцно досі тримається Погибель: вони загрожують безпеці Гробниці, і прибічники Сильвани мають знищити їх швидко й нещадно."},sec={{t="Прихована загроза в пагорбах",b="Лихо Берена, що сховалося високо в скелях на південний захід від Амбермілла, — це затінена печера й звивиста гірська стежка, приховані від головної дороги. Після спустошень Третьої війни мерці Погибелі, що не підкорилися Відступникам, під командуванням некроманта-ренегата Тула Рейвенклова укріпили цей анклав. Замість схилитися перед Темною Леді чи відступити на північ, слуги Рейвенклова — регенти, вартові й наймити — таємно збиралися тут, щоб підготувати напад на базу Відступників у Гробниці. Розвідники Відступників викрили їх, і тиха скеля перетворилася на поле бою для загонів Орди, посланих знищити загрозу, перш ніж напад відбудеться."}},faq={{q="Що таке Лихо Берена?",a="Це печера й гірський перехід довкола неї на південний захід від Амбермілла в Срібноліссі, між центральним шляхом і бічною дорогою до Амбермілла.",al={"лихо берена","де лихо берена","печера лиха берена"}},{q="Хто контролює Лихо Берена?",a="Печеру захопила нежить Погибелі, віддана некромантові Тулу Рейвенклову, — зокрема вартові, трудяги й регенти Рейвенклова.",al={"хто живе в лиху берена","вороги лиха берена","нежить рейвенклов"}},{q="Чому Відступникам важливе це місце?",a="Розвідники Відступників з'ясували, що нежить, яка засіла в Лиху Берена, збирає війська й озброюється для неминучого нападу на Гробницю, тож Жрець Тіні Аллістер наказав завдати випереджальних ударів.",al={"лихо берена елістер","чому нападати на лихо берена","загроза гробниці"}},{q="Хто такий Тул Рейвенклов?",a="Тул Рейвенклов — могутній некромант у Срібноліссі, що тримав під владою осередки безмозких і ворожих прислужників Погибелі й залякував край із таких місць, як Лихо Берена й Фортеця Фенріс.",al={"тул рейвенклов","тул срібнолісся"}}},fp="13,256,28.691.0,22.161.0,27.134.0,45.222.0,23.218.0"}
P.entries["subzone:bitter-reaches"] = {n="Гіркі Обшири",s="Гіркі Обшири — скелясті, обвітрені дикі землі на північному сході Азшари. Цивілізація їх майже не торкнулася, а суворими кручами никають хижі звірі й величезні гірські велетні.",h="Гіркі Обшири — скелясті, обвітрені дикі землі на північному сході Азшари.",kw={"гіркі обшири","азшара","гірський срібношавлій","химери","гіпогрифи","гірські велетні","травництво"},ang={["class:Hunter"]="Гнізда на кручах Гірких Обширів — чудові мисливські угіддя, що аж кишать дикими гіпогрифами й агресивними химерами, споконвічними мешканцями цього прадавнього узбережжя.",["profession:Herbalism"]="Обвітрені висоти Гірких Обширів — одне з небагатьох місць в Азшарі, де росте цінний Гірський Срібношавлій, але щоб його зібрати, вам доведеться мати справу з химерами й велетнями."},sec={{t="Небезпечний прибережний край",b="Гіркі Обшири, що займають північно-східні кручі Азшари, лишаються суворою й неприборканою смугою кам'янистої землі над Великим Морем. На висотах гніздяться зграї диких гіпогрифів і двоголових химер, а холодною землею повзуть їдкі слизняки. На високих північних хребтах колосальні гірські велетні захопили схили, витіснили менших істот і перетворили засніжені підступи на смертельну пастку для кожного самотнього мандрівника."},{t="Рослини скель",b="Попри суворі вітри й хижих звірів, скелястий край живить рідкісні гірські рослини. Поодинокі кущики Гірського Срібношавлію чіпляються за високі кам'яні стіни й вітряні уступи, тож небезпечна місцевість часом варта мандрів для відважних травників, які зуміють уникнути велетнів і ревнивих до своїх земель химер."}},faq={{q="Де Гіркі Обшири?",a="Гіркі Обшири займають північно-східну частину Азшари — високі прибережні кручі й хребти над затокою.",al={"місце гірких обширів","де гіркі обшири","гіркі обшири азшара"}},{q="Які істоти тут живуть?",a="Тут водяться гіпогрифи, що ревно стережуть свої землі, двоголові химери й слизуни. А північною межею блукають височенні гірські велетні.",al={"мобі гірких обширів","що живе в гірких обширах","чудовиська гірких обширів"}},{q="Чому тут гірські велетні?",a="Прадавні гірські велетні живуть на високих північних вершинах і околицях Азшари: вони вибороли собі власні володіння й вигнали звідти більшість місцевих звірів.",al={"гірські велетні азшари","чому велетні в гірких обширах"}},{q="Які цінні ресурси ростуть у Гірких Обширах?",a="На скелястих виступах і хребтах подекуди трапляються рідкісні високогірні трави, як-от Гірський Срібношавлій.",al={"трави гірких обширів","збір у гірких обширах"}}},fp="14,191,28.480.0,18.331.0,29.120.0,25.132.0,35.178.0,51.124.0"}
P.entries["subzone:black-channel-marsh"] = {n="Багно Чорного Каналу",s="Багно Чорного Каналу — каламутна трясовина на південному заході Багнокраю, обабіч головної дороги до Гавані Менетіл. Мокрі землі, що кишать агресивними рапторами, — безпосередня загроза для необачних мандрівників і гінців із припасами, що перетинають прибережні низини.",h="Багно Чорного Каналу — каламутна трясовина на південному заході Багнокраю, обабіч головної дороги до Гавані...",kw={"багно чорного каналу","раптори","гавань менетіл","дорога","болото","багнокрай"},ang={["class:Hunter"]="Болото — небезпечний полігон для мисливців, що прагнуть приборкати чи вистежити лютих рапторів Багнокраю просто біля головної дороги.",["faction:Alliance"]="Цей коридор — життєво важлива артерія, що з'єднує порт Гавані Менетіл з рештою Каз Модану, тож набіги рапторів — постійний головний біль для мандрівників."},sec={{t="Небезпека на дорозі до Менетіла",b="Багно Чорного Каналу, що простягається болотистими низинами на південний захід від головного шляху, має сумну славу серед погоничів караванів і гінців, що прямують до Гавані Менетіл. Висока дорога створює ілюзію безпеки, але в застояних протоках і густому очереті живуть зграї рапторів, ревних до своєї території. Голодні звірі раз у раз вибігають просто на дорогу й нападають на новобранців і втомлених подорожніх, що відійдуть від протоптаної стежки бодай на крок-другий."}},faq={{q="Де Багно Чорного Каналу?",a="Багно Чорного Каналу займає південно-західний куток Багнокраю. Воно межує з південним боком великої дороги, що веде до Гавані Менетіл.",al={"де багно чорного каналу","місце багна чорного каналу","чорний канал мокрі землі"}},{q="Чому це багно вважають небезпечним для мандрівників?",a="У багні аж кишить лігвами рапторів. Ці хижаки полюють на околицях болота й раз у раз підкрадаються аж до узбіччя дороги, заскочуючи зненацька необачних мандрівників і недосвідчених шукачів пригод.",al={"чому небезпечно","загрози багна чорного каналу","раптори на дорозі"}},{q="Хто найчастіше тут подорожує?",a="Дорогою повз багно часто ходять гінці Альянсу, дворфійські купці й мандрівники між Айронфорджем і доками Гавані Менетіл.",al={"хто тут подорожує","мандрівники"}}},fp="19,280,26.449.0,37.149.0,53.225.0,36.177.0"}
P.entries["subzone:blackchar-cave"] = {n="Печера Чорної Гарі",s="Печера Чорної Гарі — таємнича замурована печера серед південно-західних скель Палючої Ущелини, неподалік підніжжя Гори Блекрок. Її вхід завалений непрохідним камінням і уламками скель.",h="Печера Чорної Гарі — таємнича замурована печера серед південно-західних скель Палючої Ущелини, неподалік...",kw={"печера чорної гарі","палюча ущелина","гора блекрок","печера","завал"},sec={{t="Замурований поріг",b="Печера Чорної Гарі, захована серед розпечених скель на підступах до Гори Блекрок, постає суцільною кам'яною стіною там, де колись, певно, був вхід до глибокої печери. Важкі уламки й обпалений шлак наглухо закривають отвір і не дають нікому дослідити тунелі, що, можливо, тягнуться далі в коріння гори. Пустельна місцевість довкола випалена попелом і магмою й мало чим може втішити мандрівників."}},faq={{q="Чи можна зайти в Печеру Чорної Гарі?",a="Ні. Вхід до Печери Чорної Гарі цілком завалений обваленим камінням, попелом і уламками. Усередині немає відкритого простору, який можна було б дослідити.",al={"чи відкрита печера чорної гарі","зайти в печеру чорної гарі","всередині печери чорної гарі"}},{q="Де Печера Чорної Гарі?",a="Вона в південно-західному куті Палючої Ущелини, серед скелястого передгір'я біля проходу до Гори Блекрок.",al={"місце печери чорної гарі","де печера чорної гарі"}}},fp="14,199,18.416.0,33.139.0,32.137.0"}
P.entries["subzone:blackfathom-deeps"] = {n="Чорноглибинні Печери",s="Чорноглибинні Печери — затоплені підземні руїни храму під Зорамським Узмор'ям на північно-західному узбережжі Ашенвалю. Колись це був величний дім молитви, присвячений богині місяця Елуні, а тепер його затоплені зали захопили наги, сатири й зловісний культ Молота Присмерку.",h="Чорноглибинні Печери — затоплені підземні руїни храму під Зорамським Узмор'ям на північно-західному узбережжі...",kw={"чорноглибинні печери","латар'лазал","аку'май","молот присмерку","наги","келріс","підземелля"},ang={["faction:Horde"]="Орда має з цими глибинами кровні рахунки: давніша розвідка в руїнах закінчилася катастрофою, і лише розвідник Темного Спису Геказі та Рокган ледве врятувалися.",["race:NightElf"]="Осквернення Латар'Лазала — глибока кривда для калдореїв, які оплакують те, як сектанти Порожнечі й наги збезчестили колись священне святилище Елуни та його місячний колодязь."},sec={{t="Від храму Елуни до найтемнішої безодні",b="До того як Великий Розкол десять тисяч років тому розтрощив прадавній Калімдор, цей комплекс звався Латар'Лазал — «Престол Неба». Присвячений богині Елуні, він мав інкрустовані самоцвітами мости, священні озера й місячний колодязь, збудовані під особистим наглядом королеви Азшари. Коли Колодязь Вічності обвалився, величне святилище пішло під океанські хвилі й вважалося назавжди втраченим. За тисячоліття берегова лінія відступила, надра зсунулися, і рештки храму опинилися частково затопленими під скелями Ашенвалю."},{t="Піднесення Аку'мая",b="Останніми роками до забутого місячного колодязя храму дісталася підступна гнилизна: порча Древніх Богів просочилася вгору з глибин землі. Ваблений темними снами й шепотом, культ Молота Присмерку облаштував у затоплених руїнах твердиню під проводом сутінкового володаря Келріса. Сектанти доглядають і плекають Аку'мая Пожирача — жахливу триголову гідру, улюбленицю їхніх прадавніх покровителів. Разом із нагами, що прибули сюди на чолі з леді Саревесс, і сатирами, які никають руїнами, культ звершує мерзенні жертовні обряди, сподіваючись випустити свого звіра у світ на поверхні."}},faq={{q="Для чого спершу збудували Чорноглибинні Печери?",a="Спершу це був ельфійський храм Латар'Лазал, присвячений місячній богині Елуні. Тут були кришталево чисті басейни, оздоблені самоцвітами споруди й священний місячний колодязь під опікою давніх Високородних, — доки під час Розколу храм не пішов під воду.",al={"історія чорноглибинних печер","чим були чорноглибинні печери","латар'лазал"}},{q="Чому тут культ Молота Присмерку?",a="Ведений темним шепотом і жахіттями, Молот Присмерку прийшов сюди поклонятися Аку'маю — первісній гідрі, улюблениці Древніх Богів — і годувати її. Під проводом сутінкового володаря Келріса культ кидає звірові полонених і невинних, щоб пришвидшити його пробудження.",al={"чому сектанти в чорноглибинних печерах","молот присмерку чорноглибинні","мета келріса"}},{q="Де вхід?",a="Вхід захований у печерних руїнах на Зорамському Узмор'ї, на крайньому північно-західному узбережжі Ашенвалю. Шукачам пригод доведеться пробиратися затопленими залами й ворожими заставами наг, щоб дістатися порталу храму.",al={"де вхід","місце чорноглибинних печер","як увійти в чорноглибинні печери"}},{q="Хто такий Ґаму-Ра?",a="Ґаму-Ра був одним з останніх мирних прадавніх створінь, що жили в затонулому храмі. Захопивши руїни, культ Молота Присмерку впіймав велетенську черепаху й роками мучив її, доки не довів до шаленства й не зробив лютим сторожовим звіром.",al={"гігантська черепаха бос","переказ про ґаму-ра","черепаха чорноглибинних печер"}}},fp="17,290,36.532.0,19.572.1,48.260.0,39.242.0,30.228.0,17.242.0"}
P.entries["subzone:blackrock-mountain"] = {n="Гора Блекрок",s="Гора Блекрок — велетенський діючий вулкан, що височіє між Палаючими Степами й Палючою Ущелиною. Вона постала внаслідок катастрофічного виклику Рагнароса, Володаря вогню, і в її порожнистих надрах ховаються прадавня дворфська кладка, ворожі армії й тліючі жахи.",h="Гора Блекрок — велетенський діючий вулкан, що височіє між Палаючими Степами й Палючою Ущелиною.",kw={"гора блекрок","рагнарос","темне залізо","тауріссан","війна трьох молотів","шпиль блекрок","вулкан"},ang={["faction:Horde"]="Для нової Орди Шпиль Блекрок — символ колишнього поневолення й кровопролиття під владою Думхаммера, а нині його утримують непокірні орки, що зреклися проводу Тралла.",["race:Dwarf"]="Гора — найтемніший розділ дворфської історії: трагічне безумство клану Темного Заліза, що коштувало йому свободи й залишило шрами на обличчі Східних Королівств."},sec={{t="Народжена катастрофою",b="Гори Блекрок не існувало аж до кульмінації Війни Трьох Молотів два з половиною століття тому. Перед загрозою знищення об'єднаними арміями Айронфорджа й клану Вайлдгаммерів тан-чародій Тауріссан шукав зброю в надрах землі. Його безрозсудне закляття зруйнувало межі між світами й викликало в Азерот Рагнароса, Володаря вогню. Наслідки були апокаліптичні: катастрофа розірвала гірський кряж Редріджу, вирвала Палючу Ущелину й Палаючі Степи та виштовхнула в небо колосальний вулкан. Тауріссан загинув у вибуху, а вцілілий клан Темного Заліза опинився у вічному рабстві Володаря вогню й висік свою столицю, Місто Тінькузні, глибоко в корінні гори."},{t="Цитадель попелу й крові",b="Під час Першої й Другої воєн гора набула нового похмурого значення. Під проводом Чо'ґалла Рада Тіней захопила верхню фортецю Шпиля Блекрок за мовчазної згоди посіпак Рагнароса. Після розграбування Стормвінда Оргрім Думхаммер розправився з радою й зробив шпиль столицею-фортецею Орди, вбачаючи у спільній назві зі своїм кланом Блекрок доленосний знак. Нині гора лишається жорстоким полем бою: дворфи Темного Заліза та їхній стихійний господар тримають вогняні глибини, а непокірні орки Блекрок, дракониди та їхні темні господарі займають верхні шпилі."}},faq={{q="Як з'явилася Гора Блекрок?",a="Вона з'явилася приблизно 250 років тому, під час Війни Трьох Молотів. Прагнучи будь-що перемогти суперницькі дворфійські клани, Імператор Тауріссан спробував вивільнити глибинну підземну енергію й ненароком закликав Рагнароса, Володаря вогню, — і руйнівний вибух звів вулкан.",al={"походження гори блекрок","хто створив гору блекрок","як утворився вулкан"}},{q="Чому вона зветься Гора Блекрок?",a="Вулкан назвали Горою Блекрок і Шпилем Блекрок за кілька століть до того, як орки ступили на Азерот. Коли прибув Оргрім Думхаммер, він побачив у тому, що назва збігається з назвою клану Блекрок, добрий знак і зробив гору своєю головною базою.",al={"походження назви блекрок","названо на честь клану блекрок"}},{q="Хто нині контролює Гору Блекрок?",a="Гору розділяє жорстока боротьба. Поневолені дворфи Темного Заліза тримають підземні зали Міста Тінькузні на службі в Рагнароса, а рештки клану Блекрок і чорні драконороди панують у верхній цитаделі — Шпилі Блекрок.",al={"хто живе в блекроку","хто править горою блекрок"}},{q="Які краї сполучає Гора Блекрок?",a="Внутрішні проходи й ланцюги Гори Блекрок — прямий шлях між Палючою Ущелиною на півночі й Палаючими Степами на півдні.",al={"як пройти крізь блекрок","зв'язки гори блекрок"}}},fp="18,264,20.717.0,24.633.0,35.285.0,35.268.0,42.259.0,46.154.0"}
P.entries["subzone:blackrock-pass"] = {n="Перевал Блекрок",s="Перевал Блекрок — гірський прохід, що сполучає північні кручі Гір Редріджу з посушливими пустирями Палаючих Степів. Пролягаючи під важкою залізною брамою, він позначає різкий рубіж між мирним людським краєм і небезпечними бойовищами дворфів Темного Заліза та орків Блекрок. Для кожного втомленого мандрівника, що прямує на північ пішки, це суворий і небезпечний кордон.",h="Перевал Блекрок — гірський прохід, що сполучає північні кручі Гір Редріджу з посушливими пустирями Палаючих...",kw={"перевал блекрок","редрідж","палаючі степи","лейкшир","брама","орки блекрок"},ang={["faction:Alliance"]="Для захисників Редріджу й Королівства Стормвінд Перевал Блекрок — вічне джерело страху, адже він відкриває оркам Блекрок прямий шлях на південь, у людські землі."},sec={{t="Випалений поріг",b="Перевал Блекрок, прорубаний у зубчастому хребті гір, — сухопутний шлях між Горами Редріджу й Палаючими Степами. На скелястій межі стоїть міцна залізна брама, що відділяє ідилічні ліси й озера південних долин від вулканічної руїни за нею. Переступивши цю межу, мандрівник лишає позаду мирні землі, які захищає знесилене ополчення Лейкширу, і опиняється на відкритому пустирі, де никають вогняні елементалі, дракониди й ворожі орчі ватаги. Мало хто перетинає перевал пішки, хіба що прямує до самої Гори Блекрок."}},faq={{q="Куди веде Перевал Блекрок?",a="Перевал Блекрок з'єднує північну межу Гір Редріджу просто з південними околицями Палаючих Степів. Це одна з прямих сухопутних брам, що пов'язують південні землі Альянсу з передгір'ям Гори Блекрок.",al={"куди веде перевал блекрок","призначення перевалу блекрок","шлях з реджриджа до палаючих степів"}},{q="Чи безпечно мандрівникам із Лейкшира переходити перевал?",a="Ні. Землі одразу на північ від перевалу куди смертоносніші за довколишні пагорби Редріджу. Палаючі Степи кишать лютими орками Блекрок, велетенськими вогняними елементалями й чорними дракончиками, тож для недосвідчених шукачів пригод і простих подорожніх тут надзвичайно небезпечно.",al={"чи можна пройти перевал блекрок","чи небезпечний перевал блекрок","вимога рівня перевалу блекрок"}},{q="Хто контролює Перевал Блекрок?",a="Ні Стормвінд, ні Орда повністю не контролюють перевал. Це спірне, слабко укріплене вузьке місце, обабіч якого насідають орки Блекрок і дикі звірі, і варта Редріджу внизу стежить за ним із глибоким страхом.",al={"хто володіє перевалом блекрок","стражі перевалу блекрок","контроль фракцій перевалу блекрок"}}},fp="14,409,20.586.0,31.250.0,58.290.0,28.240.0"}
P.entries["subzone:blackrock-stronghold"] = {n="Твердиня Блекрок",s="Твердиня Блекрок — добре укріплений табір, вирубаний у скелях на півночі Палаючих Степів, просто біля входу до Гори Блекрок. Це великий польовий гарнізон орків Блекрок та їхніх союзників під прапором Темної Орди.",h="Твердиня Блекрок — добре укріплений табір, вирубаний у скелях на півночі Палаючих Степів, просто біля входу...",kw={"твердиня блекрок","темна орда","орки блекрок","палаючі степи","ренд блекгенд","гарнізон"},ang={["faction:Alliance"]="Твердиня — похмуре нагадування про Другу війну: вона стоїть на відстані одного удару від північних кордонів Королівства Стормвінд.",["faction:Horde"]="Для Орди Тралла клан Блекрок — ганебна спадщина Старої Орди: кровожерні, зіпсовані рештки, що зрікаються честі й миру."},sec={{t="Гарнізон Темної Орди",b="Твердиня, що розкинулася на випалених передгір'ях під Горою Блекрок, — головна наземна база клану Блекрок у Палаючих Степах. На відміну від Орди Тралла, ці орки чіпляються за свою войовничу спадщину й служать Рендові Блекгенду та драконородам, що причаїлися вгорі, у шпилі."},{t="Передова Шпиля Блекрок",b="Твердиня — водночас зовнішня оборона й плацдарм для нападів на Гори Редріджу та сусідні людські землі. Фортеця невпинно стежить за південними підступами до гори й кидає виклик кожному, хто наважиться перетнути спустошені пустирі."}},faq={{q="Що таке Твердиня Блекрок?",a="Це укріплена військова база на півночі Палаючих Степів, під самою Горою Блекрок, що правує за зовнішній гарнізон клану орків Блекрок.",al={"що це за місце","твердиня блекрок палаючі степи","що таке твердиня блекрок"}},{q="Чи ці орки дружні до Орди Тралла?",a="Ні. Орки Твердині Блекрок належать до Темної Орди, яку очолює Ренд Блекгенд. Вони не визнають проводу Тралла й ворожі і до Альянсу, і до нової Орди.",al={"чи це орда","чи орки блекрок з орди","дружні до орди"}}},fp="20,275,26.299.0,29.280.0,29.166.0,45.173.0"}
P.entries["subzone:blackthorn-ridge"] = {n="Кряж Чорного Терну",s="Кряж Чорного Терну — порізана, задушена терновиками долина в південній частині Пусток, просто на північ від Рейзорфен Краула. Тут кишать агресивні шипогриви Гостромани, що стережуть свої колючі поселення. Високо на кряжі стоїть табір орчихи-шаманки Брайн, яка оберігає надзвичайно чисте озерце гірської води.",h="Кряж Чорного Терну — порізана, задушена терновиками долина в південній частині Пусток, просто на північ від...",kw={"кряж чорного терну","гостромани","шипогриви","брайн","рейзорфен краул","пустки"},ang={["class:Shaman"]="Кряж — важливе місце паломництва для молодих шаманів Орди, які шукають Брайн, щоб пізнати чистоту природної стихії води серед суворих сухих рівнин.",["faction:Horde"]="Гостромани, що живуть на кряжі, загрожують шляхам постачання Орди через південні Пустки до Тисячі Голок, тож каравани мусять бути постійно напоготові."},sec={{t="Колючий редут",b="Кряж Чорного Терну, що лежить поблизу велетенських наростів Рейзорфен Краула, заріс густими хащами величезних гострих колючок. Шипогриви Гостромани вважають ці землі прадавньою територією і використовують природні загорожі, щоб влаштовувати засідки на чужинців і готувати вилазки в південні Пустки. Попри постійну небезпеку, мандрівники шукають кряж заради відлюдної орчихи-шаманки Брайн: її табір стоїть над джерелом, відомим на весь Калімдор дивовижною прозорістю й духовною чистотою."}},faq={{q="Де Кряж Чорного Терну?",a="Кряж Чорного Терну — на крайньому півдні Пусток, трохи на північ від велетенських колючих заростей довкола Рейзорфен Краулу й на південь від Табору Тауражо.",al={"місце кряжа чорного терну","де чорний терн","як знайти кряж чорного терну"}},{q="Хто живе на Кряжі Чорного Терну?",a="Дно долини кишить ворожими шипогривами Гостроманами. А над їхніми хащами, на високому скелястому виступі, живе Брайн — орк-шаман, що пильнує гірське джерело поблизу.",al={"хто на кряжі чорного терну","мешканці кряжа чорного терну","вепролюди чорного терну"}},{q="Чим особливе озерце під табором Брайна?",a="Хоча довкола посушливі рівнини й колюча скверна шипогривячих хащів, приховане озерце під кряжем має надзвичайно чисту, прозору воду, тож це священне природне осердя для шаманських обрядів.",al={"озерце брайна","вода чорного терну","джерело кряжа чорного терну"}}},fp="16,345,22.491.0,26.152.0,30.187.0,45.233.0"}
P.entries["subzone:blackwolf-river"] = {n="Річка Чорного Вовка",s="Річка Чорного Вовка витікає з Озера Скельної Заводі й збігає крізь Кручу Вітрорізу в Горах Кам'яного Кігтя. Колись це був чистий гірський потік, а тепер його води геть отруєні хижацькими вирубками та промисловими роботами Венчурної Компанії.",h="Річка Чорного Вовка витікає з Озера Скельної Заводі й збігає крізь Кручу Вітрорізу в Горах Кам'яного Кігтя.",kw={"річка","гори кам'яного кігтя","венчурна компанія","гобліни","забруднення","лісоруби"},ang={["class:Druid"]="Осквернення Річки Чорного Вовка гоблінськими лісорубами — тяжка образа для Кола Кенарія і всіх, хто шанує дикі води Калімдору.",["race:Tauren"]="Понівечена земля й каламутні води, зіпсовані зайдами, що женуться за наживою, лише зміцнюють рішучість тауренів очистити Гори Кам'яного Кігтя від цієї безоглядної промислової напасті."},sec={{t="Промислові стоки",b="Спускаючись з Озера Скельної Заводі, Річка Чорного Вовка перетинає улоговину Кручі Вітрорізу. Вона мала б бути незайманою гірською притокою, але натомість узяла на себе весь тягар неприборканого гоблінського підприємництва. Поки Венчурна Компанія розчищає навколишні ліси важкими машинами й циркулярними пилами, мул, мастило та відходи лісозаготівлі невпинно стікають у течію. Сплюндрована річка — яскравий приклад торговельного грабунку, що загрожує дикій природі Кам'яного Кігтя."}},faq={{q="Звідки витікає й куди тече Річка Чорного Вовка?",a="Річка витікає з Озера Скельної Заводі у верхів'ях гір і в'ється вирубаною улоговиною Кручі Вітрорізу.",al={"джерело річки чорного вовка","де річка чорного вовка","місце річки чорного вовка"}},{q="Чому вода в річці забруднена?",a="Венчурна Компанія веде на Кручі Вітрорізу масштабну вирубку лісу за допомогою механічних лісозаготівельних машин. Стоки з її парових машин, відходи й наслідки суцільної вирубки стікають просто в річку.",al={"чому річка брудна","забруднення чорного вовка","забруднення венчурної компанії"}},{q="Хто нині господарює вздовж річки?",a="На березі панує Венчурна Компанія: вона використовує навколишню долину для заготівлі деревини й роботи важких машин, попри опір місцевих звірів і тубільних мешканців.",al={"хто контролює річку чорного вовка","хто біля річки","вороги біля річки чорного вовка"}}},fp="15,259,17.458.0,46.133.0,32.203.0,43.194.0"}
P.entries["subzone:blackwood-den"] = {n="Лігво Чорнолісся",s="Лігво Чорнолісся — осквернене стійбище фурболгів на півдні Темного Узбережжя, біля кордону з Ашенвалем. Колись мирна оселя, печера й табори довкола неї поринули в божевілля разом з усім племенем Чорнолісся. Самотній розвідник нічних ельфів на ім'я Волкор опинився в пастці в печері й чекає допомоги з Обердайна.",h="Лігво Чорнолісся — осквернене стійбище фурболгів на півдні Темного Узбережжя, біля кордону з Ашенвалем.",kw={"лігво чорнолісся","фурболги","волкор","скверна","печера","темне узбережжя"},ang={["class:Druid"]="Друїди оплакують занепад фурболгів, що колись були вірними охоронцями дикої природи, і бачать у божевіллі Лігва Чорнолісся ще одну болючу ознаку отруєної природи Калімдору.",["race:NightElf"]="Для нічних ельфів Обердайна втрата племені Чорнолісся через скверну — трагічна подія, а порятунок Волкора з його лап — нагальний обов'язок, щоб уберегти своїх на південній дорозі."},sec={{t="Осквернена твердиня",b="Лігво Чорнолісся, що лежить біля південного кордону, де Темне Узбережжя сходиться з Ашенвалем, — це звивиста мережа грубих таборів і кам'яниста печера. Фурболги Чорнолісся, що живуть тут, піддалися скверні, яка охопила край, і стали люто ворожими до чужинців. Глибоко в печері нічний ельф Волкор досі в облозі агресивного племені й у смертельній небезпеці, і йому конче потрібна допомога розвідників і мандрівників, посланих з Обердайна."}},faq={{q="Що таке Лігво Чорнолісся?",a="Лігво Чорнолісся — поселення фурболгів і печерний комплекс на крайньому півдні Темного Узбережжя, біля межі з Ашенвалем. Це база зіпсованого скверною племені фурболгів Чорнолісся.",al={"що таке лігво чорнолісся","фортеця чорнолісся","де лігво чорнолісся"}},{q="Хто в печері в Лігві Чорнолісся?",a="У печері — Волкор, нічний ельф, що опинився в пастці у ворожому тилу. Мандрівники, які його знайдуть, мають разом із союзниками в Обердайні влаштувати втечу й безпечно вивести його з лігва.",al={"хто в пастці в печері","хто такий волкор","ельф у лігві чорнолісся"}},{q="Чому тутешні фурболги ворожі?",a="Фурболги Чорнолісся стали жертвами темної скверни, що поширилася Темним Узбережжям і Калімдором після Третьої війни. Ця біда довела їх до несамовитого шалу, і вони нападають на будь-якого чужинця, щойно його побачать.",al={"чому фурболги чорнолісся агресивні","чи фурболги чорнолісся злі","осквернені фурболги темного узбережжя"}}},fp="13,344,22.482.0,22.186.0,40.208.0,34.231.0"}
P.entries["subzone:blackwood-lake"] = {n="Озеро Чорнолісся",s="Озеро Чорнолісся — отруєна водойма на півдні Східних Чумних земель, де кишать ворожі зіпсовані елементалі. Колись тут було мирне лордеронське село, а тепер край переслідують спогади про трагедію й війну, і за ним пильнує невеликий передовий табір Срібного світанку.",h="Озеро Чорнолісся — отруєна водойма на півдні Східних Чумних земель, де кишать ворожі зіпсовані елементалі.",kw={"озеро чорнолісся","східні чумні землі","елементалі","срібний світанок","ґарітос","дарроушир","горґус спустошувач"},ang={["class:Paladin"]="Отруєні води й тлін довкола Озера Чорнолісся наочно показують, як скверна спотворює природних елементалів Лордерону, — тут потрібен очищувальний дотик Світла.",["race:Human"]="Для людей Лордерону Озеро Чорнолісся — гірке нагадування про загибель роду великого маршала Ґарітоса і про те, як безжально Погибель стерла сільські містечка королівства."},sec={{t="Отруєна пам'ять",b="До Третьої війни на цих берегах стояло тихе поселення Чорнолісся. Це був родовий дім великого маршала Отмара Ґарітоса, чиї родинні володіння й підданих вирізали під час Другої війни, поки він захищав Кель'Талас. Нині від селища не лишилося й сліду, а саме озеро отруїла нестримна чума нежиття. Під каламутною поверхнею вирують хворі, мерзенні водяні елементалі, що нападають на кожного, хто наблизиться до берега."},{t="Реліквії полеглих",b="Озеро зберігає й похмурі реліквії Битви за Дарроушир. Місцеві історичні записи, як-от Розширені Аннали Дерровширу, свідчать, що відрубаний череп воєначальника Погибелі Горґуса Спустошувача кинули в смердючі глибини Озера Чорнолісся. Неподалік, на невеликому передовому посту, цілитель Срібного світанку доглядає побитих піхотинців, намагаючись утримати солдатів живими в тіні спустошення, що лишила Погибель."}},faq={{q="Які істоти чаяться в Озері Чорнолісся?",a="Озеро кишить зіпсованими водяними елементалями. Як і більшість прісних вод Чумних Земель, ці води спотворили некромантичні стоки й бруд, перетворивши місцевих духів на люті, отруйні сутності.",al={"що у воді","чудовиська озера","стихійці озера чорнолісся"}},{q="Яке містечко колись тут стояло?",a="На цих берегах колись стояло лордеронське село Чорнолісся. Ним правила родина Великого Маршала Отмара Ґарітоса, доки його не сплюндрував і не знищив загін орків у Другій війні.",al={"містечко чорнолісся","хто тут жив","рідне місто ґарітоса"}},{q="Чому біля озера стоїть Срібний Світанок?",a="Срібний Світанок тримає біля озера невеликий польовий табір, де Срібний Медик доглядає поранених піхотинців. Це пункт невідкладної допомоги для патрулів, що б'ються на дорогах між Дарроуширом і сусідніми твердинями Погибелі.",al={"табір срібного світанку","лікар срібного світанку","чому тут солдати"}},{q="Яка реліквія Дарроушира похована в Озері Чорнолісся?",a="Згідно з Літописами Дарровширу, череп Горґуса Спустошувача, одного з головних ватажків Погибелі під час нападу на Дарроушир, кинули в глибини озера після того, як його здолали.",al={"голова горгуса руйнівника","предмет завдання в озері","літопис даррошира в озері"}}},fp="14,294,17.471.0,20.414.1,38.219.0,29.209.0,45.229.0,51.203.0"}
P.entries["subzone:bladefist-bay"] = {n="Затока Блейдфіст",s="Затока Блейдфіст — суворий відтинок узбережжя на сході Дуротару, одразу за брамою Оргріммара. Названа на честь Карґата Блейдфіста, затока служить природною гаванню, зверненою до Великого Моря, у тіні скелястих круч і сусідніх південних берегів Азшари.",h="Затока Блейдфіст — суворий відтинок узбережжя на сході Дуротару, одразу за брамою Оргріммара.",kw={"затока блейдфіст","узбережжя","гавань","карґат","розтрощена рука","оргріммар","дуротар"},ang={["class:Rogue"]="Розтрощена Рука діє в тінях Оргріммара як гільдія злодіїв і вбивць Орди, тож для таємних агентів це узбережжя має тихий відгомін.",["race:Orc"]="Затока носить горде й жорстоке ім'я Карґата Блейдфіста, нагадуючи про випробування клану Розтрощеної Руки на Дренорі."},sec={{t="Гавань на Великому Морі",b="Простягшись уздовж північно-східного краю Дуротару, Затока Блейдфіст відкривається просто в неосяжні води Великого Моря. Затиснута скелястими урвищами й підступним прибоєм, вона є головним морським порогом столиці Орди — Оргріммара. Припливи раз у раз викидають на берег плавник, океанське сміття та уламки, тож серед місцевих затока має славу природного збірника морського непотребу. Просто на північ, через воду, височіють прадавні червоні скелі й руїни Азшари, роблячи затоку важливим морським кордоном Дуротару."},{t="Тінь Розтрощеної Руки",b="Затока вшановує Карґата Блейдфіста — славетного вождя клану Розтрощеної Руки, який відтяв собі руку, щоб замінити її клинком під час випробувань старої Орди на Дренорі. Близькість затоки до місць на кшталт Череп-скелі, де в тіні діють культисти й приховані мережі розбійників, перегукується з лютою та безжальною спадщиною клану, чий вождь дав цим водам ім'я."}},faq={{q="На честь кого названо Затоку Блейдфіст?",a="Затоку названо на честь Карґата Блейдфіста — легендарного вождя клану Розтрощеної Руки, що замінив свою відрубану руку смертоносним серпоподібним лезом.",al={"хто такий блейдфіст","на честь блейдфіста","затока каргата блейдфіста"}},{q="Де Затока Блейдфіст?",a="Вона на північно-східному узбережжі Дуротара, просто на схід від головної брами Оргріммара й на південь через воду від Азшари.",al={"місце затоки блейдфіст","де затока блейдфіст","як дістатися затоки блейдфіст"}},{q="Які загрози чатують довкола Затоки Блейдфіст?",a="Берег лежить просто поруч із Череп-скелею — печерою, що зажила лихої слави сховищем чорнокнижників, демонів і членів зловісного культу Палаючого Клинка.",al={"небезпека затоки блейдфіст","небезпеки довкола затоки блейдфіст","вороги затоки блейдфіст"}},{q="Чому затоку іноді називають смітником?",a="Течії Великого Моря постійно виносять на її береги морське сміття, уламки й рештки кораблів, тож затока славиться як звалище всього, що викидає море.",al={"смітник затоки","океанське сміття блейдфіст","сміттєва затока"}}},fp="13,267,25.553.0,28.387.0,33.157.0,31.129.0,39.148.0,46.175.0"}
P.entries["subzone:bloodfen-burrow"] = {n="Нора Кривавої Драговини",s="Нора Кривавої Драговини — печера в південно-західній частині Багна Пилоброду, де кишать люті раптори. Звірі захопили печеру й галявину навколо неї, геть заполонивши руїни поселення, що колись намагалося вижити серед боліт.",h="Нора Кривавої Драговини — печера в південно-західній частині Багна Пилоброду, де кишать люті раптори.",kw={"нора кривавої драговини","багно пилоброду","раптори","печера","кортелло","мисливці"},ang={["class:Hunter"]="Раптори Кривавої Драговини, що гніздяться тут, — люті й прудкі звірі, які чудово підійдуть мисливцям, що шукають витривалих і агресивних болотяних супутників."},sec={{t="Лігво хижаків",b="Захована в південно-західних закутках Багна Пилоброду, Нора Кривавої Драговини — головне лігво агресивних тутешніх рапторів Кривавої Драговини. Вхід до печери й улоговина довкола аж кишать зграєю, яку приваблюють захищена розколина й щедрі мисливські угіддя, що їх дає болото. Біля входу лежать розкидані уламки й розтрощені рештки невідомого поселення — похмуре нагадування про те, хто насправді панує в глибинах болота. А ще мандрівники шепочуть, що Кортелло, відчайдушний пірат, залишив десь у цьому смертоносному лігві одну зі своїх захованих загадок-підказок."}},faq={{q="Хто живе в Норі Кривавої Драговини?",a="Нору заполонили раптори Кривавої Драговини. Вони влаштували густе гніздовище і в печері, і на галявині довкола, нападаючи на кожного, хто необачно вдереться на їхню територію.",al={"хто тут живе","раптори нори кривавої драговини","мобі нори кривавої драговини"}},{q="Що за руїни біля печери?",a="The remains of an unidentified settlement lie outside the cave. Raptors destroyed the settlement, but the identity and fate of its occupants are not recorded.",al={"руїни біля печери","хто збудував хатини біля нори","руїни зовні печери"}},{q="Навіщо шукачеві пригод обшукувати Нору Кривавої Драговини?",a="Окрім полювання на лютих болотяних рапторів, дослідники, що розгадують Загадку Кортелло, мусять спуститися в нору: пірат сховав одну з підказок своєї загадки в темних глибинах печери.",al={"загадка кортелло","скарб нори кривавої драговини","завдання нори кривавої драговини"}}},fp="15,244,18.594.0,30.208.0,36.158.0,47.202.1"}
P.entries["subzone:bloodhoof-village"] = {n="Село Бладгуф",s="Село Бладгуф — центральне тауренське поселення на берегах Озера Кам'яного Бика в Малгорі. Назване на честь племені Бладгуф, воно стає першим великим осередком для молодих мисливців і сміливців, що прямують із Табору Нарачі до Тандер Блафа. Під проводом Бейна Бладгуфа село узгоджує місцеву оборону, торгівлю й традиційні обряди по всіх рівнинах.",h="Село Бладгуф — центральне тауренське поселення на берегах Озера Кам'яного Бика в Малгорі.",kw={"село бладгуф","бейн бладгуф","озеро кам'яного бика","малгор","таурени","поселення"},ang={["faction:Horde"]="Це мирне поселення — важлива зупинка й сполучна ланка між південними рівнинами Малгору та столицею Орди в Тандер Блафі.",["race:Tauren"]="Для молодих тауренів вхід до Села Бладгуф — перший справжній крок із юності до ширшої відповідальності перед племенем і духовної зрілості."},sec={{t="Серце рівнин",b="Розташоване довкола прозорих вод Озера Кам'яного Бика, Село Бладгуф — жвавий осередок торгівлі, ремесла й обрядів у центрі Малгору. Молоді таурени, що пройшли випробування в Таборі Нарачі, приходять сюди відточити вміння, перш ніж рушити далі, до великих плато Тандер Блафа. Село також відоме по всьому Калімдору своїми майстрами-барабанниками й терплячими заводчиками, що приручають диких кодо для подорожей."},{t="Проводирі та обряди",b="Повсякденне врядування й оборона краю лежать на Бейні Бладгуфі, синові Верховного Вождя Кайрна Бладгуфа. Під його пильним оком сміливців посилають убезпечувати пасовища від агресивних звірів, зазіхань шипогривів і тіньової присутності Венчурної Компанії. Поруч із Бейном духовні провідники, як-от Зарлман Ту-Мунс, дбають про внутрішнє життя племені й ведуть новачків через священні мандри на кшталт Обряду Видіння."}},faq={{q="Хто очолює Село Бладгуф?",a="Бейн Бладгуф, син Верховного Вождя Кайрна Бладгуфа, очолює поселення й керує його обороною від загроз центральним рівнинам.",al={"хто очолює село","бейн бладгуф","хто головний в бладгуфі"}},{q="Які важливі обряди тут проводять?",a="Духовні наставники на кшталт Зарлмана Ту-Мунса ведуть молодих тауренів традиційним Обрядом Видіння — неодмінною духовною подорожжю на шляху до дорослості.",al={"обряд видіння","духовні випробування","завдання зарлмана ту-мунса"}},{q="Чим славиться поселення?",a="Село Бладгуф славиться своїми неповторними обрядовими барабанами, а ще це головне місце, де приборкують диких рівнинних кодо й навчають їх ходити під сідлом.",al={"скакуни тауренів","приборкання кодо","барабани бладгуфа"}},{q="Куди вирушають мандрівники, завершивши тут справи?",a="Коли справи в центрі Малгору завершено, мандрівників зазвичай скеровують на північ, до Тандер Блафа — столиці тауренів.",al={"після бладгуфа","куди далі після бладгуфа","наступний центр"}}},fp="17,379,19.417.0,20.454.0,28.141.0,36.160.0,43.146.0,55.142.0"}
P.entries["subzone:bloodtooth-camp"] = {n="Табір Кривавого Ікла",s="Табір Кривавого Ікла — стійбище ворожих осквернених фурболгів у центральному Ашенвалі, трохи на захід від Річки Фалфаррен. Під проводом вождя Рана Бладтуса ці колись мирні створіння піддалися темному божевіллю й нападають на кожного, хто наближається. Табір — одна з головних цілей розвідників Альянсу, які очищають довколишні ліси.",h="Табір Кривавого Ікла — стійбище ворожих осквернених фурболгів у центральному Ашенвалі, трохи на захід від...",kw={"табір кривавого ікла","ран бладтус","фурболги","скверна","річка фалфаррен","ашенваль"},ang={["faction:Alliance"]="Для шукачів пригод з Альянсу Табір Кривавого Ікла — осередок скверни, що загрожує безпеці південних гаїв і місячних колодязів Ашенвалю.",["race:NightElf"]="Нічні ельфи бачать у божевіллі племені Рана Бладтуса трагічну ознаку глибокої скверни, що спотворює їхню прадавню батьківщину."},sec={{t="Осквернене лігво",b="Табір Кривавого Ікла, що сховався на південний захід від південного місячного колодязя й на захід від Річки Фалфаррен, — суворе нагадування про занепад, який охоплює Ашенваль. Фурболги, що живуть тут, колись були пов'язані зі священною дикою природою Калімдору, але затяжна духовна скверна поглинула їхнє плем'я. Під командою Рана Бладтуса вони з шаленою ворожістю стережуть своє примітивне поселення, кидаючись і на мандрівників, і на нічних ельфів, що боронять ліс."},{t="Очищення лісу",b="Зграя Рана Бладтуса загрожує ближнім священним місцям, тож вартові Альянсу та їхні союзники не можуть оминути табір. Щоб повернути лісові гармонію — а саме допомогти Рейн Вульфраннер в очищенні, — Кролґ посилає шукачів пригод проникнути до табору, убити Рана Бладтуса й покінчити з його лютими охоронцями."}},faq={{q="Де Табір Кривавого Ікла?",a="Табір Кривавого Ікла — у центрі Ашенвалю, просто на захід від Річки Фалфаррен і трохи на південний захід від південного Місячного Колодязя.",al={"місце табору кривавого ікла","де табір кривавого ікла","знайти табір кривавого ікла"}},{q="Чому тутешні фурболги ворожі?",a="Як і чимало племен фурболгів Ашенвалю, клан Кривавого Ікла став жертвою темної демонічної скверни, що лишилася в нетрях. Вона доводить їх до божевілля й безмежної агресії до всіх чужинців.",al={"чому фурболги кривавого ікла нападають","осквернення кривавого ікла","чи фурболги тут злі"}},{q="Хто очолює фурболгів у Таборі Кривавого Ікла?",a="Табором керує Ран Бладтус — лютий вождь, що верховодить місцевими фурболгами разом зі своєю особистою вартою.",al={"бос табору кривавого ікла","ран кривавий ікол","хто очолює табір кривавого ікла"}},{q="Чому Альянс посилає сюди розвідників?",a="Під час подій «Очищення Рейн» фурболг-вигнанець Кролґ скеровує звитяжців Альянсу вдарити по табору, знищити Рана Бладтуса й усунути загрозу, яку становлять для краю його зіпсовані скверною прибічники.",al={"завдання табору кривавого ікла","чому вбити рана","місія кролга"}}},fp="15,364,15.448.0,20.375.1,33.131.0,34.213.0,42.131.0,39.222.0"}
P.entries["subzone:bloodvenom-falls"] = {n="Водоспад Кривавої Отрути",s="Водоспад Кривавої Отрути — височенний смердючий водоспад, що зривається з осквернених скель північного Сквернолісся. Його отруйний потік живить Річку Кривавої Отрути й несе породжену демонами гниль униз схилами гір до земель нижче за течією.",h="Водоспад Кривавої Отрути — височенний смердючий водоспад, що зривається з осквернених скель північного...",kw={"водоспад кривавої отрути","водоспад","річка кривавої отрути","річка дикого закруту","сквернолісся","темне узбережжя"},ang={["class:Druid"]="Отруйний водоспад — гірке видовище для Кола Кенарія: це головний канал, яким мерзенна недуга Сквернолісся тече до земель унизу.",["race:NightElf"]="Для нічних ельфів видовище Водоспаду Кривавої Отрути, що живить отруєну Річку Дикого Закруту на Темному Узбережжі, — пряма загроза родовим домівкам і прибережним святилищам."},sec={{t="Джерело гнилизни",b="Водоспад Кривавої Отрути, що спадає з урвищ Сквернолісся, — одна з найочевидніших ран, завданих давнім лісам Калімдору. Колись це був чистий гірський каскад, але в Третю війну демонічна магія й рештки Палаючого Легіону перетворили його воду на ядучий мул. Водоспад живить Річку Кривавої Отрути, що в'ється самим серцем Сквернолісся. Звідти отруєний потік мчить гірськими схилами й стає мерзенною Річкою Дикого Закруту на Темному Узбережжі, розносячи заразу далеко за зачумлені межі Сквернолісся."},{t="Отрута для природи",b="Ядучі стоки Водоспаду Кривавої Отрути не лише барвлять річище — вони спотворюють усе, чого торкаються. На болотистих берегах у його бризках розводяться покручені древені, хворі звірі й агресивні слизи. Для друїдів і охоронців лісу, що намагаються стримати гниль Сквернолісся, водоспад — моторошне нагадування, що води північного Калімдору глибоко хворі в самому своєму витоку."}},faq={{q="Куди тече вода з Водоспаду Кривавої Отрути?",a="Водоспад живить Річку Кривавої Отрути. Річка перетинає Сквернолісся, а тоді спадає з гір на Темне Узбережжя, де стає зіпсованою Річкою Дикого Закруту.",al={"куди тече кривава отрута","шлях річки кривавої отрути","куди стікає"}},{q="Чому водоспад зіпсований?",a="Під час Третьої війни демонічна магія Палаючого Легіону просякла край і зіпсувала дикі ліси Сквернолісся. Джерела й високогірні струмки, що живлять водоспад, увібрали цю скверну, і вода перетворилася на отруйну жижу.",al={"чому водоспад зелений","чому вода отруєна","що осквернило водоспад кривавої отрути"}},{q="Чи впливає скверна водоспаду на інші краї?",a="Так. Води спадають зі Сквернолісся західними гірськими хребтами на Темне Узбережжя, виходять там отруєною Річкою Дикого Закруту й несуть гниль до узбережжя.",al={"чи гниліліс отруює темне узбережжя","як це впливає на темне узбережжя","забруднення річок темного узбережжя"}},{q="Чи можна очистити води Водоспаду Кривавої Отрути?",a="Коло Кенарія й далі шукає способів очистити Сквернолісся, але через величезний об'єм і глибоку насиченість річки демонічною скверною зцілити водоспад — титанічне завдання, яке досі не розв'язане.",al={"чи друїди можуть виправити","чи можна очистити водоспад","очищення водоспаду"}}},fp="16,219,17.560.0,17.381.0,48.179.0,31.240.0,52.164.0,47.203.0"}
P.entries["subzone:bloodvenom-post"] = {n="Застава Кривавої Отрути",s="Застава Кривавої Отрути — віддалене поселення Орди на скелястих урвищах західного Сквернолісся, звідки видно Темне Узбережжя. Тауренські будівлі й тауренська варта дають Орді плацдарм у краї, де панують демонічна скверна й осквернена звірина.",h="Застава Кривавої Отрути — віддалене поселення Орди на скелястих урвищах західного Сквернолісся, звідки видно...",kw={"застава кривавої отрути","орда","таурени","сквернолісся","темне узбережжя","застава"},ang={["faction:Horde"]="Як єдиний укріплений притулок Орди в Скверноліссі, цей табір дає безпеку, захист і базу для дій у цілком ворожій глушині.",["race:Tauren"]="Таурени-воїни тримають цю заставу, щоб вивчати спустошення природи, заподіяне Легіоном, і протидіяти скверні, що нищить природних духів землі."},sec={{t="Хиткий плацдарм",b="До Застави Кривавої Отрути, схованої на високих кручах над Темним Узбережжям, можна дістатися, якщо звернути з головного шляху Сквернолісся й піти оскверненим південним берегом Річки Кривавої Отрути. Збудований із традиційних тауренських наметів, тотемів і дозорних веж, цей табір дає мандрівникам Орди важливу базу посеред лісу, що помирає. Звідси розвідники стежать за наступом демонічних сил, вивчають, як поширюється отруєння вод, і намагаються наглядати за ворожою звіриною, спотвореною рештками сили Палаючого Легіону."},{t="Очі над кряжем",b="Табір не лише спостерігає за отруєними нетрями Сквернолісся: він стоїть просто на краю урвища, звідки видно північ Темного Узбережжя. Таке відлюдне розташування служить подвійній меті: Орда знає про пересування нічних ельфів уздовж західного узбережжя, а сама лишається поза легкою досяжністю патрулів Альянсу, що ходять центральним шляхом лісу."}},faq={{q="Де Застава Кривавої Отрути?",a="Застава Кривавої Отрути захована на західних хребтах центрального Сквернолісся. Щоб дістатися до неї з головної дороги північ — південь, ідіть південним берегом Річки Кривавої Отрути на захід вузькою стежкою, що огинає скелястий схил.",al={"знайти заставу кривавої отрути","як дістатися застави кривавої отрути","напрям до застави кривавої отрути"}},{q="Хто контролює цю заставу?",a="Застава Кривавої Отрути належить Орді: її охороняють таурени, і збудована вона в традиційному тауренському стилі.",al={"хто керує заставою кривавої отрути","фракція застави кривавої отрути"}},{q="Чому заставу названо Кривавою Отрутою?",a="Вона названа на честь сусідньої Річки Кривавої Отрути, чиї води забруднила й отруїла демонічна скверна, що просочилася в ліс.",al={"чому кривава отрута","значення назви кривавої отрути"}},{q="З якими загрозами стикаються тут розвідники?",a="Застава постійно потерпає від зіпсованих скверною звірів Сквернолісся — скажених шаблезубів, отруєних слизунів і спотворених деревнів, — а також від демонічної присутності Ради Тіней і решток Палаючого Легіону по всьому краю.",al={"вороги кривавої отрути","що нападає на заставу кривавої отрути"}}},fp="15,243,21.534.0,21.345.0,33.232.0,26.90.0,33.146.0,37.244.0"}
P.entries["subzone:bloodvenom-river"] = {n="Річка Кривавої Отрути",s="Річка Кривавої Отрути — смердючий потік, що перетинає центральне Сквернолісся й просякнутий демонічною скверною, яка сплюндрувала давній ліс. Її гнилі води просочуються нижче за течією через гори до Темного Узбережжя й перетворюються на отруєну Річку Дикого Закруту.",h="Річка Кривавої Отрути — смердючий потік, що перетинає центральне Сквернолісся й просякнутий демонічною...",kw={"річка кривавої отрути","річка","сквернолісся","темне узбережжя","річка дикого закруту","скверна"},ang={["class:Druid"]="Річка Кривавої Отрути — разюче свідчення осквернення священних гаїв Калімдору: вона розносить скверну по різних краях і вимагає, щоб природу відновили.",["race:NightElf"]="Для калдореїв бачити, як води їхніх родових лісів отруюють Темне Узбережжя через Річку Дикого Закруту, — гірке нагадування про незагоєну рану, яку лишив Легіон."},sec={{t="Жила скверни",b="Річка Кривавої Отрути, що тече оскверненим серцем Сквернолісся, — відкритий канал духовного й тілесного тління цієї землі. Її береги вкриті мерзенними слизами, мутованими звірами й гидкими стоками, що лишилися після вторгнення Палаючого Легіону. Скверна в руслі настільки сильна, що отруює землі далеко за межами самого Сквернолісся: вона тече на захід, до прибережних лісів Темного Узбережжя, вже як Річка Дикого Закруту."}},faq={{q="Чому річка зіпсована?",a="Річка тече центральним Сквернолісся — давнім лісом нічних ельфів, глибоко спотвореним демонічною магією Палаючого Легіону під час Третьої війни. Скверна цілком просякла землю й води, і річка стала руслом отруйного мулу й некротичного слизу.",al={"скверна річки кривавої отрути","чому вода зелена","отрута річки гнилолісся"}},{q="Куди тече Річка Кривавої Отрути?",a="Річка тече отруєною долиною Сквернолісся, а тоді прориває гори й спадає на Темне Узбережжя. За хребтом її зіпсовані води течуть далі під назвою Річка Дикого Закруту.",al={"шлях річки кривавої отрути","куди вона тече","річка до темного узбережжя"}},{q="Які істоти живуть на берегах річки?",a="У воді й на мулистих берегах живуть отруйні слизуни, спотворені звірі й зіпсовані хижаки, яких приваблює чи породжує ця згубна демонічна пошесть.",al={"дика природа річки кривавої отрути","мобі біля річки","чудовиська в річці"}}},fp="16,261,20.435.0,27.281.0,37.206.0,41.151.0"}
P.entries["subzone:bluefen"] = {n="Синє Багно",s="Синє Багно — мокра болотиста місцина в північній частині Багна Пилоброду, між Селом Папоротяної Стіни й Селом Чорного Копита. Тут кишать агресивні болотяні хижаки, а ще ця трясовина стала плацдармом для таємних лазутчиків Терамору, що стежать за пересуванням Орди.",h="Синє Багно — мокра болотиста місцина в північній частині Багна Пилоброду, між Селом Папоротяної Стіни й Селом...",kw={"синє багно","багно пилоброду","лазутчики терамору","кам'яний молот","раптори","кроколіски"},ang={["faction:Alliance"]="Хоч дикі звірі й роблять подорож небезпечною, розвідники Терамору користуються густою болотяною рослинністю Синього Багна, щоб пильно стежити за таборами огрів і тауренів неподалік.",["faction:Horde"]="Синє Багно, що лежить одразу на схід від Села Папоротяної Стіни, подвійно небезпечне для чемпіонів Орди: тут і люті болотяні звірі, і пильні лазутчики Терамору, які шпигують за вашими союзниками з Кам'яного Молота."},sec={{t="Спірне болото",b="Затиснуте між ограми Кам'яного Молота із Села Папоротяної Стіни на заході й тауренами Ґрімтотем із Села Чорного Копита на сході, Синє Багно втілює всі дикі небезпеки Багна Пилоброду. Задушливе болото кишить хижаками — тут раптори, велетенські павуки, птахи-падальники й кроколіски, що чатують у воді. Окрім природних хижаків, мандрівникам доводиться мати справу з лазутчиками Терамору, які нишпорять каламутною місцевістю, шпигують за Ордою й поширюють людський вплив углиб болота."}},faq={{q="Де Синє Багно?",a="Синє Багно — на півночі Багна Пилоброду, просто між Селом Папоротяної Стіни на заході й Селом Блекгуф на сході.",al={"місце синього багна","де синє багно","карта синього багна"}},{q="Які загрози чатують у Синьому Багні?",a="Болото кишить небезпечними звірами — павуками, кроколісками, рапторами й болотяними птахами. До того ж місцину потай розвідують лазутчики Терамору, загрожуючи мандрівникам з Орди.",al={"вороги синього багна","що живе в синьому багні","мобі синього багна"}},{q="Чому розвідники Терамору діють у Синьому Багні?",a="Лазутчики Терамору стежать із Синього Багна за північчю Багна Пилоброду: вони спостерігають за сусіднім поселенням огрів Кам'яного Молота — Селом Папоротяної Стіни — й патрулюють спірні болотяні стежки.",al={"лазутчики терамору","чому альянс тут","шпигуни терамору"}}},fp="7,276,15.502.0,25.135.0,37.198.0,43.196.0"}
P.entries["subzone:bluegill-marsh"] = {n="Багно Синьозябрих",s="Багно Блакитнозябрих — мокра трясовина на заході Багнокраю, де розкинулося поселення ворожого племені мурлоків-Блакитнозябрих. Протоки й халупи люто стережуть ці водяні істоти під владою громила на ім'я Жерун. Мандрівникам, що йдуть через західні драговини, варто обережно обирати шлях, щоб їх не оточили на мілині.",h="Багно Блакитнозябрих — мокра трясовина на заході Багнокраю, де розкинулося поселення ворожого племені...",kw={"багно синьозябрих","мурлоки","жерун","гавань менетіл","синьозябрі","багнокрай"},ang={["faction:Alliance"]="Розташовані неподалік від Гавані Менетіл, агресивні мурлоки-Блакитнозябрі — постійна дошкульна загроза для мандрівників і шляхів постачання через західний Багнокрай."},sec={{t="Кишливе лихо",b="Серед багнистих рівнин західного Багнокраю Багно Блакитнозябрих повне мулу, очерету й булькотливих бойових вигуків місцевих мурлоків. Плем'я Блакитнозябрих поставило по всій застояній воді грубі первісні табори й оголосило ці землі своїми. На відміну від самотніших болотяних звірів, ці мурлоки живуть і полюють тісними зграями. Обачні волоцюги й розвідники з Гавані Менетіл знають: забредеш на їхню територію — і на тебе нападуть з усіх боків, а надто тоді, коли каламутною мілиною нишпорить грізний ватажок Жерун."}},faq={{q="Що таке Багно Блакитнозябрих?",a="Багно Блакитнозябрих — болотиста місцина на заході Багнокраю. Це головне поселення й гніздовище агресивного племені мурлоків Блакитнозябрих.",al={"де багно блакитнозябрих","що це за місце","болото мурлоків мокрих земель"}},{q="Хто панує на болоті?",a="Плем'я Блакитнозябрих очолює могутній і лютий мурлок на прізвисько Жерун, що пильнує скупчені табори й нищить кожного суходільця, який зазіхає на їхні води.",al={"вождь мурлоків мокрих земель","ґоблер","хто веде блакитнозябрих мурлоків"}},{q="Чому тут небезпечно мандрувати самому?",a="Мурлоки тут рідко никають поодинці. Вони збираються біля хиж і на берегах тісними ватагами по двоє-троє, тож самотнього мандрівника в глибокому в'язкому болоті дуже легко здолати.",al={"чому тут так багато мурлоків","чи багно блакитнозябрих важке","агресія мурлоків"}},{q="Навіщо мандрівники заходять у Багно Блакитнозябрих?",a="Розвідників і шукачів пригод із сусідніх поселень на кшталт Гавані Менетіл раз у раз посилають на болото проріджувати агресивних мурлоків і повертати крадене, яке ті потягли до своїх таборів.",al={"навіщо йти сюди","завдання багна блакитнозябрих","причини відвідати"}}},fp="14,361,17.573.0,23.163.0,25.189.0,41.197.0,45.201.0"}
P.entries["subzone:bolgan-s-hole"] = {n="Нора Болґана",s="Нора Болґана — підземна печера в південних скелях Села Ґелкіс у Пустограї. Це внутрішнє святилище клану кентаврів Ґелкіс, де живуть найвищі вожді й зберігаються священні реліквії землі.",h="Нора Болґана — підземна печера в південних скелях Села Ґелкіс у Пустограї.",kw={"нора болґана","село ґелкіс","пустограй","кентаври","принцеса терадрас","кристали","печера"},ang={["class:Shaman"]="Печера похмуро показує, як шанування землі може спотворитися, коли воно пов'язане з кривавою спадщиною Принцеси Терадрас, а не з природною рівновагою духів."},sec={{t="Осередок влади Ґелкіс",b="Видовбана глибоко в зубчастих урвищах над табором Ґелкіс, Нора Болґана слугує племені командним центром. Саме тут правлячий хан тримає двір в оточенні досвідчених вартових і найвпливовіших шаманів племені. Печера — природне укріплення проти ворожих кланів, передусім кровожерливих кентаврів Маґрам на сході."},{t="Сльози Принцеси Землі",b="Крім військового значення, печера має для Ґелкіс глибокий релігійний сенс. Із вологих кам'яних стін проростають сяйливі блакитні мінерали, відомі як сльози Терадрас. Шамани Ґелкіс одержимо збирають і стережуть ці кристали, шануючи їх як божественне благословення, що дарує підземний захист Принцеси Терадрас — первісної стихійної володарки землі й праматері роду кентаврів."}},faq={{q="Де Нора Болґана?",a="Нора Болґана — печера в південній частині Села Ґелкіс, захована серед пагорбів півдня Пустограю.",al={"місце нори болґана","де нора болґана","вхід до нори болґана"}},{q="Хто живе в Норі Болґана?",a="У печері — вищий провід кентаврів Ґелкіс, зокрема хан клану, як-от Хан Шака, а також їхнє найближче коло охоронців і шаманів-містиків.",al={"хто в норі болґана","бос нори болґана","місце ґелкіса хана"}},{q="Що за сяйливі блакитні кристали в печері?",a="Ці кристали звуться сльозами Терадрас. Ґелкіс шанують їх як зриме втілення прихильності своєї матері-землі й вірять, що камені дарують містичний захист тим, хто ними володіє.",al={"блакитні кристали в норі болґана","сльози терадраса","каміння нори болґана"}},{q="Чи можуть гравці безпечно зайти в Нору Болґана?",a="Зазвичай кентаври Ґелкіс у печері люто ворожі до чужинців. Але мандрівники, які стануть на бік Ґелкіс, винищуючи їхніх ненависних суперників — клан Маґрамів, — можуть здобути таку прихильність, що зможуть ходити печерою спокійно.",al={"чи нора болґана ворожа","дружні до ґелкіса","чи можна зайти в нору болґана"}}},fp="13,217,24.365.0,27.409.0,31.116.0,31.173.0,51.204.0,39.230.0"}
P.entries["subzone:bones-of-grakkarond"] = {n="Кістки Ґраккаронда",s="Кістки Ґраккаронда — рештки скелета величезного бронзового дракона, що біліють під сонцем у центрі Силітусу. Цей змій загинув під час прадавньої Війни Мінливих Пісків, і тепер його кістки — похмурий пам'ятник, священний для вартових-анубісатів кіражів.",h="Кістки Ґраккаронда — рештки скелета величезного бронзового дракона, що біліють під сонцем у центрі Силітусу.",kw={"кістки ґраккаронда","бронзовий дракон","війна мінливих пісків","анубісати","оссиріан","силітус"},ang={["race:NightElf"]="Скелет — суворе нагадування про Війну Мінливих Пісків, коли калдореї й чотири драконячі роди пліч-о-пліч відкидали навалу кіражів."},sec={{t="Пам'ятник мінливих пісків",b="Посеред продутих вітрами дюн центрального Силітусу лежать велетенські ребра й череп Ґраккаронда — бронзового дракона, що загинув під час прадавньої Війни Мінливих Пісків. У тій апокаліптичній битві тисячу років тому великого дракона повалив Оссиріан Безшрамний — воїн-анубісат, звеличений темними силами міста-царства. Для анубісатів цей трофей з поля бою — священне свідчення їхньої переваги над драконячими зграями, тож його так і лишили незайманим там, де дракон упав."}},faq={{q="Чиї це кістки?",a="Це рештки Ґраккаронда — великого бронзового дракона з Бронзового драконячого роду. Він загинув у битві з комахоподібними військами Ан'Кіража тисячу років тому, під час Війни Рухомих Пісків.",al={"хто був ґраккаронд","який дракон тут загинув","скелет дракона сілітус"}},{q="Хто вбив Ґраккаронда?",a="Ґраккаронда вбив воїн-анубісат Оссиріан Безшрамний. Перемога над бронзовим змієм принесла Оссиріанові величезну славу й темні благословення від володарів Ан'Кіража.",al={"хто вбив дракона","як загинув ґраккаронд"}},{q="Чому анубісати шанують це місце?",a="Анубісати вважають кістяк священним, бо він нагадує про їхню вирішальну перемогу над могутнім драконячим родом. Він стоїть серед відкритих дюн як переможний символ їхньої сили проти тих, хто прийшов їх ув'язнити.",al={"чому ануб'ісати шанують","чому кістки священні"}}},fp="19,269,32.494.0,22.205.0,22.185.0,39.228.0"}
P.entries["subzone:booty-bay"] = {n="Буті Бей",s="Буті Бей — розлогий піратський притулок, вбудований у стрімкі морські скелі на півдні Долини Стренглторну; ним заправляють Нападники Чорної Води з картелю Стімвідл. Суходолом сюди потрапляють крізь роззявлену пащу велетенської акулячої туші. Це нейтральний порт із залізними правилами, де Альянс і Орда змішуються під пильним оком добре озброєних гоблінських вишибал.",h="Буті Бей — розлогий піратський притулок, вбудований у стрімкі морські скелі на півдні Долини Стренглторну...",kw={"буті бей","піратський порт","нападники чорної води","картель стімвідл","долина стренглторну","нейтральне місто"},ang={["class:Rogue"]="Буті Бей, відомий як рай для пройдисвітів, аж кишить зв'язками в злочинному світі, скупниками краденого, замкненими скриньками й потаємними донощиками, готовими продати таємниці за монету.",["faction:Alliance"]="Далеко на південь від захищених кордонів Стормвінда Буті Бей пропонує мандрівникам Альянсу рідкісні нейтральні вигоди, польотні маршрути й морське сполучення просто з Калімдором."},sec={{t="Кубло пройдисвітів і наживи",b="Колись тут було людське поселення під назвою Бухта Чорної Води, яке згодом заполонили тролі джунглів, а ще до Першої війни бухту захопили гобліни з картелю Стімвідл. Нині це міжнародне роздоріжжя й притулок для пройдисвітів, вигнанців і купців. Портом з балконів таверни «Солоний моряк» керують Барон Ревілґаз і Флотоводець Сігорн. На позір тут панує беззаконня, але насправді лад суворий: кожен може пити, торгувати чи наймати найманців, якщо дотримується миру картелю й сплачує портові збори."},{t="Загрози з моря",b="Гамірні доки Буті Бею сполучають Східні Королівства просто з Раджетом за Великим Морем, тож порт — важливий осередок торгівлі й подорожей між континентами. Проте величезні статки притягують невпинну ворожість. Головний ворог міста — Буканіри Кривавого Вітрила, агресивний піратський флот, що раз у раз грабує кораблі Чорної Води, никає узбережжям Стренглторну й відкрито плете змову, щоб цілком знищити й пограбувати гоблінський порт."}},faq={{q="Хто править Буті Бей?",a="Портом править Барон Ревілґаз — помітна постать картелю Стімвідл — у тісній співпраці з Флотоводцем Сігорном, тауреном-командиром Нападників Чорної Води. Обидва ведуть свої справи з верхніх поверхів таверни «Солоний Моряк», звідки видно гавань.",al={"лідер буті бею","хто править буті беєм","бос буті бею"}},{q="Чому гравці Альянсу й Орди можуть тут стояти пліч-о-пліч?",a="Буті Бей контролює нейтральний картель Стімвідл, для якого прибуток і торгівля куди важливіші за ворожнечу фракцій. Картель суворо дотримується нейтралітету: він радий кожному, хто має гроші, і спускає добірних гоблінів-вишибал на кожного, хто наважиться почати бійку.",al={"чому буті бей нейтральний","безпечна зона буті бею","чи орда нападе на альянс тут"}},{q="Хто такі Буканіри Кривавого Вітрила?",a="Буканіри Кривавого Вітрила — суперницьке злочинне угруповання, що веде запеклу війну з Нападниками Чорної Води. Вони тримають кораблі вздовж південного узбережжя Долини Стренглторну й завзято плетуть змову, щоб захопити Буті Бей і його прибуткову гавань.",al={"пірати кривавого вітрила","чому кривавий вітрила ненавидять буті бей","переказ про буканірів кривавого вітрила"}},{q="Куди плаває корабель із Буті Бей?",a="Пасажирське судно з нижніх доків пливе через Велике Море просто до портового містечка Раджет у Пустках — це головний нейтральний шлях між півднем Східних Королівств і Калімдором.",al={"куди пливе корабель буті бею","призначення корабля","корабель до калімдора"}},{q="Що за велетенська статуя біля входу в затоку?",a="Величезна статуя невідомого гобліна з розкинутими руками стоїть на Мисі Жанейро, одразу за входом до гавані. Вона правує за орієнтир і привітальний пам'ятник для купецьких кораблів і піратських команд, що прибувають.",al={"статуя буті бею","колос буті бею","статуя на острові"}}},fp="9,361,30.568.0,20.455.0,20.281.0,55.273.0,33.237.0,38.224.0,56.223.0"}
P.entries["subzone:bough-shadow"] = {n="Тінь Віття",s="Тінь Віття — відлюдний гай у далекому північно-східному куточку Ашенвалю, на схід від Лісової Пісні. Його серце — велетенське Велике Дерево, що вкоренилося над давнім порталом, який веде просто до Смарагдового Сну.",h="Тінь Віття — відлюдний гай у далекому північно-східному куточку Ашенвалю, на схід від Лісової Пісні.",kw={"тінь віття","велике дерево","смарагдовий сон","зелені дракони","портал","нордрассіл"},ang={["class:Druid"]="Тінь Віття — священна земля для друїдів: тут розташований один із відчутних порогів, що з'єднують Азерот безпосередньо з володіннями зелених драконів і Смарагдовим Сном.",["race:NightElf"]="Це велике дерево, що росте далеко за руїнами Лісової Пісні, виплекали руки калдореїв із гілки самого Нордрассілу, і воно стоїть як живий пам'ятник давній ельфійській опіці над природою."},sec={{t="Брама до Сну",b="У Тіні Віття росте одне з рідкісних Великих Дерев, виплеканих із живця Світового Дерева, Нордрассілу. Давно посаджене друїдами, що йшли за Фандралом Стаґгелмом, воно запускає коріння глибоко в землю довкола природного переходу до Смарагдового Сну. Сьогодні цей тихий, але величний гай пильно охороняє рід зелених драконів. Смарагдові дракони, як-от Фантім і Скрадач снів, кружляють над кронами, а патрулі драконородів-емеральдонів та оракули невідступно стережуть вихористий зелений портал біля підніжжя дерева, завертаючи кожного смертного, хто наближається без запрошення."}},faq={{q="Що за сяйливий зелений портал тут?",a="Вир біля підніжжя Великого Дерева — прямий прохід до Смарагдового Сну, дикого царства духів Азероту. Це один із кількох таких природних переходів, розкиданих світом.",al={"портал тіні віття","що за портал","зелений портал ашенвалю"}},{q="Чому Тінь Віття охороняють зелені дракони?",a="Зеленому драконячому роду Ізери доручено пильнувати Смарагдовий Сон і його прямі переходи до фізичного світу. Смарагдові дракони й драконороди патрулюють Тінь Віття, щоб жодні зіпсовані сили чи непрохані гості не прослизнули крізь поріг.",al={"чому дракони в ашенвалі","зелений драконячий лет тінь віття","чому зелені дракони тут"}},{q="Хто посадив тут Велике Дерево?",a="Дерево посадили тисячоліття тому друїди нічних ельфів, вірні Фандралові Стаґгелму: вони вкоренили тут живець, узятий із гілок Світового Дерева Нордрассіл.",al={"хто створив тінь віття","хто посадив дерево","походження дерева"}},{q="Чи можуть гравці зайти в портал?",a="Ні. Прохід надійно запечатаний для смертних фізичного світу, а хто підійде надто близько, накличе гнів добірних драконячих вартових довкола.",al={"чи можна зайти в портал","увійти в портал тіні віття","як увійти в портал сну"}}},fp="12,221,22.577.0,38.210.0,44.246.0,32.176.0,29.162.0"}
P.entries["subzone:boulder-gor"] = {n="Болдер'ґор",s="Болдер'ґор — скелястий пагорб у західній частині Аратійського нагір'я, просто на північ від зруйнованого людського королівства Стромґард. Тут стоїть табір огрів Каменекулаків та їхніх незвичних союзників — лісових тролів із племені Сухокорів.",h="Болдер'ґор — скелястий пагорб у західній частині Аратійського нагір'я, просто на північ від зруйнованого...",kw={"болдер'ґор","огри","каменекулаки","сухокори","тролі","стромґард","аратійське нагір'я"},ang={["faction:Alliance"]="Для сил Альянсу, що прагнуть відвоювати Стромґард, Болдер'ґор — серйозна загроза, яка чатує просто на північному порозі занепалого королівства.",["race:Troll"]="Тролі Темного Списа не знайдуть тут рідні: лісові тролі Сухокорів із Болдер'ґора плекають давню глибоку ворожнечу до всіх чужинців, зокрема й до інших тролячих племен."},sec={{t="Лігво огрів і тролів",b="Стрімка круча Болдер'ґор, що здіймається просто на північ від осипаних валів Фортеці Стромгард, належить клану Каменекулаків. У її тіні стоїть курган Застави Каменекулаків, тож це місце — головний оплот огрської сили в нагір'ї. Як не дивно, тутешні огри ділять вогнища й укріплення з лісовими тролями з племені Сухокорів, серед яких є й тіньові заклиначі, що підсилюють грубу силу клану темною магією. Через цей союз центральні дороги нагір'я постійно небезпечні для мандрівників."},{t="Навколишні землі",b="Зі схилів Болдер'ґора видно відкриті простори західного нагір'я. Затиснутий між руїнами Стромґарда, куди проник Синдикат, і дикими осередками стихій на рівнинах, Болдер'ґор лишається пильно стереженою, ворожою твердинею племінної згуртованості проти мандрівників і з Альянсу, і з Орди."}},faq={{q="Що таке Болдер'ґор?",a="Болдер'ґор — високий пагорб і табір на північ від Фортеці Стромгард на Аратійському нагір'ї. Тут повно огрів Каменекулаків і лісових тролів Сухокорів.",al={"де болдер'ґор","інформація про болдер'ґор","що це за місце"}},{q="Чому лісові тролі живуть тут поруч з ограми?",a="Тролі Сухокори й огри Каменекулаки тримаються розважливого союзу на Аратійському нагір'ї. І ті, й ті прагнуть панувати на нагір'ї й відбиватися від суперників, поєднуючи тролячу тіньову магію з грубою огрською силою.",al={"чому тролі тут","союз огрів сухокорів","тролі й огри"}},{q="Які помітні місця поблизу Болдер'ґору?",a="Болдер'ґор лежить просто на північ від Фортеці Стромгард, а в самому пагорбі — огрський курган Застава Каменекулаків.",al={"місця поруч","що біля болдер'ґора","пам'ятки"}},{q="Чи Болдер'ґор дружній до Орди чи Альянсу?",a="Ні до кого. Огри Каменекулаки й тролі Сухокори з Болдер'ґору цілком ворожі і до Альянсу, і до Орди й люто боронять свій пагорб від чужинців.",al={"чи можна безпечно","чи ворожий болдер'ґор"}}},fp="11,249,25.542.0,21.312.0,20.171.0,50.216.0,42.122.0,49.174.0"}
P.entries["subzone:boulder-lode-mine"] = {n="Шахта Кам'яної Жили",s="Шахта Кам'яної Жили — хижацька розробка, врізана в пагорби північно-східних Пусток. Хоча орківські прапори й сторожові вежі свідчать, що першою це місце облаштувала Орда, нині ним твердо заволоділа й орудує безжальна Венчурна Компанія.",h="Шахта Кам'яної Жили — хижацька розробка, врізана в пагорби північно-східних Пусток.",kw={"шахта кам'яної жили","венчурна компанія","бос копперплаґ","смарагд","гірництво","пустки"},ang={["faction:Horde"]="Бачити, як Венчурна Компанія хазяйнує в укріпленнях із прапорами Орди, — дратівливе нагадування про те, як зухвало гоблінський картель зазіхає на землі Калімдору.",["profession:Mining"]="Глибокі тунелі врізаються просто в посушливі пагорби, відкриваючи багаті рудні жили, які Венчурна Компанія нещадно вибирає."},sec={{t="Корпоративна ділянка",b="Обвітрені орківські споруди біля входу до Шахти Кам'яної Жили вказують на те, що колись цією ділянкою володіла або навіть заснувала її Орда. Проте сьогодні тут кишать наглядачі й костоломи Венчурної Компанії, що працюють під орудою Боса Копперплаґа. Гоблінський синдикат нещадно розорює каньйон, не зважаючи ні на місцеву природу, ні на своїх робітників, — його цікавлять лише цінні мінерали, дорогоцінне каміння й промислові машини."},{t="Самоцвіти й креслення",b="Чутки про багатства з Шахти Кам'яної Жили дійшли до сторонніх вух у Раджеті. Начальник Пристані Діззівіг послав найманців забрати величезний смарагд, який нібито знайшли в її тунелях, а інженери, що хочуть розібратися в складних гоблінських машинах, знають: Бос Копперплаґ ховає у своєму таборі важливі робочі посібники."}},faq={{q="Хто контролює Шахту Кам'яної Жили?",a="Шахтою керує Венчурна Компанія під безпосередньою владою Боса Копперплаґа; її стережуть добре озброєні охоронці компанії й наглядачі за робітниками.",al={"хто керує шахтою","бос шахти кам'яної жили","хто в кам'яній жилі"}},{q="Чи шахта спершу належала Орді?",a="Уцілілі орківські дерев'яні споруди, вартові вежі й вилинялі прапори Орди переконливо свідчать, що спершу шахту заснувала чи привласнила Орда, а вже потім прийшла й захопила її Венчурна Компанія.",al={"орочі прапори шахти","шахта орди","чому тут прапори орди"}},{q="Чому Начальника Пристані Діззівіга цікавить це місце?",a="Діззівіг прочув, що рудокоп у Шахті Кам'яної Жили викопав незвично великий і цінний смарагд, і наймає безпринципних найманців, щоб ті пробралися в тунелі й поцупили камінь за частку прибутку.",al={"завдання діззівіга про шахту","смарагд пустки","скарб шахтаря"}},{q="Що пов'язує Боса Копперплаґа із самофланжем?",a="У Боса Копперплаґа — необхідний посібник із керування загадковою машиною-самофланжем, знайденою неподалік, і інженери з Раджета посилають шукачів пригод забрати в його ватаги книгу та її розкидані сторінки.",al={"інструкція самофланжа шахта","інструкція коппера","шахта ріллі"}}},fp="17,247,15.464.0,19.338.0,31.159.0,39.200.0,53.201.0,56.212.0"}
P.entries["subzone:boulderfist-hall"] = {n="Зала Кам'янокулаків",s="Зала Кам'янокулаків — добре укріплений курган огрів у південних пагорбах Аратійського нагір'я, просто на північ від Мосту Тандол. Це місцева твердиня клану, чиї огри під проводом Кор'ґреша Колдрейджа тримають у кулаці довколишні торгові шляхи й долини.",h="Зала Кам'янокулаків — добре укріплений курган огрів у південних пагорбах Аратійського нагір'я, просто на...",kw={"зала кам'янокулаків","огри","кор'ґреш колдрейдж","міст тандол","аратійське нагір'я","каменекулаки"},ang={["faction:Alliance"]="Тутешні огри засіли просто над Мостом Тандол і постійно загрожують засідками гінцям і підкріпленням Альянсу, що йдуть на північ з Айронфорджа в нагір'я.",["faction:Horde"]="Щоб утвердитися в Аратійському нагір'ї, треба зламати незалежну владу огрів і очистити південний хребет, аби вберегти шляхи Орди з Гаммерфолла."},sec={{t="Оплот грубої сили",b="Зала Кам'янокулаків, видовбана в скелястих південних кручах Аратійського нагір'я, — головний оплот клану в цьому краї. Під захистом земляних валів і глибоких печер огри-громили й огри-маги тримають укріплене поселення за кілька кроків від Села Сухокорів і стратегічного Мосту Тандол. У глибині кургану чатує їхній місцевий вождь Кор'ґреш Колдрейдж разом із посіпаками на кшталт Фаланакса. Із цієї твердині огри силою тримають довколишні дороги, тож будь-який мирний шлях між нагір'ям і Багнокраєм небезпечний і для мандрівників, і для валок із припасами."}},faq={{q="Що таке Зала Кам'янокулаків?",a="Це укріплений огрський курган і печерний комплекс на півдні Аратійського нагір'я — головна база клану Каменекулаків у цьому краї.",al={"що це за місце","пагорб каменекулаків","печера огрів арати"}},{q="Хто править Залою Кам'янокулаків?",a="Твердиню очолює огр-вождь Кор'ґреш Колдрейдж, що керує кланом із глибокої печери в кургані разом зі звитяжцями на кшталт Фаланакса.",al={"хто керує залою каменекулаків","бос огрів арати","кор'ґреш"}},{q="Чому це місце важливе стратегічно?",a="Завдяки близькості до Мосту Тандол огри Каменекулаки можуть загрожувати життєво важливому сухопутному шляху між Аратійським нагір'ям і Каз Моданом: перекривати рух і битися із сусідніми тролями й мандрівниками.",al={"чому огри тут","небезпека мосту тандол"}},{q="Чи Каменекулаки — союзники тролів Сухокорів поблизу?",a="Ні. Огри Каменекулаки й лісові тролі з Села Сухокорів живуть зовсім поруч, але лишаються незалежними й ворожими угрупованнями, що змагаються за панування на Аратійському нагір'ї.",al={"огри й тролі друзі","союз сухокорів"}}},fp="16,315,27.633.0,25.157.0,27.153.0,45.217.0,61.182.0"}
P.entries["subzone:boulderfist-outpost"] = {n="Застава Кам'яного Кулака",s="Застава Каменекулаків — укріплений курган у самій глибині огрського поселення Болдер'ґор в Аратійському нагір'ї. Це внутрішнє лігво й сховище, де живуть войовничі огри та кілька тролів із племені Сухокорів.",h="Застава Каменекулаків — укріплений курган у самій глибині огрського поселення Болдер'ґор в Аратійському...",kw={"застава кам'яного кулака","болдер'ґор","огри","курган","сухокори","аратійське нагір'я"},ang={["faction:Alliance"]="Розвідникам Альянсу в нагір'ї краще обходити курган десятою дорогою: огри-громили всередині нападають на кожного чужинця, щойно його побачать.",["faction:Horde"]="Огри з кургану не розрізняють фракцій і нападають на мандрівників Орди так само охоче, як на їхніх суперників з Альянсу."},sec={{t="Твердиня в кургані",b="Застава Каменекулаків, видовбана в землі й камені західного нагір'я, — серце Болдер'ґора. Поки нагорі в поселенні панують огри-громили, у надрах застави зосереджена головна сила клану й прихований темний підземний прихисток. Між ограми тут часом трапляються кілька тролів-знахарів із племені Сухокорів — ознака хиткої співпраці між племенами."}},faq={{q="Де Застава Каменекулаків?",a="Застава Каменекулаків — внутрішній курган у більшому огрському поселенні Болдер'ґор на західних просторах Аратійського нагір'я.",al={"місце застави каменекулаків","де застава каменекулаків","вхід до пагорба каменекулаків"}},{q="Чому в огрській заставі тролі?",a="Лісові тролі Сухокори живуть неподалік на Аратійському нагір'ї й часом ділять землю з ограми Каменекулаками. У глибині застави поруч з ограми можна зустріти кількох знахарів-Сухокорів, що чаклують своє ремесло.",al={"чому тролі в огрській заставі","тролі каменекулаків","тролі сухокорів арати"}},{q="Хто ув'язнений у заставі?",a="Наразі не відомо, щоб у заставі тримали когось із бранців на ім'я. Її вогкі коридори належать громилам Каменекулаків і кільком знахарям-Сухокорам, тож кожен, хто туди зайде, має готуватися до бою, а не до порятунку.",al={"в'язні каменекулаків","хто в пастці","полонені огрів арати"}},{q="Хто очолює огрів у заставі?",a="Нутрощами кургану патрулюють громили клану, але відомо, що там чаїться й надзвичайно лютий огр на ім'я Коворк — помітна загроза.",al={"коворк","бос каменекулаків арати","рідкісний каменекулак"}}},fp="19,239,29.390.0,37.154.0,44.240.0,33.219.0,39.150.0"}
P.entries["subzone:boulderslide-cavern"] = {n="Печера Кам'яного Зсуву",s="Печера Кам'яного Зсуву — підземний лабіринт нір у найглибшому кінці Яру Кам'яного Зсуву в Горах Кам'яного Кігтя. Тут головне лігвище й копальня місцевих кобольдів Кам'яного Зсуву, які одержимо риють тунелі в пошуках сяйливих мінералів.",h="Печера Кам'яного Зсуву — підземний лабіринт нір у найглибшому кінці Яру Кам'яного Зсуву в Горах Кам'яного...",kw={"печера","кобольди","резоніт","ґоґґерок","гірництво","гори кам'яного кігтя"},ang={["class:Shaman"]="Резонітові кристали й сплячий землянин Ґоґґерок відгукуються первісною магією землі — відлунням прадавніх каменетворців, що колись формували цей світ.",["profession:Mining"]="Клан Кам'яного Зсуву невтомно розробляє печеру, прокладаючи тунель за тунелем, аби дістатися сяйливих жил магічного резоніту."},sec={{t="Розкопки резоніту",b="Кобольди Кам'яного Зсуву глибоко вгризлися в скелі Кам'яного Кігтя й зробили Печеру Кам'яного Зсуву своєю твердинею. На відміну від звичайних печерних шкідників, що шукають лише сховку, ці кобольди гарячково видобувають резоніт — рідкісний сяйливий пурпуровий кристал, вкраплений по всій породі. Кристали пульсують залишками земної магії, і через це істоти шаленіють, люто обороняючи свої розкопки від кожного прибульця."},{t="Сплячий велетень",b="Глибше в печерах безоглядні розкопки відкрили прадавні таємниці. У підземну скелю вмурована резонітова скриня, в якій спить Ґоґґерок — землянин із незапам'ятних часів. Кобольди невпинно риють довкола цієї містичної реліквії й ризикують пробудити істоту, сповнену первісної магії каменю, — а це вмить стане загрозою для всього яру."}},faq={{q="Що тут добувають кобольди?",a="Кобольди добувають резоніт — рідкісний фіолетовий кристал, вкраплений у скельні стіни печери. Мінерал ледь чутно гуде від слідів магії землі, тож це цінна здобич, і кобольди фанатично стережуть свої схованки.",al={"що таке резоніт","фіолетові кристали кам'яного кігтя","чому кобольди добувають"}},{q="Хто такий Ґоґґерок?",a="Ґоґґерок — давній землянин, що дрімає в резонітовій скрині в глибині печери. Розкопки кобольдів довкола його місця спочинку можуть порушити його багатовіковий сон.",al={"переказ про ґоґґерока","земляни кам'яного зсуву","сплячий велетень у печері"}},{q="Де Печера Кам'яного Зсуву?",a="Вхід до печери — у дальньому кінці Яру Кам'яного Зсуву, серед скелястих гір на півдні Гір Кам'яного Кігтя, трохи на північний схід від стежки до Пусток.",al={"місце печери кам'яного зсуву","як знайти печеру кам'яного зсуву","де печера"}},{q="Чому Орда цікавиться цією печерою?",a="Орда стежить за печерою, щоб стримувати навалу агресивних кобольдів, яка вихлюпується в яр, а також цікавиться магічними властивостями резонітових кристалів, які вони добувають.",al={"завдання орди кам'яного зсуву","чому посилають до кам'яного зсуву"}}},fp="19,271,16.421.0,20.353.1,33.236.0,16.188.0,37.176.0,43.185.0"}
P.entries["subzone:boulderslide-ravine"] = {n="Яр Кам'яного Зсуву",s="Яр Кам'яного Зсуву — дикий відлюдний каньйон серед центральних вершин Гір Кам'яного Кігтя, куди веде Стежка Павутинника. Прямі сутички між Ордою та Альянсом його здебільшого оминули: це кам'янистий підхід до Печери Кам'яного Зсуву, де досі живуть дикі гірські звірі.",h="Яр Кам'яного Зсуву — дикий відлюдний каньйон серед центральних вершин Гір Кам'яного Кігтя, куди веде Стежка...",kw={"яр","каньйон","печера","наскельні малюнки","таурени","гірництво"},ang={["profession:Mining"]="Стрімкі скельні стіни яру — надійне місце, щоб угледіти рудні жили, які оголює рухлива гірська порода.",["race:Tauren"]="Вицвілі малюнки в бічній печерці мають виразні риси тауренських племінних знаків — натяк на те, що стежки ваших предків пролягали крізь височини Кам'яного Кігтя."},sec={{t="Тихий гірський прохід",b="Яр Кам'яного Зсуву, захований осторонь Стежки Павутинника, — вузька розколина у височинах Кам'яного Кігтя. Поки лісоруби, нічні ельфи та Орда воюють за деревину й священні галявини по всьому краю, цей скелястий прохід війська майже не тривожать. Тутешня живність — дикі гірські барани та бродячі скельні звірі на кшталт скельних буревісників, що пробираються підступними уступами й прямовисними кам'яними стінами. Не зводять очей з яру й рудошукачі: на кам'янистих схилах, що ведуть углиб до печер, раз у раз проступають багаті рудні жили."},{t="Сліди в камені",b="Навпроти входу до Печери Кам'яного Зсуву, над самим яром, є невелика тиха печерка. Її освітлюють грубі смолоскипи, всередині стоять поторощені часом бочки з припасами, а стіни вкривають примітивні племінні малюнки. Ці грубі зображення разюче схожі на прадавні тауренські візерунки — певно, тубільні племена мандрували тут або шукали тимчасового прихистку серед цих скель задовго до того, як у гори прийшли нинішні війни."}},faq={{q="Де Яр Кам'яного Зсуву?",a="Яр Кам'яного Зсуву — у Горах Кам'яного Кігтя. До нього можна дістатися Стежкою Павутинника вгору, до вищих скель.",al={"місце яру кам'яного зсуву","як дістатися яру кам'яного зсуву","де яр кам'яного зсуву"}},{q="Які істоти живуть у Яру Кам'яного Зсуву?",a="Яр населяють здебільшого місцеві звірі, передусім гірські барани й небезпечні скельні скрадачі, як-от Скельні Буревії.",al={"мобі яру кам'яного зсуву","що в яру кам'яного зсуву"}},{q="Що за покинута печера навпроти Печери Кам'яного Зсуву?",a="Навпроти входу до печери — невелика ніша, освітлена смолоскипами, із старими бочками. На її кам'яних стінах — племінні малюнки, схожі на традиційне мистецтво тауренів, тож колись тут, певно, бували місцеві мандрівники чи мисливці.",al={"покинута печера кам'яного зсуву","печера в яру кам'яного зсуву","печера тауренів кам'яного кігтя"}},{q="Чим важливий Яр Кам'яного Зсуву?",a="Він — природний підступ до Печери Кам'яного Зсуву, підземного лігва глибоко в горах, а ще мандрівники знаходять тут цінні рудні виходи.",al={"навіщо яр кам'яного зсуву","призначення яру кам'яного зсуву"}}},fp="19,306,21.567.0,19.442.0,37.130.0,43.128.0,59.222.0,39.172.0"}
P.entries["subzone:brackenwall-village"] = {n="Село Папоротяної Стіни",s="Село Папоротяної Стіни — головний форпост Орди в Багні Пилоброду, що тулиться серед трясовин у північно-західному куті краю. Його заснували вцілілі огри Кам'яного Молота, після того як дракони спустошили їхнє давнє поселення на півдні, і тепер село — хистка твердиня в оточенні шпигунів Альянсу, дезертирів і чорних драконів.",h="Село Папоротяної Стіни — головний форпост Орди в Багні Пилоброду, що тулиться серед трясовин у...",kw={"село папоротяної стіни","багно пилоброду","кам'яний молот","огри","мок'морокк","драз'зілб","орда"},ang={["faction:Alliance"]="Папоротяна Стіна лежить глибоко на ворожій території, але розслідування зникнення дипломата й справи дезертирів-ренегатів із Терамору приведуть відважних агентів аж до краю табору огрів.",["faction:Horde"]="Папоротяна Стіна — ваш єдиний прихисток і пункт польотів у болоті; обороняючи її, ви зберігаєте для Орди важливий пост спостереження й захищений фланг проти Терамору."},sec={{t="Притулок Кам'яного Молота",b="Коли чорне драконяче кодло вигнало огрів Кам'яного Молота з їхнього давнього дому в Селі Кам'яного Молота на півдні болота, їхній ватажок — Володар Мок'Морокк, наступник Рекссара, — повів уцілілих на північ, у глиб болота, щоб збудувати Папоротяну Стіну. Поселення, що виросло довкола традиційних земляних насипів, хатин і старої сторожової вежі, дало пошарпаному кланові захищений прихисток. Хоч село й на боці Орди, воно гниє зсередини: Мок'Морокк сидить склавши руки, накопичує припаси й не хоче протистояти драконячій загрозі, лишаючи духовний і тактичний провід кланом таким постатям, як огр-маг Драз'Зілб, та посланцям Орди."},{t="Очі в болоті",b="Окрім внутрішнього розладу, Папоротяну Стіну обсідають і зовнішні загрози. Лазутчики Терамору постійно чатують у хащах, шпигують за тим, що діється в селі, і доповідають в острівну фортецю. А Павала Ріта, дезертира з Терамору, вигнаного із Загубленого Мису, підозрюють у крадіжці важливих припасів із форпосту. Під пильними поглядами зі сходу й під загрозою чорних драконів, що нишпорять на півдні, Папоротяна Стіна лишається відрізаним плацдармом Орди, який стримує і Альянс, і виводок Оніксії."}},faq={{q="Чому тут огри — союзники Орди?",a="Це огри Кам'яного Молота — шляхетний клан, який звитяжець Рекссар прийняв до сучасної Орди під час заснування Дуротара. Здолавши їхнього колишнього ватажка, Рекссар став їхнім вождем і прив'язав клан до нового союзу Вождя Тралла, а тоді передав провід Мок'Морокку.",al={"чому огри союзники орди","переказ про клан кам'яного молота","хто ці огри"}},{q="Чому Кам'яний Молот оселився тут, а не лишився в старому домі?",a="Їхнє родове поселення на півдні Багна Пилоброду захопив і стер на порох чорний драконячий рід. Володар Мок'Морокк повів уцілілих на північ, у болото, і заснував Папоротяну Стіну як укріплений прихисток.",al={"що сталося з селом кам'яного молота","чому папоротяна стіна","огри-біженці"}},{q="Хто керує Селом Папоротяної Стіни?",a="Поселенням керує Володар Мок'Морокк, але його владою чимало хто невдоволений. Замість того щоб згуртувати народ і відвоювати батьківщину чи кинути виклик драконам, він ховається в селі, а щоденні негаразди мусять розв'язувати огр-маг Драз'Зілб і посланці Орди.",al={"керівник папоротяної стіни","хто керує папоротяною стіною","мок'морокк"}},{q="Чому біля села шпигуни Терамору?",a="Попри крихке перемир'я між Терамором і Оргріммаром, військо Леді Джайни Праудмур пильно стежить за будь-якими пересуваннями військ Орди в Багні Пилоброду. Лазутчики никають околицями Папоротяної Стіни, доповідаючи про сили огрів і дії Орди.",al={"шпигуни терамору пилові болота","лазутчики терамору","чому терамор стежить"}}},fp="19,343,23.633.0,15.527.1,47.294.0,71.229.0,40.263.0,50.262.0"}
P.entries["subzone:brackwell-pumpkin-patch"] = {n="Гарбузова Ділянка Брекуеллів",s="Гарбузова Ділянка Брекуеллів — захоплена ферма на південному сході Лісу Елвінн. Колись домівку родини Брекуеллів, її поля й хатину цілком прибрало до рук Братство Дефіас як робочий сховок. Тут зустрічаються змовники-розбійники й звідси переправляють украдене золото.",h="Гарбузова Ділянка Брекуеллів — захоплена ферма на південному сході Лісу Елвінн.",kw={"гарбузова ділянка брекуеллів","ферма","братство дефіас","розбійники","принцеса","сурена каледон","ліс елвінн"},ang={["class:Warlock"]="У халупі на фермі переховується втікачка-учениця Сурена Каледон, чиє вкрадене кольє з кривавика потрібне, щоб зв'язати блукача Порожнечі.",["faction:Alliance"]="Захоплена ділянка — одна з найсхідніших робочих баз Дефіасів в Елвінні, що безпосередньо загрожує сусіднім фермам і торговим шляхам."},sec={{t="Розбійницький прихисток",b="Ферма Брекуеллів на південний схід від садиби Стоунфілдів колись була родючим клаптем елвіннської землі. Нині її законні господарі зникли безслідно — їх вигнала, а може, й гірше, хвиля злочинності, що здіймається. За їхньої відсутності Братство Дефіас захопило міцну хатину й зарослі поля ферми. Місце працює як схованка й перевалочний пункт, де розбійники перегруповуються подалі від пильних очей патрулів Ґолдшира. Помітні змовники на кшталт Морґана Збирача використовують відлюдну ділянку, щоб приймати партії золота, незаконно вкраденого з лісових копалень."},{t="Свині й темна магія",b="Дефіаси — не єдині бешкетники, що нишпорять серед гарбузового бадилля. Брекуелли лишили по собі величезну свиню-рекордистку на ім'я Принцеса, яка блукає ділянкою й без упину тероризує сусідні поля. Тим часом горище хатини та господарські будівлі приховують небезпечні особисті справи: розбійник Ерлан Драджмур звабив Сурену Каледон — ученицю-чорнокнижницю, що втекла від свого наставника в Стормвінді з украденим артефактом-кривавиком, і так привернув до сховку увагу темних практиків."}},faq={{q="Що сталося з родиною Брекуеллів?",a="Їхня доля достеменно невідома. Коли Братство Дефіас поширило свою присутність на південний схід Лісу Елвінн, Брекуеллів або змусили втекти, або вбили, а їхні гарбузові поля й хата дісталися розбійникам.",al={"де брекуелли","хто жив на фермі брекуеллів","доля родини брекуеллів"}},{q="Навіщо Братству Дефіас ця ферма?",a="Ферма — відлюдна база біля межі лісу. Тут братство зберігає награбоване й керує контрабандою — скажімо, отримує через кур'єрів на кшталт Морґана Збирача партії краденого шахтного золота — подалі від Варти Стормвінда.",al={"чому дефіас тут","що бандити роблять на ділянці","дефіас у брекуеллів"}},{q="Хто така Принцеса?",a="Принцеса — величезна свиня-призерка, яку колись виростили Брекуелли. Покинута, коли ферма впала, вона розрослася ще більше, бо раз у раз вдирається на сусідню Ферму Стоунфілдів і пожирає їхній добірний урожай.",al={"свиня принцеса","гігантська свиня","чому тут величезний кабан"}},{q="Навіщо чорнокнижники приходять на гарбузову ділянку?",a="Сурена Каледон, учениця стормвіндського наставника чорнокнижників Ґакіна Зв'язувача Темряви, викрала могутнє Намисто Кровавика й утекла на ферму, щоб сховатися там зі своїм коханцем — розбійником Дефіас Ерланом Драджмуром. Ґакін посилає сюди молодих чорнокнижників стратити її й повернути реліквію.",al={"завдання чорнокнижника брекуелл","сурена кейледон","завдання пустоти ґакіна"}}},fp="23,317,14.602.0,19.504.1,38.236.0,46.283.0,16.221.0,42.276.0"}
P.entries["subzone:brambleblade-ravine"] = {n="Яр Тернистого Клинка",s="Яр Тернистого Клинка — скелястий каньйон, що врізається в північно-східний край Плато Червоної Хмари. Це укріплене лігво шипогривів племені Щетиноспинних, які раз у раз нападають на сусіднє тауренське поселення, Табір Нарачі. Молодих тауренських сміливців посилають сюди довести свою силу й захистити батьківщину від цих лютих зайд.",h="Яр Тернистого Клинка — скелястий каньйон, що врізається в північно-східний край Плато Червоної Хмари.",kw={"яр тернистого клинка","шипогриви","щетиноспинні","плато червоної хмари","табір нарачі","шарптаск торнмантл"},ang={["faction:Horde"]="Зачистка войовничих Щетиноспинних у Яру Тернистого Клинка допомагає Орді закріпити перші позиції по всьому Малгору.",["race:Tauren"]="Для молодих тауренів, що дорослішають у Таборі Нарачі, похід у Яр Тернистого Клинка — одне з найперших випробувань бойової та духовної витривалості на захист племені."},sec={{t="Скалка в боці плато",b="Вирізьблений у випаленій сонцем землі Плато Червоної Хмари, Яр Тернистого Клинка густо заріс колючими хащами й усіяний стійбищами шипогривів. Плем'я Щетиноспинних використовує цю природну фортецю як плацдарм для наскоків на Табір Нарачі, загрожуючи безпеці молодих тауренів, що входять у зрілий вік. Шамани й воїни Щетиноспинних на чолі з Вождем Шарптаском Торнмантлом живуть у глибині яру серед вишколених бойових вепрів. Для Шу'хало удар у саме серце каньйону — водночас важливий обряд посвяти й сувора необхідність, щоб убезпечити рівнини."}},faq={{q="Що таке Яр Тернистого Клинка?",a="Яр Тернистого Клинка — каньйон на північно-східному краю Плато Червоної Хмари в Малгорі. Тут повно шипогривів Щетиноспинів, і це їхня місцева твердиня.",al={"яр тернистого клинка","що таке яр тернистого клинка","тернистий клинок мулґор"}},{q="Чому шипогриви Щетиноспини нападають звідси?",a="Щетиноспини люто стережуть свої землі й вважають присутність тауренів зазіханням на землі, які вони мають за свої. З Яру Тернистого Клинка вони раз у раз здійснюють набіги на сусідній Табір Нарачі.",al={"чому вепролюди нападають","мотиви щетиноспинів","табір нараше вепролюди"}},{q="Хто очолює шипогривів у Яру Тернистого Клинка?",a="Тутешніх шипогривів очолює Вождь Шарптаск Торнмантл — грізний ватажок, що живе у великій хижі в глибині яру.",al={"ватажок яру тернистого клинка","бос вепролюдів мулґору","вождь гострозуб тернорубаха"}},{q="Чому молоді таурени вирушають до яру?",a="Старійшини й вожді Табору Нарачі доручають молодим звитяжцям увійти в яр, відкинути загрозу Щетиноспинів, проредити їх і здолати їхніх ватажків, щоб убезпечити плато.",al={"завдання тауренів тернистого клинка","чому йти до тернистого клинка","завдання табору нараше"}}},fp="19,341,26.544.0,28.181.0,53.214.0,46.147.0,41.199.0"}
P.entries["subzone:bramblescar"] = {n="Тернистий Шрам",s="Тернистий Шрам — потужно укріплене поселення шипогривів Гостроманів на півдні Пусток. Густі колючі терновики захищають стійбище, а його мешканці ведуть жорстоку війну із суперницьким племенем Щетиноспинів по той бік Золотого Шляху.",h="Тернистий Шрам — потужно укріплене поселення шипогривів Гостроманів на півдні Пусток.",kw={"тернистий шрам","гостромани","шипогриви","щетиноспини","золотий шлях","пустки"},ang={["faction:Horde"]="Захистити Золотий Шлях від набігів шипогривів із Тернистого Шраму вкрай важливо, щоб зберегти безпечне сполучення між Перехрестям, Табором Тауражо й південним прикордонням."},sec={{t="Твердиня серед колючок",b="Тернистий Шрам, врізаний у порізані велетенські колючі хащі південних Пусток, — важливий редут шипогривів Гостроманів. Оборонні терновики виростають настільки густими й гострими, що відлякують випадкових мандрівників, але шипогриви всередині аж ніяк не мирні. Затято ревниві до своєї землі й ворожі до чужинців, вони раз у раз нападають на кожного, хто наблизиться до їхніх меж, бо вважають усіх, хто не шипогрив, загарбниками землі, благословенної їхніми давніми богами-вепрами."},{t="Кривава ворожнеча племен",b="Тернистий Шрам перебуває у вічній напрузі навпроти Аґама'ґора, через Золотий Шлях, — стійбища, яке тримає суперницьке плем'я Щетиноспинів. Два племені зчепилися в нескінченній війні за панування над південними Пустками. Відбиваючись від мандрівників Орди на шляху й відганяючи загони Щетиноспинів, воїни Гостроманів із Тернистого Шраму постійно в лютій бойовій готовності."}},faq={{q="Хто живе в Тернистому Шрамі?",a="У Тернистому Шрамі живе плем'я шипогривів Гостроманів, що боронить свій зарослий колючками табір і від суперників-шипогривів, і від усіх мандрівників, що проходять повз.",al={"хто тут","мобі тернистого шраму","вепролюди тернистого шраму"}},{q="Чому тутешні шипогриви б'ються між собою?",a="Гостромани з Тернистого Шраму й шипогриви Щетиноспини через дорогу в Аґама'ґорі — запеклі вороги, що ведуть люту кровну ворожнечу за панування на півдні Пусток.",al={"чому вони воюють","гостромани проти щетиноспинів","війна вепролюдів"}},{q="Де Тернистий Шрам?",a="Тернистий Шрам лежить на південних рівнинах Пусток, трохи на схід від головного Золотого Шляху, навпроти Аґама'ґору.",al={"місце тернистого шраму","де тернистий шрам","як знайти тернистий шрам"}},{q="Чи тутешні шипогриви ворожі до Орди?",a="Так. Шипогриви Гостромани вважають Орду загарбниками, що зазіхнули на їхні священні племінні землі, і нападають на кожного мандрівника, що підійде близько.",al={"чи тернистий шрам дружній","репутація орди тернистий шрам"}}},fp="11,238,17.466.0,17.402.0,25.164.0,46.184.0,29.121.0,43.157.0"}
P.entries["subzone:brewnall-village"] = {n="Село Брюнолл",s="Село Брюнолл — невелике дворфське поселення в Долині Холодного Вітерцю, неподалік входу до Гномреґану. Засноване родиною Барліброю, воно служить полігоном для сміливих пивоварних дослідів і місцевої оборони від диких звірів. Хоч його й називають селом, насправді це радше сільський табір у засніжених гномських низинах Дун Мороґу.",h="Село Брюнолл — невелике дворфське поселення в Долині Холодного Вітерцю, неподалік входу до Гномреґану.",kw={"село брюнолл","барліброю","пивовари","долина холодного вітерцю","гномреґан","дун мороґ"},ang={["race:Dwarf"]="Для дворфів пошук Барліброю досконалого рецепта — почесна справа, що підтримує одну з найкращих традицій Айронфорджа.",["race:Gnome"]="Розташоване поруч із Гномреґаном, село — несподівана дворфська застава глибоко в гномських долинах західного Дун Мороґу."},sec={{t="Гірке варево в долині",b="Сховане серед заметів Долини Холодного Вітерцю, Село Брюнолл лежить просто посеред споконвічних гномських земель західного Дун Мороґу. Тут живе клан Барліброю — непохитні дворфські пивовари, віддані вдосконаленню прадавніх рецептів і створенню найкращого стауту. Хоч це й зветься селом, застава складається здебільшого з наметів і просто неба розставленого пивоварного начиння, а не з кам'яних будівель. Випробовуючи дослідні партії елю й відбиваючись від лютих тутешніх вовків та ведмедів, Барліброю чимало покладаються на мандрівних горян, які збирають рідкісні інгредієнти й охороняють долину."}},faq={{q="Що таке Село Брюнолл?",a="Село Брюнолл — невеликий дворфійський табір у Долині Холодного Вітерцю на заході Дун Мороґу, трохи на схід від Гномреґана. Це застава, де клан Барліброу випробовує нові рецепти пива й дає раду місцевим звірам.",al={"де село брюнолл","що за село брюнолл","інформація про брюнолл"}},{q="Чому це звуть селом, якщо тут немає будинків?",a="Попри назву «село», це по суті табір просто неба з наметів і барил із припасами. Барліброу облаштували тут свою броварню в холодному кліматі, так і не збудувавши справжніх кам'яних осель.",al={"чому це табір","де будинки","споруди брюнолла"}},{q="Чому дворфійське поселення стоїть на гномівських землях?",a="Західна половина Дун Мороґу оточує Гномреґан і заселена здебільшого гномами, але тісний союз Айронфорджа з гномами робить спільні поселення звичною справою. Барліброу оселилися тут, у Долині Холодного Вітерцю, щоб спокійно займатися своїм ремеслом.",al={"дворфи біля гномреґану","чому дворфи тут","дворфійський табір на землях гномів"}},{q="З якими негараздами стикаються мешканці?",a="На табір часто нападають агресивні звірі долини, передусім скельні кабани, ведмеді й морозні вовки. До того ж Барліброу постійно шукають рідкісних і незвичних складників, щоб винайти нові, ще кращі напої.",al={"завдання брюнолла","що потрібно барлібрю","проблеми села"}}},fp="16,380,27.637.0,25.243.0,53.234.0,57.266.0,36.244.0"}
P.entries["subzone:brightwater-lake"] = {n="Озеро Світлої Води",s="Озеро Світлої Води — найбільша водойма Галявин Тірісфалю, що простягається оповитими імлою низинами на північний схід від Брілла. Колись тихий притулок королівства Лордерон, тепер його води холодні й темні, а посередині лежить острів, де некромант-вигнанець веде свої заборонені дослідження.",h="Озеро Світлої Води — найбільша водойма Галявин Тірісфалю, що простягається оповитими імлою низинами на...",kw={"озеро світлої води","тірісфаль","брілл","ґунтер арканус","притулок ґунтера","некромант","мурлоки"},ang={["class:Mage"]="Озеро зберігає рештки чарів давніх битв, що точилися в Тірісфалі, а також унікальну, нікому не підвладну майстерність чарівника-відступника Ґунтера Аркануса.",["race:Undead"]="Для Відступників убезпечити Озеро Світлої Води важливо, щоб боронити східні підступи до Брілла й з'ясувати, чи самостійний некромант Ґунтер Арканус стане надбанням або ворогом."},sec={{t="Води півночі",b="Озеро Світлої Води, що розкинулося північними рівнинами між містечком Брілл і Багряною Сторожовою Заставою, — тихий і моторошний орієнтир у серці Тірісфалю. Тисячі років тому його імлисті береги бачили давні битви, зокрема ранні сутички з повелителем жаху Катра'натіром. У мирні століття під владою Королівства Лордерон озеро було мальовничим сільським затишком. Сьогодні, як і решта галявин, воно давно втратило свою первозданність. Чумні Землі лежать недалеко на схід, а каламутні холодні води відбивають лише сіре небо, усохлі дерева й постійну загрозу мандрівних мурлоків і ворожої нежиті."},{t="Притулок самітника",b="Rising from the center of Brightwater Lake is an island known as Gunther's Retreat. Gunther Arcanus broke free of the Lich King's control on his own, but believed all other undead remained Scourge slaves. He isolated himself and set undead servants to guard his retreat. Bethor Iceshard seeks to show his old friend that the Forsaken also possess free will. After an adventurer proves their opposition to the Scourge, Gunther agrees to join the Forsaken."}},faq={{q="Де Озеро Світлої Води?",a="Озеро Світлої Води — на північному сході Галявин Тірісфалю, трохи на північний схід від осередку Відступників Брілла. Воно лежить просто на південь від порізаного Північного Узбережжя й на захід від Багряної Сторожової Застави, що стереже гірські перевали до Західних Чумних Земель.",al={"місце озера світлої води","де озеро світлої води","знайти озеро світлої води"}},{q="Хто живе на острові посеред озера?",a="The central island is known as Gunther's Retreat. An isolated necromancer and his undead servants dwell there, attracting the interest of the Forsaken in nearby Brill and the Undercity.",al={"хто на острові","ґюнтер арканус","неігровий персонаж острова світлої води"}},{q="Які загрози чатують біля води?",a="Travelers along the shorelines frequently encounter aggressive vile fins and murlocs scavenging the banks. Approaching the central island brings danger from the undead servants sworn to protect Gunther Arcanus from intruders.",al={"чудовиська озера","вороги світлої води","небезпеки озера світлої води"}},{q="Чому вартові в Бріллі розповідають про літній табір тут?",a="Вартові Смерті в Бріллі сухо жартують, що Відступники намагалися влаштувати на березі Озера Світлої Води дитячий літній табір, але мусили його закрити, бо там лютували психи в масках, — похмурий місцевий жарт, що перегукується з людськими страшилками біля вогнища.",al={"чутка про літній табір","жарт вартових бріллу","маскований псих табір"}}},fp="16,307,19.652.0,19.454.1,34.247.0,50.185.0,41.225.0,57.266.0"}
P.entries["subzone:brightwood-grove"] = {n="Гай Брайтвуд",s="Гай Брайтвуд — темний лісовий простір одразу на захід від Даркшира в Сутінколіссі. Колись частина мирного хліборобського краю, тепер він кишить лютими воргенами Найтбейн, що отаборилися серед зруйнованих садиб і нападають на кожного мандрівника, який підійде надто близько.",h="Гай Брайтвуд — темний лісовий простір одразу на захід від Даркшира в Сутінколіссі.",kw={"гай брайтвуд","воргени","нічна згуба","даркшир","сутінколісся"},ang={["class:Hunter"]="Темні хащі гаю — сувора місцевість для вистежування лютих воргенів Найтбейн, що перевіряє пильність кожного мисливця перед засідками за деревами.",["faction:Alliance"]="Гай Брайтвуд лежить просто за брамою Даркшира, тож знищення тутешніх зграй воргенів життєво важливе, щоб обложене місто не відрізали від заходу."},sec={{t="Гай у тіні",b="Гай Брайтвуд, що видніється просто з околиць Даркшира, уособлює повзучу небезпеку, яка загрожує межам міста. Садиби й огорожі, що колись розмежовували мирні ниви, тепер повалені й гниють. На їхньому місці воргени Найтбейн спорудили грубі табори й никають зарослими галявинами. Близькість цих вовкоподібних звірів — постійна загроза для міста, тож Нічна Варта й перехожі шукачі пригод мусять раз у раз проріджувати їхні лави, доки вони не захопили поселення."}},faq={{q="Де Гай Брайтвуд?",a="Гай Брайтвуд — на сході Сутінколісся, трохи на захід від містечка Даркшир, уздовж головних стежок.",al={"місце гаю брайтвуд","де гай брайтвуд","брайтвуд сутінковий ліс"}},{q="Які істоти живуть у Гаю Брайтвуд?",a="Гай заполонили дикі воргени Найтбейн. Ці прокляті вовколюди влаштували грубі табори в зруйнованих будівлях і нападають на кожного, хто наближається.",al={"чудовиська гаю брайтвуд","вороги брайтвуда","що живе в брайтвуді"}},{q="Чим гай небезпечний для Даркширу?",a="Гай Брайтвуд лежить одразу на захід від Даркширу, тож агресивні зграї воргенів у хащах — пряма загроза міським патрулям, шляхам постачання й усім мандрівникам, що прибувають дорогою.",al={"чому гай небезпечний","загроза брайтвуда даркширу"}},{q="Чи є в гаю дружні поселення?",a="Ні. Кілька кам'яних будівель і хуторів на околицях гаю цілком зруйновані, покинуті на поталу негоді й захоплені мандрівними воргенами.",al={"чи є дружні в брайтвуді","містечко брайтвуд"}}},fp="16,279,17.516.0,26.111.0,40.174.0,40.207.0,48.152.0"}
P.entries["subzone:brill"] = {n="Брілл",s="Брілл — головне поселення Відступників в серці Галявин Тірісфалю, одразу на північ від Руїн Лордерона. Колись квітуче людське містечко, тепер воно править за адміністративний і військовий осередок для щойно пробуджених мерців, що виходять за межі Похоронного Подзвону.",h="Брілл — головне поселення Відступників в серці Галявин Тірісфалю, одразу на північ від Руїн Лордерона.",kw={"брілл","тірісфаль","відступники","цепелін","магістрат севрен","таверна шибеничний кінець","культ проклятих"},ang={["faction:Horde"]="Пристань цепелінів за містом — головна ланка північної Орди між Лордероном і союзними твердинями в Калімдорі та Східних Королівствах.",["race:Undead"]="Для Відступників, що вирушають із Похоронного Подзвону, Брілл — перший проблиск цивілізації й місце, де починають доводити вірність Темній Леді."},sec={{t="Від чумної землі до бастіону",b="До Третьої війни Брілл був жвавим селом під владою місцевих дворян — родин Барових і Аґамандів. Цьому добробуту настав кінець, коли Кел'Тузад обрав ці місця для найперших дослідів Культу Проклятих із Чумою Нежиті. Спустошлива пошесть прокотилася населенням так швидко, що місцеве ополчення було вибите, а по собі лишила величезне братське кладовище.\n\nТепер, відбудований Відступниками під проводом Магістрата Севрена, Брілл зберігає обвітрену лордеронську архітектуру під покровом похмурої цілеспрямованості. Містечко править за командний центр краю, координуючи оборону від вторгнень Багряного Хрестового Походу, мандрівних решток Погибелі та місцевих звірів, спотворених некромантичним тлінням."},{t="Перехрестя північного Лордерона",b="Окрім місцевої оборони, Брілл — важливе перехрестя, що з'єднує Галявини Тірісфалю з рештою Орди. Над головою гоблінська вежа цепелінів забезпечує сполучення на південь, до Дуротару, і вглиб Долини Стренглторну. У самому поселенні Таверна «Шибеничний Кінець» править не лише за темний прихисток для подорожніх, а й за імпровізовану лабораторію, де полонених багряних фанатиків допитують і піддають аптекарським дослідам."}},faq={{q="Хто править Бріллом?",a="Магістрат Севрен керує цивільним управлінням і місцевою обороною Брілла від імені Леді Сильвани Віндраннер і Відступників.",al={"хто править бріллом","хто керує бріллом","магістрат бріллу"}},{q="Чому під Бріллом такий величезний цвинтар?",a="Саме в Бріллі Кел'Тузад провів одні з перших дослідів Чуми Нежиття на живих. Зараза з жахливою швидкістю викосила місцевих людей, тож довелося влаштувати велике кладовище, щоб поховати жертв, перш ніж вони повстануть як Погибель.",al={"цвинтар біля бріллу","кладовище під бріллом","чому стільки могил"}},{q="Для чого Таверна «Шибеничний Кінець»?",a="Окрім того що тут ночують утомлені мандрівники, підвал таверни правує за базу для аптекарів, які проводять хімічні й токсикологічні досліди на полонених фанатиках Багряного Хрестового Походу.",al={"шибеничний кінець","корчма бріллу","що відбувається в таверні бріллу"}},{q="Куди літає цепелін із вежі під Бріллом?",a="Вежа цепелінів, яку обслуговують гобліни, сполучає Лордерон просто з Калімдором під Оргріммаром, а також на півдні — з Базовим Табором Ґром'ґол у Долині Стренглторну.",al={"куди летять цепеліни бріллу","куди літають дирижаблі з бріллу","маршрути польотів бріллу"}}},fp="5,273,29.744.0,32.429.0,16.135.0,52.252.0,37.176.0,54.164.0"}
P.entries["subzone:brill-town-hall"] = {n="Ратуша Брілла",s="Ратуша Брілла — адміністративне серце поселення Брілл у центральних Галявинах Тірісфалю. Найпомітніша будівля містечка, вона править за цивільний штаб, звідки Відступники керують своїми місцевими володіннями й координують оборону галявин.",h="Ратуша Брілла — адміністративне серце поселення Брілл у центральних Галявинах Тірісфалю.",kw={"ратуша брілла","брілл","магістрат севрен","відступники","врядування","тірісфаль"},ang={["faction:Horde"]="Союзники Орди, прибувши в Тірісфаль, можуть завітати до ратуші, щоб зрозуміти, як Відступники підтримують цивільну владу й військовий лад на своїх потемнілих рідних землях.",["race:Undead"]="Для Відступників, що вирушають із Похоронного Подзвону, ратуша — перший смак упорядкованого цивільного врядування в державі Королеви Сильвани, де офіційно організовують місцеву оборону й відновлення."},sec={{t="Цивільний осідок Відступників",b="Поки значна частина Лордерона лежить розбита й зруйнована, Ратуша Брілла досі стоїть як діючий громадський центр під владою нежиті. Усередині Магістрат Севрен керує справами містечка зі свого подіуму, роздаючи шукачам пригод Відступників важливі доручення й розпорядження. Якщо не рахувати Лігва Осквернителя в Аратійському нагір'ї, це одна з небагатьох визнаних ратуш у відомому світі, якою справді керують Відступники, — похмура пародія й водночас дієве продовження міської бюрократії старого Лордерона."}},faq={{q="Для чого Ратуша Брілла?",a="Це місцеве осердя влади поселення Брілл. Провід Відступників, передусім Магістрат Севрен, звідси організовує місцеву оборону, видає укази й доручає важливі справи мандрівникам і щойно пробудженій нежиті.",al={"призначення ратуші бріллу","що це за будівля","чому відвідати ратушу бріллу"}},{q="Хто тут головний?",a="Магістрат Севрен керує ратушею зі своєї кафедри: він веде міські справи від імені Відступників і спрямовує дії по всьому центру Галявин Тірісфалю.",al={"хто керує ратушею бріллу","керівник ратуші бріллу","хто магістрат"}},{q="Чим ця ратуша особлива порівняно з іншими?",a="Ратуші — зазвичай пережиток живих людських королівств. Ратуша Брілла особлива тим, що це одна з небагатьох діючих громадських зал, які утримують Відступники; таке є хіба що в місцях на кшталт Лігва Осквернителя на Аратійському нагір'ї.",al={"унікальна ратуша відступників","чи є інші ратуші відступників"}}},fp="15,278,26.509.0,37.251.0,22.176.0,49.226.0"}
P.entries["subzone:broken-hall"] = {n="Зруйнована Зала",s="Зруйнована Зала — затоплений зовнішній поріг затонулого Храму Атал'Гаккара на Болоті Скорботи. Вона розкололася, коли Ізера, Аспект драконів, разом зі своєю зграєю потягла величний зикурат під воду, і нині ці руїни стоять покинуті, бо фанатики Атал'аї відступили в глибші святилища.",h="Зруйнована Зала — затоплений зовнішній поріг затонулого Храму Атал'Гаккара на Болоті Скорботи.",kw={"зруйнована зала","храм атал'гаккара","затонулий храм","атал'аї","ізера","болото скорботи"},ang={["race:Troll"]="Для тролів, які шанують лоа, Зруйнована Зала — похмуре нагадування про загибель, що спіткала фанатиків Атал'аї, які пішли проти решти свого народу, аби служити Гаккарові Душолупу."},sec={{t="Затоплений поріг",b="Коли зелені дракони обрушили свій гнів на жрецтво Атал'аї й занурили їхній нечестивий зикурат у Ставок Сліз, найбільше від катаклізму постраждали зовнішні споруди. Підлога Зруйнованої Зали повністю обвалилася, і каламутна болотяна вода затопила приміщення. Через руйнування й затоплення тролі-культисти покинули цю вхідну залу й відступили вглиб комплексу. Шукачам пригод, які проникають до затонулого храму, доводиться брести цими розмоклими руїнами, перш ніж піднятися сходами до Зали Масок."}},faq={{q="Що таке Зруйнована Зала?",a="Це крайня вхідна зала Храму Атал'Гаккара, одразу за затопленим входом під Ставком Сліз.",al={"огляд зруйнованої зали","що це за місце","вхідна зала храму"}},{q="Чому Зруйнована Зала затоплена й зруйнована?",a="Залу зруйновано, коли зелений драконячий рід затягнув увесь храм під болотяні води, щоб зупинити закликання Бога Крові Гаккара: підлога тріснула, а залу затопило.",al={"чому зруйнована зала мокра","чому зала затоплена","хто зруйнував залу"}},{q="Чи живуть у цій залі тролі Атал'аї?",a="Сама Зруйнована Зала здебільшого покинута. Після затоплення верхнього храму культисти Атал'аї відступили в сухіші, зручніші для оборони зали глибше в комплексі.",al={"вороги зруйнованої зали","чи порожня зруйнована зала"}},{q="Куди ведуть сходи у Зруйнованій Залі?",a="Піднявшись кам'яними сходами із затопленої Зруйнованої Зали, дослідники потрапляють просто до Зали Масок.",al={"сходи зруйнованої зали","вихід зруйнованої зали","куди йти зі зруйнованої зали"}}},fp="11,304,17.555.0,24.141.0,42.193.0,49.184.0,44.115.0"}
P.entries["subzone:broken-pillar"] = {n="Зламаний Стовп",s="Зламаний Стовп — вивітрене скупчення прадавніх тролячих руїн, що стирчать із дюн на південь від Ґаджетзана. Тут облаштував відлюдну дослідницьку станцію гоблін-старатель і вчений Марвон Рівітсікер, який вивчає загадкові артефакти, поховані в довколишніх пісках.",h="Зламаний Стовп — вивітрене скупчення прадавніх тролячих руїн, що стирчать із дюн на південь від Ґаджетзана.",kw={"зламаний стовп","марвон рівітсікер","ґаз'рідіан","тролячі руїни","ґаджетзан","танаріс"},ang={["race:Gnome"]="Цікавість, що рухає дослідженнями Марвона Рівітсікера, який вивчає невідомі властивості реліквій, перегукується з гномівськими науковими амбіціями, хоча методи в нього суто гоблінські.",["race:Troll"]="Ці розсипані стовпи — урочисті знаки прабатьківської тролячої архітектури, відлуння доби, коли влада імперії над південним Калімдором ще не розкришилася під тиском часу й піску."},sec={{t="Вибілене сонцем каміння",b="Зламаний Стовп здіймається з пісків на південь від Ґаджетзана й на схід від підступних Пісків Безодні та позначає рештки прадавньої тролячої архітектури, яку давно поглинув Танаріс. Попри безлюдну місцевість і пустельних звірів, що підступають дедалі ближче, тут можна натрапити на рідкісні підказки про доісторичні цивілізації континенту. Марвон Рівітсікер, гоблін-дослідник, який раніше працював у Раджеті, розбив біля розтрощеної кладки самотній табір, щоб вивчати дивні реліквії, відомі як ґаз'рідіан, розкидані по всій пустелі."}},faq={{q="Що таке Зламаний Стовп?",a="Зламаний Стовп — давні тролячі руїни в центрі Танаріса, на південь від Ґаджетзана й на схід від Пісків Безодні. Від первісної споруди лишилися хіба вивітрені кам'яні стовпи й уламки, напівзасипані мінливими дюнами.",al={"зламаний стовп танаріс","що таке зламаний стовп","руїни стовпа"}},{q="Хто отаборився біля Зламаного Стовпа?",a="Марвон Рівітсікер — допитливий гоблін-науковець і шукач із Раджета — влаштував серед руїн самотній дослідницький табір. Він вивчає загадкові прикраси Ґаз'рідіан, поховані в навколишній пустелі.",al={"хто біля зламаного стовпа","неігровий персонаж зламаного стовпа","місце марвона ріветсікера"}},{q="Хто збудував тутешні руїни?",a="Кладка тролячої роботи — вона сягає часів, коли давні тролячі імперії панували на півдні Калімдору, задовго до того, як край поглинули піски.",al={"хто збудував зламаний стовп","історія зламаного стовпа","походження зламаного стовпа"}},{q="Що таке реліквії Ґаз'рідіан?",a="Ґаз'рідіан — давні кам'яні артефакти й різьблені личини, поховані в пісках Танаріса. Марвон Рівітсікер вивчає їх у своєму таборі біля Зламаного Стовпа, щоб розгадати таємниці й силу, приховані в мистецтві зниклої імперії.",al={"ґаз'рідіан","що таке ґаз'рідіан","предмети завдань марвона"}}},fp="13,279,18.526.0,26.242.0,35.228.0,34.177.0,28.228.0"}
P.entries["subzone:bronzebeard-encampment"] = {n="Табір Бронзоборода",s="Табір Бронзоборода — суворий дворфійський форпост на півдні Силітусу, трохи на схід від величезної Стіни Скарабея. Тут працюють загартовані мандрівники й науковці з Ліги Дослідників, і табір слугує базою для вивчення прадавніх гліфів силітидів і таємниць, похованих під пустельними пісками.",h="Табір Бронзоборода — суворий дворфійський форпост на півдні Силітусу, трохи на схід від величезної Стіни...",kw={"табір бронзоборода","ліга дослідників","силітус","стіна скарабея","дворфи","гліфи"},ang={["faction:Alliance"]="Для мандрівників з Альянсу, що пробираються похмурими просторами Силітусу, цей віддалений табір — бажаний дружній форпост далеко на південь від Цитаделі Кенаріуса.",["race:Dwarf"]="Форпост показує незламну впертість Ліги Дослідників і доводить, що для дворфів Айронфорджа, які шукають історичної правди, немає надто ворожої пустелі."},sec={{t="Опора серед мінливих пісків",b="Табір Бронзоборода, що притулився до безлюдних південних круч Силітусу, — рідкісний прихисток дворфійської витривалості в цілком ворожій пустелі. Заснований завдяки археологічним прагненням Айронфорджа, табір стоїть так, що звідси видно височенну Стіну Скарабея. Тут дослідники на кшталт Рутґара Ґліфшейпера й Франкала Стоунбриджа долали пекучу спеку, скорпідів і навали силітидів, щоб вивчати дивні написи й пам'ятки, залишені забутими цивілізаціями."},{t="Гліфи й відчай",b="Життя в таборі — аж ніяк не тихі розкопки. Загроза силітидів розповзається з підземних вуликів по всій пустелі, а неподалік у пісках нишпорять небезпечні жахіття на кшталт страхітливого скорпіда Смертохвата, тож форпост мусить поєднувати ретельну науку з боротьбою за виживання. Дослідники покладаються на заїжджих шукачів пригод: ті здобувають відбитки загадкових гліфів, допомагають розшифрувати прадавні мови комах і шукають зниклих товаришів, які забрели надто глибоко в божевілля пустелі."}},faq={{q="Де Табір Бронзоборода?",a="Табір — на півдні Силітусу, на схід від колосальної Стіни Скарабея й на північ від південного гірського хребта.",al={"де табір бронзоборода","місце табору бронзоборода","як знайти табір бронзоборода"}},{q="Хто керує Табором Бронзбірда?",a="У таборі працюють члени й соратники дворфійської Ліги Дослідників, зокрема дослідник гліфів Рутґар Ґліфшейпер, Франкал Стоунбридж і їхній супутник Ґлібб.",al={"хто в таборі бронзоборода","неігрові персонажі табору бронзоборода","хто керує табором бронзоборода"}},{q="Що тут вивчають дворфи?",a="Дослідники розшифровують давні кам'яні гліфи, з'ясовують, як спілкуються силітиди, і розкопують давно поховані таємниці півдня Калімдору.",al={"чому дворфи в сілітусі","що вивчає рутґар","призначення табору бронзоборода"}},{q="Які загрози чатують біля табору?",a="Навколишньою пустелею никають агресивні силітиди, піщані скорпіони й горезвісний велетенський скорпід Смертохват, Жах Пісків, що гніздиться трохи на південний схід.",al={"небезпеки біля табору бронзоборода","місце дезклеспа","чудовиська табору бронзоборода"}}},fp="22,331,32.498.0,22.486.0,44.131.0,36.178.0,35.176.0,38.187.0"}
P.entries["subzone:browman-mill"] = {n="Тартак Броумена",s="Тартак Броумена — сплюндрована лісопильня трохи на північ від Каплиці Надії Світла у Східних Чумних землях. Колись важлива частина лісоторгівлі Лордерону, тепер вона кишить прислужниками-нежиттю під залізною владою Погибелі. Її колишній власник, Стівен Броумен, і після смерті лишається в пастці свого зруйнованого цеху.",h="Тартак Броумена — сплюндрована лісопильня трохи на північ від Каплиці Надії Світла у Східних Чумних землях.",kw={"тартак броумена","стівен броумен","східні чумні землі","каплиця надії світла","погибель","нежить"},ang={["class:Paladin"]="Осквернені рештки тартака й змучені духи, що блукають його територією, — саме те, від чого святі ордени борються очистити Лордерон.",["race:Undead"]="Поневолення Стівена Броумена — суворе нагадування про долю всіх жертв Короля-Ліча, яким не дісталася вільна воля, виборена Відступниками."},sec={{t="Зруйнований промисел",b="До Третьої війни Тартак Броумена обслуговував довколишні містечка й обійстя Лордерону, обробляючи деревину з багатих лісів Східнолісся. Коли чума Погибелі прокотилася королівством, тартак загинув разом з усією провінцією. Нині гнилі колоди й розтрощені колеса стоять без діла, а довкола патрулюють гидоти, баньші та воїни-скелети. Через близькість до Каплиці Надії Світла тартак — постійне й грізне нагадування про орду нежиті, що тисне на самий поріг Срібного світанку."},{t="Доля наглядача",b="Перший власник тартака, Стівен Броумен, спіткав ту саму похмуру долю, що й незліченні прості люди Лордерону. Убитий, коли Погибель заполонила маєток, він повстав у нежитті ненажерливим гулем. Позбавлений людяності й поневолений волею Короля-Ліча, Броумен блукає в темних стінах свого колишнього тартака, стережучи розтрощені руїни справи всього свого життя."}},faq={{q="Де Тартак Броумена?",a="Тартак Броумена — на крайньому сході Східних Чумних земель, просто на північ від Каплиці Надії Світла.",al={"місце тартака броумена","де тартак броумена","як знайти тартак броумена"}},{q="Які вороги живуть на тартаку?",a="Подвір'я кишить силами Погибелі: тут і кремезні гидоти, і банші, що голосять, і кістяні потвори, і мандрівні гулі.",al={"мобі тартака броумена","хто на тартаку броумена","що живе на тартаку броумена"}},{q="Хто такий Стівен Броумен?",a="Стівен Броумен був першим господарем тартаку з людей. Він загинув під час падіння Лордерона й повстав гулем, прикутим стерегти свою зруйновану будівлю.",al={"хто такий стівен броумен","переказ про стівена броумена","гуль броумена"}},{q="Чому Тартак Броумена небезпечний для мандрівників?",a="Через велике скупчення могутньої нежиті це смертельно небезпечне місце — тим паче що воно лише за кілька хвилин їзди на північ від твердині Срібного Світанку в Каплиці Надії Світла.",al={"чому тартак броумена небезпечний","загроза тартака броумена"}}},fp="12,323,17.538.0,19.371.0,30.125.0,38.134.0,24.196.0,43.175.0"}
P.entries["subzone:bulwark"] = {n="Заслон",s="Заслон — укріплена застава на межі Галявин Тірісфалю й Західних Чумних Земель. Її спільно утримують Відступники й нейтральний Срібний світанок; це передова Орди проти Погибелі й головний вихідний пункт для походів на отруєний схід.",h="Заслон — укріплена застава на межі Галявин Тірісфалю й Західних Чумних Земель.",kw={"заслон","тірісфаль","відступники","срібний світанок","західні чумні землі","орда","погибель"},ang={["faction:Horde"]="Для Орди Заслон — те саме, що для Альянсу Табір Студеного Вітру: головна брама й штаб для всіх операцій у Чумних Землях.",["race:Undead"]="Для Відступників Заслон — ключова вузька шийка, що не дає арміям Короля-Ліча рушити просто на Брілл і Андерсіті."},sec={{t="Щит проти Погибелі",b="Заслон стоїть просто на східній межі Галявин Тірісфалю й лишається останньою перепоною, що захищає серцеві землі Відступників від чумних жахів Західних Чумних Земель. Під час навали Погибелі на Лордерон тут стояв табір під проводом Утера Світлоносця, де знаходили прихисток уцілілі, що тікали з руїн Столичного Міста. Нині неотесані дерев'яні частоколи й добре озброєна варта боронять прохід від блукаючої нежиті. Заслон — це непевна, але необхідна співпраця: сили Відступників діють разом зі Срібним світанком, вербуючи загартованих поборників Орди, щоб відкидати поплічників Короля-Ліча, перш ніж ті ринуть у Тірісфаль."}},faq={{q="Навіщо Заслон?",a="Заслон — перший оборонний гарнізон і плацдарм Орди проти Погибелі. Він захищає Галявини Тірісфалю й Андерсіті від навали із Західних Чумних Земель, а ще тут перебувають командири Срібного Світанку й Відступників, що організовують наступ на отруєні землі.",al={"чому заслон тут","призначення заслону","що це за місце"}},{q="Чи можуть персонажі Альянсу прийти на Заслон, щоб поговорити зі Срібним Світанком?",a="Ні. Представники Срібного Світанку тут нейтральні, але табір щільно охороняють вартові Відступників. На кожного члена Альянсу, що ступить за частокіл, нападуть, щойно побачать.",al={"чи альянс може користуватися заслоном","альянс на заслоні","чи заслон лише для орди"}},{q="Що тут було до того, як Відступники звели укріплення?",a="Під час Третьої війни й падіння Столиці Утер Світлоносець влаштував тут тимчасовий табір, щоб прихистити й захистити людей, які тікали від першої навали Погибелі на Лордерон.",al={"історія заслону","переказ про заслон","табір утера"}},{q="Чи безпечний Заслон для молодих шукачів пригод, що покидають Тірісфаль?",a="Ні. Брама межує просто з Галявинами Тірісфалю, але Західні Чумні Землі за нею кишать смертоносною нежиттю високого рівня й чумними казанами. Новачків, що забредуть за частокіл, чекає швидка смерть.",al={"чи низькорівневі можуть пройти заслон","вхід до чумних земель низького рівня"}}},fp="7,300,28.665.0,35.301.0,72.208.0,58.213.0,59.216.0"}
P.entries["subzone:burning-blade-coven"] = {n="Ковен Палаючого Клинка",s="Схований у північних скелях Долини Випробувань, Ковен Палаючого Клинка — заражена мережа печер, що загрожує найновішим новобранцям Орди. Усередині чаяться осквернені культисти й прикликані демони, перетворивши стару мінеральну печеру на плацдарм темної магії просто на порозі Дуротару.",h="Схований у північних скелях Долини Випробувань, Ковен Палаючого Клинка — заражена мережа печер, що загрожує...",kw={"ковен палаючого клинка","культисти","демони","біси","печера","долина випробувань","ярроґ бейншедов"},ang={["class:Warlock"]="Демонічні біси й темні обряди тут — ранній застережливий погляд на те, що стається, коли силу Скверни пускають у хід безоглядно, у відкритому непослуху Орді.",["race:Orc"]="Присутність культу Палаючого Клинка так близько до Долини Випробувань — нестерпна образа для нової Орди Тралла й суворе нагадування про поклоніння демонам, яке орки так боролися залишити позаду."},sec={{t="Тінь над полігоном",b="Запилені червоні гори, що обступають Долину Випробувань, колись були просто дикою місциною для випробувань молодих орків і тролів Темного Списа, які робили перші кроки на службі Орді. Та нещодавно північні печери охопили темні обряди. З гирла печери висипають біси та дрібні демони, сіючи хаос і загрожуючи новобранцям. Культ Палаючого Клинка на чолі з потаємним чорнокнижником Ярроґом Бейншедовом міцно окопався в глибині, перетворивши колись звичайний тренувальний майданчик на справжнє поле бою з демонічним скверненням."},{t="Скверна в скелях",b="Ще до того, як тут укорінилися демони, печери привернули увагу місцевих наглядачів, що сподівалися добути сировину для поселення. Наглядач Тазз'ріл спустився вглиб із мінеральною розвідкою, та його поспіхом вигнали, і він покинув цінне спорядження, коли культисти дали про себе знати. Нині відтіснити ковен Бейншедова — найголовніше випробування для майбутніх воїнів, розбійників і чаклунів, перш ніж їх визнають готовими вийти в ширший Дуротар."}},faq={{q="Де Ковен Палаючого Клинка?",a="Печера врізана у високі червоні скельні хребти просто вздовж північного краю Долини Випробувань у Дуротарі.",al={"місце ковену","де ковен палаючого клинка","місце печери в долині"}},{q="Хто очолює тутешніх культистів?",a="Ковен очолює чорнокнижник на ім'я Ярроґ Бейншедов, що керує місцевими обрядами й командує закликаними демонами.",al={"ватажок ковену","хто очолює ковен палаючого клинка","яррог"}},{q="Які вороги чаяться всередині?",a="Печера кишить свавільними бісами, дрібними демонічними прислужниками й смертними послушниками, вірними зловісному культу Палаючого Клинка.",al={"які мобі в печері","чудовиська ковену","демони в долині випробувань"}},{q="Навіщо новобранці заходять у печеру?",a="Спуститися в темні глибини печери, повернути загублене знаряддя на кшталт кайла Наглядача Тазз'ріла й убити Ярроґа Бейншедова — останній обряд посвяти для нових шукачів пригод з орків і тролів, перш ніж вони покинуть долину.",al={"навіщо йти до ковену","призначення ковену","останнє випробування ковену"}}},fp="19,297,33.554.0,23.490.0,41.117.0,28.118.0,34.127.0,37.216.0"}
P.entries["subzone:caer-darrow"] = {n="Каер Дарроу",s="Каер Дарроу — укріплений острів на Озері Дарроумер у Західних Чумних Землях. Колись тут був родовий маєток шляхетного Дому Баровів, але твердиню острова потай продали Кел'Тузадові й перетворили на школу некромантії Сколомансію, а місто нагорі заполонили блукаючі привиди.",h="Каер Дарроу — укріплений острів на Озері Дарроумер у Західних Чумних Землях.",kw={"каер дарроу","дім баровів","сколомансія","озеро дарроумер","кел'тузад","альтерак","друга війна"},ang={["faction:Alliance"]="Для Альянсу Каер Дарроу — це дві глибокі зради: засідка альтерацьких каперів у Другій війні, що викрила зраду короля Перенольда, і продаж Домом Баровів власного родового гнізда Кел'Тузадові.",["race:Human"]="Люди впізнають у цьому острові колишній маєток Дому Баровів — колись однієї з найбагатших шляхетних родин Лордерону, аж доки жадібність не штовхнула їх до угод із Культом Проклятих."},sec={{t="Спадок війни й зради",b="Задовго до Погибелі Каер Дарроу був стратегічною твердинею Лордерону, де зберігався прадавній ельфійський руновий камінь. Під час Другої війни Орда розграбувала фортецю й розколола руновий камінь, щоб збудувати з нього Вівтарі Бур Ґул'дана. Коли лорд Утер Світлоносець приплив, аби допомогти вцілілим, його флот потрапив у засідку альтерацьких каперів, — і саме ця підступність викрила перед Альянсом зраду Альтераку."},{t="Падіння Дому Баровів",b="Відбудований після Другої війни, Каер Дарроу став розкішним маєтком родини Баровів, яка мала земельні грамоти на угіддя в Бріллі, Таррен Міллі й Саутшорі. Відчайдушно прагнучи вберегти свої статки й життя, коли підступала старість, Барови уклали угоду з Кел'Тузадом. Під фортецею пустив коріння Культ Проклятих і заснував Сколомансію. Ще до того як Третя війна прокотилася Лордероном, на слуг і містян острова наслали першу, пробну чуму. Мешканці загинули й тепер приречені блукати зруйнованою твердинею неупокоєними відлуннями."}},faq={{q="Що таке Каер Дарроу?",a="Каер Дарроу — острівна фортеця на Озері Дарроумер у Західних Чумних Землях. Колись горда родова садиба заможної родини Баровів, нині це моторошні руїни, у катакомбах яких розташована некромантична академія Сколомансія.",al={"огляд каер даррову","що це за місце","переказ про каер дарроу"}},{q="Чому містечко покинуте й зруйноване?",a="Родина Баровів уклала угоду з Кел'Тузадом: віддала свій маєток Культу Проклятих в обмін на безсмертя. Культ використав челядь замку для перших некромантичних дослідів, а тоді наслав на все поселення смертельну чуму — ще до того, як почалося ширше вторгнення в Лордерон.",al={"чому каер дарроу зруйноване","що сталося з каер дарроу","історія каер дарроу"}},{q="Чому я не бачу привидів у містечку?",a="Убиті мешканці Каер Дарроу блукають неспокійними духами, застиглими у свої останні миті. Звичайне око їх не бачить — потрібен особливий магічний зір, як-от Примарна Есенція, яку дають духи Еви й Люсьєна Саркгоффів.",al={"де привиди","невидимі люди каер дарроу","як побачити привидів"}},{q="Що за рунний камінь колись тут був?",a="Під час Другої війни в Каер Дарроу зберігався давній рунний камінь високих ельфів. Орда напала на острів і розтрощила священний камінь на шматки, з яких Ґул'дан збудував Вівтарі Бур, щоб спрямовувати магію в огрів-магів.",al={"рунний камінь каер дарроу","ельфійський рунний камінь","камінь вівтаря бур"}},{q="Що під фортецею?",a="Під замком лежить Сколомансія — штаб і навчальна академія Культу Проклятих. Під проводом Темного Майстра Ґандлінґа некроманти й послушники вивчають там темні мистецтва й проводять досліди на мертвих.",al={"що під каер дарроу","що в підвалі","підземелля під каер дарроу"}}},fp="11,317,28.424.0,23.548.1,20.236.0,37.298.0,39.248.1,44.232.0,32.217.0"}
P.entries["subzone:calmbreeze-inn"] = {n="Корчма «Тихий Вітерець»",s="Корчма «Тихий Вітерець» — так звуться головні заклади Острова Зефрас, де можна знайти прихисток і послуги: вони є і в Селі Шен'дар, і у Валанаарі. Це важливі зупинки для мандрівників, що досліджують острів: тут працюють місцеві наставники ремесел і корчмарі, а також зберігаються історичні реліквії.",h="Корчма «Тихий Вітерець» — так звуться головні заклади Острова Зефрас, де можна знайти прихисток і послуги...",kw={"корчма тихий вітерець","острів зефрас","село шен'дар","валанаар","корчма","наставники ремесел"},ang={["class:Rogue"]="Міріанн Містблейд навчає розбійницького ремесла біля вогнища корчми «Тихий Вітерець» у Селі Шен'дар.",["profession:Herbalism"]="Травники, що завітають до Села Шен'дар, можуть знайти в корчмі «Тихий Вітерець» Галассу Фернбріз і відточити своє ремесло збирача."},sec={{t="Відпочинок на острові",b="Корчми «Тихий Вітерець» дають прихисток серед звивистих стежок Острова Зефрас. У Селі Шен'дар корчму тримає Коріелла Калмбріз, і там же збираються острівні ремісники — зокрема наставники травництва, знімання шкур і зачарування. А у Валанаарі ще одна корчма «Тихий Вітерець» приймає місцевих подорожніх і зберігає рідкісні дивовижі, серед них — звуковий кристал із записом історії давнього повстання в Ельдре'Таласі."}},faq={{q="Де корчми «Тихий Вітерець»?",a="Корчми «Тихий Вітерець» є і в Селі Шен'дар, і у Валаанарі на Острові Зефрас.",al={"місце корчми тихий вітерець","де корчма тихий вітерець","карта корчми тихий вітерець"}},{q="Хто тримає корчму в Селі Шен'дар?",a="Корчмою в Селі Шен'дар опікується корчмарка Коріелла Калмбріз, що гостинно приймає і мешканців острова, і мандрівників.",al={"корчмар тихого вітерця","хто тримає корчму тихий вітерець"}},{q="Яких наставників можна знайти в корчмі?",a="У Селі Шен'дар у корчмі є Галасса Фернбріз (Травництво), Мендаласс Таттерменд (Білування), Насаланна Віндсінґер (Накладання чарів) і Міріанн Містблейд (наставниця розбійників).",al={"наставники тихого вітерця","наставники корчми шен'дар"}},{q="Що за звуковий кристал нагорі у Валаанарі?",a="Нагорі в корчмі Валаанара лежить звуковий кристал із третьою частиною «Повстання в Ельдре'Таласі» — літопису історичних подій давнього міста Високородних.",al={"звуковий кристал валаанара","кристал заколоту ельдре'таласа"}}},fp="14,286,16.458.0,38.92.0,37.139.0,38.183.0,53.166.0"}
P.entries["subzone:camp-aparaje"] = {n="Табір Апараже",s="Колись Табір Апараже був мирним тауренським селищем у східних височинах Гір Кам'яного Кігтя. Нині його захопило вороже плем'я Ґрімтотем: вони вирізали поселенців і забрали заставу собі.",h="Колись Табір Апараже був мирним тауренським селищем у східних височинах Гір Кам'яного Кігтя.",kw={"табір апараже","ґрімтотем","гори кам'яного кігтя","ґрундіґ дарклауд","макаба флетгуф","таурени"},ang={["faction:Horde"]="Вигнати Ґрімтотемів із Табору Апараже — це і помста, і оборона: віроломне плем'я має відповісти за різанину безневинних підданих Орди в Горах Кам'яного Кігтя.",["race:Tauren"]="Руїни Табору Апараже — гірке нагадування про жорстокість племені Ґрімтотем, яке веде Маґата. Вони доводять, що не всі діти Земної Матері поділяють бачення честі й миру, яке плекає Кайрн Бладгуф."},sec={{t="Трагічний занепад",b="Табір Апараже на кручах Гір Кам'яного Кігтя заснували мирні таурени, які хотіли спокійно жити у височинах. Той спокій розлетівся на друзки, коли нападники з сусідньої Застави Ґрімтотем на чолі з Ґрундіґом Дарклаудом без жодної причини люто вдарили по селищу. Мешканців вирізали або прогнали, а вцілілі — як-от Макаба Флетгуф — оплакують зруйнований дім і зі страхом думають про долю родичів, що потрапили в полон."},{t="Під владою Ґрімтотемів",b="Тепер Табір Апараже цілком зайняли воїни Ґрімтотем, і плем'я зробило його своєю передовою базою в цьому краї. На відміну від звичних поселень Ґрімтотем, де майорять сині знаки, великий тотем в Апараже розмальовано густою багряною фарбою."}},faq={{q="Хто колись жив у Таборі Апараже?",a="У Таборі Апараже жили мирні таурени, пов'язані з Ордою й племенем Бладгуф, зокрема Макаба Флетгуф і його донька Кая, — доки на поселення не напали.",al={"хто жив тут","первісні мешканці табору апараже","село макаби флетгуфа"}},{q="Чому табір ворожий до гравців Орди?",a="Село жорстоко захопило плем'я Ґрімтотем — ненависний до чужих і підступний тауренський клан, що не визнає влади Кайрна Бладгуфа й нападає на чужинців, зокрема й на членів Орди.",al={"чому таурени нападають","хто керує табором апараже","чому табір апараже червоний"}},{q="Хто очолив напад на Табір Апараже?",a="Напад очолив Ґрундіґ Дарклауд — жорстокий вождь Ґрімтотемів, що діє із Застави Ґрімтотем і прагне поширити жорстоку владу свого племені на Гори Кам'яного Кігтя.",al={"хто напав на апараже","ґрундіґ дарклауд","хто тут ватажок"}},{q="Що сталося з уцілілими селянами?",a="Більшість мешканців загинула під час нападу. Кільком удалося втекти, а інших, як-от юну Каю Флетгуф, Ґрімтотеми захопили в полон і тримають на сусідній Заставі Ґрімтотем.",al={"кая флетгуф","де вціліли","чи є вцілілі"}}},fp="12,250,17.458.0,20.270.0,33.176.0,41.205.0,36.169.0,41.186.0"}
P.entries["subzone:camp-e-thok"] = {n="Табір Е'ток",s="Табір Е'ток — поселення кентаврів Ґалак на північному заході Тисячі Голок. Войовниче плем'я використовує цей табір у каньйоні як базу для засідок на каравани, що проходять руслом річки внизу.",h="Табір Е'ток — поселення кентаврів Ґалак на північному заході Тисячі Голок.",kw={"табір е'ток","кентаври ґалак","тисяча голок","засідки","каравани","візло берінґшайнер"},ang={["race:Tauren"]="Невпинна агресія кентаврів Ґалак із Табору Е'ток — постійне нагадування про давню війну тауренів і кентаврів на півдні Калімдору."},sec={{t="Твердиня Ґалаків",b="Табір Е'ток, захований у суворих північно-західних закутках Тисячі Голок, — важливе поселення ворожих кентаврів Ґалак. Як і їхні родичі по всьому Калімдору, Ґалаки — невгамовні хижаки, що полюють на кожного мандрівника, який забреде в тіні каньйону. Табір сумно відомий набігами на торгові каравани: саме звідси напали на гобліна Візло Берінґшайнера й захопили його товари — хоча його найцінніший пристрій вислизнув із їхніх рук, бо його стерегла люта пантера."}},faq={{q="Хто живе в Таборі Е'ток?",a="Табір займає клан кентаврів Ґалак — агресивне плем'я, що панує в частині північного заходу Тисячі Голок.",al={"хто в таборі е'ток","мешканці табору е'ток","хто керує табором е'ток"}},{q="Що тут сталося з Візло Берінґшайнером?",a="На купецький караван, у якому був гоблін Візло Берінґшайнер, напали кентаври Ґалак із Табору Е'ток. Вони пограбували караван, але не змогли забрати Візлову цінну штуковину, бо вона була закріплена на нашийнику його лютої пантери.",al={"набіг на візло берінґшайнера","напад на гоблінський караван","що кентаври вкрали у візло"}},{q="Де Табір Е'ток?",a="Табір Е'ток — на північному заході Тисячі Голок, біля підніжжя стін каньйону поблизу Висот Розщепленого Копита.",al={"місце табору е'ток","де табір е'ток","карта табору е'ток"}}},fp="11,231,18.508.0,25.127.0,42.256.0,29.124.0"}
P.entries["subzone:camp-kosh"] = {n="Табір Кош",s="Табір Кош — стійбище огрів на півночі Пустищ, де живуть агресивні огри Курного Виверга. Тутешні громили засідають біля важливих шляхів, нападають на каравани й підбирають усе спорядження, яке мандрівники лишають у суворій пустелі.",h="Табір Кош — стійбище огрів на півночі Пустищ, де живуть агресивні огри Курного Виверга.",kw={"табір кош","огри","курний виверг","пустища","каравани","ульдаман"},ang={["faction:Alliance"]="Розвідникам Альянсу, що йдуть північним перевалом до Палючої Ущелини, біля Табору Кош слід бути насторожі: тутешні громили охоче влаштовують засідки на обози.",["race:Dwarf"]="Огри-мародери з Табору Кош розграбували життєво важливі харчі й зброю, які лишила знесилена експедиція Сіґрун Айронг'ю до Ульдамана."},sec={{t="Лігво мародерів",b="Табір Кош, розташований у північних пустирях Пустищ, — найпівнічніше поселення огрів Курного Виверга, яким належать і сусідні табори Бофф, Каґґ і Вурґ. Огри звідси користуються близькістю доріг і грабують вразливі обози, що прямують до Карґата чи на захід, у Палючу Ущелину. Коли дворфські шукачі на чолі з Сіґрун Айронг'ю мусили втекти з розкопок в Ульдамані, громили з Табору Кош миттю пограбували їхні покинуті вози й потягли до свого курного стійбища цінні харчі та зброю."}},faq={{q="Хто живе в Таборі Кош?",a="У Таборі Кош живуть огри Пилоригачі — плем'я жорстоких огрів, що контролює кілька невеликих таборів по всіх посушливих Пустищах.",al={"мобі табору кош","хто в таборі кош","огри табору кош"}},{q="Чому Табір Кош розташований саме тут?",a="Північне розташування дає огрям Пилоригачам змогу влаштовувати засідки на каравани з припасами й необачних мандрівників між Палючою Ущелиною, Ульдаманом і заставою Орди Карґат.",al={"чому табір кош тут","місце табору кош"}},{q="Що огри вкрали в дворфів?",a="Коли дворфійська експедиція Сіґруна Айронг'ю відступила від небезпек Ульдамана, вона покинула в пустелі вози з припасами. Огри з Табору Кош обнишпорили уламки й поцупили ящики з харчами й партії зброї.",al={"припаси дворфів табір кош","припаси сіґрун айронх'ю","вози улдамана"}}},fp="9,250,19.583.0,23.138.0,30.177.0,42.227.0"}
P.entries["subzone:camp-mojache"] = {n="Табір Моджаче",s="Табір Моджаче — головна застава Орди у Фераласі: укріплене поселення тауренів на потоці, що живить Озеро Дикого Вітру. Тут мандрівники, які мають справу з дикими нетрями, лютим звіром і прадавніми руїнами глибокого лісу, знаходять прихисток, припаси та сполучення повітрям.",h="Табір Моджаче — головна застава Орди у Фераласі: укріплене поселення тауренів на потоці, що живить Озеро...",kw={"табір моджаче","фералас","орда","таурени","застава","озеро дикого вітру"},ang={["faction:Horde"]="Моджаче — єдиний укріплений опорний пункт Орди у Фераласі, тож лише тут ви можете перепочити, поповнити припаси й швидко перебратися через глибокий ліс.",["race:Tauren"]="Табір Моджаче — найпівденніший осередок давнього ремесла й поселень вашого народу в Калімдорі, місце, де таурени знайшли злагоду з глибоким тропічним лісом."},sec={{t="Оплот тауренів серед тропічного лісу",b="Табір Моджаче стоїть у східному Фераласі, на бистрому потоці, що впадає в Озеро Дикого Вітру. Це поселення тауренів, зведене, щоб закріпитися в дикому південному лісі. Хоч у густих джунглях чигає чимало небезпек — від лютих звірів до огрів Ґордунні й войовничих гнолів Лісолапів, — табір лишається острівцем безпеки. Тут є житло, торговці й сідало вітрокрилів, тож він став життєво важливим вузлом для героїв Орди, що діють у цьому краї."},{t="Прикордонна застава",b="Мисливці й воїни табору славляться відвагою та товстою шкурою: вони невсипно стережуться набігів із навколишніх нетрів. Для Орди втримати Моджаче — означає мати вплив на весь Фералас і стримувати як нічних ельфів з узбережжя, так і темні сили, що зачаїлися в Лютопащі."}},faq={{q="Що таке Табір Моджаче?",a="Табір Моджаче — головна база Орди у Фераласі. Збудований і утримуваний переважно тауренами, він стоїть обабіч струмка, що впадає в Озеро Дикого Вітру, і пропонує відпочинок, торгові припаси й повітряне сполучення.",al={"призначення табору моджаче","що це за табір","містечко тауренів ферелас"}},{q="Хто очолює чи боронить табір?",a="Поселення захищають бувалі тауренські звитяжці, що відбивають набіги місцевих звірячих зграй, огрів Ґордунні й агресивних гнолів Лісолапів, які никають лісами трохи на захід.",al={"стражі табору моджаче","хто захищає моджаче","хто керує табором моджаче"}},{q="Куди літає місцевий приборкувач летунів?",a="З вітрогоничного сідала табору мандрівники можуть дістатися великих осередків — Тандер Блафа, Перехрестя в Пустках, Села Тіньової Здобичі в Пустограї — і сусідніх застав, як-от Ґаджетзана в Танарісі.",al={"маршрути польотів моджаче","куди літати з моджаче"}},{q="Які головні загрози оточують Табір Моджаче?",a="У навколишніх лісах — клан гнолів Лісолапів на заході, огри Ґордунні, що стережуть свої землі на півночі й півдні, і сили Альянсу, що діють із далекого західного узбережжя — Твердині Перистого Місяця.",al={"небезпеки феласу моджаче","загрози біля табору моджаче","вороги біля моджаче"}}},fp="12,306,34.478.0,16.347.0,21.230.0,30.191.0,42.204.0,41.210.0"}
P.entries["subzone:camp-narache"] = {n="Табір Нарачі",s="Табір Нарачі — відлюдне селище на Плато Червоної Хмари в південному Малгорі. Це прабатьківська домівка племені Гоквінд і місце випробувань, де молоді таурени починають навчання. Високо над рівнинами табір береже давні традиції й невпинно стереже від зазіхань шипогривів і не зниклої загрози кентаврів.",h="Табір Нарачі — відлюдне селище на Плато Червоної Хмари в південному Малгорі.",kw={"табір нарачі","плато червоної хмари","малгор","таурени","гоквінд","стартова зона","шипогриви"},ang={["class:Shaman"]="Молоді шамани роблять тут найперші кроки духовним шляхом: проходять випробування, щоб здобути свій Тотем Землі й заговорити напряму зі стихіями плато.",["race:Tauren"]="Для тауренів Табір Нарачі — кінець дитинства: священна земля, де ви проходите перші обряди полювання й налаштовуєтеся на духів предків під пильним оком старійшин Гоквіндів."},sec={{t="Серце племені Гоквінд",b="Табір Нарачі, що лежить на північному краю піднесеного Плато Червоної Хмари, — головне поселення племені Гоквінд. Селище складається з кількох великих шкіряних осель і наметів: тут є спільний намет для поранених сміливців, зброярня, пекарський намет і духовний куточок для роздумів і спілкування з предками. У центрі табору колом стоять старійшини племені й наставники шляхів; тут досі дає поради поважна Прамати Гоквінд, скеровуючи щойно посвячену молодь, яка стає на шлях захисників Земної Матері."},{t="Місце випробувань під загрозою",b="Хоч табір природно укріплений стрімкими урвищами плато, спокою Табору Нарачі бракує. Шипогриви Щетиноспинних із Яру Тернистого Клинка невпинно зазіхають на землі Гоквіндів, а віддалік чатують розвідники кентаврів. Молоді мисливці, шамани, друїди й воїни гартуються тут, виполюючи агресивну місцеву живність, захищаючи криницю селища та відбиваючи наскоки шипогривів, перш ніж спуститися великим шляхом у ширші долини Малгору."}},faq={{q="Що таке Табір Нарачі?",a="Табір Нарачі — стартове селище молодих тауренів на вершині Плато Червоної Хмари в південному Малгорі. Це головне стійбище племені Гоквінд, прихисток, де мисливці, воїни, друїди й шамани-початківці опановують своє ремесло, перш ніж вирушити до Села Бладгуф і Тандер Блафа.",al={"що таке табір нарачі","лор нарачі","стартове місто тауренів"}},{q="Хто очолює селище?",a="Вождь Гоквінд веде сміливців племені й керує обороною плато разом із шанованою старійшиною племені, Праматір'ю Гоквінд. Наставники й старійшини племені збираються в центрі табору, щоб навчати молодих шукачів пригод.",al={"хто очолює табір нарачі","вождь табору нарачі","ватажок гоквінд"}},{q="Які загрози чигають на табір?",a="Стійбищу постійно дошкуляють шипогриви Щетиноспинних, що діють із Яру Тернистого Клинка на сході. Окрім здичавілих бойових вепрів і довгоступів, що блукають довколишніми кручами, не зникла небезпека хижих ватаг кентаврів, і це тримає сміливців Гоквіндів у постійній готовності.",al={"вороги табору нарачі","хто нападає на табір нарачі","загрози плато"}},{q="Чи легко мандрівникам залишити плато?",a="Плато Червоної Хмари з усіх боків оточене стрімкими урвищами. Єдиний спуск до великих рівнин Малгору — гірська стежка, що веде на північ під охороною сміливців Гоквіндів, які не дають ворожим звірам і шипогривам влаштовувати засідки на подорожніх.",al={"як залишити плато червоної хмари","вихід із табору нарачі","стежка з плато"}}},fp="12,358,27.590.0,29.487.0,21.318.0,22.237.0,32.285.0,36.250.0"}
P.entries["subzone:camp-taurajo"] = {n="Табір Тауражо",s="Табір Тауражо — тихе поселення тауренів на півдні Пусток, просто біля гірського перевалу, що веде на захід до Малгору. Це важливий прикордонний прихисток: утомлені мандрівники знайдуть тут корчму, припаси, наставників ремесел і вітрокрилів, що літають між рівнинами й центральним Калімдором.",h="Табір Тауражо — тихе поселення тауренів на півдні Пусток, просто біля гірського перевалу, що веде на захід до...",kw={"табір тауражо","таурени","малгор","вітрокрили","корчма","пустки"},ang={["faction:Horde"]="Табір Тауражо захищає важливе сухопутне перехрестя й повітряний шлях, міцно пов'язуючи Малгор з рештою підвладного Орді центрального Калімдору.",["race:Tauren"]="Для тауренів, що вперше вирушають із Малгору, Табір Тауражо — перший дружній прихисток на суворих рівнинах Пусток."},sec={{t="Прикордоння Червоних Скель",b="Табір Тауражо, що стоїть біля східного виходу з перевалу до Малгору, часто стає першим місцем, де молоді таурени, які вирушають із Села Бладгуф, бачать безкраї Пустки. Оточений сухими чагарниками й порізаними плато, табір водночас застава й торговий осередок. Тут знаходять прихисток мисливці, шкірники й польові травники, а вітрокрили сполучають його з Тандер Блафом, Перехрестям і Заставою Вільного Вітру далі на півдні."}},faq={{q="Що таке Табір Тауражо?",a="Табір Тауражо — тауренська застава й поселення на півдні Пусток, важливий перевалочний пункт між рідним Малгором і посушливими чагарниками Пусток.",al={"огляд табору тауражо","що таке тауражо","переказ про тауражо"}},{q="Куди веде дорога на захід?",a="Ґрунтова стежка на захід повз Табір Тауражо веде гірським перевалом у Малгор — просто до Села Бладгуф і Тандер Блафа.",al={"західний прохід тауражо","дорога на захід від тауражо","шлях до мулґору"}},{q="Куди літають вітрогони з Табору Тауражо?",a="Місцевий приборкувач летунів веде маршрути віверн, що сполучають табір із Перехрестям на півночі, Тандер Блафом на заході й Заставою Вільного Вітру в Тисячі Голок на півдні.",al={"майстер польотів тауражо","маршрути польотів тауражо","сполучення тауражо"}}},fp="12,303,25.441.0,21.173.0,30.146.0,47.189.0"}
P.entries["subzone:camp-wurg"] = {n="Табір Вурґ",s="Табір Вурґ — стійбище огрів у посушливих просторах Пустищ. Це одна з кількох застав, які захопили войовничі огри Курного Виверга, що панують у східних долинах.",h="Табір Вурґ — стійбище огрів у посушливих просторах Пустищ.",kw={"табір вурґ","огри","курний виверг","пустища","то'ґрун"},sec={{t="Твердиня Курного Виверга",b="Табір Вурґ, захований серед скель Пустищ, — один із чотирьох головних таборів огрів Курного Виверга поряд із Табором Каґґ, Табором Бофф і Табором Кош. Тутешні огри люто боронять свої суворі землі й видирають із немилосердної пустелі все, що можуть. Поки рядові громили й вибивайли живуть біля грубих багать і шкур Вурґа, їхній ватажок, Бос То'ґрун, не має тут постійного осідку: він блукає стежками Пустищ і пильнує всі свої табори."}},faq={{q="Хто живе в Таборі Вурґ?",a="Табір Вурґ населяють огри Пилоригачі — люте плем'я, що ревно стереже свої землі й заснувало поселення по всіх Пустищах.",al={"мобі табору вурґ","хто в таборі вурґ","хто тут живе"}},{q="Де ватажок табору?",a="Ватажок огрів Пилоригачів, Бос То'ґрун, не сидить у Таборі Вурґ. Натомість він обходить відкриті стежки Пустищ між Вурґом, Каґґом, Боффом і Кошем.",al={"бос табору вурґ","місце босса тоґруна","хто керує табором вурґ"}},{q="Які ще табори належать цьому племені?",a="Пилоригачі контролюють чотири головні твердині на Пустищах: Табір Вурґ, Табір Каґґ, Табір Бофф і Табір Кош.",al={"табори пилового шлунка","інші огрські табори пустищ","огрські поселення пустищ"}}},fp="9,193,24.521.0,23.132.0,32.175.0,38.119.0"}
P.entries["subzone:canals-stormwind-city"] = {n="Канали (Стормвінд)",s="Канали — мережа облицьованих каменем водних шляхів, що в'ються Стормвіндом і розділяють його квартали. Це тихі шляхи для перехожих і рибалок, але вони ховають приховані небезпеки й вхід до міської в'язниці.",h="Канали — мережа облицьованих каменем водних шляхів, що в'ються Стормвіндом і розділяють його квартали.",kw={"канали","стормвінд","риболовля","в'язниця","кроколіск-альбінос"},ang={["faction:Alliance"]="Канали — свідчення відбудови столиці Альянсом Лордерону, що перетворив завалені трупами руїни Першої війни знову на справне, мальовниче місто.",["profession:Cooking"]="Тихі береги каналів — зручне місце, де кухарі-початківці можуть навчитися ловити свіжу рибу, не виходячи за безпечні мури столиці."},sec={{t="Артерії столиці",b="Канали з'єднують і окреслюють квартали Стормвінда, відділяючи гомінкі ринки Торгового Кварталу від старих провулків Старого Міста, соборних садів і Дворфійського Кварталу. Кам'яні мости, арки й набережні обрамлюють тихі заклади на кшталт Виноробні Ґалліни, кравецьких крамниць і спокійних житлових будинків. Водні шляхи не лише служать місцевим купцям і рибалкам-аматорам — вони ще й ховають укріплений вхід до В'язниці, де під рівнем вулиць тримають найнебезпечніших злочинців і бунтарів Стормвінда."},{t="Моторошне минуле й тіні в глибині",b="Спокійна гладінь каналів приховує жорстоке минуле. Після розграбування Стормвінда в Першу війну канали виявилися завалені уламками, колодами й тілами вбитих захисників. Коли Альянс Лордерону звільнив руїни, солдати взялися за похмуру роботу: розчищали канали й ховали мертвих, перш ніж почалася відбудова. Нині, хоч канали очищено й відновлено, їхні глибини досі оповиті таємницею — у місті ходять чутки про величезного кроколіска-альбіноса, що никає під пристанями."}},faq={{q="Що сталося з каналами під час Першої війни?",a="Коли Орда орків захопила й сплюндрувала Стормвінд у Першій війні, водні шляхи лишилися завалені битим камінням, деревом і гниючими тілами. Війська Альянсу Лордерона, що відвоювали місто, мусили ретельно розчистити канали й гідно поховати полеглих, перш ніж місто можна було відбудовувати.",al={"історія каналів","канали першої війни","розграбування каналів стормвінда"}},{q="Чи справді в каналах Стормвінда живе чудовисько?",a="Напевно ніхто не скаже. Живучі міські легенди розповідають про величезного білого кроколіска, що чаїться у водах. Міські вартові й мешканці часто відмахуються від цього як від корчемних пліток, але свідчення не вщухають, і шукачів пригод застерігають не падати у воду.",al={"крокодил стормвінда","алігатор каналів","чудовисько каналізації","білий кроколіск"}},{q="Де вхід до В'язниці?",a="Вхід до В'язниці — на найпівнічнішій ділянці каналу довкола Кварталу магів, і його пильно стереже Міська Варта Стормвінда.",al={"де вхід до в'язниці","вхід до в'язниці","як дістатися в'язниці"}},{q="Чи можуть гравці плавати каналами, щоб пересуватися Стормвіндом?",a="Плавати каналами цілком можна, але щоб вибратися назад на вулицю, доведеться шукати кам'яні сходи чи причали, розкидані вздовж набережних.",al={"плавання каналами","подорож водою стормвінд","водний маршрут стормвінда"}}},fp="23,257,23.546.0,38.519.0,49.299.0,50.245.0,46.151.0,63.154.0"}
P.entries["subzone:canals-undercity"] = {n="Канали (Андерсіті)",s="Канали — каламутний кільцевий рів, що в'ється між окремими кварталами Андерсіті. Замість прісної води їх заповнює неприродний, отруйний зелений слиз, тож вони водночас слугують каналізацією і похмурим символом підземної твердині Відступників.",h="Канали — каламутний кільцевий рів, що в'ється між окремими кварталами Андерсіті.",kw={"канали","андерсіті","відступники","слиз","рів","рибальство"},ang={["class:Shaman"]="Стихії майже не мають влади над забрудненою твані, що заповнює водні шляхи Андерсіті, тож звичні закляття на кшталт Ходіння по воді тут не діють зовсім.",["race:Undead"]="Неживим тілам Відступників смердючі канали анітрохи не шкодять, тож вони слугують і оборонним ровом, і стоком для хімікатів — саме те, що треба підземному королівству."},sec={{t="Отруйний рів",b="Канали, висічені в підземних глибинах під руїнами Лордерона, оточують серце Андерсіті й розділяють його квартали широкими руслами млявої зеленої твані. Міста живих пропускають вулицями річкову воду, щоб тримати їх у чистоті, а Відступники заповнили ці кам'яні жолоби промисловими покидьками, хімічними стоками й алхімічними відходами. Рідина ледь помітно, хворобливо світиться й випускає смердючі випари, тож перейти її звичними чарами на кшталт ходіння по воді неможливо. Попри смертоносність цієї бурди, відчайдушні рибалки часом витягають із багна дивні, зіпсовані дивовижі."}},faq={{q="Що за зелена рідина в каналах?",a="Це алхімічний мул з отруйних стоків, побічних продуктів чуми й промислових відходів, що збирається в стічній системі Андерсіті. На відміну від чистої води, він явно отруєний і шкідливий.",al={"зелена вода андерсіті","що за слиз в андерсіті","зелена річка слизу"}},{q="Чи можна рибалити в каналах Андерсіті?",a="Так, терплячі рибалки можуть закинути вудку в цю жижу. Окрім хворобливої, отруєної риби, часом витягують і непотріб, зокрема старі людські черепи з полеглого минулого Лордерона.",al={"рибалка в андерсіті","чи можна рибалити тут","рибалка у зеленому слизу"}},{q="Чому «Ходіння по воді» не діє на каналах?",a="Густа хімічна жижа поводиться не так, як природна вода. Її мерзенна в'язкість і неприродний склад не дають шаманам та іншим заклиначам утриматися на поверхні за допомогою звичайної магії ходіння по воді.",al={"ходіння по воді андерсіті","шаман ходіння по воді помилка","чому не можу ходити по воді в андерсіті"}}},fp="18,261,12.614.0,39.201.0,37.192.0,45.217.0"}
P.entries["subzone:cape-of-stranglethorn"] = {n="Мис Стренглторну",s="Мис Стренглторну — випалений сонцем південний край Долини Стренглторну, що простягається від Арени Ґурубаші на південь аж до морських урвищ. Опорою краю є розлогий піратський порт Буті Бей, а сам мис — поле битви, за яке змагаються гобліни, Буканіри Кривавого Вітрила, прадавні тролі джунглів і дика природа, що наступає звідусіль.",h="Мис Стренглторну — випалений сонцем південний край Долини Стренглторну, що простягається від Арени Ґурубаші...",kw={"мис стренглторну","буті бей","буканіри кривавого вітрила","пірати","південні моря","долина стренглторну"},ang={["class:Rogue"]="Мис — притулок для каперів, пройдисвітів і головорізів: тут безліч нагод поцупити гаманець, провезти узбережжям контрабанду чи нацькувати Нападників Чорної Води на Буканірів Кривавого Вітрила.",["profession:Cooking"]="Довколишні Південні Моря й прибережні води — цінні рибальські угіддя, а рідкісні рецепти продають лише торговці рибою й портові кухарі Буті Бею."},sec={{t="Край континенту",b="На південь від прадавнього колізею Арени Ґурубаші густі джунглі поступаються узбережжю, відомому як Мис Стренглторну. Мис, усіяний поселеннями тролів, що розсипаються, — як-от Руїни Джубувалу й Руїни Абораза, — давно вийшов з-під влади Імперії Ґурубаші. Нині на його пляжах, у бухтах і на лісових галявинах у хаосі співіснують небезпечні хижаки, табори мурлоків і ворогуючі піратські команди, що б'ються за торгові шляхи й закопану здобич."},{t="Буті Бей і війна з буканірами",b="Головна сила на мисі — Нападники Чорної Води на чолі з Бароном Ревілґазом і Флотоводцем Сігорном, що правлять із піратського міста Буті Бей. Цю нейтральну гавань, вирубану просто в скелях південної бухти, пароплави сполучають із Раджетом, а отже, Східні Королівства — з Калімдором. Проте влада гоблінів досі хитка. Буканіри Кривавого Вітрила хазяйнують на південних мілинах і зовнішніх островах, грабують шляхи постачання й відкрито замишляють повалити Буті Бей і захопити повну владу над Південними Морями."}},faq={{q="Чим відрізняються Долина Стренглторну й Мис Стренглторну?",a="Мис Стренглторну — це саме південна частина більшої Долини Стренглторну: землі й узбережжя на південь від Арени Ґурубаші аж до Буті Бей.",al={"мис проти долини","географія стренглторну","де мис"}},{q="Хто править Мисом Стренглторну?",a="Жодна влада не контролює весь мис. Буті Бей і води довкола підпорядковані Баронові Ревілґазу й Нападникам Чорної Води, за якими стоять гобліни, а Буканіри Кривавого Вітрила, наги й рештки тролів тримають різні пляжі й руїни в глибині суходолу.",al={"хто править буті беєм","правитель мису","хто контролює мис"}},{q="Чи можуть і Орда, і Альянс користуватися Буті Бей?",a="Так. Буті Бей — відкритий нейтральний порт, який утримує картель Стімвідл. Доки мандрівники тримають зброю в піхвах і зберігають мир у межах міста, шукачі пригод і з Альянсу, і з Орди можуть користуватися його доками, крамарями, приборкувачем летунів і аукціоном.",al={"чи буті бей нейтральний","альянс і орда буті бей","чи орда може увійти в буті бей"}},{q="Що таке Арена Ґурубаші?",a="Арена Ґурубаші — давня троляча бійцівська яма біля північного краю мису, де збираються бійці, щоб випробувати себе.",al={"скриня ґурубаші","правила арени","арена стренглторну"}},{q="Як мандрівники дістаються між Мисом і Калімдором?",a="Пароплав, яким керують гобліни, регулярно ходить між доками Буті Бей і портовим містечком Раджет у Пустках — це один із небагатьох пасажирських шляхів між континентами через Південні Моря.",al={"корабель до раджета","транспорт до калімдора","корабель буті бею"}}},fp="21,323,21.466.0,31.516.0,80.184.0,36.256.0,42.271.0,28.132.0,51.196.0"}
